// Flips square (c, r), the board wrapping around its edges.
fn flip(c: int, r: int) {
  let i = ((r + 4) % 4) * 4 + (c + 4) % 4;
  lit[i] = !lit[i];
}

fn press(i: int) {
  let c = i % 4;
  let r = i / 4;
  flip(c, r);
  flip(c - 1, r);
  flip(c + 1, r);
  flip(c, r - 1);
  flip(c, r + 1);
}

