}

// Dungeon: the arrows (or a tap beside you) move you or hit a monster in the way; space waits.
// You see 2 squares around you; the potion heals 3; the stairs lead down to tougher monsters.
// icon: loop 4 4 20 4 20 20 4 20 dot 9 9 3 line 13 16 19 16 19 10
state seen = [false; 100];  // 10 x 10 squares, row by row: seen before
state mx = [3, 7];          // the monsters: where, and their HP (0: gone)
state my = [4, 2];
state mhp = [2, 3];
state px = 1;
state py = 1;
state hp = 10;
state floor = 1;
state potion = true;

fn wall(c: int, r: int) -> bool {
  return c == 0 || c == 9 || r == 0 || r == 9 || (c == 5 && r <= 7);
}

fn sgn(n: int) -> int {
  if n > 0 { return 1; }
  if n < 0 { return -1; }
  return 0;
}

// The monster on (c, r), or -1.
fn monster(c: int, r: int) -> int {
  for k in 0..2 {
    if mhp[k] > 0 && mx[k] == c && my[k] == r { return k; }
  }
  return -1;
}

fn free(c: int, r: int) -> bool {
  return !wall(c, r) && monster(c, r) < 0 && (c != px || r != py);
}

fn near(c: int, r: int) -> bool { return abs(c - px) <= 2 && abs(r - py) <= 2; }

// What you see now stays seen.
fn look() {
  for i in 0..100 {
    if near(i % 10, i / 10) { seen[i] = true; }
  }
}

// Each monster within 3 squares hits you if it is beside you, else steps toward you.
fn monsters() {
  for k in 0..2 {
    if mhp[k] > 0 && hp > 0 && max(abs(mx[k] - px), abs(my[k] - py)) <= 3 {
      let ax = sgn(px - mx[k]);
      let ay = sgn(py - my[k]);
      if abs(mx[k] - px) + abs(my[k] - py) == 1 {
        hp -= 1;
      } else if ax != 0 && free(mx[k] + ax, my[k]) {
        mx[k] += ax;
      } else if ay != 0 && free(mx[k], my[k] + ay) {
        my[k] += ay;
      }
    }
  }
}

// A floor begins: the same map, nothing seen, the monsters tougher the deeper.
fn begin() {
  for i in 0..100 { seen[i] = false; }
  px = 1;
  py = 1;
  mx[0] = 3;
  my[0] = 4;
  mhp[0] = 1 + floor;
  mx[1] = 7;
  my[1] = 2;
  mhp[1] = 2 + floor;
  potion = true;
}

// A turn: a step, a hit or (0, 0) a wait; then the monsters.
fn act(dx: int, dy: int) {
  let c = px + dx;
  let r = py + dy;
  if hp == 0 || wall(c, r) { return; }
  look();
  let k = monster(c, r);
  if k >= 0 {
    mhp[k] -= 1;
  } else {
    px = c;
    py = r;
    if potion && c == 8 && r == 4 {
      potion = false;
      hp = min(10, hp + 3);
    }
    if c == 8 && r == 1 {
      floor += 1;
      begin();
      return;
    }
  }
  monsters();
}

// The board, 10 x 10 squares of 12 units; what was never seen is blank.
fn scene() {
  let cells = [0; 100];
  for i in 0..100 {
    let c = i % 10;
    let r = i / 10;
    if seen[i] || near(c, r) {
      cells[i] = 2;
      if wall(c, r) { cells[i] = 8; }
      if c == 8 && r == 1 { cells[i] = 3; }
      if potion && c == 8 && r == 4 { cells[i] = 5; }
      if monster(c, r) >= 0 { cells[i] = 1; }
      if c == px && r == py { cells[i] = 4; }
    }
  }
  pixels(cells, 0, 0, 10, 12);
  if hp == 0 { text("Game over", 60, 60, 16, 11); }
}

on key "left" { act(-1, 0); }
on key "right" { act(1, 0); }
on key "up" { act(0, -1); }
on key "down" { act(0, 1); }
on key "space" { act(0, 0); }

label "Dungeon";
label "HP " + hp + "   Floor " + floor;
canvas 120, 120, scene() {
  if abs(x / 12 - px) + abs(y / 12 - py) == 1 { act(x / 12 - px, y / 12 - py); }
}
button "New game" {
  hp = 10;
  floor = 1;
  begin();
}

// Torch escape: the arrows (or a tap beside you) walk, 1 oil a step; take the key, open the red
// door, reach the exit. Your torch lights 2 squares around you, 1 when low; at 0 oil it goes out.
// icon: fill 10 12 14 12 13 21 11 21 fill 12 3 16 8 12 11 8 8
state px = 1;               // you, on a 9 x 9 board
state py = 1;
state oil = 24;
state gold = 0;
state key = 0;              // 0 lying on its square, 1 carried, 2 used on the door
state coins = [true, true]; // the gold on 4,1 and on 3,7, not yet taken
state flask = true;
state end = "";             // You escaped, or Game over

fn wall(c: int, r: int) -> bool {
  return c == 0 || c == 8 || r == 0 || r == 8 || (r == 4 && c != 2) || (c == 5 && (r == 5 || r == 6));
}

// The color of what is on (c, r), you aside.
fn what(c: int, r: int) -> int {
  if wall(c, r) { return 8; }
  if c == 2 && r == 4 && key < 2 { return 1; }
  if c == 7 && r == 2 && key == 0 { return 6; }
  if (c == 4 && r == 1 && coins[0]) || (c == 3 && r == 7 && coins[1]) { return 3; }
  if c == 2 && r == 6 && flask { return 5; }
  if c == 7 && r == 5 { return 7; }
  return 2;
}

// A step: walls stop you, and the door unless you carry the key; then you take what is there.
fn step(dx: int, dy: int) {
  let c = px + dx;
  let r = py + dy;
  if end != "" || wall(c, r) { return; }
  if c == 2 && r == 4 && key < 2 {
    if key == 0 { return; }
    key = 2;
  }
  px = c;
  py = r;
  oil -= 1;
  if key == 0 && c == 7 && r == 2 { key = 1; }
  if coins[0] && c == 4 && r == 1 {
    coins[0] = false;
    gold += 1;
  }
  if coins[1] && c == 3 && r == 7 {
    coins[1] = false;
    gold += 1;
  }
  if flask && c == 2 && r == 6 {
    flask = false;
    oil = min(24, oil + 10);
  }
  if c == 7 && r == 5 {
    end = "You escaped";
  } else if oil <= 0 {
    end = "Game over";
  }
}

// How far the torch lights.
fn light() -> int {
  if oil > 10 { return 2; }
  if oil > 0 { return 1; }
  return 0;
}

fn carry() -> string {
  if key == 1 { return "   Key"; }
  return "";
}

// The board, 9 x 9 squares of 12 units: only what the torch lights shows.
fn scene() {
  let cells = [0; 81];
  let d = light();
  for i in 0..81 {
    if abs(i % 9 - px) <= d && abs(i / 9 - py) <= d { cells[i] = what(i % 9, i / 9); }
  }
  cells[py * 9 + px] = 4;
  pixels(cells, 0, 0, 9, 12);
  if end != "" { text(end, 54, 54, 12, 11); }
}

on key "left" { step(-1, 0); }
on key "right" { step(1, 0); }
on key "up" { step(0, -1); }
on key "down" { step(0, 1); }

label "Torch escape";
label "Oil " + oil + "   Gold " + gold + carry();
canvas 108, 108, scene() {
  if abs(x / 12 - px) + abs(y / 12 - py) == 1 { step(x / 12 - px, y / 12 - py); }
}
button "New game" {
  px = 1;
  py = 1;
  oil = 24;
  gold = 0;
  key = 0;
  coins[0] = true;
  coins[1] = true;
  flask = true;
  end = "";
}

// Rock paper scissors: pick your throw; the computer plays Rock, Paper, Scissors in turn.
// icon: dot 7 16 4 loop 13 12 21 12 21 20 13 20 line 8 3 16 10 line 8 10 16 3
state names = ["Rock", "Paper", "Scissors"];
state rounds = 0;       // rounds played: the computer's next throw is rounds % 3
state computer = -1;    // its last throw: 0 rock, 1 paper, 2 scissors; -1 before the first
state result = "";
state wins = 0;
state losses = 0;
state ties = 0;

// Each throw beats the one before it, round the circle: paper rock, scissors paper, rock scissors.
fn play(me: int) {
  computer = rounds % 3;
  rounds += 1;
  if me == computer {
    result = "Draw";
    ties += 1;
  } else if me == (computer + 1) % 3 {
    result = "You win";
    wins += 1;
  } else {
    result = "You lose";
    losses += 1;
  }
}

fn thrown() -> string {
  if computer < 0 { return "-"; }
  return names[computer];
}

label "Rock paper scissors";
row {
  button "Rock" { play(0); }
  button "Paper" { play(1); }
  button "Scissors" { play(2); }
}
label "Computer: " + thrown();
label result;
label "Wins: " + wins + "   Losses: " + losses + "   Ties: " + ties;

// Rock paper scissors for two: left picks with a s d, right with j k l; when both have, the round is played.
// icon: dot 6 12 4 line 12 4 12 20 loop 15 8 21 8 21 16 15 16
state lpick = -1;       // each player's pick this round: -1 none yet, 0 rock, 1 paper, 2 scissors
state rpick = -1;
state result = "";
state lscore = 0;
state rscore = 0;

// The round, once both have picked: each throw beats the one before it, round the circle.
fn play() {
  if lpick < 0 || rpick < 0 { return; }
  if lpick == rpick {
    result = "Draw";
  } else if lpick == (rpick + 1) % 3 {
    result = "Left wins";
    lscore += 1;
  } else {
    result = "Right wins";
    rscore += 1;
  }
  lpick = -1;
  rpick = -1;
}

fn pickl(k: int) { lpick = k; play(); }
fn pickr(k: int) { rpick = k; play(); }

fn ready(k: int) -> string {
  if k < 0 { return "picking"; }
  return "ready";
}

on key "a" { pickl(0); }
on key "s" { pickl(1); }
on key "d" { pickl(2); }
on key "j" { pickr(0); }
on key "k" { pickr(1); }
on key "l" { pickr(2); }

