// Crossing: green until you press Cross; then yellow for 2 seconds, red for 5 (Walk), and green again.
// icon: dot 12 4 2 line 12 7 12 14 line 12 14 8 21 line 12 14 16 21 line 7 10 17 10
state lit = 2;          // the lamp lit, top to bottom: 0 red, 1 yellow, 2 green
state speed = 0;        // ms until the light changes; 0 while it rests on green

// Lamp k, from the top, in its color when lit, else dark gray.
fn lamp(k: int, color: int) {
  let c = 8;
  if lit == k { c = color; }
  circle(20, 20 + k * 40, 16, c);
}

fn scene() {
  lamp(0, 1);
  lamp(1, 3);
  lamp(2, 2);
}

fn sign() -> string {
  if lit == 0 { return "Walk"; }
  return "Wait";
}

// Yellow gives way to red for 5 seconds, red to green, which waits for Cross.
every speed {
  if lit == 1 {
