// icon: line 4 8 7 5 7 19 loop 12 5 19 5 19 19 12 19
state bits = "";

// The value of the digits of n read as binary; -1 if one is not 0 or 1.
fn value(n: int) -> int {
  let v = 0;
  let p = 1;
  let m = n;
  for i in 0..19 {
    let d = m % 10;
    if d > 1 { return -1; }
    v += d * p;
    p = p * 2;
    m = m / 10;
  }
  return v;
}

fn shown() -> string {
  if bits == "" { return "Decimal: 0"; }
  let n = parse(bits, -1);
  if n < 0 || value(n) < 0 { return "Not binary"; }
  return "Decimal: " + value(n);
}

