// Mastermind: build a guess of 4 colored pegs and score it; Exact is the right color in the
// right place, Close a right color in the wrong place. Find the code in 10 guesses.
// icon: dot 5 8 3 dot 12 8 3 dot 19 8 3 dot 5 17 2 dot 12 17 2 dot 19 17 2
state code = [1, 2, 4, 3];    // the hidden code's colors: 1 red 2 green 3 yellow 4 blue 5 purple 6 cyan
state games = 0;              // games begun after the first
state rows = [0; 0];          // the guesses made, 4 colors each
state guess = [0; 0];         // the guess being made
state hits = 0;               // the latest score: Exact
state near = 0;               // and Close
state over = 0;               // 0 playing, 1 won, 2 lost
state names = ["", "Red", "Green", "Yellow", "Blue", "Purple", "Cyan"];

// Exact for the guess at rows[at] to rows[at + 3].
fn exact(at: int) -> int {
  let n = 0;
  for i in 0..4 {
    if rows[at + i] == code[i] { n += 1; }
  }
  return n;
}

// For each color, the fewer of its pegs in the guess and in the code, added up.
fn alike(at: int) -> int {
  let n = 0;
  for c in 1..7 {
    let g = 0;
    let k = 0;
    for i in 0..4 {
      if rows[at + i] == c { g += 1; }
      if code[i] == c { k += 1; }
    }
    n += min(g, k);
  }
  return n;
}

fn named() -> string {
  return names[code[0]] + " " + names[code[1]] + " " + names[code[2]] + " " + names[code[3]];
}

fn add(c: int) {
  if over == 0 && len(guess) < 4 { push(guess, c); }
}

fn score() {
  if over > 0 || len(guess) < 4 { return; }
  for i in 0..4 { push(rows, guess[i]); }
  clear(guess);
  let at = len(rows) - 4;
  hits = exact(at);
  near = alike(at) - hits;
  if hits == 4 { over = 1; } else if len(rows) == 40 { over = 2; }
}

fn fresh() {
  games += 1;
  if games == 1 {
    code = [6, 6, 5, 1];
  } else {
    for i in 0..4 { code[i] = 1 + random(6); }
  }
  clear(rows);
  clear(guess);
  hits = 0;
  near = 0;
  over = 0;
}

// Ten rows of pegs, the guess being made in the next; beside each guess its score, ink pegs for
// Exact and dim ones for Close.
fn scene() {
  for r in 0..10 {
    for i in 0..4 {
      let k = r * 4 + i;
      if k < len(rows) {
        circle(10 + i * 12, 7 + r * 12, 4, rows[k]);
      } else if r * 4 == len(rows) && i < len(guess) {
        circle(10 + i * 12, 7 + r * 12, 4, guess[i]);
      } else {
        circle(10 + i * 12, 7 + r * 12, 1, 10);
      }
    }
    if r * 4 < len(rows) {
      let e = exact(r * 4);
      let a = alike(r * 4);
      for i in 0..a {
        let s = 10;
        if i < e { s = 9; }
        circle(62 + i * 6, 7 + r * 12, 2, s);
      }
    }
  }
}

