// Bulls and Cows: guess the 4-digit number, its digits all different, in 8 tries. Bulls are
// digits in the right place, Cows digits in the number but elsewhere.
// icon: loop 3 6 21 6 21 18 3 18 line 7 10 7 14 line 11 10 11 14 line 15 10 15 14 dot 19 12 2
state secret = 4271;
state games = 0;              // games begun after the first
state entry = "";
state said = [""; 0];         // the guesses, oldest first, and their scores
state bulls = [0; 0];
state cows = [0; 0];
state bad = false;            // the last try was not 4 different digits
state over = 0;               // 0 playing, 1 won, 2 lost

fn place(i: int) -> int {
  if i == 0 { return 1000; }
  if i == 1 { return 100; }
  if i == 2 { return 10; }
  return 1;
}

// Digit i, from the left, of a number of 4 digits (a 0 in front counted).
fn digit(n: int, i: int) -> int { return n / place(i) % 10; }

fn valid(s: string) -> bool {
  let n = parse(s, -1);
  if len(s) != 4 || n < 0 { return false; }
  for i in 0..4 {
    for j in 0..4 {
      if i < j && digit(n, i) == digit(n, j) { return false; }
    }
  }
  return true;
}

fn spelled(n: int) -> string { return "" + digit(n, 0) + digit(n, 1) + digit(n, 2) + digit(n, 3); }

fn guess() {
  if over > 0 { return; }
  if !valid(entry) {
    bad = true;
    return;
  }
  bad = false;
  let n = parse(entry, 0);
  let b = 0;
  let c = 0;
  for i in 0..4 {
    for j in 0..4 {
      if digit(n, i) == digit(secret, j) {
        if i == j { b += 1; } else { c += 1; }
      }
    }
  }
  push(said, spelled(n));
  push(bulls, b);
  push(cows, c);
  if b == 4 { over = 1; } else if len(said) == 8 { over = 2; }
}

// A secret of 4 different digits: the first 4 of the digits shuffled.
