state over = 0;           // 0 playing, 1 I won, 2 I lost

// The computer leaves one more than a multiple of 4 when it can, else takes 1.
fn computer() {
  let k = (left - 1) % 4;
  if k == 0 { k = 1; }
  left -= k;
  took = k;
  if left == 0 { over = 1; }
}

fn take(n: int) {
  if over > 0 || n > left { return; }
  left -= n;
  if left == 0 { over = 2; } else { computer(); }
}

// The matches, two rows of ten: a yellow stick with a red head.
