// Pixel editor: pick a color and a tool; the Pen paints where you tap or drag, Fill floods the
// area of one color you tap. Clear empties the board.
// icon: fill 5 3 13 11 9 15 1 7 line 13 11 19 15 19 20 dot 19 20 2
state art = [-1; 256];      // 16 x 16 squares, row by row: -1 blank, else a color
