// Life: tap squares to bring them to life or kill them; Step moves one generation, Play runs
// them until Pause. The edges are dead.
// icon: fill 9 3 15 3 15 9 9 9 fill 15 9 21 9 21 15 15 15 fill 3 15 9 15 9 21 3 21 fill 9 15 15 15 15 21 9 21 fill 15 15 21 15 21 21 15 21
state live = [false; 400];    // 20 x 20 squares, row by row
state generation = 0;
state speed = 0;              // ms a generation while it plays, else 0

fn alive() -> int {
  let n = 0;
  for i in 0..400 {
    if live[i] { n += 1; }
  }
  return n;
}

// Each live square adds one to each of its neighbours on the board; then the rules.
fn step() {
  let near = [0; 400];
  for i in 0..400 {
    if live[i] {
      let c = i % 20;
      let r = i / 20;
      for dr in -1..2 {
        for dc in -1..2 {
          let on = c + dc >= 0 && c + dc < 20 && r + dr >= 0 && r + dr < 20;
          if on && (dc != 0 || dr != 0) { near[i + dr * 20 + dc] += 1; }
        }
      }
    }
  }
  for i in 0..400 { live[i] = near[i] == 3 || (live[i] && near[i] == 2); }
  generation += 1;
}

fn flip(i: int) { live[i] = !live[i]; }

