// icon: loop 3 3 21 3 21 21 3 21 line 9 3 9 21 line 15 3 15 21 line 3 9 21 9 line 3 15 21 15
state given = [
  1, 6, 0, 7, 9, 0, 5, 0, 2,
  0, 2, 0, 0, 3, 0, 0, 0, 0,
  7, 0, 0, 0, 0, 0, 1, 3, 6,
