  if over() { return; }
  sel = -1;
  if given[i] == 0 { sel = i; }
}

// d written in the selected square (0 clears it), unless it clashes: then a mistake.
fn write(d: int) {
  if sel < 0 || over() { return; }
  if d > 0 && clash(sel, d) {
