// Match three: tap a gem, then one next to it, to swap them when that makes a line of three or
// more; lines clear for 10 points a gem and new gems fall in. Ten moves.
// icon: loop 12 3 20 10 12 21 4 10 line 4 10 20 10 line 9 10 12 21 line 15 10 12 21
state first = [
  1, 3, 4, 1, 3, 5, 5, 1,
  1, 3, 2, 4, 1, 5, 5, 2,
  4, 4, 5, 1, 2, 2, 1, 4,
  4, 3, 3, 4, 4, 1, 4, 5,
  2, 1, 5, 3, 5, 5, 3, 2,
  4, 2, 3, 3, 5, 5, 4, 4,
  4, 3, 5, 1, 2, 1, 2, 1,
  3, 1, 1, 4, 1, 4, 3, 1
];                        // the starting board, row by row from the top: colors 1 to 5
state gems = [
  1, 3, 4, 1, 3, 5, 5, 1,
  1, 3, 2, 4, 1, 5, 5, 2,
  4, 4, 5, 1, 2, 2, 1, 4,
  4, 3, 3, 4, 4, 1, 4, 5,
  2, 1, 5, 3, 5, 5, 3, 2,
  4, 2, 3, 3, 5, 5, 4, 4,
  4, 3, 5, 1, 2, 1, 2, 1,
  3, 1, 1, 4, 1, 4, 3, 1
];
state sel = -1;           // the selected gem; -1 none
state score = 0;
state moves = 10;
state made = 0;           // new gems so far: the next one's color is made % 5 + 1

fn at(c: int, r: int) -> int {
  if c < 0 || c >= 8 || r < 0 || r >= 8 { return 0; }
  return gems[r * 8 + c];
}

// How many gems of color v follow (c, r), a step (dc, dr) at a time, up to 2.
fn run(c: int, r: int, dc: int, dr: int, v: int) -> int {
  let n = 0;
  for k in 1..3 {
    if n == k - 1 && at(c + dc * k, r + dr * k) == v { n = k; }
  }
  return n;
}

// Whether gem i is in a line of three or more of its color, across or down.
fn lined(i: int) -> bool {
  let v = gems[i];
  if v == 0 { return false; }
  let c = i % 8;
  let r = i / 8;
  if run(c, r, 1, 0, v) + run(c, r, -1, 0, v) >= 2 { return true; }
  return run(c, r, 0, 1, v) + run(c, r, 0, -1, v) >= 2;
}

fn any() -> bool {
  for i in 0..64 {
    if lined(i) { return true; }
  }
  return false;
}

// Every gem in a line clears, 10 points each; in each column, from the left, what is left falls
// and new gems fill it from the lowest empty square up.
fn crush() {
  let gone = [false; 64];
  for i in 0..64 { gone[i] = lined(i); }
  for i in 0..64 {
    if gone[i] {
      gems[i] = 0;
      score += 10;
    }
  }
  for c in 0..8 {
    let low = 7;
    for k in 0..8 {
      let v = gems[(7 - k) * 8 + c];
      if v != 0 {
        gems[(7 - k) * 8 + c] = 0;
        gems[low * 8 + c] = v;
        low -= 1;
      }
    }
    for k in 0..low + 1 {
      gems[(low - k) * 8 + c] = made % 5 + 1;
      made += 1;
    }
  }
}

fn beside(i: int, j: int) -> bool {
  return (abs(i - j) == 1 && i / 8 == j / 8) || abs(i - j) == 8;
}

// A tap selects a gem; a gem next to the selected one swaps with it if that makes a line.
fn tap(i: int) {
  if moves == 0 { return; }
  if sel < 0 || (sel != i && !beside(sel, i)) {
    sel = i;
    return;
  }
  let j = sel;
  sel = -1;
  if j == i { return; }
  let a = gems[j];
  gems[j] = gems[i];
  gems[i] = a;
  if !any() {
    gems[i] = gems[j];
    gems[j] = a;
    return;
  }
  moves -= 1;
  repeat 30 {
    if any() { crush(); }
  }
}

fn fresh() {
  for i in 0..64 { gems[i] = first[i]; }
  sel = -1;
  score = 0;
  moves = 10;
  made = 0;
}

// Gems on squares 15 units wide; the selected one ringed in ink.
fn scene() {
  for i in 0..64 {
    let px = (i % 8) * 15;
    let py = (i / 8) * 15;
    rect(px + 1, py + 1, 13, 13, gems[i]);
    if i == sel { ring(px + 7, py + 7, 7, 1, 9); }
  }
}

fn status() -> string {
  if moves == 0 { return "Game over"; }
  return "Swap two gems side by side";
}

