    rect(px + 1, py + 1, 13, 13, gems[i]);
    if i == sel { ring(px + 7, py + 7, 7, 1, 9); }
  }
}

fn status() -> string {
  if left() == 0 { return "You win"; }
  if stuck() { return "Game over"; }
  return "Clear every gem";
}

