  let met = px == gx && py == gy;
  meet();
  if !met && dots[py * 7 + px] {
    dots[py * 7 + px] = false;
    score += 10;
    if left() == 0 {
      won = true;
      speed = 0;
    }
  }
  if !met && speed > 0 && steps % 2 == 0 { chase(); }
}

