state dx = 0;
state dy = 0;
state left = 0;
state power = 5;
state strokes = 0;
state total = 0;
state speed = 0;                // 100 while a game runs, else 0
state done = false;
state tees = [2, 4, 2, 2, 2, 6];   // each hole's tee and cup: column, row
state cups = [9, 4, 9, 2, 9, 6];

fn wall(c: int, r: int) -> bool {
  if c <= 0 || c >= 11 || r <= 0 || r >= 7 { return true; }
  if hole == 2 { return c == 6 && r <= 5; }
  if hole == 3 { return (c == 5 || c == 8) && r >= 2; }
  return false;
}

fn tee(h: int) {
  hole = h;
  strokes = 0;
  left = 0;
  bx = tees[h * 2 - 2];
  by = tees[h * 2 - 1];
}

fn start() {
  total = 0;
  power = 5;
  done = false;
  tee(1);
  speed = 100;
}

fn hit(x: int, y: int) {
  if speed > 0 && left == 0 {
    dx = x;
    dy = y;
    left = power;
    strokes += 1;
  }
}

fn holed() {
  total += strokes;
  if hole == 3 {
    done = true;
    left = 0;
    speed = 0;
  } else {
    tee(hole + 1);
  }
}

// One square of the roll; a wall ahead turns it back.
every speed {
  if left > 0 {
    if wall(bx + dx, by + dy) {
      dx = -dx;
      dy = -dy;
    }
    if wall(bx + dx, by + dy) {
      left = 0;
    } else {
      bx += dx;
      by += dy;
      left -= 1;
      if bx == cups[hole * 2 - 2] && by == cups[hole * 2 - 1] { holed(); }
    }
  }
}

