saved state best = 0;

fn wall(c: int, r: int) -> bool { return c <= 0 || c >= 13 || r <= 0 || r >= 8; }

fn water(c: int, r: int) -> bool { return c >= 6 && c <= 7 && r >= 3 && r <= 5; }

fn sand(c: int, r: int) -> bool {
  return (c == 9 && r >= 1 && r <= 2) || (r == 6 && c >= 4 && c <= 5);
}

fn start() {
  bx = 2;
  by = 4;
  left = 0;
  power = 3;
  strokes = 0;
  holed = false;
  speed = 100;
}

fn hit(x: int, y: int) {
  if speed > 0 && left == 0 {
    dx = x;
    dy = y;
    fx = bx;
    fy = by;
    left = power;
    strokes += 1;
  }
}

// One square of the roll: a wall ahead turns it back; then water, sand or the cup.
every speed {
  if left > 0 {
    if wall(bx + dx, by + dy) {
      dx = -dx;
      dy = -dy;
    }
    bx += dx;
    by += dy;
    left -= 1;
    if water(bx, by) {
      bx = fx;
      by = fy;
      left = 0;
      strokes += 1;
    } else if sand(bx, by) {
      left = 0;
    } else if bx == 11 && by == 4 && left <= 2 {
      holed = true;
      left = 0;
      speed = 0;
      if best == 0 || strokes < best { best = strokes; }
    }
  }
}

