  return n;
}

fn start() {
  for i in 0..63 {
    bricks[i] = i == 3 || i == 22 || i == 38 || i == 44 || i == 60;
    blast[i] = false;
  }
  ex = [6, 8];
  ey = [0, 6];
  edx = [-1, 0];
  edy = [0, -1];
  alive = [true, true];
  px = 0;
  py = 0;
  bomb = -1;
  steps = 0;
  lives = 3;
  score = 0;
  won = false;
  over = false;
  speed = 200;
}

fn die() {
  lives -= 1;
  px = 0;
  py = 0;
  if lives == 0 {
    over = true;
    speed = 0;
  }
}

// An enemy on the player's square costs a life.
fn touch() {
  for k in 0..2 {
    if speed > 0 && alive[k] && ex[k] == px && ey[k] == py { die(); }
  }
}

// The blast along one way from (c, r), up to 2 squares: a pillar stops it, a brick too.
fn ray(c: int, r: int, dx: int, dy: int) {
  for n in 1..3 {
    let x2 = c + dx * n;
    let y2 = r + dy * n;
    if x2 < 0 || x2 > 8 || y2 < 0 || y2 > 6 || pillar(x2, y2) { return; }
    blast[y2 * 9 + x2] = true;
    if bricks[y2 * 9 + x2] {
      bricks[y2 * 9 + x2] = false;
      score += 10;
      return;
    }
  }
}

fn explode() {
  let c = bomb % 9;
  let r = bomb / 9;
  bomb = -1;
  blast[r * 9 + c] = true;
  ray(c, r, 1, 0);
  ray(c, r, -1, 0);
  ray(c, r, 0, 1);
  ray(c, r, 0, -1);
  for k in 0..2 {
    if alive[k] && blast[ey[k] * 9 + ex[k]] {
      alive[k] = false;
      score += 100;
    }
  }
  if blast[py * 9 + px] { die(); }
}

// An enemy a square its way, or back the other way if that is blocked.
fn patrol(k: int) {
  if blocked(ex[k] + edx[k], ey[k] + edy[k]) {
    edx[k] = -edx[k];
    edy[k] = -edy[k];
  }
  if !blocked(ex[k] + edx[k], ey[k] + edy[k]) {
    ex[k] += edx[k];
    ey[k] += edy[k];
  }
}

every speed {
  steps += 1;
  for i in 0..63 { blast[i] = false; }
  if bomb >= 0 {
    fuse -= 1;
    if fuse == 0 { explode(); }
  }
  if speed > 0 && steps % 2 == 0 {
    for k in 0..2 {
      if alive[k] { patrol(k); }
    }
    touch();
  }
}

fn walk(dx: int, dy: int) {
  if speed > 0 && !blocked(px + dx, py + dy) {
    px += dx;
    py += dy;
    touch();
    if speed > 0 && px == 8 && py == 4 && !bricks[44] && enemies() == 0 {
      won = true;
      speed = 0;
    }
  }
}

fn drop() {
  if speed > 0 && bomb < 0 {
    bomb = py * 9 + px;
    fuse = 8;
  }
}

