// Pinball: space or Launch sends a ball up from the lower right; left and right (or a tap on
// either half) raise the flippers just before the ball lands. The red bumper scores 10.
// icon: line 3 21 3 3 21 3 21 21 dot 12 9 3 line 5 19 10 21 line 19 19 14 21 dot 16 15 2
state bx = 0;                   // the ball: square and way (across -1, 0 or 1; down -1 or 1)
state by = 0;
state dx = 0;
state dy = 0;
state inplay = false;
state upl = 0;                  // steps each flipper stays up
state upr = 0;
state balls = 3;
state score = 0;
state speed = 0;                // ms a step; 0 while no game runs
state over = false;

fn wall(c: int, r: int) -> bool { return c <= 0 || c >= 8 || r <= 0; }

fn start() {
  inplay = false;
  upl = 0;
  upr = 0;
  balls = 3;
  score = 0;
  over = false;
  speed = 150;
}

fn launch() {
  if speed > 0 && !inplay {
    bx = 7;
    by = 9;
    dx = -1;
    dy = -1;
    inplay = true;
  }
}

fn lose() {
  inplay = false;
  balls -= 1;
  if balls == 0 {
    over = true;
    speed = 0;
  }
}

// One square: walls turn it, the bumper sends it back, a raised flipper sends it up.
fn roll() {
  if dx != 0 && wall(bx + dx, by) { dx = -dx; }
  if wall(bx, by + dy) { dy = -dy; }
  let nx = bx + dx;
  let ny = by + dy;
  if nx == 3 && ny == 4 {
    dx = -dx;
    dy = -dy;
    score += 10;
  } else if ny == 10 {
    if nx >= 1 && nx <= 3 && upl > 0 {
      dx = nx - 2;
      dy = -1;
    } else if nx >= 5 && nx <= 7 && upr > 0 {
      dx = nx - 6;
      dy = -1;
    } else {
      lose();
    }
  } else {
    bx = nx;
    by = ny;
  }
}

every speed {
  if inplay { roll(); }
  upl = max(0, upl - 1);
  upr = max(0, upr - 1);
}

fn flipl() { if speed > 0 { upl = 2; } }
fn flipr() { if speed > 0 { upr = 2; } }

on key "left" { flipl(); }
on key "right" { flipr(); }
on key "space" { launch(); }

fn flip(up: int) -> int {
  if up > 0 { return 6; }
  return 4;
}

fn scene() {
  let cells = [-1; 108];
  for i in 0..108 {
    if wall(i % 9, i / 9) { cells[i] = 8; }
  }
  cells[39] = 1;
  for c in 1..4 { cells[90 + c] = flip(upl); }
  for c in 5..8 { cells[90 + c] = flip(upr); }
  if inplay { cells[by * 9 + bx] = 3; }
  pixels(cells, 0, 0, 9, 10);
  if over { text("Game over", 45, 60, 12, 11); }
}

label "Pinball";
label "Score: " + score + "   Balls: " + balls;
canvas 90, 120, scene() {
  if x < 45 {
    flipl();
  } else {
    flipr();
  }
}
row {
  if speed == 0 { button "Start" { start(); } }
  button "Launch" { launch(); }
}

// Pinball: up or Launch sends a ball up from the lower right; space (or a tap) raises both
// flippers. Knock down all three purple targets to reach the next level; clear level 2 to win.
// icon: line 3 21 3 3 21 3 21 21 fill 6 7 9 7 9 10 6 10 fill 15 7 18 7 18 10 15 10 dot 12 15 2 line 5 20 10 21 line 19 20 14 21
state bx = 0;                   // the ball: square and way (across -1, 0 or 1; down -1 or 1)
state by = 0;
state dx = 0;
state dy = 0;
state inplay = false;
state up = 0;                   // steps the flippers stay up
state stand = [true, true, true];   // the targets at columns 1, 5 and 7 of row 3
state tcol = [1, 5, 7];
state balls = 3;
state score = 0;
state level = 1;
state speed = 0;                // ms a step; 0 while no game runs
state result = "";

fn wall(c: int, r: int) -> bool { return c <= 0 || c >= 8 || r <= 0; }

// The standing target on (c, r), or -1.
fn target(c: int, r: int) -> int {
  for k in 0..3 {
    if stand[k] && r == 3 && tcol[k] == c { return k; }
  }
  return -1;
}

fn standing() -> int {
  let n = 0;
  for k in 0..3 {
    if stand[k] { n += 1; }
  }
  return n;
}

fn start() {
  inplay = false;
  up = 0;
  stand = [true, true, true];
  balls = 3;
  score = 0;
  level = 1;
  result = "";
  speed = 150;
}

fn launch() {
  if speed > 0 && !inplay {
    bx = 7;
    by = 9;
    dx = -1;
    dy = -1;
    inplay = true;
  }
}

fn knock(k: int) {
  stand[k] = false;
  score += 25;
  if standing() == 0 {
    score += 100;
    level += 1;
    if level == 3 {
      result = "You win";
      speed = 0;
    } else {
      stand = [true, true, true];
    }
  }
}

// One square: walls turn it, a target falls and sends it back, raised flippers send it up.
fn roll() {
  if dx != 0 && wall(bx + dx, by) { dx = -dx; }
  if wall(bx, by + dy) { dy = -dy; }
  let nx = bx + dx;
  let ny = by + dy;
  let k = target(nx, ny);
  if k >= 0 {
    dx = -dx;
    dy = -dy;
    knock(k);
  } else if ny == 10 {
    if up > 0 && nx >= 1 && nx <= 3 {
      dx = nx - 2;
      dy = -1;
    } else if up > 0 && nx >= 5 && nx <= 7 {
      dx = nx - 6;
      dy = -1;
    } else {
      inplay = false;
      balls -= 1;
      if balls == 0 {
        result = "Game over";
        speed = 0;
      }
    }
  } else {
    bx = nx;
    by = ny;
  }
}

every speed {
  if inplay { roll(); }
  up = max(0, up - 1);
}

fn flip() { if speed > 0 { up = 2; } }

on key "up" { launch(); }
on key "space" { flip(); }

fn scene() {
  let cells = [-1; 108];
  for i in 0..108 {
    if wall(i % 9, i / 9) { cells[i] = 8; }
  }
  for k in 0..3 {
    if stand[k] { cells[27 + tcol[k]] = 5; }
  }
  let f = 4;
  if up > 0 { f = 6; }
  for c in 1..8 {
    if c != 4 { cells[90 + c] = f; }
  }
  if inplay { cells[by * 9 + bx] = 3; }
  pixels(cells, 0, 0, 9, 10);
  if result != "" { text(result, 45, 60, 12, 11); }
}

label "Pinball";
label "Score: " + score + "   Balls: " + balls + "   Level: " + level;
canvas 90, 120, scene() { flip(); }
row {
  if speed == 0 { button "Start" { start(); } }
  button "Launch" { launch(); }
}

// Power grid: pick Plant, Line or House and tap to build (Bulldoze sells for half); houses joined
// to a plant by lines light up, 4 a plant. Start the months: lit houses pay 2, plants cost 3.
// icon: fill 13 2 6 13 11 13 9 22 18 10 13 10 15 2
state board = [0; 64];      // 8 x 8 squares, row by row: 0 empty, 1 plant, 2 line, 3 house
state power = [false; 64];  // the plants and the lines power reaches
state lit = [false; 64];    // the houses lit
state tool = 3;             // what a tap builds: 1 plant, 2 line, 3 house, 0 bulldoze
state names = ["Bulldoze", "Plant", "Line", "House"];
state costs = [0, 10, 1, 3];
state coins = 40;
state month = 0;
state speed = 0;            // ms a month: 2000 while the months run
state broke = false;

// The square beside i the way k goes (0 right, 1 left, 2 down, 3 up); -1 off the board.
fn beside(i: int, k: int) -> int {
  let dx = [1, -1, 0, 0];
  let dy = [0, 0, 1, -1];
  let c = i % 8 + dx[k];
  let r = i / 8 + dy[k];
  if c < 0 || c > 7 || r < 0 || r > 7 { return -1; }
  return r * 8 + c;
}

fn count(k: int) -> int {
  let n = 0;
  for i in 0..64 {
    if board[i] == k { n += 1; }
  }
  return n;
}

fn lights() -> int {
  let n = 0;
  for i in 0..64 {
    if lit[i] { n += 1; }
  }
  return n;
}

fn joined(i: int) -> bool {
  for k in 0..4 {
    let n = beside(i, k);
    if n >= 0 && power[n] { return true; }
  }
  return false;
}

// Power out from the plants along the lines; then the joined houses lit in order, 4 a plant.
fn wire() {
  let q = [0; 0];
  for i in 0..64 {
    power[i] = board[i] == 1;
    if power[i] { push(q, i); }
  }
  let h = 0;
  repeat 64 {
    if h < len(q) {
      let i = q[h];
      h += 1;
      for k in 0..4 {
        let n = beside(i, k);
        if n >= 0 && board[n] == 2 && !power[n] {
          power[n] = true;
          push(q, n);
        }
      }
    }
  }
  let room = 4 * count(1);
  for i in 0..64 {
    lit[i] = board[i] == 3 && room > 0 && joined(i);
    if lit[i] { room -= 1; }
  }
}

fn build(i: int) {
  if broke { return; }
  if tool == 0 {
    coins += costs[board[i]] / 2;
    board[i] = 0;
  } else if board[i] == 0 && coins >= costs[tool] {
    board[i] = tool;
    coins -= costs[tool];
  }
  wire();
}

fn reset() {
  for i in 0..64 { board[i] = 0; }
  wire();
  tool = 3;
  coins = 40;
  month = 0;
  broke = false;
}

every speed {
  month += 1;
  coins += 2 * lights() - 3 * count(1);
  if coins < 0 {
    broke = true;
    speed = 0;
  }
}

// The board, 8 x 8 squares of 16 units: plants red, lines gray, houses yellow when lit, else blue.
fn scene() {
  let tint = [-1, 1, 8, 4];
  let cells = [-1; 64];
  for i in 0..64 {
    cells[i] = tint[board[i]];
    if lit[i] { cells[i] = 3; }
  }
  pixels(cells, 0, 0, 8, 16);
  for k in 0..9 {
    line(k * 16, 0, k * 16, 128, 1, 10);
    line(0, k * 16, 128, k * 16, 1, 10);
  }
  if broke { text("Bankrupt", 64, 64, 16, 11); }
}

label "Power grid";
label "Month " + month + "   Coins " + coins + "   Lit " + lights();
label "Tool: " + names[tool];
canvas 128, 128, scene() { build((y / 16) * 8 + x / 16); }
row {
  for k in 0..4 { button names[(k + 1) % 4] { tool = (k + 1) % 4; } }
}
if speed == 0 && !broke && month == 0 { button "Start" { speed = 2000; } }
if broke { button "New city" { reset(); } }

// Town: pick Road, House or Farm and tap to build (Bulldoze clears); Start the days. Houses by a
// road hold 3 people who eat and pay tax; farms by a road grow food; 3 hungry days end it.
// icon: fill 3 11 12 3 21 11 loop 6 11 18 11 18 20 6 20 fill 10 14 14 14 14 20 10 20
state board = [0; 64];      // 8 x 8 squares, row by row: 0 empty, 1 road, 2 house, 3 farm
state tool = 1;             // what a tap builds: 1 road, 2 house, 3 farm, 0 bulldoze
state names = ["Bulldoze", "Road", "House", "Farm"];
state costs = [0, 1, 5, 4];
state coins = 40;
state food = 10;
state day = 0;
state hungry = 0;           // days in a row without enough food
state speed = 0;            // ms a day: 1000 while the days run
state over = false;

// Whether square i has a road beside it.
fn byroad(i: int) -> bool {
  let c = i % 8;
  let r = i / 8;
  if c > 0 && board[i - 1] == 1 { return true; }
  if c < 7 && board[i + 1] == 1 { return true; }
  if r > 0 && board[i - 8] == 1 { return true; }
  return r < 7 && board[i + 8] == 1;
}

// How many squares holding k have a road beside them.
fn served(k: int) -> int {
  let n = 0;
  for i in 0..64 {
    if board[i] == k && byroad(i) { n += 1; }
  }
  return n;
}

fn people() -> int { return 3 * served(2); }

fn build(i: int) {
  if over { return; }
  if tool == 0 {
    board[i] = 0;
  } else if board[i] == 0 && coins >= costs[tool] {
    board[i] = tool;
    coins -= costs[tool];
  }
}

fn reset() {
  for i in 0..64 { board[i] = 0; }
  tool = 1;
  coins = 40;
  food = 10;
  day = 0;
  hungry = 0;
  over = false;
}

// A day: the farms grow food, the people eat it and pay tax; without enough they go hungry.
every speed {
  day += 1;
  food += 4 * served(3);
  let p = people();
  if food >= p {
    food -= p;
    coins += p;
    hungry = 0;
  } else {
    food = 0;
    hungry += 1;
  }
  if hungry >= 3 {
    over = true;
    speed = 0;
  }
}

// The board, 8 x 8 squares of 16 units: roads gray, houses blue, farms green; faint edges.
fn scene() {
  let tint = [-1, 8, 4, 2];
  let cells = [-1; 64];
  for i in 0..64 { cells[i] = tint[board[i]]; }
  pixels(cells, 0, 0, 8, 16);
  for k in 0..9 {
    line(k * 16, 0, k * 16, 128, 1, 10);
    line(0, k * 16, 128, k * 16, 1, 10);
  }
  if over { text("Game over", 64, 64, 16, 11); }
}

label "Town";
label "Day " + day + "   Coins " + coins + "   Food " + food;
label "People " + people() + "   Hungry " + hungry + "   Tool: " + names[tool];
canvas 128, 128, scene() { build((y / 16) * 8 + x / 16); }
row {
  for k in 0..4 { button names[(k + 1) % 4] { tool = (k + 1) % 4; } }
}
if speed == 0 && !over && day == 0 { button "Start" { speed = 1000; } }
if over { button "New city" { reset(); } }

// Lanes: play cards from your hand into your lanes (more mana each turn), then End turn and the
// creatures fight; one with no foe across hits the hero. Bring the foe from 20 life to 0.
// icon: loop 3 3 10 3 10 13 3 13 loop 14 11 21 11 21 21 14 21 line 6 21 18 3
state cards = ["Squire", "Archer", "Knight"];
state costs = [1, 2, 3];
state atk = [1, 2, 3];
state hp = [2, 1, 3];
state foeatk = [1, 2, 3];     // Goblin, Wolf, Troll
state foehp = [1, 2, 4];
state hand = [0, 1, 2];       // cards held: 0 Squire, 1 Archer, 2 Knight
state drawn = 3;              // cards drawn: the next is drawn % 3
state mine = [0, 0, 0];       // my creature in each lane: its attack, and its health (0: none)
state minehp = [0, 0, 0];
state theirs = [0, 0, 0];     // the foe's
state theirhp = [0, 0, 0];
state sent = 0;               // creatures the foe has played
state life = 20;
state foe = 20;
state turn = 1;
state mana = 1;
state over = "";              // You win or You lose, once it is over

fn play(i: int) {
  let c = hand[i];
  if over != "" || mana < costs[c] { return; }
  for l in 0..3 {
    if minehp[l] == 0 {
      mine[l] = atk[c];
      minehp[l] = hp[c];
      mana -= costs[c];
      remove(hand, i);
      return;
    }
  }
}

// The foe's next creature into its leftmost empty lane; with none empty it waits.
fn enter() {
  for l in 0..3 {
    if theirhp[l] == 0 {
      theirs[l] = foeatk[sent % 3];
      theirhp[l] = foehp[sent % 3];
      sent += 1;
      return;
    }
  }
}

// The fight, lane by lane; then the foe plays and a new turn begins.
fn fight() {
  if over != "" { return; }
  for l in 0..3 {
    if minehp[l] > 0 && theirhp[l] > 0 {
      minehp[l] = max(0, minehp[l] - theirs[l]);
      theirhp[l] = max(0, theirhp[l] - mine[l]);
    } else if minehp[l] > 0 {
      foe = max(0, foe - mine[l]);
    } else if theirhp[l] > 0 {
      life = max(0, life - theirs[l]);
    }
  }
  if foe == 0 {
    over = "You win";
  } else if life == 0 {
    over = "You lose";
  } else {
    enter();
    turn += 1;
    mana = min(5, turn);
    push(hand, drawn % 3);
    drawn += 1;
  }
}

fn reset() {
  clear(hand);
  for c in 0..3 {
    push(hand, c);
    mine[c] = 0;
    minehp[c] = 0;
    theirs[c] = 0;
    theirhp[c] = 0;
  }
  drawn = 3;
  sent = 0;
  life = 20;
  foe = 20;
  turn = 1;
  mana = 1;
  over = "";
}

// The board: 3 lanes of 40 units, the foe's row above, mine below; each creature's attack and
// health written in its square, above its middle.
fn scene() {
  let cells = [-1; 6];
  for l in 0..3 {
    if theirhp[l] > 0 { cells[l] = 1; }
    if minehp[l] > 0 { cells[3 + l] = 4; }
  }
  pixels(cells, 0, 0, 3, 40);
  for l in 0..3 {
    if theirhp[l] > 0 { text(theirs[l] + "/" + theirhp[l], l * 40 + 20, 8, 8, 9); }
    if minehp[l] > 0 { text(mine[l] + "/" + minehp[l], l * 40 + 20, 48, 8, 9); }
  }
  line(0, 40, 120, 40, 1, 10);
  if over != "" { text(over, 60, 40, 12, 11); }
}

label "Lanes";
label "Turn " + turn + "   Mana " + mana;
label "Life " + life + "   Foe " + foe;
canvas 120, 80, scene();
row {
  for i in 0..len(hand) { button cards[hand[i]] { play(i); } }
}
row {
  button "End turn" { fight(); }
  if over != "" { button "New game" { reset(); } }
}

// Spire: play cards from your hand (Strike 6 damage, Bash 10, Defend 5 block) with 3 energy a
// turn, then End turn and the foe attacks. Beat the Slime, the Goblin and the Ogre in turn.
// icon: line 5 19 17 7 line 15 5 19 9 line 7 13 11 17 dot 5 19 2
state deck = [0, 1, 0, 2, 1, 0, 1, 2, 0, 1];   // 0 Strike, 1 Defend, 2 Bash
state hand = [0, 1, 0, 2, 1];                 // the first five, dealt
state next = 5;                               // the next card of the deck drawn
state cards = ["Strike", "Defend", "Bash"];
state foes = ["Slime", "Goblin", "Ogre"];
state lives = [20, 24, 32];
state foe = 0;
state hp = 20;
state hits = 0;              // attacks this foe has made
state health = 30;
state block = 0;
state energy = 3;
state over = "";             // You win or Defeated, once it is over

// The foe's next attack: the Slime 4, 6; the Goblin 5, 5, 10; the Ogre 8, 12; round and round.
fn attack() -> int {
  if foe == 0 {
    if hits % 2 == 0 { return 4; }
    return 6;
  }
  if foe == 1 {
    if hits % 3 == 2 { return 10; }
    return 5;
  }
  if hits % 2 == 0 { return 8; }
  return 12;
}

fn cost(c: int) -> int {
  if c == 2 { return 2; }
  return 1;
}

// A new turn: 5 cards from the deck, round and round; 3 energy; no block.
fn draw() {
  clear(hand);
  for k in 0..5 {
    push(hand, deck[next]);
    next = (next + 1) % 10;
  }
  block = 0;
  energy = 3;
}

fn play(i: int) {
  let c = hand[i];
  if over != "" || energy < cost(c) { return; }
  energy -= cost(c);
  remove(hand, i);
  if c == 1 {
    block += 5;
    return;
  }
  if c == 0 { hp -= 6; } else { hp -= 10; }
  if hp <= 0 {
    foe += 1;
    hits = 0;
    if foe == 3 {
      hp = 0;
      over = "You win";
    } else {
      hp = lives[foe];
      draw();
    }
  }
}

fn end() {
  if over != "" { return; }
  health = max(0, health - max(0, attack() - block));
  hits += 1;
  if health == 0 { over = "Defeated"; } else { draw(); }
}

fn reset() {
  next = 0;
  draw();
  foe = 0;
  hp = 20;
  hits = 0;
  health = 30;
  over = "";
}

fn name() -> string { return foes[min(foe, 2)]; }

// The foe: a body sized by its kind, its HP as a bar; the end said over it.
fn scene() {
  let k = min(foe, 2);
  let tint = [2, 6, 5];
  if over != "You win" {
    circle(80, 50, 18 + k * 6, tint[k]);
    circle(72 - k * 2, 44, 3, 9);
    circle(88 + k * 2, 44, 3, 9);
    rect(30, 88, 100, 6, 8);
    rect(30, 88, hp * 100 / lives[k], 6, 1);
  }
  if over != "" { text(over, 80, 50, 16, 11); }
}

label "Spire";
label "Health " + health + "   Block " + block + "   Energy " + energy;
label name() + "   HP " + hp + "   Attack " + attack();
canvas 160, 100, scene();
row {
  for i in 0..len(hand) { button cards[hand[i]] { play(i); } }
}
row {
  button "End turn" { end(); }
  if over != "" { button "New run" { reset(); } }
}

// Wildfire box: pick Sand, Plant, Fire, Stone or Erase and tap or drag to paint. Sand falls and
// piles; fire spreads from plant to plant and burns out after 3 steps; stone stops it.
// icon: fill 12 2 18 11 17 17 12 21 7 17 6 11 9 7 11 11
state box = [0; 192];       // 16 x 12 squares, row by row: 0 empty, 1 fire, 2 plant, 3 sand, 8 stone
state age = [0; 192];       // steps each fire has burned
state was = [false; 192];   // the squares burning before this step
state tool = 3;
state burned = 0;           // plants caught fire
state names = ["Sand", "Plant", "Fire", "Stone", "Erase"];
state kinds = [3, 2, 1, 8, 0];

fn open(c: int, r: int) -> bool {
  return c >= 0 && c < 16 && r < 12 && box[r * 16 + c] == 0;
}

// Where the grain on (c, r) falls this step: down, else down-left, else down-right; -1 none.
fn drop(c: int, r: int) -> int {
  if open(c, r + 1) { return (r + 1) * 16 + c; }
  if open(c - 1, r + 1) { return (r + 1) * 16 + c - 1; }
  if open(c + 1, r + 1) { return (r + 1) * 16 + c + 1; }
  return -1;
}

// Whether a square beside square i was burning before this step.
fn near(i: int) -> bool {
  let c = i % 16;
  if c > 0 && was[i - 1] { return true; }
  if c < 15 && was[i + 1] { return true; }
  if i >= 16 && was[i - 16] { return true; }
  return i < 176 && was[i + 16];
}

fn count(k: int) -> int {
  let n = 0;
  for i in 0..192 {
    if box[i] == k { n += 1; }
  }
  return n;
}

fn name(k: int) -> string {
  for t in 0..5 {
    if kinds[t] == k { return names[t]; }
  }
  return "";
}

fn paint(i: int) {
  box[i] = tool;
  age[i] = 0;
}

// A step: the sand falls (from the bottom row up); the fires light the plants beside them, then
// burn a step more, going out after 3.
every 100 {
  let moved = [false; 192];
  for j in 0..12 {
    for c in 0..16 {
      let i = (11 - j) * 16 + c;
      if box[i] == 3 && !moved[i] {
        let t = drop(c, 11 - j);
        if t >= 0 {
          box[t] = 3;
          box[i] = 0;
          moved[t] = true;
        }
      }
    }
  }
  for i in 0..192 { was[i] = box[i] == 1; }
  for i in 0..192 {
    if box[i] == 2 && near(i) {
      box[i] = 1;
      age[i] = 0;
      burned += 1;
    }
  }
  for i in 0..192 {
    if was[i] {
      age[i] += 1;
      if age[i] >= 3 { box[i] = 0; }
    }
  }
}

fn scene() {
  let cells = [-1; 192];
  for i in 0..192 {
    if box[i] > 0 { cells[i] = box[i]; }
  }
  pixels(cells, 0, 0, 16, 10);
}

