  button "Clear" {
    for i in 0..192 { box[i] = 0; }
  }
}

// Beat box: tap the squares to put drum hits on the 16 steps (rows: Kick, Snare, Hat, Clap); Play
// runs the beat, lighting each step as it sounds; + and - set the BPM; Basic puts in a beat.
// icon: fill 4 11 20 11 18 20 6 20 line 6 3 11 10 line 18 3 13 10
state pat = [false; 64];    // 4 rows of 16 steps, row by row: Kick, Snare, Hat, Clap
state step = 0;             // the step playing, 1 to 16; 0 while stopped
state bpm = 120;
state hits = 0;
state speed = 0;            // ms a step; 0 while stopped

// How many drums are on at step s (1 to 16).
fn sounds(s: int) -> int {
  let n = 0;
  for r in 0..4 {
    if pat[r * 16 + s - 1] { n += 1; }
  }
  return n;
}

// Step s begins: what is on there sounds.
fn reach(s: int) {
  step = s;
  hits += sounds(s);
}

fn play() {
  hits = 0;
  speed = 15000 / bpm;
  reach(1);
}

fn stop() {
  speed = 0;
  step = 0;
}

fn tempo(d: int) {
  bpm = min(240, max(60, bpm + d));
  if speed > 0 { speed = 15000 / bpm; }
}

// The basic beat: the kick on 1, 5, 9 and 13, the snare on 5 and 13, the hat on every odd step.
fn basic() {
  for i in 0..64 {
    let c = i % 16;
    let r = i / 16;
    pat[i] = (r == 0 && c % 4 == 0) || (r == 1 && c % 8 == 4) || (r == 2 && c % 2 == 0);
  }
}

fn flip(i: int) { pat[i] = !pat[i]; }

every speed { reach(step % 16 + 1); }

// The board, 16 x 4 squares of 10 units, each drum its color; the step playing lit; faint edges.
fn scene() {
  let tint = [1, 3, 4, 5];
  let cells = [-1; 64];
  for i in 0..64 {
    if pat[i] { cells[i] = tint[i / 16]; }
    if step == i % 16 + 1 {
      if pat[i] { cells[i] = 2; } else { cells[i] = 8; }
    }
  }
  pixels(cells, 0, 0, 16, 10);
  for k in 0..17 { line(k * 10, 0, k * 10, 40, 1, 10); }
  for k in 0..5 { line(0, k * 10, 160, k * 10, 1, 10); }
}

label "Beat box";
label "Step " + step + "   BPM " + bpm + "   Hits " + hits;
canvas 160, 40, scene() { flip((y / 10) * 16 + x / 10); }
label "Rows: Kick, Snare, Hat, Clap";
row {
  if speed == 0 { button "Play" { play(); } } else { button "Stop" { stop(); } }
  button "-" { tempo(-10); }
  button "+" { tempo(10); }
  button "Basic" { basic(); }
  button "Clear" {
    for i in 0..64 { pat[i] = false; }
  }
}

// Tune maker: tap a square to put that note on its step (tap it again to take it off); Play loops
// the tune, lighting each note; the keys 1 to 8 (0 none) change the step playing.
// icon: dot 8 18 4 line 12 18 12 4 18 8
state tune = [0; 8];        // each step's pitch: 1 (the bottom row) to 8 (the top); 0 no note
state step = 0;             // the step playing, 1 to the length; 0 while stopped
state length = 8;
state speed = 0;            // ms a step: 250 while it plays

// A tap: the pitch on its step, or off if it is there already.
fn put(c: int, n: int) {
  if tune[c] == n { tune[c] = 0; } else { tune[c] = n; }
}

// The pitch playing now.
fn now() -> int {
  if step == 0 { return 0; }
  return tune[step - 1];
}

// Every note a row up (d 1) or down (d -1), unless one would leave the board.
fn shift(d: int) {
  for c in 0..8 {
    if tune[c] > 0 && (tune[c] + d < 1 || tune[c] + d > 8) { return; }
  }
  for c in 0..8 {
    if tune[c] > 0 { tune[c] += d; }
  }
}

fn record(n: int) {
  if step > 0 { tune[step - 1] = n; }
}

fn play() {
  step = 1;
  speed = 250;
}

fn stop() {
  step = 0;
  speed = 0;
}

every speed {
  if step >= length { step = 1; } else { step += 1; }
}

// The board, 8 x 8 squares of 12 units, the note playing lit; faint edges, and the tune's end.
fn scene() {
  let cells = [-1; 64];
  for c in 0..8 {
    if tune[c] > 0 {
      let i = (8 - tune[c]) * 8 + c;
      cells[i] = 4;
      if step == c + 1 { cells[i] = 3; }
    }
  }
  pixels(cells, 0, 0, 8, 12);
  for k in 0..9 {
    line(k * 12, 0, k * 12, 96, 1, 10);
    line(0, k * 12, 96, k * 12, 1, 10);
  }
  line(length * 12, 0, length * 12, 96, 2, 11);
}

on key "0" { record(0); }
on key "1" { record(1); }
on key "2" { record(2); }
on key "3" { record(3); }
on key "4" { record(4); }
on key "5" { record(5); }
on key "6" { record(6); }
on key "7" { record(7); }
on key "8" { record(8); }

label "Tune maker";
label "Step " + step + "   Note " + now() + "   Length " + length;
