    for c in 0..8 { tune[c] = 0; }
  }
}

// Pet: type a name and Adopt; Feed, Play, Buy snack, Sleep and Wake; tap it to pet it. An hour
// passes every 2 seconds: it grows hungry, bored and tired; left starving it sickens and runs away.
// icon: ring 12 14 8 fill 4 3 10 7 5 11 fill 20 3 14 7 19 11 dot 9 13 2 dot 15 13 2
state typed = "";           // what the input holds
state pet = "";             // the pet's name; "" before the first adoption
state food = 5;
state fun = 5;
state energy = 5;
state health = 5;
state coins = 10;
state snacks = 2;
state hour = 0;
state asleep = false;
state petted = false;       // petted already this hour
state speed = 0;            // ms an hour: 2000 while a pet is with you

fn cap(v: int) -> int { return min(10, max(0, v)); }

fn here() -> bool { return speed > 0; }

fn awake() -> bool { return speed > 0 && !asleep; }

// The first of these that holds.
fn mood() -> string {
  if asleep { return "Asleep"; }
  if health <= 2 { return "Sick"; }
  if food <= 2 { return "Hungry"; }
  if energy <= 2 { return "Tired"; }
  if fun <= 2 { return "Bored"; }
  if fun >= 7 { return "Happy"; }
  return "Okay";
}

fn adopt() {
  if typed == "" { return; }
  pet = typed;
  food = 5;
  fun = 5;
  energy = 5;
  health = 5;
  coins = 10;
  snacks = 2;
  hour = 0;
  asleep = false;
  petted = false;
  speed = 2000;
}

fn feed() {
  if awake() && snacks > 0 {
    snacks -= 1;
    food = cap(food + 3);
  }
}

fn play() {
  if awake() && energy >= 2 {
    energy -= 2;
    fun = cap(fun + 3);
    coins += 2;
  }
}

fn buy() {
  if here() && coins >= 3 {
    coins -= 3;
    snacks += 1;
  }
}

fn stroke() {
  if awake() && !petted {
    fun = cap(fun + 1);
    petted = true;
  }
}

// An hour: hungrier, and bored and tired while awake (rested while asleep); starving hurts.
every speed {
  hour += 1;
  food = cap(food - 1);
  if asleep {
    energy = cap(energy + 3);
  } else {
    fun = cap(fun - 1);
    energy = cap(energy - 1);
  }
  if food == 0 { health -= 1; }
  petted = false;
  if health <= 0 {
    health = 0;
    speed = 0;
  }
}

// Its eyes and mouth by its mood.
fn face(m: string) {
  if m == "Asleep" {
    line(62, 50, 72, 50, 2, 9);
    line(88, 50, 98, 50, 2, 9);
    text("z z", 124, 24, 10, 10);
  } else {
    circle(67, 50, 4, 9);
    circle(93, 50, 4, 9);
  }
  if m == "Happy" {
    line(70, 68, 80, 74, 2, 9);
    line(80, 74, 90, 68, 2, 9);
  } else if m == "Okay" || m == "Asleep" {
    line(72, 70, 88, 70, 2, 9);
  } else {
    line(70, 74, 80, 68, 2, 9);
    line(80, 68, 90, 74, 2, 9);
  }
}

// The pet: a round purple body with ears, its face, and its mood under it.
fn scene() {
  if pet == "" {
    text("Type a name, then Adopt", 80, 60, 8, 10);
  } else if !here() {
    text("Ran away", 80, 60, 16, 11);
  } else {
    circle(56, 28, 12, 5);
    circle(104, 28, 12, 5);
    circle(80, 60, 34, 5);
    face(mood());
    text(mood(), 80, 108, 10, 9);
  }
}

label "Pet";
if !here() {
  row {
    input typed;
    button "Adopt" { adopt(); }
  }
}
if pet != "" {
  label pet + "   Hour " + hour;
  label "Food " + food + "   Fun " + fun + "   Energy " + energy + "   Health " + health;
  label "Coins " + coins + "   Snacks " + snacks;
}
