// Alarm clock: the clock starts at 12:00:00. Type the alarm's hour and minute and press Set;
// it beeps at that time until Off, which turns the alarm off.
// icon: fill 12 3 17 7 18 15 21 18 3 18 6 15 7 7 dot 12 20 2
state now = 43200;        // the clock, in seconds from midnight
state hour = "";
state minute = "";
state alarm = -1;         // the alarm, in minutes from midnight; -1: off
state beeping = false;

// Two digits: 5 is 05.
fn two(n: int) -> string {
  if n < 10 { return "0" + n; }
  return "" + n;
}

fn shown() -> string {
  if alarm < 0 { return "off"; }
  return two(alarm / 60) + ":" + two(alarm % 60);
}

fn set_alarm() {
  let h = parse(hour, -1);
  let m = parse(minute, -1);
  if h >= 0 && h <= 23 && m >= 0 && m <= 59 { alarm = h * 60 + m; }
}

every 1000 {
  now = (now + 1) % 86400;
  if now == alarm * 60 { beeping = true; }
}

label "Alarm clock";
label two(now / 3600) + ":" + two(now / 60 % 60) + ":" + two(now % 60);
row {
  label "Hour";
  input hour;
  label "Minute";
  input minute;
  button "Set" { set_alarm(); }
}
label "Alarm: " + shown();
if beeping {
  label "Beep!";
  button "Off" {
    beeping = false;
    alarm = -1;
