  if cols[n % 8] == bx { score += 1; } else { missed += 1; }
  n += 1;
  ay = 0;
  if missed >= 3 {
    speed = 0;
    over = true;
  }
}

fn steer(c: int) {
  if speed > 0 { bx = min(7, max(0, c)); }
}

