// Catch the fruit, dodge the bombs: Start, then move the basket with left and right, or tap a
// column. A missed fruit or a caught bomb costs a life; three lives.
// icon: dot 9 9 5 dot 16 6 3 line 16 3 18 1 fill 3 15 21 15 18 21 6 21
state cols = [2, 7, 4, 0, 9, 5];  // the columns the things fall in, in turn
state tx = [0; 0];        // the things falling: column, row, whether a bomb
state ty = [0; 0];
state tb = [false; 0];
state made = 0;           // things dropped this game
state steps = 0;
state mid = 5;            // the basket's middle column; it covers mid - 1 to mid + 1
state score = 0;
state lives = 3;
state speed = 0;          // ms a step; 0 while no game runs
state over = false;

// The next thing, in the top row: every third a bomb.
fn drop() {
  push(tx, cols[made % 6]);
  push(ty, 0);
  push(tb, (made + 1) % 3 == 0);
  made += 1;
}

fn start() {
  clear(tx);
  clear(ty);
  clear(tb);
  made = 0;
  steps = 0;
  mid = 5;
  score = 0;
  lives = 3;
  over = false;
  speed = 300;
  drop();
}

// A thing in the bottom row: into the basket or past it.
fn land(i: int) {
  let caught = abs(tx[i] - mid) <= 1;
  if caught && !tb[i] { score += 1; }
  if caught == tb[i] { lives -= 1; }
}

every speed {
  steps += 1;
  for j in 0..len(ty) {
    let i = len(ty) - 1 - j;
    ty[i] += 1;
    if ty[i] == 7 {
      land(i);
      remove(tx, i);
      remove(ty, i);
      remove(tb, i);
    }
  }
  if lives <= 0 {
    speed = 0;
    over = true;
  } else if steps % 4 == 0 {
    drop();
  }
}

fn steer(c: int) {
  if speed > 0 { mid = min(8, max(1, c)); }
}

fn tint(i: int) -> int {
  if tb[i] { return 1; }
  return 2;
}

// The board, 10 x 8 squares of 12 units: fruit green, bombs red, the basket blue.
fn scene() {
  let b = [-1; 80];
  for i in 0..len(tx) { b[ty[i] * 10 + tx[i]] = tint(i); }
  for c in mid - 1..mid + 2 { b[70 + c] = 4; }
  pixels(b, 0, 0, 10, 12);
  if over { text("Game over", 60, 40, 14, 11); }
}

