// Bridges: tap an island, then another in its row or column, to build a bridge; again for a
// second, again to take them away. Give every island its number of bridges; none may cross.
// icon: ring 5 6 3 ring 19 6 3 ring 12 18 3 line 8 5 16 5 line 8 7 16 7 line 6 9 10 15
state ix = [0, 3, 6, 0, 2, 5, 0, 3, 6, 0, 2, 6];   // the islands' columns, rows and numbers
state iy = [0, 0, 0, 2, 2, 2, 4, 4, 4, 6, 6, 6];
state need = [3, 2, 2, 5, 3, 1, 3, 3, 5, 1, 2, 4];
state ba = [0; 0];            // the bridges: the two islands and how many (1 or 2)
state bb = [0; 0];
state bn = [0; 0];
state picked = -1;

fn island(c: int, r: int) -> int {
  for k in 0..len(ix) {
    if ix[k] == c && iy[k] == r { return k; }
  }
  return -1;
}

fn bridge(a: int, b: int) -> int {
  for i in 0..len(ba) {
    if (ba[i] == a && bb[i] == b) || (ba[i] == b && bb[i] == a) { return i; }
  }
  return -1;
}

fn deg(k: int) -> int {
  let n = 0;
  for i in 0..len(ba) {
    if ba[i] == k || bb[i] == k { n += bn[i]; }
  }
  return n;
}

fn total() -> int {
  let n = 0;
  for i in 0..len(bn) { n += bn[i]; }
  return n;
}

fn solved() -> bool {
  for k in 0..len(ix) {
    if deg(k) != need[k] { return false; }
  }
  return true;
}

fn sign(n: int) -> int {
  if n > 0 { return 1; }
  if n < 0 { return -1; }
  return 0;
}

// How many squares lie between islands a and b (in line), and the s-th of them from a.
fn gap(a: int, b: int) -> int { return abs(ix[b] - ix[a]) + abs(iy[b] - iy[a]) - 1; }

fn sq(a: int, b: int, s: int) -> int {
  return (iy[a] + sign(iy[b] - iy[a]) * s) * 7 + ix[a] + sign(ix[b] - ix[a]) * s;
}

// Whether a and b may be joined: in line, nothing between them, no other bridge across the way.
fn joinable(a: int, b: int) -> bool {
  if ix[a] != ix[b] && iy[a] != iy[b] { return false; }
  let water = [0; 49];
  for i in 0..len(ba) {
    if i != bridge(a, b) {
      for s in 1..gap(ba[i], bb[i]) + 1 { water[sq(ba[i], bb[i], s)] = 1; }
    }
  }
  for s in 1..gap(a, b) + 1 {
    let j = sq(a, b, s);
    if island(j % 7, j / 7) >= 0 || water[j] > 0 { return false; }
  }
  return true;
}

// None, one, two, then none again between a and b.
fn cycle(a: int, b: int) {
  let i = bridge(a, b);
  if i < 0 {
    push(ba, a);
    push(bb, b);
    push(bn, 1);
  } else if bn[i] == 1 {
    bn[i] = 2;
  } else {
    remove(ba, i);
    remove(bb, i);
    remove(bn, i);
  }
}

fn tap(c: int, r: int) {
  let k = island(c, r);
  if k < 0 || solved() { return; }
  if picked < 0 {
    picked = k;
  } else if picked == k {
    picked = -1;
  } else if joinable(picked, k) {
    cycle(picked, k);
    picked = -1;
  } else {
    picked = k;
  }
}

fn tint(k: int) -> int {
  if deg(k) < need[k] { return 3; }
  if deg(k) == need[k] { return 2; }
  return 1;
}

// Squares of 20 units: under one bridge blue, two purple; the islands over them with their numbers.
fn scene() {
  let b = [-1; 49];
  for i in 0..len(ba) {
    for s in 1..gap(ba[i], bb[i]) + 1 { b[sq(ba[i], bb[i], s)] = 3 + bn[i]; }
  }
  pixels(b, 0, 0, 7, 20);
  for k in 0..len(ix) {
    circle(ix[k] * 20 + 10, iy[k] * 20 + 10, 8, tint(k));
    if k == picked { ring(ix[k] * 20 + 10, iy[k] * 20 + 10, 10, 2, 9); }
    text(need[k], ix[k] * 20 + 10, iy[k] * 20 + 10, 10, 9);
  }
}

