// Whether (x, y) is on the board and on no trail.
fn free(x: int, y: int) -> bool {
  return x >= 0 && x < 14 && y >= 0 && y < 10 && board[y * 14 + x] == 0;
}

// The computer's way: straight if free, else to its left, else to its right, else straight.
fn plan() -> int {
  let left = (cd + 3) % 4;
  let right = (cd + 1) % 4;
  if free(cx + dxs[cd], cy + dys[cd]) { return cd; }
  if free(cx + dxs[left], cy + dys[left]) { return left; }
  if free(cx + dxs[right], cy + dys[right]) { return right; }
  return cd;
}

