fn count(v: int) -> int {
  let n = 0;
  for i in 0..5 {
    if dice[i] == v { n += 1; }
  }
  return n;
}

fn sum() -> int {
  let n = 0;
  for i in 0..5 { n += dice[i]; }
  return n;
}

// The most dice showing one number.
fn most() -> int {
  let m = 0;
  for v in 1..7 { m = max(m, count(v)); }
  return m;
}

// Whether the dice hold n numbers in a row.
fn straight(n: int) -> bool {
  for a in 1..8 - n {
    let ok = true;
    for v in a..a + n {
      if count(v) == 0 { ok = false; }
    }
    if ok { return true; }
  }
  return false;
}

fn pairs() -> bool {
  for v in 1..7 {
    if count(v) == 2 { return true; }
  }
  return false;
}

// What the dice score in category k.
fn worth(k: int) -> int {
  if k < 6 { return count(k + 1) * (k + 1); }
  if k == 6 && most() >= 3 { return sum(); }
  if k == 7 && most() >= 4 { return sum(); }
  if k == 8 && most() == 3 && pairs() { return 25; }
  if k == 9 && straight(4) { return 30; }
  if k == 10 && straight(5) { return 40; }
  if k == 11 && most() == 5 { return 50; }
  if k == 12 { return sum(); }
  return 0;
}

fn upper() -> int {
  let n = 0;
  for k in 0..6 { n += got[k]; }
  return n;
}

fn total() -> int {
  let n = extra;
  for k in 0..13 { n += got[k]; }
  if upper() >= 63 { n += 35; }
  return n;
}

fn roll() {
  if over || rolls >= 3 { return; }
  for i in 0..5 {
    if rolls == 0 || !held[i] {
      dice[i] = list[next];
      next = (next + 1) % len(list);
    }
  }
  rolls += 1;
}

fn hold(i: int) {
  if !over && rolls > 0 { held[i] = !held[i]; }
}

fn take(k: int) {
  if over || rolls == 0 || used[k] { return; }
  if most() == 5 && used[11] && got[11] == 50 { extra += 100; }
  got[k] = worth(k);
  used[k] = true;
  rolls = 0;
  for i in 0..5 { held[i] = false; }
  let left = 0;
  for j in 0..13 {
    if !used[j] { left += 1; }
  }
  over = left == 0;
}

fn fresh() {
  next = 0;
  rolls = 0;
  extra = 0;
  over = false;
  for k in 0..13 {
    used[k] = false;
    got[k] = 0;
