fn points(n: int) -> int {
  if n <= 4 { return 1; }
  if n == 5 { return 2; }
  if n == 6 { return 3; }
  if n == 7 { return 5; }
  return 11;
}

// A letter joins the word if the clock runs, it is not in it yet and it touches the last one.
fn add(i: int) {
  if speed == 0 || used(i) { return; }
  if len(path) > 0 && !near(path[len(path) - 1], i) { return; }
  push(path, i);
}

fn enter() {
