// Whether the group of stones at i has a liberty: a search over its stones.
fn free(i: int) -> bool {
  let p = board[i];
  let seen = [false; 49];
  let todo = [i];
  seen[i] = true;
  let at = 0;
  repeat 49 {
    if at < len(todo) {
      let j = todo[at];
      at += 1;
      for d in 0..4 {
        let k = step(j, d);
        if k >= 0 && board[k] == 0 { return true; }
        if k >= 0 && board[k] == p && !seen[k] {
          seen[k] = true;
          push(todo, k);
        }
      }
    }
  }
  return false;
}

// Takes the group of stones at i off the board: how many.
fn take(i: int) -> int {
  let p = board[i];
  let todo = [i];
  board[i] = 0;
  let at = 0;
  repeat 49 {
    if at < len(todo) {
      let j = todo[at];
      at += 1;
      for d in 0..4 {
        let k = step(j, d);
        if k >= 0 && board[k] == p {
          board[k] = 0;
          push(todo, k);
        }
      }
    }
  }
  return len(todo);
}

// A stone at i; the other's groups it leaves without a liberty are taken. A move that leaves its
// own group none is taken back.
fn play(i: int) {
  if winner != 0 || board[i] != 0 { return; }
  for k in 0..49 { before[k] = board[k]; }
  board[i] = turn;
  let got = 0;
  for d in 0..4 {
    let k = step(i, d);
    if k >= 0 && board[k] == 3 - turn && !free(k) { got += take(k); }
  }
  if !free(i) {
    for k in 0..49 { board[k] = before[k]; }
    return;
  }
  taken[turn] += got;
  if taken[turn] >= 5 { winner = turn; } else { turn = 3 - turn; }
}

fn fresh() {
  for k in 0..49 { board[k] = 0; }
  taken[1] = 0;
  taken[2] = 0;
  turn = 1;
  winner = 0;
}

// Lines through the middles of 7 x 7 squares of 20 units; black stones ink, white silver.
