    if board[i] == 2 {
      circle(x, y, 9, 7);
      ring(x, y, 9, 1, 10);
    }
  }
}

fn status() -> string {
  if winner == 1 { return "Black wins"; }
  if winner == 2 { return "White wins"; }
  if turn == 1 { return "Black to play"; }
  return "White to play";
}

