// Centipede: left and right (or a tap) move your shooter; space or Fire sends a dart up its
// column. A mushroom takes two hits. Shoot every segment; it reaching you costs one of 3 lives.
// icon: dot 6 16 3 dot 12 16 3 dot 18 16 3 line 18 13 16 8 line 12 11 12 3
state sc = [0; 0];              // the segments: column, row and way (1 right, -1 left)
state sr = [0; 0];
state sw = [0; 0];
state shrooms = [0; 99];        // a mushroom's hits left on each square: 2 whole, 1 hit once
state gun = 4;                  // the shooter's column, on row 10
state dc = 0;                   // the dart: its column and row, the row -1 when none flies
state dr = -1;
state score = 0;
state lives = 3;
state steps = 0;
state speed = 0;                // ms a step; 0 while no game runs
state result = "";

fn at(c: int, r: int) -> int { return r * 9 + c; }

// n segments on row 0, from column 0, heading right.
fn place(n: int) {
  clear(sc);
  clear(sr);
  clear(sw);
  for c in 0..n {
    push(sc, c);
    push(sr, 0);
    push(sw, 1);
  }
}

fn start() {
  for i in 0..99 { shrooms[i] = 0; }
  shrooms[at(2, 2)] = 2;
  shrooms[at(6, 4)] = 2;
  shrooms[at(3, 6)] = 2;
  gun = 4;
  dr = -1;
  score = 0;
  lives = 3;
  steps = 0;
  result = "";
  place(4);
  speed = 100;
}

fn segat(c: int, r: int) -> int {
  for i in 0..len(sc) {
    if sc[i] == c && sr[i] == r { return i; }
  }
  return -1;
}

// Whatever stands on (c, r) is hit; whether anything did.
fn hit(c: int, r: int) -> bool {
  let i = segat(c, r);
  if i >= 0 {
    remove(sc, i);
    remove(sr, i);
    remove(sw, i);
    shrooms[at(c, r)] = 2;
    score += 10;
    if len(sc) == 0 {
      result = "You win";
      speed = 0;
    }
    return true;
  }
  if shrooms[at(c, r)] > 0 {
    shrooms[at(c, r)] -= 1;
    score += 1;
    return true;
  }
  return false;
}

fn blocked(c: int, r: int) -> bool {
  if c < 0 || c > 8 { return true; }
  return shrooms[at(c, r)] > 0;
}

// A segment reached row 10: a life lost, and those left start over on row 0.
fn lost() {
  lives -= 1;
  dr = -1;
  if lives == 0 {
    result = "Game over";
    speed = 0;
  } else {
    place(len(sc));
  }
}

fn reached() -> bool {
  for i in 0..len(sc) {
    if sr[i] == 10 { return true; }
  }
  return false;
}

fn crawl() {
  for i in 0..len(sc) {
    if blocked(sc[i] + sw[i], sr[i]) {
      sr[i] += 1;
      sw[i] = -sw[i];
    } else {
      sc[i] += sw[i];
    }
  }
  if dr >= 0 && segat(dc, dr) >= 0 && hit(dc, dr) { dr = -1; }
  if reached() { lost(); }
}

fn fire() {
  if speed > 0 && dr < 0 && !hit(gun, 9) {
    dc = gun;
    dr = 9;
  }
}

fn slide(d: int) {
  if speed > 0 { gun = min(8, max(0, gun + d)); }
}

every speed {
  steps += 1;
  if dr >= 0 {
    dr -= 1;
    if dr >= 0 && hit(dc, dr) { dr = -1; }
  }
  if speed > 0 && steps % 2 == 0 { crawl(); }
}

on key "left" { slide(-1); }
on key "right" { slide(1); }
on key "space" { fire(); }

fn scene() {
  let cells = [-1; 99];
  for i in 0..99 {
    if shrooms[i] == 2 { cells[i] = 5; }
    if shrooms[i] == 1 { cells[i] = 1; }
  }
  cells[at(gun, 10)] = 4;
  if dr >= 0 { cells[at(dc, dr)] = 3; }
  for i in 0..len(sc) { cells[at(sc[i], sr[i])] = 2; }
  pixels(cells, 0, 0, 9, 10);
  if result != "" { text(result, 45, 50, 12, 11); }
}

