// Air Hockey for two: blue moves with the arrows, red with w a s d; move into the puck to strike
// it. It slows a little at every rail. Score in the other's goal; the first to 3 wins.
// icon: ring 12 12 9 dot 12 12 3 line 8 3 16 3 line 8 21 16 21
state mx = [3, 3];              // the mallets, blue (0) in rows 6 to 9 and red (1) in rows 1 to 4
state my = [8, 2];
state px = 3;                   // the puck: square, way across and up or down, speed (it moves
state py = 5;                   // every speed-th step) and steps until it moves
state dx = 0;
state dy = 0;
state slow = 1;
state wait = 0;
state score = [0, 0];
state speed = 0;                // ms a step; 0 while no game runs
state result = "";

// The puck at rest in the middle, the mallets back.
fn face() {
  mx = [3, 3];
  my = [8, 2];
  px = 3;
  py = 5;
  dx = 0;
  dy = 0;
  slow = 1;
}

fn start() {
  score = [0, 0];
  result = "";
  face();
  speed = 100;
}

fn goal(k: int) {
  score[k] += 1;
  face();
  if score[k] == 3 {
    result = "Blue wins";
    if k == 1 { result = "Red wins"; }
    speed = 0;
  }
}

fn held(c: int, r: int) -> bool { return c == mx[0] && r == my[0] || c == mx[1] && r == my[1]; }

// The puck moves: off a rail it turns and slows, at a mallet it turns back and stays.
fn glide() {
  if px + dx < 0 || px + dx > 6 {
    dx = -dx;
    slow = min(4, slow + 1);
  }
  if py + dy < 0 || py + dy > 10 {
    dy = -dy;
    slow = min(4, slow + 1);
  }
  if held(px + dx, py + dy) {
    dx = -dx;
    dy = -dy;
  } else {
    px += dx;
    py += dy;
    if px >= 2 && px <= 4 && py == 0 { goal(0); }
    if px >= 2 && px <= 4 && py == 10 { goal(1); }
  }
  wait = slow;
}

every speed {
  if dx != 0 || dy != 0 {
    wait -= 1;
    if wait <= 0 { glide(); }
  }
}

// Mallet k a square that way, kept in its half; onto the puck (wherever it is) it stays and
// strikes it instead.
fn slide(k: int, x: int, y: int) {
  let c = mx[k] + x;
  let r = my[k] + y;
  if speed == 0 { return; }
  if c == px && r == py {
    if x != 0 { dx = x; }
    if y != 0 { dy = y; }
    slow = 1;
    wait = 1;
  } else if c >= 0 && c <= 6 && r >= 1 + 5 * (1 - k) && r <= 4 + 5 * (1 - k) {
    mx[k] = c;
    my[k] = r;
  }
}

on key "left" { slide(0, -1, 0); }
on key "right" { slide(0, 1, 0); }
on key "up" { slide(0, 0, -1); }
on key "down" { slide(0, 0, 1); }
on key "a" { slide(1, -1, 0); }
on key "d" { slide(1, 1, 0); }
on key "w" { slide(1, 0, -1); }
on key "s" { slide(1, 0, 1); }

