// A pump for the first monster on the two squares ahead, through dug squares only.
fn pump() {
  if speed == 0 { return; }
  for k in 1..3 {
    let c = px + fx * k;
    let r = py + fy * k;
    if !inside(c, r) || dirt[at(c, r)] { return; }
    let i = monster(c, r);
    if i >= 0 {
      pumps[i] += 1;
      if pumps[i] == 3 {
        alive[i] = false;
        score += 100;
      }
      if !alive[0] && !alive[1] && level == 2 {
        result = "You win";
        speed = 0;
      } else if !alive[0] && !alive[1] {
        level = 2;
        setup();
