// Q*bert: hop with the arrows or a tap (up and left hop up, right and down down) to turn every
// cube yellow; dodge the green balls. Three levels, each harder to finish; 3 lives.
// icon: fill 12 3 21 8 12 13 3 8 fill 3 8 12 13 12 21 3 16 fill 21 8 12 13 12 21 21 16
state cube = [0; 10];           // each cube, 0 blue, 1 purple, 2 yellow: row r, place i at at(r, i)
state qr = 0;                   // Q*bert's cube: row and place in it
state qi = 0;
state br = -1;                  // the ball's cube (row -1: none) and its hops so far
state bi = 0;
state hops = 0;
state level = 1;
state lives = 3;
state score = 0;
state steps = 0;                // steps since the level began
state speed = 0;                // ms a step; 0 while no game runs
state result = "";

fn at(r: int, i: int) -> int { return r * (r + 1) / 2 + i; }

fn left() -> int {
  let n = 0;
  for k in 0..10 {
    if cube[k] != 2 { n += 1; }
  }
  return n;
}

fn begin() {
  for k in 0..10 { cube[k] = 0; }
  qr = 0;
  qi = 0;
  br = -1;
  steps = 0;
}

fn start() {
  level = 1;
  lives = 3;
  score = 0;
  result = "";
  begin();
  speed = 200;
}

fn lose() {
  lives -= 1;
  qr = 0;
  qi = 0;
  br = -1;
  if lives == 0 {
    result = "Game over";
    speed = 0;
  }
}

// Q*bert lands on cube k: its color moves on as the level says.
fn turn(k: int) {
  let was = cube[k];
  if level == 1 || level == 3 && cube[k] == 0 {
    cube[k] = 2;
  } else if level == 2 {
    cube[k] = min(2, cube[k] + 1);
  } else {
    cube[k] = 0;
  }
  if cube[k] != was { score += 25; }
  if left() == 0 && level == 3 {
    result = "You win";
    speed = 0;
  } else if left() == 0 {
    level += 1;
    begin();
  }
}

fn hop(dr: int, di: int) {
  if speed == 0 { return; }
  let r = qr + dr;
  let i = qi + di;
  if r < 0 || r > 3 || i < 0 || i > r {
    lose();
  } else if r == br && i == bi {
    lose();
  } else {
    qr = r;
    qi = i;
    turn(at(r, i));
  }
}

every speed {
  steps += 1;
  if br >= 0 {
    br += 1;
    if hops % 2 == 1 { bi += 1; }
    hops += 1;
    if br > 3 { br = -1; }
  } else if steps % 5 == 0 {
    br = 0;
    bi = 0;
    hops = 0;
  }
  if br == qr && bi == qi { lose(); }
}

on key "up" { hop(-1, 0); }
on key "left" { hop(-1, -1); }
on key "right" { hop(1, 1); }
on key "down" { hop(1, 0); }

fn scene() {
  let cells = [-1; 28];
  let colors = [4, 5, 3];
  for r in 0..4 {
    for i in 0..r + 1 { cells[r * 7 + 3 - r + 2 * i] = colors[cube[at(r, i)]]; }
  }
  if br >= 0 { cells[br * 7 + 3 - br + 2 * bi] = 2; }
  cells[qr * 7 + 3 - qr + 2 * qi] = 1;
  pixels(cells, 0, 0, 7, 10);
  if result != "" { text(result, 35, 35, 10, 11); }
}

label "Q*bert";
label "Level: " + level + "   Lives: " + lives + "   Score: " + score + "   Left: " + left();
// A tap hops toward it: up or down, then left or right.
canvas 70, 40, scene() {
  let c = 3 - qr + 2 * qi;
  if y / 10 < qr && x / 10 < c { hop(-1, -1); } else if y / 10 < qr { hop(-1, 0); }
  if y / 10 > qr && x / 10 < c { hop(1, 0); } else if y / 10 > qr { hop(1, 1); }
}
if speed == 0 { button "Start" { start(); } }

// Q*bert: hop with the arrows or a tap (up and left hop up, right and down down) to turn every
// cube yellow. Coily chases you; ride a cyan disc and it leaps after you. 3 lives.
// icon: fill 12 3 21 8 12 13 3 8 fill 3 8 12 13 12 21 3 16 fill 21 8 12 13 12 21 21 16
state yellow = [false; 15];     // each cube, row r, place i at r * (r + 1) / 2 + i
state qr = 0;                   // Q*bert's cube
state qi = 0;
state cr = -1;                  // Coily's cube (row -1: not on the pyramid)
state ci = 0;
state discs = [true, true];     // the left disc and the right one
state lives = 3;
state score = 0;
state steps = 0;
state speed = 0;                // ms a step; 0 while no game runs
state result = "";

fn at(r: int, i: int) -> int { return r * (r + 1) / 2 + i; }

fn cube(r: int, i: int) -> bool { return r >= 0 && r < 5 && i >= 0 && i <= r; }

fn place(r: int, i: int) -> int { return 4 - r + 2 * i; }

fn start() {
  for k in 0..15 { yellow[k] = false; }
  qr = 0;
  qi = 0;
  cr = -1;
  discs = [true, true];
  lives = 3;
  score = 0;
  steps = 0;
  result = "";
  speed = 300;
}

fn lose() {
  lives -= 1;
  qr = 0;
  qi = 0;
  cr = -1;
  if lives == 0 {
    result = "Game over";
    speed = 0;
  }
}

fn land(r: int, i: int) {
  qr = r;
  qi = i;
  if !yellow[at(r, i)] {
    yellow[at(r, i)] = true;
    score += 25;
  }
  let all = true;
  for k in 0..15 {
    if !yellow[k] { all = false; }
  }
  if all {
    result = "You win";
    speed = 0;
  }
}

// A disc carries Q*bert to the top; Coily leaps after him.
fn ride(d: int) {
  discs[d] = false;
  if cr >= 0 {
    cr = -1;
    score += 500;
  }
  land(0, 0);
}

fn hop(dr: int, di: int) {
  if speed == 0 { return; }
  let r = qr + dr;
  let i = qi + di;
  if r == 1 && i == -1 && discs[0] {
    ride(0);
  } else if r == 1 && i == 2 && discs[1] {
    ride(1);
  } else if !cube(r, i) || r == cr && i == ci {
    lose();
  } else {
    land(r, i);
  }
}

// Coily hops toward Q*bert: down unless he is higher, left if he is to the left.
every speed {
  steps += 1;
  if cr < 0 {
    if steps % 4 == 0 {
      cr = 0;
      ci = 0;
    }
  } else {
    let dr = 1;
    if qr < cr { dr = -1; }
    let dc = 1;
    if place(qr, qi) < place(cr, ci) { dc = -1; }
    cr += dr;
    ci += (dr + dc) / 2;
    if !cube(cr, ci) {
      cr = -1;
      score += 500;
    }
  }
  if cr == qr && ci == qi { lose(); }
}

on key "up" { hop(-1, 0); }
on key "left" { hop(-1, -1); }
on key "right" { hop(1, 1); }
on key "down" { hop(1, 0); }

fn scene() {
  let cells = [-1; 45];
  for r in 0..5 {
    for i in 0..r + 1 {
      cells[r * 9 + place(r, i)] = 4;
      if yellow[at(r, i)] { cells[r * 9 + place(r, i)] = 3; }
    }
  }
  if discs[0] { cells[10] = 6; }
  if discs[1] { cells[16] = 6; }
  if cr >= 0 { cells[cr * 9 + place(cr, ci)] = 5; }
  cells[qr * 9 + place(qr, qi)] = 1;
  pixels(cells, 0, 0, 9, 10);
  if result != "" { text(result, 45, 45, 12, 11); }
}

label "Q*bert";
label "Lives: " + lives + "   Score: " + score;
// A tap hops toward it: up or down, then left or right.
canvas 90, 50, scene() {
  let c = place(qr, qi);
  if y / 10 < qr && x / 10 < c { hop(-1, -1); } else if y / 10 < qr { hop(-1, 0); }
  if y / 10 > qr && x / 10 < c { hop(1, 0); } else if y / 10 > qr { hop(1, 1); }
}
if speed == 0 { button "Start" { start(); } }

// Helicopter: space or Engine turns the engine on and off; on, the helicopter climbs harder and
// harder, off it drops. Fly as far through the cave as you can without touching its rock.
// icon: line 4 7 20 7 line 12 7 12 10 fill 7 10 17 10 17 17 7 17 line 17 13 22 13 line 7 20 17 20
state tops = [1, 1, 2, 3, 4, 4, 3, 2, 1, 1];      // the cave, again every 10 columns: rock
state floors = [9, 8, 8, 9, 9, 8, 7, 6, 6, 7];    // above tops, and from floors down
state hy = 4;                   // the helicopter's row, in column 3
state climb = 0;                // rows a step, below 0 up: -2 to 2
state engine = false;
state distance = 0;
saved state best = 0;
state speed = 0;                // ms a step; 0 while no game runs
state crashed = false;

fn rock(w: int, r: int) -> bool { return r < tops[w % 10] || r >= floors[w % 10]; }

fn start() {
  hy = 4;
  climb = 0;
  engine = false;
  distance = 0;
  crashed = false;
  speed = 200;
}

fn crash() {
  crashed = true;
  speed = 0;
  best = max(best, distance);
}

// The cave moves a column; the climb changes by 1; the helicopter moves a row at a time.
every speed {
  distance += 1;
  if engine { climb = max(-2, climb - 1); } else { climb = min(2, climb + 1); }
  for k in 0..abs(climb) {
    if !crashed {
      hy += climb / abs(climb);
      if rock(distance + 3, hy) { crash(); }
    }
  }
  if !crashed && rock(distance + 3, hy) { crash(); }
}

fn toggle() {
  if speed > 0 { engine = !engine; }
}

on key "space" { toggle(); }

fn onoff(on: bool) -> string {
  if on { return "on"; }
  return "off";
}

fn scene() {
  let cells = [-1; 160];
  for i in 0..160 {
    if rock(distance + i % 16, i / 16) { cells[i] = 8; }
  }
  cells[hy * 16 + 3] = 3;
  pixels(cells, 0, 0, 16, 10);
  if crashed { text("Game over", 80, 50, 16, 11); }
}

label "Helicopter";
label "Distance: " + distance + "   Best: " + best + "   Engine: " + onoff(engine);
canvas 160, 100, scene();
row {
  if speed == 0 { button "Start" { start(); } }
  button "Engine" { toggle(); }
}

// Helicopter Rescue: the arrows (or a tap) fly your helicopter, each move burning fuel; it sinks
// when you wait. Pick people off the roofs and land on the cyan pad to drop them and refuel.
// icon: line 4 6 20 6 line 12 6 12 9 fill 6 9 18 9 18 16 6 16 line 18 12 22 12 line 8 19 16 19
state px = [0; 0];              // the people still on the roofs
state py = [0; 0];
state hx = 0;                   // the helicopter
state hy = 6;
state fuel = 25;
state aboard = 0;
state level = 1;
state score = 0;
state speed = 0;                // ms a step; 0 while no game runs
state result = "";

fn solid(c: int, r: int) -> bool {
  if r == 7 { return true; }
  return (c == 4 || c == 5) && r >= 4 || (c == 8 || c == 9) && r >= 2 || c == 11 && r >= 5;
}

fn person(c: int, r: int) {
  push(px, c);
  push(py, r);
}

fn begin() {
  clear(px);
  clear(py);
  if level == 1 {
    person(4, 3);
    person(9, 1);
  } else {
    person(5, 3);
    person(9, 1);
    person(7, 6);
  }
  hx = 0;
  hy = 6;
  fuel = 28 - 3 * level;
  aboard = 0;
}

fn start() {
  level = 1;
  score = 0;
  result = "";
  begin();
  speed = 400;
}

// Where the helicopter is now: people there climb aboard; on the pad all aboard get off.
fn arrive() {
  for i in 0..len(px) {
    if i < len(px) && px[i] == hx && py[i] == hy {
      remove(px, i);
      remove(py, i);
      aboard += 1;
    }
  }
  if hy == 6 && hx <= 1 {
    score += 100 * aboard;
    aboard = 0;
    fuel = 28 - 3 * level;
    if len(px) == 0 && level == 2 {
      result = "You win";
      speed = 0;
    } else if len(px) == 0 {
      level = 2;
      begin();
    }
  } else if fuel == 0 {
    result = "Game over";
    speed = 0;
  }
}

fn fly(dx: int, dy: int) {
  let c = hx + dx;
  let r = hy + dy;
  if speed > 0 && fuel > 0 && c >= 0 && c < 12 && r >= 0 && !solid(c, r) {
    hx = c;
    hy = r;
    fuel -= 1;
    arrive();
  }
}

every speed {
  if !solid(hx, hy + 1) {
    hy += 1;
    arrive();
  }
}

on key "left" { fly(-1, 0); }
on key "right" { fly(1, 0); }
on key "up" { fly(0, -1); }
on key "down" { fly(0, 1); }

fn scene() {
  let cells = [-1; 96];
  for i in 0..96 {
    if solid(i % 12, i / 12) { cells[i] = 8; }
  }
  cells[84] = 6;
  cells[85] = 6;
  for i in 0..len(px) { cells[py[i] * 12 + px[i]] = 2; }
  cells[hy * 12 + hx] = 3;
  pixels(cells, 0, 0, 12, 10);
  if result != "" { text(result, 60, 25, 14, 11); }
}

label "Helicopter Rescue";
label "Level: " + level + "   Fuel: " + fuel + "   Aboard: " + aboard + "   Score: " + score;
// A tap flies a square toward it, across or up and down, whichever is farther.
canvas 120, 80, scene() {
  let dx = x / 10 - hx;
  let dy = y / 10 - hy;
  if abs(dx) > abs(dy) { fly(dx / abs(dx), 0); } else if dy != 0 { fly(0, dy / abs(dy)); }
}
if speed == 0 { button "Start" { start(); } }

// Ant colony: tap earth beside a tunnel to dig it (as many digs a day as ants); Start the days.
// Ants eat 1 food a day and hatch when there is food and room. Dig out all three food pockets.
// icon: dot 12 6 3 dot 12 12 3 dot 12 18 4 line 8 9 16 9 line 7 15 17 15
state dug = [false; 80];    // 10 x 8 squares, row by row: dug out by the ants
state day = 0;
state ants = 2;
state food = 6;
state digs = 2;
state found = 0;            // food pockets dug out
state speed = 0;            // ms a day: 1000 while the days run
state over = "";            // You win or Game over, once it ends

// The nest (column 4, rows 1 and 2) and what the ants dug.
fn tunnel(i: int) -> bool { return dug[i] || i == 14 || i == 24; }

fn pocket(i: int) -> bool { return i == 31 || i == 28 || i == 75; }

// Grass (row 0) and rock (row 4, columns 3 to 6) are never dug.
fn hard(i: int) -> bool { return i < 10 || (i / 10 == 4 && i % 10 >= 3 && i % 10 <= 6); }

fn beside(i: int) -> bool {
  let c = i % 10;
  if c > 0 && tunnel(i - 1) { return true; }
  if c < 9 && tunnel(i + 1) { return true; }
  if i >= 10 && tunnel(i - 10) { return true; }
  return i < 70 && tunnel(i + 10);
}

fn tunnels() -> int {
  let n = 0;
  for i in 0..80 {
    if tunnel(i) { n += 1; }
  }
  return n;
}

fn dig(i: int) {
  if over != "" || digs == 0 || tunnel(i) || hard(i) || !beside(i) { return; }
  dug[i] = true;
  digs -= 1;
  if pocket(i) {
    food += 6;
    found += 1;
    if found == 3 {
      over = "You win";
      speed = 0;
    }
  }
}

fn reset() {
  for i in 0..80 { dug[i] = false; }
  day = 0;
  ants = 2;
  food = 6;
  digs = 2;
  found = 0;
  speed = 0;
  over = "";
}

// A day: the ants eat (short of food, one dies), one hatches if it can, the digs come back.
every speed {
  day += 1;
  if food >= ants {
    food -= ants;
  } else {
    food = 0;
    ants -= 1;
  }
  if food >= 3 && tunnels() > ants {
    ants += 1;
    food -= 3;
  }
  digs = ants;
  if ants == 0 {
    over = "Game over";
    speed = 0;
  }
}

// The slice of earth, 10 x 8 squares of 12 units: grass green, rock gray, food red, earth yellow,
// tunnels empty.
fn scene() {
  let cells = [3; 80];
  for i in 0..80 {
    if tunnel(i) {
      cells[i] = -1;
    } else if i < 10 {
      cells[i] = 2;
    } else if hard(i) {
      cells[i] = 8;
    } else if pocket(i) {
      cells[i] = 1;
    }
  }
  pixels(cells, 0, 0, 10, 12);
  if over != "" { text(over, 60, 48, 14, 11); }
}

label "Ant colony";
label "Day " + day + "   Ants " + ants + "   Food " + food + "   Digs " + digs;
canvas 120, 96, scene() {
  if x < 120 && y < 96 { dig((y / 12) * 10 + x / 12); }
}
if speed == 0 && day == 0 && over == "" { button "Start" { speed = 1000; } }
if over != "" { button "New colony" { reset(); } }

// Colony: send idle colonists to Farm or Mine, Build domes with metal, then Start the days. Each
// colonist eats 1 food a day; every 3rd day a newcomer comes if a dome has room. Reach 10.
// icon: fill 3 18 5 12 9 9 12 8 15 9 19 12 21 18 line 2 21 22 21 line 12 8 12 3
state day = 0;
state food = 12;
state metal = 0;
state domes = 1;
state idle = 4;
state farmers = 0;
state miners = 0;
state speed = 0;            // ms a day: 1000 while the days run
state over = "";            // Colony lost or Colony thrives, once it ends

fn people() -> int { return idle + farmers + miners; }

fn send(job: int) {
  if over != "" || idle == 0 { return; }
  idle -= 1;
  if job == 0 { farmers += 1; } else { miners += 1; }
}

fn recall() {
  if over != "" { return; }
  idle += farmers + miners;
  farmers = 0;
  miners = 0;
}

fn build() {
  if over == "" && metal >= 10 {
    metal -= 10;
    domes += 1;
  }
}

// One colonist starves: an idle one first, then a miner, then a farmer.
fn starve() {
  if idle > 0 {
    idle -= 1;
  } else if miners > 0 {
    miners -= 1;
  } else if farmers > 0 {
    farmers -= 1;
  }
}

fn reset() {
  day = 0;
  food = 12;
  metal = 0;
  domes = 1;
  idle = 4;
  farmers = 0;
  miners = 0;
  speed = 0;
  over = "";
}

// A day: work, then eat (short of food, one starves), then maybe a newcomer.
every speed {
  day += 1;
  food += 3 * farmers;
  metal += 2 * miners;
  let n = people();
  if food >= n {
    food -= n;
  } else {
    food = 0;
    starve();
  }
  if day % 3 == 0 && people() < 4 * domes { idle += 1; }
  if people() == 0 {
    over = "Colony lost";
    speed = 0;
  } else if people() >= 10 {
    over = "Colony thrives";
    speed = 0;
  }
}

// The colony: domes on red ground, its colonists in front (farmers green, miners silver, idle
// blue); the end said over it.
fn scene() {
  for k in 0..min(domes, 5) { circle(20 + k * 30, 52, 13, 6); }
  rect(0, 52, 160, 28, 1);
  let n = min(people(), 12);
  for i in 0..n {
    let c = 4;
    if i < farmers { c = 2; } else if i < farmers + miners { c = 7; }
    circle(12 + i * 12, 66, 4, c);
  }
  if over != "" { text(over, 80, 24, 14, 11); }
}

label "Colony";
label "Day " + day + "   Food " + food + "   Metal " + metal + "   Domes " + domes;
label "Colonists " + people() + "   Idle " + idle + "   Farmers " + farmers + "   Miners " + miners;
canvas 160, 80, scene();
row {
  button "Farm" { send(0); }
  button "Mine" { send(1); }
  button "Recall" { recall(); }
  button "Build dome" { build(); }
}
if speed == 0 && day == 0 && over == "" { button "Start" { speed = 1000; } }
if over != "" { button "New colony" { reset(); } }

// Zoo keeper: pick up a food, then tap a pen to feed its animal (the wrong food makes it hungrier).
// Animals under 5 hunger bring a coin a minute: buy a penguin and a giraffe. Reach 25 coins.
// icon: ring 12 13 8 dot 6 6 3 dot 18 6 3 dot 9 12 2 dot 15 12 2 line 10 17 14 17
state hunger = [0, 0, 0, 0];             // the Lion, the Panda, the Penguin, the Giraffe
state here = [true, true, false, false];
state names = ["Lion", "Panda", "Penguin", "Giraffe"];
state foods = ["meat", "bamboo", "fish", "leaves"];
state pace = [2, 1, 3, 1];               // how much hungrier a minute makes each
state tint = [3, 7, 4, 5];
state carry = -1;                        // the food carried, or -1
state coins = 0;
state minute = 0;
state speed = 0;                         // ms a minute: 1000 while the zoo is open
state over = "";                         // Game over or You win, once it ends

fn pick(f: int) {
  if over == "" { carry = f; }
}

// The food carried, given to the animal in pen p: its own fills it, any other upsets it.
fn feed(p: int) {
  if over != "" || carry < 0 || !here[p] { return; }
  if carry == p { hunger[p] = 0; } else { hunger[p] += 2; }
  carry = -1;
}

fn buy(p: int, cost: int) {
  if over == "" && !here[p] && coins >= cost {
    coins -= cost;
    here[p] = true;
  }
}

fn carrying() -> string {
  if carry < 0 { return "Carrying nothing"; }
  return "Carrying " + foods[carry];
}

fn reset() {
  for p in 0..4 { hunger[p] = 0; }
  here[2] = false;
  here[3] = false;
  carry = -1;
  coins = 0;
  minute = 0;
  over = "";
}

// A minute: all grow hungrier, the content ones bring a coin; one at 10 escapes.
every speed {
  minute += 1;
  let loose = false;
  for p in 0..4 {
    if here[p] {
      hunger[p] += pace[p];
      if hunger[p] < 5 { coins += 1; }
      if hunger[p] >= 10 { loose = true; }
    }
  }
  if loose {
    over = "Game over";
  } else if coins >= 25 {
    over = "You win";
  }
  if over != "" { speed = 0; }
}

// Four pens of 40 units: each animal a body in its color, its hunger a red bar under it.
fn scene() {
  for p in 0..4 {
    rect(p * 40 + 1, 1, 38, 58, 2);
    text(names[p], p * 40 + 20, 8, 6, 9);
    if here[p] {
      circle(p * 40 + 20, 30, 10, tint[p]);
      circle(p * 40 + 16, 28, 2, 9);
      circle(p * 40 + 24, 28, 2, 9);
      rect(p * 40 + 5, 50, min(hunger[p], 10) * 3, 4, 1);
    }
  }
  if over != "" { text(over, 80, 30, 14, 11); }
}

label "Zoo keeper";
label "Minute " + minute + "   Coins " + coins + "   " + carrying();
