if over != "" { button "New game" { reset(); } }

// Soccer manager: pick three players with their buttons and Play the next match. Players who
// play tire (fitness under 5 halves their skill) and the others rest. Five matches; 9 points wins.
// icon: ring 12 12 9 fill 12 8 16 11 14 15 10 15 8 11
state names = ["Axel", "Bolt", "Cruz", "Duke", "Enzo"];
state skill = [6, 5, 4, 3, 2];
state fit = [10, 10, 10, 10, 10];
state picked = [false, false, false, false, false];
state teams = ["Rovers", "United", "City", "Athletic", "Wanderers"];
state power = [9, 12, 14, 10, 15];
state played = 0;
state points = 0;
state scored = 0;
state conceded = 0;
state last = "";             // the last result

fn part(p: int) -> int {
  if fit[p] < 5 { return skill[p] / 2; }
  return skill[p];
}

fn strength() -> int {
  let s = 0;
  for p in 0..5 {
    if picked[p] { s += part(p); }
  }
  return s;
}

fn count() -> int {
  let n = 0;
  for p in 0..5 {
    if picked[p] { n += 1; }
  }
  return n;
}

fn toggle(p: int) {
  if picked[p] {
    picked[p] = false;
  } else if count() < 3 {
    picked[p] = true;
  }
}

// The next match: goals are strengths divided by 3; then the players tire or rest.
fn play() {
  if played == 5 || count() != 3 { return; }
  let us = strength() / 3;
  let them = power[played] / 3;
  scored += us;
  conceded += them;
  if us > them { points += 3; } else if us == them { points += 1; }
  last = "Last: " + us + " - " + them + " " + teams[played];
  played += 1;
  for p in 0..5 {
    if picked[p] { fit[p] = max(0, fit[p] - 4); } else { fit[p] = min(10, fit[p] + 3); }
  }
}

fn reset() {
  for p in 0..5 {
    fit[p] = 10;
    picked[p] = false;
  }
  played = 0;
  points = 0;
  scored = 0;
  conceded = 0;
  last = "";
}

fn mark(p: int) -> string {
  if picked[p] { return "  (in)"; }
  return "";
}

fn next() -> string {
  if played < 5 { return "Next " + teams[played]; }
  if points >= 9 { return "Champions"; }
  return "Season over";
}

label "Soccer manager";
label next();
label "Played " + played + "   Points " + points + "   Scored " + scored + "   Conceded " + conceded;
if last != "" { label last; }
for p in 0..5 { label names[p] + " " + fit[p] + mark(p); }
label "Lineup strength " + strength();
row {
  for p in 0..5 { button names[p] { toggle(p); } }
}
row {
  button "Play" { play(); }
  button "New season" { reset(); }
}

// Touchline: Kick off, then pick Attack, Balanced or Defend as the match runs and bring on a Sub
// when legs tire (under 50 Energy). Home has a chance on odd tens of minutes, Away on even ones.
// icon: loop 2 5 22 5 22 19 2 19 line 12 5 12 19 ring 12 12 4
state minute = 0;
state home = 0;
state away = 0;
state tactic = 1;            // 0 Attack, 1 Balanced, 2 Defend
state names = ["Attack", "Balanced", "Defend"];
state attacks = [8, 6, 3];
state defenses = [3, 6, 8];
state energy = 100;
state subs = 3;
state speed = 0;             // ms a minute: 200 while the match runs
state over = "";             // the result, at full time

fn tired() -> int {
  if energy < 50 { return 2; }
  return 0;
}

fn attack() -> int { return attacks[tactic] - tired(); }

fn defense() -> int { return defenses[tactic] - tired(); }

fn pick(t: int) {
  if over == "" { tactic = t; }
}

fn sub() {
  if over == "" && subs > 0 {
    subs -= 1;
    energy = 100;
  }
}

fn reset() {
  minute = 0;
  home = 0;
  away = 0;
  tactic = 1;
  energy = 100;
  subs = 3;
  speed = 0;
  over = "";
}

// A minute: legs tire; on each ten a chance, Home's on odd tens and Away's on even ones.
every speed {
  minute += 1;
  if tactic == 0 { energy = max(0, energy - 2); } else { energy = max(0, energy - 1); }
  if minute % 20 == 10 && attack() > 5 { home += 1; }
  if minute % 20 == 0 && defense() < 6 { away += 1; }
  if minute == 90 {
    speed = 0;
    if home > away {
      over = "Full time: You win";
    } else if home < away {
      over = "Full time: You lose";
    } else {
      over = "Full time: Draw";
    }
  }
}

// The pitch: the ball near the goal of the next chance, the score over it.
fn scene() {
  rect(0, 0, 160, 90, 2);
  line(80, 0, 80, 90, 1, 9);
  ring(80, 45, 12, 1, 9);
  rect(0, 33, 6, 24, 9);
  rect(154, 33, 6, 24, 9);
  let bx = 80;
  if minute > 0 && minute < 90 {
    if (minute / 10) % 2 == 0 { bx = 130; } else { bx = 30; }
  }
  circle(bx, 45, 4, 9);
  if over != "" { text(over, 80, 20, 10, 11); }
}

label "Touchline";
