// Active-time battle: Start, and when your gauge is full Attack or drink a Potion. Beat the Wolf,
// the Troll and the Dragon in turn; each one beaten levels you up.
// icon: line 4 20 16 8 line 14 4 20 10 line 6 14 10 18 loop 3 21 7 21 7 17
state names = ["Wolf", "Troll", "Dragon"];
state lives = [20, 40, 60];
state hits = [4, 7, 9];
state paces = [5, 4, 10];       // how much each monster's gauge fills a tick
state m = 0;                    // the monster fought
state foe = 20;
state hp = 50;
state power = 6;
state potions = 2;
state level = 1;
state gauge = 0;                // the Hero's
state fill = 0;                 // the monster's
state speed = 0;                // ms a tick: 100 while the fight runs
state begun = false;
state over = "";                // Victory or Game over, once it ends

fn ready() -> bool { return speed > 0 && gauge >= 100; }

// The monster beaten: the next one comes, the Hero levels up.
fn beaten() {
  if m == 2 {
    over = "Victory";
    speed = 0;
    return;
  }
  m += 1;
  foe = lives[m];
  fill = 0;
  level += 1;
  power += 3;
  hp = 50;
}

fn attack() {
  if !ready() { return; }
  gauge = 0;
  foe = max(0, foe - power);
  if foe == 0 { beaten(); }
}

fn potion() {
  if ready() && potions > 0 {
    potions -= 1;
    hp = min(50, hp + 15);
    gauge = 0;
  }
}

fn reset() {
  m = 0;
  foe = 20;
  hp = 50;
  power = 6;
  potions = 2;
  level = 1;
  gauge = 0;
  fill = 0;
  speed = 0;
  begun = false;
  over = "";
}

every speed {
  gauge = min(100, gauge + 10);
  fill += paces[m];
  if fill >= 100 {
    fill = 0;
    hp = max(0, hp - hits[m]);
    if hp == 0 {
      over = "Game over";
      speed = 0;
    }
  }
}

// The Hero and the monster face to face, each with its gauge as a bar under it.
fn scene() {
  rect(20, 30, 20, 30, 4);
  circle(30, 22, 8, 4);
  circle(120, 40, 14 + m * 4, 1 + m * 2);
  rect(10, 80, gauge * 4 / 10, 6, 6);
  rect(100, 80, fill * 4 / 10, 6, 1);
  line(10, 89, 50, 89, 1, 10);
  line(100, 89, 140, 89, 1, 10);
  if over != "" { text(over, 80, 10, 12, 11); }
}

fn status() -> string {
  if over != "" { return over; }
  if ready() { return "Ready"; }
  return "";
}

label "Active-time battle";
