row {
  button "Attack" { attack(); }
  button "Potion" { potion(); }
  if !begun {
    button "Start" {
      begun = true;
      speed = 100;
    }
  }
  if over != "" { button "New game" { reset(); } }
}

// Party battle: tap a foe to target it; on each hero's turn Attack, or the Knight Defends, the
// Mage casts Fire on all foes, the Cleric Heals all heroes. Then the foes strike the first hero.
// icon: line 5 19 17 7 line 7 13 11 17 line 14 4 20 10 dot 5 19 2
state names = ["Knight", "Mage", "Cleric"];
state hp = [30, 16, 20];
state full = [30, 16, 20];
state mp = [0, 12, 9];
state blows = [8, 3, 2];       // each hero's Attack
state foes = ["Orc", "Bat", "Slime"];
state foe = [34, 14, 22];
state hits = [6, 3, 4];
state tint = [2, 5, 6];
state turn = 0;                // the hero whose turn it is
state target = 0;
state guard = false;           // the Knight defends
state over = "";               // Victory or Defeat, once it ends

fn firstfoe() -> int {
  for i in 0..3 {
    if foe[i] > 0 { return i; }
  }
  return -1;
}

fn firsthero() -> int {
  for h in 0..3 {
    if hp[h] > 0 { return h; }
  }
  return -1;
}

// Each standing foe strikes the first hero standing; a defending Knight takes half.
fn strike() {
  for i in 0..3 {
    let h = firsthero();
    if foe[i] > 0 && h >= 0 {
      let d = hits[i];
      if h == 0 && guard { d = d / 2; }
      hp[h] = max(0, hp[h] - d);
    }
  }
}

// The next standing hero's turn; after the last, the foes strike and a new round begins.
fn advance() {
  for t in turn + 1..3 {
    if hp[t] > 0 {
      turn = t;
      return;
    }
  }
  strike();
  if firsthero() < 0 {
    over = "Defeat";
    return;
  }
  turn = firsthero();
}

// An action of the hero whose turn it is: 0 Attack, 1 Defend, 2 Fire, 3 Heal.
fn act(k: int) {
  if over != "" { return; }
  let h = turn;
  if k == 0 {
    foe[target] = max(0, foe[target] - blows[h]);
  } else if k == 1 {
    if h != 0 { return; }
  } else if k == 2 {
    if h != 1 || mp[1] < 4 { return; }
    mp[1] -= 4;
    for i in 0..3 { foe[i] = max(0, foe[i] - 6); }
  } else {
    if h != 2 || mp[2] < 3 { return; }
    mp[2] -= 3;
    for j in 0..3 {
      if hp[j] > 0 { hp[j] = min(full[j], hp[j] + 10); }
    }
  }
  if h == 0 { guard = k == 1; }
  if firstfoe() < 0 {
    over = "Victory";
    return;
  }
  if foe[target] == 0 { target = firstfoe(); }
  advance();
}

fn aim(i: int) {
  if over == "" && foe[i] > 0 { target = i; }
}

fn reset() {
  for h in 0..3 { hp[h] = full[h]; }
  mp[1] = 12;
  mp[2] = 9;
  foe[0] = 34;
  foe[1] = 14;
  foe[2] = 22;
  turn = 0;
  target = 0;
  guard = false;
  over = "";
}

fn now() -> string {
  if over != "" { return over; }
  return names[turn] + "'s turn";
}

// The foes in a row, 50 units each: a body while it stands, a ring round the target.
fn scene() {
  for i in 0..3 {
    if foe[i] > 0 {
      circle(i * 50 + 25, 30, 12 + hits[i], tint[i]);
      circle(i * 50 + 20, 26, 2, 9);
      circle(i * 50 + 30, 26, 2, 9);
      text(foes[i], i * 50 + 25, 54, 6, 9);
    }
  }
  if over == "" { ring(target * 50 + 25, 30, 22, 2, 11); }
  if over != "" { text(over, 75, 30, 14, 11); }
}

