// Castaway: the arrows (or a tap beside you) walk, chop trees for wood and eat berries; every
// action makes you hungrier. Build a raft from 5 wood and sail off before Hunger reaches 15.
// icon: loop 3 15 21 15 18 20 6 20 line 12 15 12 3 fill 12 4 19 12 12 12
state first = [4, 4, 4, 4, 4, 4, 4, 4,  4, 3, 2, 3, 3, 8, 2, 4,  4, 3, 3, 5, 3, 2, 3, 4,
               4, 2, 8, 3, 3, 3, 5, 4,  4, 3, 2, 3, 8, 2, 3, 4,  4, 4, 4, 4, 4, 4, 4, 4];
state map = [4, 4, 4, 4, 4, 4, 4, 4,  4, 3, 2, 3, 3, 8, 2, 4,  4, 3, 3, 5, 3, 2, 3, 4,
             4, 2, 8, 3, 3, 3, 5, 4,  4, 3, 2, 3, 8, 2, 3, 4,  4, 4, 4, 4, 4, 4, 4, 4];
// 8 x 6 squares, row by row, by color: 4 water, 3 sand, 2 tree, 8 rock, 5 berry bush
state px = 1;
state py = 1;
state wood = 0;
state hunger = 0;
state raft = false;
state over = "";             // Escaped or Game over, once it ends

// A step toward (dx, dy): walk, chop or eat; rocks and water (without a raft) stop you.
fn step(dx: int, dy: int) {
  if over != "" { return; }
  let i = (py + dy) * 8 + px + dx;
  let t = map[i];
  if t == 8 { return; }
  if t == 4 {
    if raft { over = "Escaped"; }
    return;
  }
  hunger += 1;
  if t == 2 {
    wood += 1;
    map[i] = 3;
  } else if t == 5 {
    hunger = max(0, hunger - 8);
    map[i] = 3;
  } else {
    px += dx;
    py += dy;
  }
  if hunger >= 15 { over = "Game over"; }
}

fn toward(c: int, r: int) {
  if abs(c - px) + abs(r - py) == 1 { step(c - px, r - py); }
}

fn build() {
  if over == "" && !raft && wood >= 5 {
    wood -= 5;
    raft = true;
  }
}

fn reset() {
  for i in 0..48 { map[i] = first[i]; }
  px = 1;
  py = 1;
  wood = 0;
  hunger = 0;
  raft = false;
  over = "";
}

// The map, 8 x 6 squares of 16 units, you in red.
fn scene() {
  let cells = [0; 48];
  for i in 0..48 { cells[i] = map[i]; }
  cells[py * 8 + px] = 1;
  pixels(cells, 0, 0, 8, 16);
  if over != "" { text(over, 64, 48, 14, 9); }
}

on key "left" { step(-1, 0); }
on key "right" { step(1, 0); }
on key "up" { step(0, -1); }
on key "down" { step(0, 1); }

