  circle(80, 90, 50, 3);
  line(60, 70, 64, 40, 3, 8);
  circle(64, 40, 8, 2);
  if fire > 0 {
    circle(100, 60, 6, 1);
    circle(100, 54, 3, 3);
  }
  if over != "" { text(over, 80, 20, 14, 11); }
}

