// The corners lie on a circle of 50 around the middle, the first at the top: corner i is at
// i * 360 / sides degrees, across by its sine and up by its cosine.
fn at(v: int) -> int { return 60 + v * 50 / 1000; }

fn side(a: int, b: int) {
  line(at(sin(a)), at(-cos(a)), at(sin(b)), at(-cos(b)), 2, 4);
}

