// Price compare: type a shop and its price in cents and press Add; it shows the best price and
// what it saves against the dearest. Remove takes an offer off.
// icon: line 3 21 21 21 loop 4 14 9 14 9 21 4 21 loop 15 7 20 7 20 21 15 21 line 5 4 8 9 11 4
state shops = [""; 0];
state prices = [0; 0];
state shop = "";
state price = "";

// The cheapest offer, the first of a tie; -1 with none.
fn best() -> int {
  let b = -1;
  for i in 0..len(prices) {
    if b < 0 || prices[i] < prices[b] { b = i; }
  }
  return b;
}

fn dearest() -> int {
  let d = 0;
  for i in 0..len(prices) { d = max(d, prices[i]); }
  return d;
}

fn summary() -> string {
  let b = best();
  if b < 0 { return "No prices yet"; }
  return "Best: " + shops[b] + " at " + prices[b];
}

fn saving() -> int {
  let b = best();
  if b < 0 { return 0; }
  return dearest() - prices[b];
}

