// Running pace: type the distance in km and the time in minutes and seconds; it shows the pace
// per km and what 10 km take at that pace.
// icon: ring 12 13 8 line 12 13 15 9 line 10 3 14 3 line 19 6 21 8
state km = "";
state mins = "";
state secs = "";

// Two digits: 5 is 05.
fn two(n: int) -> string {
  if n < 10 { return "0" + n; }
  return "" + n;
}

// Seconds as minutes and seconds: 330 is 5:30.
fn clock(s: int) -> string { return s / 60 + ":" + two(s % 60); }

// Seconds a km, rounded down; 0 without a distance.
fn pace() -> int {
  let d = parse(km, 0);
  if d <= 0 { return 0; }
  return (parse(mins, 0) * 60 + parse(secs, 0)) / d;
}

