// The kth number not called yet (from 0), as its square.
fn uncalled(k: int) -> int {
  let n = 0;
  for i in 0..75 {
    if marks[i] == 0 {
      if n == k { return i; }
      n += 1;
    }
  }
  return -1;
}

fn call() {
  if count >= 75 { return; }
  let i = uncalled(random(75 - count));
  marks[i] = 2;
  count += 1;
  last = i + 1;
}

