// Timetable maker: type the first bus's hour and minute and the minutes between buses; it
// lists every departure before midnight.
// icon: loop 3 4 21 4 21 21 3 21 line 3 9 21 9 line 7 13 17 13 line 7 17 17 17
state hour = "";
state minute = "";
state gap = "";

fn two(n: int) -> string {
  if n < 10 { return "0" + n; }
  return "" + n;
}

fn clock(m: int) -> string { return two(m / 60) + ":" + two(m % 60); }

fn first() -> int { return min(max(parse(hour, 0), 0), 23) * 60 + min(max(parse(minute, 0), 0), 59); }

fn step() -> int { return min(max(parse(gap, 0), 0), 1440); }

// How many leave before midnight: with no gap, just the first.
fn count() -> int {
  if step() == 0 { return 1; }
  return (1439 - first()) / step() + 1;
}

label "Timetable maker";
row { label "First bus hour"; input hour; }
row { label "Minute"; input minute; }
row { label "Every (min)"; input gap; }
label "Departures: " + count();
for i in 0..count() { label clock(first() + i * step()); }

