// Team balancer: type a player's name and skill (1 to 10) and press Add; the players are split
// into two teams of near equal skill, the strongest first.
// icon: line 12 4 12 20 line 5 20 19 20 line 4 8 20 8 loop 2 14 4 8 6 14 loop 18 14 20 8 22 14
state names = [""; 0];
state skills = [0; 0];
state side = [0; 0];      // each player's team: 1 Team A, 2 Team B
state order = [0; 0];     // the players in the order they joined a team
state name = "";
state skill = "";

// The next to join: the highest skill not yet on a team, the first added on a tie.
fn pick() -> int {
  let best = -1;
  for i in 0..len(skills) {
    if side[i] == 0 && (best < 0 || skills[i] > skills[best]) { best = i; }
  }
  return best;
}

fn split() {
  for i in 0..len(side) { side[i] = 0; }
  clear(order);
  let a = 0;
  let b = 0;
  for k in 0..len(skills) {
    let p = pick();
    push(order, p);
    if a <= b {
      side[p] = 1;
      a += skills[p];
    } else {
      side[p] = 2;
      b += skills[p];
    }
  }
}

fn total(t: int) -> int {
  let n = 0;
  for i in 0..len(skills) {
    if side[i] == t { n += skills[i]; }
  }
  return n;
}

fn players(t: int) -> string {
  let s = "";
  for i in 0..len(order) {
    if side[order[i]] == t {
      if s != "" { s = s + ", "; }
      s = s + names[order[i]];
    }
  }
  return s;
}

label "Team balancer";
row { label "Name"; input name; }
row { label "Skill 1-10"; input skill; }
button "Add" {
  let s = parse(skill, 0);
  if name != "" && s >= 1 && s <= 10 {
    push(names, name);
    push(skills, s);
    push(side, 0);
    split();
    name = "";
  }
}
label "Team A (" + total(1) + "): " + players(1);
label "Team B (" + total(2) + "): " + players(2);

// Timesheet: type the hours worked each weekday; it adds them up, finds overtime past 40 and
// the pay ($20 an hour, $30 for each overtime hour).
// icon: loop 4 3 20 3 20 21 4 21 line 8 8 16 8 line 8 12 16 12 line 8 16 13 16
state mon = "";
state tue = "";
state wed = "";
state thu = "";
state fri = "";
state days = ["Monday", "Tuesday", "Wednesday", "Thursday", "Friday"];

fn hours(s: string) -> int { return min(max(parse(s, 0), 0), 24); }

// Day i's hours, Monday first.
fn day(i: int) -> int {
  if i == 0 { return hours(mon); }
  if i == 1 { return hours(tue); }
  if i == 2 { return hours(wed); }
  if i == 3 { return hours(thu); }
  return hours(fri);
}

fn total() -> int {
  let n = 0;
  for i in 0..5 { n += day(i); }
  return n;
}

fn overtime() -> int { return max(0, total() - 40); }

fn longest() -> string {
  let best = 0;
  for i in 1..5 {
    if day(i) > day(best) { best = i; }
  }
  if day(best) == 0 { return "none"; }
  return days[best];
}

label "Timesheet";
row { label "Monday"; input mon; }
row { label "Tuesday"; input tue; }
row { label "Wednesday"; input wed; }
row { label "Thursday"; input thu; }
row { label "Friday"; input fri; }
label "Total: " + total() + " hours";
label "Overtime: " + overtime() + " hours";
label "Pay: $" + ((total() - overtime()) * 20 + overtime() * 30);
label "Longest: " + longest();

// Shift log: type a shift's start and end as 24-hour times (0900, 1730) and press Add; it shows
// each shift's length and the total. A shift that ends before it starts runs past midnight.
// icon: ring 12 12 9 line 12 6 12 12 16 15
state starts = [0; 0];    // minutes after midnight
state lengths = [0; 0];   // minutes
state from = "";
state till = "";

// A four-digit time in minutes after midnight, or -1 when it is no time.
fn minutes(s: string) -> int {
  let t = parse(s, -1);
  if t < 0 || t / 100 > 23 || t % 100 > 59 { return -1; }
  return t / 100 * 60 + t % 100;
}

fn two(n: int) -> string {
