// Each letter added, or taken away when a larger one follows it.
fn total() -> int {
  let n = 0;
  for i in 0..len(letters) {
    let v = value(letters[i]);
    if i + 1 < len(letters) && v < value(letters[i + 1]) {
      n -= v;
    } else {
      n += v;
    }
  }
  return n;
}

fn written() -> string {
  let s = "";
  for i in 0..len(letters) { s = s + letters[i]; }
  return s;
}

