// Towers of Hanoi: move the four discs from the left peg to the right one, a smaller disc always
// on a larger. Tap a peg to pick its top disc, then the peg to put it on.
// icon: line 12 4 12 20 line 3 21 21 21 fill 8 10 16 10 16 13 8 13 fill 6 15 18 15 18 18 6 18
state at = [0, 0, 0, 0];      // the peg of each disc, the smallest first
state pegs = ["Left", "Middle", "Right"];
state held = -1;              // the peg picked; -1 none
state moves = 0;

// The top disc of peg p, the smallest on it; -1 if it is empty.
fn top(p: int) -> int {
  for d in 0..4 {
    if at[d] == p { return d; }
  }
  return -1;
}

fn solved() -> bool {
  for d in 0..4 {
    if at[d] != 2 { return false; }
  }
  return true;
}

fn tap(p: int) {
  if solved() { return; }
  if held < 0 {
    if top(p) >= 0 { held = p; }
    return;
  }
  let d = top(held);
  let under = top(p);
  if p != held && (under < 0 || under > d) {
    at[d] = p;
    moves += 1;
  }
  held = -1;
}

// How high disc d sits: the larger discs under it on its peg.
fn level(d: int) -> int {
  let n = 0;
  for e in d + 1..4 {
    if at[e] == at[d] { n += 1; }
  }
  return n;
}

// Pegs 50 units apart, levels 20 units tall from the bottom; each disc 10 wider than the last.
fn scene() {
  for p in 0..3 { line(p * 50 + 25, 6, p * 50 + 25, 80, 2, 8); }
  for d in 0..4 {
    let w = 16 + d * 10;
    rect(at[d] * 50 + 25 - w / 2, (3 - level(d)) * 20 + 2, w, 16, d + 1);
  }
}

