// The top disc of peg p, the smallest on it; -1 if it is empty.
fn top(p: int) -> int {
  for d in 0..3 {
    if at[d] == p { return d; }
  }
  return -1;
}

fn solved() -> bool { return at[0] == 2 && at[1] == 2 && at[2] == 2; }

fn tap(p: int) {
  if held < 0 {
    if top(p) >= 0 { held = p; }
    return;
  }
  let d = top(held);
  if top(p) < 0 || top(p) > d {
    at[d] = p;
    moves += 1;
  }
  held = -1;
}

fn level(d: int) -> int {
  let n = 0;
  for e in d + 1..3 {
    if at[e] == at[d] { n += 1; }
  }
  return n;
}

// A board of 15 x 5 squares: the pegs in columns 2, 7 and 12, the discs 1, 3 and 5 squares
// wide stacked from the bottom row, and the picked peg's top disc lifted to the top row.
fn scene() {
  let b = [-1; 75];
  for p in 0..3 {
    for r in 1..5 { b[r * 15 + p * 5 + 2] = 8; }
