// Jumble: unscramble the word, type it and press Guess. Skip shows the answer and moves on.
// icon: fill 3 6 10 6 10 13 3 13 fill 14 11 21 11 21 18 14 18 line 6 16 6 20 17 20
state words = ["OXYGEN", "WIZARD", "QUIVER"];
state small = ["oxygen", "wizard", "quiver"];
state letters = ["O", "X", "Y", "G", "E", "N", "W", "I", "Z", "A", "R", "D",
                 "Q", "U", "I", "V", "E", "R"];
state scramble = "N E G Y X O";     // the word shown, its letters mixed up
state order = [0; 6];               // which of the word's letters goes where
state n = 0;                        // words shown before this one
state score = 0;
state guess = "";
state said = "";

// Mixes up the next word's letters, never leaving them all in place.
fn shuffle() {
  for i in 0..6 { order[i] = i; }
  for k in 0..5 {
    let i = 5 - k;
    let j = random(i + 1);
    let t = order[i];
    order[i] = order[j];
    order[j] = t;
  }
  if order[0] == 0 && order[1] == 1 && order[2] == 2 && order[3] == 3 && order[4] == 4 {
    order[0] = 1;
    order[1] = 0;
  }
  scramble = letters[(n % 3) * 6 + order[0]];
  for i in 1..6 { scramble = scramble + " " + letters[(n % 3) * 6 + order[i]]; }
}

fn next() {
  n += 1;
  guess = "";
  shuffle();
}

fn check() {
  if guess == words[n % 3] || guess == small[n % 3] {
    score += 1;
    said = "Correct!";
    next();
  } else {
    said = "Try again";
  }
}

