// Bowling scorecard: tap the pins each roll knocks down; X a strike, / a spare, - none. Each
// frame shows its running score once its bonus is known.
// icon: dot 8 16 5 dot 17 5 2 fill 15 9 19 9 21 15 19 21 15 21 13 15
state rolls = [0; 0];
state starts = [0; 0];      // where each frame begun starts in rolls
state marks = [""; 10];
state frame = 0;            // the frame being bowled; 10 when the game is over
state ball = 0;             // rolls in it so far
state up = 10;              // pins standing
state fresh = true;         // whether they were all just set up

fn sign(n: int) -> string {
  if fresh && n == 10 { return "X"; }
  if !fresh && n == up { return "/"; }
  if n == 0 { return "-"; }
  return "" + n;
}

fn roll(n: int) {
  if ball == 0 { push(starts, len(rolls)); }
  push(rolls, n);
  marks[frame] = marks[frame] + sign(n);
  up -= n;
  ball += 1;
  fresh = false;
  if up == 0 {
    up = 10;
    fresh = true;
  }
  if frame < 9 {
    if fresh || ball == 2 {
      frame += 1;
      ball = 0;
      up = 10;
      fresh = true;
    }
  } else if ball == 3 || (ball == 2 && !fresh && rolls[len(rolls) - 2] < 10) {
    frame = 10;
  }
}

// Frame f's score, -1 until its bonus is known.
fn value(f: int) -> int {
  let s = starts[f];
  let n = len(rolls);
  if rolls[s] == 10 || (s + 1 < n && rolls[s] + rolls[s + 1] == 10) {
    if s + 2 < n { return rolls[s] + rolls[s + 1] + rolls[s + 2]; }
    return -1;
  }
  if s + 1 < n { return rolls[s] + rolls[s + 1]; }
  return -1;
}

// The running score up to frame f, -1 if not yet known.
fn total(f: int) -> int {
  let s = 0;
  for k in 0..f + 1 {
    let v = value(k);
    if v < 0 { return -1; }
    s += v;
  }
  return s;
}

fn score() -> int {
  let s = 0;
  for f in 0..len(starts) {
    if total(f) >= 0 { s = total(f); }
  }
  return s;
}

fn line(f: int) -> string {
  if total(f) < 0 { return (f + 1) + ": " + marks[f]; }
  return (f + 1) + ": " + marks[f] + " " + total(f);
}

