// Bowling score: tap the pins each roll knocks down; a strike adds the next two rolls, a spare
// the next one.
// icon: dot 8 16 5 dot 17 5 2 fill 15 9 19 9 21 15 19 21 15 21 13 15
state rolls = [0; 0];
state frame = 1;          // 11 once the game is over
state ball = 0;           // rolls in this frame so far
state up = 10;            // pins standing

fn roll(n: int) {
  push(rolls, n);
  up -= n;
  ball += 1;
  if frame < 10 {
    if up == 0 || ball == 2 {
      frame += 1;
      ball = 0;
      up = 10;
    }
  } else {
    if up == 0 { up = 10; }
    if ball == 3 { frame = 11; }
    if ball == 2 {
      let a = rolls[len(rolls) - 2];
      if a < 10 && a + n < 10 { frame = 11; }
    }
  }
}

// The score of the frames whose bonus is known.
fn score() -> int {
  let s = 0;
  let i = 0;
  let n = len(rolls);
  for f in 0..10 {
    if i >= n { return s; }
    if rolls[i] == 10 {
      if i + 2 >= n { return s; }
      s += 10 + rolls[i + 1] + rolls[i + 2];
      i += 1;
    } else {
      if i + 1 >= n { return s; }
      if rolls[i] + rolls[i + 1] == 10 {
        if i + 2 >= n { return s; }
        s += 10 + rolls[i + 2];
      } else {
        s += rolls[i] + rolls[i + 1];
      }
      i += 2;
    }
  }
  return s;
}

label "Bowling";
