// Shut the box: Roll, then tap open tiles that add up to the roll to shut them. Shut them all;
// a roll no tiles can make ends the game. The dice are set for practice.
// icon: loop 2 7 22 7 22 17 2 17 line 7 7 7 17 line 12 7 12 17 line 17 7 17 17 fill 12 7 17 7 17 17 12 17
state dice = [4, 5, 6, 2, 3, 4, 5, 1, 2, 3, 6, 4];   // the rolls in order, two dice each
