// Knight's tour: tap any square to set the knight down, then jump it a knight's move at a time
// to squares it has not been on. Visit all 36. Undo takes a move back.
// icon: fill 7 21 18 21 18 18 16 9 13 4 9 4 4 11 6 13 11 11 8 18 7 18
state path = [0; 0];      // the squares visited, in order: row * 6 + column

// The move number of square i, 0 if not visited.
fn step(i: int) -> int {
  for k in 0..len(path) {
    if path[k] == i { return k + 1; }
  }
  return 0;
}

fn jump(a: int, b: int) -> bool {
  let dc = abs(a % 6 - b % 6);
  let dr = abs(a / 6 - b / 6);
  return (dc == 1 && dr == 2) || (dc == 2 && dr == 1);
}

// Whether the knight can jump to square i now.
fn open(i: int) -> bool {
  return len(path) > 0 && step(i) == 0 && jump(path[len(path) - 1], i);
}

fn left() -> int {
  let n = 0;
  for i in 0..36 {
    if open(i) { n += 1; }
  }
  return n;
}

fn tap(i: int) {
  if len(path) == 0 || open(i) { push(path, i); }
}

fn scene() {
  let b = [8; 36];
  for i in 0..36 {
    if open(i) { b[i] = 3; }
    if step(i) > 0 { b[i] = 2; }
  }
  if len(path) > 0 { b[path[len(path) - 1]] = 4; }
  pixels(b, 0, 0, 6, 20);
  for k in 0..len(path) { text(k + 1, path[k] % 6 * 20 + 10, path[k] / 6 * 20 + 10, 10, 9); }
}

