// Pipes: tap a tile to turn its pipe a quarter turn clockwise; water flows from the middle tile
// through pipes that meet. Fill all 25 tiles to win.
// icon: line 3 12 12 12 12 21 line 12 3 12 12 21 12 dot 12 12 3
state pipe = [2, 13, 10, 6, 8, 3, 7, 1, 7, 13, 5, 10, 4, 9, 1, 5, 9, 1, 3, 3, 9, 10, 5, 10, 6];
state first = [2, 13, 10, 6, 8, 3, 7, 1, 7, 13, 5, 10, 4, 9, 1, 5, 9, 1, 3, 3, 9, 10, 5, 10, 6];
state turns = 0;          // a pipe's openings: 1 up, 2 right, 4 down, 8 left

fn opens(i: int, side: int) -> bool { return (pipe[i] / side) % 2 == 1; }

// Whether water flows from tile i one step by side (and dx, dy) into its neighbour.
fn joins(i: int, side: int, back: int, dx: int, dy: int) -> bool {
  let x = i % 5 + dx;
  let y = i / 5 + dy;
  if x < 0 || x > 4 || y < 0 || y > 4 { return false; }
  return opens(i, side) && opens(y * 5 + x, back);
}

// The tiles water reaches from the middle, as a count, or whether tile t is one of them.
fn flood(t: int) -> int {
  let wet = [false; 25];
  let todo = [12];
  wet[12] = true;
  let k = 0;
  repeat 25 {
    if k < len(todo) {
      let i = todo[k];
      k += 1;
      if joins(i, 1, 4, 0, -1) && !wet[i - 5] { wet[i - 5] = true; push(todo, i - 5); }
      if joins(i, 2, 8, 1, 0) && !wet[i + 1] { wet[i + 1] = true; push(todo, i + 1); }
      if joins(i, 4, 1, 0, 1) && !wet[i + 5] { wet[i + 5] = true; push(todo, i + 5); }
      if joins(i, 8, 2, -1, 0) && !wet[i - 1] { wet[i - 1] = true; push(todo, i - 1); }
    }
  }
  if t >= 0 && !wet[t] { return 0; }
  return len(todo);
}

fn solved() -> bool { return flood(-1) == 25; }

fn turn(i: int) {
  if solved() { return; }
  pipe[i] = pipe[i] * 2 % 16 + pipe[i] / 8;
  turns += 1;
}

// Each tile's pipe, 20 units a tile: from its middle to each side it opens to.
fn scene() {
  for i in 0..25 {
    let cx = i % 5 * 20 + 10;
    let cy = i / 5 * 20 + 10;
    let ink = 8;
    if flood(i) > 0 { ink = 4; }
    if opens(i, 1) { line(cx, cy, cx, cy - 10, 4, ink); }
    if opens(i, 2) { line(cx, cy, cx + 10, cy, 4, ink); }
    if opens(i, 4) { line(cx, cy, cx, cy + 10, 4, ink); }
    if opens(i, 8) { line(cx, cy, cx - 10, cy, 4, ink); }
    circle(cx, cy, 3, ink);
  }
}

