if empty() { label "Board clear, you win!"; }

// Color lines: tap a ball, then an empty square it can reach, to move it. Five or more of a color
// in a line clear and score; any other move brings three new balls. A full board ends it.
// icon: dot 5 12 3 dot 12 12 3 dot 19 12 3 ring 12 12 9
state board = [0, 0, 0, 0, 0, 0, 0, 0, 0, 3, 4, 5, 0, 2, 1, 3, 4, 5, 4, 5, 0, 2, 0, 3, 0, 4, 3,
  0, 1, 3, 0, 4, 0, 0, 5, 0, 5, 2, 0, 3, 0, 2, 5, 0, 4, 2, 0, 4, 5, 3, 0, 4, 0, 3, 0, 5, 0, 0, 0,
  3, 0, 0, 0, 3, 0, 4, 0, 1, 0, 0, 0, 4, 1, 1, 1, 1, 0, 2, 0, 0, 5];
state first = [0, 0, 0, 0, 0, 0, 0, 0, 0, 3, 4, 5, 0, 2, 1, 3, 4, 5, 4, 5, 0, 2, 0, 3, 0, 4, 3,
  0, 1, 3, 0, 4, 0, 0, 5, 0, 5, 2, 0, 3, 0, 2, 5, 0, 4, 2, 0, 4, 5, 3, 0, 4, 0, 3, 0, 5, 0, 0, 0,
  3, 0, 0, 0, 3, 0, 4, 0, 1, 0, 0, 0, 4, 1, 1, 1, 1, 0, 2, 0, 0, 5];
state sel = -1;
state score = 0;
state made = 0;           // the new balls so far: the next one's color is made % 5 + 1

fn full() -> bool {
  for i in 0..81 {
    if board[i] == 0 { return false; }
  }
  return true;
}

// Whether a path of empty squares joins square a to the empty square b.
fn reach(a: int, b: int) -> bool {
  let seen = [false; 81];
  let todo = [a];
  seen[a] = true;
  let k = 0;
  repeat 81 {
    if k < len(todo) {
      let i = todo[k];
      k += 1;
      let near = [i - 9, i + 9, i - 1, i + 1];
      let ok = [i >= 9, i < 72, i % 9 > 0, i % 9 < 8];
      for d in 0..4 {
        let j = near[d];
        if ok[d] && j == b { return true; }
        if ok[d] && board[j] == 0 && !seen[j] {
          seen[j] = true;
          push(todo, j);
        }
      }
    }
  }
  return false;
}

// How many balls of square i's color lie next to it in a row, stepping dx, dy.
fn run(i: int, dx: int, dy: int) -> int {
  let n = 0;
  let cx = i % 9 + dx;
  let cy = i / 9 + dy;
  repeat 8 {
    if cx >= 0 && cx < 9 && cy >= 0 && cy < 9 && board[cy * 9 + cx] == board[i] {
      n += 1;
      cx += dx;
      cy += dy;
    } else {
      cx = -9;
    }
  }
  return n;
}

// Clears every line of five or more through square i; whether any cleared.
fn lines(i: int) -> bool {
  let dxs = [1, 0, 1, 1];
  let dys = [0, 1, 1, -1];
  let gone = [false; 81];
  let n = 0;
  for d in 0..4 {
    let a = run(i, dxs[d], dys[d]);
    let b = run(i, -dxs[d], -dys[d]);
    if a + b >= 4 {
      for k in 0..a + b + 1 {
        gone[i + (k - b) * (dys[d] * 9 + dxs[d])] = true;
      }
    }
  }
  for j in 0..81 {
    if gone[j] {
      board[j] = 0;
      n += 1;
    }
  }
  score += n * 2;
  return n > 0;
}

// Three new balls, each on the first empty square, colored in turn.
fn spawn() {
  repeat 3 {
    let put = false;
    for i in 0..81 {
      if !put && board[i] == 0 {
        board[i] = made % 5 + 1;
        made += 1;
        put = true;
      }
    }
  }
}

fn tap(i: int) {
  if full() { return; }
  if board[i] > 0 {
    if i == sel { sel = -1; } else { sel = i; }
  } else if sel >= 0 && reach(sel, i) {
    board[i] = board[sel];
    board[sel] = 0;
    sel = -1;
    if !lines(i) { spawn(); }
  }
}

fn scene() {
  for i in 0..81 {
    let cx = i % 9 * 20 + 10;
    let cy = i / 9 * 20 + 10;
    ring(cx, cy, 10, 1, 7);
    if board[i] > 0 { circle(cx, cy, 7, board[i]); }
    if i == sel { ring(cx, cy, 9, 2, 11); }
  }
  if full() { text("Game over", 90, 90, 20, 11); }
}

