  0, 0, 0, 2, 3, 0, 0, 0, 0, 4, 0, 0, 2, 1, 3, 0, 0, 0, 0, 0, 4, 0];
state sel = -1;
state score = 0;

// Whether a path of empty squares joins square a to the empty square b.
fn reach(a: int, b: int) -> bool {
  let seen = [false; 81];
  let todo = [a];
  let k = 0;
  repeat 81 {
    if k < len(todo) {
      let i = todo[k];
      k += 1;
      let near = [i - 9, i + 9, i - 1, i + 1];
      let ok = [i >= 9, i < 72, i % 9 > 0, i % 9 < 8];
      for d in 0..4 {
        let j = near[d];
        if ok[d] && j == b { return true; }
        if ok[d] && board[j] == 0 && !seen[j] {
          seen[j] = true;
          push(todo, j);
        }
      }
    }
  }
  return false;
}

// How many balls of square i's color lie next to it in a row, stepping dx, dy.
fn run(i: int, dx: int, dy: int) -> int {
  let n = 0;
  let cx = i % 9 + dx;
  let cy = i / 9 + dy;
  repeat 8 {
