      n += 1;
      cx += dx;
      cy += dy;
    } else {
      cx = -9;
    }
  }
  return n;
}

// Clears every line of five or more through square i, a point a ball; whether any cleared.
fn lines(i: int) -> bool {
  let dxs = [1, 0, 1, 1];
  let dys = [0, 1, 1, -1];
  let gone = [false; 81];
  for d in 0..4 {
    let a = run(i, dxs[d], dys[d]);
    let b = run(i, -dxs[d], -dys[d]);
    if a + b >= 4 {
      for k in 0..a + b + 1 { gone[i + (k - b) * (dys[d] * 9 + dxs[d])] = true; }
    }
  }
  let n = 0;
  for j in 0..81 {
    if gone[j] {
      board[j] = 0;
      n += 1;
    }
  }
  score += n;
  return n > 0;
}

// Three new balls of random colors, each on the first empty square from a random one on.
fn drop() {
  repeat 3 {
    let k = random(81);
    let put = false;
    for j in 0..81 {
      let i = (k + j) % 81;
      if !put && board[i] == 0 {
        board[i] = 1 + random(5);
        put = true;
      }
    }
  }
}

fn tap(i: int) {
  if board[i] > 0 {
    sel = i;
  } else if sel >= 0 && reach(sel, i) {
    board[i] = board[sel];
    board[sel] = 0;
    sel = -1;
    if !lines(i) { drop(); }
  }
}

fn scene() {
  for i in 0..81 {
    if board[i] > 0 { circle(i % 9 * 20 + 10, i / 9 * 20 + 10, 8, board[i]); }
  }
  if sel >= 0 { ring(sel % 9 * 20 + 10, sel / 9 * 20 + 10, 10, 2, 11); }
}

