state words = ["FROG", "CAT", "DOG", "BEE", "OWL", "FOX"];
state found = [false; 6];
state lit = [false; 36];   // the squares of the words found
state sel = -1;            // the first letter tapped; -1 none

fn sign(v: int) -> int {
  if v > 0 { return 1; }
  if v < 0 { return -1; }
  return 0;
}

// The step from square a toward square b on a straight line; 0 when there is none.
fn step(a: int, b: int) -> int {
  let dc = b % 6 - a % 6;
  let dr = b / 6 - a / 6;
  if dc != 0 && dr != 0 && abs(dc) != abs(dr) { return 0; }
  return sign(dr) * 6 + sign(dc);
}

fn count() -> int {
  let n = 0;
  for k in 0..6 {
    if found[k] { n += 1; }
  }
