// Ludo for two: Roll, then tap the token to move (a 6 brings one in from the yard and rolls again).
// Round the board clockwise and home exactly; land on the other player to send it back.
// icon: loop 3 3 21 3 21 21 3 21 dot 8 8 3 dot 16 16 3 ring 12 12 3
state dice = [3, 6, 4, 6, 6, 6, 2, 5, 3, 1, 4, 6, 2, 6, 6, 5, 2, 6, 6, 3, 4, 1, 6, 3, 6, 6, 6, 6, 5,
  2, 2, 4, 1];
state next = 0;
state pos = [-1, -1, -1, -1];  // red's two tokens, then blue's: -1 in the yard, 0 to 23 on the way, 24 home
state turn = 1;           // 1 red, 2 blue
state roll = 0;
state waiting = false;    // whether a roll waits for a move
state winner = 0;

// The square of track place k, clockwise from the top left corner.
fn track(k: int) -> int {
  let t = k % 24;
  if t <= 6 { return t; }
  if t <= 12 { return (t - 6) * 7 + 6; }
  if t <= 18 { return 42 + 18 - t; }
  return (24 - t) * 7;
}

fn token(p: int, t: int) -> int { return p * 2 - 2 + t; }

fn at(p: int, t: int) -> int { return track(pos[token(p, t)] + (p - 1) * 12); }

fn yard(p: int, i: int) -> bool {
  if p == 1 { return i == 8 || i == 9; }
  return i == 40 || i == 39;
}

fn can(p: int, t: int) -> bool {
  let now = pos[token(p, t)];
  if now == 24 || (now < 0 && roll != 6) || now + roll > 24 { return false; }
  let to = 0;
  if now >= 0 { to = now + roll; }
  if to == 24 { return true; }
  let o = pos[token(p, 1 - t)];
  return !(o >= 0 && o < 24 && track(o + (p - 1) * 12) == track(to + (p - 1) * 12));
}

fn rolldie() {
  if winner > 0 || waiting { return; }
  roll = dice[next];
  next = (next + 1) % len(dice);
  if can(turn, 0) || can(turn, 1) { waiting = true; } else { turn = 3 - turn; }
}

fn move(t: int) {
  let k = token(turn, t);
  if pos[k] < 0 { pos[k] = 0; } else { pos[k] += roll; }
  if pos[k] < 24 {
    let o = 3 - turn;
    for u in 0..2 {
      if pos[token(o, u)] >= 0 && pos[token(o, u)] < 24 && at(o, u) == at(turn, t) { pos[token(o, u)] = -1; }
    }
  }
  waiting = false;
  if pos[token(turn, 0)] == 24 && pos[token(turn, 1)] == 24 {
    winner = turn;
  } else if roll != 6 {
    turn = 3 - turn;
  }
}

fn tap(i: int) {
  if !waiting { return; }
  for t in 0..2 {
    let p = pos[token(turn, t)];
    let here = (p < 0 && yard(turn, i)) || (p >= 0 && p < 24 && at(turn, t) == i);
    if waiting && here && can(turn, t) { move(t); }
  }
}

fn penned(p: int) -> int {
  let n = 0;
  for t in 0..2 {
    if pos[token(p, t)] < 0 { n += 1; }
  }
  return n;
}

fn scene() {
  let cells = [0; 49];
  for k in 0..24 { cells[track(k)] = 8; }
  if penned(1) >= 1 { cells[8] = 1; }
  if penned(1) == 2 { cells[9] = 1; }
  if penned(2) >= 1 { cells[40] = 4; }
  if penned(2) == 2 { cells[39] = 4; }
  for t in 0..2 {
    if pos[t] >= 0 && pos[t] < 24 { cells[at(1, t)] = 1; }
    if pos[2 + t] >= 0 && pos[2 + t] < 24 { cells[at(2, t)] = 4; }
  }
  pixels(cells, 0, 0, 7, 16);
}

fn status() -> string {
  if winner == 1 { return "Red wins"; }
  if winner == 2 { return "Blue wins"; }
  let who = "Red";
  if turn == 2 { who = "Blue"; }
  if waiting { return who + " to move"; }
  return who + " to roll";
}

label "Ludo";
label status();
canvas 112, 112, scene() { tap((y / 16) * 7 + x / 16); }
row {
  button "Roll" { rolldie(); }
  label "Rolled: " + roll;
}

// Ludo race: press Roll and your piece moves round the edge, clockwise. A 6 brings it out and rolls
// again; land on the other piece to knock it off; exactly back to your corner wins.
// icon: loop 3 3 21 3 21 21 3 21 dot 7 7 3 dot 17 17 3
state pos = [-1, -1];     // red's and blue's: -1 off the board, 0 to 23 the squares gone, 24 home
state turn = 0;           // 0 red, 1 blue
state die = 0;            // the last roll; the next is one more, after 6 back to 1
state winner = -1;

// The square of track place k, clockwise from the top left corner.
fn track(k: int) -> int {
  let t = k % 24;
  if t <= 6 { return t; }
  if t <= 12 { return (t - 6) * 7 + 6; }
  if t <= 18 { return 60 - t; }
  return (24 - t) * 7;
}

fn at(p: int) -> int { return track(pos[p] + p * 12); }

fn roll() {
  if winner >= 0 { return; }
  die = die % 6 + 1;
  let moved = false;
  if pos[turn] < 0 && die == 6 {
    pos[turn] = 0;
    moved = true;
  } else if pos[turn] >= 0 && pos[turn] + die <= 24 {
    pos[turn] += die;
    moved = true;
  }
  if moved && pos[turn] == 24 { winner = turn; }
  if moved && pos[turn] < 24 && pos[1 - turn] >= 0 && at(1 - turn) == at(turn) { pos[1 - turn] = -1; }
  if !(moved && die == 6) { turn = 1 - turn; }
}

fn scene() {
  let cells = [0; 49];
  for k in 0..24 { cells[track(k)] = 8; }
  if pos[0] >= 0 && pos[0] < 24 { cells[at(0)] = 1; }
  if pos[1] >= 0 && pos[1] < 24 { cells[at(1)] = 4; }
  pixels(cells, 0, 0, 7, 16);
}

fn status() -> string {
  if winner == 0 { return "Red wins!"; }
  if winner == 1 { return "Blue wins!"; }
  if turn == 0 { return "Red's roll"; }
  return "Blue's roll";
}

label "Ludo race";
canvas 112, 112, scene();
label status() + "   Die: " + die;
button "Roll" { roll(); }

// Columns: pieces of three jewels fall; left and right move them, up cycles the jewels, down drops.
// Three or more of a color in a line, across, down or diagonally, vanish. Press Start.
// icon: fill 9 2 15 2 15 8 9 8 fill 9 9 15 9 15 15 9 15 fill 9 16 15 16 15 22 9 22
state board = [0; 78];    // 6 a row, 13 rows: 0 empty, else a jewel's color
state pieces = [1, 2, 4, 1, 2, 4, 2, 4, 1, 4, 1, 2, 4, 2, 1, 5, 5, 3, 4, 4, 5, 6, 3, 2, 1, 5, 1,
  5, 1, 5, 1, 5, 1, 3, 3, 3];
state pc = [0, 0, 0];     // the falling piece, top to bottom
state px = 2;
state py = 0;             // the row of its top jewel
state next = 0;           // the next piece in the list
state speed = 0;          // 600 while a game runs
state score = 0;
state over = false;
state gone = [false; 78];

fn free(c: int, r: int) -> bool {
  return c >= 0 && c < 6 && r >= 0 && r < 13 && board[r * 6 + c] == 0;
}

fn fits(c: int, r: int) -> bool {
  return free(c, r) && free(c, r + 1) && free(c, r + 2);
}

fn spawn() {
  for k in 0..3 { pc[k] = pieces[next * 3 + k]; }
  next = (next + 1) % 12;
  px = 2;
  py = 0;
  if !fits(2, 0) {
    over = true;
    speed = 0;
  }
}

// Whether three squares from (c, r), a step (dc, dr) apart, hold one color.
fn three(c: int, r: int, dc: int, dr: int) -> bool {
  let e = c + 2 * dc;
  let f = r + 2 * dr;
  if e < 0 || e >= 6 || f < 0 || f >= 13 { return false; }
  let v = board[r * 6 + c];
  return v > 0 && board[(r + dr) * 6 + c + dc] == v && board[f * 6 + e] == v;
}

fn flag(c: int, r: int, dc: int, dr: int) {
  if three(c, r, dc, dr) {
    for k in 0..3 { gone[(r + k * dr) * 6 + c + k * dc] = true; }
  }
}

// Each column's jewels fall to the bottom.
fn fall() {
  for c in 0..6 {
    let to = 12;
    for k in 0..13 {
      let r = 12 - k;
      let v = board[r * 6 + c];
      if v > 0 {
        board[r * 6 + c] = 0;
        board[to * 6 + c] = v;
        to -= 1;
      }
    }
  }
}

// Lines vanish, the jewels above fall, and again, the chain's step multiplying the points.
fn settle() {
  let step = 1;
  repeat 30 {
    for i in 0..78 { gone[i] = false; }
    for i in 0..78 {
      flag(i % 6, i / 6, 1, 0);
      flag(i % 6, i / 6, 0, 1);
      flag(i % 6, i / 6, 1, 1);
      flag(i % 6, i / 6, 1, -1);
    }
    let n = 0;
    for i in 0..78 {
      if gone[i] {
        board[i] = 0;
        n += 1;
      }
    }
    score += 10 * n * step;
    step += 1;
    fall();
  }
}

fn land() {
  for k in 0..3 { board[(py + k) * 6 + px] = pc[k]; }
  settle();
  spawn();
}

fn start() {
  for i in 0..78 { board[i] = 0; }
  score = 0;
  over = false;
  next = 0;
  speed = 600;
  spawn();
}

fn shift(d: int) {
  if speed > 0 && fits(px + d, py) { px += d; }
}

fn cycle() {
  if speed > 0 {
    let b = pc[2];
    pc[2] = pc[1];
    pc[1] = pc[0];
    pc[0] = b;
  }
}

fn drop() {
  if speed > 0 {
    repeat 13 {
      if fits(px, py + 1) { py += 1; }
    }
    land();
  }
}

every speed {
  if fits(px, py + 1) { py += 1; } else { land(); }
}

on key "left" { shift(-1); }
on key "right" { shift(1); }
on key "up" { cycle(); }
on key "down" { drop(); }

fn scene() {
  let cells = [0; 78];
  for i in 0..78 { cells[i] = board[i]; }
  if speed > 0 {
    for k in 0..3 { cells[(py + k) * 6 + px] = pc[k]; }
  }
  pixels(cells, 0, 0, 6, 12);
  if over { text("Game over", 36, 60, 10, 11); }
}

