  rx = 0;
  ry = 6;
  gx = 7;
  way = -1;
  if lives == 0 {
    over = true;
    speed = 0;
  }
}

// The runner on its square: gold is taken (the last shows the escape ladder), the top of the
// board wins, the guard catches it.
fn arrive() {
  if map[at(rx, ry)] == 3 {
    map[at(rx, ry)] = 0;
    score += 100;
    if score == 300 {
      for r in 0..4 { map[at(0, r)] = 6; }
    }
  }
  if ry == 0 {
    won = true;
    speed = 0;
  }
  if ry == 3 && rx == gx { caught(); }
}

fn run(x: int, y: int) {
  let c = rx + x;
  let r = ry + y;
  if speed == 0 || !stands() || c < 0 || c > 9 || r < 0 || map[at(c, r)] == 8 { return; }
  if y < 0 && map[at(rx, ry)] != 6 { return; }
  rx = c;
  ry = r;
  arrive();
}

// Each 100 ms the runner falls a square if nothing holds it; every 3rd, the guard walks a square,
// turning back at the edge and at the ladder.
every speed {
  ticks += 1;
  if !stands() {
    ry += 1;
    arrive();
  }
  if speed > 0 && ticks % 3 == 0 {
    if gx + way < 0 || gx + way > 7 { way = -way; }
    gx += way;
    if ry == 3 && rx == gx { caught(); }
  }
}

