// Pengo: the arrows (or a tap beside the penguin) walk it; walking into an ice block pushes it, and
// it slides until something stops it, crushing the sno-bees in its way. Crush both to win. 3 lives.
// icon: fill 2 11 10 11 10 20 2 20 dot 16 15 5 dot 16 6 3
state ice = [false; 63];        // 9 x 7, square c + 9 * r: an ice block
state first = [3, 10, 14, 16, 21, 28, 30, 32, 34, 45, 47, 49, 51, 53, 54];   // the ice at Start
state bx = [0, 8];              // the sno-bees: square, and whether crushed
state by = [0, 0];
state alive = [true, true];
state px = 4;                   // the penguin
state py = 6;
state score = 0;
state lives = 3;
state speed = 0;                // 500 while a game runs, else 0
state won = false;
state over = false;

fn at(c: int, r: int) -> int { return r * 9 + c; }

fn on(c: int, r: int) -> bool { return c >= 0 && c < 9 && r >= 0 && r < 7; }

// The sno-bee on square (c, r), or -1.
fn bee(c: int, r: int) -> int {
  for k in 0..2 {
    if alive[k] && bx[k] == c && by[k] == r { return k; }
  }
  return -1;
}

fn sign(n: int) -> int {
  if n > 0 { return 1; }
  if n < 0 { return -1; }
  return 0;
}

fn home() {
  px = 4;
  py = 6;
  bx = [0, 8];
  by = [0, 0];
}

fn start() {
  for i in 0..63 { ice[i] = false; }
  for k in 0..len(first) { ice[first[k]] = true; }
  alive = [true, true];
  home();
  score = 0;
  lives = 3;
  won = false;
  over = false;
  speed = 500;
}

fn caught() {
  lives -= 1;
  home();
  if lives == 0 {
    over = true;
    speed = 0;
  }
}

// The block at (c, r) pushed by (dx, dy): it slides while the next square is free of ice and on
// the board, crushing sno-bees; one that cannot move breaks.
fn shove(c: int, r: int, dx: int, dy: int) {
  let x = c;
  let y = r;
  for step in 0..9 {
    if on(x + dx, y + dy) && !ice[at(x + dx, y + dy)] {
      x += dx;
      y += dy;
      let k = bee(x, y);
      if k >= 0 {
        alive[k] = false;
        score += 100;
      }
    }
  }
  ice[at(c, r)] = false;
  if x == c && y == r {
    score += 10;
  } else {
    ice[at(x, y)] = true;
  }
  if !alive[0] && !alive[1] {
    won = true;
    speed = 0;
  }
}

fn walk(dx: int, dy: int) {
  let x = px + dx;
  let y = py + dy;
  if speed == 0 || !on(x, y) { return; }
  if ice[at(x, y)] {
    shove(x, y, dx, dy);
  } else if bee(x, y) >= 0 {
    caught();
  } else {
    px = x;
    py = y;
  }
}

// Each sno-bee in turn a square toward the penguin: across if it can, else up or down; a catch
// ends the step.
every speed {
  let l = lives;
  for k in 0..2 {
    if lives == l && alive[k] {
      let sx = sign(px - bx[k]);
      let sy = sign(py - by[k]);
      let x = bx[k] + sx;
      let y = by[k] + sy;
      if sx != 0 && !ice[at(x, by[k])] && bee(x, by[k]) < 0 {
        bx[k] = x;
      } else if sy != 0 && !ice[at(bx[k], y)] && bee(bx[k], y) < 0 {
        by[k] = y;
      }
      if bx[k] == px && by[k] == py { caught(); }
    }
  }
}

