// Pengo: the arrows (or a tap) walk the penguin; walking into a block slides it until it hits
// something. Line up the three yellow diamonds to win; a sliding block crushes the sno-bee.
// icon: fill 12 3 20 12 12 21 4 12 dot 19 19 3
state ice = [false; 49];        // 7 x 7, square c + 7 * r
state gem = [false; 49];        // a diamond block
state first = [2, 6, 11, 13, 31, 40, 41];   // the ice at Start
state gems = [9, 18, 21];                  // the diamonds
state bx = 6;                   // the sno-bee, while alive
state by = 6;
state alive = true;
state px = 3;                   // the penguin
state py = 3;
state score = 0;
state lives = 3;
state speed = 0;                // 500 while a game runs, else 0
state won = false;
state over = false;

fn at(c: int, r: int) -> int { return r * 7 + c; }

fn on(c: int, r: int) -> bool { return c >= 0 && c < 7 && r >= 0 && r < 7; }

fn block(c: int, r: int) -> bool { return ice[at(c, r)] || gem[at(c, r)]; }

fn sign(n: int) -> int {
  if n > 0 { return 1; }
  if n < 0 { return -1; }
  return 0;
}

fn home() {
  px = 3;
  py = 3;
  bx = 6;
  by = 6;
}

fn start() {
  for i in 0..49 {
    ice[i] = false;
    gem[i] = false;
  }
  for k in 0..len(first) { ice[first[k]] = true; }
  for k in 0..3 { gem[gems[k]] = true; }
  alive = true;
  home();
  score = 0;
  lives = 3;
  won = false;
  over = false;
  speed = 500;
}

// Whether the three diamonds stand side by side in one row or one column.
fn lined() -> bool {
  for i in 0..49 {
    if gem[i] && i % 7 < 5 && gem[i + 1] && gem[i + 2] { return true; }
    if gem[i] && i < 35 && gem[i + 7] && gem[i + 14] { return true; }
  }
  return false;
}

// The block at (c, r) pushed by (dx, dy) slides while the next square is free of blocks and on the
// board, crushing the sno-bee; ice that cannot move breaks, a diamond stays.
fn shove(c: int, r: int, dx: int, dy: int) {
  let x = c;
  let y = r;
  for step in 0..7 {
    if on(x + dx, y + dy) && !block(x + dx, y + dy) {
      x += dx;
      y += dy;
      if alive && bx == x && by == y {
        alive = false;
        score += 100;
      }
    }
  }
  if x == c && y == r {
    ice[at(c, r)] = false;
  } else if gem[at(c, r)] {
    gem[at(c, r)] = false;
    gem[at(x, y)] = true;
  } else {
    ice[at(c, r)] = false;
    ice[at(x, y)] = true;
  }
  if lined() {
    score += 1000;
    won = true;
    speed = 0;
  }
}

fn caught() {
  lives -= 1;
  home();
  if lives == 0 {
    over = true;
    speed = 0;
  }
}

fn walk(dx: int, dy: int) {
  let x = px + dx;
  let y = py + dy;
  if speed == 0 || !on(x, y) { return; }
  if block(x, y) {
    shove(x, y, dx, dy);
  } else if alive && bx == x && by == y {
    caught();
  } else {
    px = x;
    py = y;
  }
}

// The sno-bee a square toward the penguin: across if it can, else up or down.
every speed {
  if alive {
    let sx = sign(px - bx);
    let sy = sign(py - by);
    if sx != 0 && !block(bx + sx, by) {
      bx += sx;
    } else if sy != 0 && !block(bx, by + sy) {
      by += sy;
    }
    if bx == px && by == py { caught(); }
  }
}

