fn start() {
  clear(tx);
  clear(ty);
  clear(tv);
  clear(bomb);
  steps = 0;
  thrown = 0;
  score = 0;
  missed = 0;
  over = false;
  speed = 100;
}

fn drop(i: int) {
  remove(tx, i);
  remove(ty, i);
  remove(tv, i);
  remove(bomb, i);
}

fn end() {
  over = true;
  speed = 0;
}

// Each step a throw every 4th step, then everything moves by its up-speed, which gravity takes
// 1 from; what falls past the bottom is gone, and a fruit gone is missed.
every speed {
  if steps % 4 == 0 {
    push(tx, cols[thrown % 8]);
    push(ty, 10);
    push(tv, 4);
    push(bomb, thrown % 4 == 3);
    thrown += 1;
  }
  steps += 1;
  let n = len(tx);
  for j in 0..n {
    let i = n - 1 - j;
    ty[i] -= tv[i];
    tv[i] -= 1;
    if ty[i] > 9 {
      if !bomb[i] { missed += 1; }
      drop(i);
    }
  }
  if missed >= 3 { end(); }
}

// A tap, or a drag crossing it, on square (c, r): what shows there is sliced.
fn slice(c: int, r: int) {
  let n = len(tx);
  for j in 0..n {
    let i = n - 1 - j;
    if speed > 0 && tx[i] == c && ty[i] == r {
      if bomb[i] {
        end();
      } else {
        score += 1;
        drop(i);
      }
    }
  }
}

fn scene() {
  let cells = [-1; 80];
  for i in 0..len(tx) {
    if ty[i] >= 0 && ty[i] <= 9 {
      cells[ty[i] * 8 + tx[i]] = 1;
      if bomb[i] { cells[ty[i] * 8 + tx[i]] = 5; }
    }
  }
  pixels(cells, 0, 0, 8, 12);
  if over { text("Game over", 48, 60, 14, 11); }
}

