// Sheepdog: the arrows (or a tap) move the dog; space or Bark barks, and sheep near it run away.
// Bark every sheep through the gate into the pen, on two levels, within 12 barks a level.
// icon: fill 3 10 13 10 13 16 3 16 dot 8 8 3 dot 18 15 3 line 18 18 18 21
state starts = [4, 5, 2, 6, 4, 5, 1, 6, 7, 6];  // the sheep of level 1, then level 2: column, row
state sx = [0; 0];              // the sheep still out
state sy = [0; 0];
state dx = 4;                   // the dog
state dy = 8;
state level = 1;
state barks = 12;
state playing = false;
state won = false;
state over = false;

fn pen(c: int, r: int) -> bool { return c >= 3 && c <= 5 && r <= 2; }

fn fence(c: int, r: int) -> bool { return ((c == 2 || c == 6) && r <= 3) || (r == 3 && (c == 3 || c == 5)); }

fn sign(n: int) -> int {
  if n > 0 { return 1; }
  if n < 0 { return -1; }
  return 0;
}

// The sheep on square (c, r), or -1.
fn sheep(c: int, r: int) -> int {
  for k in 0..len(sx) {
    if sx[k] == c && sy[k] == r { return k; }
  }
  return -1;
}

fn free(c: int, r: int) -> bool {
  return c >= 0 && c < 9 && r >= 0 && r < 9 && !fence(c, r) && sheep(c, r) < 0 && !(c == dx && r == dy);
}

fn load(n: int) {
  level = n;
  clear(sx);
  clear(sy);
  for i in 0..10 {
    if (n == 1 && i < 4) || (n == 2 && i >= 4) {
      if i % 2 == 0 { push(sx, starts[i]); } else { push(sy, starts[i]); }
    }
  }
  dx = 4;
  dy = 8;
  barks = 12;
}

fn start() {
  load(1);
  won = false;
  over = false;
  playing = true;
}

fn walk(x: int, y: int) {
  if playing && free(dx + x, dy + y) {
    dx += x;
    dy += y;
  }
}

// Sheep k runs a square straight away from the dog: both ways if it can, else across, else up
// or down; onto the pen, it is penned, off the board (column -9) until the bark is over.
fn run(k: int) {
  let mx = sign(sx[k] - dx);
  let my = sign(sy[k] - dy);
  let x = sx[k];
  let y = sy[k];
  if free(x + mx, y + my) {
    x += mx;
    y += my;
  } else if mx != 0 && free(x + mx, y) {
    x += mx;
  } else if my != 0 && free(x, y + my) {
    y += my;
  }
  sx[k] = x;
  sy[k] = y;
  if pen(x, y) { sx[k] = -9; }
}

fn bark() {
  if !playing { return; }
  barks -= 1;
  for k in 0..len(sx) {
    if abs(sx[k] - dx) <= 2 && abs(sy[k] - dy) <= 2 { run(k); }
  }
  let n = len(sx);
  for j in 0..n {
    let k = n - 1 - j;
    if sx[k] < 0 {
      remove(sx, k);
      remove(sy, k);
    }
  }
  if len(sx) == 0 && level == 1 {
    load(2);
  } else if len(sx) == 0 {
    won = true;
    playing = false;
  } else if barks == 0 {
    over = true;
    playing = false;
  }
}

on key "left" { walk(-1, 0); }
on key "right" { walk(1, 0); }
on key "up" { walk(0, -1); }
on key "down" { walk(0, 1); }
on key "space" { bark(); }

fn scene() {
  let cells = [-1; 81];
  for i in 0..81 {
    if pen(i % 9, i / 9) { cells[i] = 2; }
    if fence(i % 9, i / 9) { cells[i] = 8; }
  }
  for k in 0..len(sx) { cells[sy[k] * 9 + sx[k]] = 3; }
  cells[dy * 9 + dx] = 4;
  pixels(cells, 0, 0, 9, 10);
  if over { text("Game over", 45, 45, 12, 11); }
  if won { text("You win", 45, 45, 12, 11); }
}

