// Brandubh for two: New game sets the board; tap a piece of the side to move, then where it goes
// along its row or column. Sandwich enemies to take them; the king wins in a corner.
// icon: fill 5 18 19 18 17 12 19 6 15 10 12 5 9 10 5 6 7 12 line 5 21 19 21
state b = [0; 49];              // 0 empty, 1 attacker, 2 defender, 3 the king
state drs = [-1, 1, 0, 0];      // up, down, left, right
state dcs = [0, 0, -1, 1];
state turn = 1;                 // the side to move: 1 attackers, 2 defenders
state pick = -1;
state result = "";

fn side(v: int) -> int {
  if v == 3 { return 2; }
  return v;
}

fn corner(i: int) -> bool { return i == 0 || i == 6 || i == 42 || i == 48; }

fn to(i: int, k: int, n: int) -> int {
  let r = i / 7 + drs[k] * n;
  let c = i % 7 + dcs[k] * n;
  if r < 0 || r > 6 || c < 0 || c > 6 { return -1; }
  return r * 7 + c;
}

// Attackers on the middle row and column, defenders next to the king in the middle.
fn setup() {
  for i in 0..49 {
    b[i] = 0;
    let d = abs(i % 7 - 3) + abs(i / 7 - 3);
    if (i % 7 == 3 || i / 7 == 3) && d > 1 { b[i] = 1; }
    if d == 1 { b[i] = 2; }
  }
  b[24] = 3;
  turn = 1;
  pick = -1;
  result = "";
}

// Whether the piece at i may go to j: along a line of empty squares; the middle and the corners
// are the king's alone.
fn can(i: int, j: int) -> bool {
  for k in 0..4 {
    let ok = true;
    for n in 1..7 {
      let s = to(i, k, n);
      if ok && s >= 0 {
        if b[s] != 0 || (b[i] != 3 && (s == 24 || corner(s))) { ok = false; }
        if ok && s == j { return true; }
      }
    }
  }
  return false;
}

// Whether square s helps side `who` capture: its own piece, a corner, or the empty middle.
fn hostile(s: int, who: int) -> bool {
  return side(b[s]) == who || corner(s) || (s == 24 && b[24] == 0);
}

fn surrounded() -> bool {
  for i in 0..49 {
    if b[i] == 3 {
      for k in 0..4 {
        let s = to(i, k, 1);
        if s < 0 || (b[s] != 1 && s != 24) { return false; }
      }
      return true;
    }
  }
  return false;
}

// The piece moved to j takes each enemy next to it with a hostile square beyond.
fn capture(j: int) {
  for k in 0..4 {
    let s = to(j, k, 1);
    let t = to(j, k, 2);
    if t >= 0 && b[s] != 0 && b[s] != 3 && side(b[s]) != turn && hostile(t, turn) { b[s] = 0; }
  }
}

fn tap(j: int) {
  if result != "" { return; }
  if b[j] > 0 && side(b[j]) == turn {
    pick = j;
  } else if pick >= 0 && can(pick, j) {
    b[j] = b[pick];
    b[pick] = 0;
    pick = -1;
    capture(j);
    if b[j] == 3 && corner(j) { result = "Defenders win"; }
    if surrounded() { result = "Attackers win"; }
    turn = 3 - turn;
  }
}

// Corners and the middle gray; attackers red, defenders blue, the king yellow, the piece picked cyan.
fn scene() {
  let tints = [-1, 1, 4, 3];
  let cells = [-1; 49];
  for i in 0..49 {
    if corner(i) || i == 24 { cells[i] = 8; }
    if b[i] > 0 { cells[i] = tints[b[i]]; }
  }
  if pick >= 0 { cells[pick] = 6; }
  pixels(cells, 0, 0, 7, 20);
}

