// Volleyball for two: A and D move the left player, the arrows the right one. Where the ball comes
// down by you sets the hit: on you 3 up, beside you on the net side 4, on the far side 2.
// icon: ring 12 8 5 line 4 22 20 22 line 12 14 12 22 dot 5 18 2 dot 19 18 2
state lx = 2;                   // the players' columns on row 9: left 0 to 5, right 7 to 12
state rx = 10;
state bx = 2;                   // the ball: column, row, way across, up speed
state by = 8;
state dx = 1;
state vy = 3;
state last = 1;                 // the side that hit it last: 1 left, 2 right
state left = 0;
state right = 0;
state speed = 0;                // ms a step; 0 while no game runs
state result = "";

// The ball goes up from row 8 at column c, toward the far side from `who`.
fn hit(who: int, c: int, up: int) {
  bx = c;
  by = 8;
  vy = up;
  dx = 1;
  if who == 2 { dx = -1; }
  last = who;
}

fn start() {
  lx = 2;
  rx = 10;
  left = 0;
  right = 0;
  result = "";
  hit(1, 2, 3);
  speed = 200;
}

fn point(who: int) {
  if who == 1 { left += 1; } else { right += 1; }
  lx = 2;
  rx = 10;
  if left == 3 || right == 3 {
    result = "Left wins";
    if right == 3 { result = "Right wins"; }
    speed = 0;
  } else if who == 1 {
    hit(1, 2, 3);
  } else {
    hit(2, 10, 3);
  }
}

// Up 3 off the player's square, 4 off the square beside it nearer the net, 2 off the far one.
fn strength(p: int) -> int { return 3 + (bx - p) * (6 - p) / abs(6 - p); }

every speed {
  if bx + dx < 0 || bx + dx > 12 { dx = -dx; } else { bx += dx; }
  by -= vy;
  vy = max(-3, vy - 1);
  if bx == 6 && by >= 6 {
    point(3 - last);
  } else if by >= 9 && bx < 6 {
    if abs(bx - lx) <= 1 { hit(1, bx, strength(lx)); } else { point(2); }
  } else if by >= 9 {
    if abs(bx - rx) <= 1 { hit(2, bx, strength(rx)); } else { point(1); }
  }
}

fn moveLeft(d: int) {
  if speed > 0 { lx = min(5, max(0, lx + d)); }
}

fn moveRight(d: int) {
  if speed > 0 { rx = min(12, max(7, rx + d)); }
}

on key "a" { moveLeft(-1); }
on key "d" { moveLeft(1); }
on key "left" { moveRight(-1); }
on key "right" { moveRight(1); }

// The net gray, the left player blue, the right one red, the ball yellow (not shown above row 0).
fn scene() {
  let cells = [-1; 130];
  for r in 6..10 { cells[r * 13 + 6] = 8; }
  cells[117 + lx] = 4;
  cells[117 + rx] = 1;
  if speed > 0 && by >= 0 { cells[by * 13 + bx] = 3; }
  pixels(cells, 0, 0, 13, 10);
  if result != "" { text(result, 65, 30, 14, 11); }
}

label "Volleyball";
label "Left: " + left + "   Right: " + right;
canvas 130, 100, scene();
if speed == 0 { button "Start" { start(); } }

// Boxing: three opponents, each faster. Punch (space) while he winds up to land it and stop his
// punch; dodge (left) just before he punches. Beat all three without going down.
// icon: fill 7 6 15 4 19 8 19 15 15 18 8 18 5 14 fill 8 18 15 18 15 21 8 21
state me = 5;                   // my health
state opp = 5;                  // the opponent's
state round = 1;
state cycles = [8, 6, 4];       // each opponent's cycle in steps: guard, 2 of wind-up, a punch
state s = 0;                    // the steps of its cycle done
state dodge = 0;                // steps I still dodge
state speed = 0;                // ms a step; 0 while no fight runs
state result = "";
state mine = ["..44....", ".4444...", "..44..11", ".444411.", "4.44....", "..44....", ".4..4...", ".4..4..."];
state guard = ["....55..", "...5555.", "11..55..", ".115555.", "....55.5", "....55..", "...5..5.", "...5..5."];
state wind = ["33..55..", "33.5555.", "....55..", "..55555.", "....55.5", "....55..", "...5..5.", "...5..5."];

fn cycle() -> int { return cycles[round - 1]; }

fn winding() -> bool { return s >= cycle() - 2; }

fn start() {
  me = 5;
  opp = 5;
  round = 1;
  s = 0;
  dodge = 0;
  result = "";
  speed = 200;
}

// A punch lands only while he winds up: it stops his punch and his cycle starts over.
fn punch() {
  if speed > 0 && winding() {
    opp -= 1;
    s = 0;
    if opp == 0 && round == 3 {
      result = "You win";
      speed = 0;
    } else if opp == 0 {
      round += 1;
      opp = 5;
    }
  }
}

fn duck() {
  if speed > 0 { dodge = 2; }
}

every speed {
  s += 1;
  if s == cycle() {
    s = 0;
    if dodge == 0 { me -= 1; }
    if me == 0 {
      result = "You lose";
      speed = 0;
    }
  }
  dodge = max(0, dodge - 1);
}

on key "space" { punch(); }
on key "left" { duck(); }


fn mood() -> string {
  if winding() { return "Wind up"; }
  return "Guard";
}

// Me on the left, leaning away while I dodge; him on the right, his glove drawn back to wind up.
fn scene() {
  let lean = 0;
  if dodge > 0 { lean = 8; }
  sprite(mine, 12 - lean, 20, 8);
  let his = guard;
  if speed > 0 && winding() { his = wind; }
  sprite(his, 84, 20, 8);
}

label "Boxing";
label "You: " + me + "   Opponent: " + opp + "   Round: " + round;
