if speed > 0 { label mood(); }
if result != "" { label result; }
row {
  if speed == 0 { button "Start" { start(); } }
  button "Punch" { punch(); }
  button "Dodge" { duck(); }
}

// Slalom: left and right push the skier sideways (up to 2 columns a step); pass between the
// flags of each of the 6 gates. A missed gate costs 10. Finish in the lowest time.
// icon: line 5 3 5 21 line 19 3 19 21 fill 5 3 10 5 5 7 fill 19 3 14 5 19 7 dot 12 15 3
state gateRows = [8, 14, 20, 26, 32, 38];   // each gate's row on the hill, and its left flag
state lefts = [3, 0, 5, 2, 6, 1];
state sx = 5;                   // the skier's column, on row 2, and its sideways speed
state vx = 0;
state d = 0;                    // rows skied
state next = 0;                 // the next gate to reach the skier
state passed = 0;
state missed = 0;
state time = 0;
saved state best = 0;
state speed = 0;                // ms a step; 0 while no run goes on
state done = false;

fn start() {
  sx = 5;
  vx = 0;
  d = 0;
  next = 0;
  passed = 0;
  missed = 0;
  time = 0;
  done = false;
  speed = 200;
}

fn nudge(dx: int) {
  if speed > 0 { vx = max(-2, min(2, vx + dx)); }
}

// A step: sideways, then a row down the hill; a gate that reaches the skier is passed or missed.
every speed {
  sx += vx;
  if sx <= 0 || sx >= 10 {
    sx = max(0, min(10, sx));
    vx = 0;
  }
  d += 1;
  time += 1;
  if gateRows[next] == d + 2 {
    if sx > lefts[next] && sx < lefts[next] + 4 {
      passed += 1;
    } else {
      missed += 1;
      time += 10;
    }
    next += 1;
    if next == 6 {
      done = true;
      speed = 0;
      if best == 0 || time < best { best = time; }
    }
  }
}

on key "left" { nudge(-1); }
on key "right" { nudge(1); }

// The hill from row d down: the flags of the gates on it, blue, and the skier, red.
fn scene() {
  let cells = [-1; 132];
  for k in 0..6 {
    let r = gateRows[k] - d;
    if r >= 0 && r < 12 {
      cells[r * 11 + lefts[k]] = 4;
      cells[r * 11 + lefts[k] + 4] = 4;
    }
  }
  cells[22 + sx] = 1;
  pixels(cells, 0, 0, 11, 10);
  if done { text("Finished", 55, 80, 14, 11); }
}

label "Slalom";
label "Time: " + time + "   Gates: " + passed + "   Missed: " + missed + "   Best: " + best;
canvas 110, 120, scene() { if x / 10 < sx { nudge(-1); } else if x / 10 > sx { nudge(1); } }
if speed == 0 { button "Start" { start(); } }

// Curling against the computer: left and right pick the column, up and down the power, space
// throws. A stone that hits another stops and passes on what it had left. It throws first.
// icon: ring 12 12 9 ring 12 12 5 dot 12 12 2
state sheet = [0; 112];         // 7 x 16 squares: 0 empty, 1 my stone, 2 the computer's
state aim = 3;                  // my column, and how many rows my stone slides
state power = 12;
state mover = -1;               // the square of the stone sliding, and the rows it has left
state left = 0;
state thrown = 0;               // stones thrown this end, mine and its in turn
state end = 1;
state me = 0;
state cpu = 0;
state speed = 0;                // 100 while a game runs, else 0
state result = "";

fn at(c: int, r: int) -> int { return r * 7 + c; }

// How far square i is from the button at column 3, row 3, squared; 99 out of the house.
fn far(i: int) -> int {
  let dc = i % 7 - 3;
  let dr = i / 7 - 3;
  if abs(dc) > 2 || abs(dr) > 2 { return 99; }
  return dc * dc + dr * dr;
}

fn throw(who: int, c: int, rows: int) {
  mover = at(c, 15);
  sheet[mover] = who;
  left = rows;
  thrown += 1;
}

fn start() {
  for i in 0..112 { sheet[i] = 0; }
  aim = 3;
  power = 12;
  mover = -1;
  thrown = 0;
  end = 1;
  me = 0;
  cpu = 0;
  result = "";
  speed = 100;
  throw(2, 3, 12);
}

fn nearest(who: int) -> int {
  let d = 99;
  for i in 0..112 {
    if sheet[i] == who { d = min(d, far(i)); }
  }
  return d;
}

fn count(who: int, than: int) -> int {
  let n = 0;
  for i in 0..112 {
    if sheet[i] == who && far(i) < than { n += 1; }
  }
  return n;
}

// The end is over: the nearer side scores its stones nearer than the other's nearest.
fn score() {
  let dm = nearest(1);
  let dc = nearest(2);
  if dm < dc { me += count(1, dc); }
  if dc < dm { cpu += count(2, dm); }
  for i in 0..112 { sheet[i] = 0; }
  thrown = 0;
  if end == 2 {
    speed = 0;
    result = "Draw";
    if me > cpu { result = "You win"; }
    if cpu > me { result = "You lose"; }
  } else {
    end = 2;
  }
}

// A step: the sliding stone goes a row up, or hits the stone there, which slides on instead.
every speed {
  if mover < 0 { return; }
  if mover < 7 {
    sheet[mover] = 0;
    mover = -1;
  } else if sheet[mover - 7] > 0 {
    mover -= 7;
  } else {
    sheet[mover - 7] = sheet[mover];
    sheet[mover] = 0;
    mover -= 7;
    left -= 1;
    if left == 0 { mover = -1; }
  }
  if mover >= 0 { return; }
  if thrown == 6 { score(); }
  if speed > 0 && thrown % 2 == 0 { throw(2, 3, 12); }
}

fn fire() {
  if speed > 0 && mover < 0 && thrown % 2 == 1 { throw(1, aim, power); }
}

on key "left" { aim = max(0, aim - 1); }
on key "right" { aim = min(6, aim + 1); }
on key "down" { power = max(1, power - 1); }
on key "up" { power = min(15, power + 1); }
on key "space" { fire(); }

// The house gray around the cyan button; my stones red, the computer's blue; my next one waiting.
fn scene() {
  let tints = [-1, 1, 4];
  let cells = [-1; 112];
  for i in 0..112 {
    if far(i) < 99 { cells[i] = 8; }
    if sheet[i] > 0 { cells[i] = tints[sheet[i]]; }
  }
  if sheet[24] == 0 { cells[24] = 6; }
  if speed > 0 && mover < 0 { cells[at(aim, 15)] = 1; }
  pixels(cells, 0, 0, 7, 10);
  if result != "" { text(result, 35, 80, 12, 11); }
}

label "Curling";
label "End: " + end + "   You: " + me + "   Computer: " + cpu;
label "Stones: " + (3 - thrown / 2) + "   Power: " + power;
canvas 70, 160, scene() { aim = min(6, x / 10); }
row {
  if speed == 0 { button "Start" { start(); } }
  button "Throw" { fire(); }
}

// Gold Miner: the claw swings below the miner; down (or Drop) shoots it out. It grabs the first
// thing it meets and hauls it up, slower when heavy. Reach the target before time runs out.
// icon: line 12 3 12 12 line 7 12 17 12 line 7 12 7 17 line 17 12 17 17 fill 9 16 15 16 15 21 9 21
state aims = [-2, -1, 0, 1, 2, 1, 0, -1];   // the swing: columns across for each row down
state worth = [0, 10, 50, 100];             // nothing, a rock, gold, a diamond
state slow = [1, 3, 2, 1];                  // the steps a square back with each
state ground = [0; 150];                    // what lies on each square: 0 to 3
state aim = 0;                  // where in the swing the claw is
state k = 1;                    // how far out the claw is: its square is 7 + k * across, row k
state out = 0;                  // 0 swinging, 1 going out, 2 coming back
state load = 0;                 // what it holds
state held = 0;                 // steps since it last came a square back
state money = 0;
state level = 1;
state time = 40;
state steps = 0;
state speed = 0;                // ms a step; 0 while no game runs
state result = "";

fn at(c: int, r: int) -> int { return r * 15 + c; }

fn across() -> int { return aims[aim]; }

fn lay(c: int, r: int, what: int) { ground[at(c, r)] = what; }

fn setup() {
  for i in 0..150 { ground[i] = 0; }
  if level == 1 {
    lay(4, 3, 1);
    lay(7, 5, 2);
    lay(12, 5, 2);
    lay(1, 3, 3);
  } else {
    lay(7, 3, 2);
    lay(3, 4, 2);
    lay(9, 2, 1);
    lay(14, 7, 2);
    lay(11, 2, 3);
    lay(7, 6, 1);
  }
  aim = 0;
  k = 1;
  out = 0;
  time = 40;
  steps = 0;
}

fn start() {
  money = 0;
  level = 1;
  result = "";
  setup();
  speed = 200;
}

fn target() -> int { return level * 150 - 50; }

fn drop() {
  if speed > 0 && out == 0 {
    out = 1;
    load = 0;
  }
}

fn reel() {
  held += 1;
  if held < slow[load] { return; }
  held = 0;
  k -= 1;
  if k > 1 { return; }
  out = 0;
  money += worth[load];
  if money >= target() && level == 2 {
    result = "You win";
    speed = 0;
  } else if money >= target() {
    level = 2;
    setup();
  }
}

// A step: the clock first (a second every 5th step), then the claw: it swings, goes a square out
// (grabbing what is there), or comes back.
every speed {
  steps += 1;
  if steps % 5 == 0 {
    time -= 1;
    if time == 0 {
      result = "Game over";
      speed = 0;
      return;
    }
  }
  if out == 0 {
    aim = (aim + 1) % 8;
  } else if out == 1 {
    let c = 7 + (k + 1) * across();
    if c < 0 || c > 14 || k + 1 > 9 {
      out = 2;
      held = 0;
    } else {
      k += 1;
      if ground[at(c, k)] > 0 {
        load = ground[at(c, k)];
        ground[at(c, k)] = 0;
        out = 2;
        held = 0;
      }
    }
  } else {
    reel();
  }
}

on key "down" { drop(); }

// The miner gray on top, the gold yellow, rocks gray, diamonds cyan, the claw purple.
fn scene() {
  let tints = [-1, 8, 3, 6];
  let cells = [-1; 150];
  for i in 0..150 { cells[i] = tints[ground[i]]; }
  cells[7] = 8;
  cells[at(7 + k * across(), k)] = 5;
  pixels(cells, 0, 0, 15, 10);
  if result != "" { text(result, 75, 50, 16, 11); }
}

label "Gold Miner";
label "Level: " + level + "   Money: " + money + "   Target: " + target() + "   Time: " + time;
canvas 150, 100, scene();
row {
  if speed == 0 { button "Start" { start(); } }
  button "Drop" { drop(); }
}

// Lemmings: they drop in and walk; tap one to make it a blocker or a digger (pick with Block and
// Dig). Water drowns them. Save enough of the 5 on each of the 2 levels.
// icon: dot 12 5 3 line 12 8 12 15 line 12 10 7 13 line 12 10 17 13 line 12 15 8 21 line 12 15 16 21
state land = [0; 160];          // 0 air, 2 ground, 6 water
state xs = [0; 0];              // the lemmings out: square, way (1 right, -1 left) and what each
state ys = [0; 0];              // does: 0 walks, 1 blocks, 2 digs, 3 saved, 4 drowned
state ds = [0; 0];
state jobs = [0; 0];
state level = 1;
state saved = 0;
state blocks = 1;
state digs = 1;
state skill = 1;                // 1 Block, 2 Dig
state ex = 1;                   // the exit, and where they come in
state ey = 8;
state sx = 6;
state sy = 5;
state steps = 0;
state speed = 0;                // ms a step; 0 while no game runs
state result = "";

fn at(c: int, r: int) -> int { return r * 16 + c; }

fn setup() {
  for i in 0..160 { land[i] = 0; }
  if level == 1 {
    for c in 0..16 { land[at(c, 9)] = 2; }
    for c in 12..16 { land[at(c, 9)] = 6; }
    ex = 1;
    sx = 6;
    sy = 5;
  } else {
    for c in 2..16 {
      for r in 4..7 { land[at(c, r)] = 2; }
    }
    for c in 0..16 { land[at(c, 9)] = 2; }
    for c in 0..4 { land[at(c, 9)] = 6; }
    ex = 11;
    sx = 3;
    sy = 1;
  }
  clear(xs);
  clear(ys);
  clear(ds);
  clear(jobs);
  saved = 0;
  blocks = 1;
  digs = 1;
  steps = 0;
}

fn start() {
  level = 1;
  result = "";
  skill = 1;
  setup();
  speed = 200;
}

fn ground(c: int, r: int) -> bool {
  return r <= 9 && land[at(c, r)] == 2;
}

fn blocker(c: int, r: int) -> bool {
  for i in 0..len(xs) {
    if xs[i] == c && ys[i] == r && jobs[i] == 1 { return true; }
  }
  return false;
}

// One lemming's step: fall, dig, or walk (turning at ground, a blocker or the edge).
fn move(i: int) {
  let c = xs[i];
  let r = ys[i];
  if jobs[i] == 2 && ground(c, r + 1) && r < 9 {
    land[at(c, r + 1)] = 0;
    ys[i] = r + 1;
  } else if !ground(c, r + 1) {
    jobs[i] = 0;
    ys[i] = r + 1;
    if r + 1 > 9 || land[at(c, r + 1)] == 6 { jobs[i] = 4; }
  } else {
    jobs[i] = 0;
    let n = c + ds[i];
    if n < 0 || n > 15 || ground(n, r) || blocker(n, r) { ds[i] = -ds[i]; } else { xs[i] = n; }
  }
  if jobs[i] < 3 && xs[i] == ex && ys[i] == ey {
    jobs[i] = 3;
    saved += 1;
  }
}

fn busy() -> bool {
  for i in 0..len(xs) {
    if jobs[i] == 0 || jobs[i] == 2 { return true; }
  }
  return false;
}

every speed {
  steps += 1;
  for i in 0..len(xs) {
    if jobs[i] == 0 || jobs[i] == 2 { move(i); }
  }
  if len(xs) < 5 && steps % 4 == 1 {
    push(xs, sx);
    push(ys, sy);
    push(ds, 1);
    push(jobs, 0);
  }
  if len(xs) == 5 && !busy() {
    if saved < 4 {
      result = "Game over";
      speed = 0;
    } else if level == 2 {
      result = "You win";
      speed = 0;
    } else {
      level = 2;
      setup();
    }
  }
}

// A tap gives the skill to the first walking lemming on that square, if one is left.
fn tap(c: int, r: int) {
  if speed == 0 { return; }
  for i in 0..len(xs) {
    if xs[i] == c && ys[i] == r && jobs[i] == 0 && ground(c, r + 1) {
      if skill == 1 && blocks > 0 {
        jobs[i] = 1;
        blocks -= 1;
      } else if skill == 2 && digs > 0 {
        jobs[i] = 2;
        digs -= 1;
      }
      return;
    }
  }
}

fn name() -> string {
  if skill == 1 { return "Block"; }
  return "Dig";
}

// Ground green, water cyan, the exit purple; lemmings blue, blockers red, diggers yellow.
fn scene() {
  let cells = [-1; 160];
  for i in 0..160 {
    if land[i] > 0 { cells[i] = land[i]; }
  }
  cells[at(ex, ey)] = 5;
  let tints = [4, 1, 3];
  for i in 0..len(xs) {
    if jobs[i] < 3 { cells[at(xs[i], ys[i])] = tints[jobs[i]]; }
  }
  pixels(cells, 0, 0, 16, 10);
  if result != "" { text(result, 80, 20, 14, 11); }
}

label "Lemmings";
label "Level: " + level + "   Out: " + len(xs) + "   Saved: " + saved + "   Need: 4";
label "Skill: " + name() + "   Blocks: " + blocks + "   Digs: " + digs;
canvas 160, 100, scene() { tap(x / 10, y / 10); }
row {
  if speed == 0 { button "Start" { start(); } }
  button "Block" { skill = 1; }
  button "Dig" { skill = 2; }
}

// Lemonade stand: a week of weather; buy lemons, set the price, open the stand each day. Half
// the lemons left overnight go bad. The chart shows the cups sold each day.
// icon: fill 7 9 17 9 15 21 9 21 line 13 9 16 3 dot 18 6 2
state day = 1;
state money = 20;
state lemons = 0;
state price = 2;
state sold = [0; 0];                 // cups sold each day so far
state weather = ["Sunny", "Hot", "Cloudy", "Rainy", "Hot", "Sunny", "Cloudy"];
state over = false;

fn base(w: string) -> int {
  if w == "Hot" { return 30; }
  if w == "Sunny" { return 20; }
  if w == "Cloudy" { return 12; }
  return 6;
}

fn open() {
  if over { return; }
  let n = min(lemons, max(0, base(weather[day - 1]) - 4 * (price - 1)));
  lemons -= n;
  money += n * price;
  push(sold, n);
  lemons -= lemons / 2;
  if day == 7 { over = true; } else { day += 1; }
}

fn reset() {
  day = 1;
  money = 20;
  lemons = 0;
  price = 2;
  clear(sold);
  over = false;
}

// Seven bars of 20 units across a canvas 120 tall: 4 units a cup.
fn chart() {
  for d in 0..len(sold) { rect(d * 20 + 2, 120 - sold[d] * 4, 16, sold[d] * 4, 4); }
}

label "Lemonade stand";
label "Day " + day + "   " + weather[day - 1];
label "Money " + money + "   Lemons " + lemons + "   Price " + price;
if len(sold) > 0 { label "Sold " + sold[len(sold) - 1] + " cups"; }
if over { label "Game over: you made " + money; }
row {
  button "Buy lemons" {
    if !over && money >= 4 {
      money -= 4;
      lemons += 10;
    }
  }
  button "-" { if !over { price = max(1, price - 1); } }
  button "+" { if !over { price = min(5, price + 1); } }
  button "Open stand" { open(); }
}
canvas 140, 120, chart();
button "New game" { reset(); }

// Lemonade stand: tap Sell for a cup; hire helpers ($10) who sell one a second each; the big
// sign ($50) makes every cup $2.
// icon: fill 7 8 17 8 15 21 9 21 line 13 8 16 3
state money = 0;
state helpers = 0;
state cup = 1;              // dollars a cup: 2 once the sign is up

every 1000 { money += helpers * cup; }

label "Lemonade stand";
