// Diner rush: seat each customer from the line at a free table, take the order, bring the food;
// the slow ones walk off. Eight customers a shift.
// icon: ring 12 12 7 line 3 4 3 20 line 21 4 21 20
state queue = [0; 0];      // ms each customer in line has waited, first first
state seat = [0, 0, 0, 0]; // each table: 0 empty, 1 reading, 2 wants to order, 3 cooking,
                           // 4 food ready, 5 eating
state left = [0, 0, 0, 0]; // ms each table's step has left (wanting to order: ms waited)
state t = 0;               // ms since Start
state come = 0;            // customers come so far
state money = 0;
state served = 0;
state lost = 0;
state speed = 0;           // 500 while a shift runs
state over = false;

fn start() {
  clear(queue);
  for i in 0..4 {
    seat[i] = 0;
    left[i] = 0;
  }
  t = 0;
  come = 0;
  money = 0;
  served = 0;
  lost = 0;
  over = false;
  speed = 500;
}

// Table i moves on to step s, which lasts ms.
fn step(i: int, s: int, ms: int) {
  seat[i] = s;
  left[i] = ms;
}

fn tap(c: int, r: int) {
  if speed == 0 || r != 1 { return; }
  if seat[c] == 0 && len(queue) > 0 {
    remove(queue, 0);
    step(c, 1, 2000);
  } else if seat[c] == 2 {
    step(c, 3, 3000);
  } else if seat[c] == 4 {
    step(c, 5, 4000);
  }
}

every speed {
  t += 500;
  for i in 0..4 {
    if seat[i] == 2 {
      left[i] += 500;
      if left[i] >= 6000 { step(i, 0, 0); lost += 1; }
    } else if seat[i] == 1 || seat[i] == 3 || seat[i] == 5 {
      left[i] -= 500;
      if left[i] <= 0 {
        if seat[i] == 5 {
          step(i, 0, 0);
          money += 10;
          served += 1;
        } else {
          step(i, seat[i] + 1, 0);
        }
      }
    }
  }
  for k in 0..len(queue) {
    let j = len(queue) - 1 - k;
    queue[j] += 500;
    if queue[j] >= 10000 { remove(queue, j); lost += 1; }
  }
  if come < 8 && t == 1000 + come * 4000 {
    come += 1;
    push(queue, 0);
  }
  if come == 8 && served + lost == 8 {
    speed = 0;
    over = true;
  }
}

// The line on top, the tables below, squares of 30 units.
fn scene() {
  let b = [0, 0, 0, 0, 2, 2, 2, 2];
  let tint = [2, 3, 1, 4, 5, 6];
  for i in 0..len(queue) { b[i] = 8; }
  for i in 0..4 { b[4 + i] = tint[seat[i]]; }
  pixels(b, 0, 0, 4, 30);
  if over { text("Shift over", 60, 30, 12, 9); }
}

label "Diner rush";
label "Money " + money + "   Served " + served + "   Lost " + lost;
canvas 120, 60, scene() { tap(x / 30, y / 30); }
if speed == 0 { button "Start" { start(); } }

