// Troll bridge: walk between the places, search, buy and take what you need, beat the troll on
// the bridge and open the castle gate with the key.
// icon: fill 4 21 4 9 8 9 8 12 11 12 11 9 13 9 13 12 16 12 16 9 20 9 20 21
state places = ["Village", "Forest", "Cave", "Bridge", "Castle"];
state at = 0;
state gold = 3;
state health = 10;
state torch = false;
state sword = false;
state key = false;
state searched = false;
state troll = 9;            // the troll's HP; 0 once beaten
state news = "";            // what just happened
state over = "";            // You win or You died, once it is over

// The places beside place p: Village-Forest, Forest-Cave, Village-Bridge, Bridge-Castle.
fn beside(p: int, q: int) -> bool {
  let a = min(p, q);
  let b = max(p, q);
  return (a == 0 && b == 1) || (a == 1 && b == 2) || (a == 0 && b == 3) || (a == 3 && b == 4);
}

fn go(q: int) {
  news = "";
  if q == 4 && troll > 0 {
    news = "The troll blocks the way.";
  } else if q == 4 && !key {
    news = "The castle gate is locked.";
  } else {
    at = q;
    if q == 4 { over = "You win"; }
  }
}

fn search() {
  if searched {
    news = "Nothing more here.";
  } else {
    searched = true;
    gold += 4;
    news = "You find 4 gold.";
  }
}

// A blow at the troll: 3 with the sword, else 1; it hits back for 2 while it stands.
fn fight() {
  if sword { troll = max(0, troll - 3); } else { troll -= 1; }
  if troll == 0 {
    gold += 6;
    news = "The troll falls and drops 6 gold.";
  } else {
    health -= 2;
    news = "The troll hits you.";
    if health <= 0 {
      health = 0;
      over = "You died";
    }
  }
}

fn reset() {
  at = 0;
  gold = 3;
  health = 10;
  torch = false;
  sword = false;
  key = false;
  searched = false;
  troll = 9;
  news = "";
  over = "";
}

fn items() -> string {
  let s = "";
  if torch { s = s + " Torch"; }
  if sword { s = s + " Sword"; }
  if key { s = s + " Key"; }
  return s;
}

// The map: the five places as dots joined by paths, the one you are in ringed.
fn scene() {
  let xs = [30, 30, 30, 90, 140];
  let ys = [60, 32, 8, 60, 60];
  line(30, 8, 30, 60, 1, 10);
  line(30, 60, 140, 60, 1, 10);
  for p in 0..5 { circle(xs[p], ys[p], 4, 9); }
  ring(xs[at], ys[at], 7, 2, 11);
  if troll > 0 { circle(98, 52, 3, 2); }
}

label "Troll bridge";
label "You are at the " + places[at] + ".";
canvas 160, 70, scene();
