// Four rooms: walk Left and Right; the monster lets you past after three hits; take the key and
// open the chest with it.
// icon: loop 4 10 20 10 20 20 4 20 line 4 14 20 14 dot 12 17 2
state things = ["a locked chest", "a monster", "a key", "nothing"];
state room = 0;
state hits = 0;
state key = false;
state won = false;

fn walk(d: int) {
  if won { return; }
  if d > 0 && things[room] == "a monster" { return; }
  room = min(len(things) - 1, max(0, room + d));
}

fn hit() {
  hits += 1;
  if hits == 3 { things[room] = "nothing"; }
}

label "Four rooms";
