  if things[room] == "a key" { button "Take key" { key = true; things[room] = "nothing"; } }
  if things[room] == "a locked chest" && key && !won { button "Open chest" { won = true; } }
}

// Lane skirmish: hire Workers for gold, train Soldiers; they march right, fight the enemy's at
// the front and hit its base. Bring the enemy base from 5 HP to 0 before yours falls.
// icon: fill 3 20 3 10 7 10 7 14 9 14 9 20 line 11 15 21 15 fill 21 15 17 12 17 18
state mine = [0; 0];        // your soldiers' squares, front first
state myhp = [0; 0];
state foes = [0; 0];        // the enemy's, front first
state foehp = [0; 0];
state gold = 10;
state workers = 1;
state base = 5;
state enemy = 5;
state ticks = 0;
state speed = 0;            // ms a tick: 1000 while it runs
state over = "";            // Victory or Defeat

fn taken(p: int) -> bool {
  for i in 0..len(mine) { if mine[i] == p { return true; } }
  for i in 0..len(foes) { if foes[i] == p { return true; } }
  return false;
}

fn hire() {
  if over == "" && gold >= 6 {
    gold -= 6;
    workers += 1;
  }
}

fn train() {
  if over == "" && gold >= 4 && !taken(0) {
    gold -= 4;
    push(mine, 0);
    push(myhp, 4);
  }
}

// Your soldiers step right, front first; one stepping off the end hits the enemy base.
fn march() {
  let i = 0;
  repeat len(mine) {
    if mine[i] == 11 {
      enemy -= 1;
      remove(mine, i);
      remove(myhp, i);
    } else {
      if !taken(mine[i] + 1) { mine[i] += 1; }
      i += 1;
    }
  }
  i = 0;
  repeat len(foes) {
    if foes[i] == 0 {
      base -= 1;
      remove(foes, i);
      remove(foehp, i);
    } else {
      if !taken(foes[i] - 1) { foes[i] -= 1; }
      i += 1;
    }
  }
}

// The two front soldiers side by side trade a blow each.
fn fight() {
  if len(mine) == 0 || len(foes) == 0 || foes[0] - mine[0] != 1 { return; }
  myhp[0] -= 1;
  foehp[0] -= 1;
  if myhp[0] == 0 { remove(mine, 0); remove(myhp, 0); }
  if foehp[0] == 0 { remove(foes, 0); remove(foehp, 0); }
}

fn tick() {
  ticks += 1;
  gold += workers;
  march();
  fight();
  if ticks % 4 == 0 && !taken(11) {
    push(foes, 11);
    push(foehp, 3);
  }
  if enemy <= 0 {
    enemy = 0;
    over = "Victory";
  } else if base <= 0 {
    base = 0;
    over = "Defeat";
  }
  if over != "" { speed = 0; }
}

fn reset() {
  clear(mine);
  clear(myhp);
  clear(foes);
  clear(foehp);
  gold = 10;
  workers = 1;
  base = 5;
  enemy = 5;
  ticks = 0;
  over = "";
}

every speed { tick(); }

// The lane, 12 squares of 16 units between the two bases; each soldier's HP on it.
fn scene() {
  let cells = [-1; 12];
  for i in 0..len(mine) { cells[mine[i]] = 4; }
  for i in 0..len(foes) { cells[foes[i]] = 1; }
  rect(0, 0, 16, 24, 6);
  rect(208, 0, 16, 24, 5);
  pixels(cells, 16, 4, 12, 16);
  for i in 0..len(mine) { text(myhp[i], mine[i] * 16 + 24, 12, 8, 9); }
  for i in 0..len(foes) { text(foehp[i], foes[i] * 16 + 24, 12, 8, 9); }
  if over != "" { text(over, 112, 12, 12, 11); }
}

label "Lane skirmish";
label "Gold " + gold + "   Workers " + workers + "   Base " + base + "   Enemy " + enemy;
canvas 224, 24, scene();
row {
  button "Worker" { hire(); }
  button "Soldier" { train(); }
