// Metro: tap stations to lay the line through them, then Start: the train runs it back and forth
// and carries passengers to their stations. Deliver 10; 4 waiting at a station ends it.
// icon: line 4 6 20 6 20 18 4 18 dot 4 6 3 dot 20 6 3 dot 20 18 3 dot 4 18 3
state names = ["Ash", "Bay", "Cove", "Dale"];
state spots = [9, 14, 38, 33];   // their squares on the 8 x 6 board, row by row
state route = [0; 0];       // the stations of the line, in order
state at = 0;               // where along the line the train is
state dir = 1;
state waits = [0; 0];       // waiting passengers: the station each waits at
state wants = [0; 0];       // and the station each wants
state rides = [0; 0];       // the stations the riders want
state delivered = 0;
state steps = 0;
state speed = 0;
state over = "";

fn online(st: int) -> bool {
  for i in 0..len(route) { if route[i] == st { return true; } }
  return false;
}

fn station(sq: int) -> int {
  for st in 0..4 { if spots[st] == sq { return st; } }
  return -1;
}

fn tap(sq: int) {
  let st = station(sq);
  if speed == 0 && steps == 0 && over == "" && st >= 0 && !online(st) { push(route, st); }
}

fn waiting(st: int) -> int {
  let n = 0;
  for i in 0..len(waits) { if waits[i] == st { n += 1; } }
  return n;
}

// A step: the train on to the next station (back at the ends); its riders for it get off, then
// those waiting there for a station on the line get on (6 at most); then a passenger comes.
fn step() {
  steps += 1;
  if at + dir < 0 || at + dir >= len(route) { dir = -dir; }
  at += dir;
  let st = route[at];
  let i = 0;
  repeat len(rides) {
    if rides[i] == st { remove(rides, i); delivered += 1; } else { i += 1; }
  }
  i = 0;
  repeat len(waits) {
    if waits[i] == st && online(wants[i]) && len(rides) < 6 {
      push(rides, wants[i]);
      remove(waits, i);
      remove(wants, i);
    } else {
      i += 1;
    }
  }
  push(waits, (steps - 1) % 4);
  push(wants, (steps + 1) % 4);
  if delivered >= 10 {
    over = "You win";
  } else {
    for s in 0..4 { if waiting(s) >= 4 { over = "Overcrowded"; } }
  }
  if over != "" { speed = 0; }
}

fn reset() {
  clear(route);
  clear(waits);
  clear(wants);
  clear(rides);
  at = 0;
  dir = 1;
  delivered = 0;
  steps = 0;
  over = "";
}

every speed { step(); }

// The board, 8 x 6 squares of 16 units: the line drawn through its stations; stations yellow,
// green once on the line, blue where the train is; each station's waiting passengers as dots.
fn scene() {
  let cells = [-1; 48];
  for st in 0..4 {
    cells[spots[st]] = 3;
    if online(st) { cells[spots[st]] = 2; }
  }
  if steps > 0 || speed > 0 { cells[spots[route[at]]] = 4; }
  for i in 1..len(route) {
    let a = spots[route[i - 1]];
    let b = spots[route[i]];
    line(a % 8 * 16 + 8, a / 8 * 16 + 8, b % 8 * 16 + 8, b / 8 * 16 + 8, 2, 10);
  }
  pixels(cells, 0, 0, 8, 16);
  for st in 0..4 {
    for k in 0..min(4, waiting(st)) { circle(spots[st] % 8 * 16 + 3 + k * 3, spots[st] / 8 * 16 - 2, 1, 9); }
  }
  if over != "" { text(over, 64, 48, 14, 11); }
}

label "Metro";
label "Waiting " + len(waits) + "   Riders " + len(rides) + "   Delivered " + delivered;
canvas 128, 96, scene() { tap(y / 16 * 8 + x / 16); }
row {
  if steps == 0 && speed == 0 && over == "" {
    button "Clear" { clear(route); }
    button "Start" {
      if len(route) >= 2 {
        at = 0;
        speed = 1000;
      }
    }
  }
  if over != "" { button "New game" { reset(); } }
}

// Shuttle: drive the train with Forward and Back; it picks up and drops off passengers by
// itself. A passenger turns up every 2 seconds; 10 waiting ends it.
// icon: line 2 16 22 16 dot 4 16 2 dot 12 16 2 dot 20 16 2 loop 7 8 17 8 17 13 7 13
state at = 0;               // the train's station, 0 to 4
state waits = [0; 0];       // waiting passengers: their station
state wants = [0; 0];       // and where each wants to go
state rides = [0; 0];       // where the riders want to go
state delivered = 0;
state speed = 2000;
state over = false;

// The train stops: riders for here get off, everyone waiting here gets on.
fn stop() {
  let i = 0;
  repeat len(rides) {
    if rides[i] == at { remove(rides, i); delivered += 1; } else { i += 1; }
  }
  i = 0;
  repeat len(waits) {
    if waits[i] == at {
      push(rides, wants[i]);
      remove(waits, i);
      remove(wants, i);
    } else {
      i += 1;
    }
  }
}

fn drive(d: int) {
  if over || at + d < 0 || at + d > 4 { return; }
  at += d;
  stop();
}

// A passenger turns up at a station other than the train's, for another station.
every speed {
  let s = random(5);
  if s == at { s = (s + 1) % 5; }
  push(waits, s);
  push(wants, (s + 1 + random(4)) % 5);
  if len(waits) >= 10 {
    over = true;
    speed = 0;
  }
}

// The line: five stations along the bottom row, the train's one blue; above each, a red square
// for each passenger waiting there (four at most shown).
fn scene() {
  let cells = [-1; 25];
  let h = [0; 5];
  for i in 0..len(waits) {
    let s = waits[i];
    if h[s] < 4 {
      cells[(3 - h[s]) * 5 + s] = 1;
      h[s] += 1;
    }
  }
  for s in 0..5 { cells[20 + s] = 8; }
  cells[20 + at] = 4;
  pixels(cells, 0, 0, 5, 12);
}

label "Shuttle";
label "Waiting " + len(waits) + "   Riding " + len(rides) + "   Delivered " + delivered;
canvas 60, 60, scene();
if over { label "Game over"; }
row {
  button "Back" { drive(-1); }
  button "Forward" { drive(1); }
}

// Robot: build a program from Forward, Left and Right, then Run it: the robot follows it step by
// step to the green flag. A wall or the edge crashes it. Two levels.
// icon: loop 6 9 18 9 18 21 6 21 line 12 9 12 5 dot 12 4 2 line 9 15 15 15
state level = 1;
state prog = [0; 0];        // the commands: 0 Forward, 1 Left, 2 Right
state px = 0;
state py = 5;
state face = 0;             // 0 up, 1 right, 2 down, 3 left
state pc = 0;               // the next command to run
state speed = 0;            // ms a command: 500 while it runs
state msg = "";             // Crash, Try again, Level complete or You win
state dx = [0, 1, 0, -1];
state dy = [-1, 0, 1, 0];
state ways = ["up", "right", "down", "left"];
state letters = ["F", "L", "R"];

fn wall(x: int, y: int) -> bool {
  if level == 1 { return x == 1 && y >= 3; }
  return (x == 2 && y >= 1) || (x == 4 && y <= 4);
}

fn flag(x: int, y: int) -> bool {
  if level == 1 { return x == 3 && y == 2; }
  return x == 5 && y == 5;
}

fn done() -> bool { return msg == "Level complete" || msg == "You win"; }

fn add(c: int) {
  if speed == 0 && !done() && len(prog) < 20 { push(prog, c); }
}

fn home() {
  px = 0;
  py = 5;
  face = 0;
}

fn run() {
  if speed == 0 && !done() && len(prog) > 0 {
    home();
    pc = 0;
    msg = "";
    speed = 500;
  }
}

fn stop(why: string) {
  msg = why;
  speed = 0;
}

// The next command: a turn, or a step forward (into a wall or off the board: a crash).
fn step() {
  let c = prog[pc];
  pc += 1;
  if c == 1 { face = (face + 3) % 4; }
  if c == 2 { face = (face + 1) % 4; }
  if c == 0 {
    let nx = px + dx[face];
    let ny = py + dy[face];
    if nx < 0 || nx > 5 || ny < 0 || ny > 5 || wall(nx, ny) {
      stop("Crash");
      return;
    }
    px = nx;
    py = ny;
    if flag(px, py) {
      if level == 1 { stop("Level complete"); } else { stop("You win"); }
      return;
    }
  }
  if pc >= len(prog) { stop("Try again"); }
}

fn listing() -> string {
  let s = "";
  for i in 0..len(prog) { s = s + " " + letters[prog[i]]; }
  return s;
}

every speed { step(); }

// The board, 6 x 6 squares of 16 units: walls gray, the flag green, the robot blue with a dot on
// the side it faces.
fn scene() {
  let cells = [-1; 36];
  for i in 0..36 {
    if wall(i % 6, i / 6) { cells[i] = 8; }
    if flag(i % 6, i / 6) { cells[i] = 2; }
  }
  cells[py * 6 + px] = 4;
  pixels(cells, 0, 0, 6, 16);
  circle(px * 16 + 8 + dx[face] * 5, py * 16 + 8 + dy[face] * 5, 2, 9);
  if msg != "" { text(msg, 48, 48, 10, 11); }
}

label "Robot   Level " + level;
canvas 96, 96, scene();
label "Facing " + ways[face] + "   Commands " + len(prog) + ":" + listing();
row {
  button "Forward" { add(0); }
  button "Left" { add(1); }
  button "Right" { add(2); }
}
row {
  button "Undo" { if speed == 0 && len(prog) > 0 { remove(prog, len(prog) - 1); } }
  button "Clear" { if speed == 0 { clear(prog); } }
  button "Run" { run(); }
  if msg == "Level complete" {
    button "Next level" {
      level = 2;
      clear(prog);
      home();
      msg = "";
    }
  }
}

// Robot: add Forward, Turn left and Turn right to the list and Run it from the corner; drive off
// the grid and it crashes. Reach the flag in the top right.
// icon: loop 6 9 18 9 18 21 6 21 line 12 9 12 5 dot 12 4 2 line 9 15 15 15
state prog = [0; 0];        // 0 forward, 1 left, 2 right
state px = 0;
state py = 4;
state face = 0;             // 0 up, 1 right, 2 down, 3 left
state pc = 0;
state speed = 0;
state msg = "";
state names = ["Forward", "Left", "Right"];

fn step() {
  let c = prog[pc];
  pc += 1;
  if c == 1 { face = (face + 3) % 4; }
  if c == 2 { face = (face + 1) % 4; }
  if c == 0 {
    let dx = [0, 1, 0, -1];
    let dy = [-1, 0, 1, 0];
    let nx = px + dx[face];
    let ny = py + dy[face];
    if nx < 0 || nx > 4 || ny < 0 || ny > 4 {
      msg = "Crash!";
    } else {
      px = nx;
      py = ny;
    }
    if px == 4 && py == 0 { msg = "You reached the flag!"; }
  }
  if msg != "" || pc >= len(prog) { speed = 0; }
}

every speed { step(); }

fn scene() {
  let cells = [-1; 25];
  cells[4] = 2;
  cells[py * 5 + px] = 4;
  pixels(cells, 0, 0, 5, 20);
}

label "Robot";
canvas 100, 100, scene();
if msg != "" { label msg; }
label "Program:" + len(prog);
row {
  button "Forward" { if speed == 0 { push(prog, 0); } }
  button "Turn left" { if speed == 0 { push(prog, 1); } }
  button "Turn right" { if speed == 0 { push(prog, 2); } }
}
row {
  button "Clear" { if speed == 0 { clear(prog); } }
  button "Run" {
    if speed == 0 && len(prog) > 0 {
      px = 0;
      py = 4;
      face = 0;
      pc = 0;
      msg = "";
      speed = 400;
    }
  }
}

// Survivors: monsters close in from the edges; your weapon fires by itself at the nearest one.
// Walk (arrows) to pick up the gems they drop and level up. Last 60 seconds.
// icon: dot 12 12 3 line 12 5 12 2 line 12 19 12 22 line 5 12 2 12 line 19 12 22 12 ring 12 12 7
state hx = 4;
state hy = 4;
state mx = [0; 0];          // the monsters, oldest first
state my = [0; 0];
state gems = [false; 81];
state hp = 3;
state xp = 0;
state time = 0;
state spawned = 0;
state speed = 0;
state over = "";
state sx = [0, 8, 8, 0, 4, 8, 4, 0];   // where monsters come in, in turn
state sy = [0, 0, 8, 8, 0, 4, 8, 4];

fn level() -> int { return 1 + xp / 3; }

fn hurt() {
  hp -= 1;
  if hp <= 0 {
    hp = 0;
    over = "Game over";
    speed = 0;
  }
}

fn walk(dx: int, dy: int) {
  if speed == 0 { return; }
  let nx = hx + dx;
  let ny = hy + dy;
  if nx < 0 || nx > 8 || ny < 0 || ny > 8 { return; }
  hx = nx;
  hy = ny;
  let i = 0;
  repeat len(mx) {
    if mx[i] == hx && my[i] == hy {
      remove(mx, i);
      remove(my, i);
      hurt();
    } else {
      i += 1;
    }
  }
  if gems[hy * 9 + hx] {
    gems[hy * 9 + hx] = false;
    xp += 1;
  }
}

// The weapon: the nearest monster within 2 squares (the oldest of the nearest) falls, leaving a gem.
fn fire() {
  let best = -1;
  let near = 3;
  for i in 0..len(mx) {
    let d = max(abs(mx[i] - hx), abs(my[i] - hy));
    if d < near {
      near = d;
      best = i;
    }
  }
  if best >= 0 {
    gems[my[best] * 9 + mx[best]] = true;
    remove(mx, best);
    remove(my, best);
  }
}

fn tick() {
  time += 1;
  let i = 0;
  repeat len(mx) {
    let ax = hx - mx[i];
    let ay = hy - my[i];
    if abs(ax) > abs(ay) { mx[i] += ax / abs(ax); } else { my[i] += ay / abs(ay); }
    if mx[i] == hx && my[i] == hy {
      remove(mx, i);
      remove(my, i);
      hurt();
    } else {
      i += 1;
    }
  }
  if over != "" { return; }
  if time % 2 == 0 || level() >= 2 { fire(); }
  if time % 2 == 0 {
    push(mx, sx[spawned % 8]);
    push(my, sy[spawned % 8]);
    spawned += 1;
  }
  if time >= 60 {
    over = "You survived";
    speed = 0;
  }
}

fn reset() {
  hx = 4;
  hy = 4;
  clear(mx);
  clear(my);
  for k in 0..81 { gems[k] = false; }
  hp = 3;
  xp = 0;
  time = 0;
  spawned = 0;
  over = "";
}

every speed { tick(); }
on key "left" { walk(-1, 0); }
on key "right" { walk(1, 0); }
on key "up" { walk(0, -1); }
on key "down" { walk(0, 1); }

// The arena, 9 x 9 squares of 12 units: gems yellow, monsters red, you blue.
fn scene() {
  let cells = [-1; 81];
  for k in 0..81 {
    if gems[k] { cells[k] = 3; }
  }
  for k in 0..len(mx) { cells[my[k] * 9 + mx[k]] = 1; }
  cells[hy * 9 + hx] = 4;
  pixels(cells, 0, 0, 9, 12);
  if over != "" { text(over, 54, 54, 14, 11); }
}

label "Survivors";
label "Time " + time + "   HP " + hp + "   XP " + xp + "   Level " + level();
canvas 108, 108, scene();
row {
  button "Left" { walk(-1, 0); }
  button "Up" { walk(0, -1); }
  button "Down" { walk(0, 1); }
  button "Right" { walk(1, 0); }
  if speed == 0 && over == "" && time == 0 { button "Start" { speed = 1000; } }
  if over != "" { button "New game" { reset(); } }
}

// Swarm: a monster comes in every second; your weapon zaps the nearest every 2 seconds. Walk with
// the arrows; each one that reaches you takes a heart.
// icon: dot 12 12 3 dot 4 4 2 dot 20 5 2 dot 5 20 2 dot 19 19 2 line 12 12 18 6
state hx = 6;               // you, on a 13 x 13 field
state hy = 6;
state mx = [0; 0];
state my = [0; 0];
state hearts = 5;
state kills = 0;
state secs = 0;
state speed = 0;

fn walk(dx: int, dy: int) {
  if speed > 0 {
    hx = min(12, max(0, hx + dx));
    hy = min(12, max(0, hy + dy));
  }
}

// A second: the monsters step toward you (one that reaches you takes a heart), every 2nd second
// the nearest is zapped, and a new one comes in at a random place on the edge.
fn tick() {
  secs += 1;
  let i = 0;
  repeat len(mx) {
    let ax = hx - mx[i];
    let ay = hy - my[i];
    if abs(ax) > abs(ay) { mx[i] += ax / abs(ax); } else if ay != 0 { my[i] += ay / abs(ay); }
    if mx[i] == hx && my[i] == hy {
      remove(mx, i);
      remove(my, i);
      hearts -= 1;
    } else {
      i += 1;
    }
  }
  if secs % 2 == 0 && len(mx) > 0 {
    let best = 0;
    for j in 0..len(mx) {
      if abs(mx[j] - hx) + abs(my[j] - hy) < abs(mx[best] - hx) + abs(my[best] - hy) { best = j; }
    }
    remove(mx, best);
    remove(my, best);
    kills += 1;
  }
  let p = random(13);
  let side = random(4);
  let xs = [p, 12, p, 0];
  let ys = [0, p, 12, p];
  push(mx, xs[side]);
  push(my, ys[side]);
  if hearts <= 0 {
    hearts = 0;
    speed = 0;
  }
}

every speed { tick(); }
on key "left" { walk(-1, 0); }
on key "right" { walk(1, 0); }
on key "up" { walk(0, -1); }
on key "down" { walk(0, 1); }

fn scene() {
  let cells = [-1; 169];
  for i in 0..len(mx) { cells[my[i] * 13 + mx[i]] = 1; }
  cells[hy * 13 + hx] = 4;
  pixels(cells, 0, 0, 13, 8);
}

label "Swarm";
label "Hearts " + hearts + "   Kills " + kills + "   Lasted " + secs + " s";
canvas 104, 104, scene();
if hearts == 0 { label "Game over"; }
if speed == 0 && hearts > 0 && secs == 0 { button "Start" { speed = 1000; } }

