// Days between: type two dates as day, month and year; it shows the days from the first to the
// second, negative when the second is earlier.
// icon: loop 3 5 21 5 21 21 3 21 line 3 10 21 10 line 8 2 8 7 line 16 2 16 7 line 7 15 17 15 line 14 12 17 15 14 18
state d1 = "";
state m1 = "";
state y1 = "";
state d2 = "";
state m2 = "";
state y2 = "";

fn leap(yr: int) -> bool { return yr % 4 == 0 && (yr % 100 != 0 || yr % 400 == 0); }

fn month_days(mon: int, yr: int) -> int {
  if mon == 2 {
    if leap(yr) { return 29; }
    return 28;
  }
  if mon == 4 || mon == 6 || mon == 9 || mon == 11 { return 30; }
  return 31;
}

fn real(day: int, mon: int, yr: int) -> bool {
  return yr >= 1 && yr <= 9999 && mon >= 1 && mon <= 12 && day >= 1 && day <= month_days(mon, yr);
}

// The days from 1 January of year 1 to this date.
fn serial(day: int, mon: int, yr: int) -> int {
  let p = yr - 1;
  let n = p * 365 + p / 4 - p / 100 + p / 400;
  for k in 1..mon { n += month_days(k, yr); }
  return n + day;
}

fn shown() -> string {
  let a = parse(d1, 0);
  let b = parse(m1, 0);
  let c = parse(y1, 0);
  let e = parse(d2, 0);
  let f = parse(m2, 0);
  let g = parse(y2, 0);
  if !real(a, b, c) || !real(e, f, g) { return "Not a date"; }
  return "Days: " + (serial(e, f, g) - serial(a, b, c));
}

