fn leap(yr: int) -> bool { return yr % 4 == 0 && (yr % 100 != 0 || yr % 400 == 0); }

fn month_days(mon: int, yr: int) -> int {
  if mon == 2 {
    if leap(yr) { return 29; }
    return 28;
  }
  if mon == 4 || mon == 6 || mon == 9 || mon == 11 { return 30; }
  return 31;
}

// Whether 8 digits YYYYMMDD name a real date.
fn real(n: int) -> bool {
  let yr = n / 10000;
  let mon = n / 100 % 100;
  let day = n % 100;
  return yr >= 1 && mon >= 1 && mon <= 12 && day >= 1 && day <= month_days(mon, yr);
}

// The days from 1 January of year 1 to the date YYYYMMDD.
fn serial(n: int) -> int {
  let yr = n / 10000;
  let p = yr - 1;
  let t = p * 365 + p / 4 - p / 100 + p / 400;
  for k in 1..n / 100 % 100 { t += month_days(k, yr); }
  return t + n % 100;
}

fn apart() -> int { return abs(serial(parse(second, 0)) - serial(parse(first, 0))); }

fn ok() -> bool { return real(parse(first, 0)) && real(parse(second, 0)); }

