// row in the top row to win.
// icon: fill 3 17 21 17 21 22 3 22 fill 6 11 18 11 18 16 6 16 fill 9 5 15 5 15 10 9 10
state board = [0; 70];    // 7 x 10 squares: 4 a stacked block
state at = 9;             // the moving row: its row, its left column, its width and its way
state bx = 0;
state wide = 3;
state dir = 1;
state height = 0;
state speed = 0;          // ms a move; 0 between games
state said = "";

fn start() {
  board = [0; 70];
  at = 9;
  bx = 0;
  wide = 3;
  dir = 1;
  height = 0;
  said = "";
  speed = 200;
}

every speed {
  if dir > 0 && bx + wide >= 7 { dir = -1; }
  if dir < 0 && bx <= 0 { dir = 1; }
  bx += dir;
}

// Stops the row: what has a block under it stays; a new row starts above, or the game ends.
fn stop() {
  if speed == 0 { return; }
  let kept = 0;
  for c in bx..bx + wide {
    if at == 9 || board[(at + 1) * 7 + c] == 4 {
      board[at * 7 + c] = 4;
      kept += 1;
    }
  }
  if kept == 0 {
    said = "Game over";
    speed = 0;
    return;
  }
  height += 1;
  if at == 0 {
    said = "You win";
    speed = 0;
    return;
  }
  at -= 1;
  bx = 0;
  wide = kept;
  dir = 1;
}

