// Chutes and ladders for Red and Blue: Roll moves the player whose turn it is; climb ladders, slide
// down chutes; a 6 rolls again; first to land on 100 wins (past it bounces back).
// icon: line 6 21 6 3 line 13 21 13 3 line 6 8 13 8 line 6 14 13 14 line 18 4 21 10 15 15 19 21
state from = [1, 4, 9, 21, 28, 36, 51, 71, 80, 16, 47, 49, 56, 62, 64, 87, 93, 95, 98];
state to = [38, 14, 31, 42, 84, 44, 67, 91, 100, 6, 26, 11, 53, 19, 60, 24, 73, 75, 78];
state dice = [2, 1, 1, 5, 6, 6, 5, 5, 4, 5];   // the rolls, in turn, over and over
state next = 0;
state at = [0, 0];        // Red's square, Blue's: 0 off the board
state turn = 0;           // 0 Red, 1 Blue
state rolled = 0;
state winner = -1;

fn name(p: int) -> string {
  if p == 0 { return "Red"; }
  return "Blue";
}

// Where a square leads: up a ladder, down a chute, or nowhere.
fn jump(n: int) -> int {
  for i in 0..len(from) {
    if from[i] == n { return to[i]; }
  }
  return n;
}

fn roll() {
  if winner >= 0 { return; }
  rolled = dice[next % len(dice)];
  next += 1;
  let t = at[turn] + rolled;
  if t > 100 { t = 200 - t; }
  at[turn] = jump(t);
  if at[turn] == 100 {
    winner = turn;
  } else if rolled != 6 {
    turn = 1 - turn;
  }
}

// Square n's column and row: 1 at the bottom left, the rows snaking up to 100 at the top left.
fn cx(n: int) -> int {
  if (n - 1) / 10 % 2 == 0 { return (n - 1) % 10 * 12 + 6; }
  return (9 - (n - 1) % 10) * 12 + 6;
}

fn cy(n: int) -> int { return (9 - (n - 1) / 10) * 12 + 6; }

// A player's token, purple where both stand.
fn token(p: int) {
  if at[p] == 0 { return; }
  let k = 1 + p * 3;
  if at[0] == at[1] { k = 5; }
  circle(cx(at[p]), cy(at[p]), 4, k);
}

fn scene() {
  for i in 0..100 { rect(i % 10 * 12, i / 10 * 12, 11, 11, 7); }
  for i in 0..len(from) {
    let k = 2;
    if to[i] < from[i] { k = 3; }
    line(cx(from[i]), cy(from[i]), cx(to[i]), cy(to[i]), 2, k);
  }
  token(0);
  token(1);
}

fn status() -> string {
  if winner >= 0 { return name(winner) + " wins"; }
  if rolled == 0 { return name(turn) + " to roll"; }
  return "Rolled " + rolled + ". " + name(turn) + " to roll";
}

