// SameGame: tap a group of two or more touching blocks of one color to select it, tap it again
// to clear it for (n - 2) squared points; blocks fall, empty columns close up. Clear them all: 1000.
// icon: fill 3 13 11 13 11 21 3 21 fill 13 13 21 13 21 21 13 21 fill 13 3 21 3 21 11 13 11 ring 7 7 3
state start = [
  1, 4, 1, 2, 1, 2, 2, 2,
  4, 2, 1, 1, 2, 1, 2, 2,
  4, 1, 4, 2, 2, 4, 1, 4,
  1, 2, 1, 1, 1, 4, 4, 1,
  2, 4, 1, 2, 4, 1, 4, 1,
  2, 2, 4, 1, 2, 1, 4, 1
];                        // the board, row by row from the top: 1 red, 2 green, 4 blue
state board = [
  1, 4, 1, 2, 1, 2, 2, 2,
  4, 2, 1, 1, 2, 1, 2, 2,
  4, 1, 4, 2, 2, 4, 1, 4,
  1, 2, 1, 1, 1, 4, 4, 1,
  2, 4, 1, 2, 4, 1, 4, 1,
  2, 2, 4, 1, 2, 1, 4, 1
];                        // as it is now: 0 an empty square
state picked = [false; 48];
state count = 0;          // the blocks selected
state score = 0;

fn reset() {
  for i in 0..48 {
    board[i] = start[i];
    picked[i] = false;
  }
  count = 0;
  score = 0;
}

// Selects the group of square i, if it has two or more blocks: a search out from it.
fn pick(i: int) {
  for k in 0..48 { picked[k] = false; }
  count = 0;
  if board[i] == 0 { return; }
  let dx = [1, -1, 0, 0];
  let dy = [0, 0, 1, -1];
  let q = [i];
  picked[i] = true;
  for n in 0..48 {
    if n < len(q) {
      for d in 0..4 {
        let c = q[n] % 8 + dx[d];
        let r = q[n] / 8 + dy[d];
        if c >= 0 && c < 8 && r >= 0 && r < 6 {
          let j = r * 8 + c;
          if !picked[j] && board[j] == board[i] {
            picked[j] = true;
            push(q, j);
          }
        }
      }
    }
  }
  count = len(q);
  if count < 2 {
    picked[i] = false;
    count = 0;
  }
}

// The selected blocks gone: the rest fall, and the columns left close up to the left.
fn clearing() {
  score += (count - 2) * (count - 2);
  let b = [0; 48];
  let to = 0;
  for c in 0..8 {
    let r = 5;
    for k in 0..6 {
      let j = (5 - k) * 8 + c;
      if board[j] > 0 && !picked[j] {
        b[r * 8 + to] = board[j];
        r -= 1;
      }
    }
    if r < 5 { to += 1; }
  }
  for i in 0..48 {
    board[i] = b[i];
    picked[i] = false;
  }
  count = 0;
  // The bottom left square is the last to empty: empty, the board is.
  if b[40] == 0 { score += 1000; }
}

// Whether a group of two or more is left: two touching blocks of one color.
fn moves() -> bool {
  for i in 0..48 {
    if board[i] > 0 && i % 8 < 7 && board[i + 1] == board[i] { return true; }
    if board[i] > 0 && i < 40 && board[i + 8] == board[i] { return true; }
  }
  return false;
}

fn tap(i: int) {
  if picked[i] { clearing(); } else { pick(i); }
}

