// SameGame: tap a group of two or more touching blocks of one color to clear it; the blocks above
// drop down and empty columns slide left.
// icon: fill 3 13 11 13 11 21 3 21 fill 13 13 21 13 21 21 13 21 fill 13 3 21 3 21 11 13 11 ring 7 7 3
state board = [
  3, 3, 3, 2, 2, 3,
  2, 1, 3, 4, 2, 1,
  1, 3, 3, 2, 1, 1,
  1, 1, 2, 2, 1, 3,
  4, 3, 2, 2, 4, 3,
  1, 1, 3, 4, 3, 1
];                        // row by row from the top: 1 red, 2 green, 3 yellow, 4 blue, 0 empty
state gone = [false; 36]; // the group a tap clears

// Marks the group of square i in gone, a search out from it; how many blocks it has.
fn group(i: int) -> int {
  for k in 0..36 { gone[k] = false; }
  let dx = [1, -1, 0, 0];
  let dy = [0, 0, 1, -1];
  let q = [i];
  gone[i] = true;
  for n in 0..36 {
    if n < len(q) {
      for d in 0..4 {
        let c = q[n] % 6 + dx[d];
        let r = q[n] / 6 + dy[d];
        if c >= 0 && c < 6 && r >= 0 && r < 6 && !gone[r * 6 + c] && board[r * 6 + c] == board[i] {
          gone[r * 6 + c] = true;
          push(q, r * 6 + c);
        }
      }
    }
  }
  return len(q);
}

// The group of square i cleared if it has two or more blocks: the rest drop, and the columns
// left close up to the left.
fn tap(i: int) {
  if board[i] == 0 || group(i) < 2 { return; }
  let b = [0; 36];
  let to = 0;
  for c in 0..6 {
    let r = 5;
    for k in 0..6 {
      let j = (5 - k) * 6 + c;
      if board[j] > 0 && !gone[j] {
        b[r * 6 + to] = board[j];
        r -= 1;
      }
    }
    if r < 5 { to += 1; }
  }
  for k in 0..36 { board[k] = b[k]; }
}

fn scene() {
  for i in 0..36 {
    if board[i] > 0 { rect((i % 6) * 20 + 1, (i / 6) * 20 + 1, 18, 18, board[i]); }
  }
}

