// Pentago for Red and Blue: tap a hole to place a marble, then turn one of the four blocks a
// quarter with its button (Left anticlockwise, Right clockwise). Five in a row wins.
// icon: loop 3 3 11 3 11 11 3 11 loop 13 3 21 3 21 11 13 11 loop 3 13 11 13 11 21 3 21 arc 17 17 4 0 270 dot 7 7 2
state board = [0; 36];    // 0 empty, 1 red, 4 blue
state turn = 1;
state placed = false;     // a marble placed, its turn still to come
state result = 0;         // 0 playing, 1 Red won, 4 Blue won, 5 a draw

fn name(p: int) -> string {
  if p == 1 { return "Red"; }
  return "Blue";
}

// Whether p has five in a row from (c, r), a step (dc, dr) on.
fn run(p: int, c: int, r: int, dc: int, dr: int) -> bool {
  for k in 0..5 {
    let x = c + dc * k;
    let y = r + dr * k;
    if x < 0 || x > 5 || y < 0 || y > 5 || board[y * 6 + x] != p { return false; }
  }
  return true;
}

fn five(p: int) -> bool {
  for i in 0..36 {
    let c = i % 6;
    let r = i / 6;
    if run(p, c, r, 1, 0) || run(p, c, r, 0, 1) || run(p, c, r, 1, 1) || run(p, c, r, 1, -1) {
      return true;
    }
  }
  return false;
}

fn full() -> bool {
  for i in 0..36 {
    if board[i] == 0 { return false; }
  }
  return true;
}

fn place(i: int) {
  if result > 0 || placed || board[i] > 0 { return; }
  board[i] = turn;
  placed = true;
}

// Block q (1 top left, 2 top right, 3 bottom left, 4 bottom right) a quarter turn, clockwise if
// cw; then five in a row is looked for.
fn twist(q: int, cw: bool) {
  if result > 0 || !placed { return; }
  let ox = (q - 1) % 2 * 3;
  let oy = (q - 1) / 2 * 3;
  let old = [0; 9];
  for k in 0..9 { old[k] = board[(oy + k / 3) * 6 + ox + k % 3]; }
  for k in 0..9 {
    let v = old[k % 3 * 3 + 2 - k / 3];
    if cw { v = old[(2 - k % 3) * 3 + k / 3]; }
    board[(oy + k / 3) * 6 + ox + k % 3] = v;
  }
  placed = false;
  let red = five(1);
  let blue = five(4);
  if red && blue {
    result = 5;
  } else if red {
    result = 1;
  } else if blue {
    result = 4;
  } else if full() {
    result = 5;
  } else {
    turn = 5 - turn;
  }
}

// The four blocks in silver, the holes 20 units apart.
fn scene() {
  for q in 0..4 { rect(q % 2 * 61, q / 2 * 61, 59, 59, 7); }
  for i in 0..36 { circle(i % 6 * 20 + 10, i / 6 * 20 + 10, 8, board[i]); }
}

fn status() -> string {
  if result == 5 { return "Draw"; }
  if result > 0 { return name(result) + " wins"; }
  if placed { return name(turn) + " to turn"; }
  return name(turn) + " to place";
}

