// Cryptogram: each letter of a saying stands for another. Pick a code letter with its button, then
// type the letter you think it stands for (space clears it); get them all right to solve it.
// icon: loop 3 6 21 6 21 18 3 18 line 7 14 9 9 11 14 line 8 12 10 12 line 14 9 18 9 16 9 16 14
state code = ["D", "G", "J", " ", "J", "W", "A", "H", "O", " ", "S", "F", "A", "N", " ", "Q", "W", "D", "Q", "G", "J", "L", " ", "D", "G", "J", " ", "K", "X", "A", "V"];
state plain = ["T", "H", "E", " ", "E", "A", "R", "L", "Y", " ", "B", "I", "R", "D", " ", "C", "A", "T", "C", "H", "E", "S", " ", "T", "H", "E", " ", "W", "O", "R", "M"];
state keys = ["A", "D", "F", "G", "H", "J", "K", "L", "N", "O", "Q", "S", "V", "W", "X"];   // the code letters, a button each
state guess = [""; 15];        // what I think each stands for
state picked = -1;

fn slot(c: string) -> int {
  for k in 0..len(keys) {
    if keys[k] == c { return k; }
  }
  return -1;
}

// Code letter i as I have it: my guess, _ for none, a space as it is.
fn shown(i: int) -> string {
  if code[i] == " " { return " "; }
  let g = guess[slot(code[i])];
  if g == "" { return "_"; }
  return g;
}

fn mine() -> string {
  let s = "";
  for i in 0..len(code) { s = s + shown(i); }
  return s;
}

fn solved() -> bool {
  for i in 0..len(code) {
    if code[i] != " " && guess[slot(code[i])] != plain[i] { return false; }
  }
  return true;
}

fn left() -> int {
  let n = 0;
  for k in 0..len(keys) {
    if guess[k] == "" { n += 1; }
  }
  return n;
}

// The picked code letter stands for t now, and no other one does.
fn put(t: string) {
  if picked < 0 || solved() { return; }
  for k in 0..len(keys) {
    if guess[k] == t { guess[k] = ""; }
  }
  guess[picked] = t;
}

fn pickedname() -> string {
  if picked < 0 { return "-"; }
  return keys[picked];
}

fn status() -> string {
  if solved() { return "Solved"; }
  return "Pick a code letter, then type a letter";
}

