// Sumo: the arrows (or a tap beside you) step your wrestler; walk into the red one to push it.
// Push it out of the ring three bouts in a row, each against a quicker wrestler.
// icon: ring 12 12 10 dot 8 12 4 dot 16 12 4
state mx = 2;                   // me
state my = 4;
state cx = 6;                   // the computer's wrestler
state cy = 4;
state bout = 1;
state steps = 0;                // steps since the bout began
state speed = 0;                // ms a step; 0 while no game runs
state result = "";

fn inside(c: int, r: int) -> bool { return (c - 4) * (c - 4) + (r - 4) * (r - 4) <= 16; }

fn begin() {
  mx = 2;
  my = 4;
  cx = 6;
  cy = 4;
  steps = 0;
}

fn start() {
  bout = 1;
  result = "";
  begin();
  speed = 100;
}

// The bout is won: the next begins, or after the third the game is won.
fn win() {
  if bout == 3 {
    result = "You win";
    speed = 0;
  } else {
    bout += 1;
    begin();
  }
}

// Whoever is outside the ring has lost the bout.
fn judge() {
  if !inside(cx, cy) {
    win();
  } else if !inside(mx, my) {
    result = "Game over";
    speed = 0;
  }
}

// I step one square; onto the computer, it is pushed a square the same way.
fn step(dx: int, dy: int) {
  if speed == 0 { return; }
  mx += dx;
  my += dy;
  if mx == cx && my == cy {
    cx += dx;
    cy += dy;
  }
  judge();
}

// The computer steps toward me, across if our columns differ at least as much as our rows;
// onto me, I am pushed.
every speed {
  steps += 1;
  if steps % (5 - bout) == 0 {
    let dx = 0;
    let dy = 0;
    if abs(mx - cx) >= abs(my - cy) {
      dx = (mx - cx) / abs(mx - cx);
    } else {
      dy = (my - cy) / abs(my - cy);
    }
    cx += dx;
    cy += dy;
    if cx == mx && cy == my {
      mx += dx;
      my += dy;
    }
    judge();
  }
}

on key "left" { step(-1, 0); }
on key "right" { step(1, 0); }
on key "up" { step(0, -1); }
on key "down" { step(0, 1); }

fn scene() {
  let cells = [-1; 81];
  for i in 0..81 {
    if inside(i % 9, i / 9) { cells[i] = 3; }
  }
  if inside(cx, cy) { cells[cy * 9 + cx] = 1; }
  if inside(mx, my) { cells[my * 9 + mx] = 4; }
  pixels(cells, 0, 0, 9, 10);
  if result != "" { text(result, 45, 45, 12, 11); }
}

