canvas 90, 90, scene() {
  let dx = x / 10 - mx;
  let dy = y / 10 - my;
  if abs(dx) > abs(dy) { step(dx / abs(dx), 0); } else if dy != 0 { step(0, dy / abs(dy)); }
}
if speed == 0 { button "Start" { start(); } }

// Sumo: press space to push the other wrestler back a step; he pushes you back on his own,
// faster each bout. Whoever is pushed 5 steps past the middle loses. Win three bouts.
// icon: ring 12 12 10 dot 8 12 4 dot 16 12 4
state rates = [1000, 500, 250];  // ms between his pushes, bout by bout
state at = 0;                    // how far I have pushed him past the middle
