// Duck hunt: tap the flying duck to shoot it, 3 shots a duck. Hit 3 of a round's 5 ducks to
// reach round 2, where they fly faster; hit 3 there too to win.
// icon: fill 4 12 9 9 15 9 20 12 15 15 9 15 fill 15 9 18 5 21 6 18 10 line 2 21 22 21
state starts = [1, 8, 3, 6, 0];   // where each duck of a round appears, on row 6
state dx = 1;                     // the duck: square, way, moves made
state dy = -1;
state px = 1;
state py = 6;
state moves = 0;
state age = 0;                    // steps since it appeared
state duck = 1;                   // which of the round's 5
state shots = 3;
state hits = 0;
state round = 1;
state speed = 0;                  // ms a step; 0 while no game runs
state result = "";

fn appear() {
  px = starts[duck - 1];
  py = 6;
  dx = 1;
  if px >= 5 { dx = -1; }
  dy = -1;
  moves = 0;
  age = 0;
  shots = 3;
}

fn start() {
  round = 1;
  duck = 1;
  hits = 0;
  result = "";
  appear();
  speed = 100;
