// Dodgeball: left and right dodge the balls thrown down at you; space or Throw throws yours up
// to knock a thrower out. Knock out all three, twice (they throw faster the second time).
// icon: ring 12 7 5 dot 12 7 2 fill 9 15 15 15 15 21 9 21 line 12 12 12 15
state tx = [1, 4, 7];           // the throwers' columns, on row 0, and whether each is in
state up = [true, true, true];
state bx = [0; 0];              // the thrown balls
state by = [0; 0];
state mx = 4;                   // me, on row 9
state my = -1;                  // my ball's row (-1: none) and column
state mc = 0;
state turn = 0;                 // the thrower whose turn is next
state steps = 0;                // steps since the level began
state level = 1;
state lives = 3;
state score = 0;
state speed = 0;                // ms a step; 0 while no game runs
state result = "";

fn begin() {
  up = [true, true, true];
  clear(bx);
  clear(by);
  mx = 4;
  my = -1;
  turn = 0;
  steps = 0;
}

fn start() {
  level = 1;
  lives = 3;
  score = 0;
  result = "";
  begin();
  speed = 100;
}

fn left() -> int {
  let n = 0;
  for i in 0..3 {
    if up[i] { n += 1; }
  }
  return n;
}

// A thrown ball on my square hits me.
fn hit() {
  for i in 0..len(bx) {
    if i < len(bx) && bx[i] == mx && by[i] == 9 {
      remove(bx, i);
      remove(by, i);
      lives -= 1;
      if lives == 0 {
        result = "Game over";
        speed = 0;
      }
    }
  }
}

// The next thrower still in throws a ball onto row 1 of its column.
fn throw() {
  for k in 0..3 {
    if !up[turn] { turn = (turn + 1) % 3; }
  }
  push(bx, tx[turn]);
  push(by, 1);
  turn = (turn + 1) % 3;
}

every speed {
  steps += 1;
  for i in 0..len(by) { by[i] += 1; }
  if len(by) > 0 && by[0] > 9 {
    remove(bx, 0);
    remove(by, 0);
  }
  if my >= 0 {
    my -= 1;
    if my == 0 {
      for i in 0..3 {
        if up[i] && tx[i] == mc {
          up[i] = false;
          score += 100;
        }
      }
      my = -1;
      if left() == 0 && level == 2 {
        result = "You win";
        speed = 0;
        return;
      } else if left() == 0 {
        level = 2;
        begin();
        return;
      }
    }
  }
  if steps % (11 - 3 * level) == 0 { throw(); }
  hit();
}

fn step(d: int) {
  if speed == 0 { return; }
  mx = min(8, max(0, mx + d));
  hit();
}

fn shoot() {
  if speed > 0 && my < 0 {
    my = 8;
    mc = mx;
  }
}

on key "left" { step(-1); }
on key "right" { step(1); }
on key "space" { shoot(); }

