// Fox and geese: tap a goose, then a free point beside or below it, to move it; the fox moves
// back, jumping a goose when it can. Trap the fox before it takes four geese.
// icon: fill 12 3 16 8 20 6 18 12 12 14 6 12 4 6 8 8 dot 5 19 2 dot 12 19 2 dot 19 19 2
state geese = [false; 49];      // the board, 7 x 7: square c + 7 * r
state fx = 3;
state fy = 4;
state pick = -1;                // the goose picked, or -1
state playing = false;
state result = "";

fn point(c: int, r: int) -> bool {
  return c >= 0 && c < 7 && r >= 0 && r < 7 && (c >= 2 && c <= 4 || r >= 2 && r <= 4);
}

fn free(c: int, r: int) -> bool { return point(c, r) && !geese[r * 7 + c] && (c != fx || r != fy); }

fn count() -> int {
  let n = 0;
  for i in 0..49 {
    if geese[i] { n += 1; }
  }
  return n;
}

fn start() {
  for i in 0..49 { geese[i] = point(i % 7, i / 7) && i < 21; }
  fx = 3;
  fy = 4;
  pick = -1;
  result = "";
  playing = true;
}

// The fox's move: the first jump up, left, right or down it can make, else the first step.
fn fox() {
  let dx = [0, -1, 1, 0];
  let dy = [-1, 0, 0, 1];
  for k in 0..4 {
    let c = fx + dx[k];
    let r = fy + dy[k];
    if point(c, r) && geese[r * 7 + c] && free(c + dx[k], r + dy[k]) {
      geese[r * 7 + c] = false;
      fx = c + dx[k];
      fy = r + dy[k];
      if count() <= 9 {
        result = "Game over";
        playing = false;
      }
      return;
    }
  }
  for k in 0..4 {
    if free(fx + dx[k], fy + dy[k]) {
      fx += dx[k];
      fy += dy[k];
      return;
    }
  }
  result = "You win";
  playing = false;
}

fn tap(c: int, r: int) {
  if !playing || !point(c, r) { return; }
  if geese[r * 7 + c] {
    pick = r * 7 + c;
  } else if pick >= 0 && free(c, r) && (abs(c - pick % 7) == 1 && r == pick / 7 || c == pick % 7 && r == pick / 7 + 1) {
    geese[pick] = false;
    geese[r * 7 + c] = true;
    pick = -1;
    fox();
  }
}

fn scene() {
  let cells = [-1; 49];
  for i in 0..49 {
    if point(i % 7, i / 7) { cells[i] = 8; }
    if geese[i] { cells[i] = 3; }
  }
  if pick >= 0 { cells[pick] = 2; }
  cells[fy * 7 + fx] = 1;
  pixels(cells, 0, 0, 7, 10);
  if result != "" { text(result, 35, 35, 10, 11); }
}

