// Fox and geese for two: the geese go first. Tap a piece, then where it goes: a goose steps
// left, right or down; the fox steps or jumps a goose to take it. Four taken and the fox wins.
// icon: fill 12 3 16 8 20 6 18 12 12 14 6 12 4 6 8 8 dot 5 19 2 dot 12 19 2 dot 19 19 2
state geese = [false; 49];      // the board, 7 x 7: square c + 7 * r
state fx = 3;
state fy = 3;
state pick = -1;                // the piece picked: its square, or -1
state fox = false;              // whose turn: the fox's, else the geese's
state playing = false;
state said = "";

fn point(c: int, r: int) -> bool {
  return c >= 0 && c < 7 && r >= 0 && r < 7 && (c >= 2 && c <= 4 || r >= 2 && r <= 4);
}

fn free(c: int, r: int) -> bool { return point(c, r) && !geese[r * 7 + c] && (c != fx || r != fy); }

fn left() -> int {
  let n = 0;
  for i in 0..49 {
    if geese[i] { n += 1; }
  }
  return n;
}

// Whether the fox can step or jump anywhere.
fn moves() -> bool {
  let dx = [0, -1, 1, 0];
  let dy = [-1, 0, 0, 1];
  for k in 0..4 {
    let c = fx + dx[k];
    let r = fy + dy[k];
    if free(c, r) || point(c, r) && geese[r * 7 + c] && free(c + dx[k], r + dy[k]) { return true; }
  }
  return false;
}

fn goose(c: int, r: int) {
  let a = pick % 7;
  let b = pick / 7;
  if free(c, r) && (abs(c - a) == 1 && r == b || c == a && r == b + 1) {
    geese[pick] = false;
    geese[r * 7 + c] = true;
    pick = -1;
    fox = true;
    if !moves() {
      said = "Geese win";
      playing = false;
    }
  }
}

fn hop(c: int, r: int) {
  let d = abs(c - fx) + abs(r - fy);
  let mx = (fx + c) / 2;
  let my = (fy + r) / 2;
  if free(c, r) && d == 1 {
    fx = c;
    fy = r;
    fox = false;
  } else if free(c, r) && d == 2 && (c == fx || r == fy) && geese[my * 7 + mx] {
    geese[my * 7 + mx] = false;
    fx = c;
    fy = r;
    fox = false;
    if left() <= 9 {
      said = "Fox wins";
      playing = false;
    }
  }
  pick = -1;
}

fn tap(c: int, r: int) {
  if !playing || !point(c, r) { return; }
  if !fox && geese[r * 7 + c] {
    pick = r * 7 + c;
  } else if fox && c == fx && r == fy {
    pick = r * 7 + c;
  } else if pick >= 0 && !fox {
    goose(c, r);
  } else if pick >= 0 {
    hop(c, r);
  }
}

fn scene() {
  let cells = [-1; 49];
  for i in 0..49 {
    if point(i % 7, i / 7) { cells[i] = 8; }
    if geese[i] { cells[i] = 3; }
  }
  if pick >= 0 { cells[pick] = 2; }
  cells[fy * 7 + fx] = 1;
  if pick == fy * 7 + fx { cells[pick] = 5; }
  pixels(cells, 0, 0, 7, 10);
}

