fn playing() -> bool { return speed > 0; }

fn note(s: string) {
  for i in 0..len(notes) {
    if notes[i] == s { return; }
  }
  push(notes, s);
}

fn items() -> string {
  if torch { return "Items: key, torch"; }
  if key { return "Items: key"; }
  return "Items: none";
}

// A search: 0 the rug, 1 the desk, 2 the bookcase, 3 the painting.
fn search(what: int) {
  if !playing() { return; }
  if what == 0 {
    key = true;
    news = "A key under the rug";
  } else if what == 1 {
    if !key {
      news = "The desk is locked";
      return;
    }
    torch = true;
    note("Last digit 8");
    news = "In the desk: a torch and a note";
  } else if what == 2 {
    if !torch {
      news = "Too dark to see";
      return;
    }
    note("First digit 2");
    news = "On the shelf: a note";
  } else {
    note("Middle digit 5");
    news = "Behind the painting: a note";
  }
}

fn turn(d: int) {
  if playing() { dials[d] = (dials[d] + 1) % 10; }
}

fn ends() {
  if time == 0 {
    over = "Time's up";
    speed = 0;
  }
}

fn open() {
  if !playing() { return; }
  if dials[0] == 2 && dials[1] == 5 && dials[2] == 8 {
    over = "Escaped";
    speed = 0;
    return;
  }
  news = "Wrong code";
  time = max(0, time - 10);
  ends();
}

fn reset() {
  time = 90;
  speed = 0;
  begun = false;
  over = "";
  key = false;
  torch = false;
  clear(notes);
  news = "";
  for i in 0..3 { dials[i] = 0; }
}

every speed {
