// Bank heist: five banks in turn. Grab $500 bags; each puts the alarm up 10%, and at 100% the
// cops take that bank's bags. Run for it to keep them. The crew of 3 splits the total.
// icon: loop 4 8 20 8 20 20 4 20 line 9 8 9 4 15 4 15 8 dot 12 14 3
state bank = 1;
state bags = 0;              // $ grabbed at this bank
state alarm = 0;             // in %
state total = 0;             // $ kept
state news = "";

fn next() {
  bags = 0;
  alarm = 0;
  bank += 1;
}

fn grab() {
  if bank > 5 { return; }
  bags += 500;
  alarm += 10;
  if alarm >= 100 {
    news = "The cops came: the bags from bank " + bank + " are lost";
    next();
  }
}

fn run() {
  if bank > 5 { return; }
  total += bags;
  news = "Away with $" + bags;
  next();
}

label "Bank heist";
if bank <= 5 {
  label "Bank " + bank + " of 5   Bags $" + bags + "   Alarm " + alarm + "%";
} else {
  label "All 5 banks done: $" + total / 3 + " each";
}
label "Total $" + total;
if news != "" { label news; }
row {
  button "Grab" { grab(); }
  button "Run" { run(); }
}

// Factory: Start it; mines dig ore, smelters make bars from 2 ore, workshops gears from 3 bars.
// Buy machines, sell bars and gears, and reach $200 to be a Tycoon.
// icon: loop 3 21 3 11 9 15 9 11 15 15 15 5 21 5 21 21 ring 12 3 2
state money = 50;
state mines = 1;
state smelters = 0;
state shops = 0;             // workshops
state ore = 0;
state bars = 0;
state gears = 0;
state time = 0;
state speed = 0;             // ms a second: 1000 while the factory runs
state begun = false;
state over = false;

fn running() -> bool { return speed > 0; }

// Pays cost if the money is there.
fn pay(cost: int) -> bool {
  if !running() || money < cost { return false; }
  money -= cost;
  return true;
}

fn earn(n: int) {
  money += n;
  if money >= 200 {
    over = true;
    speed = 0;
  }
}

fn reset() {
  money = 50;
  mines = 1;
  smelters = 0;
  shops = 0;
  ore = 0;
  bars = 0;
  gears = 0;
  time = 0;
  speed = 0;
  begun = false;
  over = false;
}

every speed {
  time += 1;
  ore += mines;
  let n = min(smelters, ore / 2);
  ore -= n * 2;
  bars += n;
  let m = min(shops, bars / 3);
  bars -= m * 3;
  gears += m;
}

// A row of boxes for each kind of machine: mines gray, smelters red, workshops blue.
fn machines(k: int, y: int, color: int) {
  for i in 0..min(k, 12) { rect(4 + i * 13, y, 10, 10, color); }
}

fn scene() {
  machines(mines, 4, 8);
  machines(smelters, 20, 1);
  machines(shops, 36, 4);
  if over { text("Tycoon", 80, 26, 14, 11); }
}

label "Factory";
label "Money " + money + "   Time " + time;
label "Ore " + ore + "   Bars " + bars + "   Gears " + gears;
label "Mines " + mines + "   Smelters " + smelters + "   Workshops " + shops;
canvas 160, 50, scene();
row {
  button "Buy mine" {
    if pay(10) { mines += 1; }
  }
  button "Buy smelter" {
    if pay(15) { smelters += 1; }
  }
  button "Buy workshop" {
    if pay(25) { shops += 1; }
  }
}
row {
  button "Sell bars" {
    if running() {
      earn(bars * 5);
      bars = 0;
    }
  }
  button "Sell gears" {
    if running() {
      earn(gears * 20);
      gears = 0;
    }
  }
}
if !begun {
  button "Start" {
    begun = true;
    speed = 1000;
  }
}
if over { button "New game" { reset(); } }

// Widget factory: each machine makes a widget a second. Sell them for $1 each and buy more
// machines for $10.
// icon: loop 3 21 3 11 9 15 9 11 15 15 15 5 21 5 21 21
state machines = 1;
state widgets = 0;
state money = 0;
state speed = 0;             // ms a step: 1000 once started
state begun = false;

every speed { widgets += machines; }

// The machines in a row, each with a widget popping out.
fn scene() {
  for i in 0..min(machines, 10) { rect(4 + i * 15, 10, 12, 12, 8); }
}

label "Widget factory";
label "Widgets " + widgets + "   Money $" + money + "   Machines " + machines;
canvas 160, 30, scene();
row {
  button "Sell" {
    money += widgets;
    widgets = 0;
  }
  button "Buy machine $10" {
