// Each digit's lit segments, one bit each: top 1, upper right 2, lower right 4, bottom 8,
// lower left 16, upper left 32, middle 64.
state lit = [63, 6, 91, 79, 102, 109, 125, 7, 127, 111];

// Segment `bit` of the digit shown, red while lit, else dark gray.
fn bar(bit: int, x: int, y: int, w: int, h: int) {
  let c = 8;
  if lit[digit] / bit % 2 == 1 { c = 1; }
  rect(x, y, w, h, c);
}

// The digit on a 60 x 100 canvas: a 3 x 5 grid of 20-unit squares, each bar over its square.
fn scene() {
  bar(1, 10, 4, 40, 10);
  bar(2, 46, 10, 10, 40);
  bar(4, 46, 50, 10, 40);
  bar(8, 10, 86, 40, 10);
  bar(16, 4, 50, 10, 40);
  bar(32, 4, 10, 10, 40);
  bar(64, 10, 45, 40, 10);
}

every speed {
  digit -= 1;
  if digit == 0 {
    speed = 0;
    flown = true;
  }
}

label "LED countdown";
canvas 60, 100, scene();
if flown { label "Liftoff"; }
if speed == 0 {
  button "Start" {
    digit = 9;
    flown = false;
    speed = 1000;
  }
}

// Fidget spinner: Flick spins it 5 faster (20 at most); it slows by 1 each second until it
// stops, and Stop stops it at once.
