// The plates of one side, largest first, as many of each as fit.
fn plan() -> string {
  let left = side();
  let s = "";
  for i in 0..len(plates) {
    for k in 0..left / plates[i] {
      if s != "" { s = s + " + "; }
      s = s + plates[i];
    }
    left = left % plates[i];
  }
  return s;
}

