// Progression transposer: tap roots to write a progression (m makes the last one minor), then move
// the key up or down to see it transposed.
// icon: line 3 6 21 6 line 3 12 21 12 line 3 18 21 18 dot 8 15 2 dot 16 9 2
state notes = ["C", "C#", "D", "D#", "E", "F", "F#", "G", "G#", "A", "A#", "B"];
state roots = [0; 0];         // each chord's root, 0 (C) to 11 (B)
state minors = [false; 0];
state shift = 0;

// The progression with every root moved up by k semitones.
fn chords(k: int) -> string {
  let s = "";
  for i in 0..len(roots) {
    if i > 0 { s = s + " "; }
    s = s + notes[(roots[i] + k) % 12];
    if minors[i] { s = s + "m"; }
  }
  return s;
}

fn add(r: int) {
  if len(roots) < 8 {
    push(roots, r);
    push(minors, false);
  }
}

