// Chord transposer: type a chord (like G or F#m) and move it up or down by semitones.
// icon: line 4 18 4 6 12 4 12 16 dot 4 18 2 dot 12 16 2 line 17 14 17 4 line 14 7 17 4 20 7
state chord = "";
state steps = 0;
state notes = ["C", "C#", "D", "D#", "E", "F", "F#", "G", "G#", "A", "A#", "B"];

// The chord's root from 0 (C) to 11 (B), or -1 when it is not a chord.
fn root() -> int {
  for i in 0..12 {
    if chord == notes[i] || chord == notes[i] + "m" { return i; }
  }
  return -1;
}

fn moved() -> string {
  let r = root();
  let k = (r + steps + 24) % 12;
  if chord == notes[r] { return notes[k]; }
  return notes[k] + "m";
}

