state hours = [0; 0];
state name = "";
state hour = "";
state note = "";

fn two(n: int) -> string {
  if n < 10 { return "0" + n; }
  return "" + n;
}

// The class already at hour h, or -1.
fn at(h: int) -> int {
  for i in 0..len(hours) {
    if hours[i] == h { return i; }
  }
  return -1;
}

fn add() {
  if name == "" { return; }
  let h = parse(hour, -1);
  note = "";
  if h < 8 || h > 17 {
    note = "Hours are 8 to 17";
  } else if at(h) >= 0 {
    note = "Clash with " + classes[at(h)];
  } else {
    let k = 0;
    for i in 0..len(hours) {
      if hours[i] < h { k = i + 1; }
    }
    insert(classes, k, name);
    insert(hours, k, h);
  }
}

