// Cycle: Next day moves on a day; Period started begins a new cycle and logs the one that ended.
// It counts down to the next period from your average cycle.
// icon: arc 12 12 9 30 330 fill 12 6 16 13 12 17 8 13
state day = 1;
state logged = [0; 0];    // the lengths of the cycles that ended

// The expected length: 28 until a cycle is logged, then their average, rounded down.
fn expected() -> int {
  if len(logged) == 0 { return 28; }
  let sum = 0;
  for i in 0..len(logged) { sum += logged[i]; }
  return sum / len(logged);
}

