fn gcd(a: int, b: int) -> int {
  let p = abs(a);
  let q = abs(b);
  for i in 0..100 {
    if q == 0 { return p; }
    let m = p % q;
    p = q;
    q = m;
  }
  return p;
}

// n / d in lowest terms, its minus first; d is never 0.
fn show(n: int, d: int) -> string {
  let g = gcd(n, d);
  let top = n / g;
  let bottom = d / g;
  if bottom < 0 {
    top = -top;
    bottom = -bottom;
  }
  if bottom == 1 { return "Answer: " + top; }
  return "Answer: " + top + "/" + bottom;
}

// k: 0 plus, 1 minus, 2 times, 3 divided by.
fn work(k: int) {
  let a = parse(an, 0);
  let b = parse(ad, 0);
  let c = parse(bn, 0);
  let d = parse(bd, 0);
  if b == 0 || d == 0 || (k == 3 && c == 0) {
    answer = "Undefined";
  } else if k == 0 {
    answer = show(a * d + c * b, b * d);
  } else if k == 1 {
    answer = show(a * d - c * b, b * d);
  } else if k == 2 {
    answer = show(a * c, b * d);
  } else {
    answer = show(a * d, b * c);
  }
}

