// The number typed, or 0 when it is not 2 to 1000000.
fn number() -> int {
  let n = parse(typed, 0);
  if n < 2 || n > 1000000 { return 0; }
  return n;
}

fn join(s: string, d: int) -> string {
  if s == "" { return "" + d; }
  return s + " x " + d;
}

// n's prime factors, smallest first, joined by x.
fn factors(n: int) -> string {
  let m = n;
  let s = "";
  for d in 2..1001 {
    if m % d == 0 {
      repeat 20 {
        if m % d == 0 {
          s = join(s, d);
          m = m / d;
        }
      }
    }
  }
  if m > 1 { s = join(s, m); }
  return s;
}

