// The logs fall as you chop: never stand where a branch comes down. 20 seconds a game.
// icon: fill 9 2 15 2 15 22 9 22 line 15 8 21 5 line 9 15 3 12 fill 3 18 7 18 7 22 3 22
state pat = [0, 1, 0, 0, 2, 0, 1, 1, 0, 2];  // the branches in turn: 0 none, 1 left, 2 right
state tree = [0; 8];      // the logs' branches, from the bottom up
state next = 0;           // the next log of pat to come in on top
state side = 1;           // the lumberjack's side: 1 left, 2 right
state score = 0;
state time = 20;
state speed = 0;          // 1000 while a game runs
state said = "";
