// Eight queens: tap a square to put a queen on it or take it off. Place all 8 with none
// attacking another along a row, a column or a diagonal.
// icon: fill 4 18 20 18 20 21 4 21 fill 5 16 4 7 9 11 12 4 15 11 20 7 19 16
state board = [0; 64];    // 8 x 8 squares: 4 a queen

// Whether all 8 queens are on and none attacks another.
fn solved() -> bool {
  let qs = [0; 0];
  for i in 0..64 {
    if board[i] > 0 { push(qs, i); }
  }
  if len(qs) != 8 { return false; }
  for a in 0..8 {
    for b in a + 1..8 {
      let dr = abs(qs[a] / 8 - qs[b] / 8);
      let dc = abs(qs[a] % 8 - qs[b] % 8);
      if dr == 0 || dc == 0 || dr == dc { return false; }
    }
  }
  return true;
}

