// v thousandths, rounded to the nearest whole.
fn near(v: int) -> int {
  if v < 0 { return -((-v + 500) / 1000); }
  return (v + 500) / 1000;
}

fn dot() {
  let c = 20 + near(12 * cos(a) + 6 * cos((n - 1) * a));
  let r = 20 - near(12 * sin(a) - 6 * sin((n - 1) * a));
  board[r * 41 + c] = ink;
}

every speed {
  a += 5;
  dot();
  if a >= 360 { speed = 0; }
}

