state food = "";
state fun = "";
state save = "";

fn amt(s: string) -> int { return max(0, min(1000000, parse(s, 0))); }
fn total() -> int { return amt(rent) + amt(food) + amt(fun) + amt(save); }
fn pct(s: string) -> int { return amt(s) * 100 / total(); }

// The color at degree d clockwise from the top: rent red, food yellow, fun blue, savings green.
fn tint(d: int, all: int) -> int {
  let at = (2 * d + 1) * all;
  if at < 720 * amt(rent) { return 1; }
  if at < 720 * (amt(rent) + amt(food)) { return 3; }
  if at < 720 * (all - amt(save)) { return 4; }
  return 2;
}

// The pie, 100 units across: a spoke a degree, in its slice's color.
fn scene() {
  let all = total();
  for d in 0..360 { line(50, 50, 50 + 49 * sin(d) / 1000, 50 - 49 * cos(d) / 1000, 3, tint(d, all)); }
}

