}

// Treasure hunt: tap squares to dig. A miss shows how many steps away the treasure is: red if
// near, blue if far. Ten digs to find it.
// icon: line 5 5 19 19 line 19 5 5 19 ring 12 12 9
state look = [2; 64];     // 2 not dug, 1 near, 4 far, 3 the treasure
state marks = [""; 64];   // the steps written on each square dug
state left = 10;
state found = false;
state over = false;

fn dig(i: int) {
  if over || look[i] != 2 { return; }
  left -= 1;
  let d = abs(i % 8 - 5) + abs(i / 8 - 2);
  if d == 0 {
    look[i] = 3;
    found = true;
    over = true;
    return;
  }
  if d <= 3 { look[i] = 1; } else { look[i] = 4; }
  marks[i] = "" + d;
  if left == 0 {
    look[21] = 3;
    over = true;
  }
}

