state bc = 0;
state side = 0;           // the boat's bank: 0 left, 1 right
state crossings = 0;
state eaten = false;

fn solved() -> bool { return m[1] == 3 && c[1] == 3; }

fn board(missionary: bool) {
  if eaten || bm + bc == 2 { return; }
  if missionary && m[side] > 0 {
    m[side] -= 1;
    bm += 1;
  }
  if !missionary && c[side] > 0 {
    c[side] -= 1;
    bc += 1;
  }
}

fn unsafe(s: int) -> bool { return m[s] > 0 && c[s] > m[s]; }

fn cross() {
  if eaten || bm + bc == 0 { return; }
  side = 1 - side;
  m[side] += bm;
  c[side] += bc;
  bm = 0;
  bc = 0;
  crossings += 1;
  if unsafe(0) || unsafe(1) { eaten = true; }
}

// The banks with their people (missionaries yellow, cannibals red), the river, the boat.
