// Dot to dot: tap to put down numbered dots, each joined to the one before by a line. Undo
// takes the last dot back; Clear starts again.
// icon: line 4 18 10 6 20 14 dot 4 18 2 dot 10 6 2 dot 20 14 2
state dx = [0; 0];        // the dots, in order
state dy = [0; 0];

// Each dot joined to the one before, its number on it.
fn scene() {
  for k in 0..len(dx) {
    if k > 0 { line(dx[k - 1], dy[k - 1], dx[k], dy[k], 1, 9); }
    circle(dx[k], dy[k], 6, 11);
    text(k + 1, dx[k], dy[k], 8, 0);
  }
}

// A tap puts a dot down; a drag or a shaky tap that comes back to the last dot adds none.
fn put(x: int, y: int) {
  let n = len(dx);
  if n > 0 && abs(dx[n - 1] - x) < 6 && abs(dy[n - 1] - y) < 6 { return; }
  push(dx, x);
  push(dy, y);
}

label "Dot to dot";
canvas 160, 120, scene() { put(x, y); }
row {
  button "Undo" {
    if len(dx) > 0 {
      remove(dx, len(dx) - 1);
      remove(dy, len(dy) - 1);
    }
  }
