    clear(dx);
    clear(dy);
  }
}

// Calcudoku: tap a square, then a digit key or button writes it there; 0 or Erase clears it. Fill
// the board with 1 to 5 once in each row and column so that every cage makes its clue.
// icon: loop 3 3 21 3 21 21 3 21 line 12 3 12 21 line 3 12 12 12 line 5 7 9 7 line 7 5 7 9
state cage = [
  0, 1, 1, 2, 2,
  0, 3, 1, 4, 5,
  6, 3, 7, 4, 5,
  6, 8, 7, 9, 9,
  6, 8, 8, 10, 9
];                        // each square's cage, row by row from the top
state ops = ["x", "+", "+", "x", "x", "/", "+", "-", "+", "x", ""];
state goal = [10, 6, 5, 12, 15, 2, 8, 1, 8, 30, 1];
state first = [0, 1, 3, 6, 8, 9, 10, 12, 16, 18, 23];   // where each cage's clue is written
state digit = [0; 25];
state sel = -1;           // the selected square; -1 none

fn left() -> int {
  let n = 0;
  for i in 0..25 {
    if digit[i] == 0 { n += 1; }
  }
  return n;
}

// Cage k's digits combined by its operation, or -1 while one of its squares is empty.
fn made(k: int) -> int {
  let sum = 0;
  let prod = 1;
  let hi = 0;
  let lo = 9;
  for i in 0..25 {
    if cage[i] == k {
      if digit[i] == 0 { return -1; }
      sum += digit[i];
      prod = prod * digit[i];
      hi = max(hi, digit[i]);
      lo = min(lo, digit[i]);
    }
  }
  if ops[k] == "x" { return prod; }
  if ops[k] == "-" { return hi - lo; }
  if ops[k] == "/" {
    if hi % lo != 0 { return 0; }
    return hi / lo;
  }
  return sum;
}

// Whether square i's digit repeats in its row or column, or its full cage misses its clue.
fn wrong(i: int) -> bool {
  if digit[i] == 0 { return false; }
  for k in 0..5 {
    let a = i / 5 * 5 + k;
    let b = k * 5 + i % 5;
    if a != i && digit[a] == digit[i] { return true; }
    if b != i && digit[b] == digit[i] { return true; }
  }
  let m = made(cage[i]);
  return m >= 0 && m != goal[cage[i]];
}

fn solved() -> bool {
  if left() > 0 { return false; }
  for i in 0..25 {
    if wrong(i) { return false; }
  }
  return true;
}

fn pick(i: int) {
  if !solved() { sel = i; }
}

fn write(d: int) {
  if sel >= 0 && !solved() { digit[sel] = d; }
}

fn shade(i: int) -> int {
  if wrong(i) { return 1; }
  if i == sel { return 3; }
  return 0;
}

// Squares 23 units wide on silver lines; thick ink lines between cages; each clue small in its
// cage's first square, each digit large in the middle.
fn scene() {
  rect(0, 0, 120, 120, 7);
  for i in 0..25 {
    let px = i % 5 * 24;
    let py = i / 5 * 24;
    rect(px, py, 23, 23, shade(i));
    if digit[i] > 0 { text(digit[i], px + 11, py + 14, 12, 9); }
    if i % 5 < 4 && cage[i + 1] != cage[i] { line(px + 23, py, px + 23, py + 23, 2, 9); }
    if i < 20 && cage[i + 5] != cage[i] { line(px, py + 23, px + 23, py + 23, 2, 9); }
  }
  for k in 0..11 { text("" + goal[k] + ops[k], first[k] % 5 * 24 + 7, first[k] / 5 * 24 + 4, 6, 10); }
}

fn status() -> string {
  if solved() { return "Solved"; }
  return "Tap a square, then a digit";
}

on key "1" { write(1); }
on key "2" { write(2); }
on key "3" { write(3); }
on key "4" { write(4); }
on key "5" { write(5); }
on key "0" { write(0); }

