// KenKen: tap a square and type 1 to 4 to fill it, 0 to clear it. Each row and column holds 1 to
// 4 once, and each cage's digits make its clue.
// icon: loop 3 3 21 3 21 21 3 21 line 12 3 12 21 line 3 12 12 12 line 5 7 9 7 line 7 5 7 9
state cage = [0, 1, 1, 2, 0, 3, 3, 2, 4, 5, 6, 6, 4, 5, 7, 6];
state ops = ["/", "-", "+", "x", "+", "/", "x", ""];
state goal = [3, 1, 5, 8, 6, 4, 6, 3];
state digit = [0; 16];
state sel = 0;

// Cage k's digits combined by its operation, or -1 while one of its squares is empty.
fn made(k: int) -> int {
  let sum = 0;
  let prod = 1;
  let hi = 0;
  let lo = 9;
  for i in 0..16 {
    if cage[i] == k {
      if digit[i] == 0 { return -1; }
      sum += digit[i];
      prod = prod * digit[i];
      hi = max(hi, digit[i]);
      lo = min(lo, digit[i]);
    }
  }
  if ops[k] == "x" { return prod; }
  if ops[k] == "-" { return hi - lo; }
  if ops[k] == "/" && hi % lo == 0 { return hi / lo; }
  if ops[k] == "/" { return 0; }
  return sum;
}

fn solved() -> bool {
  for i in 0..16 {
    if digit[i] == 0 { return false; }
    for k in 0..4 {
      let a = i / 4 * 4 + k;
      let b = k * 4 + i % 4;
      if (a != i && digit[a] == digit[i]) || (b != i && digit[b] == digit[i]) { return false; }
    }
  }
  for k in 0..8 {
    if made(k) != goal[k] { return false; }
  }
  return true;
}

// Whether square i is its cage's first, where the clue goes.
fn lead(i: int) -> bool {
  for j in 0..i {
    if cage[j] == cage[i] { return false; }
  }
  return true;
}

fn type(d: int) { digit[sel] = d; }

// Each cage in its own color, 30 units a square; the clue at the top left of its first square,
// the digits in the middle, a ring round the selected square.
fn scene() {
  let b = [0; 16];
  for i in 0..16 { b[i] = cage[i] + 1; }
  pixels(b, 0, 0, 4, 30);
  for i in 0..16 {
    let px = i % 4 * 30;
    let py = i / 4 * 30;
    if lead(i) { text("" + goal[cage[i]] + ops[cage[i]], px + 8, py + 5, 7, 9); }
    if digit[i] > 0 { text(digit[i], px + 15, py + 17, 14, 9); }
  }
  ring(sel % 4 * 30 + 15, sel / 4 * 30 + 15, 14, 2, 9);
}

on key "1" { type(1); }
on key "2" { type(2); }
on key "3" { type(3); }
on key "4" { type(4); }
on key "0" { type(0); }

