// Hitori: tap a square to shade it, again to clear it. Shade until no number repeats among the
// white squares of a row or column, no two shaded squares touch, and the white squares stay joined.
// icon: loop 3 3 21 3 21 21 3 21 fill 3 3 12 3 12 12 3 12 fill 12 12 21 12 21 21 12 21
state nums = [3, 5, 1, 4, 4, 3, 3, 5, 3, 1, 1, 2, 4, 3, 5, 5, 3, 2, 2, 4, 1, 1, 5, 5, 2];
state shaded = [false; 25];

// Whether square i is white and its number is on another white square of its row or column.
fn twin(i: int) -> bool {
  if shaded[i] { return false; }
  for k in 0..5 {
    let a = i / 5 * 5 + k;
    let b = k * 5 + i % 5;
    if a != i && !shaded[a] && nums[a] == nums[i] { return true; }
    if b != i && !shaded[b] && nums[b] == nums[i] { return true; }
  }
  return false;
}

// Square i's neighbour d (0 up, 1 down, 2 left, 3 right), or -1 off the board.
fn near(i: int, d: int) -> int {
  if d == 0 && i >= 5 { return i - 5; }
  if d == 1 && i < 20 { return i + 5; }
  if d == 2 && i % 5 > 0 { return i - 1; }
  if d == 3 && i % 5 < 4 { return i + 1; }
  return -1;
}

fn count() -> int {
  let n = 0;
  for i in 0..25 {
    if shaded[i] { n += 1; }
  }
  return n;
}

fn touching() -> bool {
  for i in 0..25 {
    if shaded[i] && near(i, 1) >= 0 && shaded[near(i, 1)] { return true; }
    if shaded[i] && near(i, 3) >= 0 && shaded[near(i, 3)] { return true; }
  }
  return false;
}

// Whether every white square joins the first one, side by side.
fn joined() -> bool {
  let seen = [false; 25];
  let todo = [0; 0];
  for i in 0..25 {
    if len(todo) == 0 && !shaded[i] {
      push(todo, i);
      seen[i] = true;
    }
  }
  let k = 0;
  repeat 25 {
    if k < len(todo) {
      let i = todo[k];
      k += 1;
      for d in 0..4 {
        let j = near(i, d);
        if j >= 0 && !shaded[j] && !seen[j] {
          seen[j] = true;
          push(todo, j);
        }
      }
    }
  }
  return len(todo) == 25 - count();
}

fn solved() -> bool {
  for i in 0..25 {
    if twin(i) { return false; }
  }
  return !touching() && joined();
}

fn tap(i: int) {
  if !solved() { shaded[i] = !shaded[i]; }
}

fn shade(i: int) -> int {
  if shaded[i] { return 8; }
  if twin(i) { return 1; }
  return 0;
}

// Squares 23 units wide on silver lines, each with its number.
fn scene() {
  rect(0, 0, 120, 120, 7);
  for i in 0..25 {
    let px = i % 5 * 24;
    let py = i / 5 * 24;
    rect(px, py, 23, 23, shade(i));
    text(nums[i], px + 11, py + 12, 12, 9);
  }
}

fn status() -> string {
  if solved() { return "Solved"; }
  return "Shade the repeats";
}

label "Hitori";
label "Shaded: " + count();
canvas 120, 120, scene() { tap(y / 24 * 5 + x / 24); }
label status();
button "Clear" {
  for i in 0..25 { shaded[i] = false; }
}

// Hitori: tap a square to black it out, again to undo. No number may repeat among the white
// squares of a row or column; black squares never touch side by side; the whites stay joined.
// icon: loop 3 3 21 3 21 21 3 21 fill 3 3 12 3 12 12 3 12 fill 12 12 21 12 21 21 12 21
state nums = [
  4, 1, 6, 5, 3, 3,
  5, 1, 4, 1, 6, 1,
  6, 2, 6, 4, 1, 4,
  2, 2, 5, 1, 3, 3,
  5, 5, 1, 6, 2, 4,
  1, 4, 3, 3, 6, 6
];
state black = [false; 36];

// Square i's neighbour d (0 up, 1 down, 2 left, 3 right), or -1 off the board.
fn near(i: int, d: int) -> int {
  if d == 0 && i >= 6 { return i - 6; }
  if d == 1 && i < 30 { return i + 6; }
  if d == 2 && i % 6 > 0 { return i - 1; }
  if d == 3 && i % 6 < 5 { return i + 1; }
  return -1;
}

// Whether two white squares of a line share a number.
fn repeats() -> bool {
  for i in 0..36 {
    for k in 0..6 {
      let a = i / 6 * 6 + k;
      let b = k * 6 + i % 6;
      if !black[i] && a != i && !black[a] && nums[a] == nums[i] { return true; }
      if !black[i] && b != i && !black[b] && nums[b] == nums[i] { return true; }
    }
  }
  return false;
}

fn touching() -> bool {
  for i in 0..36 {
    for d in 0..4 {
      if black[i] && near(i, d) >= 0 && black[near(i, d)] { return true; }
    }
  }
  return false;
}

// Whether every white square joins the first one, side by side.
fn joined() -> bool {
  let seen = [false; 36];
  let todo = [0; 0];
  let whites = 0;
  for i in 0..36 {
    if !black[i] { whites += 1; }
    if len(todo) == 0 && !black[i] {
      push(todo, i);
      seen[i] = true;
    }
  }
  let k = 0;
  repeat 36 {
    if k < len(todo) {
      let i = todo[k];
      k += 1;
      for d in 0..4 {
        let j = near(i, d);
        if j >= 0 && !black[j] && !seen[j] {
          seen[j] = true;
          push(todo, j);
        }
      }
    }
  }
  return len(todo) == whites;
}

fn solved() -> bool { return !repeats() && !touching() && joined(); }

fn flip(i: int) { black[i] = !black[i]; }

fn scene() {
  rect(0, 0, 120, 120, 8);
  for i in 0..36 {
    let px = i % 6 * 20;
    let py = i / 6 * 20;
    if black[i] {
      rect(px, py, 19, 19, 9);
    } else {
      rect(px, py, 19, 19, 0);
      text(nums[i], px + 9, py + 10, 11, 9);
    }
  }
}

