if solved() { label "Solved!"; }

// Akari: tap a white square to put a bulb there, again to take it away. Light every white square
// with no bulb lighting another, and give each numbered wall that many bulbs beside it.
// icon: ring 12 9 6 fill 9 15 15 15 15 18 9 18 line 10 21 14 21
state board = [
  -2, -2, -2, -2, -2, -2, -2,
  -2, -1, 1, 1, -2, -2, -2,
  -2, -2, 0, -2, -2, -2, -2,
  -2, -2, -2, -2, -2, -2, -2,
  0, 2, -2, -2, -2, 2, -2,
  -2, -2, -2, 0, -2, -2, 3,
  -2, -2, -2, -2, 0, -2, -2
];                        // row by row from the top: -2 white, -1 a wall, 0 to 4 a numbered wall
state bulb = [false; 49];

fn white(c: int, r: int) -> bool {
  return c >= 0 && c < 7 && r >= 0 && r < 7 && board[r * 7 + c] == -2;
}

// How many bulbs other than square i's own light square i: those in a straight line, no wall between.
fn rays(i: int) -> int {
  let n = 0;
  for d in 0..4 {
    let dc = 0;
    let dr = 0;
    if d == 0 { dc = 1; }
    if d == 1 { dc = -1; }
    if d == 2 { dr = 1; }
    if d == 3 { dr = -1; }
    let c = i % 7 + dc;
    let r = i / 7 + dr;
    repeat 6 {
      if white(c, r) {
        if bulb[r * 7 + c] { n += 1; }
        c += dc;
        r += dr;
      } else {
        c = -9;
      }
    }
  }
  return n;
}

fn lit(i: int) -> bool { return bulb[i] || rays(i) > 0; }

fn dark() -> int {
  let n = 0;
  for i in 0..49 {
    if board[i] == -2 && !lit(i) { n += 1; }
  }
  return n;
}

// The bulbs on the squares side by side with wall i.
fn beside(i: int) -> int {
  let n = 0;
  let c = i % 7;
  let r = i / 7;
  if white(c - 1, r) && bulb[i - 1] { n += 1; }
  if white(c + 1, r) && bulb[i + 1] { n += 1; }
  if white(c, r - 1) && bulb[i - 7] { n += 1; }
  if white(c, r + 1) && bulb[i + 7] { n += 1; }
  return n;
}

fn solved() -> bool {
  if dark() > 0 { return false; }
  for i in 0..49 {
    if bulb[i] && rays(i) > 0 { return false; }
    if board[i] >= 0 && beside(i) != board[i] { return false; }
  }
  return true;
}

fn tap(i: int) {
  if board[i] == -2 && !solved() { bulb[i] = !bulb[i]; }
}

fn shade(i: int) -> int {
  if board[i] != -2 { return 8; }
  if lit(i) { return 3; }
  return 0;
}

// Squares 19 units wide on silver lines; walls gray with their numbers; bulbs blue circles, red
// when another bulb lights them.
fn scene() {
  rect(0, 0, 140, 140, 7);
  for i in 0..49 {
    let px = i % 7 * 20;
    let py = i / 7 * 20;
    rect(px, py, 19, 19, shade(i));
    if board[i] >= 0 { text(board[i], px + 9, py + 10, 11, 9); }
    if bulb[i] && rays(i) > 0 { circle(px + 9, py + 9, 6, 1); }
    if bulb[i] && rays(i) == 0 { circle(px + 9, py + 9, 6, 4); }
  }
}

fn status() -> string {
  if solved() { return "Solved"; }
  return "Light every square";
}

label "Akari";
label "Dark: " + dark();
