// Light up: tap a white square for a bulb, again to take it out. Light every white square, no
// bulb shining on another, and each numbered wall touching that many bulbs.
// icon: ring 12 9 6 fill 9 15 15 15 15 18 9 18 line 10 21 14 21
state board = [
  0, -2, -2, 3, -2, -2,
  -2, -2, 3, -2, -2, -2,
  -2, -2, -2, -2, -2, -2,
  -2, -2, -2, -2, -2, -2,
  1, 1, -2, -2, -2, -2,
  -2, 1, -2, -2, -2, 0
];                        // row by row from the top: -2 white, 0 to 4 a wall and its number
state bulb = [false; 36];

fn white(c: int, r: int) -> bool { return c >= 0 && c < 6 && r >= 0 && r < 6 && board[r * 6 + c] == -2; }

// The bulbs that shine on square i from along its row and column, walls stopping them.
fn shine(i: int) -> int {
  let n = 0;
  let dc = [1, -1, 0, 0];
  let dr = [0, 0, 1, -1];
  for d in 0..4 {
    let c = i % 6 + dc[d];
    let r = i / 6 + dr[d];
    let open = true;
    repeat 5 {
      if open && white(c, r) {
        if bulb[r * 6 + c] { n += 1; }
        c += dc[d];
        r += dr[d];
      } else {
        open = false;
      }
    }
  }
  return n;
}

fn touching(i: int) -> int {
  let n = 0;
  let c = i % 6;
  let r = i / 6;
  if white(c - 1, r) && bulb[i - 1] { n += 1; }
  if white(c + 1, r) && bulb[i + 1] { n += 1; }
  if white(c, r - 1) && bulb[i - 6] { n += 1; }
  if white(c, r + 1) && bulb[i + 6] { n += 1; }
  return n;
}

fn solved() -> bool {
  for i in 0..36 {
    if board[i] == -2 && !bulb[i] && shine(i) == 0 { return false; }
    if bulb[i] && shine(i) > 0 { return false; }
    if board[i] >= 0 && touching(i) != board[i] { return false; }
  }
  return true;
}

fn flip(i: int) {
  if board[i] == -2 { bulb[i] = !bulb[i]; }
}

// Walls gray, lit squares yellow, bulbs blue (red when shone on).
fn tint(i: int) -> int {
  if board[i] != -2 { return 8; }
  if bulb[i] && shine(i) > 0 { return 1; }
  if bulb[i] { return 4; }
  if shine(i) > 0 { return 3; }
  return 0;
}

fn scene() {
  let b = [0; 36];
  for i in 0..36 { b[i] = tint(i); }
  pixels(b, 0, 0, 6, 20);
  for i in 0..36 {
    if board[i] >= 0 { text(board[i], i % 6 * 20 + 10, i / 6 * 20 + 10, 12, 9); }
  }
}

