// Tetravex: tap a tile, then another, to swap them. Solved when every pair of touching sides
// shows the same number.
// icon: loop 3 3 21 3 21 21 3 21 line 3 3 21 21 line 21 3 3 21
state sides = [
  9, 5, 0, 4,   0, 4, 0, 2,   9, 2, 8, 4,
  3, 7, 9, 5,   9, 5, 0, 1,   4, 1, 9, 8,
  8, 5, 3, 1,   6, 1, 9, 0,   2, 0, 4, 6
];                        // each place's tile, top row first: its top, right, bottom and left
state ox = [20, 34, 20, 6];   // where each side's number goes on a tile
state oy = [7, 20, 33, 20];
state sel = -1;           // the first tile tapped; -1 none

fn solved() -> bool {
  for i in 0..9 {
    if i % 3 < 2 && sides[i * 4 + 1] != sides[i * 4 + 7] { return false; }
    if i < 6 && sides[i * 4 + 2] != sides[i * 4 + 12] { return false; }
  }
  return true;
}

// The first tap picks a tile, the second swaps it with the one picked.
fn tap(i: int) {
  if sel < 0 {
    sel = i;
    return;
  }
  for s in 0..4 {
    let t = sides[i * 4 + s];
    sides[i * 4 + s] = sides[sel * 4 + s];
    sides[sel * 4 + s] = t;
  }
  sel = -1;
}

// Tiles 39 units wide, each number near its side; the picked tile yellow.
fn scene() {
  for i in 0..9 {
    let x0 = i % 3 * 40;
    let y0 = i / 3 * 40;
    let k = 7;
    if i == sel { k = 3; }
    rect(x0, y0, 39, 39, k);
    for s in 0..4 { text(sides[i * 4 + s], x0 + ox[s], y0 + oy[s], 10, 9); }
  }
}

