    if board[i] == 1 { line(px + 1, py + 17, px + 17, py + 1, 2, 9); }
    if board[i] == 2 { line(px + 1, py + 1, px + 17, py + 17, 2, 9); }
  }
  rect(0, 46, 3, 7, 1);
}

fn status() -> string {
  if solved() { return "Solved"; }
  return "Flip mirrors to reach the target";
}

