// Quarto: put the piece the computer hands you (ringed) on the board, then tap one below to give
// it. Four in a line sharing color, height, shape or fill win for whoever places the fourth.
// icon: ring 7 8 4 dot 17 8 4 fill 3 14 11 14 11 21 3 21 loop 13 14 21 14 21 21 13 21
state board = [-1; 16];   // the piece on each square; -1 empty
state left = [true; 16];  // whether each piece is still below the board
state hand = 0;           // the piece I must place; -1 while I must give one
state over = "";

// A piece's qualities as bits: 1 round, 2 hollow, 4 tall, 8 blue.
fn bit(p: int, b: int) -> bool { return p / b % 2 == 1; }

// Whether the four squares from a by step s share a quality.
fn shares(a: int, s: int) -> bool {
  let b = 1;
  for q in 0..4 {
    let on = 0;
    for k in 0..4 {
      let p = board[a + s * k];
      if p < 0 { return false; }
      if bit(p, b) { on += 1; }
    }
    if on == 0 || on == 4 { return true; }
    b = b * 2;
  }
  return false;
}

fn quarto() -> bool {
  for k in 0..4 {
    if shares(k * 4, 1) || shares(k, 4) { return true; }
  }
  return shares(0, 5) || shares(3, 3);
}

fn full() -> bool {
  for i in 0..16 {
    if board[i] < 0 { return false; }
  }
  return true;
}

// Piece p placed on square i by who; a quarto wins, a full board without one is a draw.
fn put(p: int, i: int, who: string) {
  board[i] = p;
  left[p] = false;
  if quarto() {
    over = who;
  } else if full() {
    over = "Draw";
  }
}

// The computer places piece p where it makes a quarto, else on the first empty square, then hands
// me the first piece left.
fn computer(p: int) {
  let spot = -1;
  for i in 0..16 {
    if spot < 0 && board[i] < 0 {
      board[i] = p;
      if quarto() { spot = i; }
      board[i] = -1;
    }
  }
  for i in 0..16 {
    if spot < 0 && board[i] < 0 { spot = i; }
  }
  put(p, spot, "Computer wins");
  for k in 0..16 {
    if hand < 0 && over == "" && left[k] { hand = k; }
  }
}

fn tap(c: int, r: int) {
  if over != "" { return; }
  let i = r * 4 + c;
  if r < 4 && hand >= 0 && board[i] < 0 {
    put(hand, i, "You win");
    hand = -1;
  } else if r >= 4 && hand < 0 && left[i - 16] {
    computer(i - 16);
  }
}

// Piece p in the cell at x, y: red or blue; tall big, short small; round a circle, square a
// square; hollow with a gray hole.
fn piece(p: int, x: int, y: int) {
  let k = 1;
  if bit(p, 8) { k = 4; }
  let h = 6;
  if bit(p, 4) { h = 10; }
  if bit(p, 1) {
    circle(x + 11, y + 11, h, k);
  } else {
    rect(x + 11 - h, y + 11 - h, h * 2 + 1, h * 2 + 1, k);
  }
  if bit(p, 2) { circle(x + 11, y + 11, 3, 8); }
}

// Cells 23 units wide on gray lines: the board, then the pieces left in their places.
fn scene() {
  rect(0, 0, 96, 192, 8);
  for i in 0..32 {
    let x = i % 4 * 24;
    let y = i / 4 * 24;
    rect(x, y, 23, 23, 0);
    if i < 16 && board[i] >= 0 { piece(board[i], x, y); }
    if i >= 16 && left[i - 16] { piece(i - 16, x, y); }
    if i - 16 == hand { ring(x + 11, y + 11, 11, 1, 3); }
  }
}

fn status() -> string {
  if over != "" { return over; }
  if hand >= 0 { return "Place the ringed piece"; }
  return "Give the computer a piece";
}

