// Quarto for two: tap a piece in the tray to hand it over; the other player taps a square to place
// it, then picks a piece for you. Four in a line sharing color, size, shape or fill wins.
// icon: ring 7 8 4 dot 17 8 4 fill 3 14 11 14 11 21 3 21 loop 13 14 21 14 21 21 13 21
state board = [-1; 16];   // the piece on each square; -1 empty
state left = [true; 16];  // whether each piece is still in the tray
state hand = -1;          // the piece handed over, to be placed; -1 while one is to be picked
state player = 1;         // who picks now; the other places
state winner = 0;

// A piece's qualities as bits: 1 round, 2 hollow, 4 tall, 8 blue.
fn bit(p: int, b: int) -> bool { return p / b % 2 == 1; }

// Whether the four squares from a by step s share a quality.
fn shares(a: int, s: int) -> bool {
  let b = 1;
  for q in 0..4 {
    let on = 0;
    for k in 0..4 {
      let p = board[a + s * k];
      if p < 0 { return false; }
      if bit(p, b) { on += 1; }
    }
    if on == 0 || on == 4 { return true; }
    b = b * 2;
  }
  return false;
}

fn quarto() -> bool {
  for k in 0..4 {
    if shares(k * 4, 1) || shares(k, 4) { return true; }
  }
  return shares(0, 5) || shares(3, 3);
}

// A pick hands a piece over; a tap on an empty square places it, and the placer picks next.
fn tap(c: int, r: int) {
  let i = r * 4 + c;
  if winner > 0 { return; }
  if r >= 4 && hand < 0 && left[i - 16] {
    hand = i - 16;
    left[hand] = false;
    player = 3 - player;
  } else if r < 4 && hand >= 0 && board[i] < 0 {
    board[i] = hand;
    hand = -1;
    if quarto() { winner = player; }
  }
}

// Piece p centered on x, y: red or blue; big or small; a circle or a square; hollow ones holed.
fn piece(p: int, x: int, y: int) {
  let k = 1;
  if bit(p, 8) { k = 4; }
  let h = 6;
  if bit(p, 4) { h = 10; }
  if bit(p, 1) {
    circle(x, y, h, k);
  } else {
    rect(x - h, y - h, h * 2 + 1, h * 2 + 1, k);
  }
  if bit(p, 2) { circle(x, y, h - 3, 0); }
}

// The board over the tray, squares 24 units wide in a checker of blank and silver; the piece
// handed over ringed in its old place.
fn scene() {
  let b = [0; 32];
  for i in 0..32 { b[i] = (i % 4 + i / 4) % 2 * 7; }
  pixels(b, 0, 0, 4, 24);
  for i in 0..32 {
    let x = i % 4 * 24 + 12;
    let y = i / 4 * 24 + 12;
    if i < 16 && board[i] >= 0 { piece(board[i], x, y); }
    if i >= 16 && (left[i - 16] || hand == i - 16) { piece(i - 16, x, y); }
    if i - 16 == hand { ring(x, y, 11, 1, 3); }
  }
}

fn status() -> string {
  if winner > 0 { return "Player " + winner + " wins!"; }
