state cols = [2, 2, 1, 1, 2, 1, 1, 2];
state marks = [0; 64];    // 0 empty, 1 a tent, 2 grass

fn tent(c: int, r: int) -> bool {
  return c >= 0 && c < 8 && r >= 0 && r < 8 && marks[r * 8 + c] == 1;
}

// Whether the tent on square i touches another, side by side or corner to corner.
fn touches(i: int) -> bool {
  for k in 0..9 {
    if k != 4 && tent(i % 8 + k % 3 - 1, i / 8 + k / 3 - 1) { return true; }
  }
  return false;
}

fn count(i: int, step: int) -> int {
  let n = 0;
  for k in 0..8 {
    if marks[i + k * step] == 1 { n += 1; }
  }
  return n;
}

// Each tree, row by row, takes a free tent beside it (left, right, above, below first): when every
// tree gets one, each has a tent of its own. This puzzle's one answer pairs up this way.
fn paired() -> bool {
  let used = [false; 64];
  for i in 0..64 {
    if trees[i] == 1 {
      let got = false;
      let near = [i - 1, i + 1, i - 8, i + 8];
      for k in 0..4 {
        let j = near[k];
        let ok = j >= 0 && j < 64 && (k > 1 || j / 8 == i / 8);
        if !got && ok && marks[j] == 1 && !used[j] {
          used[j] = true;
          got = true;
        }
      }
      if !got { return false; }
    }
  }
  return true;
}

fn solved() -> bool {
  for k in 0..8 {
    if count(k * 8, 1) != rows[k] || count(k, 8) != cols[k] { return false; }
  }
  for i in 0..64 {
    if marks[i] == 1 && touches(i) { return false; }
  }
  return paired();
}

// The colors anew after a change.
fn paint() {
  for i in 0..64 {
    look[i] = trees[i] * 2;
    if marks[i] == 1 && touches(i) { look[i] = 1; } else if marks[i] == 1 { look[i] = 3; }
    if marks[i] == 2 { look[i] = 8; }
  }
}

// The clues of the rows (or of the columns) in one line.
fn clues(of_rows: bool) -> string {
  let s = "";
  for k in 0..8 {
    if of_rows { s = s + " " + rows[k]; } else { s = s + " " + cols[k]; }
  }
  return s;
}

