// Skyscrapers: pick a height, then tap squares to build it. Each row and column holds 1 to 5 once;
// a clue counts the buildings seen from its side, the taller hiding the shorter.
// icon: fill 3 21 3 12 8 12 8 21 fill 10 21 10 4 15 4 15 21 fill 17 21 17 9 21 9 21 21
state top = [2, 3, 0, 2, 0];      // the clues, 0 for none
state bottom = [3, 0, 0, 0, 0];
state lefts = [0, 0, 3, 0, 3];
state rights = [3, 3, 0, 2, 0];
state h = [0; 25];                // the heights built, 0 none
state tint = [0; 25];             // red where a height repeats in its row or column
state shown = [""; 25];           // each square's number
state pen = 1;

// Square k along line n seen from its side: d 0 from above, 1 from below, 2 from the left, 3 from
// the right.
fn at(d: int, n: int, k: int) -> int {
  if d == 0 { return h[k * 5 + n]; }
  if d == 1 { return h[(4 - k) * 5 + n]; }
  if d == 2 { return h[n * 5 + k]; }
  return h[n * 5 + 4 - k];
}

fn seen(d: int, n: int) -> int {
  let tall = 0;
  let count = 0;
  for k in 0..5 {
    if at(d, n, k) > tall {
      tall = at(d, n, k);
      count += 1;
    }
  }
  return count;
}

fn clash(i: int) -> bool {
  if h[i] == 0 { return false; }
  for k in 0..5 {
    let a = i / 5 * 5 + k;
    let b = k * 5 + i % 5;
    if (a != i && h[a] == h[i]) || (b != i && h[b] == h[i]) { return true; }
  }
  return false;
}

fn empty() -> int {
  let n = 0;
  for i in 0..25 {
    if h[i] == 0 { n += 1; }
  }
  return n;
}

fn met(clue: int, d: int, n: int) -> bool { return clue == 0 || seen(d, n) == clue; }

fn solved() -> bool {
  if empty() > 0 { return false; }
  for i in 0..25 {
    if clash(i) { return false; }
  }
  for n in 0..5 {
    if !met(top[n], 0, n) || !met(bottom[n], 1, n) || !met(lefts[n], 2, n) || !met(rights[n], 3, n) {
      return false;
    }
  }
  return true;
}

fn paint() {
  for i in 0..25 {
    tint[i] = 0;
    if clash(i) { tint[i] = 1; }
    shown[i] = "";
    if h[i] > 0 { shown[i] = "" + h[i]; }
  }
}

// One side's clues in a line, - for none.
fn clues(d: int) -> string {
  let s = "";
  for n in 0..5 {
    let v = top[n];
    if d == 1 { v = bottom[n]; }
    if d == 2 { v = lefts[n]; }
    if d == 3 { v = rights[n]; }
    if v > 0 { s = s + " " + v; } else { s = s + " -"; }
  }
  return s;
}

