      let c = clues[d * 4 + n];
      if c > 0 && seen(d, n) != c { return false; }
      for k in 0..4 {
        if at(d, n, k) == 0 { return false; }
        for j in 0..k {
          if at(d, n, j) == at(d, n, k) { return false; }
