              "4", "", "", "", "",
              "", "2", "", "", "",
              "3", "2", "", "", "",
              "", "4", "", "", ""];
state owner = [-1; 25];   // each square's box: its top left square, -1 none
state tint = [0; 25];
state corner = -1;

fn good(o: int) -> bool {
  let size = 0;
  let count = 0;
  let n = 0;
  for i in 0..25 {
    if owner[i] == o {
      size += 1;
      if nums[i] != "" {
        count += 1;
        n = parse(nums[i], 0);
      }
    }
  }
  return count == 1 && n == size;
}

fn solved() -> bool {
  for i in 0..25 {
    if owner[i] < 0 || !good(owner[i]) { return false; }
  }
  return true;
}

// The box with corners a and b, if it overlaps no other.
fn draw(a: int, b: int) {
  let c0 = min(a % 5, b % 5);
  let r0 = min(a / 5, b / 5);
  for pass in 0..2 {
    for i in 0..25 {
      if i % 5 >= c0 && i % 5 <= max(a % 5, b % 5) && i / 5 >= r0 && i / 5 <= max(a / 5, b / 5) {
        if pass == 0 && owner[i] >= 0 { return; }
        if pass == 1 { owner[i] = r0 * 5 + c0; }
      }
    }
  }
}

fn tap(i: int) {
  if corner >= 0 {
    draw(corner, i);
    corner = -1;
  } else if owner[i] >= 0 {
    let o = owner[i];
    for k in 0..25 {
      if owner[k] == o { owner[k] = -1; }
    }
  } else {
    corner = i;
  }
  for k in 0..25 {
    tint[k] = 0;
    if owner[k] >= 0 { tint[k] = owner[k] % 6 + 1; }
  }
  if corner >= 0 { tint[corner] = 8; }
}

