// A quarter turn toward dx, dy; then a fall if any square under it has no floor.
fn turn(dx: int, dy: int) {
  if won() { return; }
  let along = (way == 1 && dx != 0) || (way == 2 && dy != 0);
  if way == 0 {
    if dx > 0 || dy > 0 { bx += dx; by += dy; } else { bx += dx * 2; by += dy * 2; }
    if dx != 0 { way = 1; } else { way = 2; }
  } else if along {
    if dx > 0 || dy > 0 { bx += dx * 2; by += dy * 2; } else { bx += dx; by += dy; }
    way = 0;
