fn on(x: int, y: int) -> bool { return x >= 0 && x < 8 && y >= 0 && y < 8; }

// How many pieces are on the line through a running dx, dy (both ways).
fn count(a: int, dx: int, dy: int) -> int {
  let n = 1;
  for k in 1..8 {
    if on(a % 8 + dx * k, a / 8 + dy * k) && board[a + (dy * 8 + dx) * k] > 0 { n += 1; }
    if on(a % 8 - dx * k, a / 8 - dy * k) && board[a - (dy * 8 + dx) * k] > 0 { n += 1; }
  }
  return n;
}

// Where the piece on a lands going dx, dy; -1 if it may not.
fn target(a: int, dx: int, dy: int) -> int {
  let n = count(a, dx, dy);
  if !on(a % 8 + dx * n, a / 8 + dy * n) { return -1; }
  for k in 1..n {
    let v = board[a + (dy * 8 + dx) * k];
    if v > 0 && v != board[a] { return -1; }
  }
  let b = a + (dy * 8 + dx) * n;
  if board[b] == board[a] { return -1; }
  return b;
}

fn can(a: int, b: int) -> bool {
  if a < 0 { return false; }
  for d in 0..9 {
    if d != 4 && target(a, d % 3 - 1, d / 3 - 1) == b { return true; }
