  repeat 64 {
    if len(todo) > 0 {
      let i = todo[len(todo) - 1];
      remove(todo, len(todo) - 1);
      for d in 0..9 {
        let x = i % 8 + d % 3 - 1;
        let y = i / 8 + d / 3 - 1;
        if on(x, y) && board[y * 8 + x] == p && !seen[y * 8 + x] {
          seen[y * 8 + x] = true;
          push(todo, y * 8 + x);
        }
      }
    }
  }
  for i in 0..64 {
    if board[i] == p && !seen[i] { return false; }
  }
  return true;
}

