// Liar's dice: type how many and which number and press Bid; the computer calls Liar or bids one
// more, and Liar calls its bid. A wrong bid or call costs a die. (Fixed dice, for testing.)
// icon: loop 3 8 13 8 13 18 3 18 dot 6 11 1 dot 10 15 1 loop 11 4 21 4 21 14 11 14 dot 16 9 1
state mine = [1, 2, 6];         // the dice each round, the last taken away when one is lost
state its = [2, 2, 3];
state nme = 3;
state nit = 3;
state q = 0;                    // the bid on the table: q dice showing f; 0 before one
state f = 0;
state many = "";
state face = "";
state news = "";

fn count(k: int) -> int {
  let n = 0;
  for i in 0..nme {
    if mine[i] == k { n += 1; }
  }
  for i in 0..nit {
    if its[i] == k { n += 1; }
  }
  return n;
}

fn own(k: int) -> int {
  let n = 0;
  for i in 0..nit {
    if its[i] == k { n += 1; }
  }
  return n;
}

fn over() -> bool { return nme == 0 || nit == 0; }

// The bid is called: if it holds the caller loses a die, else the bidder; a new round.
fn called(byMe: bool) {
  if (count(f) >= q) == byMe {
    nme -= 1;
    news = "You lose a die";
  } else {
    nit -= 1;
    news = "The computer loses a die";
  }
  if nme == 0 { news = "You lose"; }
  if nit == 0 { news = "You win"; }
  q = 0;
  f = 0;
}

fn bid() {
  let nq = parse(many, 0);
  let nf = parse(face, 0);
  if over() || nq < 1 || nf < 1 || nf > 6 || nq < q || (nq == q && nf <= f) { return; }
  q = nq;
  f = nf;
  if q > own(f) + 2 {
    called(false);
  } else {
    q += 1;
    news = "The computer bids " + q + " x " + f;
  }
}

fn dice() -> string {
  let s = "Your dice:";
  for i in 0..nme { s = s + " " + mine[i]; }
  return s;
}

