  let d = 1;
  for k in c..7 { d = d * 10; }
  return lots[(level - 1) * 8 + r] / d % 10;
}

fn home() {
  for i in 0..64 {
    if at(i % 8, i / 8) == 4 {
      bx = i % 8;
      by = i / 8;
    }
  }
  vx = 0;
  vy = 0;
  mag = 0;
}

fn clamp(v: int) -> int { return min(2, max(-2, v)); }

// The ball enters square (c, r): 1 if it falls in a pit, 2 if it drops into the hole, else 0.
fn enter(c: int, r: int) -> int {
  bx = c;
  by = r;
  if at(c, r) == 2 { return 1; }
  if at(c, r) == 3 { return 2; }
  return 0;
}

fn roll() -> int {
  let n = abs(vx);
  for k in 0..n {
    if vx != 0 {
      let nx = bx + vx / abs(vx);
      if at(nx, by) == 1 {
        vx = 0;
      } else if enter(nx, by) > 0 {
        return enter(bx, by);
      }
    }
  }
  n = abs(vy);
  for k in 0..n {
    if vy != 0 {
      let ny = by + vy / abs(vy);
      if at(bx, ny) == 1 {
        vy = 0;
      } else if enter(bx, ny) > 0 {
        return enter(bx, by);
      }
    }
  }
  return 0;
}

every speed {
  vx = clamp(vx + mx[mag]);
  vy = clamp(vy + my[mag]);
  let r = roll();
  if r == 1 {
    lives -= 1;
    if lives == 0 {
      said = "Game over";
      speed = 0;
    } else {
      home();
    }
  } else if r == 2 && level == 2 {
    said = "You win";
    speed = 0;
  } else if r == 2 {
    level = 2;
    home();
  }
}

fn pull(m: int) { if speed > 0 { mag = m; } }

