  cells[17] = 8;
  cells[27] = 8;
  cells[35] = 8;
  for f in 0..3 {
    for c in 0..3 {
      if !served[f] && pressed[f * 3 + c] { cells[f * 18 + 3 + c] = 6; }
      if !served[f] && !pressed[f * 3 + c] { cells[f * 18 + 3 + c] = tints[f]; }
    }
  }
  cells[18 + sausage()] = 1;
  cells[cy * 9 + cx] = 4;
  pixels(cells, 0, 0, 9, 12);
  if result != "" { text(result, 54, 30, 12, 11); }
}

