// Burger Drop: walk with left and right, climb with up and down at the ends. Walk over a piece to
// drop it a floor, knocking down the one it lands on; get all three onto the plate.
// icon: fill 4 10 6 5 18 5 20 10 line 3 13 21 13 fill 4 16 20 16 19 20 5 20
state pf = [0, 1, 2];           // each piece's floor, 0 the top; 3 on the plate
state walked = [false; 9];      // each piece's squares walked over on its floor
state cf = 2;                   // the chef's floor and column (0 to 6)
state cx = 0;
state on = false;               // a game runs

fn served() -> bool { return pf[0] == 3 && pf[1] == 3 && pf[2] == 3; }

// Piece p drops a floor; the piece it lands on drops too, and so on down.
fn fall(p: int) {
  let cur = p;
  for k in 0..3 {
    if cur >= 0 {
      let f = pf[cur] + 1;
      let under = -1;
      for q in 0..3 {
        if f < 3 && pf[q] == f { under = q; }
      }
      pf[cur] = f;
      for i in 0..3 { walked[cur * 3 + i] = false; }
      cur = under;
    }
  }
}

fn walk(dx: int, dy: int) {
  if !on || served() { return; }
  cx = min(6, max(0, cx + dx));
  if cx == 0 || cx == 6 { cf = min(2, max(0, cf + dy)); }
  for p in 0..3 {
    if pf[p] == cf && cx >= 2 && cx <= 4 {
      walked[p * 3 + cx - 2] = true;
      if walked[p * 3] && walked[p * 3 + 1] && walked[p * 3 + 2] { fall(p); }
    }
  }
}

on key "left" { walk(-1, 0); }
on key "right" { walk(1, 0); }
on key "up" { walk(0, -1); }
