// Hill Climb: right or Gas speeds the car up (3 at most) and burns fuel; downhill speeds it up,
// uphill slows it. Reach the right edge on two levels before the fuel runs out.
// icon: fill 4 13 9 9 16 9 20 13 20 17 4 17 ring 8 18 3 ring 17 18 3
state tops = [6, 6, 5, 4, 4, 5, 6, 6, 5, 4, 3, 3, 2, 2, 3, 3,
              6, 5, 4, 3, 4, 5, 6, 5, 4, 3, 2, 2, 3, 4, 3, 2];
state fuels = [6, 7];           // each level's fuel
state level = 1;
state cx = 0;
state speed = 0;
state fuel = 6;
state step = 0;                 // ms a step; 0 while no game runs
state result = "";

fn top(c: int) -> int { return tops[(level - 1) * 16 + c]; }

fn begin() {
  cx = 0;
  speed = 0;
  fuel = fuels[level - 1];
}

fn start() {
  level = 1;
  begin();
  result = "";
  step = 300;
}

fn gas() {
  if step > 0 && fuel > 0 && speed < 3 {
    speed += 1;
    fuel -= 1;
  }
}

every step {
  if speed > 0 {
    cx += 1;
    speed = min(3, max(0, speed + top(cx) - top(cx - 1)));
  }
  if cx == 15 && level == 2 {
    result = "You win";
    step = 0;
  } else if cx == 15 {
    level = 2;
    begin();
  } else if speed == 0 && fuel == 0 {
    result = "Game over";
    step = 0;
  }
}

on key "right" { gas(); }

fn scene() {
  let cells = [-1; 128];
  for c in 0..16 {
    for r in top(c)..8 { cells[r * 16 + c] = 2; }
  }
  cells[(top(cx) - 1) * 16 + cx] = 4;
  pixels(cells, 0, 0, 16, 10);
  if result != "" { text(result, 80, 15, 12, 11); }
}

label "Hill Climb";
label "Level: " + level + "   Speed: " + speed + "   Fuel: " + fuel;
canvas 160, 80, scene();
row {
  if step == 0 { button "Start" { start(); } }
  button "Gas" { gas(); }
}

// Hill Climb: the right arrow is the gas: a burst of speed for 1 fuel. Hills slow you going up
// and speed you up coming down; out of fuel and stopped, the game is over.
// icon: fill 4 13 9 9 16 9 20 13 20 17 4 17 ring 8 18 3 ring 17 18 3
state pos = 0;                  // how far, a column a step
state v = 0;                    // speed
state fuel = 10;
state speed = 0;                // ms a step; 0 while no game runs
state over = false;
state played = false;           // a game has begun: the road shows

// The hills: up for 5 columns, down for 5.
fn height(p: int) -> int { return 5 - abs(p % 10 - 5); }

// A step on: uphill costs 2 speed, downhill gives 1.
every speed {
  if v > 0 {
    pos += 1;
    if height(pos) > height(pos - 1) { v -= 2; } else { v += 1; }
    v = max(0, v);
  }
  if v == 0 && fuel == 0 {
    over = true;
    speed = 0;
  }
}

on key "right" {
  if speed > 0 && fuel > 0 {
    fuel -= 1;
    v += 2;
  }
}

// The hills ahead, a column each, and the car on the first.
fn scene() {
  let cells = [-1; 60];
  for i in 0..60 {
    if i / 10 >= 6 - height(pos + i % 10) { cells[i] = 2; }
  }
  cells[50 - height(pos) * 10] = 4;
  pixels(cells, 0, 0, 10, 10);
}

label "Hill Climb";
if played {
  label "Fuel: " + fuel + "   Distance: " + pos;
  canvas 100, 60, scene();
}
if over { label "Game over"; }
if speed == 0 {
  button "Start" {
    pos = 0;
    v = 0;
    fuel = 10;
    over = false;
    played = true;
    speed = 200;
  }
}

// Flight Control: tap a plane to pick it, then the arrows turn it. Bring all four down on the
// green runway; planes turn around at the edges, and two on one square crash.
// icon: line 12 2 12 21 fill 2 14 12 7 22 14 12 11 fill 7 21 12 17 17 21
state when = [1, 5, 9, 13];     // each plane's arrival: step, square and the way it flies
state ex = [0, 9, 3, 9];
state ey = [2, 6, 0, 1];
state edx = [1, -1, 0, -1];
state edy = [0, 0, 1, 0];
state px = [0; 0];              // the planes in the air, and which of the four each is
state py = [0; 0];
state dx = [0; 0];
state dy = [0; 0];
state id = [0; 0];
state picked = -1;
state made = 0;
state landed = 0;
state steps = 0;
state speed = 0;                // ms a step; 0 while no game runs
state result = "";

fn start() {
  clear(px);
  clear(py);
  clear(dx);
  clear(dy);
  clear(id);
  picked = -1;
  made = 0;
  landed = 0;
  steps = 0;
  result = "";
  speed = 400;
}

fn runway(i: int) -> bool { return py[i] == 9 && px[i] >= 4 && px[i] <= 6; }

// One plane's move: at an edge it turns around.
fn fly(i: int) {
  if px[i] + dx[i] < 0 || px[i] + dx[i] > 9 { dx[i] = -dx[i]; }
  if py[i] + dy[i] < 0 || py[i] + dy[i] > 9 { dy[i] = -dy[i]; }
  px[i] += dx[i];
  py[i] += dy[i];
}

fn crashed() -> bool {
  for i in 0..len(px) {
    for j in i + 1..len(px) {
      if px[i] == px[j] && py[i] == py[j] { return true; }
    }
  }
  return false;
}

every speed {
  steps += 1;
  for i in 0..len(px) { fly(i); }
  let i = 0;
  for n in 0..len(px) {
    if i < len(px) && runway(i) {
      remove(px, i);
      remove(py, i);
      remove(dx, i);
      remove(dy, i);
      remove(id, i);
      landed += 1;
    } else {
      i += 1;
    }
  }
  if made < 4 && when[made] == steps {
    push(px, ex[made]);
    push(py, ey[made]);
    push(dx, edx[made]);
    push(dy, edy[made]);
    push(id, made);
    made += 1;
  }
  if crashed() {
    result = "Game over";
    speed = 0;
  } else if landed == 4 {
    result = "You win";
    speed = 0;
  }
}

fn pick(c: int, r: int) {
  for i in 0..len(px) {
    if speed > 0 && px[i] == c && py[i] == r { picked = id[i]; }
  }
}

fn turn(x: int, y: int) {
  for i in 0..len(px) {
    if speed > 0 && id[i] == picked {
      dx[i] = x;
      dy[i] = y;
    }
  }
}

on key "left" { turn(-1, 0); }
on key "right" { turn(1, 0); }
on key "up" { turn(0, -1); }
on key "down" { turn(0, 1); }

fn scene() {
  let cells = [-1; 100];
  for c in 4..7 { cells[90 + c] = 2; }
  for i in 0..len(px) {
    cells[py[i] * 10 + px[i]] = 3;
    if id[i] == picked { cells[py[i] * 10 + px[i]] = 6; }
  }
  pixels(cells, 0, 0, 10, 10);
  if result != "" { text(result, 50, 40, 14, 11); }
}

label "Flight Control";
label "Landed: " + landed;
canvas 100, 100, scene() { pick(x / 10, y / 10); }
if speed == 0 { button "Start" { start(); } }

// Flight Control: a plane joins the line every second; press 1, 2 or 3 to land the first in line
// on that runway. A landing takes 3 seconds: a busy runway is a crash, and 5 waiting is too many.
// icon: line 12 2 12 21 fill 2 14 12 7 22 14 12 11 fill 7 21 12 17 17 21
state t = 0;                    // tenths of a second since Start
state waiting = 0;
state busy = [0, 0, 0];         // tenths each runway's landing still takes
state landed = 0;
state speed = 0;                // 100 while a game runs, else 0
state result = "";

every speed {
  t += 1;
  for r in 0..3 {
    if busy[r] > 0 {
      busy[r] -= 1;
      if busy[r] == 0 { landed += 1; }
    }
  }
  if t % 10 == 0 { waiting += 1; }
  if waiting >= 5 {
    result = "Game over: 5 waiting";
    speed = 0;
  }
}

fn send(r: int) {
  if speed > 0 && waiting > 0 && busy[r] > 0 {
    result = "Crash! Game over";
    speed = 0;
  } else if speed > 0 && waiting > 0 {
    busy[r] = 30;
    waiting -= 1;
  }
}

on key "1" { send(0); }
on key "2" { send(1); }
on key "3" { send(2); }

// The line of planes waiting, and the three runways, each with its plane while it lands.
fn scene() {
  for i in 0..waiting { circle(10 + i * 12, 8, 4, 3); }
  for r in 0..3 {
    rect(5 + r * 30, 30, 24, 6, 2);
    if busy[r] > 0 { circle(17 + r * 30, 33, 3, 4); }
  }
}

label "Flight Control";
label "Landed: " + landed + "   Waiting: " + waiting;
canvas 95, 40, scene();
if result != "" { label result; }
if speed == 0 {
  button "Start" {
    t = 0;
    waiting = 1;
    busy = [0, 0, 0];
    landed = 0;
    result = "";
    speed = 100;
  }
}

// Rail Switch: up and down set the switch; send each train to the station of its color.
// Three trains at the wrong station and the game is over.
// icon: line 2 16 10 16 line 10 16 22 16 line 10 16 18 6 22 6 line 6 12 6 20 line 15 12 15 20
state when = [1, 5, 9, 13, 17, 21];     // when each train comes in, and its color
state tints = [1, 4, 2, 4, 1, 2];
state stations = [1, 2, 4];             // the stations' colors, top to bottom
state tc = [0; 0];                      // the trains: column, branch (-1 up, 0, 1 down), color
state tb = [0; 0];
state tk = [0; 0];
state switch = 0;
state made = 0;
state arrived = 0;
state score = 0;
state wrong = 0;
state steps = 0;
state speed = 0;                        // ms a step; 0 while no game runs
state result = "";

// The row of column c on branch b.
fn rowof(c: int, b: int) -> int {
  if c <= 4 { return 3; }
  if c == 5 { return 3 + b; }
  return 3 + 2 * b;
}

fn start() {
  clear(tc);
  clear(tb);
  clear(tk);
  switch = 0;
  made = 0;
  arrived = 0;
  score = 0;
  wrong = 0;
  steps = 0;
  result = "";
  speed = 300;
}

fn turn(d: int) {
  if speed > 0 { switch = min(1, max(-1, switch + d)); }
}

fn aim(b: int) {
  if speed > 0 { switch = b; }
}

every speed {
  steps += 1;
  let i = 0;
  for n in 0..len(tc) {
    if tc[i] == 4 { tb[i] = switch; }
    tc[i] += 1;
    if tc[i] == 11 {
      if stations[tb[i] + 1] == tk[i] { score += 1; } else { wrong += 1; }
      arrived += 1;
      remove(tc, i);
      remove(tb, i);
      remove(tk, i);
    } else {
      i += 1;
    }
  }
  if made < 6 && when[made] == steps {
    push(tc, 0);
    push(tb, 0);
    push(tk, tints[made]);
    made += 1;
  }
  if wrong == 3 {
    result = "Game over";
    speed = 0;
  } else if arrived == 6 {
    result = "You win";
    speed = 0;
  }
}

on key "up" { turn(-1); }
on key "down" { turn(1); }

fn scene() {
  let cells = [-1; 84];
  for c in 0..11 { cells[36 + c] = 8; }
  for c in 6..11 {
    cells[12 + c] = 8;
    cells[60 + c] = 8;
  }
  cells[29] = 8;
  cells[53] = 8;
  for b in 0..3 { cells[(1 + 2 * b) * 12 + 11] = stations[b]; }
  cells[(3 + switch) * 12 + 5] = 3;
  for i in 0..len(tc) { cells[rowof(tc[i], tb[i]) * 12 + tc[i]] = tk[i]; }
  pixels(cells, 0, 0, 12, 10);
  if result != "" { text(result, 60, 60, 12, 11); }
}

label "Rail Switch";
label "Score: " + score + "   Wrong: " + wrong;
// A tap points the switch at the branch on that side: above the line, on it or below it.
canvas 120, 70, scene() {
  if y < 30 { aim(-1); } else if y < 40 { aim(0); } else { aim(1); }
}
if speed == 0 { button "Start" { start(); } }

// Rail Switch: a train every 3 seconds; space flips the switch between the red and blue
// stations. Send each train home: three at the wrong station end the game.
// icon: line 2 12 12 12 line 12 12 22 4 line 12 12 22 20 dot 21 4 2 dot 21 20 2
state colors = [1, 1, 4, 1, 4, 4];      // the trains' colors in turn: 1 red, 4 blue
state t = 0;                            // tenths of a second since Start
state sw = 1;                           // the station the switch points at
state went = [0; 0];                    // past the switch, not yet in: the station each goes to
state score = 0;
state wrong = 0;
state speed = 0;                        // 100 while a game runs, else 0

// Train k comes at 30k tenths, passes the switch 20 later and is in 20 after that.
every speed {
  t += 1;
  if t % 30 == 20 { push(went, sw); }
  if t % 30 == 10 && t >= 40 {
    if went[0] == colors[(t - 40) / 30 % 6] { score += 1; } else { wrong += 1; }
    remove(went, 0);
  }
  if wrong == 3 { speed = 0; }
}

on key "space" {
  if speed > 0 { sw = 5 - sw; }
}

// The next train on its way to the switch, and the station the switch points at, in its color.
fn scene() {
  if speed > 0 { circle(t % 30 * 3, 20, 3, colors[t / 30 % 6]); }
  circle(92, 4 + sw * 8, 4, sw);
}

label "Rail Switch";
label "Score: " + score;
canvas 100, 40, scene();
if wrong == 3 { label "Game over"; }
if speed == 0 {
  button "Start" {
    t = 0;
    sw = 1;
    clear(went);
    score = 0;
    wrong = 0;
    speed = 100;
  }
}

// Planet Shield: left and right turn the blue shield around the planet. Block the meteors
// coming from every side; three hits and the planet is lost.
// icon: dot 12 12 5 arc 12 12 9 300 60 line 4 4 7 7 line 20 20 17 17
state ox = [0, 1, 1, 1, 0, -1, -1, -1];      // the 8 squares around the planet, clockwise from
state oy = [-1, -1, 0, 1, 1, 1, 0, -1];      // the top: their offsets
state when = [1, 3, 5, 7, 9, 11, 13, 15];    // each meteor's step and side
state from = [0, 2, 4, 6, 1, 5, 7, 3];
state md = [0; 0];                           // the meteors: side, and squares from the planet
state mr = [0; 0];
state shield = 0;
state steps = 0;
state made = 0;
state gone = 0;
state blocked = 0;
state health = 3;
state speed = 0;                             // ms a step; 0 while no game runs
state result = "";

fn start() {
  clear(md);
  clear(mr);
  shield = 0;
  steps = 0;
  made = 0;
  gone = 0;
  blocked = 0;
  health = 3;
  result = "";
  speed = 300;
}

fn ends() {
  if health == 0 {
    result = "Game over";
    speed = 0;
  } else if gone == 8 {
    result = "You win";
    speed = 0;
  }
}

fn lose(i: int) {
  remove(md, i);
  remove(mr, i);
  gone += 1;
}

// Every meteor on the shield's square is destroyed.
fn block() {
  let i = 0;
  for n in 0..len(md) {
    if i < len(md) && mr[i] == 1 && md[i] == shield {
      lose(i);
      blocked += 1;
    } else {
      i += 1;
    }
  }
}

fn put(i: int) {
  if speed > 0 {
    shield = i;
    block();
    ends();
  }
}

// A tap puts the shield on the side of the planet it is on.
fn aim(c: int, r: int) {
  for i in 0..8 {
    if ox[i] == max(-1, min(1, c - 4)) && oy[i] == max(-1, min(1, r - 4)) { put(i); }
  }
}

every speed {
  steps += 1;
  for i in 0..len(mr) { mr[i] -= 1; }
  block();
  if len(mr) > 0 && mr[0] == 0 {
    lose(0);
    health -= 1;
  }
  if made < 8 && when[made] == steps {
    push(md, from[made]);
    push(mr, 4);
    made += 1;
  }
  ends();
}

on key "right" { put((shield + 1) % 8); }
on key "left" { put((shield + 7) % 8); }

fn scene() {
  let cells = [-1; 81];
  cells[40] = 2;
  cells[(4 + oy[shield]) * 9 + 4 + ox[shield]] = 4;
  for i in 0..len(md) { cells[(4 + mr[i] * oy[md[i]]) * 9 + 4 + mr[i] * ox[md[i]]] = 1; }
  pixels(cells, 0, 0, 9, 10);
  if result != "" { text(result, 45, 20, 12, 11); }
}

label "Planet Shield";
label "Blocked: " + blocked + "   Health: " + health;
canvas 90, 90, scene() { aim(x / 10, y / 10); }
if speed == 0 { button "Start" { start(); } }

// Planet Shield: the arrows turn the shield to the side a meteor comes from. A meteor every
// 2 seconds: above, right, below, left. Three hits on the planet and it is over.
// icon: dot 12 12 5 arc 12 12 9 300 60 line 4 4 7 7 line 20 20 17 17
state off = [-7, 1, 7, -1];     // a square toward each side, up, right, down, left
state t = 0;                    // tenths of a second since Start
state shield = 0;
state score = 0;
state lives = 3;
state speed = 0;                // 100 while a game runs, else 0

// Meteor k leaves at 20k tenths from side k % 4 and arrives 20 later.
every speed {
  t += 1;
  if t % 20 == 0 && shield == (t / 20 - 1) % 4 {
    score += 1;
  } else if t % 20 == 0 {
    lives -= 1;
  }
  if lives == 0 { speed = 0; }
}

fn turn(side: int) {
  if speed > 0 { shield = side; }
}

on key "up" { turn(0); }
on key "right" { turn(1); }
on key "down" { turn(2); }
on key "left" { turn(3); }

// The planet in the middle of 7 x 7 squares, the shield beside it, the meteor on its way in.
fn scene() {
  let cells = [-1; 49];
  cells[24] = 2;
  cells[24 + off[shield]] = 4;
  if speed > 0 { cells[24 + off[t / 20 % 4] * (3 - t % 20 / 7)] = 1; }
  pixels(cells, 0, 0, 7, 10);
}

label "Planet Shield";
label "Score: " + score + "   Lives: " + lives;
canvas 70, 70, scene();
if lives == 0 { label "Game over"; }
if speed == 0 {
  button "Start" {
    t = 0;
    score = 0;
    lives = 3;
    speed = 100;
  }
}

// Hotel: Start the week; tap a free (green) room to check the next guest in, End day to collect
// $10 a guest a night, tap a dirty (red) room to clean it ($5), Build more rooms ($30). 7 days.
// icon: line 3 5 3 20 fill 3 11 21 11 21 16 3 16 line 21 16 21 20 dot 8 8 3
state kind = [0; 8];        // 2 rows of 4 rooms: 0 not built, 1 free, 2 a guest, 3 dirty
state nights = [0; 8];      // the nights each room's guest still stays
state day = 1;
state money = 40;
state waiting = 0;
state lost = 0;
state guests = 0;           // guests checked in this week
state playing = false;
state over = false;

fn start() {
  for i in 0..8 {
    kind[i] = 0;
    nights[i] = 0;
    if i < 4 { kind[i] = 1; }
  }
  day = 1;
  money = 40;
  waiting = 3;
  lost = 0;
  guests = 0;
  playing = true;
  over = false;
}

// A tap: a free room takes the next guest (1, 2, 3 nights in turn), a dirty one is cleaned.
fn tap(i: int) {
  if !playing { return; }
  if kind[i] == 1 && waiting > 0 {
    kind[i] = 2;
    nights[i] = guests % 3 + 1;
    guests += 1;
    waiting -= 1;
  } else if kind[i] == 3 && money >= 5 {
    kind[i] = 1;
    money -= 5;
  }
}

fn build() {
  if !playing || money < 30 { return; }
  for i in 4..8 {
    if kind[i] == 0 {
      kind[i] = 1;
      money -= 30;
      return;
    }
  }
}

// The night: the waiting leave, each guest pays, and those done leave a dirty room.
fn night() {
  if !playing { return; }
  lost += waiting;
  waiting = 0;
  for i in 0..8 {
    if kind[i] == 2 {
      money += 10;
      nights[i] -= 1;
      if nights[i] == 0 { kind[i] = 3; }
    }
  }
  if day == 7 {
    playing = false;
    over = true;
  } else {
    day += 1;
    waiting = 3;
  }
}

// The rooms, 4 x 2 squares of 30 units: not built gray, free green, a guest blue, dirty red.
fn scene() {
  let tint = [8, 2, 4, 1];
  let cells = [8; 8];
  for i in 0..8 { cells[i] = tint[kind[i]]; }
  pixels(cells, 0, 0, 4, 30);
  if over { text("Week over", 60, 30, 12, 11); }
}

label "Hotel";
label "Day " + day + "   Money " + money;
label "Waiting " + waiting + "   Lost " + lost;
canvas 120, 60, scene() { tap((y / 30) * 4 + x / 30); }
row {
  button "End day" { night(); }
  button "Build" { build(); }
  if !playing { button "Start" { start(); } }
}

// Hotel tycoon: each room earns $15 a night. End night to collect; Build a room for $60.
// icon: loop 5 21 5 7 12 3 19 7 19 21 line 10 21 10 15 14 15 14 21
state money = 100;
state rooms = 2;

label "Hotel tycoon";
label "Money $" + money + "   Rooms " + rooms;
row {
