}

// Detective: walk the manor with the arrows (or tap a square beside you) to find the clues, then
// accuse the Butler, Cook, Maid or Gardener once 2 clues are found. 12 moves.
// icon: ring 10 10 7 line 15 15 21 21
state px = 2;               // where the detective stands
state py = 4;
state moves = 12;
state hidden = [true, true, true];   // the clues not yet found
state cx = [0, 0, 4];
state cy = [2, 0, 0];
state reads = ["Not the Gardener", "Not the Cook", "Not the Maid"];
state notes = [""; 0];      // the notebook: clues found, in order
state verdict = "";         // "" while the case is open

fn open() -> bool { return verdict == ""; }

fn step(dx: int, dy: int) {
  let nx = px + dx;
  let ny = py + dy;
  if !open() || moves == 0 || nx < 0 || nx > 4 || ny < 0 || ny > 4 { return; }
  px = nx;
  py = ny;
  moves -= 1;
  for k in 0..3 {
    if hidden[k] && cx[k] == px && cy[k] == py {
      hidden[k] = false;
      push(notes, reads[k]);
    }
  }
}

fn tap(c: int, r: int) {
