fn clue(i: int) -> bool { return i == 0 || i == 4 || i == 12 || i == 20 || i == 24; }

fn over() -> bool { return found == 5 || left == 0; }

// A search of a square not yet searched.
fn search(i: int) {
  if over() || searched[i] { return; }
  searched[i] = true;
  left -= 1;
  if clue(i) { found += 1; }
}

fn again() {
