// Deck: type a title and Add a slide; Prev and Next (or the arrows) page through; Move left
// reorders, Delete removes; Play shows them all from the first, a slide every 2 seconds.
// icon: loop 3 4 21 4 21 16 3 16 line 12 16 12 21 line 8 21 16 21
state titles = [""; 0];
