state typed = "";
state speed = 0;            // ms a slide while playing

fn add() {
  if typed == "" { return; }
  push(titles, typed);
  at = len(titles) - 1;
  typed = "";
}

fn go(d: int) {
  if len(titles) > 0 { at = min(len(titles) - 1, max(0, at + d)); }
}

fn earlier() {
  if at > 0 && at < len(titles) {
    let t = titles[at - 1];
    titles[at - 1] = titles[at];
    titles[at] = t;
    at -= 1;
  }
}

fn drop() {
  if len(titles) == 0 { return; }
  remove(titles, at);
  if at >= len(titles) { at = max(0, len(titles) - 1); }
}

fn play() {
  if len(titles) == 0 { return; }
  at = 0;
  speed = 2000;
  if len(titles) == 1 { speed = 0; }
}

every speed {
  go(1);
  if at >= len(titles) - 1 { speed = 0; }
}

fn where() -> string {
  if len(titles) == 0 { return "No slides"; }
  return "Slide " + (at + 1) + " of " + len(titles);
}

