fn cost(k: int) -> int {
  if k == 2 { return 10; }
  if k == 3 { return 15; }
  return 20;
}

fn named(k: int) -> string {
  if k == 2 { return "Farm"; }
  if k == 3 { return "House"; }
  return "Barracks";
}

fn count(k: int) -> int {
  let n = 0;
  for i in 0..24 {
