state map = [8, 8, 8, 8, 8, 8, 8, 8, 8, 8, 8, 8, 5, 8, 8, 8, 8, 8, 8, 8, 8, 8, 8, 8, 8];
                            // 5 x 5: 8 not yours, 2 yours, 5 the castle in the middle
state gold = 5;

fn mine(c: int, r: int) -> bool {
  if c < 0 || c > 4 || r < 0 || r > 4 { return false; }
  return map[r * 5 + c] != 8;
}

fn lands() -> int {
  let n = 0;
  for i in 0..25 {
    if map[i] != 8 { n += 1; }
  }
  return n;
}

// A land not yet yours, beside one that is.
fn conquer(c: int, r: int) {
  let beside = mine(c - 1, r) || mine(c + 1, r) || mine(c, r - 1) || mine(c, r + 1);
  if !mine(c, r) && beside && gold >= 3 {
    map[r * 5 + c] = 2;
    gold -= 3;
  }
}

