}

// Light the bulb: tap squares to lay wire from the battery (top left) to the bulb (bottom right);
// it lights up yellow when a line of wire joins them.
// icon: ring 12 9 6 line 9 15 9 19 15 19 15 15 line 10 21 14 21
state look = [0; 36];       // 6 x 6 squares: 4 wire; the bulb 3 once lit
state signs = ["+", "", "", "", "", "", "", "", "", "", "", "", "", "", "", "", "", "", "", "",
               "", "", "", "", "", "", "", "", "", "", "", "", "", "", "", "bulb"];
state power = [false; 36];  // the squares the battery's power reaches

// Whether power reaches a square beside square i.
fn fed(i: int) -> bool {
  let c = i % 6;
  let r = i / 6;
  if c > 0 && power[i - 1] { return true; }
  if c < 5 && power[i + 1] { return true; }
  if r > 0 && power[i - 6] { return true; }
  if r < 5 && power[i + 6] { return true; }
  return false;
}

// Wire on an empty square; power spreads from the battery along it to the bulb.
fn lay(i: int) {
  if i == 0 || i == 35 || look[i] != 0 { return; }
  look[i] = 4;
  for k in 0..36 { power[k] = k == 0; }
  repeat 36 {
    for k in 0..36 {
      if look[k] == 4 && fed(k) { power[k] = true; }
    }
  }
  if fed(35) { look[35] = 3; }
}

label "Light the bulb";
grid 6, look, signs { lay(cell); }

