fn level() -> int { return 1 + xp / 30; }

fn most() -> int { return 20 + 10 * level(); }

fn named() -> string {
  if boss == 0 { return "Slime"; }
  if boss == 1 { return "Goblin"; }
  return "Dragon";
}

fn add() {
  if typed != "" {
    push(tasks, typed);
    typed = "";
