// A task done: a hit on the boss, then XP and gold; a new level fills health.
fn done(i: int) {
  remove(tasks, i);
  if boss < 3 {
    hp = max(0, hp - 10 * level());
    if hp == 0 {
      gold += 25;
      boss += 1;
      if boss == 1 { hp = 60; }
      if boss == 2 { hp = 100; }
    }
  }
  let was = level();
  xp += 10;
  gold += 5;
  if level() > was { health = most(); }
}

fn night() {
  day += 1;
  fainted = false;
  health -= 5 * len(tasks);
  if health <= 0 {
    fainted = true;
    gold = 0;
    health = most();
  }
}

fn potion() {
  if gold >= 15 {
    gold -= 15;
    health = min(most(), health + 15);
  }
}

