// Truss bridge: tap a joint, then one beside it, to build a beam ($4); a joint holds once two
// beams at an angle tie it to joints that hold. Test sends a truck across the bottom row.
// icon: line 2 18 22 18 line 2 18 7 8 12 18 17 8 22 18 line 7 8 17 8
state ba = [0; 0];          // the beams: joint to joint, a joint r * 7 + c
state bb = [0; 0];
state firm = [false, false, false, false, false, false, false,
              true, false, false, false, false, false, true,
              true, false, false, false, false, false, true];
state sel = -1;             // the selected joint
state money = 90;
state truck = 0;            // the truck's column
state speed = 0;            // ms a move: 500 while the truck drives
state tested = false;
state news = "";

fn anchor(j: int) -> bool { return j == 7 || j == 13 || j == 14 || j == 20; }

fn beam(p: int, q: int) -> bool {
  for i in 0..len(ba) {
    if (ba[i] == p && bb[i] == q) || (ba[i] == q && bb[i] == p) { return true; }
  }
  return false;
}

fn beside(p: int, q: int) -> bool {
  return p != q && abs(p % 7 - q % 7) <= 1 && abs(p / 7 - q / 7) <= 1;
}

// Joint j holds if two beams tie it to joints that hold, not straight across from each other.
fn holds(j: int) -> bool {
  let dx = [0; 0];
  let dy = [0; 0];
  for i in 0..len(ba) {
    let k = -1;
    if ba[i] == j { k = bb[i]; }
    if bb[i] == j { k = ba[i]; }
    if k >= 0 && firm[k] {
      push(dx, k % 7 - j % 7);
      push(dy, k / 7 - j / 7);
    }
  }
  for p in 0..len(dx) {
    for q in p + 1..len(dx) {
      if dx[p] != -dx[q] || dy[p] != -dy[q] { return true; }
    }
  }
  return false;
}

fn brace() {
  for j in 0..21 { firm[j] = anchor(j); }
  repeat 21 {
    for j in 0..21 {
      if !firm[j] && holds(j) { firm[j] = true; }
    }
  }
}

fn tap(j: int) {
  if tested { return; }
  if sel >= 0 && beside(sel, j) && !beam(sel, j) && money >= 4 {
    push(ba, sel);
    push(bb, j);
    money -= 4;
    brace();
  }
  sel = j;
}

every speed {
  let next = 14 + truck + 1;
  if beam(next - 1, next) && firm[next] {
    truck += 1;
    if truck == 6 {
      news = "Bridge holds";
      speed = 0;
    }
  } else {
    news = "Collapsed";
    speed = 0;
  }
}

fn tint(j: int) -> int {
  if j == sel { return 3; }
  if anchor(j) { return 6; }
  if firm[j] { return 2; }
  return 8;
}

// 7 x 3 squares of 20 units: the beams, the joints at their middles, the truck over the deck.
fn scene() {
  for i in 0..len(ba) { line(ba[i] % 7 * 20 + 10, ba[i] / 7 * 20 + 10, bb[i] % 7 * 20 + 10, bb[i] / 7 * 20 + 10, 2, 9); }
  for j in 0..21 { circle(j % 7 * 20 + 10, j / 7 * 20 + 10, 4, tint(j)); }
  if tested { rect(truck * 20 + 4, 37, 12, 7, 1); }
}

label "Truss bridge";
label "Money " + money;
if news != "" { label news; }
canvas 140, 60, scene() { tap((y / 20) * 7 + x / 20); }
row {
  button "Test" {
    if !tested {
      tested = true;
      truck = 0;
      speed = 500;
    }
  }
  button "New bridge" {
    clear(ba);
    clear(bb);
    brace();
    sel = -1;
    money = 90;
    tested = false;
    speed = 0;
    news = "";
  }
}

// Bridge: tap the water to lay planks ($10 each), then Go: the car drives over from the left bank
