// Starfighter: Start, then the arrows (or a tap) move your ship and space or Fire shoots the lowest
// enemy in your column. Each wave comes down faster and in more rows; one that lands costs a life.
// icon: fill 12 2 16 14 21 20 12 17 3 20 8 14 line 12 17 12 22
state ex = [0; 0];          // the enemies: column and row
state ey = [0; 0];
state ship = 4;
state wave = 1;
state score = 0;
state lives = 3;
state charged = true;
state steps = 0;
state speed = 0;            // ms a step: 500 while a game runs
state played = false;

fn spawn() {
  for r in 0..wave {
    for k in 0..4 {
      push(ex, 1 + 2 * k);
      push(ey, r);
    }
  }
}

fn start() {
  clear(ex);
  clear(ey);
  ship = 4;
  wave = 1;
  score = 0;
  lives = 3;
  charged = true;
  steps = 0;
  spawn();
  speed = 500;
  played = true;
}

fn steer(c: int) {
  if speed > 0 { ship = min(8, max(0, c)); }
}

// The lowest enemy in the ship's column is shot down.
fn fire() {
  if speed == 0 || !charged { return; }
  charged = false;
  let best = -1;
  for i in 0..len(ex) {
    if ex[i] == ship && (best < 0 || ey[i] > ey[best]) { best = i; }
  }
  if best >= 0 {
    remove(ex, best);
    remove(ey, best);
    score += 10;
  }
}

every speed {
  steps += 1;
  charged = true;
  if wave > 1 || steps % 2 == 0 {
    let n = len(ey);
    for j in 0..n {
      let i = n - 1 - j;
      ey[i] += 1;
      if ey[i] >= 9 {
        remove(ex, i);
        remove(ey, i);
        lives = max(0, lives - 1);
      }
    }
  }
  if lives == 0 {
    speed = 0;
  } else if len(ex) == 0 {
    wave += 1;
    spawn();
  }
}

// The board, 9 x 10 squares of 12 units.
fn scene() {
  let cells = [-1; 90];
  for i in 0..len(ex) { cells[ey[i] * 9 + ex[i]] = 1; }
  cells[81 + ship] = 4;
  pixels(cells, 0, 0, 9, 12);
  if played && speed == 0 { text("Game over", 54, 50, 14, 11); }
}

on key "left" { steer(ship - 1); }
on key "right" { steer(ship + 1); }
on key "space" { fire(); }

label "Starfighter";
label "Wave " + wave + "   Score " + score + "   Lives " + lives;
canvas 108, 120, scene() { steer(x / 12); }
row {
  button "Fire" { fire(); }
  if speed == 0 { button "Start" { start(); } }
}

