// Safari: Start, drive the jeep with the arrows (or a tap beside it) and press space or Photo to
// snap the animals beside you: lion 30, zebra 20, elephant 10, all three 40 more. 5 films, 60 s.
// icon: loop 3 9 21 9 21 15 3 15 loop 7 9 9 4 15 4 17 9 dot 7 18 2 dot 17 18 2
state jx = 0;               // the jeep
state jy = 7;
state lx = 0;               // the lion walks row 2, the zebra column 5
state ld = 1;
state zy = 0;
state zd = 1;
state got = [false, false, false];   // the album: lion, zebra, elephant
state time = 60;
state film = 5;
state score = 0;
state speed = 0;            // ms a tick: 1000 while a safari runs
state played = false;

fn animal(c: int, r: int) -> bool {
  return (c == lx && r == 2) || (c == 5 && r == zy) || (c == 2 && r == 5);
}

fn start() {
  jx = 0;
  jy = 7;
  lx = 0;
  ld = 1;
  zy = 0;
  zd = 1;
  for i in 0..3 { got[i] = false; }
  time = 60;
  film = 5;
  score = 0;
  speed = 1000;
  played = true;
}

fn drive(dx: int, dy: int) {
  let c = jx + dx;
  let r = jy + dy;
  if speed > 0 && c >= 0 && c < 8 && r >= 0 && r < 8 && !animal(c, r) {
    jx = c;
    jy = r;
  }
}

fn near(c: int, r: int) -> bool { return abs(c - jx) <= 1 && abs(r - jy) <= 1; }

fn snap(k: int, points: int) {
