fn spelled() -> string {
  let s = "";
  for i in 0..len(word) { s = s + word[i]; }
  return s;
}

// Whether the letters read the same from either end.
fn mirrored() -> bool {
  let n = len(word);
  for i in 0..n / 2 {
    if word[i] != word[n - 1 - i] { return false; }
  }
  return true;
}

fn verdict() -> string {
  if len(word) == 0 { return "Tap letters to spell a word"; }
  if mirrored() { return spelled() + " is a palindrome"; }
  return spelled() + " is not a palindrome";
}

