state top = 0;          // the highest number on the way; 0 before the first Go

// Steps from the number typed down to 1, halving an even number, 3n + 1 for an odd one.
fn go() {
  let n = parse(typed, 0);
  if n < 1 || n > 1000000 { return; }
  steps = 0;
  top = n;
  repeat 1000 {
    if n != 1 {
      if n % 2 == 0 {
        n = n / 2;
      } else {
        n = 3 * n + 1;
      }
      steps += 1;
      top = max(top, n);
    }
  }
}

