// Spoonerisms: Swap trades the first letters of the phrase's two words; Next shows the next phrase.
// icon: line 4 7 19 7 line 15 3 19 7 15 11 line 20 17 5 17 line 9 13 5 17 9 21
state caps = ["J", "B", "B", "F", "S", "B", "P", "R"];     // each word's first letter, a capital
state smalls = ["j", "b", "b", "f", "s", "b", "p", "r"];   // and small
state rests = ["elly", "eans", "ig", "eet", "ail", "oat", "et", "ock"];
state k = 0;              // the phrase: words 2k and 2k + 1
state swapped = false;

// The phrase as it now is: a capital starts the first word.
fn phrase() -> string {
  let a = 2 * k;
  let b = a + 1;
  if swapped { return caps[b] + rests[a] + " " + smalls[a] + rests[b]; }
  return caps[a] + rests[a] + " " + smalls[b] + rests[b];
}

