// Secret handshake: type a number from 1 to 31 to see the handshake its binary digits make.
// icon: ring 12 12 10 line 6 9 10 9 ring 16 9 2 arc 12 13 5 120 240
state typed = "";
state moves = ["wink", "double blink", "close your eyes", "jump"];
state bits = [1, 2, 4, 8];   // each move's binary digit; 16 reverses them

fn shake(n: int) -> string {
  let s = "";
  for j in 0..4 {
    let i = j;
    if n / 16 % 2 == 1 { i = 3 - j; }
    if n / bits[i] % 2 == 1 {
      if s != "" { s = s + ", "; }
      s = s + moves[i];
    }
  }
  if s == "" { return "nothing"; }
  return s;
}

