// About time: +1 min and +10 min move the clock; it says the time in words to the nearest five minutes.
// icon: ring 12 12 10 line 12 12 12 6 line 12 12 17 12
state h = 9;              // the hour, 1 to 12
state m = 0;              // the minutes, 0 to 59
state hours = ["twelve", "one", "two", "three", "four", "five", "six", "seven", "eight", "nine",
               "ten", "eleven"];
state fives = ["o'clock", "five past", "ten past", "quarter past", "twenty past",
               "twenty-five past", "half past", "twenty-five to", "twenty to", "quarter to",
               "ten to", "five to"];

fn add(n: int) {
  m += n;
  if m >= 60 {
    m -= 60;
    h = h % 12 + 1;
  }
}

fn digits() -> string {
  if m < 10 { return h + ":0" + m; }
  return h + ":" + m;
}

// The nearest five minutes (0 to 12 fives); past half past, the words count to the next hour.
fn about() -> string {
  let r = (m + 2) / 5;
  let hour = h % 12;
  if r > 6 { hour = (h + 1) % 12; }
  if r == 12 { r = 0; }
  if r == 0 { return hours[hour] + " o'clock"; }
  return fives[r] + " " + hours[hour];
}

