// Ruler: tap a centimetre to measure from the left end to it; Clear starts over.
// icon: loop 2 8 22 8 22 16 2 16 line 6 8 6 12 line 10 8 10 14 line 14 8 14 12 line 18 8 18 14
state cm = 0;             // centimetres measured, 0 to 15

// Centimetre k: red once measured, else yellow.
fn part(k: int) {
  let c = 3;
  if k < cm { c = 1; }
  rect(k * 10, 0, 9, 24, c);
}

fn scene() {
  for k in 0..15 { part(k); }
}

