// Inch ruler: tap a quarter inch to measure from the left end to it, in inches and quarters.
// icon: loop 2 8 22 8 22 16 2 16 line 7 8 7 14 line 12 8 12 11 line 17 8 17 14
state q = 0;              // quarter inches measured, 0 to 24

// q quarters as whole inches and a quarter, a half or three quarters.
fn length() -> string {
  let whole = q / 4;
  let part = "";
  if q % 4 == 1 { part = "1/4"; }
  if q % 4 == 2 { part = "1/2"; }
  if q % 4 == 3 { part = "3/4"; }
  if part == "" { return whole + " in"; }
  if whole == 0 { return part + " in"; }
  return whole + " " + part + " in";
}

// Quarter k: blue once measured, else yellow.
fn quarter(k: int) {
  let c = 3;
  if k < q { c = 4; }
  rect(k * 8, 0, 7, 24, c);
}

fn scene() {
  for k in 0..24 { quarter(k); }
}

label "Inch ruler";
canvas 192, 24, scene() { q = min(24, x / 8 + 1); }
label "Length: " + length();

