// Mileage log: type the odometer reading and press Log; each higher reading is a trip, and it shows
// the miles driven since the start and what they are owed at 67 cents a mile. Reset starts again.
// icon: arc 12 15 9 270 90 line 3 15 21 15 line 12 15 17 9 dot 12 15 2
state readings = [0; 0];  // in the order logged, each higher than the last
state typed = "";

// Cents as two digits: 5 is 05.
fn two(n: int) -> string {
  if n < 10 { return "0" + n; }
  return "" + n;
}

fn driven() -> int {
  if len(readings) == 0 { return 0; }
  return readings[len(readings) - 1] - readings[0];
}

fn owed() -> string {
  let c = driven() * 67;
  return "$" + c / 100 + "." + two(c % 100);
}

fn log() {
  let n = parse(typed, -1);
  if n < 0 { return; }
  if len(readings) > 0 && n <= readings[len(readings) - 1] { return; }
  push(readings, n);
  typed = "";
}

label "Mileage log";
row {
  input typed;
  button "Log" { log(); }
  button "Reset" { clear(readings); }
}
if len(readings) > 0 { label "Start: " + readings[0]; }
label "Trips: " + max(0, len(readings) - 1);
label "Driven: " + driven() + " miles";
label "Owed: " + owed();

