// Where s is on the list; -1 if it is not.
fn find(s: string) -> int {
  for i in 0..len(guests) {
    if guests[i] == s { return i; }
  }
  return -1;
}

fn count() -> int {
  let n = 0;
  for i in 0..len(brought) {
    if brought[i] { n += 1; }
  }
  return n;
}

// The guests still to bring a gift, in the order added.
fn waiting() -> string {
  let s = "";
  for i in 0..len(guests) {
    if !brought[i] {
      if s != "" { s = s + ", "; }
      s = s + guests[i];
    }
  }
  return s;
}

