// Scale fit: tap notes to pick them; it names every major scale that holds them all. Clear unpicks
// them.
// icon: ring 7 18 3 line 10 18 10 4 line 10 4 18 7 line 13 14 15 17 21 9
state names = ["C", "C#", "D", "D#", "E", "F", "F#", "G", "G#", "A", "A#", "B"];
state picked = [false; 12];

// Whether note n is in the major scale on key k: whole, whole, half, whole, whole, whole, half.
fn inscale(k: int, n: int) -> bool {
  let d = (n - k + 12) % 12;
  return d == 0 || d == 2 || d == 4 || d == 5 || d == 7 || d == 9 || d == 11;
}

fn holds(k: int) -> bool {
  for n in 0..12 {
    if picked[n] && !inscale(k, n) { return false; }
  }
  return true;
}

fn notes() -> string {
  let s = "";
  for n in 0..12 {
    if picked[n] {
      if s != "" { s = s + " "; }
      s = s + names[n];
    }
  }
  if s == "" { return "none"; }
  return s;
}

fn fits() -> string {
  let s = "";
  for k in 0..12 {
    if holds(k) {
      if s != "" { s = s + ", "; }
      s = s + names[k] + " major";
    }
  }
  if s == "" { return "none"; }
  return s;
}

