fn num(s: string) -> int { return max(0, parse(s, 0)); }

// a * b / c, to the nearest whole number (a half rounds up); 0 when c is 0.
fn scale(a: int, b: int, c: int) -> int {
  if c == 0 { return 0; }
  return (2 * a * b + c) / (2 * c);
