// Aspect ratio: type a width and a height; it shows their ratio in lowest terms and whether the
// picture is landscape, portrait or square.
// icon: loop 2 6 22 6 22 18 2 18 line 6 10 6 14 line 18 10 18 14
state w = "";
state h = "";

// The greatest common divisor, by Euclid's steps (a few dozen at most for 64-bit numbers).
fn gcd(a: int, b: int) -> int {
  let p = a;
  let q = b;
  repeat 100 {
    if q != 0 {
      let r = p % q;
      p = q;
      q = r;
    }
  }
  return p;
}

// The ratio in lowest terms, width first.
fn ratio(a: int, b: int) -> string {
  let g = gcd(a, b);
  return (a / g) + ":" + (b / g);
}

fn shape(a: int, b: int) -> string {
  if a > b { return "Landscape"; }
  if a < b { return "Portrait"; }
  return "Square";
}

