  } else {
    push(ladder, w);
    said = "";
    if w == 3 { said = "You made it to dog!"; }
  }
  typed = "";
}

fn shown() -> string {
  let s = words[ladder[0]];
  for i in 1..len(ladder) { s = s + " > " + words[ladder[i]]; }
  return s;
}

