state weave = 0;          // 0 plain, 1 twill, 2 basket
state dyes = ["Red", "Yellow", "Blue", "Green"];
state hues = [1, 3, 4, 2];
state weaves = ["Plain", "Twill", "Basket"];

// Whether warp thread c lies over weft thread r.
fn over(c: int, r: int) -> bool {
  if weave == 0 { return (c + r) % 2 == 0; }
  if weave == 1 { return (c + r) % 4 < 2; }
  return (c / 2 + r / 2) % 2 == 0;
}

fn cloth() {
  let b = [0; 81];
  for c in 0..8 { b[c + 1] = warp[c]; }
  for r in 0..8 {
    b[(r + 1) * 9] = weft[r];
    for c in 0..8 {
      if over(c, r) {
        b[(r + 1) * 9 + c + 1] = warp[c];
      } else {
        b[(r + 1) * 9 + c + 1] = weft[r];
      }
    }
  }
  pixels(b, 0, 0, 9, 12);
}

// A tap dyes the thread under it: a warp in the top row, a weft in the left column.
fn tap(c: int, r: int) {
  if r == 0 && c > 0 && c < 9 { warp[c - 1] = hues[pick]; }
  if c == 0 && r > 0 && r < 9 { weft[r - 1] = hues[pick]; }
}

