// to see where it lands. Clear takes the rungs away.
// icon: line 5 3 5 21 line 12 3 12 21 line 19 3 19 21 line 5 8 12 8 line 12 14 19 14
state rung = [false; 56];   // the board, 7 a row: rungs in columns 1, 3 and 5
state landed = 0;           // the post the last ghost reached, 1 to 4; 0 before any

// A rung at column c, row r, unless c is a post, or a rung beside it shares a post.
fn add(c: int, r: int) {
  if c % 2 == 0 { return; }
  let i = r * 7 + c;
  if c >= 3 && rung[i - 2] { return; }
  if c <= 3 && rung[i + 2] { return; }
  rung[i] = true;
}

// Where a ghost from post p (0 to 3) reaches the bottom, row by row crossing every rung it meets.
fn lands(p: int) -> int {
  let at = p;
  for r in 0..8 {
    if at > 0 && rung[r * 7 + at * 2 - 1] {
      at -= 1;
    } else if at < 3 && rung[r * 7 + at * 2 + 1] {
      at += 1;
    }
  }
  return at + 1;
}

// The posts gray, the rungs blue.
fn scene() {
  let b = [-1; 56];
  for i in 0..56 {
    if i % 7 % 2 == 0 { b[i] = 8; }
    if rung[i] { b[i] = 4; }
  }
  pixels(b, 0, 0, 7, 16);
}

