// Where a ghost from line p comes out at the bottom, crossing each rung it meets.
fn ends(p: int) -> int {
  let at = p;
  for k in 0..3 {
    if rungs[k] == at {
      at += 1;
    } else if rungs[k] == at - 1 {
      at -= 1;
    }
  }
  return at;
}

// A row of the picture with rung k across it.
fn bar(k: int) -> string {
  if rungs[k] == 0 { return "9999999.....9"; }
  return "9.....9999999";
}

// The ladder, 8 units a square.
