// Chopsticks against the computer: tap one of your hands (the bottom row), then one of its hands
// to add your fingers to it; 5 or more puts a hand out. Put both of its hands out to win.
// icon: line 6 20 6 9 line 10 20 10 5 line 14 20 14 6 line 18 20 18 10 loop 5 20 19 20 19 22 5 22
state mine = [1, 1];
state its = [1, 1];
state picked = -1;        // my hand picked, or -1
state playing = false;
state said = "";

// Adds n fingers to a hand; 5 or more is out.
fn add(h: int, n: int) -> int {
  if h + n >= 5 { return 0; }
  return h + n;
}

// The fuller of two hands: the left on a tie.
fn fuller(l: int, r: int) -> int {
  if r > l { return 1; }
  return 0;
}

fn answer() {
  if its[0] == 0 && its[1] == 0 {
    playing = false;
    said = "You win!";
    return;
  }
  let a = fuller(its[0], its[1]);
  let t = fuller(mine[0], mine[1]);
  mine[t] = add(mine[t], its[a]);
  if mine[0] == 0 && mine[1] == 0 {
    playing = false;
    said = "You lose";
  }
}

// A tap on square c (column), r (row): row 1 picks my hand, row 0 plays it onto the computer's.
fn tap(c: int, r: int) {
  if !playing { return; }
  if r == 1 {
    if mine[c] > 0 { picked = c; }
    return;
  }
  if picked < 0 || its[c] == 0 { return; }
  its[c] = add(its[c], mine[picked]);
  picked = -1;
  answer();
}

// A hand at x, y: its fingers as lines over a palm, gray once it is out, the picked one in accent.
fn hand(x: int, y: int, n: int, on: bool) {
  let ink = 4;
  if on { ink = 11; }
  if n == 0 { ink = 8; }
  rect(x - 16, y + 4, 32, 14, ink);
  for f in 0..n { rect(x - 14 + f * 8, y - 16, 4, 20, ink); }
}

fn scene() {
  for c in 0..2 {
    hand(c * 80 + 40, 40, its[c], false);
    hand(c * 80 + 40, 120, mine[c], picked == c);
  }
}

