// Chopsticks for two on one screen: the bottom player goes first. Tap one of your hands, then
// one of the other player's, to add your fingers to it; 5 kills a hand. Lose both and you lose.
// icon: line 6 20 6 9 line 10 20 10 5 line 14 20 14 6 line 18 20 18 10 loop 5 20 19 20 19 22 5 22
state hands = [1, 1, 1, 1];   // the top player's left and right, then the bottom player's
state turn = 1;               // whose turn: 1 the bottom player, 0 the top
state picked = -1;            // the hand picked, or -1
state said = "";

fn alive(p: int) -> bool { return hands[p * 2] > 0 || hands[p * 2 + 1] > 0; }

fn tap(c: int, r: int) {
  let h = r * 2 + c;
  if said != "" || hands[h] == 0 { return; }
  if r == turn {
    picked = h;
    return;
  }
  if picked < 0 { return; }
  hands[h] += hands[picked];
  if hands[h] >= 5 { hands[h] = 0; }
  picked = -1;
  turn = 1 - turn;
  if !alive(turn) {
    if turn == 0 { said = "Bottom wins!"; } else { said = "Top wins!"; }
  }
}

// Each hand a square of the board: its fingers as a number, the picked one in accent.
fn scene() {
  for h in 0..4 {
    let ink = 9;
    if h == picked { ink = 11; }
    if hands[h] > 0 { text(hands[h], h % 2 * 80 + 40, h / 2 * 60 + 30, 24, ink); }
  }
}

