// Pick-up sticks: tap a stick to pick it up, but only one with no stick lying across it; a
// pinned one wobbles the pile, and three wobbles end the game. Clear the pile to win.
// icon: line 3 19 21 5 line 4 6 20 20 line 12 3 12 21
state hue = [1, 3, 2, 4, 1, 3];       // the sticks from the bottom of the pile up
state first = [17, 3, 32, 14, 50, 25]; // each stick's first square: row * 8 + column
state stride = [1, 8, 1, 8, 1, 8];     // along a row, or down a column
state size = [6, 6, 5, 7, 6, 5];
state worth = [0, 1, 3, 2, 5];         // points by color: red 1, green 3, yellow 2, blue 5
state there = [true, true, true, true, true, true];
state score = 0;
state wobbles = 0;
state playing = false;
state said = "";

// Whether stick i lies on square sq.
fn covers(i: int, sq: int) -> bool {
  let k = sq - first[i];
  return k >= 0 && k % stride[i] == 0 && k / stride[i] < size[i];
}

// The highest stick still on square sq, or -1.
fn top(sq: int) -> int {
  for j in 0..6 {
    let i = 5 - j;
    if there[i] && covers(i, sq) { return i; }
  }
  return -1;
}

// Whether a higher stick still there shares a square with stick i.
fn pinned(i: int) -> bool {
  for j in i + 1..6 {
    if there[j] {
      for k in 0..size[i] {
        if covers(j, first[i] + k * stride[i]) { return true; }
      }
    }
  }
  return false;
}

fn left() -> int {
  let n = 0;
  for i in 0..6 {
    if there[i] { n += 1; }
  }
  return n;
}

fn touch(sq: int) {
  let i = top(sq);
  if !playing || i < 0 { return; }
  if pinned(i) {
    wobbles += 1;
    if wobbles == 3 {
      playing = false;
      said = "Game over";
    }
    return;
  }
  there[i] = false;
  score += worth[hue[i]];
  if left() == 0 {
    playing = false;
    said = "Cleared!";
  }
}

fn scene() {
  let b = [0; 64];
  for sq in 0..64 {
    let i = top(sq);
    if i >= 0 { b[sq] = hue[i]; }
  }
  pixels(b, 0, 0, 8, 16);
}

