// Note reader: press Start, then name each note on the staff with its letter, treble and bass
// clef in turn. A wrong letter is counted and the note stays; 8 notes, timed.
// icon: line 3 8 21 8 line 3 12 21 12 line 3 16 21 16 dot 12 14 3 line 15 14 15 4
state letters = ["C", "D", "E", "F", "G", "A", "B"];
state want = ["E", "C", "G", "D", "A", "B", "F", "C"];
state bass = [false, false, true, true, false, true, false, true];
state steps = [0, 5, 0, 4, 3, 2, 8, 10];   // up from the staff's bottom line, a line or space each
state at = 0;             // the note showing
state right = 0;
state wrong = 0;
state secs = 0;
state speed = 0;          // ms a tick; 0 when no drill runs
state done = false;

every speed { secs += 1; }

fn answer(s: string) {
  if speed == 0 { return; }
  if s != want[at] {
    wrong += 1;
    return;
  }
  right += 1;
  at += 1;
  if at == len(want) {
    speed = 0;
    done = true;
  }
}

fn clef() -> string {
  if done { return "Done!"; }
  if speed == 0 { return "Press Start"; }
  if bass[at] { return "Bass clef"; }
  return "Treble clef";
}

// Where step s of the staff is: its bottom line at 50, a line or space each 5 units up.
fn place(s: int) -> int { return 50 - s * 5; }

// The staff's five lines, the note on its line or space, and its ledger line past the top.
fn scene() {
  for i in 0..5 { line(0, place(i * 2), 160, place(i * 2), 1, 9); }
  if speed == 0 { return; }
  if steps[at] > 8 { line(70, place(10), 90, place(10), 1, 9); }
  circle(80, place(steps[at]), 4, 9);
}

