fn block(i: int) -> bool { return board[i] > 0 && board[i] < 8; }

// Blocks drop until something holds them, the picked one followed.
fn fall() {
  repeat 6 {
    for j in 0..54 {
      let i = 53 - j;
      if block(i) && board[i + 9] == 0 {
        board[i + 9] = board[i];
        board[i] = 0;
        if sel == i { sel = i + 9; }
      }
    }
  }
}

// Every block touching one of its color vanishes, all at once: whether any did.
fn vanish() -> bool {
  let gone = [false; 63];
  let any = false;
  for i in 0..54 {
    if block(i) && board[i] == board[i + 1] { gone[i] = true; gone[i + 1] = true; any = true; }
    if block(i) && board[i] == board[i + 9] { gone[i] = true; gone[i + 9] = true; any = true; }
  }
  for i in 0..63 {
    if gone[i] { board[i] = 0; }
  }
  if sel >= 0 && gone[sel] { sel = -1; }
  return any;
}

fn count(k: int) -> int {
  let n = 0;
  for i in 0..63 {
    if board[i] == k { n += 1; }
  }
  return n;
}

fn stuck() -> bool {
  for k in 1..8 {
    if count(k) == 1 { return true; }
  }
  return false;
}

fn left() -> int {
  let n = 0;
  for k in 1..8 { n += count(k); }
  return n;
}

fn slide(d: int) {
  if sel < 0 || stuck() || board[sel + d] != 0 { return; }
  board[sel + d] = board[sel];
  board[sel] = 0;
  sel += d;
  moves += 1;
  repeat 10 {
    fall();
    if !vanish() { return; }
  }
}

fn retry() {
  for i in 0..63 { board[i] = level[i]; }
  sel = -1;
  moves = 0;
}

fn scene() {
  pixels(board, 0, 0, 9, 12);
  if sel >= 0 { ring(sel % 9 * 12 + 6, sel / 9 * 12 + 6, 6, 1, 9); }
}

fn status() -> string {
  if left() == 0 { return "Cleared"; }
  if stuck() { return "Stuck"; }
  return "";
}

