// The cave: the wumpus at column 4 row 2, pits at 2, 4 and 3, 1, the gold at 5, 0.
fn pit(i: int) -> bool { return i == 26 || i == 9; }
fn near(i: int, j: int) -> bool { return abs(i % 6 - j % 6) + abs(i / 6 - j / 6) == 1; }

