// Card c into a hand, A to K; if one of its rank is there, both go out instead.
fn add(me: bool, c: int) {
  if me {
    for i in 0..len(mine) {
      if mine[i] % 13 == c % 13 { remove(mine, i); return; }
    }
    let at = 0;
    for i in 0..len(mine) {
