      if theirs[i] % 13 == c % 13 { remove(theirs, i); return; }
    }
    let at = 0;
    for i in 0..len(theirs) {
      if theirs[i] % 13 < c % 13 { at = i + 1; }
    }
    insert(theirs, at, c);
  }
}

fn deal() {
  clear(mine);
  clear(theirs);
  let n = 0;
  for c in 0..52 {
    if c != 11 {
      add(n % 2 == 0, c);
      n += 1;
    }
  }
  dealt = true;
}

