// Black Box: tap a gray square on the rim to send a ray into the box: red, it hit an atom; yellow,
// it came back; green, where it went in and came out. Tap the box to guess the 4 atoms, then Check.
// icon: loop 3 3 21 3 21 21 3 21 dot 9 9 3 dot 15 15 2 line 3 9 9 9 9 3
state atoms = [12, 44, 46, 76];   // hidden: row * 10 + column
state marks = [0; 100];           // the rim: 1 hit, 3 back, 2 in and out
state guess = [false; 100];
state checked = false;

fn atom(c: int, r: int) -> bool {
  for k in 0..4 {
    if atoms[k] == r * 10 + c { return true; }
  }
  return false;
}

fn rim(i: int) -> bool { return (i % 10 == 0 || i % 10 == 9) != (i < 10 || i >= 90); }

// A ray from rim square (c0, r0): each step it looks at the square ahead and its two sides.
fn fire(c0: int, r0: int) {
  let c = c0;
  let r = r0;
  let dc = 0;
  let dr = 0;
  if r0 == 0 { dr = 1; } else if r0 == 9 { dr = -1; } else if c0 == 0 { dc = 1; } else { dc = -1; }
  let first = true;
  repeat 200 {
    let ac = c + dc;
    let ar = r + dr;
    let a = atom(ac - dr, ar + dc);
    let b = atom(ac + dr, ar - dc);
    if atom(ac, ar) {
      marks[r0 * 10 + c0] = 1;
      return;
    }
    if (a || b) && first {
      marks[r0 * 10 + c0] = 3;
      return;
    }
    if a && b {
      dc = -dc;
      dr = -dr;
    } else if a {
      let t = dc;
      dc = dr;
      dr = -t;
    } else if b {
      let t = dc;
      dc = -dr;
      dr = t;
    } else {
      c = ac;
      r = ar;
      first = false;
      if rim(r * 10 + c) {
        if c == c0 && r == r0 { marks[r * 10 + c] = 3; } else { marks[r * 10 + c] = 2; marks[r0 * 10 + c0] = 2; }
        return;
      }
    }
  }
}

fn count(k: int) -> int {
  let n = 0;
  for i in 0..100 {
    if k == 0 && marks[i] > 0 { n += 1; }
    if k == 1 && guess[i] { n += 1; }
    if k == 2 && guess[i] && atom(i % 10, i / 10) { n += 1; }
  }
  return n;
}

fn score() -> int {
  if checked { return count(0) + 5 * (4 - count(2)); }
  return count(0);
}

fn shade(i: int) -> int {
  let on = atom(i % 10, i / 10);
  if rim(i) && marks[i] > 0 { return marks[i]; }
  if rim(i) { return 8; }
  if checked && on && guess[i] { return 2; }
  if checked && guess[i] { return 1; }
  if checked && on { return 5; }
  if guess[i] { return 4; }
  return 0;
}

fn scene() {
  let b = [0; 100];
  for i in 0..100 { b[i] = shade(i); }
  pixels(b, 0, 0, 10, 12);
}

