  rect(0, 0, 120, 120, 10);
  for i in 0..16 { rect(i % 4 * 30 + 1, i / 4 * 30 + 1, 28, 28, tiles[i]); }
}

fn status() -> string {
  if solved() { return "Solved"; }
  return "Make the rows red, green, yellow, blue";
}

