// Whether p's stone at f may jump to t: straight, over the other's stones with empty squares
// between them, landing on an empty square.
fn legal(f: int, t: int, p: int) -> bool {
  let fc = f % 6;
  let fr = f / 6;
  let dist = abs(t % 6 - fc) + abs(t / 6 - fr);
  if stones[f] != p || stones[t] != 0 || (t % 6 != fc && t / 6 != fr) || dist % 2 == 1 { return false; }
  let sx = (t % 6 - fc) / dist;
  let sy = (t / 6 - fr) / dist;
  for k in 1..dist {
    let i = (fr + sy * k) * 6 + fc + sx * k;
    if k % 2 == 1 && stones[i] != 5 - p { return false; }
    if k % 2 == 0 && stones[i] != 0 { return false; }
  }
  return true;
}

fn can(p: int) -> bool {
  for i in 0..36 {
    if i % 6 < 4 && (legal(i, i + 2, p) || legal(i + 2, i, p)) { return true; }
    if i < 24 && (legal(i, i + 12, p) || legal(i + 12, i, p)) { return true; }
  }
  return false;
}

fn jump(f: int, t: int) {
  let dist = abs(t % 6 - f % 6) + abs(t / 6 - f / 6);
  for k in 0..dist { stones[f + (t - f) / dist * k] = 0; }
  stones[t] = turn;
}

fn next() {
  turn = 5 - turn;
  if taken == 2 && !can(turn) { winner = 5 - turn; }
}

