    if stones[i] == 4 && abs(i % 6 - gap % 6) + abs(i / 6 - gap / 6) == 1 {
      stones[i] = 0;
      taken = 2;
      next();
    }
  } else if stones[i] == turn {
    pick = i;
  } else if pick >= 0 && legal(pick, i, turn) {
    jump(pick, i);
    pick = -1;
    next();
  }
}

fn hue(i: int) -> int {
