// Train tracks: lay one line of track from A on the left edge to B on the bottom, with as many track
// squares in each row and column as its number says. Tap a square to lay track or take it up.
// icon: line 3 8 21 8 line 3 16 21 16 line 6 5 6 19 line 12 5 12 19 line 18 5 18 19
state track = [
  false, false, false, false, false, false,
  false, false, false, false, false, false,
  true, false, false, false, false, false,
  false, false, false, false, false, false,
  false, false, false, false, false, false,
  false, false, false, false, true, false
];                        // A is square 12, B square 34
state rows = [6, 2, 5, 2, 1, 4];
state cols = [3, 4, 4, 3, 3, 3];

fn on(c: int, r: int) -> bool {
  if c < 0 || c > 5 || r < 0 || r > 5 { return false; }
  return track[r * 6 + c];
}

// The track squares touching square i side to side, and the edge for A and B.
fn links(i: int) -> int {
  let c = i % 6;
  let r = i / 6;
  let n = 0;
  if on(c - 1, r) { n += 1; }
  if on(c + 1, r) { n += 1; }
  if on(c, r - 1) { n += 1; }
  if on(c, r + 1) { n += 1; }
  if i == 12 || i == 34 { n += 1; }
  return n;
}

fn laid() -> int {
  let n = 0;
  for i in 0..36 {
    if track[i] { n += 1; }
  }
  return n;
}

fn solved() -> bool {
  let rn = [0; 6];
  let cn = [0; 6];
  let reach = [false; 36];
  reach[12] = true;
  for i in 0..36 {
    if track[i] {
      rn[i / 6] += 1;
      cn[i % 6] += 1;
      if links(i) != 2 { return false; }
    }
  }
  for k in 0..6 {
    if rn[k] != rows[k] || cn[k] != cols[k] { return false; }
  }
  // Spread from A along the track until every reachable square is reached.
  for pass in 0..36 {
    for i in 0..36 {
      let c = i % 6;
      let r = i / 6;
      let near = (c > 0 && reach[i - 1]) || (c < 5 && reach[i + 1]) || (r > 0 && reach[i - 6]) || (r < 5 && reach[i + 6]);
      if track[i] && near { reach[i] = true; }
    }
  }
  for i in 0..36 {
    if track[i] && !reach[i] { return false; }
  }
  return true;
}

fn tap(i: int) {
  if i != 12 && i != 34 && !solved() { track[i] = !track[i]; }
}

fn shade(i: int) -> int {
  if track[i] { return 3; }
  return 0;
}

// The squares 20 units apart, the row numbers to the right, the column numbers below.
fn scene() {
  rect(0, 0, 120, 120, 8);
  for i in 0..36 { rect(i % 6 * 20, i / 6 * 20, 19, 19, shade(i)); }
  text("A", 10, 50, 8, 9);
  text("B", 90, 110, 8, 9);
  for k in 0..6 {
    text(rows[k], 130, k * 20 + 10, 9, 9);
    text(cols[k], k * 20 + 10, 130, 9, 9);
  }
}

label "Train Tracks";
label "Track: " + laid();
canvas 140, 140, scene() {
  if x < 120 && y < 120 { tap((y / 20) * 6 + x / 20); }
}
if solved() { label "Solved"; }
button "Clear" {
  for i in 0..36 { track[i] = i == 12 || i == 34; }
}

// Train tracks: tap squares to lay one line of track from A (left of the second row) to B (bottom of
// the fourth column), with each row's and column's number of track squares.
// icon: line 3 8 21 8 line 3 16 21 16 line 6 5 6 19 line 12 5 12 19 line 18 5 18 19
state track = [
  false, false, false, false, false,
  true, false, false, false, false,
  false, false, false, false, false,
  false, false, false, false, false,
  false, false, false, true, false
];                        // A is square 5, B square 23
state rows = [3, 3, 3, 4, 2];
state cols = [3, 1, 4, 2, 5];

fn on(c: int, r: int) -> bool {
  if c < 0 || c > 4 || r < 0 || r > 4 { return false; }
  return track[r * 5 + c];
}

fn links(i: int) -> int {
  let c = i % 5;
  let r = i / 5;
  let n = 0;
  if on(c - 1, r) { n += 1; }
  if on(c + 1, r) { n += 1; }
  if on(c, r - 1) { n += 1; }
  if on(c, r + 1) { n += 1; }
  if i == 5 || i == 23 { n += 1; }
  return n;
}

// The counts match, every track square links two ways (the edge counts for A and B), and all of
// it is reached from A.
fn solved() -> bool {
  let rn = [0; 5];
  let cn = [0; 5];
  let reach = [false; 25];
  reach[5] = true;
  for i in 0..25 {
    if track[i] {
      rn[i / 5] += 1;
      cn[i % 5] += 1;
      if links(i) != 2 { return false; }
    }
  }
  for k in 0..5 {
    if rn[k] != rows[k] || cn[k] != cols[k] { return false; }
  }
  for pass in 0..25 {
    for i in 0..25 {
      let near = (i % 5 > 0 && reach[i - 1]) || (i % 5 < 4 && reach[i + 1]) || (i >= 5 && reach[i - 5]) || (i < 20 && reach[i + 5]);
      if track[i] && near { reach[i] = true; }
    }
  }
  for i in 0..25 {
    if track[i] && !reach[i] { return false; }
  }
  return true;
}

fn shade(i: int) -> int {
  if track[i] { return 8; }
  return 0;
}

fn scene() {
  for i in 0..25 { rect(i % 5 * 20, i / 5 * 20, 19, 19, shade(i)); }
  text("A", 4, 30, 8, 11);
  text("B", 70, 96, 8, 11);
  for k in 0..5 {
    text(rows[k], 110, k * 20 + 10, 9, 9);
    text(cols[k], k * 20 + 10, 110, 9, 9);
  }
}

