  }
}
if solved() { label "Solved"; }

// Farkle: Roll, tap scoring dice to hold them, then Roll the rest or Bank. 1s are 100, 5s 50, three
// alike 100 times the number (three 1s 1000); a roll with none of them loses the turn. Reach 1500.
// icon: loop 3 3 13 3 13 13 3 13 dot 8 8 2 loop 11 11 21 11 21 21 11 21 dot 14 14 2 dot 18 18 2
state seq = [
  1, 5, 2, 2, 3, 6, 2, 2, 2, 4, 5, 3, 4, 6, 2, 3, 4, 1, 4, 4,
  5, 2, 3, 5, 5, 5, 2, 6, 3, 3, 6, 6, 2, 4, 1, 1, 1, 2, 3, 4
];                        // the numbers the dice show, in turn
state next = 0;
state dice = [0; 6];      // each die's number, 0 before a turn's first roll
state mode = [0; 6];      // 0 from the last roll, 1 held, 2 put aside
state rolled = false;     // a turn is on
state farkled = false;
state turn = 0;
state score = 0;

fn single(f: int) -> int {
  if f == 1 { return 100; }
  if f == 5 { return 50; }
  return 0;
}

// What the held dice score, or 0 if one of them scores nothing.
fn held() -> int {
  let cnt = [0; 7];
  for d in 0..6 {
    if mode[d] == 1 { cnt[dice[d]] += 1; }
  }
  let s = 0;
  for f in 1..7 {
    let c = cnt[f];
    if c >= 3 {
      s += f * 100;
      if f == 1 { s += 900; }
      c -= 3;
    }
    if c > 0 && single(f) == 0 { return 0; }
    s += c * single(f);
  }
  return s;
}

// Whether the dice just rolled hold a 1, a 5 or three alike.
fn scores() -> bool {
  let cnt = [0; 7];
  for d in 0..6 {
    if mode[d] == 0 { cnt[dice[d]] += 1; }
  }
  for f in 1..7 {
    if cnt[f] >= 3 { return true; }
  }
  return cnt[1] > 0 || cnt[5] > 0;
}

fn throw() {
  for d in 0..6 {
    if mode[d] == 0 {
      dice[d] = seq[next];
      next = (next + 1) % 40;
    }
  }
  if !scores() {
    farkled = true;
    rolled = false;
    turn = 0;
  }
}

fn roll() {
  if score >= 1500 { return; }
  if !rolled {
    for d in 0..6 { mode[d] = 0; }
    turn = 0;
    farkled = false;
    rolled = true;
    throw();
    return;
  }
  if held() == 0 { return; }
  turn += held();
  let aside = 0;
  for d in 0..6 {
    if mode[d] == 1 { mode[d] = 2; }
    if mode[d] == 2 { aside += 1; }
  }
  if aside == 6 {
    for d in 0..6 { mode[d] = 0; }
  }
  throw();
}

fn bank() {
  if score >= 1500 || !rolled || held() == 0 { return; }
  score += turn + held();
  turn = 0;
  rolled = false;
  for d in 0..6 {
    mode[d] = 0;
    dice[d] = 0;
  }
}

fn hue(d: int) -> int {
  if mode[d] == 1 { return 3; }
  if mode[d] == 2 { return 8; }
  return 0;
}

fn scene() {
  rect(0, 0, 120, 20, 10);
  for d in 0..6 {
    rect(d * 20 + 1, 1, 18, 18, hue(d));
    if dice[d] > 0 { text(dice[d], d * 20 + 10, 10, 12, 9); }
  }
}

fn status() -> string {
  if score >= 1500 { return "You win"; }
  if farkled { return "Farkled!"; }
  return "Hold scoring dice, then Roll or Bank";
}

label "Farkle";
label "Score: " + score + "   Turn: " + turn + "   Held: " + held();
canvas 120, 20, scene() {
  let d = x / 20;
  if rolled && mode[d] != 2 { mode[d] = 1 - mode[d]; }
}
label status();
row {
  button "Roll" { roll(); }
  button "Bank" { bank(); }
  button "New game" {
    score = 0;
    turn = 0;
