    farkled = false;
    for d in 0..6 {
      mode[d] = 0;
      dice[d] = 0;
    }
  }
}

// Farkle: Roll, and the 1s (100), 5s (50) and three of a kind (100 times, three 1s 1000) are set
// aside; Roll the rest or Bank the turn. A roll that scores nothing loses the turn.
// icon: loop 3 3 13 3 13 13 3 13 dot 8 8 2 loop 11 11 21 11 21 21 11 21 dot 14 14 2 dot 18 18 2
state dice = [0; 0];      // the last roll
state left = 6;           // dice still to roll this turn
state next = 1;           // the number the next die shows
state turn = 0;
state score = 0;
state lost = false;

// Throws the dice left; sets aside and scores the 1s, 5s and threes of a kind.
fn throw() {
  clear(dice);
  let cnt = [0; 7];
  for k in 0..left {
    push(dice, next);
    cnt[next] += 1;
    next = next % 6 + 1;
  }
  let got = 0;
  let kept = 0;
  for f in 1..7 {
    if cnt[f] >= 3 {
      got += f * 100;
      if f == 1 { got += 900; }
      kept += 3;
      cnt[f] -= 3;
    }
  }
  got += cnt[1] * 100 + cnt[5] * 50;
  kept += cnt[1] + cnt[5];
  if got == 0 {
    turn = 0;
    left = 6;
    lost = true;
  } else {
    turn += got;
    left -= kept;
    if left == 0 { left = 6; }
  }
}

// The last roll's dice in a row.
fn scene() {
  for k in 0..len(dice) {
    rect(k * 20 + 1, 1, 18, 18, 7);
    text(dice[k], k * 20 + 10, 10, 12, 9);
  }
}

label "Farkle";
canvas 120, 20, scene();
label "Turn: " + turn + "   Score: " + score;
if lost { label "Nothing scored: turn lost"; }
row {
  button "Roll" {
    lost = false;
    throw();
  }
  button "Bank" {
    score += turn;
    turn = 0;
    left = 6;
  }
}

// Kite: keep it up through three levels. It sinks a row a step, and every 4th step a gust lifts
// it two; space or Pull lifts it one. Touch the ground and it crashes.
// icon: fill 12 2 19 9 12 16 5 9 line 12 16 9 22
state ky = 4;                   // the kite's row
state level = 1;
state steps = 0;                // steps of this level
state speed = 0;                // ms a step; 0 while no game runs
state said = "";

// A level begins with the kite at row 4; each is faster.
fn begin() {
  ky = 4;
  steps = 0;
  speed = 400 - level * 100;
}

fn stop(s: string) {
  said = s;
  speed = 0;
}

every speed {
  steps += 1;
  if steps % 4 == 0 { ky = max(0, ky - 2); } else { ky += 1; }
  if ky >= 9 {
    stop("Game over");
  } else if steps == 16 && level == 3 {
    stop("You win");
  } else if steps == 16 {
    level += 1;
    begin();
  }
}

fn pull() {
  if speed > 0 { ky = max(0, ky - 1); }
}

on key "space" { pull(); }

fn scene() {
  let cells = [-1; 100];
  for c in 0..10 { cells[90 + c] = 2; }
  cells[ky * 10 + 4] = 4;
  pixels(cells, 0, 0, 10, 10);
  if said != "" { text(said, 50, 30, 14, 11); }
}

label "Kite";
label "Level: " + level + "   Step: " + steps;
canvas 100, 100, scene();
row {
  if speed == 0 {
    button "Start" {
      level = 1;
      said = "";
      begin();
    }
  }
  button "Pull" { pull(); }
}

// Kite: it sinks a metre every half second; Pull lifts it two. Over 20 m the string snaps, at
// 0 m it crashes. Keep it up for a minute to win.
// icon: fill 12 2 19 9 12 16 5 9 line 12 16 9 22
state h = 10;                   // the height in m
state ticks = 0;                // half seconds flown
state speed = 0;                // ms a tick; 0 while no game runs
state said = "";

fn stop(s: string) {
  said = s;
  speed = 0;
}

fn check() {
  if h > 20 {
    stop("Game over: the string snapped");
  } else if h <= 0 {
    stop("Game over: crashed");
  } else if ticks >= 120 {
    stop("You win!");
  }
}

every speed {
  h -= 1;
  ticks += 1;
  check();
}

fn pull() {
  if speed > 0 {
    h += 2;
    check();
  }
}

on key "space" { pull(); }

// The kite on its string, 5 units a metre above the ground.
fn scene() {
  let y = 105 - max(0, min(h, 21)) * 5;
  line(50, 120, 50, y, 1, 10);
  sprite(["..4..", ".444.", "44444", ".444.", "..4.."], 48, y - 4, 1);
  if said != "" { text(said, 50, 20, 8, 11); }
}

label "Kite";
label "Height: " + h + " m";
canvas 100, 120, scene();
row {
  if speed == 0 {
    button "Start" {
      h = 10;
      ticks = 0;
      said = "";
      speed = 500;
    }
  }
  button "Pull" { pull(); }
}

// Big fish: the arrows swim. Eat fish no bigger than you (green) to grow, and keep away from
// bigger ones (red), which swim on and come round again. Eat them all to clear a level.
// icon: fill 2 12 8 6 15 6 18 12 15 18 8 18 fill 17 12 22 7 22 17
state fx = [0; 0];              // the fish: column, row and size
state fy = [0; 0];
state fs = [0; 0];
state mx = 0;                   // me
state my = 5;
state size = 1;
state level = 1;
state speed = 0;                // ms a swim; 0 while no game runs
state said = "";

fn begin() {
  mx = 0;
  my = 5;
  size = 1;
  if level == 1 {
    fx = [8, 5, 9, 3];
    fy = [0, 1, 2, 4];
    fs = [3, 1, 2, 1];
    speed = 500;
  } else {
    fx = [9, 6, 3, 8, 2];
    fy = [0, 1, 2, 3, 4];
    fs = [4, 1, 3, 2, 1];
    speed = 300;
  }
}

fn stop(s: string) {
  said = s;
  speed = 0;
}

// A fish on my square: I eat it if it is no bigger, else it eats me.
fn meet() {
  let k = -1;
  for i in 0..len(fx) {
    if fx[i] == mx && fy[i] == my { k = i; }
  }
  if k < 0 { return; }
  if fs[k] > size {
    stop("Game over");
    return;
  }
  size += 1;
  remove(fx, k);
  remove(fy, k);
  remove(fs, k);
  if len(fx) == 0 && level == 2 {
    stop("You win");
  } else if len(fx) == 0 {
    level = 2;
    begin();
  }
}

every speed {
  for i in 0..len(fx) { fx[i] = (fx[i] + 9) % 10; }
  meet();
}

fn swim(dx: int, dy: int) {
  if speed == 0 { return; }
  mx = min(9, max(0, mx + dx));
  my = min(5, max(0, my + dy));
  meet();
}

on key "left" { swim(-1, 0); }
on key "right" { swim(1, 0); }
on key "up" { swim(0, -1); }
on key "down" { swim(0, 1); }

fn scene() {
  let cells = [-1; 60];
  for i in 0..len(fx) {
    cells[fy[i] * 10 + fx[i]] = 1;
    if fs[i] <= size { cells[fy[i] * 10 + fx[i]] = 2; }
  }
  cells[my * 10 + mx] = 4;
  pixels(cells, 0, 0, 10, 10);
  if said != "" { text(said, 50, 30, 14, 11); }
}

label "Big Fish";
label "Level: " + level + "   Size: " + size;
canvas 100, 60, scene();
if speed == 0 {
  button "Start" {
    level = 1;
    said = "";
    begin();
  }
