// Crate climber: crates drop one at a time. The arrows walk, and climb onto a crate one high;
// stand two crates up to clear level 1, three for level 2. Don't get crushed.
// icon: loop 3 12 11 12 11 20 3 20 loop 13 4 21 4 21 12 13 12 loop 13 12 21 12 21 20 13 20
state crates = [false; 64];     // the landed crates, 8 x 8: square c + 8 * r
state cx = -1;                  // the falling crate (cx -1: none)
state cy = 0;
state next = 0;                 // crates dropped this level
state px = 0;                   // me
state py = 7;
state level = 1;
state speed = 0;                // ms a step; 0 while no game runs
state said = "";

// The column of the level's k-th crate.
fn column(k: int) -> int {
  if level == 1 {
    let o = [2, 3, 3];
    return o[k % 3];
  }
  let o = [4, 5, 5, 6, 6, 6];
  return o[k % 6];
}

fn landed(c: int, r: int) -> bool { return r > 7 || crates[r * 8 + c]; }

fn begin() {
  for i in 0..64 { crates[i] = false; }
  cx = -1;
  next = 0;
  px = 0;
  py = 7;
  speed = 400 - level * 100;
}

fn stop(s: string) {
  said = s;
  speed = 0;
}

every speed {
  if cx < 0 {
    cx = column(next);
    cy = 0;
    next += 1;
  } else {
    cy += 1;
  }
  if cx == px && cy == py {
    stop("Game over");
  } else if landed(cx, cy + 1) {
    crates[cy * 8 + cx] = true;
    cx = -1;
  }
}

fn falling(c: int, r: int) -> bool { return c == cx && r == cy; }

// A step across: onto an empty square, or up onto a crate one high; then down to stand.
fn walk(d: int) {
  let c = px + d;
  if speed == 0 || c < 0 || c > 7 || falling(c, py) { return; }
  let r = py;
  if crates[r * 8 + c] {
    if r == 0 || crates[(r - 1) * 8 + c] || falling(c, r - 1) { return; }
    r -= 1;
  }
  px = c;
  py = r;
  for k in 0..8 {
    if !landed(px, py + 1) { py += 1; }
  }
  if py == 6 - level && level == 2 {
    stop("You win");
  } else if py == 6 - level {
    level = 2;
    begin();
  }
}

on key "left" { walk(-1); }
