// Capture the flag: the arrows move you. Run into the guards' half, grab the flag and bring it
// home; a guard that catches you sends you back. Two captures a level, two levels.
// icon: line 6 21 6 3 fill 7 3 19 7 7 11 dot 15 17 3
state gx = [0; 0];              // the guards
state gy = [0; 0];
state mx = 0;                   // me
state my = 3;
state carry = false;
state level = 1;
state captures = 0;
state lives = 3;
state speed = 0;                // ms a guard move; 0 while no game runs
state said = "";

// Me at my base, the flag in its place, the guards at their starts.
fn place() {
  mx = 0;
  my = 3;
  carry = false;
  if level == 1 {
    gx = [7];
    gy = [3];
    speed = 400;
  } else {
    gx = [7, 7];
    gy = [1, 5];
    speed = 250;
  }
}

fn stop(s: string) {
  said = s;
  speed = 0;
}

// A guard on my square tags me; the flag reached is picked up; brought home, it is a capture.
fn meet() {
  for i in 0..len(gx) {
    if speed > 0 && gx[i] == mx && gy[i] == my {
      lives -= 1;
      mx = 0;
      my = 3;
      carry = false;
      if lives == 0 { stop("Game over"); }
    }
  }
  if speed > 0 && mx == 9 && my == 3 { carry = true; }
  if speed > 0 && carry && mx <= 4 {
    captures += 1;
    if captures < 2 {
      place();
    } else if level == 2 {
      carry = false;
      stop("You win");
    } else {
      level = 2;
      captures = 0;
      place();
    }
  }
}

every speed {
  let t = max(5, mx);
  for i in 0..len(gx) {
    if gx[i] < t {
      gx[i] += 1;
    } else if gx[i] > t {
      gx[i] -= 1;
    } else if gy[i] < my {
      gy[i] += 1;
    } else if gy[i] > my {
      gy[i] -= 1;
    }
  }
  meet();
}

fn walk(dx: int, dy: int) {
  if speed == 0 { return; }
  mx = min(9, max(0, mx + dx));
  my = min(6, max(0, my + dy));
  meet();
}

