// Capture the flag for two: Blue moves with W A S D, Red with the arrows. Grab the other flag and
// bring it to your own; step on a raider in your half to send them home. First to 3 wins.
// icon: line 6 21 6 3 fill 7 3 19 7 7 11 dot 15 17 3
state px = [0, 9];              // Blue, then Red: where each is, whether it carries a flag, its score
state py = [2, 2];
state carry = [false, false];
state score = [0, 0];
state playing = false;
state said = "";

fn home(p: int) {
  px[p] = p * 9;
  py[p] = 2;
}

// Player p steps; o is the other one.
fn step(p: int, dx: int, dy: int) {
  if !playing { return; }
  let o = 1 - p;
  let x = min(9, max(0, px[p] + dx));
  let y = min(4, max(0, py[p] + dy));
  let mine = x < 5 && p == 0 || x >= 5 && p == 1;
  if x == px[o] && y == py[o] && !mine { return; }
  px[p] = x;
  py[p] = y;
  if x == px[o] && y == py[o] {
    home(o);
    carry[o] = false;
  }
  if x == o * 9 && y == 2 && !carry[o] { carry[p] = true; }
  if carry[p] && x == p * 9 && y == 2 {
    score[p] += 1;
    carry[p] = false;
    home(0);
    home(1);
    if score[p] == 3 {
      playing = false;
      if p == 0 { said = "Blue wins!"; } else { said = "Red wins!"; }
    }
  }
}

on key "w" { step(0, 0, -1); }
on key "a" { step(0, -1, 0); }
on key "s" { step(0, 0, 1); }
on key "d" { step(0, 1, 0); }
on key "up" { step(1, 0, -1); }
on key "left" { step(1, -1, 0); }
on key "down" { step(1, 0, 1); }
