  if speed == 0 || c > 8 || scoops == 0 { return; }
  let r = 7;
  for k in 0..8 {
    if r >= 0 && sand[r * 10 + c] { r -= 1; }
  }
  if r >= 0 && !water[r * 10 + c] {
    sand[r * 10 + c] = true;
    scoops -= 1;
  }
}

