    if sand[i] { cells[i] = 3; }
    if water[i] { cells[i] = 4; }
  }
  if !water[79] { cells[79] = 1; }
  pixels(cells, 0, 0, 10, 10);
  if said != "" { text(said, 50, 20, 12, 11); }
}

