state sit = 0;                  // the end the sitting clown is on: 0 the left, 2 the right
state fx = 4;                   // the flying clown: where, which way across, whether rising
state fy = 5;
state dx = 1;
state up = true;
state level = 1;
state popped = 0;
state lives = 3;
state speed = 0;                // ms a step; 0 while no game runs
state said = "";

fn begin() {
  balloons = [false, true, false, true, false, true, false];
  s = 2;
  sit = 0;
  fx = 4;
  fy = 5;
  dx = 1;
  up = true;
  speed = 300 - level * 100;
}

fn stop(t: string) {
  said = t;
  speed = 0;
}

fn left() -> int {
  let n = 0;
  for c in 0..7 {
    if balloons[c] { n += 1; }
  }
  return n;
}

fn pop() {
  balloons[fx] = false;
  popped += 1;
  up = false;
  if left() == 0 && level == 2 {
    stop("You win");
  } else if left() == 0 {
    level = 2;
    begin();
