    level = 1;
    popped = 0;
    lives = 3;
    said = "";
    begin();
  }
}

// Seesaw balance: clowns climb on, small then big; the arrows seat each on the left or right
// end. Keep the ends within 3 of each other (2 on level 2) for 10 clowns a level.
// icon: line 2 16 22 12 fill 12 15 8 21 16 21 dot 5 11 3 dot 19 7 3
state wl = 0;                   // the weight on each end
state wr = 0;
state seated = 0;               // clowns seated this level
state level = 1;
state playing = false;
state said = "";

fn weight() -> int {
  if seated % 2 == 0 { return 1; }
  return 2;
}

fn put(right: bool) {
  if !playing { return; }
  if right { wr += weight(); } else { wl += weight(); }
  seated += 1;
  if abs(wl - wr) > 4 - level {
    said = "It tipped: game over";
    playing = false;
  } else if seated == 10 && level == 2 {
    said = "You win!";
    playing = false;
  } else if seated == 10 {
    level = 2;
    wl = 0;
    wr = 0;
    seated = 0;
  }
}

on key "left" { put(false); }
on key "right" { put(true); }

// The plank leans toward the heavier end.
fn scene() {
  let t = max(-4, min(4, wr - wl)) * 4;
  line(10, 30 - t, 90, 30 + t, 3, 8);
  rect(46, 32, 8, 18, 10);
}

label "Seesaw";
label "Left: " + wl + "   Right: " + wr;
canvas 100, 50, scene();
label said;
if !playing {
  button "Start" {
    level = 1;
    wl = 0;
    wr = 0;
    seated = 0;
    said = "";
    playing = true;
  }
}

// Durak against the computer: tap a card to attack; when it attacks, tap a card that beats it,
// or Take. Trumps beat any other suit. Out of cards when the stock is gone, and you win.
// icon: loop 3 5 12 5 12 19 3 19 loop 12 5 21 5 21 19 12 19 line 7 9 7 15 line 16 9 16 15
state deck = [11, 7, 5, 4, 12, 15, 14, 10, 9, 6, 8, 13, 0, 3, 2, 1];   // a card is suit * 4 + rank
state ranks = ["J", "Q", "K", "A"];
state suits = ["S", "H", "D", "C"];
state me = [0; 0];
state cpu = [0; 0];
state stock = [0; 0];
state trump = 0;
state att = -1;                 // the computer's attack waiting for my answer, or -1
state playing = false;
state said = "";

fn name(c: int) -> string { return ranks[c % 4] + suits[c / 4]; }

fn beats(a: int, d: int) -> bool {
  return d / 4 == a / 4 && d % 4 > a % 4 || d / 4 == trump && a / 4 != trump;
}

// A card's worth to the computer: non-trumps before trumps, then by rank.
fn worth(c: int) -> int {
  if c / 4 == trump { return 10 + c % 4; }
  return c % 4;
}

fn drawMe() {
  for k in 0..4 {
    if len(me) < 4 && len(stock) > 0 {
      push(me, stock[0]);
      remove(stock, 0);
    }
  }
}

fn drawCpu() {
  for k in 0..4 {
    if len(cpu) < 4 && len(stock) > 0 {
      push(cpu, stock[0]);
      remove(stock, 0);
    }
  }
}

// Whether the game is over: the stock gone and a hand empty.
fn over() -> bool {
  if len(stock) > 0 || len(me) > 0 && len(cpu) > 0 { return false; }
  if len(me) == 0 && len(cpu) == 0 {
    said = "Draw";
  } else if len(me) == 0 {
    said = "You win";
  } else {
    said = "You lose";
  }
  playing = false;
  return true;
}

fn attack() {
  let pick = 0;
  for i in 1..len(cpu) {
    if worth(cpu[i]) < worth(cpu[pick]) { pick = i; }
  }
  att = cpu[pick];
  remove(cpu, pick);
}

// The computer answers my card a: its lowest card that beats it, else it takes it.
fn defend(a: int) {
  let pick = -1;
  for i in 0..len(cpu) {
    if beats(a, cpu[i]) && (pick < 0 || worth(cpu[i]) < worth(cpu[pick])) { pick = i; }
  }
  if pick < 0 {
    push(cpu, a);
    drawMe();
    drawCpu();
    over();
    return;
  }
  remove(cpu, pick);
  drawMe();
  drawCpu();
  if !over() { attack(); }
}

fn tap(c: int, r: int) {
  if !playing || r != 2 || c >= len(me) { return; }
  let card = me[c];
  if att < 0 {
    remove(me, c);
    defend(card);
  } else if beats(att, card) {
    remove(me, c);
    att = -1;
    drawCpu();
    drawMe();
    over();
  }
}

fn take() {
  if !playing || att < 0 { return; }
  push(me, att);
  att = -1;
  drawCpu();
  drawMe();
  if !over() { attack(); }
}

fn face(c: int, x: int, y: int) {
  let ink = 9;
  if c / 4 == 1 || c / 4 == 2 { ink = 1; }
  rect(x * 20 + 1, y * 20 + 1, 18, 18, 7);
  text(name(c), x * 20 + 10, y * 20 + 10, 8, ink);
}

fn scene() {
  for i in 0..min(8, len(cpu)) { rect(i * 20 + 1, 1, 18, 18, 4); }
  if len(stock) > 1 { rect(1, 21, 18, 18, 4); }
  if len(stock) > 0 { face(stock[len(stock) - 1], 1, 1); }
  if att >= 0 { face(att, 3, 1); }
  for i in 0..min(8, len(me)) { face(me[i], i, 2); }
}

label "Durak";
label said;
canvas 160, 60, scene() { tap(x / 20, y / 20); }
row {
  if !playing {
    button "Start" {
      clear(me);
      clear(cpu);
      clear(stock);
      for i in 0..4 {
        push(me, deck[i]);
        push(cpu, deck[i + 4]);
      }
      for i in 8..16 { push(stock, deck[i]); }
      trump = deck[15] / 4;
      att = -1;
      said = "";
      playing = true;
    }
  }
  if att >= 0 { button "Take" { take(); } }
}

// Durak with a short deck: tap a card to attack; when the computer attacks, tap a card that
// beats it, or Take. Out of cards once the stock is gone, and you win.
// icon: loop 3 5 12 5 12 19 3 19 loop 12 5 21 5 21 19 12 19 line 7 9 7 15 line 16 9 16 15
state deck = [11, 4, 9, 1, 7, 0, 5, 6, 8, 2, 10, 3];   // a card is suit * 3 + rank
state ranks = ["Q", "K", "A"];
state suits = ["S", "H", "D", "C"];
state me = [0; 0];
state cpu = [0; 0];
state stock = [0; 0];
state trump = 0;
state att = -1;                 // the computer's attack waiting for my answer, or -1
state playing = false;
state said = "";

fn name(c: int) -> string { return ranks[c % 3] + suits[c / 3]; }

fn beats(a: int, d: int) -> bool {
  return d / 3 == a / 3 && d % 3 > a % 3 || d / 3 == trump && a / 3 != trump;
}

fn worth(c: int) -> int {
  if c / 3 == trump { return 10 + c % 3; }
  return c % 3;
}

fn drawMe() {
  for k in 0..3 {
    if len(me) < 3 && len(stock) > 0 {
      push(me, stock[0]);
      remove(stock, 0);
    }
  }
}

fn drawCpu() {
  for k in 0..3 {
    if len(cpu) < 3 && len(stock) > 0 {
      push(cpu, stock[0]);
      remove(stock, 0);
    }
  }
}

fn over() -> bool {
  if len(stock) > 0 || len(me) > 0 && len(cpu) > 0 { return false; }
  if len(me) == 0 { said = "You win"; } else { said = "You lose"; }
  playing = false;
  return true;
}

fn attack() {
  let pick = 0;
  for i in 1..len(cpu) {
    if worth(cpu[i]) < worth(cpu[pick]) { pick = i; }
  }
  att = cpu[pick];
  remove(cpu, pick);
}

fn defend(a: int) {
  let pick = -1;
  for i in 0..len(cpu) {
    if beats(a, cpu[i]) && (pick < 0 || worth(cpu[i]) < worth(cpu[pick])) { pick = i; }
  }
  if pick < 0 {
    push(cpu, a);
  } else {
    remove(cpu, pick);
  }
  drawMe();
  drawCpu();
  if !over() && pick >= 0 { attack(); }
}

fn play(i: int) {
  let card = me[i];
  if att < 0 {
    remove(me, i);
    defend(card);
  } else if beats(att, card) {
    remove(me, i);
    att = -1;
    drawCpu();
    drawMe();
    over();
  }
}

label "Durak";
label "Trumps: " + suits[trump];
if att >= 0 { label "The computer attacks: " + name(att); }
label said;
if playing {
  row {
    for i in 0..len(me) { button name(me[i]) { play(i); } }
  }
}
if playing && att >= 0 {
  button "Take" {
    push(me, att);
    att = -1;
    drawCpu();
    drawMe();
    if !over() { attack(); }
  }
}
if !playing {
  button "Start" {
    clear(me);
    clear(cpu);
    clear(stock);
    for i in 0..3 {
      push(me, deck[i]);
      push(cpu, deck[i + 3]);
    }
    for i in 6..12 { push(stock, deck[i]); }
    trump = deck[11] / 3;
    att = -1;
    said = "";
    playing = true;
  }
}

// Skyline bomber: the plane crosses the city, a row lower each pass; space or Drop lets a bomb
// fall. Flatten every building to clear a level; fly into one and it is over. Two levels.
// icon: fill 2 5 12 5 15 3 17 3 17 8 2 8 fill 4 13 9 13 9 21 4 21 fill 14 11 20 11 20 21 14 21 dot 7 10 2
state city = [false; 64];      // the board, 8 x 8: square c + 8 * r, true a building
state px = 0;                  // the plane
state py = 0;
state bx = 0;                  // the bomb, by -1 with none falling
state by = -1;
state level = 1;
state score = 0;
state speed = 0;               // ms a step; 0 while no game runs
state result = "";

fn left() -> int {
  let n = 0;
  for i in 0..64 {
    if city[i] { n += 1; }
  }
  return n;
}

// The level's buildings, standing on the bottom row; the plane back at the top left.
fn build() {
  let h = [0, 2, 1, 3, 0, 2, 1, 0];
  if level == 2 { h = [2, 1, 3, 2, 1, 3, 1, 2]; }
  for i in 0..64 { city[i] = i / 8 >= 8 - h[i % 8]; }
  px = 0;
  py = 0;
  by = -1;
}

fn start() {
  level = 1;
  score = 0;
  result = "";
  build();
  speed = 200;
}

fn blast(c: int, r: int) {
  if r < 8 && city[r * 8 + c] {
    city[r * 8 + c] = false;
    score += 1;
  }
}

every speed {
  if by >= 0 {
    by += 1;
    if by > 7 {
      by = -1;
    } else if city[by * 8 + bx] {
      blast(bx, by);
      blast(bx, by + 1);
      by = -1;
    }
  }
  px += 1;
  if px > 7 {
    px = 0;
    py += 1;
  }
  if city[py * 8 + px] {
    result = "Game over";
    speed = 0;
  } else if left() == 0 && level == 2 {
    result = "You win";
    speed = 0;
  } else if left() == 0 {
    level = 2;
    build();
  }
}

fn drop() {
  if speed > 0 && by < 0 {
    bx = px;
    by = py;
  }
}

on key "space" { drop(); }

fn scene() {
  let cells = [-1; 64];
  for i in 0..64 {
    if city[i] { cells[i] = 8; }
  }
  if by >= 0 { cells[by * 8 + bx] = 3; }
  cells[py * 8 + px] = 1;
  pixels(cells, 0, 0, 8, 10);
  if result != "" { text(result, 40, 30, 12, 11); }
}

label "Skyline Bomber";
label "Level: " + level + "   Score: " + score;
canvas 80, 80, scene();
row {
  if speed == 0 { button "Start" { start(); } }
  button "Drop" { drop(); }
}

// Skyline bomber: the plane passes over six buildings, a floor lower each time round; space
// knocks the top floor off the one below it. Flatten them all before the plane flies into one.
// icon: fill 2 5 12 5 15 3 17 3 17 8 2 8 fill 4 13 9 13 9 21 4 21 fill 14 11 20 11 20 21 14 21 dot 7 10 2
state tall = [0; 6];           // each building's floors
state pos = 0;                 // the building the plane is over
state high = 6;                // the floor the plane flies at
state score = 0;
state speed = 0;               // ms a move; 0 while no game runs
state result = "";

fn floors() -> int {
  let n = 0;
  for i in 0..6 { n += tall[i]; }
  return n;
}

fn start() {
  tall = [4, 2, 5, 3, 1, 4];
  pos = 0;
  high = 6;
  score = 0;
  result = "";
  speed = 500;
}

every speed {
  pos += 1;
  if pos == 6 {
    pos = 0;
    high -= 1;
  }
  if tall[pos] >= high {
    result = "Game over";
    speed = 0;
  }
}

on key "space" {
  if speed > 0 && tall[pos] > 0 {
    tall[pos] -= 1;
    score += 1;
    if floors() == 0 {
      result = "You win";
      speed = 0;
    }
  }
}

fn scene() {
  for i in 0..6 { rect(i * 20 + 2, 80 - tall[i] * 10, 16, tall[i] * 10, 8); }
  if speed > 0 { rect(pos * 20 + 3, 82 - high * 10, 14, 6, 1); }
  if result != "" { text(result, 60, 10, 12, 11); }
}

label "Skyline Bomber";
label "Score: " + score;
canvas 120, 80, scene();
if speed == 0 { button "Start" { start(); } }

// Number muncher: the arrows move the muncher; space or Munch eats the number under it. Eat
// every multiple, never another number, and keep away from the troggle. Two levels.
// icon: ring 12 12 9 line 21 7 12 12 21 17 dot 11 7 2
state eaten = [false; 30];     // the board, 6 x 5: square c + 6 * r
state mc = 0;                  // the muncher
state mr = 0;
state tc = 5;                  // the troggle
state tr = 4;
state level = 1;
state score = 0;
state lives = 3;
state speed = 0;               // ms a troggle step; 0 while no game runs
state result = "";

fn num(i: int) -> int {
  if level == 1 { return i + 1; }
  return i + 31;
}

fn factor() -> int {
  if level == 1 { return 4; }
  return 7;
}

fn wanted(i: int) -> bool { return !eaten[i] && num(i) % factor() == 0; }

fn home() {
  mc = 0;
  mr = 0;
  tc = 5;
  tr = 4;
}

fn setup() {
  for i in 0..30 { eaten[i] = false; }
  home();
}

fn start() {
  level = 1;
  score = 0;
  lives = 3;
  result = "";
  setup();
  speed = 1000;
}

fn lose() {
  lives -= 1;
  if lives == 0 {
    result = "Game over";
    speed = 0;
  }
}

fn meet() {
  if mc == tc && mr == tr {
    lose();
    home();
  }
}

fn walk(dc: int, dr: int) {
  if speed == 0 { return; }
  mc = min(5, max(0, mc + dc));
  mr = min(4, max(0, mr + dr));
  meet();
}

fn munch() {
  let i = mr * 6 + mc;
  if speed == 0 || eaten[i] { return; }
  if num(i) % factor() != 0 {
    lose();
    return;
  }
  eaten[i] = true;
  score += 1;
  for j in 0..30 {
    if wanted(j) { return; }
  }
  if level == 2 {
    result = "You win";
    speed = 0;
  } else {
    level = 2;
    setup();
  }
}

// The troggle: a step across toward the muncher, else up or down.
every speed {
  if tc != mc {
    tc += (mc - tc) / abs(mc - tc);
  } else if tr != mr {
    tr += (mr - tr) / abs(mr - tr);
  }
  meet();
}

on key "left" { walk(-1, 0); }
on key "right" { walk(1, 0); }
on key "up" { walk(0, -1); }
on key "down" { walk(0, 1); }
on key "space" { munch(); }

fn scene() {
  let cells = [-1; 30];
  cells[tr * 6 + tc] = 1;
  cells[mr * 6 + mc] = 2;
  pixels(cells, 0, 0, 6, 20);
  for i in 0..30 {
    if !eaten[i] { text(num(i), i % 6 * 20 + 10, i / 6 * 20 + 10, 8, 9); }
  }
  if result != "" { text(result, 60, 50, 14, 11); }
}

label "Number Muncher";
label "Level: " + level + "   Multiples of " + factor() + "   Score: " + score + "   Lives: " + lives;
canvas 120, 100, scene();
row {
  if speed == 0 { button "Start" { start(); } }
  button "Munch" { munch(); }
}

// Number munchers: the arrows move you and space eats the number you are on. Eat every multiple
// of 3; a wrong number, or the troggle catching you, costs one of your 3 lives.
// icon: ring 12 12 9 line 21 7 12 12 21 17 dot 11 7 2
state eaten = [false; 25];     // the board, 5 x 5: square c + 5 * r holds c + 5 * r + 1
state me = 0;
state trog = 24;
state score = 0;
state lives = 3;
state speed = 0;               // ms a troggle step; 0 while no game runs
state result = "";

fn start() {
  for i in 0..25 { eaten[i] = false; }
  me = 0;
  trog = 24;
  score = 0;
  lives = 3;
  result = "";
  speed = 1000;
}

fn lose() {
  lives -= 1;
  if lives == 0 {
    result = "Game over";
    speed = 0;
  }
}

fn caught() {
  if me == trog {
    lose();
    trog = 24;
  }
}

fn walk(dc: int, dr: int) {
  let c = me % 5 + dc;
  let r = me / 5 + dr;
  if speed > 0 && c >= 0 && c < 5 && r >= 0 && r < 5 {
    me = r * 5 + c;
    caught();
  }
}

fn eat() {
  if speed == 0 || eaten[me] { return; }
  if (me + 1) % 3 != 0 {
    lose();
    return;
  }
  eaten[me] = true;
  score += 1;
  if score == 8 {
    result = "You win";
    speed = 0;
  }
}

// The troggle steps toward you: across, then up or down.
every speed {
  let c = trog % 5;
  let r = trog / 5;
  if c != me % 5 {
    c += (me % 5 - c) / abs(me % 5 - c);
  } else if r != me / 5 {
    r += (me / 5 - r) / abs(me / 5 - r);
  }
  trog = r * 5 + c;
  caught();
}

on key "left" { walk(-1, 0); }
on key "right" { walk(1, 0); }
on key "up" { walk(0, -1); }
on key "down" { walk(0, 1); }
on key "space" { eat(); }

fn scene() {
  let cells = [-1; 25];
  cells[trog] = 1;
  cells[me] = 2;
  pixels(cells, 0, 0, 5, 20);
  for i in 0..25 {
    if !eaten[i] { text(i + 1, i % 5 * 20 + 10, i / 5 * 20 + 10, 8, 9); }
  }
  if result != "" { text(result, 50, 50, 14, 11); }
}

label "Number Munchers";
label "Score: " + score + "   Lives: " + lives;
canvas 100, 100, scene();
if speed == 0 { button "Start" { start(); } }

// Theseus and the Minotaur: the arrows move Theseus a square, space or Wait lets a turn pass;
// then the Minotaur takes two steps toward him. Reach the exit in both mazes without being caught.
// icon: line 3 4 3 20 21 20 21 4 line 8 4 8 14 line 15 10 15 20 dot 12 8 3
state wall = [false; 36];      // the maze, 6 x 6: square c + 6 * r
state th = 0;                  // Theseus, the Minotaur and the exit: their squares
state mi = 0;
state ex = 0;
state level = 1;
state moves = 0;
state playing = false;
state result = "";

fn load() {
  let w = [7, 8, 10, 16, 20, 21, 22, 31];
  let at = [14, 23, 33];
  if level == 2 {
    w = [7, 8, 9, 10, 13, 21, 23, 28, 30];
    at = [32, 2, 4];
  }
  for i in 0..36 { wall[i] = false; }
  for i in 0..len(w) { wall[w[i]] = true; }
  th = at[0];
  mi = at[1];
  ex = at[2];
  moves = 0;
}

fn free(c: int, r: int) -> bool { return c >= 0 && c < 6 && r >= 0 && r < 6 && !wall[r * 6 + c]; }

fn sign(n: int) -> int {
  if n > 0 { return 1; }
  if n < 0 { return -1; }
  return 0;
}

// The Minotaur's two steps: across toward Theseus if it can, else up or down; whether it caught him.
fn chase() -> bool {
  for k in 0..2 {
    let c = mi % 6;
    let r = mi / 6;
    let dc = sign(th % 6 - c);
    let dr = sign(th / 6 - r);
    if dc != 0 && free(c + dc, r) {
      mi += dc;
    } else if dr != 0 && free(c, r + dr) {
      mi += dr * 6;
    }
    if mi == th { return true; }
  }
  return false;
}

fn stop(s: string) {
  result = s;
  playing = false;
}

fn turn(dc: int, dr: int) {
  let c = th % 6 + dc;
  let r = th / 6 + dr;
  if !playing || !free(c, r) { return; }
  th = r * 6 + c;
  moves += 1;
  if th == mi {
    stop("Game over");
  } else if th == ex && level == 2 {
    stop("You win");
  } else if th == ex {
    level = 2;
    load();
  } else if chase() {
    stop("Game over");
  }
}

on key "left" { turn(-1, 0); }
on key "right" { turn(1, 0); }
on key "up" { turn(0, -1); }
on key "down" { turn(0, 1); }
on key "space" { turn(0, 0); }

fn scene() {
  let cells = [-1; 36];
  for i in 0..36 {
    if wall[i] { cells[i] = 8; }
  }
  cells[ex] = 3;
  cells[th] = 2;
  cells[mi] = 1;
  pixels(cells, 0, 0, 6, 12);
  if result != "" { text(result, 36, 36, 10, 11); }
}

label "Theseus and the Minotaur";
label "Level: " + level + "   Moves: " + moves;
canvas 72, 72, scene();
row {
  if !playing {
    button "Start" {
      level = 1;
      result = "";
      load();
      playing = true;
    }
  }
  button "Wait" { turn(0, 0); }
}

// Theseus and the Minotaur: the arrows move you a square; then the Minotaur takes two steps
// toward you, across first. Reach the exit before it catches you.
// icon: line 3 4 3 20 21 20 21 4 line 8 4 8 14 line 15 10 15 20 dot 12 8 3
state wall = [false, false, false, false, false, false, true, true, false, false, false, true,
  false, false, true, false, false, true, false, false, false, false, false, false, false];
state th = 5;                  // you, the Minotaur: squares of the 5 x 5 maze, c + 5 * r
state mi = 4;
state result = "";

fn free(c: int, r: int) -> bool { return c >= 0 && c < 5 && r >= 0 && r < 5 && !wall[r * 5 + c]; }

fn sign(n: int) -> int {
  if n > 0 { return 1; }
  if n < 0 { return -1; }
  return 0;
}

fn chase() -> bool {
  for k in 0..2 {
    let c = mi % 5;
    let r = mi / 5;
    let dc = sign(th % 5 - c);
    let dr = sign(th / 5 - r);
    if dc != 0 && free(c + dc, r) {
      mi += dc;
    } else if dr != 0 && free(c, r + dr) {
      mi += dr * 5;
    }
    if mi == th { return true; }
  }
  return false;
}

fn turn(dc: int, dr: int) {
  let c = th % 5 + dc;
  let r = th / 5 + dr;
  if result != "" || !free(c, r) { return; }
  th = r * 5 + c;
  if th == mi {
    result = "Eaten! Game over";
  } else if th == 2 {
    result = "You escaped!";
  } else if chase() {
    result = "Eaten! Game over";
  }
}

