fn attempt() {
  if speed == 0 { return; }
  if dial == want() && way == need() {
    done += 1;
    if starts[safe] + done == starts[safe + 1] && safe == 2 {
      result = "You win";
      speed = 0;
    } else if starts[safe] + done == starts[safe + 1] {
      safe += 1;
      begin();
    }
  } else {
    alarm += 1;
    done = 0;
    if alarm == 3 {
      result = "Game over";
      speed = 0;
    }
  }
}

