fn lock() {
  if speed == 0 { return; }
  if dial != combos[next] {
    result = "Alarm! Game over";
    speed = 0;
    return;
  }
  next += 1;
  if next == ends[safe] {
    safe += 1;
    dial = 0;
  }
  if safe == 3 {
    result = "You win";
    speed = 0;
  }
}

