// A gene written with d dominant letters: is letter k (0 or 1) the dominant one?
fn big(d: int, k: int) -> int {
  if d == 2 || (d == 1 && k == 0) { return 1; }
  return 0;
}

// The child of parent 1's gamete r and parent 2's gamete c: its dominant letters.
fn color(r: int, c: int) -> int { return big(p1[0], r / 2) + big(p2[0], c / 2); }
fn shape(r: int, c: int) -> int { return big(p1[1], r % 2) + big(p2[1], c % 2); }

fn gene(d: int, a: string, b: string) -> string {
  if d == 2 { return a + a; }
  if d == 1 { return a + b; }
  return b + b;
}

fn genes(dc: int, ds: int) -> string { return gene(dc, "Y", "y") + gene(ds, "R", "r"); }

// How many children are yellow (or green) and round (or wrinkled).
fn count(yellow: bool, round: bool) -> int {
  let n = 0;
  for i in 0..16 {
    if (color(i / 4, i % 4) > 0) == yellow && (shape(i / 4, i % 4) > 0) == round { n += 1; }
  }
  return n;
}

fn scene() {
  let cells = [2; 16];
  for i in 0..16 {
    if color(i / 4, i % 4) > 0 { cells[i] = 3; }
  }
  pixels(cells, 0, 0, 4, 40);
  for i in 0..16 {
    let g = genes(color(i / 4, i % 4), shape(i / 4, i % 4));
    text(g, i % 4 * 40 + 20, i / 4 * 40 + 20, 10, 9);
  }
}

fn step(d: int) -> int { return (d + 2) % 3; }

