fn add() {
  let h = parse(hp, 0);
  if name == "" || h <= 0 { return; }
  let v = parse(init, 0);
  let p = len(names);
  for k in 0..len(names) {
    if p == len(names) && inits[k] < v { p = k; }
  }
  if len(names) > 0 && turn >= p { turn += 1; }
  if sel >= p { sel += 1; }
  insert(names, p, name);
  insert(inits, p, v);
  insert(hps, p, h);
  insert(tops, p, h);
}

fn change(d: int) {
  if sel < 0 { return; }
  hps[sel] = max(0, min(tops[sel], hps[sel] + d));
}

fn next() {
  for k in turn + 1..len(names) {
    if hps[k] > 0 {
      turn = k;
      return;
    }
  }
  for k in 0..len(names) {
    if hps[k] > 0 {
      turn = k;
      round += 1;
      return;
    }
  }
}

fn who() -> string {
  if len(names) == 0 { return "none"; }
  return names[turn];
}

fn shown(i: int) -> string {
  if hps[i] == 0 { return names[i] + " down"; }
  return names[i] + " HP " + hps[i];
}

fn mark(i: int) -> string {
  if i == sel { return ">"; }
  return "";
}

