// Assembler: a toy computer. Type a number and tap an instruction to add a line; Run runs the
// program, Step one line. Acc and Counter are its registers; Print writes Acc to the output.
// icon: loop 6 6 18 6 18 18 6 18 line 9 2 9 6 line 15 2 15 6 line 9 18 9 22 line 15 18 15 22
state names = ["Load", "Add", "Double", "Times", "Loop", "Print"];
state ops = [0; 0];          // each line's instruction, an index into names
state nums = [0; 0];
state num = "";
state acc = 0;
state counter = 0;
state pc = 0;
state out = "";
state note = "";             // Too many steps or Overflow

fn big(v: int) -> bool { return v > 1000000000 || v < -1000000000; }

fn put(op: int) {
  push(ops, op);
  push(nums, parse(num, 0));
}

fn shown(i: int) -> string {
  let s = i + " " + names[ops[i]];
  if ops[i] != 2 && ops[i] != 5 { s = s + " " + nums[i]; }
  return s;
}

fn reset() {
  acc = 0;
  counter = 0;
  pc = 0;
  out = "";
  note = "";
}

// The line at PC; false once the program has ended or stopped.
fn step() -> bool {
  if note != "" || pc < 0 || pc >= len(ops) { return false; }
  let op = ops[pc];
  let n = nums[pc];
  if (op == 0 || op == 3) && big(n) || op == 1 && (n > 1000000000 - acc || n < -1000000000 - acc) || op == 2 && big(acc * 2) {
    note = "Overflow";
    return false;
  }
  pc += 1;
  if op == 0 {
    acc = n;
  } else if op == 1 {
    acc += n;
  } else if op == 2 {
    acc = acc * 2;
  } else if op == 3 {
    counter = n;
  } else if op == 4 {
    counter -= 1;
    if counter > 0 { pc = n; }
  } else {
    out = out + " " + acc;
  }
  return true;
}

fn run() {
  reset();
  for k in 0..1000 {
    if !step() { return; }
  }
  if pc >= 0 && pc < len(ops) { note = "Too many steps"; }
}

label "Assembler";
