// Photo editor: pick a color and a tool, then tap the picture: Paint colors a square, Fill the
// patch of one color around it. Flip, Rotate, and Undo back to the start.
// icon: loop 3 6 21 6 21 19 3 19 ring 9 11 2 line 5 17 11 12 15 15 21 10
state first = [4, 4, 4, 4, 4, 4, 3, 3,  4, 4, 4, 4, 4, 4, 3, 3,  4, 4, 1, 1, 4, 4, 4, 4,
               4, 1, 1, 1, 1, 4, 4, 4,  4, 5, 5, 5, 5, 4, 4, 4,  2, 5, 6, 5, 5, 2, 2, 2,
               2, 5, 6, 5, 5, 2, 2, 2,  2, 2, 2, 2, 2, 2, 2, 2];
state pic = [4, 4, 4, 4, 4, 4, 3, 3,  4, 4, 4, 4, 4, 4, 3, 3,  4, 4, 1, 1, 4, 4, 4, 4,
             4, 1, 1, 1, 1, 4, 4, 4,  4, 5, 5, 5, 5, 4, 4, 4,  2, 5, 6, 5, 5, 2, 2, 2,
             2, 5, 6, 5, 5, 2, 2, 2,  2, 2, 2, 2, 2, 2, 2, 2];
state undo = [0; 0];         // the pictures before each edit, 64 squares each, the latest last
state names = ["Red", "Green", "Yellow", "Blue", "Purple", "Cyan"];
state color = 1;
state filling = false;

// Keeps the picture before an edit, the latest 30.
fn keep() {
  if len(undo) >= 30 * 64 {
    for k in 0..64 { remove(undo, 0); }
  }
  for i in 0..64 { push(undo, pic[i]); }
}

fn back() {
  let n = len(undo);
  if n < 64 { return; }
  for i in 0..64 { pic[i] = undo[n - 64 + i]; }
  for k in 0..64 { remove(undo, n - 64); }
}

// Every square of the tapped one's color joined to it, side by side.
fn fill(start: int) {
  let old = pic[start];
  let todo = [start];
  for k in 0..4096 {
    if len(todo) > 0 {
      let i = todo[len(todo) - 1];
      remove(todo, len(todo) - 1);
      if pic[i] == old {
        pic[i] = color;
        if i % 8 > 0 { push(todo, i - 1); }
        if i % 8 < 7 { push(todo, i + 1); }
        if i >= 8 { push(todo, i - 8); }
        if i < 56 { push(todo, i + 8); }
      }
    }
  }
}

fn tap(i: int) {
  if pic[i] == color { return; }
  keep();
  if filling { fill(i); } else { pic[i] = color; }
}

fn flip() {
  keep();
  let was = [0; 64];
  for i in 0..64 { was[i] = pic[i]; }
  for i in 0..64 { pic[i] = was[i / 8 * 8 + 7 - i % 8]; }
}

// A quarter turn clockwise: square (c, r) comes from (r, 7 - c).
fn turn() {
  keep();
  let was = [0; 64];
  for i in 0..64 { was[i] = pic[i]; }
  for i in 0..64 { pic[i] = was[(7 - i % 8) * 8 + i / 8]; }
}

fn tool() -> string {
  if filling { return "Fill"; }
  return "Paint";
}

fn scene() {
  pixels(pic, 0, 0, 8, 16);
  for k in 1..8 {
    line(k * 16, 0, k * 16, 128, 1, 8);
    line(0, k * 16, 128, k * 16, 1, 8);
  }
}

