fn keep() {
  if len(undo) >= 15 * 256 {
    for k in 0..256 { remove(undo, 0); }
  }
  for i in 0..256 { push(undo, art[i]); }
}

fn back() {
  let n = len(undo);
  if n < 256 { return; }
  for i in 0..256 { art[i] = undo[n - 256 + i]; }
  for k in 0..256 { remove(undo, n - 256); }
}

