// icon: fill 2 4 7 7 7 17 2 20 fill 22 4 17 7 17 17 22 20 loop 9 9 15 9 15 15 9 15
state first = [4, 4, 4, 4, 4, 4, 4, 4,  1, 0, 0, 0, 0, 0, 0, 1,  1, 0, 2, 2, 2, 2, 0, 1,
               1, 0, 2, 0, 0, 3, 0, 1,  1, 0, 2, 0, 6, 2, 0, 1,  1, 0, 2, 2, 2, 2, 0, 1,
               1, 0, 0, 0, 0, 0, 0, 1,  5, 5, 5, 5, 5, 5, 5, 5];
state map = [4, 4, 4, 4, 4, 4, 4, 4,  1, 0, 0, 0, 0, 0, 0, 1,  1, 0, 2, 2, 2, 2, 0, 1,
             1, 0, 2, 0, 0, 3, 0, 1,  1, 0, 2, 0, 6, 2, 0, 1,  1, 0, 2, 2, 2, 2, 0, 1,
             1, 0, 0, 0, 0, 0, 0, 1,  5, 5, 5, 5, 5, 5, 5, 5];   // 0 floor, else a wall's color
state names = ["North", "East", "South", "West"];
state dxs = [0, 1, 0, -1];
state dys = [-1, 0, 1, 0];
state px = 1;
state py = 1;
state face = 1;
state steps = 0;
state keys = 0;
state got = false;           // the key picked up
state won = false;

fn at(x: int, y: int) -> int { return map[y * 8 + x]; }

fn ahead() -> int {
  let n = 0;
  for k in 1..8 {
    if n == k - 1 && at(px + dxs[face] * k, py + dys[face] * k) == 0 { n = k; }
  }
  return n;
}

fn walk(s: int) {
  if won { return; }
  let x = px + dxs[face] * s;
  let y = py + dys[face] * s;
  let w = at(x, y);
  if w == 6 && s == 1 {
    won = true;
  } else if w == 3 && s == 1 && keys > 0 {
    map[y * 8 + x] = 0;
    keys -= 1;
  } else if w == 0 {
    px = x;
    py = y;
    steps += 1;
    if !got && x == 1 && y == 6 {
      got = true;
      keys += 1;
    }
  }
}

fn turn(d: int) { if !won { face = (face + d) % 4; } }

fn reset() {
  for i in 0..64 { map[i] = first[i]; }
  px = 1;
  py = 1;
  face = 1;
  steps = 0;
  keys = 0;
  got = false;
  won = false;
}

// One ray a column, 40 columns of 4 units: a grid walk (DDA) in thousandths of a square from
// the middle of yours; the wall is 100 units tall right in front, shorter with distance.
fn column(c: int) {
  let k = (2 * c + 1 - 40) * 25;
  let rx = dxs[face] * 1000 - dys[face] * 660 * k / 1000;
  let ry = dys[face] * 1000 + dxs[face] * 660 * k / 1000;
  let gx = 1000000000;
  let gy = 1000000000;
  if rx != 0 { gx = 1000000 / abs(rx); }
  if ry != 0 { gy = 1000000 / abs(ry); }
  let sx = gx / 2;
  let sy = gy / 2;
  let mx = px;
  let my = py;
  let d = 0;
  let w = 0;
  for s in 0..20 {
    if w == 0 {
      if sx < sy {
        d = sx;
        sx += gx;
        if rx > 0 { mx += 1; } else { mx -= 1; }
      } else {
        d = sy;
        sy += gy;
        if ry > 0 { my += 1; } else { my -= 1; }
      }
      w = at(mx, my);
    }
  }
  let h = min(100, 50000 / max(1, d));
  rect(c * 4, 50 - h / 2, 4, h, w);
}

fn scene() {
  rect(0, 0, 160, 50, 7);
  rect(0, 50, 160, 50, 8);
  for c in 0..40 { column(c); }
}

// The map from above: you in blue, the key while it lies there.
fn plan() {
  let b = [-1; 64];
  for i in 0..64 {
    if map[i] > 0 { b[i] = map[i]; }
  }
  if !got { b[49] = 3; }
  pixels(b, 0, 0, 8, 6);
  circle(px * 6 + 3, py * 6 + 3, 2, 9);
  circle(px * 6 + 3 + dxs[face] * 3, py * 6 + 3 + dys[face] * 3, 1, 9);
}

on key "up" { walk(1); }
on key "down" { walk(-1); }
on key "left" { turn(3); }
on key "right" { turn(1); }

label "Raycaster";
canvas 160, 100, scene();
label "Steps " + steps + "   Keys " + keys + "   Facing: " + names[face] + "   Ahead " + ahead();
if won { label "You escaped!"; }
row {
  canvas 48, 48, plan();
  button "Left" { turn(3); }
  button "Forward" { walk(1); }
  button "Back" { walk(-1); }
  button "Right" { turn(1); }
