// Trip planner: tap cities on the map to add stops; + and - set the last stop's nights, Undo
// takes it off. Type a budget to see what is left.
// icon: line 3 18 9 9 15 14 21 5 ring 3 18 2 ring 21 5 2 dot 9 9 2 dot 15 14 2
state names = ["Lisbon", "Madrid", "Paris", "Berlin", "Rome", "Vienna"];
state cx = [0, 2, 3, 7, 6, 8];
state cy = [4, 4, 1, 0, 5, 2];
state price = [60, 70, 120, 80, 90, 100];
state stops = [0; 0];        // the cities of the trip, in order
state nights = [0; 0];
state budget = "";

fn city(c: int, r: int) -> int {
  for k in 0..6 {
    if cx[k] == c && cy[k] == r { return k; }
  }
  return -1;
}

fn add(k: int) {
  let n = len(stops);
  if k < 0 || n > 0 && stops[n - 1] == k { return; }
  push(stops, k);
  push(nights, 1);
}

fn more(d: int) {
  let n = len(nights);
  if n > 0 { nights[n - 1] = max(1, min(9, nights[n - 1] + d)); }
}

fn hotels() -> int {
  let t = 0;
  for i in 0..len(stops) { t += nights[i] * price[stops[i]]; }
  return t;
}

fn travel() -> int {
  let t = 0;
  for i in 1..len(stops) {
    t += 10 * (abs(cx[stops[i]] - cx[stops[i - 1]]) + abs(cy[stops[i]] - cy[stops[i - 1]]));
  }
  return t;
}

fn total() -> int { return hotels() + travel(); }

fn nightsall() -> int {
  let t = 0;
  for i in 0..len(nights) { t += nights[i]; }
  return t;
}

fn route() -> string {
  let s = "";
  for i in 0..len(stops) {
    if i > 0 { s = s + ", "; }
    s = s + names[stops[i]];
  }
  return s;
}

fn trip(k: int) -> bool {
  for i in 0..len(stops) {
    if stops[i] == k { return true; }
  }
  return false;
}

// The map, 16 units a square: the route in lines, the cities over it.
fn scene() {
  for i in 1..len(stops) {
    line(cx[stops[i - 1]] * 16 + 8, cy[stops[i - 1]] * 16 + 8, cx[stops[i]] * 16 + 8, cy[stops[i]] * 16 + 8, 1, 4);
  }
  for k in 0..6 {
    let c = 3;
    if trip(k) { c = 2; }
    circle(cx[k] * 16 + 8, cy[k] * 16 + 8, 6, c);
  }
}

label "Trip planner";
canvas 160, 96, scene() {
  if x < 160 && y < 96 { add(city(x / 16, y / 16)); }
}
label "Route: " + route();
row {
  button "+" { more(1); }
  button "-" { more(-1); }
  button "Undo" {
    if len(stops) > 0 {
      remove(stops, len(stops) - 1);
      remove(nights, len(nights) - 1);
    }
  }
  label "Budget";
  input budget;
}
label "Stops " + len(stops) + "   Nights " + nightsall();
label "Hotels " + hotels() + "   Travel " + travel() + "   Total " + total();
label "Left " + (parse(budget, 0) - total());
if total() > parse(budget, 0) { label "Over budget"; }

// Hike planner: tap the map to add waypoints in order; the distance counts squares across plus
// up or down, 1 km each. Undo takes off the last waypoint.
// icon: line 3 20 8 8 15 15 21 4 dot 3 20 2 dot 21 4 2
state wx = [0; 0];
state wy = [0; 0];

fn km() -> int {
  let t = 0;
  for i in 1..len(wx) { t += abs(wx[i] - wx[i - 1]) + abs(wy[i] - wy[i - 1]); }
  return t;
}

// The map, 10 x 10 squares of 12 units: the waypoints, and the path between them.
