// Starship crew: move Ada, Bo and Cy between Weapons, Deflector and Repair (tap a name) while the
// battle runs. Weapons charge the guns, the Deflector the shields, Repair mends the hull.
// icon: fill 3 12 9 7 19 9 22 12 19 15 9 17 line 12 7 9 3 line 12 17 9 21
state names = ["Ada", "Bo", "Cy"];
state posts = ["Weapons", "Deflector", "Repair"];
state at = [0, 1, 2];        // each crew member's station
state time = 0;
state hull = 20;
state shields = 0;
state charge = 0;
state enemy = 15;
state speed = 0;             // 1000 while the clock runs
state begun = false;
state over = "";             // Victory or Destroyed

fn crew(s: int) -> int {
  let n = 0;
  for k in 0..3 {
    if at[k] == s { n += 1; }
  }
  return n;
}

fn reset() {
  for k in 0..3 { at[k] = k; }
  time = 0;
  hull = 20;
  shields = 0;
  charge = 0;
  enemy = 15;
  speed = 0;
  begun = false;
  over = "";
}

fn stop(why: string) {
  over = why;
  speed = 0;
}

every speed {
  time += 1;
  charge += crew(0);
  if charge >= 4 {
    charge -= 4;
    enemy = max(0, enemy - 3);
  }
  shields = min(3, shields + crew(1));
  if time % 2 == 0 { hull = min(20, hull + crew(2)); }
  if time % 3 == 0 {
    let soak = min(shields, 4);
    shields -= soak;
    hull = max(0, hull - (4 - soak));
  }
  if enemy == 0 {
    stop("Victory");
  } else if hull == 0 {
    stop("Destroyed");
  }
}

// The two ships, the shields a ring round yours, the hulls as bars.
fn scene() {
  rect(10, 30, 40, 20, 4);
  if shields > 0 { ring(30, 40, 26, shields, 6); }
  rect(110, 30, 40, 20, 1);
  rect(10, 60, hull * 2, 4, 2);
  rect(110, 60, enemy * 2, 4, 1);
  if over != "" { text(over, 80, 10, 10, 11); }
}

