  button "Start" {
    begun = true;
    speed = 1000;
  }
}
if over != "" { button "New game" { reset(); } }

// Space battle: each turn order Fire (5 damage), Shields (block the next 2 shots) or Repair (+3
// hull); then the enemy shoots for 4.
// icon: fill 2 12 10 6 16 9 21 12 16 15 10 18 line 21 12 23 12
state hull = 20;
state enemy = 30;
