// Triangle types: type the three sides' lengths; it says what kind of triangle they make.
// icon: loop 12 3 21 20 3 20 line 7 12 9 13 line 17 12 15 13
state a = "";
state b = "";
state c = "";

// A side's length, or 0 for anything but a whole number above 0.
fn side(s: string) -> int { return max(0, parse(s, 0)); }

fn kind() -> string {
  let p = side(a);
  let q = side(b);
  let r = side(c);
  if p == 0 || q == 0 || r == 0 { return "Enter three sides"; }
  // The longest side must be shorter than the other two together.
  if max(p, max(q, r)) * 2 >= p + q + r { return "Not a triangle"; }
  if p == q && q == r { return "Equilateral"; }
  if p == q || q == r || p == r { return "Isosceles"; }
  return "Scalene";
}

label "Triangle types";
row { label "Side 1"; input a; }
row { label "Side 2"; input b; }
row { label "Side 3"; input c; }
label kind();

// Triangle angles: A+ A- B+ B- set two angles; the third is what is left, and it says the kind.
// icon: loop 3 20 21 20 3 6 line 3 15 8 15 8 20
state a = 60;
state b = 60;

fn kind() -> string {
  let c = 180 - a - b;
  let big = max(a, max(b, c));
  if c <= 0 { return "Not a triangle"; }
  if big == 90 { return "Right"; }
  if big > 90 { return "Obtuse"; }
  return "Acute";
}

label "Triangle angles";
row {
  label "A: " + a;
  button "A-" { a = max(10, a - 10); }
  button "A+" { a += 10; }
}
row {
  label "B: " + b;
  button "B-" { b = max(10, b - 10); }
  button "B+" { b += 10; }
}
label "C: " + (180 - a - b);
label kind();

