               "ninth", "tenth", "eleventh", "twelfth", "thirteenth", "fourteenth", "fifteenth",
               "sixteenth", "seventeenth", "eighteenth", "nineteenth", "twentieth"];

// Up to twenty a word of its own; after that, twenty- or thirty- and the units' word.
fn word() -> string {
  if day <= 20 { return units[day]; }
  if day < 30 { return "twenty-" + units[day - 20]; }
  if day == 30 { return "thirtieth"; }
  return "thirty-" + units[day - 30];
}

