// Monty Hall: pick a door; the host opens a door with a goat; stay or switch, then Next game.
// icon: loop 5 3 19 3 19 21 5 21 dot 15 12 2
state game = 0;           // games before this one
state pick = 0;           // the door picked, 0 before a pick
state opened = 0;         // the door the host opened
state end = 0;            // the door ended at, 0 before Stay or Switch

// The door the car is behind this game: 1, 2, 3 in turn.
fn car() -> int { return game % 3 + 1; }

// A pick, once a game; the host opens the first door that is neither it nor the car's.
fn choose(d: int) {
  if pick != 0 { return; }
  pick = d;
  for k in 1..4 {
    if opened == 0 && k != pick && k != car() { opened = k; }
  }
}

fn outcome() -> string {
  if end == car() { return "You win"; }
  return "You lose";
}

label "Monty Hall";
if pick == 0 {
  label "Pick a door";
} else {
  label "Door " + opened + " has a goat";
}
if end != 0 { label outcome(); }
row {
  for d in 1..4 { button "Door " + d { choose(d); } }
}
if pick != 0 && end == 0 {
  row {
    button "Stay" { end = pick; }
    button "Switch" { end = 6 - pick - opened; }
  }
}
if end != 0 {
  button "Next game" {
    game += 1;
    pick = 0;
    opened = 0;
    end = 0;
  }
}

// Take-home pay: type a yearly salary; it works out the tax (none to 12000, 20% to 50000,
// 40% above) and what is left a year and a month.
// icon: loop 2 6 22 6 22 18 2 18 ring 12 12 3
state salary = "";

fn pay() -> int { return max(0, parse(salary, 0)); }

// 20% of the part from 12000 to 50000 and 40% of the part above, rounded down once.
fn tax() -> int {
  let s = pay();
  let low = max(0, min(s, 50000) - 12000);
  let high = max(0, s - 50000);
  return (low * 20 + high * 40) / 100;
}

fn net() -> int { return pay() - tax(); }

label "Take-home pay";
row {
  label "Yearly salary";
  input salary;
}
label "Tax to pay: " + tax();
label "Net per year: " + net();
label "Net per month: " + net() / 12;

// Weekly pay: type the hourly rate and the hours worked; hours past 40 pay one and a half
// times the rate. It shows the week's pay and a year of such weeks.
// icon: ring 12 12 9 line 12 6 12 12 16 15
state rate = "";
state hours = "";

fn num(s: string) -> int { return max(0, parse(s, 0)); }

fn extra() -> int { return max(0, num(hours) - 40); }

// The first 40 hours at the rate, the rest at one and a half times it, rounded down.
fn week() -> int {
  let r = num(rate);
  return r * (num(hours) - extra()) + r * extra() * 3 / 2;
}

label "Weekly pay";
row {
  label "Rate per hour";
  input rate;
}
row {
  label "Hours this week";
  input hours;
}
label "Overtime hours: " + extra();
label "Week's pay: " + week();
label "Year's pay: " + week() * 52;

// Carry-on packer: type an item and its weight in grams, then Add; Remove takes one off.
// It adds up the weight against a 7000 g limit.
// icon: loop 4 8 20 8 20 21 4 21 line 9 8 9 4 15 4 15 8
state names = [""; 0];
state grams = [0; 0];
state item = "";
state weight = "";

fn total() -> int {
  let t = 0;
  for i in 0..len(grams) { t += grams[i]; }
  return t;
}

// What is left under the limit, or how far over it the bag is.
