state logs = [0; 0];      // the readings, in kWh, a day apart

fn latest() -> int { return logs[len(logs) - 1]; }

// Whether n can be logged: a number, and not below the last reading.
fn takes(n: int) -> bool {
  if n < 0 { return false; }
  if len(logs) == 0 { return true; }
  return n >= latest();
}

fn used() -> int {
  if len(logs) < 2 { return 0; }
  return latest() - logs[0];
}

fn average() -> int {
  if len(logs) < 2 { return 0; }
  return used() / (len(logs) - 1);
}

fn highest() -> int {
  let h = 0;
  for i in 0..len(logs) {
    if i > 0 { h = max(h, logs[i] - logs[i - 1]); }
  }
  return h;
}

