// Stairs: type the floor-to-floor rise and the tread depth in mm; it works out the risers (none
// over 180 mm), their height, the treads and the stair's run.
// icon: line 2 21 2 17 7 17 7 12 12 12 12 7 17 7 17 3 22 3 line 2 21 22 21 22 3
state rise = "";
state depth = "";

fn num(s: string) -> int { return max(0, parse(s, 0)); }

// The fewest risers of at most 180 mm: the rise over 180, rounded up.
fn risers() -> int { return (num(rise) + 179) / 180; }

// The rise over the risers, to the nearest mm (a half up).
fn height() -> int {
  if risers() == 0 { return 0; }
  return (2 * num(rise) + risers()) / (2 * risers());
}

fn treads() -> int { return max(0, risers() - 1); }

