// 24 solver: type four numbers and press Solve; it shows a way to make 24 with + - * and /
// (fractions allowed along the way), or says it can't be done.
// icon: loop 3 3 21 3 21 21 3 21 line 7 12 17 12 line 12 7 12 17
state a = "";
state b = "";
state c = "";
state d = "";
state answer = "";
state vn = [0; 4];            // the numbers at each step: numerators, denominators, how made
state vd = [1; 4];
state vs = [""; 4];
state rn = 0;                 // one operation's result
state rd = 1;
state rs = "";

// Operation k on (an/ad, sa) and (bn/bd, sb): + - * / and the - and / the other way round.
fn calc(k: int, an: int, ad: int, sa: string, bn: int, bd: int, sb: string) -> bool {
  if k == 0 { rn = an * bd + bn * ad; rd = ad * bd; rs = "(" + sa + " + " + sb + ")"; }
  if k == 1 { rn = an * bd - bn * ad; rd = ad * bd; rs = "(" + sa + " - " + sb + ")"; }
  if k == 2 { rn = bn * ad - an * bd; rd = ad * bd; rs = "(" + sb + " - " + sa + ")"; }
  if k == 3 { rn = an * bn; rd = ad * bd; rs = "(" + sa + " * " + sb + ")"; }
  if k == 4 {
    if bn == 0 { return false; }
    rn = an * bd;
    rd = ad * bn;
    rs = "(" + sa + " / " + sb + ")";
  }
  if k == 5 {
    if an == 0 { return false; }
    rn = bn * ad;
    rd = bd * an;
    rs = "(" + sb + " / " + sa + ")";
  }
  return true;
}

// The last two numbers: whether some operation makes 24.
fn two(pn: int, pd: int, ps: string, qn: int, qd: int, qs: string) -> bool {
  for k in 0..6 {
    if calc(k, pn, pd, ps, qn, qd, qs) && rn == 24 * rd {
      answer = rs + " = 24";
      return true;
    }
  }
  return false;
}

// Three numbers (vn, vd, vs from 0 to 2): combine a pair, then the last two.
fn three() -> bool {
  for p in 0..3 {
    let i = 0;                // the pairs 0 1, 0 2, 1 2, and o the one left
    let j = p + 1;
    if p == 2 { i = 1; j = 2; }
    let o = 3 - i - j;
    for k in 0..6 {
      if calc(k, vn[i], vd[i], vs[i], vn[j], vd[j], vs[j]) {
        if two(rn, rd, rs, vn[o], vd[o], vs[o]) { return true; }
      }
    }
  }
  return false;
}

fn solve() {
  let ns = [parse(a, -1), parse(b, -1), parse(c, -1), parse(d, -1)];
  for i in 0..4 {
    if ns[i] < 0 || ns[i] > 100 {
      answer = "Type four whole numbers from 0 to 100";
      return;
    }
  }
  for p in 0..6 {
    let i = 0;
    let j = p + 1;
    if p >= 3 { i = 1; j = p - 1; }
    if p == 5 { i = 2; j = 3; }
    let rest = [0; 0];
    for m in 0..4 {
      if m != i && m != j { push(rest, m); }
    }
    for k in 0..6 {
      let si = "" + ns[i];
      let sj = "" + ns[j];
      if calc(k, ns[i], 1, si, ns[j], 1, sj) {
        vn = [rn, ns[rest[0]], ns[rest[1]], 0];
        vd = [rd, 1, 1, 1];
        vs = [rs, "" + ns[rest[0]], "" + ns[rest[1]], ""];
        if three() { return; }
      }
    }
  }
  answer = "No solution: 24 can't be made";
}

