// A random free square for number k.
fn free(k: int) {
  let s = random(25);
  let put = false;
  for j in 0..25 {
    let i = (s + j) % 25;
    if !put && at[i] == 0 {
      at[i] = k;
      put = true;
    }
  }
}

fn deal() {
  at = [0; 25];
  for k in 1..level + 4 {
    if first { at[(k * 7) % 25] = k; } else { free(k); }
  }
  next = 1;
  shown = true;
}

fn tap(i: int) {
  if !playing || at[i] == 0 { return; }
  if at[i] != next {
    playing = false;
    over = true;
    shown = true;
    first = false;
    return;
  }
  at[i] = 0;
  shown = false;
  next += 1;
  if next == level + 4 {
    best = max(best, level);
    level += 1;
    deal();
  }
}

fn scene() {
  for i in 0..25 {
    if at[i] > 0 {
      rect((i % 5) * 24 + 1, (i / 5) * 24 + 1, 22, 22, 4);
      if shown { text(at[i], (i % 5) * 24 + 12, (i / 5) * 24 + 12, 12, 9); }
