// Ship, captain and crew: type each throw of the dice still in play (like 61423) and press
// Roll. It keeps the 6, then the 5, then the 4; the other two dice are the cargo.
// icon: line 3 14 21 14 17 20 7 20 3 14 line 12 14 12 3 fill 12 4 19 11 12 11
state throw = "";
state kept = 0;           // 0 nothing, 1 the ship, 2 and the captain, 3 and the crew
state rolls = 3;
state cargo = 0;
