// How many times digit d is in n.
fn count(n: int, d: int) -> int {
  let k = 0;
  let m = n;
  repeat 6 {
    if m % 10 == d { k += 1; }
    m = m / 10;
  }
  return k;
}

// Whether the throw has exactly the dice still in play, each 1 to 6.
fn fair(n: int) -> bool {
  if n <= 0 || len(throw) != 5 - kept { return false; }
  let m = n;
  for i in 0..len(throw) {
    if m % 10 < 1 || m % 10 > 6 { return false; }
    m = m / 10;
  }
  return m == 0;
}

fn roll() {
  let n = parse(throw, -1);
  if over || !fair(n) { return; }
  let sum = 0;
  let m = n;
  for i in 0..len(throw) {
    sum += m % 10;
    m = m / 10;
  }
  if kept == 0 && count(n, 6) > 0 { kept = 1; sum -= 6; }
  if kept == 1 && count(n, 5) > 0 { kept = 2; sum -= 5; }
  if kept == 2 && count(n, 4) > 0 { kept = 3; sum -= 4; }
  rolls -= 1;
  if kept == 3 {
    cargo = sum;
    over = true;
  } else if rolls == 0 {
    cargo = 0;
    over = true;
  }
}

fn need() -> int { return 6 - kept; }

