// Untangle: tap a dot, then an empty square, to move it there. Move the dots until no two
// lines cross.
// icon: line 5 5 19 19 line 19 5 5 19 dot 5 5 3 dot 19 19 3 dot 19 5 3 dot 5 19 3
state px = [3, 4, 5, 3, 5, 1];
state py = [2, 0, 2, 5, 1, 1];
state ea = [0, 1, 2, 3, 4, 5, 0, 0, 3];      // the lines: from dot ea[i] to dot eb[i]
state eb = [1, 2, 3, 4, 5, 0, 2, 3, 5];
state pick = -1;
state moves = 0;

// Which side of the line from dot a to dot b dot c lies on: 1, -1, or 0 on it.
fn side(a: int, b: int, c: int) -> int {
  let v = (px[b] - px[a]) * (py[c] - py[a]) - (py[b] - py[a]) * (px[c] - px[a]);
  if v > 0 { return 1; }
  if v < 0 { return -1; }
  return 0;
}

fn crosses(i: int, j: int) -> bool {
  let a = ea[i];
  let b = eb[i];
  let c = ea[j];
  let d = eb[j];
  if a == c || a == d || b == c || b == d { return false; }
  return side(a, b, c) * side(a, b, d) < 0 && side(c, d, a) * side(c, d, b) < 0;
}

fn crossings() -> int {
  let n = 0;
  for i in 0..len(ea) {
    for j in i + 1..len(ea) {
      if crosses(i, j) { n += 1; }
    }
  }
  return n;
}

// The dot on square (c, r), else -1.
fn dotat(c: int, r: int) -> int {
  for i in 0..len(px) {
    if px[i] == c && py[i] == r { return i; }
  }
  return -1;
}

fn tap(c: int, r: int) {
  if crossings() == 0 { return; }
  let d = dotat(c, r);
  if d >= 0 {
    pick = d;
  } else if pick >= 0 {
    px[pick] = c;
    py[pick] = r;
    pick = -1;
    moves += 1;
  }
}

fn hue(i: int) -> int {
  if i == pick { return 1; }
  return 4;
}

fn scene() {
  for i in 0..36 { rect(i % 6 * 20 + 9, i / 6 * 20 + 9, 2, 2, 8); }
  for i in 0..len(ea) {
    line(px[ea[i]] * 20 + 10, py[ea[i]] * 20 + 10, px[eb[i]] * 20 + 10, py[eb[i]] * 20 + 10, 2, 10);
  }
  for i in 0..len(px) { circle(px[i] * 20 + 10, py[i] * 20 + 10, 6, hue(i)); }
}

