// Which side of the line from dot a to dot b dot c lies on: 1, -1, or 0 on it.
fn side(a: int, b: int, c: int) -> int {
  let v = (px[b] - px[a]) * (py[c] - py[a]) - (py[b] - py[a]) * (px[c] - px[a]);
  if v > 0 { return 1; }
  if v < 0 { return -1; }
  return 0;
}

// Whether the line from dot i to the next crosses the line from dot j to the next.
fn crosses(i: int, j: int) -> bool {
  let n = len(px);
  let b = (i + 1) % n;
  let d = (j + 1) % n;
  if i == j || i == d || b == j || b == d { return false; }
  return side(i, b, j) * side(i, b, d) < 0 && side(j, d, i) * side(j, d, b) < 0;
}

fn tangled() -> bool {
  for i in 0..len(px) {
    for j in 0..len(px) {
      if crosses(i, j) { return true; }
    }
  }
  return false;
}

fn dotat(c: int, r: int) -> int {
  for i in 0..len(px) {
    if px[i] == c && py[i] == r { return i; }
  }
  return -1;
}

fn tap(c: int, r: int) {
  let d = dotat(c, r);
  if d >= 0 {
    pick = d;
  } else if pick >= 0 {
    px[pick] = c;
    py[pick] = r;
    pick = -1;
  }
}

fn hue(i: int) -> int {
  if i == pick { return 3; }
  return 4;
}

