fn empty() -> int {
  let n = 0;
  for i in 0..16 {
    if nums[i] == 0 { n += 1; }
  }
  return n;
}

// Whether squares i and j share a row or a column and hold the same number.
fn clash(i: int, j: int) -> bool {
  return i != j && nums[i] == nums[j] && (i / 4 == j / 4 || i % 4 == j % 4);
}

fn solved() -> bool {
  if empty() > 0 { return false; }
  for i in 0..16 {
    for j in 0..16 {
      if clash(i, j) { return false; }
    }
  }
  for k in 0..len(big) {
    if nums[big[k]] <= nums[small[k]] { return false; }
  }
  return true;
}

fn put(v: int) {
  if pick >= 0 && !solved() { nums[pick] = v; }
}

fn tap(i: int) {
  if solved() { return; }
  pick = -1;
  if given[i] == 0 { pick = i; }
}

// A sign's mark, its open side toward the greater square.
fn mark(a: int, b: int) -> string {
  if a / 4 == b / 4 && a < b { return ">"; }
  if a / 4 == b / 4 { return "<"; }
  if a < b { return "v"; }
  return "^";
}

