state nums = [0; 25];                               // what was written, given squares 0
state big = [0, 1, 5, 11, 12, 14, 15, 17, 23];     // square big[k] is greater than small[k]
state small = [1, 2, 10, 6, 13, 13, 16, 18, 24];
state pick = -1;

fn at(i: int) -> int { return given[i] + nums[i]; }

fn clash(i: int, j: int) -> bool {
  return i != j && at(i) == at(j) && (i / 5 == j / 5 || i % 5 == j % 5);
}

fn solved() -> bool {
  for i in 0..25 {
    if at(i) == 0 { return false; }
    for j in 0..25 {
      if clash(i, j) { return false; }
    }
  }
  for k in 0..len(big) {
    if at(big[k]) <= at(small[k]) { return false; }
  }
  return true;
