state cells = [0; 25];     // 0 blank, 1 X, 4 O
state turn = 1;
state pick = -1;
state win = 0;

fn edge(i: int) -> bool { return i % 5 == 0 || i % 5 == 4 || i / 5 == 0 || i / 5 == 4; }

// Whether t is an end of the row or column of p, other than p.
fn dest(p: int, t: int) -> bool {
  let rowend = t / 5 == p / 5 && (t % 5 == 0 || t % 5 == 4);
  let colend = t % 5 == p % 5 && (t / 5 == 0 || t / 5 == 4);
  return t != p && (rowend || colend);
}

// The cube at p goes in at t; the ones between slide one square toward p.
fn shove(p: int, t: int) {
  let s = 5;
  if t / 5 == p / 5 { s = 1; }
  if t < p { s = -s; }
  let k = p;
  repeat 4 {
    if k != t {
      cells[k] = cells[k + s];
      k += s;
    }
  }
  cells[t] = turn;
}

// Whether the five squares from a, stepping s, all hold m.
fn five(a: int, s: int, m: int) -> bool {
  for k in 0..5 {
    if cells[a + k * s] != m { return false; }
  }
  return true;
}

fn lined(m: int) -> bool {
  for k in 0..5 {
    if five(k * 5, 1, m) || five(k, 5, m) { return true; }
  }
  return five(0, 6, m) || five(4, 4, m);
}

