// Scopa against the computer: Start deals; tap a card to play it. It takes a table card of its value,
// else cards adding up to it; clearing the table is a scopa. Most points wins.
// icon: loop 3 5 13 5 13 20 3 20 loop 11 3 21 3 21 18 11 18 dot 16 10 2
state deck = [6, 9, 6, 6, 1, 2, 4, 8, 7, 6, 10, 1, 1, 5, 5, 1, 4, 3, 3, 8, 10, 4, 5, 5, 9, 3, 7, 9,
  10, 2, 9, 7, 8, 8, 10, 7, 4, 2, 3, 2];
state pos = 0;
state me = [0; 0];
state cp = [0; 0];
state table = [0; 0];
state mine = 0;          // cards on my pile, and the computer's
state its = 0;
state ms = 0;            // scope: mine, and the computer's
state cs = 0;
state last = 0;          // who took last: 1 me, 2 the computer
state over = false;

// The table cards a card of value v takes, as bits: one of its value, else the fewest adding up to it.
fn best(v: int) -> int {
  let bit = 1;
  for i in 0..len(table) {
    if table[i] == v { return bit; }
    bit = bit * 2;
  }
  let found = 0;
  let fewest = 99;
  for m in 1..bit {
    let s = 0;
    let n = 0;
    let b = m;
    for i in 0..len(table) {
      if b % 2 == 1 {
        s += table[i];
        n += 1;
      }
      b = b / 2;
    }
    if s == v && n < fewest {
      found = m;
      fewest = n;
    }
  }
  return found;
}

fn deal() {
  for k in 0..3 {
    push(me, deck[pos + k]);
    push(cp, deck[pos + 3 + k]);
  }
  pos += 6;
}

// Who (1 me, 2 the computer) plays card v.
fn play(who: int, v: int) {
  let m = best(v);
  if m == 0 {
    push(table, v);
  } else {
    let n = 1;
    let t = len(table);
    for k in 0..t {
      let i = t - 1 - k;
      let b = m;
      repeat i { b = b / 2; }
      if b % 2 == 1 {
        remove(table, i);
        n += 1;
      }
    }
    if who == 1 { mine += n; } else { its += n; }
    last = who;
    if len(table) == 0 && (pos < 40 || len(me) + len(cp) > 0) {
      if who == 1 { ms += 1; } else { cs += 1; }
    }
  }
  if len(me) + len(cp) == 0 {
    if pos < 40 {
      deal();
    } else {
      if last == 1 { mine += len(table); } else { its += len(table); }
      clear(table);
      over = true;
    }
  }
}

fn computer() {
  let pick = 0;
  for i in 0..len(cp) {
    if best(cp[len(cp) - 1 - i]) > 0 { pick = len(cp) - 1 - i; }
  }
  let v = cp[pick];
  remove(cp, pick);
  play(2, v);
}

fn mine_turn(i: int) {
  let v = me[i];
  remove(me, i);
  play(1, v);
  if !over { computer(); }
}

fn points(a: int, b: int, s: int) -> int {
  if a > b { return s + 1; }
  return s;
}

fn result() -> string {
  let a = points(mine, its, ms);
  let b = points(its, mine, cs);
  if a > b { return "You win!"; }
  if b > a { return "Computer wins!"; }
  return "Draw";
}

fn scene() {
  for i in 0..len(table) {
    rect(i * 20 + 2, 4, 16, 24, 7);
    text(table[i], i * 20 + 10, 16, 10, 9);
  }
}

