// Thermometers: fill each thermometer from its bulb so every row and column holds its number of
// filled squares. Tap a square to fill up to it; tap the last filled square to empty it.
// icon: line 12 3 12 13 dot 12 17 5 line 16 5 19 5 line 16 9 19 9
state cells = [0, 5, 10, 1, 2, 3, 4, 9, 8, 7, 6, 12, 13, 14, 21, 16, 11, 15, 20, 24, 23, 22, 17, 18, 19];
state starts = [0, 3, 7, 11, 14, 17, 19, 22];   // each thermometer's squares in cells, bulb first
state sizes = [3, 4, 4, 3, 3, 2, 3, 3];
state fill = [0; 8];                            // how many squares of each are filled
state need = [3, 4, 1, 4, 3];                   // the rows' numbers
state needc = [3, 3, 4, 3, 2];                  // the columns'

// The thermometer that holds square i.
fn which(i: int) -> int {
  for t in 0..8 {
    for k in 0..sizes[t] {
      if cells[starts[t] + k] == i { return t; }
    }
  }
  return 0;
}

// How far square i is from its bulb (the bulb 0).
fn place(i: int) -> int {
  let t = which(i);
  for k in 0..sizes[t] {
    if cells[starts[t] + k] == i { return k; }
  }
  return 0;
}

fn full(i: int) -> bool { return place(i) < fill[which(i)]; }

fn tap(i: int) {
  let t = which(i);
  let k = place(i) + 1;
  if fill[t] == k { fill[t] = k - 1; } else { fill[t] = k; }
}

fn solved() -> bool {
  for a in 0..5 {
    let across = 0;
    let down = 0;
    for b in 0..5 {
      if full(a * 5 + b) { across += 1; }
      if full(b * 5 + a) { down += 1; }
    }
    if across != need[a] || down != needc[a] { return false; }
  }
  return true;
}

fn cx(i: int) -> int { return i % 5 * 20 + 10; }
fn cy(i: int) -> int { return i / 5 * 20 + 10; }

// A thermometer: a silver tube and bulb, red from the bulb as far as it is filled.
fn tube(t: int) {
  let a = cells[starts[t]];
  let z = cells[starts[t] + sizes[t] - 1];
  line(cx(a), cy(a), cx(z), cy(z), 8, 7);
  circle(cx(a), cy(a), 7, 7);
  if fill[t] > 0 {
    let e = cells[starts[t] + fill[t] - 1];
    line(cx(a), cy(a), cx(e), cy(e), 8, 1);
    circle(cx(a), cy(a), 7, 1);
  }
}

