      circle(i % 5 * 20 + 10, i / 5 * 20 + 10, 8, tc[i]);
      circle(i % 5 * 20 + 10, i / 5 * 20 + 10, 5, middle(i));
    }
  }
  if pick >= 0 { ring(pick % 5 * 20 + 10, pick / 5 * 20 + 10, 10, 2, 11); }
}

fn status() -> string {
  if winner == 1 { return "Black wins"; }
  if winner == 2 { return "White wins"; }
  if turn == 1 { return "Black's turn"; }
  return "White's turn";
}

