// Blob drop: pairs of blobs fall; arrows move them, up turns, space drops. Four or more of a
// color joined by sides pop, and what falls into the gaps can pop again.
// icon: dot 8 16 4 dot 16 16 4 dot 8 8 4 ring 16 8 4
state board = [0; 60];
state tops = [2, 1, 2, 1, 1];       // each pair's upper blob, in order
state lows = [2, 1, 1, 2, 1];       // and its lower one
state k = 0;
state px = 2;                       // the lower blob's square
state py = 1;
state ox = 0;                       // where the upper one is from it
state oy = -1;
state pc = 0;                       // the falling pair's colors; 0 none
state oc = 0;
state speed = 0;
state score = 0;
state over = false;

fn free(x: int, y: int) -> bool {
  if x < 0 || x > 5 || y < 0 || y > 9 { return false; }
  return board[y * 6 + x] == 0;
}

fn fits(x: int, y: int) -> bool { return free(x, y) && free(x + ox, y + oy); }

fn spawn() {
  pc = lows[k];
  oc = tops[k];
  k = (k + 1) % 5;
  px = 2;
  py = 1;
  ox = 0;
  oy = -1;
  if !fits(2, 1) {
    over = true;
    speed = 0;
    pc = 0;
  }
}

// Every blob falls as far as it can.
fn settle() {
  for x in 0..6 {
    let w = 9;
    for j in 0..10 {
      let v = board[(9 - j) * 6 + x];
      if v > 0 {
        board[(9 - j) * 6 + x] = 0;
        board[w * 6 + x] = v;
        w -= 1;
      }
    }
  }
}

fn same(i: int, j: int) -> bool { return board[i] > 0 && board[i] == board[j]; }

// Pops every group of 4 or more; whether any popped.
fn pop() -> bool {
  let group = [0; 60];
  for i in 0..60 { group[i] = i; }
  let moved = true;
  for pass in 0..60 {
    if moved {
      moved = false;
      for i in 0..60 {
        if board[i] > 0 {
          let g = group[i];
          if i % 6 > 0 && same(i, i - 1) { g = min(g, group[i - 1]); }
          if i % 6 < 5 && same(i, i + 1) { g = min(g, group[i + 1]); }
          if i >= 6 && same(i, i - 6) { g = min(g, group[i - 6]); }
          if i < 54 && same(i, i + 6) { g = min(g, group[i + 6]); }
          if g < group[i] {
            group[i] = g;
            moved = true;
          }
        }
      }
    }
  }
  let size = [0; 60];
  for i in 0..60 { if board[i] > 0 { size[group[i]] += 1; } }
  let any = false;
  for i in 0..60 {
    if board[i] > 0 && size[group[i]] >= 4 {
      board[i] = 0;
      score += 10;
      any = true;
    }
  }
  return any;
}

fn land() {
  board[py * 6 + px] = pc;
  board[(py + oy) * 6 + px + ox] = oc;
  pc = 0;
  settle();
  let going = true;
  for round in 0..30 {
    if going {
      going = pop();
      settle();
    }
  }
  spawn();
}

fn shift(d: int) { if pc > 0 && fits(px + d, py) { px += d; } }

fn turn() {
  if pc > 0 && free(px - oy, py + ox) {
    let t = ox;
    ox = -oy;
    oy = t;
  }
}

fn drop() {
  if pc == 0 { return; }
  for j in 0..10 { if fits(px, py + 1) { py += 1; } }
  land();
}

fn start() {
  for i in 0..60 { board[i] = 0; }
  score = 0;
  k = 0;
  over = false;
  speed = 500;
  spawn();
}

fn scene() {
  let b = [0; 60];
  for i in 0..60 { b[i] = board[i]; }
  if pc > 0 {
    b[py * 6 + px] = pc;
    b[(py + oy) * 6 + px + ox] = oc;
  }
  pixels(b, 0, 0, 6, 12);
  if over { text("Game over", 36, 60, 10, 11); }
}

every speed {
  if fits(px, py + 1) { py += 1; } else { land(); }
}

