// Cribbage: one deal against the computer. Click your cards to play them; it answers with its
// first card that fits. After the play both hands are counted with the starter, 5S.
// icon: loop 4 4 13 4 13 18 4 18 loop 11 7 20 7 20 21 11 21 dot 8 9 2 dot 16 16 2
state ranks = [7, 6, 12, 2, 8, 11, 12, 12];   // mine, then the computer's
state suits = [3, 3, 3, 3, 2, 4, 3, 2];       // 1 C 2 D 3 H 4 S
state names = ["7H", "6H", "QH", "2H", "8D", "JS", "QH", "QD"];
state used = [false; 8];
state seq = [0; 0];       // the ranks played since the count began
state count = 0;
state score = [0, 0];     // mine, the computer's
state last = 0;           // who played last: 0 me, 1 the computer
state done = false;

fn val(r: int) -> int { return min(r, 10); }

// Points for the card just played: 15, 31, pairs, a run among the last cards.
fn pegged() -> int {
  let n = len(seq);
  let pts = 0;
  if count == 15 || count == 31 { pts += 2; }
  let same = 1;
  for k in 1..n {
    if same == k && seq[n - 1 - k] == seq[n - 1] { same += 1; }
  }
  pts += same * (same - 1);
  let run = 0;
  for m in 3..n + 1 {
    let lo = 14;
    let hi = 0;
    let twice = false;
    for a in n - m..n {
      lo = min(lo, seq[a]);
      hi = max(hi, seq[a]);
      for b in a + 1..n { if seq[a] == seq[b] { twice = true; } }
    }
    if !twice && hi - lo == m - 1 { run = m; }
  }
  return pts + run;
}

fn can(p: int) -> bool {
  for i in p * 4..p * 4 + 4 {
    if !used[i] && count + val(ranks[i]) <= 31 { return true; }
  }
  return false;
}

fn play(i: int) {
  used[i] = true;
  count += val(ranks[i]);
  push(seq, ranks[i]);
  last = i / 4;
  score[last] += pegged();
}

// A hand (cards p * 4 to p * 4 + 3) counted with the starter, 5S.
fn hand(p: int) -> int {
  let r = [5, 0, 0, 0, 0];
  let s = [4, 0, 0, 0, 0];
  for k in 0..4 {
    r[k + 1] = ranks[p * 4 + k];
    s[k + 1] = suits[p * 4 + k];
  }
  let pts = 0;
  let runs = [0, 0, 0, 0, 0, 0];
  for m in 1..32 {
    let sum = 0;
    let n = 0;
    let lo = 14;
    let hi = 0;
    let bit = 1;
    let seen = [false; 14];
    let twice = false;
    for k in 0..5 {
      if m / bit % 2 == 1 {
        sum += val(r[k]);
        n += 1;
        lo = min(lo, r[k]);
        hi = max(hi, r[k]);
        if seen[r[k]] { twice = true; }
        seen[r[k]] = true;
      }
      bit = bit * 2;
    }
    if sum == 15 { pts += 2; }
    if n == 2 && twice { pts += 2; }
    if n >= 3 && !twice && hi - lo == n - 1 { runs[n] += 1; }
  }
  if runs[5] > 0 { pts += 5 * runs[5]; } else if runs[4] > 0 { pts += 4 * runs[4]; } else { pts += 3 * runs[3]; }
  if s[1] == s[2] && s[2] == s[3] && s[3] == s[4] {
    pts += 4;
    if s[0] == s[1] { pts += 1; }
  }
  for k in 1..5 {
    if r[k] == 11 && s[k] == s[0] { pts += 1; }
  }
  return pts;
}

// After my card: the computer plays while it may; goes and new counts; the show at the end.
fn answer() {
  let turn = 1;
  for step in 0..20 {
    if !done {
      if can(turn) {
        if turn == 0 { return; }
        let pick = -1;
        for i in 4..8 {
          if pick < 0 && !used[i] && count + val(ranks[i]) <= 31 { pick = i; }
        }
        play(pick);
        turn = 0;
      } else if can(1 - turn) {
        turn = 1 - turn;
      } else {
        if count != 31 { score[last] += 1; }
        count = 0;
        clear(seq);
        turn = 1 - last;
        let all = true;
        for i in 0..8 { if !used[i] { all = false; } }
        if all {
          score[0] += hand(0);
          score[1] += hand(1);
          done = true;
        }
      }
    }
  }
}

fn verdict() -> string {
  if score[0] > score[1] { return "You win"; }
  if score[1] > score[0] { return "Computer wins"; }
  return "Tie";
}

// The cards played since the count began.
fn scene() {
  for k in 0..len(seq) {
    rect(k * 22 + 1, 2, 20, 28, 7);
    text(seq[k], k * 22 + 11, 16, 10, 9);
  }
}

