// Portal maze: the arrows move you a square; a portal sends you to its twin. Reach the exit of
// both mazes.
// icon: ring 7 12 5 ring 17 12 5 line 11 12 13 12
state wall = [false; 49];      // the maze, 7 x 7: square c + 7 * r
state pp = [0, 0];             // the purple portals
state cc = [0, 0];             // the cyan ones
state me = 0;
state ex = 0;
state level = 1;
state moves = 0;
state playing = false;
state result = "";

fn load() {
  let w = [3, 8, 10, 12, 15, 16, 17, 19, 24, 26, 28, 29, 31, 32, 33, 40, 43, 44, 45];
  let at = [0, 20, 9, 25, 35, 46];
  if level == 2 {
    w = [3, 8, 10, 11, 12, 15, 17, 21, 22, 23, 24, 25, 26, 27, 35, 36, 37, 38, 39, 41];
    at = [44, 4, 16, 34, 14, 18];
  }
  for i in 0..49 { wall[i] = false; }
  for i in 0..len(w) { wall[w[i]] = true; }
  me = at[0];
  ex = at[1];
  pp[0] = at[2];
  pp[1] = at[3];
  cc[0] = at[4];
  cc[1] = at[5];
  moves = 0;
}

// Where a step onto square i lands: a portal's twin, else i itself.
fn land(i: int) -> int {
  if i == pp[0] { return pp[1]; }
  if i == pp[1] { return pp[0]; }
  if i == cc[0] { return cc[1]; }
  if i == cc[1] { return cc[0]; }
  return i;
}

fn step(dc: int, dr: int) {
  let c = me % 7 + dc;
  let r = me / 7 + dr;
  if !playing || c < 0 || c >= 7 || r < 0 || r >= 7 || wall[r * 7 + c] { return; }
  me = land(r * 7 + c);
  moves += 1;
  if me == ex && level == 2 {
    result = "You win";
    playing = false;
  } else if me == ex {
    level = 2;
    load();
  }
}

