// Turf duel: player 1 moves with WASD, player 2 with the arrows; each square walked onto turns
// that player's color. After 30 seconds, more squares wins.
// icon: fill 3 3 12 3 12 12 3 12 loop 12 12 21 12 21 21 12 21 dot 7 7 2
state own = [0; 64];           // the 8 x 8 board, c + 8 * r: 0 nobody's, 2 player 1's, 1 player 2's
state at = [0, 63];            // where each player stands
state left = 0;                // seconds left; 0 while no game runs
state result = "";

fn count(v: int) -> int {
  let n = 0;
  for i in 0..64 {
    if own[i] == v { n += 1; }
  }
  return n;
}

fn play() {
  for i in 0..64 { own[i] = 0; }
  at[0] = 0;
  at[1] = 63;
  own[0] = 2;
  own[63] = 1;
  result = "";
  left = 30;
}

// Player p (0 or 1) steps one square.
fn walk(p: int, dc: int, dr: int) {
  let c = at[p] % 8 + dc;
  let r = at[p] / 8 + dr;
