fn home() {
  flying = false;
  k = 0;
  sx = 4;
  sy = 3;
}

fn stop(s: string) {
  result = s;
  speed = 0;
}

fn launch() {
  if speed == 0 || flying { return; }
  flying = true;
  dx = ox[(k + 1) % 8] - ox[k];
  dy = oy[(k + 1) % 8] - oy[k];
}

every speed {
  if !flying {
    k = (k + 1) % 8;
    sx = ox[k];
    sy = oy[k];
