// Hungry hippos for two: a marble rolls into the middle; player 1 chomps with A, player 2 with L.
// The first to chomp eats it; first to 5 wins.
// icon: ring 12 13 8 dot 9 10 2 dot 15 10 2 line 8 17 16 17
state score = [0, 0];
state marble = false;          // whether a marble is in the middle
state ticks = 4;               // 500 ms steps until the next marble
