// President against West and East: click a card higher than the pile's top, or Pass. Get rid
// of your cards first to be President; the last one holding cards is Scum.
// icon: loop 4 6 12 4 15 18 7 20 loop 11 5 19 3 21 17 14 19 line 8 10 10 16
state cards = [2, 4, 5, 7, 9, 1, 3, 6, 8, 8, 1, 2, 3, 5, 7];
state who = [-1; 15];          // whose each card is: 0 me, 1 West, 2 East, -1 played
state top = 0;                 // the card on the pile, 0 while it is clear
state last = 0;                // who played it
state turn = 0;
state passes = 0;              // passes since it was played
state place = 0;               // players out so far
state mine = 0;                // my place: 0 President, 1 Vice President, 2 Scum
state playing = false;
state result = "";

fn count(p: int) -> int {
  let n = 0;
  for i in 0..15 {
    if who[i] == p { n += 1; }
  }
  return n;
}

// The next player after p who still holds cards.
fn nextOf(p: int) -> int {
  for k in 1..4 {
    if count((p + k) % 3) > 0 { return (p + k) % 3; }
  }
  return p;
}

fn holding() -> int {
  let n = 0;
  for p in 0..3 {
    if count(p) > 0 { n += 1; }
  }
  return n;
}

fn put(i: int) {
  let p = who[i];
  who[i] = -1;
  top = cards[i];
  last = p;
  passes = 0;
  if count(p) == 0 {
    if p == 0 { mine = place; }
    place += 1;
  }
  if holding() == 1 {
    if count(0) > 0 { mine = 2; }
    let words = ["President", "Vice President", "Scum"];
    result = "You are " + words[mine];
    playing = false;
  }
}

// After p plays or passes: the pile clears once all the others holding cards have passed.
fn after(p: int) {
  if !playing { return; }
  let others = 0;
  for q in 0..3 {
    if q != last && count(q) > 0 { others += 1; }
  }
  if top > 0 && passes >= others {
    top = 0;
    passes = 0;
    turn = last;
    if count(last) == 0 { turn = nextOf(last); }
  } else {
    turn = nextOf(p);
  }
}

// A computer player's turn: its lowest card that beats the top (any, leading), else a pass.
fn bot(p: int) {
  let k = -1;
  for i in 0..15 {
    if who[i] == p && cards[i] > top && (k < 0 || cards[i] < cards[k]) { k = i; }
  }
  if k >= 0 {
    put(k);
  } else {
    passes += 1;
  }
  after(p);
}

fn bots() {
  for s in 0..40 {
    if playing && turn != 0 { bot(turn); }
  }
}

fn play(i: int) {
  if !playing || turn != 0 || who[i] != 0 || cards[i] <= top { return; }
  put(i);
  after(0);
  bots();
}

fn pass() {
  if !playing || turn != 0 || top == 0 { return; }
  passes += 1;
  after(0);
  bots();
}

fn pile() -> string {
  if top == 0 { return "none"; }
  return "" + top;
}

