// robots close in each second; two that meet blow up. Clear two rooms with three lives.
// icon: ring 12 6 4 line 12 10 12 16 line 6 12 18 12 line 12 16 8 22 line 12 16 16 22
state rx = [0; 0];             // the robots
state ry = [0; 0];
state starts = [8, 3, 3, 1, 2, 0, 4, 3, 2, 6, 9, 0];   // each room's robots: column, row
state px = 0;
state py = 3;
state fx = 1;                  // the way the player faces
state fy = 0;
state room = 1;
state score = 0;
state lives = 3;
state speed = 0;               // ms a step; 0 while no game runs
state result = "";

fn robot(x: int, y: int) -> int {
  for i in 0..len(rx) {
    if rx[i] == x && ry[i] == y { return i; }
  }
  return -1;
}

fn begin() {
  clear(rx);
  clear(ry);
  for k in 0..3 {
    push(rx, starts[(room - 1) * 6 + k * 2]);
    push(ry, starts[(room - 1) * 6 + k * 2 + 1]);
  }
  px = 0;
  py = 3;
  fx = 1;
  fy = 0;
}

fn start() {
  room = 1;
  score = 0;
  lives = 3;
  result = "";
  begin();
  speed = 1000;
}

fn hit() {
  lives -= 1;
  if lives == 0 {
    result = "Game over";
    speed = 0;
  } else {
    begin();
  }
}

// After robots go: an empty room leads on.
fn cleared() {
  if len(rx) > 0 { return; }
  if room == 2 {
    result = "You win";
    speed = 0;
  } else {
    room = 2;
    begin();
  }
}

fn walk(dx: int, dy: int) {
  if speed == 0 { return; }
  fx = dx;
  fy = dy;
  px = min(10, max(0, px + dx));
  py = min(6, max(0, py + dy));
  if robot(px, py) >= 0 { hit(); }
}

fn fire() {
  if speed == 0 { return; }
  let x = px + fx;
  let y = py + fy;
  for k in 0..11 {
    if x >= 0 && x <= 10 && y >= 0 && y <= 6 && robot(x, y) >= 0 {
      let i = robot(x, y);
      remove(rx, i);
      remove(ry, i);
      score += 50;
      cleared();
      return;
    }
    x += fx;
    y += fy;
  }
}

every speed {
  for i in 0..len(rx) {
    if rx[i] < px { rx[i] += 1; } else if rx[i] > px { rx[i] -= 1; }
    else if ry[i] < py { ry[i] += 1; } else if ry[i] > py { ry[i] -= 1; }
  }
  let gone = [false; 0];
  for i in 0..len(rx) {
    let same = false;
    for j in 0..len(rx) {
      if j != i && rx[j] == rx[i] && ry[j] == ry[i] { same = true; }
    }
    push(gone, same);
  }
  for k in 0..len(gone) {
    let i = len(gone) - 1 - k;
    if gone[i] { remove(rx, i); remove(ry, i); }
  }
  if robot(px, py) >= 0 { hit(); } else { cleared(); }
}

on key "left" { walk(-1, 0); }
on key "right" { walk(1, 0); }
on key "up" { walk(0, -1); }
on key "down" { walk(0, 1); }
on key "space" { fire(); }

