fn caught() -> bool {
  for i in 0..4 {
    if rx[i] == px && ry[i] == py { return true; }
  }
  return false;
}

fn check() {
  if caught() {
    result = "Game over";
    speed = 0;
  }
}

fn walk(dx: int, dy: int) {
  if speed == 0 { return; }
  fx = dx;
  fy = dy;
  px = min(8, max(0, px + dx));
  py = min(8, max(0, py + dy));
  check();
}

// The first robot along the laser, or -1.
fn first() -> int {
  let best = -1;
  let near = 99;
  for i in 0..4 {
    let ax = rx[i] - px;
    let ay = ry[i] - py;
    if rx[i] >= 0 && ax * fy == 0 && ay * fx == 0 && ax * fx + ay * fy > 0 && ax * fx + ay * fy < near {
      near = ax * fx + ay * fy;
      best = i;
    }
  }
  return best;
}

fn fire() {
  if speed == 0 { return; }
  let i = first();
  if i < 0 { return; }
  rx[i] = -1;
  ry[i] = -1;
  kills += 1;
  if kills % 4 == 0 {
    room += 1;
    begin();
  }
}

every speed {
  for i in 0..4 {
    if rx[i] >= 0 {
      if rx[i] < px { rx[i] += 1; } else if rx[i] > px { rx[i] -= 1; }
      else if ry[i] < py { ry[i] += 1; } else if ry[i] > py { ry[i] -= 1; }
    }
  }
  check();
}

