fn value(c: string) -> int {
  if c == "Egg" { return 1; }
  if c == "Salmon" { return 2; }
  if c == "Squid" { return 3; }
  return 0;
}

// Player p (0 me, 1 the computer) takes card c.
fn take(p: int, c: string) {
  if c == "Wasabi" {
    wasabi[p] += 1;
  } else if wasabi[p] > 0 {
    score[p] += 3 * value(c);
    wasabi[p] -= 1;
  } else {
    score[p] += value(c);
  }
}

fn start() {
  mine = ["Squid", "Wasabi", "Egg", "Salmon"];
  its = ["Egg", "Wasabi", "Squid", "Squid"];
  wasabi = [0, 0];
  score = [0, 0];
  result = "";
  playing = true;
}

fn pick(i: int) {
  take(0, mine[i]);
  remove(mine, i);
  take(1, its[0]);
  remove(its, 0);
  let held = mine;
  mine = its;
  its = held;
  if len(mine) == 0 {
    playing = false;
    result = "A tie";
    if score[0] > score[1] { result = "You win"; }
    if score[0] < score[1] { result = "The computer wins"; }
  }
}

