// Rune duel: build a spell of two runes (1 mana each) and Cast it: Fire Fire 6 damage, Ice Ice a
// shield, Stone Stone heals 5, a mix 2 damage. The mage strikes for 4 every 3 seconds.
// icon: fill 12 2 20 12 12 22 4 12 line 12 7 12 17 line 9 10 15 14
state spell = [""; 0];
state me = 20;
state mage = 30;
state mana = 4;
state time = 0;
state shield = false;
state speed = 0;             // 1000 while the clock runs
state begun = false;
state over = "";             // Victory or Defeated

fn words() -> string {
  let s = "Spell:";
  for i in 0..len(spell) { s = s + " " + spell[i]; }
  return s;
}

fn add(rune: string) {
  if !begun || over != "" || len(spell) >= 2 || mana < 1 { return; }
  mana -= 1;
  push(spell, rune);
}

fn stop(why: string) {
  over = why;
  speed = 0;
}

fn hit(n: int) { mage = max(0, mage - n); }

fn cast() {
  if !begun || over != "" || len(spell) < 2 { return; }
  let a = spell[0];
  let b = spell[1];
  clear(spell);
  if a != b {
    hit(2);
  } else if a == "Fire" {
    hit(6);
  } else if a == "Ice" {
    shield = true;
  } else {
    me = min(20, me + 5);
  }
  if mage == 0 { stop("Victory"); }
}

fn reset() {
  clear(spell);
  me = 20;
  mage = 30;
  mana = 4;
  time = 0;
  shield = false;
  speed = 0;
  begun = false;
  over = "";
}

every speed {
  time += 1;
  mana = min(6, mana + 1);
  if time % 3 == 0 {
    if shield {
      shield = false;
    } else {
      me = max(0, me - 4);
    }
  }
  if me == 0 { stop("Defeated"); }
}

// Me on the left, the mage on the right, a ring for the shield.
fn scene() {
  circle(30, 30, 10, 4);
  if shield { ring(30, 30, 16, 2, 6); }
  circle(130, 30, 10, 5);
  if over != "" { text(over, 80, 52, 10, 11); }
}

label "Rune duel";
label "Health " + me + "   Mage " + mage + "   Mana " + mana + "   Time " + time;
canvas 160, 60, scene();
label words();
if shield { label "Shield up"; }
row {
  button "Fire" { add("Fire"); }
  button "Ice" { add("Ice"); }
  button "Stone" { add("Stone"); }
  button "Cast" { cast(); }
}
if !begun {
  button "Start" {
    begun = true;
    speed = 1000;
  }
}
if over != "" { button "New game" { reset(); } }

// Rune duel: cast fire, water or earth; water beats fire, fire beats earth, earth beats water.
// The loser takes 3, a tie hurts both 1. The computer casts fire, water, earth in turn.
// icon: fill 12 2 20 12 12 22 4 12 line 12 7 12 17
state runes = ["Fire", "Water", "Earth"];
state me = 10;
state foe = 10;
state round = 0;
state last = "";

// Whether rune a beats rune b (0 fire, 1 water, 2 earth).
fn beats(a: int, b: int) -> bool {
  return (a == 1 && b == 0) || (a == 0 && b == 2) || (a == 2 && b == 1);
}

fn cast(a: int) {
  if me == 0 || foe == 0 { return; }
  let b = round % 3;
  round += 1;
  last = "You cast " + runes[a] + ", the computer " + runes[b];
  if beats(a, b) {
    foe = max(0, foe - 3);
  } else if beats(b, a) {
    me = max(0, me - 3);
  } else {
    me = max(0, me - 1);
    foe = max(0, foe - 1);
  }
}

label "Rune duel";
label "You " + me + "   Computer " + foe;
label last;
if me == 0 && foe == 0 {
  label "A draw: both fall";
} else if foe == 0 {
  label "You win!";
} else if me == 0 {
  label "You lose: the computer wins";
}
if me > 0 && foe > 0 {
  row {
    for i in 0..3 { button runes[i] { cast(i); } }
  }
} else {
  button "Duel again" {
    me = 10;
    foe = 10;
    round = 0;
    last = "";
  }
}

// Customs desk: approve or deny each traveller. Deny passports expired before 2026, and from the
// 4th traveller on everyone from Obristan. Right calls earn 5 credits; 3 mistakes and you are fired.
// icon: loop 4 4 20 4 20 20 4 20 ring 12 11 4 line 8 17 16 17
state names = ["Ana", "Boris", "Cleo", "Dmitri", "Elif", "Femi"];
state lands = ["Kolechia", "Obristan", "Antegria", "Kolechia", "Obristan", "Antegria"];
state years = [2028, 2024, 2027, 2025, 2029, 2026];
state now = 0;               // the traveller at the desk
state credits = 0;
state mistakes = 0;
state left = 30;
state speed = 0;             // 1000 while the desk is open
state begun = false;
state over = "";             // Shift over or Fired

fn banned() -> bool { return now >= 3; }

fn fair(i: int) -> bool {
  if years[i] < 2026 { return false; }
  if banned() && lands[i] == "Obristan" { return false; }
  return true;
}

fn stop(why: string) {
  over = why;
  speed = 0;
}

fn judge(ok: bool) {
  if !begun || over != "" { return; }
  if ok == fair(now) {
    credits += 5;
  } else {
    mistakes += 1;
  }
  now += 1;
  if mistakes >= 3 {
    stop("Fired");
  } else if now >= 6 {
    stop("Shift over");
  }
}

fn reset() {
  now = 0;
  credits = 0;
  mistakes = 0;
  left = 30;
  speed = 0;
  begun = false;
  over = "";
}

every speed {
  left -= 1;
  if left == 0 { stop("Shift over"); }
}

label "Customs desk";
label "Credits " + credits + "   Mistakes " + mistakes + "   Time left " + left;
if banned() { label "Bulletin: No entry from Obristan"; }
if over == "" && now < 6 {
  label "Traveller: " + names[now] + " of " + lands[now];
  label "Passport expires " + years[now];
} else {
  label over;
}
row {
  button "Approve" { judge(true); }
  button "Deny" { judge(false); }
}
if !begun {
  button "Start" {
    begun = true;
    speed = 1000;
  }
}
if over != "" { button "New shift" { reset(); } }

// Customs desk: approve a traveller whose passport is good in 2026, deny one that expired.
// Three wrong calls and you are fired.
// icon: loop 4 4 20 4 20 20 4 20 ring 12 11 4 line 8 17 16 17
state names = ["Ana", "Ben", "Cy", "Dee", "Eve"];
state years = [2029, 2024, 2027, 2025, 2026];
state now = 0;
state right = 0;
state wrong = 0;

fn call(ok: bool) {
  if wrong >= 3 || now >= 5 { return; }
  if ok == (years[now] >= 2026) {
    right += 1;
  } else {
    wrong += 1;
  }
  now += 1;
}

label "Customs desk";
label "Right " + right + "   Wrong " + wrong;
if wrong >= 3 {
  label "You're fired!";
} else if now < 5 {
  label names[now] + ": passport expires " + years[now];
  row {
    button "Approve" { call(true); }
    button "Deny" { call(false); }
  }
} else {
  label "The line is done";
}

// Mech arena: move with the arrows, Fire (space) along your row or column for 3; each shot adds 4
// heat, and at 8 the guns stop until it cools (1 a second). The enemy closes in and hits for 2.
// icon: loop 7 6 17 6 17 15 7 15 line 9 15 7 21 line 15 15 17 21 line 17 9 22 9
state mx = 0;
state my = 3;
state ex = 6;
state ey = 6;
state heat = 0;
state armor = 10;
state enemy = 9;
state time = 0;
state speed = 0;             // 1000 while the clock runs
state begun = false;
state over = "";

fn live() -> bool { return begun && over == ""; }

fn near() -> bool { return abs(mx - ex) + abs(my - ey) == 1; }

fn stop(why: string) {
  over = why;
  speed = 0;
}

fn step(dx: int, dy: int) {
  if !live() { return; }
  let nx = mx + dx;
  let ny = my + dy;
  if nx < 0 || nx > 6 || ny < 0 || ny > 6 || (nx == ex && ny == ey) { return; }
  mx = nx;
  my = ny;
}

fn fire() {
  if !live() || heat >= 8 { return; }
  heat += 4;
  if mx == ex || my == ey { enemy = max(0, enemy - 3); }
  if enemy == 0 { stop("Victory"); }
}

fn toward(a: int, b: int) -> int {
  if b > a { return a + 1; }
  return a - 1;
}

fn reset() {
  mx = 0;
  my = 3;
  ex = 6;
  ey = 6;
  heat = 0;
  armor = 10;
  enemy = 9;
  time = 0;
  speed = 0;
  begun = false;
  over = "";
}

every speed {
  time += 1;
  heat = max(0, heat - 1);
  if near() {
    armor = max(0, armor - 2);
    if armor == 0 { stop("Destroyed"); }
  } else if ex != mx {
    ex = toward(ex, mx);
  } else {
    ey = toward(ey, my);
  }
}

on key "left" { step(-1, 0); }
on key "right" { step(1, 0); }
on key "up" { step(0, -1); }
on key "down" { step(0, 1); }
on key "space" { fire(); }

// The arena, 7 x 7 squares of 16 units, faint lines between.
fn scene() {
  let b = [0; 49];
  b[my * 7 + mx] = 4;
  b[ey * 7 + ex] = 1;
  pixels(b, 0, 0, 7, 16);
  for i in 1..7 {
    line(i * 16, 0, i * 16, 112, 1, 8);
    line(0, i * 16, 112, i * 16, 1, 8);
  }
  if over != "" { text(over, 56, 4, 8, 11); }
}

label "Mech arena";
label "Time " + time + "   Heat " + heat + "   Armor " + armor + "   Enemy " + enemy;
if heat >= 8 { label "Overheated"; }
canvas 112, 112, scene();
row {
  button "Left" { step(-1, 0); }
  button "Up" { step(0, -1); }
  button "Down" { step(0, 1); }
  button "Right" { step(1, 0); }
  button "Fire" { fire(); }
}
if !begun {
  button "Start" {
    begun = true;
    speed = 1000;
  }
}
if over != "" { button "New game" { reset(); } }

