// Life sim: Work, Eat, Sleep and Play each spend an hour, and every hour costs a food. Keep
// Food, Energy and Fun above 0; the bars show them.
// icon: ring 12 7 4 line 12 11 12 17 line 6 13 18 13 line 12 17 8 22 line 12 17 16 22
state day = 1;
state hour = 8;
state money = 0;
state food = 10;
state energy = 10;
state fun = 10;
state over = false;

fn need(v: int) -> int { return max(0, min(10, v)); }

// The button's effect is done: an hour passes, then a need at 0 ends the life.
fn pass() {
  food = need(food - 1);
  hour += 1;
  if hour == 24 {
    hour = 0;
    day += 1;
  }
  if food == 0 || energy == 0 || fun == 0 { over = true; }
}

fn act(cash: int, f: int, e: int, j: int) {
  if over || money + cash < 0 { return; }
  money += cash;
  food = need(food + f);
  energy = need(energy + e);
  fun = need(fun + j);
  pass();
}

fn again() {
  day = 1;
  hour = 8;
  money = 0;
  food = 10;
  energy = 10;
  fun = 10;
  over = false;
}

// Three bars, 40 units a third, 10 units a point.
fn bars() {
  rect(8, 100 - food * 10, 24, food * 10, 2);
  rect(48, 100 - energy * 10, 24, energy * 10, 2);
  rect(88, 100 - fun * 10, 24, fun * 10, 2);
}

label "Life sim";
label "Day " + day + "   Hour " + hour + "   Money " + money;
label "Food " + food + "   Energy " + energy + "   Fun " + fun;
if over { label "Game over"; }
row {
  button "Work" { act(15, 0, -2, -2); }
  button "Eat" { act(-5, 5, 0, 0); }
  button "Sleep" { act(0, 0, 5, 0); }
