// Football dash: Hike, then up and down (or a tap above or below him) dodge the tacklers as the
// runner races for the end zone. Each touchdown makes the next plays faster; four tackles end it.
// icon: loop 3 12 8 7 16 7 21 12 16 17 8 17 line 9 12 15 12 line 11 10 11 14 line 13 10 13 14
state rc = 0;               // the runner's column and row
state rr = 2;
state pace = 500;           // ms a column, once hiked
state speed = 0;            // ms a column now: 0 between plays
state score = 0;
state downs = 4;
state tc = [3, 5, 5, 6, 6, 8];
state tr = [2, 0, 1, 3, 4, 2];

fn tackler(c: int, r: int) -> bool {
  for i in 0..len(tc) {
    if tc[i] == c && tr[i] == r { return true; }
  }
  return false;
}

fn huddle() {
  speed = 0;
  rc = 0;
  rr = 2;
}

// The runner reaches (c, r): a tackle, a touchdown, or on he goes.
fn reach(c: int, r: int) {
  if tackler(c, r) {
    downs -= 1;
    huddle();
  } else if c == 9 {
    score += 7;
    pace = max(200, pace - 100);
    huddle();
  } else {
    rc = c;
    rr = r;
  }
}

fn dodge(d: int) {
  if speed > 0 && rr + d >= 0 && rr + d < 5 { reach(rc, rr + d); }
}

fn hike() {
  if downs > 0 && speed == 0 { speed = pace; }
}

fn again() {
  huddle();
  pace = 500;
  score = 0;
  downs = 4;
}

fn field() {
  let b = [2; 50];
  for r in 0..5 { b[r * 10 + 9] = 3; }
  for i in 0..len(tc) { b[tr[i] * 10 + tc[i]] = 4; }
  b[rr * 10 + rc] = 1;
  pixels(b, 0, 0, 10, 16);
  if downs == 0 { text("Game over", 80, 40, 14, 9); }
}

every speed { reach(rc + 1, rr); }

on key "up" { dodge(-1); }
on key "down" { dodge(1); }

label "Football dash";
label "Score " + score + "   Downs " + downs;
canvas 160, 80, field() {
  if y / 16 < rr { dodge(-1); } else if y / 16 > rr { dodge(1); }
}
row {
  button "Hike" { hike(); }
  button "New game" { again(); }
}

// Football: call Run (4 yards) or Pass (15, but only every 3rd is caught). Make 10 yards in 4
// downs or turn it over; 80 yards from your 20 is a touchdown.
// icon: loop 3 12 8 7 16 7 21 12 16 17 8 17 line 9 12 15 12 line 11 10 11 14 line 13 10 13 14
state ball = 20;            // yards from my own goal line
state down = 1;
state togo = 10;
state passes = 0;
state score = 0;

fn fresh(at: int) {
  ball = at;
  down = 1;
  togo = 10;
}

fn play(gain: int) {
  ball += gain;
  togo -= gain;
  if ball >= 100 {
    score += 7;
    fresh(20);
  } else if togo <= 0 {
    fresh(ball);
  } else if down == 4 {
    fresh(20);
  } else {
    down += 1;
  }
}

fn pass() {
  passes += 1;
  if passes % 3 == 0 { play(15); } else { play(0); }
}

label "Football";
label "Down " + down + "   To go " + togo + "   Ball on " + ball;
label "Score " + score;
row {
  button "Run" { play(4); }
  button "Pass" { pass(); }
}

// Highrise: a floor slides back and forth above the tower; Drop (or space) lays it down and cuts
// off what hangs over. Stack to the top row; a miss ends it.
// icon: fill 8 20 16 20 16 15 8 15 fill 9 14 15 14 15 9 9 9 fill 6 8 14 8 14 4 6 4
state fl = [3];             // each floor's left end, from the bottom row up
state fw = [4];             // and its width
state mx = 0;               // the moving floor's left end
state dir = 1;
state speed = 0;            // ms a step; 0 while no game runs
state floors = 0;
state score = 0;
state result = "";

fn top() -> int { return len(fl) - 1; }

fn next() {
  mx = 0;
  dir = 1;
}

fn start() {
  clear(fl);
  clear(fw);
  push(fl, 3);
  push(fw, 4);
  floors = 0;
  score = 0;
  result = "";
  next();
  speed = 300;
}

fn drop() {
  if speed == 0 { return; }
  let w = fw[top()];
  let a = max(mx, fl[top()]);
  let b = min(mx + w, fl[top()] + w);
  if b <= a {
    result = "Game over";
    speed = 0;
    return;
  }
  if b - a == w { score += 25; } else { score += 10; }
  push(fl, a);
  push(fw, b - a);
  floors += 1;
  if len(fl) == 12 {
    result = "You win!";
    speed = 0;
  } else {
    next();
  }
}

every speed {
  if mx + fw[top()] - 1 >= 9 { dir = -1; } else if mx <= 0 { dir = 1; }
  mx += dir;
}

on key "space" { drop(); }

fn scene() {
  let b = [-1; 120];
  for k in 0..len(fl) {
    for c in fl[k]..fl[k] + fw[k] { b[(11 - k) * 10 + c] = 4; }
  }
  if speed > 0 {
    for c in mx..mx + fw[top()] { b[(10 - top()) * 10 + c] = 3; }
  }
  pixels(b, 0, 0, 10, 10);
}

label "Highrise";
label "Floors " + floors + "   Score " + score;
label result;
canvas 100, 120, scene();
row {
  if speed == 0 { button "Start" { start(); } }
  button "Drop" { drop(); }
}

