state sr = 0;
state speed = 0;            // ms a step; 0 between rides
state result = "";

fn at(c: int, r: int) -> int { return r * 20 + c; }

fn free(c: int, r: int) -> bool {
  return c >= 0 && c < 20 && r >= 0 && r < 12 && track[at(c, r)] == 0;
}

fn stop(what: string) {
  result = what;
  speed = 0;
}

every speed {
  if sr == 11 {
    stop("Crashed");
  } else if track[at(sc, sr + 1)] == 0 {
    sr += 1;
  } else if sc == 19 {
    stop("Finished!");
  } else if free(sc + 1, sr) {
    sc += 1;
  } else if free(sc + 1, sr - 1) {
    sc += 1;
    sr -= 1;
  } else {
    stop("Crashed");
  }
}

fn scene() {
  let b = [-1; 240];
  for i in 0..240 {
    if track[i] > 0 { b[i] = 2; }
  }
  b[at(sc, sr)] = 1;
