// GCD and LCM: type two whole numbers; it shows their greatest common divisor and least
// common multiple as you type.
// icon: ring 9 12 6 ring 15 12 6
state first = "";
state second = "";

// The greatest common divisor, by Euclid's rule.
fn divisor(a: int, b: int) -> int {
  let p = a;
  let q = b;
  while q != 0 {
    let r = p % q;
    p = q;
    q = r;
  }
  return p;
}

fn num(s: string) -> int { return parse(s, 0); }

// Whether both hold a whole number from 1 up (and not so big that the product overflows).
fn both() -> bool {
  let a = num(first);
  let b = num(second);
  return a >= 1 && b >= 1 && a <= 1000000 && b <= 1000000;
}

label "GCD and LCM";
input first;
input second;
if both() {
  label "GCD: " + divisor(num(first), num(second));
  label "LCM: " + num(first) / divisor(num(first), num(second)) * num(second);
} else {
  label "Type two whole numbers from 1 up";
}

// Euclid's GCD: type two numbers and press Start; each Step takes the smaller from the larger
// until they are equal: that number is their greatest common divisor.
// icon: loop 3 6 21 6 21 10 3 10 loop 3 14 12 14 12 18 3 18
state one = "";           // what is typed
state two = "";
state a = 0;              // the pair
state b = 0;
state steps = 0;

// Whether the pair is done: equal, and a pair at all.
fn done() -> bool { return a == b && a > 0; }

fn begin() {
  let p = parse(one, 0);
  let q = parse(two, 0);
  if p >= 1 && q >= 1 && p <= 1000000 && q <= 1000000 {
    a = p;
    b = q;
    steps = 0;
  }
}

fn step() {
  if a == b { return; }
  if a > b {
    a -= b;
  } else {
    b -= a;
  }
  steps += 1;
}

label "Euclid's GCD";
row {
  input one;
  input two;
  button "Start" { begin(); }
}
label "First: " + a;
label "Second: " + b;
label "Steps: " + steps;
if done() { label "GCD: " + a; }
button "Step" { step(); }

