// Use-by: type the day and month a food was opened and the days it keeps once open; it shows the
// date to use it by.
// icon: loop 3 5 21 5 21 21 3 21 line 3 10 21 10 line 8 3 8 7 line 16 3 16 7 line 8 15 11 18 16 13
state day = "";
state month = "";
state keep = "";
state lengths = [31, 28, 31, 30, 31, 30, 31, 31, 30, 31, 30, 31];
state months = ["January", "February", "March", "April", "May", "June", "July", "August",
                "September", "October", "November", "December"];

fn valid() -> bool {
  let m = parse(month, 0);
  if m < 1 || m > 12 { return false; }
  let d = parse(day, 0);
  return d >= 1 && d <= lengths[m - 1] && parse(keep, -1) >= 0;
}

// The date the days kept after the opening; a whole year of 365 days comes back to the same date.
fn useby() -> string {
  let m = parse(month, 0) - 1;
  let d = parse(day, 0) + parse(keep, 0) % 365;
  while d > lengths[m] {
    d -= lengths[m];
    m = (m + 1) % 12;
  }
  return d + " " + months[m];
}

