// Paced reader: type a passage and press Start to read it a word at a time, 250 ms a word and
// twice that for a word ending in punctuation; Pause holds a word and Resume carries on.
// icon: loop 2 12 7 7 12 6 17 7 22 12 17 17 12 18 7 17 line 10 10 10 14 line 14 10 14 14
state passage = "";
state words = [""; 0];
state at = 0;             // the word showing
