// The words of s, split at spaces.
fn split(s: string) -> [string] {
  let out = [""; 0];
  let w = "";
  for i in 0..len(s) {
    if s[i] == " " {
      if w != "" { push(out, w); }
      w = "";
    } else {
      w = w + s[i];
    }
  }
  if w != "" { push(out, w); }
  return out;
}

// How long a word stays: twice as long when it ends in punctuation.
fn hold(w: string) -> int {
  let c = w[len(w) - 1];
  if c == "." || c == "," || c == "!" || c == "?" { return 500; }
  return 250;
}

fn shown() -> string {
  if done { return "Done"; }
  if reading { return words[at]; }
  return "";
}

fn scene() { text(shown(), 80, 20, 14, 9); }

every speed {
  at += 1;
  if at >= len(words) {
    speed = 0;
    reading = false;
    done = true;
  } else {
    speed = hold(words[at]);
  }
}

