state names = ["January", "February", "March", "April", "May", "June", "July", "August",
  "September", "October", "November", "December"];
state lengths = [31, 28, 31, 30, 31, 30, 31, 31, 30, 31, 30, 31];

fn m() -> int { return parse(month, 0); }
fn d() -> int { return parse(day, 0); }

fn real() -> bool {
  if m() < 1 || m() > 12 { return false; }
  return d() >= 1 && d() <= lengths[m() - 1];
}

// The day of the year the period began, from 0 (January 1).
fn start() -> int {
  let n = d() - 1;
  for i in 0..m() - 1 { n += lengths[i]; }
  return n;
}

// The date `days` days after the period began, as MONTH D (into the next year past the end).
fn after(days: int) -> string {
  let n = (start() + days) % 365;
  let i = 0;
  while n >= lengths[i] {
    n -= lengths[i];
    i += 1;
  }
  return names[i] + " " + (n + 1);
}

