fn when(d: int) -> string {
  if d > 1 { return "due in " + d + " days"; }
  if d == 1 { return "due tomorrow"; }
  if d == 0 { return "due today"; }
  if d == -1 { return "1 day late"; }
  return (0 - d) + " days late";
}

fn late() -> int {
  let n = 0;
