state fh = "";
state fm = "";
state ahead = "";

fn num(s: string) -> int { return min(1000, max(-1000, parse(s, 0))); }

// Minutes as H:MM on a 24-hour clock.
fn clock(t: int) -> string {
  let m = (t % 1440 + 1440) % 1440;
  let r = m % 60;
  if r < 10 { return m / 60 + ":0" + r; }
  return m / 60 + ":" + r;
}

// Minutes from midnight of the day it leaves, by the clock where it leaves.
fn landed() -> int { return num(dh) * 60 + num(dm) + num(fh) * 60 + num(fm); }

fn local() -> int { return landed() + num(ahead) * 60; }

fn day() -> string {
  let t = local();
  if t < 0 { return "Previous day"; }
  if t < 1440 { return "Same day"; }
  if t < 2880 { return "Next day"; }
  return (t / 1440) + " days later";
}

