// A step from i, kept within a list of n.
fn step(i: int, d: int, n: int) -> int { return min(n - 1, max(0, i + d)); }

// The stops gained: a slower shutter, a wider aperture and a higher ISO each add one.
fn stops() -> int { return (s - 3) + (4 - a) + iso; }

fn signed(n: int) -> string {
  if n > 0 { return "+" + n; }
  return "" + n;
}

