state digits = ["1", "2", "3", "4", "5", "6", "7", "8", "9"];

fn sum(a: int, b: int, c: int) -> int { return cells[a] + cells[b] + cells[c]; }

fn rows() -> string { return sum(0, 1, 2) + " " + sum(3, 4, 5) + " " + sum(6, 7, 8); }

fn cols() -> string { return sum(0, 3, 6) + " " + sum(1, 4, 7) + " " + sum(2, 5, 8); }

fn diags() -> string { return sum(0, 4, 8) + " " + sum(2, 4, 6); }

fn magic() -> bool {
  return rows() == "15 15 15" && cols() == "15 15 15" && diags() == "15 15";
}

// What each square shows: its number, or nothing.
fn texts() -> [string] {
  let t = [""; 9];
  for i in 0..9 {
    if cells[i] > 0 { t[i] = "" + cells[i]; }
  }
  return t;
}

fn tints() -> [int] {
  let t = [0; 9];
  for i in 0..9 {
    if cells[i] > 0 && magic() { t[i] = 2; } else if cells[i] > 0 { t[i] = 3; }
  }
  return t;
}

// The picked number goes here, leaving any square it held before.
fn put(i: int) {
  for k in 0..9 {
    if cells[k] == pick { cells[k] = 0; }
  }
  cells[i] = pick;
}

