// Lo Shu puzzle: tap a square, then another, to swap their numbers. Solve it when every row,
// column and diagonal adds up to 15.
// icon: line 9 3 9 21 line 15 3 15 21 line 3 9 21 9 line 3 15 21 15 line 5 19 19 5
state cells = [1, 2, 3, 4, 5, 6, 7, 8, 9];
state picked = -1;        // the square tapped first, -1 if none
state swaps = 0;

fn sum(a: int, b: int, c: int) -> int { return cells[a] + cells[b] + cells[c]; }

fn solved() -> bool {
  let lines = [0, 1, 2, 3, 4, 5, 6, 7, 8, 0, 3, 6, 1, 4, 7, 2, 5, 8, 0, 4, 8, 2, 4, 6];
  for k in 0..8 {
    if sum(lines[3 * k], lines[3 * k + 1], lines[3 * k + 2]) != 15 { return false; }
  }
  return true;
}

fn texts() -> [string] {
  let t = [""; 9];
  for i in 0..9 { t[i] = "" + cells[i]; }
  return t;
}

fn tints() -> [int] {
  let t = [4; 9];
  if picked >= 0 { t[picked] = 3; }
  return t;
}

fn tap(i: int) {
  if picked < 0 {
    picked = i;
  } else {
    let n = cells[i];
    cells[i] = cells[picked];
    cells[picked] = n;
    if i != picked { swaps += 1; }
    picked = -1;
  }
}

label "Lo Shu puzzle";
grid 3, tints(), texts() { tap(cell); }
label "Swaps: " + swaps;
if solved() { label "Solved! Every line adds up to 15."; }

