// The pairs of neighbours whose crops are a and b, each pair once.
fn pairs(a: int, b: int) -> int {
  let n = 0;
  for i in 0..24 {
    if i % 6 < 5 {
      if (bed[i] == a && bed[i + 1] == b) || (bed[i] == b && bed[i + 1] == a) { n += 1; }
    }
    if i < 18 {
      if (bed[i] == a && bed[i + 6] == b) || (bed[i] == b && bed[i + 6] == a) { n += 1; }
    }
  }
  return n;
}

fn name() -> string {
