// Dobble: two cards show; click the one symbol both of them have. Six rounds, then Again.
// icon: ring 8 12 6 ring 16 12 6 dot 12 12 2
state names = ["Anchor", "Bell", "Cactus", "Dragon", "Igloo", "Lemon", "Rocket"];
state deck = [0, 1, 2, 0, 3, 4, 1, 3, 5, 0, 5, 6, 1, 4, 6, 2, 4, 5, 2, 3, 6];  // 3 symbols a card
state round = 1;
state score = 0;
state misses = 0;
