fn has(card: int, s: int) -> bool {
  for k in 0..3 {
    if deck[card * 3 + k] == s { return true; }
  }
  return false;
}

// A card, as a circle with its three names, centered at cx.
fn card(c: int, cx: int) {
  circle(cx, 50, 46, 7);
  ring(cx, 50, 46, 2, 9);
  for k in 0..3 { text(names[deck[c * 3 + k]], cx, 28 + k * 22, 10, 9); }
}

fn scene() {
  if over {
    text("Game over", 100, 50, 16, 11);
  } else {
    card(round - 1, 50);
    card(round, 150);
  }
}

fn answer(s: int) {
  if over { return; }
  if has(round - 1, s) && has(round, s) {
    score += 1;
    if round == 6 { over = true; } else { round += 1; }
  } else {
    misses += 1;
  }
}

