// Dobble helper: type each card's symbols in its box, spaces between, then press Find (or
// enter): it shows the symbol both cards have.
// icon: ring 8 12 6 ring 16 12 6 dot 12 12 2
state one = "";
state two = "";
state found = "";

// The words of s, split at spaces.
fn words(s: string) -> [string] {
  let out = [""; 0];
  let w = "";
  for i in 0..len(s) {
    if s[i] == " " {
      if w != "" { push(out, w); }
      w = "";
    } else {
      w = w + s[i];
    }
  }
  if w != "" { push(out, w); }
  return out;
}

fn find() {
  let a = words(one);
  let b = words(two);
  found = "None";
  for i in 0..len(a) {
    for j in 0..len(b) {
      if a[i] == b[j] { found = a[i]; }
    }
  }
}

on key "enter" { find(); }

