// Connections: tap four words that belong together, then Submit. Four mistakes and it's over.
// icon: fill 3 3 10 3 10 10 3 10 fill 14 3 21 3 21 10 14 10 loop 3 14 10 14 10 21 3 21 loop 14 14 21 14 21 21 14 21
state words = ["Pike", "Snap", "Piano", "Butter", "Bridge", "Fire", "Sole", "Lock", "Map", "Carp", "Dragon", "Rummy", "Keyboard", "House", "Poker", "Perch"];
state group = [0, 1, 2, 3, 1, 3, 0, 2, 2, 0, 3, 1, 2, 3, 1, 0];   // each word's group
state names = ["Fish", "Card games", "Things with keys", "___fly"];
state colors = [3, 2, 4, 5];
state chosen = [false; 16];
state solved = [false; 4];
state found = [""; 0];        // the groups found, by name, in order
state left = 4;
state away = false;

fn picked() -> int {
  let n = 0;
  for i in 0..16 {
    if chosen[i] { n += 1; }
  }
  return n;
}

fn over() -> bool { return left == 0 || len(found) == 4; }

fn tints() -> [int] {
  let t = [8; 16];
  for i in 0..16 {
    if solved[group[i]] { t[i] = colors[group[i]]; } else if chosen[i] { t[i] = 6; }
  }
  return t;
}

fn tap(i: int) {
  if over() || solved[group[i]] { return; }
  if chosen[i] { chosen[i] = false; } else if picked() < 4 { chosen[i] = true; }
}

fn submit() {
  if over() || picked() != 4 { return; }
  let most = 0;
  let g = 0;
  for k in 0..4 {
    let n = 0;
    for i in 0..16 {
      if chosen[i] && group[i] == k { n += 1; }
    }
    if n > most { most = n; g = k; }
  }
  if most == 4 {
    solved[g] = true;
    push(found, names[g]);
    away = false;
  } else {
    left -= 1;
    away = most == 3;
  }
  chosen = [false; 16];
}

