state group = [0, 1, 2, 3, 1, 0, 3, 2, 2, 3, 0, 1, 3, 1, 2, 0];
state names = ["Planets", "Reds", "Before ball", "Greek letters"];
state chosen = [false; 16];
state solved = [false; 4];
state mistakes = 0;

fn picked() -> int {
  let n = 0;
  for i in 0..16 {
    if chosen[i] { n += 1; }
  }
  return n;
}

fn shown(i: int) -> string {
  if chosen[i] { return "[" + words[i] + "]"; }
  return words[i];
}

fn members(g: int) -> string {
  let s = "";
  for i in 0..16 {
    if group[i] == g {
      if s != "" { s = s + ", "; }
      s = s + words[i];
    }
  }
  return s;
}

fn tap(i: int) {
  if mistakes == 4 { return; }
  if chosen[i] { chosen[i] = false; } else if picked() < 4 { chosen[i] = true; }
}

fn submit() {
  if mistakes == 4 || picked() != 4 { return; }
  let g = -1;
  for i in 0..16 {
    if chosen[i] {
      if g == -1 { g = group[i]; } else if g != group[i] { g = -2; }
    }
