// Selection sort: press Step to move the shortest unsorted bar to the front of the unsorted
// ones. Sorted bars turn green.
// icon: fill 3 21 3 15 7 15 7 21 fill 10 21 10 10 14 10 14 21 fill 17 21 17 4 21 4 21 21
state bars = [5, 2, 7, 1, 8, 3, 6, 4];
state done = 0;           // how many bars on the left are sorted
state steps = 0;
state swaps = 0;

fn scene() {
  let b = [-1; 64];
  for i in 0..8 {
    let c = 4;
    if i < done { c = 2; }
    for h in 0..bars[i] { b[(7 - h) * 8 + i] = c; }
  }
  pixels(b, 0, 0, 8, 10);
}

fn step() {
  if done == 8 { return; }
  let low = done;
  for i in done..8 {
    if bars[i] < bars[low] { low = i; }
  }
  if low != done {
    let t = bars[low];
    bars[low] = bars[done];
    bars[done] = t;
    swaps += 1;
  }
  steps += 1;
  done += 1;
  if done == 7 { done = 8; }
}

label "Selection sort";
canvas 80, 80, scene();
row {
  button "Step" { step(); }
  button "Reset" {
    bars = [5, 2, 7, 1, 8, 3, 6, 4];
    done = 0;
    steps = 0;
    swaps = 0;
  }
}
label "Steps: " + steps + "   Swaps: " + swaps;
if done == 8 { label "Sorted!"; }

// Bubble sort: type numbers with spaces between and press Sort to watch them sorted as bars,
// a comparison at a time (the pair compared turns red); it counts the swaps.
// icon: fill 3 21 3 9 7 9 7 21 fill 10 21 10 15 14 15 14 21 fill 17 21 17 4 21 4 21 21
state typed = "";
state bars = [0; 0];
state at = 0;             // the left bar of the pair compared next
state end = 0;            // this pass compares pairs up to here
state swaps = 0;
state speed = 0;          // ms a comparison; 0 while nothing moves

// The numbers in s, split at spaces.
fn numbers(s: string) -> [int] {
  let out = bars;
  clear(out);
  let w = "";
  for i in 0..len(s) + 1 {
    if i == len(s) || s[i] == " " {
      if w != "" { push(out, parse(w, 0)); }
      w = "";
    } else {
      w = w + s[i];
    }
  }
  return out;
}

// Each bar 10 units wide and 5 a unit of its number tall, the pair compared red.
fn scene() {
  for i in 0..len(bars) {
    let c = 4;
    if speed > 0 && (i == at || i == at + 1) { c = 1; }
    rect(i * 10, 120 - bars[i] * 5, 9, bars[i] * 5, c);
  }
}

every speed {
  if bars[at] > bars[at + 1] {
    let t = bars[at];
    bars[at] = bars[at + 1];
    bars[at + 1] = t;
    swaps += 1;
  }
  at += 1;
  if at >= end {
    at = 0;
    end -= 1;
    if end <= 0 { speed = 0; }
  }
}

label "Bubble sort";
row {
  input typed;
  button "Sort" {
    bars = numbers(typed);
    swaps = 0;
    at = 0;
    end = len(bars) - 1;
    if end > 0 { speed = 200; }
  }
}
canvas 160, 120, scene();
label "Swaps: " + swaps;

// Hexapawn: tap one of your blue pawns, then where it goes (up one, or diagonally up to take a
// red pawn). The computer answers. Reach the far row, take them all, or leave it no move.
// icon: dot 7 6 3 dot 17 6 3 fill 4 21 10 21 7 12 fill 14 21 20 21 17 12
state board = [1, 1, 1, 0, 0, 0, 4, 4, 4];   // 1 red, 4 blue, 0 empty
state picked = -1;
state result = "";        // "" while playing
state wins = 0;
state losses = 0;

// Whether a pawn at i of color k can move to j: down for red, up for blue.
fn legal(i: int, j: int, k: int) -> bool {
  let dir = 1;
  let foe = 4;
  if k == 4 { dir = -1; foe = 1; }
  if j / 3 != i / 3 + dir { return false; }
  if j % 3 == i % 3 { return board[j] == 0; }
  return abs(j % 3 - i % 3) == 1 && board[j] == foe;
}

fn moves(k: int) -> bool {
  for i in 0..9 {
    if board[i] == k {
      for j in 0..9 {
        if legal(i, j, k) { return true; }
      }
    }
  }
  return false;
}

fn count(k: int) -> int {
  let n = 0;
  for i in 0..9 {
    if board[i] == k { n += 1; }
  }
  return n;
}

// Whether the player of color k, who just moved, has won.
fn won(k: int, far: int) -> bool {
  let foe = 5 - k;
  return board[far] == k || board[far + 1] == k || board[far + 2] == k || count(foe) == 0 || !moves(foe);
}

fn reply() {
  let from = -1;
  let to = -1;
  for i in 0..9 {
    for j in 0..9 {
      if from < 0 && board[i] == 1 && j % 3 != i % 3 && legal(i, j, 1) { from = i; to = j; }
    }
  }
  for i in 0..9 {
    if from < 0 && board[i] == 1 && i < 6 && legal(i, i + 3, 1) { from = i; to = i + 3; }
  }
  board[to] = 1;
  board[from] = 0;
  if won(1, 6) {
    result = "Computer wins!";
    losses += 1;
  }
}

fn tap(i: int) {
  if result != "" { return; }
  if board[i] == 4 {
    picked = i;
  } else if picked >= 0 && legal(picked, i, 4) {
    board[i] = 4;
    board[picked] = 0;
    picked = -1;
    if won(4, 0) {
      result = "You win!";
      wins += 1;
    } else {
      reply();
    }
  } else {
    picked = -1;
  }
}

fn tints() -> [int] {
  let t = board;
  if picked >= 0 { t[picked] = 6; }
  return t;
}

label "Hexapawn";
grid 3, tints() { tap(cell); }
label result;
label "Wins: " + wins + "  Losses: " + losses;
if result != "" {
  button "New game" {
    board = [1, 1, 1, 0, 0, 0, 4, 4, 4];
    picked = -1;
    result = "";
  }
}

// Hexapawn for two: blue moves first. Tap one of your pawns, then where it goes: one square
// forward, or diagonally forward to take. Reach the far row, take them all, or leave no move.
// icon: dot 7 6 3 dot 17 6 3 fill 4 21 10 21 7 12 fill 14 21 20 21 17 12
state board = [1, 1, 1, 0, 0, 0, 4, 4, 4];   // 1 red, 4 blue, 0 empty
state turn = 4;           // whose move: 4 blue, 1 red
state picked = -1;
state winner = "";

// Whether the pawn at i, of color k, may move to j: blue up, red down.
fn legal(i: int, j: int, k: int) -> bool {
  let dir = 1;
  if k == 4 { dir = -1; }
  if j / 3 != i / 3 + dir { return false; }
  if j % 3 == i % 3 { return board[j] == 0; }
  return abs(j % 3 - i % 3) == 1 && board[j] == 5 - k;
}

fn stuck(k: int) -> bool {
  for i in 0..9 {
    for j in 0..9 {
      if board[i] == k && legal(i, j, k) { return false; }
    }
  }
  return true;
}

fn tap(i: int) {
  if winner != "" { return; }
  if board[i] == turn {
    picked = i;
  } else if picked >= 0 && legal(picked, i, turn) {
    board[i] = turn;
    board[picked] = 0;
    picked = -1;
    let far = 6;
    if turn == 4 { far = 0; }
    if board[far] == turn || board[far + 1] == turn || board[far + 2] == turn || stuck(5 - turn) {
      if turn == 4 { winner = "Blue"; } else { winner = "Red"; }
    }
    turn = 5 - turn;
  } else {
    picked = -1;
  }
}

fn tints() -> [int] {
  let t = board;
  if picked >= 0 { t[picked] = 3; }
  return t;
}

fn status() -> string {
  if winner != "" { return winner + " wins!"; }
  if turn == 4 { return "Blue to move"; }
  return "Red to move";
}

label "Hexapawn";
grid 3, tints() { tap(cell); }
label status();

