// SOS: pick S or O, then tap an empty square. Each S-O-S you make scores a point and you go
// again. Blue starts; the most points when the board is full wins.
// icon: line 4 6 4 18 dot 12 12 4 line 20 6 20 18
state letters = [""; 25];
state owners = [0; 25];   // the color of the player who wrote each square: 4 blue, 1 red
state pick = "S";
state turn = 4;
state blue = 0;
state red = 0;

fn at(c: int, r: int) -> string {
  if c < 0 || c > 4 || r < 0 || r > 4 { return ""; }
  return letters[r * 5 + c];
}

// The S-O-S lines through square (c, r) in direction (dc, dr), with its letter at any place.
fn lines(c: int, r: int, dc: int, dr: int) -> int {
  let n = 0;
  for k in 0..3 {
    let sc = c - k * dc;
    let sr = r - k * dr;
    if at(sc, sr) == "S" && at(sc + dc, sr + dr) == "O" && at(sc + 2 * dc, sr + 2 * dr) == "S" { n += 1; }
  }
  return n;
}

fn write(i: int) {
  if letters[i] != "" || full() { return; }
  letters[i] = pick;
  owners[i] = turn;
  let c = i % 5;
  let r = i / 5;
  let got = lines(c, r, 1, 0) + lines(c, r, 0, 1) + lines(c, r, 1, 1) + lines(c, r, 1, -1);
  if turn == 4 { blue += got; } else { red += got; }
  if got == 0 { turn = 5 - turn; }
}

fn full() -> bool {
  for i in 0..25 {
    if letters[i] == "" { return false; }
  }
  return true;
}

fn result() -> string {
  if blue > red { return "Blue wins!"; }
  if red > blue { return "Red wins!"; }
  return "Draw";
}

