// icon: line 4 6 4 18 dot 12 12 4 line 20 6 20 18
state letters = [""; 25];
state pick = "S";
state player = 0;         // whose turn: 0 or 1
state points = [0, 0];

fn at(c: int, r: int) -> string {
  if c < 0 || c > 4 || r < 0 || r > 4 { return ""; }
  return letters[r * 5 + c];
}

// The S-O-S lines through (c, r) along (dc, dr).
fn lines(c: int, r: int, dc: int, dr: int) -> int {
  let n = 0;
  for k in 0..3 {
    let sc = c - k * dc;
    let sr = r - k * dr;
    if at(sc, sr) == "S" && at(sc + dc, sr + dr) == "O" && at(sc + 2 * dc, sr + 2 * dr) == "S" { n += 1; }
  }
  return n;
}

fn left() -> int {
  let n = 0;
  for i in 0..25 {
    if letters[i] == "" { n += 1; }
  }
  return n;
}

fn write(i: int) {
  if letters[i] != "" { return; }
  letters[i] = pick;
  let c = i % 5;
  let r = i / 5;
  let got = lines(c, r, 1, 0) + lines(c, r, 0, 1) + lines(c, r, 1, 1) + lines(c, r, 1, -1);
  points[player] += got;
  if got == 0 { player = 1 - player; }
}

fn status() -> string {
  if left() > 0 { return "Player " + (player + 1) + " to play"; }
  if points[0] > points[1] { return "Player 1 wins!"; }
  if points[1] > points[0] { return "Player 2 wins!"; }
  return "It's a draw";
}

