// The teams in the line, Bye included when odd.
fn size() -> int { return len(teams) + len(teams) % 2; }

fn rounds() -> int { return size() - 1; }

// Who stands at place p of the line in round r: the first never moves, the rest turn.
fn place(r: int, p: int) -> int {
  if p == 0 { return 0; }
  let m = size() - 1;
  return 1 + ((p - 1 - r) % m + m) % m;
}

fn match(i: int) -> string {
  let a = place(shown, i);
  let b = place(shown, size() - 1 - i);
  if a == len(teams) { return teams[b] + " rests"; }
  if b == len(teams) { return teams[a] + " rests"; }
  return teams[a] + " v " + teams[b];
}

