// What a 10 odds bet wins when point p is made.
fn pays(p: int) -> int {
  if p == 4 || p == 10 { return 20; }
  if p == 5 || p == 9 { return 15; }
  return 12;
}

fn roll(t: int) {
  if point == 0 {
    if t == 7 || t == 11 {
      bank += 10;
    } else if t == 2 || t == 3 || t == 12 {
      bank -= 10;
    } else {
      point = t;
    }
  } else if t == point {
    bank += 10;
    if odds > 0 { bank += pays(point); }
    point = 0;
    odds = 0;
  } else if t == 7 {
    bank -= 10 + odds;
    point = 0;
    odds = 0;
  }
}

fn shown() -> string {
  if point == 0 { return "off"; }
  return "" + point;
}

