// Mind map: tap an idea to select it; type and press Add for a new branch of it, Rename to
// rename it, Delete to remove it with its branches. Drawn as a tree growing to the right.
// icon: ring 12 12 4 line 9 9 4 4 line 15 9 20 4 line 9 15 4 20 line 15 15 20 20
state names = ["Plans"];  // the ideas in outline order
state depths = [0];
state sel = 0;
state typed = "";

// Where the branches of idea i end: the first idea after it that is no deeper.
fn ends(i: int) -> int {
  let j = i + 1;
  while j < len(depths) && depths[j] > depths[i] { j += 1; }
  return j;
}

fn parent(i: int) -> int {
  let k = i - 1;
  while depths[k] >= depths[i] { k -= 1; }
  return k;
}

// The middle of column or row k, squares 30 units wide.
fn mid(k: int) -> int { return k * 30 + 15; }

// Lines from each idea to its parent, under a box in each idea's square.
fn scene() {
  let b = [-1; 24];
  for i in 1..len(names) {
    let p = parent(i);
    line(mid(depths[p]), mid(p), mid(depths[i]), mid(i), 1, 8);
  }
  for i in 0..len(names) { b[i * 4 + depths[i]] = sel == i ? 3 : 4; }
  pixels(b, 0, 0, 4, 30);
  for i in 0..len(names) { text(names[i], mid(depths[i]), mid(i), 8, 9); }
}

fn add() {
  if typed == "" || len(names) >= 6 || depths[sel] >= 3 { return; }
  let j = ends(sel);
  insert(names, j, typed);
  insert(depths, j, depths[sel] + 1);
  typed = "";
}

fn cut() {
  if sel == 0 { return; }
  repeat ends(sel) - sel {
    remove(names, sel);
    remove(depths, sel);
  }
  sel = 0;
}

fn pick(c: int, r: int) {
  if r < len(names) && depths[r] == c { sel = r; }
}

