// Garden mind map: type an idea and tap an empty square beside one already on the map (above,
// below, left or right) to put it there; the map grows out from Garden in the middle.
// icon: loop 9 9 15 9 15 15 9 15 loop 9 2 15 2 15 8 9 8 loop 16 9 22 9 22 15 16 15 loop 2 16 8 16 8 22 2 22
state words = [""; 49];   // the idea on each square; Garden's, the middle, aside
state typed = "";

fn taken(i: int) -> bool { return i == 24 || words[i] != ""; }

// Whether square (c, r) is beside one on the map.
fn beside(c: int, r: int) -> bool {
  let i = r * 7 + c;
  return (c > 0 && taken(i - 1)) || (c < 6 && taken(i + 1)) || (r > 0 && taken(i - 7)) || (r < 6 && taken(i + 7));
}

fn put(i: int) {
  if typed != "" && !taken(i) && beside(i % 7, i / 7) {
    words[i] = typed;
    typed = "";
  }
}

fn names() -> [string] {
  let w = words;
  w[24] = "Garden";
  return w;
}

fn shades() -> [int] {
  let s = [0; 49];
  for i in 0..49 {
    if taken(i) { s[i] = 3; }
  }
  s[24] = 2;
  return s;
}

