// Ten pairs: cross out two digits that are equal or make 10 and have only crossed-out squares
// between them, along the rows or up and down a column. Add writes the rest out again.
// icon: loop 3 6 11 6 11 18 3 18 loop 13 6 21 6 21 18 13 18 line 7 9 7 15 line 17 9 17 15
state digits = [1, 2, 3, 4, 5, 6, 7, 8, 9, 1, 1, 1, 2, 1, 3, 1, 4, 1, 5, 1, 6, 1, 7, 1, 8, 1, 9];
state gone = [false; 54]; // crossed out
state sel = -1;

fn live(i: int) -> bool { return i < len(digits) && !gone[i]; }

// Whether only crossed-out squares lie between a and b, stepping by step.
fn gap(a: int, b: int, step: int) -> bool {
  let k = a + step;
  while k < b {
    if live(k) { return false; }
    k += step;
  }
  return true;
}

fn neighbours(a: int, b: int) -> bool {
  let lo = min(a, b);
  let hi = max(a, b);
  return gap(lo, hi, 1) || (lo % 9 == hi % 9 && gap(lo, hi, 9));
}

fn tap(i: int) {
  if !live(i) { return; }
  if sel == i {
    sel = -1;
  } else if sel < 0 {
    sel = i;
  } else if (digits[sel] == digits[i] || digits[sel] + digits[i] == 10) && neighbours(sel, i) {
    gone[sel] = true;
    gone[i] = true;
    sel = -1;
  } else {
    sel = i;
  }
}

fn add() {
  let more = [0; 0];
  for i in 0..len(digits) {
    if !gone[i] { push(more, digits[i]); }
  }
  if len(digits) + len(more) > 54 { return; }
  for j in 0..len(more) { push(digits, more[j]); }
}

fn left() -> int {
  let n = 0;
  for i in 0..len(digits) {
    if !gone[i] { n += 1; }
  }
  return n;
}

fn shades() -> [int] {
  let s = [0; 54];
  for i in 0..len(digits) { s[i] = gone[i] ? 8 : 3; }
  if sel >= 0 { s[sel] = 4; }
  return s;
}

fn faces() -> [string] {
  let f = [""; 54];
  for i in 0..len(digits) { f[i] = "" + digits[i]; }
  return f;
}

label "Ten pairs";
grid 9, shades(), faces() { tap(cell); }
button "Add" { add(); }
label "Left: " + left();

// Make ten: tap two numbers that add up to 10 and they disappear; clear them all.
