  if sel == i {
    sel = -1;
  } else if sel >= 0 && nums[sel] + nums[i] == 10 {
    nums[sel] = 0;
    nums[i] = 0;
    sel = -1;
  } else {
    sel = i;
  }
}

fn shades() -> [int] {
  let s = [0; 12];
