// What the step up from score s costs.
fn cost(s: int) -> int { return s >= 13 ? 2 : 1; }

// The modifier, rounded down: the score halved, less 5.
fn bonus(s: int) -> int { return s / 2 - 5; }

fn signed(n: int) -> string { return n >= 0 ? "+" + n : "" + n; }

fn up(i: int) {
  if scores[i] < 15 && cost(scores[i]) <= left {
    left -= cost(scores[i]);
    scores[i] += 1;
  }
}

fn down(i: int) {
  if scores[i] > 8 {
    scores[i] -= 1;
    left += cost(scores[i]);
  }
}

