// Venn sort: place each number in the diagram with the four buttons: Even only, Both,
// Multiple of 3 only or Neither. A right answer writes it in; a wrong one says where it goes.
// icon: ring 9 12 7 ring 15 12 7
state nums = [12, 7, 9, 10, 30, 1, 15, 4, 18, 5];
