// The part number n belongs in: 0 even only, 1 both, 2 multiple of 3 only, 3 neither.
fn part(n: int) -> int {
  if n % 2 == 0 && n % 3 == 0 { return 1; }
  if n % 2 == 0 { return 0; }
  if n % 3 == 0 { return 2; }
  return 3;
}

fn answer(p: int) {
  if turn >= 10 { return; }
  let n = nums[turn];
  if part(n) == p {
    score += 1;
    push(placed, n);
    said = "";
  } else {
    said = "No: " + n + " goes in " + parts[part(n)];
  }
  turn += 1;
}

// The numbers placed in part p.
fn listed(p: int) -> string {
  let s = "";
  for i in 0..len(placed) {
    if part(placed[i]) == p { s = s + placed[i] + " "; }
