fn count(p: int) -> int {
  let n = 0;
  for i in 0..len(parts) {
    if parts[i] == p { n += 1; }
  }
  return n;
}

// How many names before name i share its part: its line in that part.
fn rank(i: int) -> int {
  let k = 0;
  for j in 0..i {
    if parts[j] == parts[i] { k += 1; }
  }
  return k;
}

fn add(p: int) {
  if typed != "" {
    push(names, typed);
    push(parts, p);
    typed = "";
  }
}

fn undo() {
  if len(names) > 0 {
    remove(names, len(names) - 1);
    remove(parts, len(parts) - 1);
  }
}

// Writes v on line r of part p: pet only, both, sibling only, then outside on the right.
fn put(v: string, p: int, r: int) { text(v, 55 + p * 45, 8 + r * 12, 7, 9); }

