    put(sets[c] + ": " + (count(c * 2) + count(1)), c * 2, 0);
  }
  for p in 0..4 { put("" + count(p), p, 1); }
  for i in 0..len(names) { put(names[i], parts[i], 2 + rank(i)); }
}

