// Cat trap: tap empty squares to build walls; after each one the cat runs a step toward the edge.
// Wall it in before it gets there. Start begins a game.
// icon: ring 12 14 7 line 6 10 7 3 11 8 line 13 8 17 3 18 10
state walls = [0; 81];                     // 1 where a wall stands
state starts = [22, 30, 51, 56, 68, 25];   // the walls a game starts with (row * 9 + column)
state cat = 40;
state placed = 0;
state play = false;
state end = 0;                             // 1 you won, 2 the cat escaped

fn edge(i: int) -> bool {
  let c = i % 9;
  let r = i / 9;
  return c == 0 || r == 0 || c == 8 || r == 8;
}

// The square beside i going k (0 up, 1 right, 2 down, 3 left), else -1 off the board.
fn step(i: int, k: int) -> int {
  let c = i % 9;
  let r = i / 9;
  if k == 0 && r > 0 { return i - 9; }
  if k == 1 && c < 8 { return i + 1; }
  if k == 2 && r < 8 { return i + 9; }
  if k == 3 && c > 0 { return i - 1; }
  return -1;
}

// Steps from each square to the edge through empty squares; -1 where the edge is out of reach.
fn dists() -> [int] {
  let d = [-1; 81];
  let q = [0; 0];
  for i in 0..81 {
    if edge(i) && walls[i] == 0 {
      d[i] = 0;
      push(q, i);
    }
  }
  let h = 0;
  while h < len(q) {
    let i = q[h];
    h += 1;
    for k in 0..4 {
      let j = step(i, k);
      if j >= 0 && walls[j] == 0 && d[j] < 0 {
        d[j] = d[i] + 1;
        push(q, j);
      }
    }
  }
  return d;
}

fn start() {
  walls = [0; 81];
  for k in 0..len(starts) { walls[starts[k]] = 1; }
  cat = 40;
  placed = 0;
  end = 0;
  play = true;
}

// A wall at i, then the cat's step (or the end).
fn tap(i: int) {
  if !play || walls[i] == 1 || i == cat { return; }
  walls[i] = 1;
  placed += 1;
  let d = dists();
  if d[cat] < 0 {
    end = 1;
    play = false;
    return;
  }
  let best = -1;
  for k in 0..4 {
    let j = step(cat, k);
    if j >= 0 && d[j] >= 0 && (best < 0 || d[j] < d[best]) { best = j; }
  }
  cat = best;
  if edge(cat) {
    end = 2;
    play = false;
  }
}

fn scene() {
  let b = [0; 81];
  for i in 0..81 {
    if walls[i] == 1 { b[i] = 4; }
  }
  pixels(b, 0, 0, 9, 12);
  for k in 1..9 {
    line(k * 12, 0, k * 12, 108, 1, 8);
    line(0, k * 12, 108, k * 12, 1, 8);
  }
  let x = cat % 9 * 12 + 6;
  let y = cat / 9 * 12 + 6;
  circle(x, y, 5, 3);
  circle(x - 3, y - 3, 1, 9);
  circle(x + 3, y - 3, 1, 9);
}

label "Cat trap";
label "Walls: " + placed;
canvas 108, 108, scene() { tap(y / 12 * 9 + x / 12); }
if end == 1 { label "You win"; } else if end == 2 { label "The cat escaped"; } else { label "Wall the cat in"; }
if !play { button "Start" { start(); } }

// Cat trap: New game sets up; tap a square to build a wall, then the cat steps toward the nearest
// edge. Box it in so it cannot move to win; if it reaches the edge it escapes.
// icon: ring 12 14 7 line 6 10 7 3 11 8 line 13 8 17 3 18 10
state walls = [0; 0];   // the squares walled (row * 7 + column)
state cat = -1;         // -1 before the first game
state end = 0;          // 1 you won, 2 it escaped

fn wall(i: int) -> bool {
  for k in 0..len(walls) {
    if walls[k] == i { return true; }
  }
  return false;
}

// How far square i is from the nearest edge.
fn far(i: int) -> int {
  let c = i % 7;
  let r = i / 7;
  return min(min(c, r), min(6 - c, 6 - r));
}

// The square beside i going k (0 up, 1 right, 2 down, 3 left), else -1.
fn step(i: int, k: int) -> int {
  let c = i % 7;
  let r = i / 7;
  if k == 0 && r > 0 { return i - 7; }
  if k == 1 && c < 6 { return i + 1; }
  if k == 2 && r < 6 { return i + 7; }
  if k == 3 && c > 0 { return i - 1; }
  return -1;
}

fn tap(i: int) {
  if cat < 0 || end > 0 || wall(i) || i == cat { return; }
  push(walls, i);
  let best = -1;
  for k in 0..4 {
    let j = step(cat, k);
    if j >= 0 && !wall(j) && (best < 0 || far(j) < far(best)) { best = j; }
  }
  if best < 0 {
    end = 1;
  } else {
    cat = best;
    if far(cat) == 0 { end = 2; }
  }
}

fn scene() {
  let b = [0; 49];
  for k in 0..len(walls) { b[walls[k]] = 8; }
  if cat >= 0 { b[cat] = 3; }
  pixels(b, 0, 0, 7, 16);
}

label "Cat trap";
canvas 112, 112, scene() { tap(y / 16 * 7 + x / 16); }
if end == 1 { label "You win! The cat is trapped."; }
if end == 2 { label "The cat escaped. You lose."; }
button "New game" {
  walls = [17, 23, 31];
  cat = 24;
  end = 0;
}

// Xiangqi for two: Start sets out the pieces; tap one of yours, then where it goes. No move may
// leave your general in check; a side with no move left loses.
// icon: ring 12 12 9 line 8 9 16 9 line 12 9 12 16 line 8 16 16 16
state side = [0; 90];                      // 1 red, 2 black (row * 9 + column)
state kind = [0; 90];                      // 1 general 2 advisor 3 elephant 4 horse 5 chariot 6 cannon 7 soldier
state back = [5, 4, 3, 2, 1, 2, 3, 4, 5];  // the home row, left to right
state turn = 1;
state pick = -1;
state won = 0;
state play = false;

fn put(i: int, s: int, k: int) {
  side[i] = s;
  kind[i] = k;
}

fn setup() {
  side = [0; 90];
  kind = [0; 90];
  for c in 0..9 {
    put(c, 2, back[c]);
    put(81 + c, 1, back[c]);
  }
  for c in 0..5 {
    put(27 + c * 2, 2, 7);
    put(54 + c * 2, 1, 7);
  }
  put(19, 2, 6);
  put(25, 2, 6);
  put(64, 1, 6);
  put(70, 1, 6);
  turn = 1;
  pick = -1;
  won = 0;
  play = true;
}

// The pieces strictly between a and b on one row or column; -1 if they share neither.
fn between(a: int, b: int) -> int {
  let n = 0;
  if a % 9 == b % 9 {
    for r in min(a, b) / 9 + 1..max(a, b) / 9 {
      if side[r * 9 + a % 9] > 0 { n += 1; }
    }
    return n;
  }
  if a / 9 == b / 9 {
    for i in min(a, b) + 1..max(a, b) {
      if side[i] > 0 { n += 1; }
    }
    return n;
  }
  return -1;
}

fn palace(s: int, i: int) -> bool {
  let c = i % 9;
  let r = i / 9;
  return c >= 3 && c <= 5 && ((s == 1 && r >= 7) || (s == 2 && r <= 2));
}

// Whether the piece on a can go to b by its own move.
fn reach(a: int, b: int) -> bool {
  let s = side[a];
  if s == 0 || side[b] == s { return false; }
  let dc = b % 9 - a % 9;
  let dr = b / 9 - a / 9;
  let k = kind[a];
  if k == 1 { return abs(dc) + abs(dr) == 1 && palace(s, b); }
  if k == 2 { return abs(dc) == 1 && abs(dr) == 1 && palace(s, b); }
  if k == 3 {
    return abs(dc) == 2 && abs(dr) == 2 && side[a + dr / 2 * 9 + dc / 2] == 0 && (s == 1) == (b / 9 >= 5);
  }
  if k == 4 {
    if abs(dc) == 1 && abs(dr) == 2 { return side[a + dr / 2 * 9] == 0; }
    if abs(dc) == 2 && abs(dr) == 1 { return side[a + dc / 2] == 0; }
    return false;
  }
  if k == 5 { return between(a, b) == 0; }
  if k == 6 { return between(a, b) == (side[b] > 0 ? 1 : 0); }
  let ahead = s == 1 ? -1 : 1;
  if dc == 0 && dr == ahead { return true; }
  let over = (s == 1 && a / 9 <= 4) || (s == 2 && a / 9 >= 5);
  return over && dr == 0 && abs(dc) == 1;
}

fn general(s: int) -> int {
  for i in 0..90 {
    if side[i] == s && kind[i] == 1 { return i; }
  }
  return -1;
}

// Whether side s's general could be taken, or faces the other general with nothing between.
fn attacked(s: int) -> bool {
  let g = general(s);
  let o = general(3 - s);
  if g < 0 || o < 0 { return false; }
  for i in 0..90 {
    if side[i] == 3 - s && reach(i, g) { return true; }
  }
  return between(g, o) == 0 && g % 9 == o % 9;
}

// Whether the side to move may move a to b: its piece's move, leaving its general safe.
fn legal(a: int, b: int) -> bool {
  if side[a] != turn || !reach(a, b) { return false; }
  let ts = side[b];
  let tk = kind[b];
  put(b, side[a], kind[a]);
  put(a, 0, 0);
  let bad = attacked(turn);
  put(a, side[b], kind[b]);
  put(b, ts, tk);
  return !bad;
}

fn stuck() -> bool {
  for a in 0..90 {
    if side[a] == turn {
      for b in 0..90 {
        if legal(a, b) { return false; }
      }
    }
  }
  return true;
}

fn tap(i: int) {
  if !play { return; }
  if side[i] == turn {
    pick = i;
  } else if pick >= 0 && legal(pick, i) {
    put(i, turn, kind[pick]);
    put(pick, 0, 0);
    pick = -1;
    turn = 3 - turn;
    if stuck() {
      won = 3 - turn;
      play = false;
    }
  }
}

fn scene() {
  for k in 1..10 { line(0, k * 20, 180, k * 20, 1, 10); }
  for k in 1..9 { line(k * 20, 0, k * 20, 200, 1, 10); }
  line(0, 100, 180, 100, 3, 6);
  line(60, 0, 60, 60, 2, 11);
