// Xiangqi for two: Start sets out the pieces; tap one of yours, then where it goes. No check rules:
// take the other general to win.
// icon: ring 12 12 9 line 8 9 16 9 line 12 9 12 16 line 8 16 16 16
state side = [0; 90];                      // 1 red, 2 black (row * 9 + column)
state kind = [0; 90];                      // 1 general 2 advisor 3 elephant 4 horse 5 chariot 6 cannon 7 soldier
state back = [5, 4, 3, 2, 1, 2, 3, 4, 5];  // the home row, left to right
