// The pieces strictly between a and b on one row or column; -1 if they share neither.
fn between(a: int, b: int) -> int {
  let n = 0;
  if a % 9 == b % 9 {
    for r in min(a, b) / 9 + 1..max(a, b) / 9 {
      if side[r * 9 + a % 9] > 0 { n += 1; }
    }
    return n;
  }
  if a / 9 == b / 9 {
    for i in min(a, b) + 1..max(a, b) {
      if side[i] > 0 { n += 1; }
    }
    return n;
  }
  return -1;
}

fn palace(s: int, i: int) -> bool {
  let c = i % 9;
  let r = i / 9;
  return c >= 3 && c <= 5 && ((s == 1 && r >= 7) || (s == 2 && r <= 2));
}

// Whether the piece on a can go to b.
fn reach(a: int, b: int) -> bool {
  let s = side[a];
  if s == 0 || side[b] == s { return false; }
  let dc = b % 9 - a % 9;
  let dr = b / 9 - a / 9;
  let k = kind[a];
  if k == 1 { return abs(dc) + abs(dr) == 1 && palace(s, b); }
  if k == 2 { return abs(dc) == 1 && abs(dr) == 1 && palace(s, b); }
  if k == 3 {
    return abs(dc) == 2 && abs(dr) == 2 && side[a + dr / 2 * 9 + dc / 2] == 0 && (s == 1) == (b / 9 >= 5);
  }
  if k == 4 {
    if abs(dc) == 1 && abs(dr) == 2 { return side[a + dr / 2 * 9] == 0; }
    if abs(dc) == 2 && abs(dr) == 1 { return side[a + dc / 2] == 0; }
    return false;
  }
  if k == 5 { return between(a, b) == 0; }
  if k == 6 { return between(a, b) == (side[b] > 0 ? 1 : 0); }
  let ahead = s == 1 ? -1 : 1;
  if dc == 0 && dr == ahead { return true; }
  let over = (s == 1 && a / 9 <= 4) || (s == 2 && a / 9 >= 5);
  return over && dr == 0 && abs(dc) == 1;
}

fn tap(i: int) {
  if !play { return; }
  if side[i] == turn {
    pick = i;
  } else if pick >= 0 && reach(pick, i) {
    if kind[i] == 1 {
      won = turn;
      play = false;
    }
    put(i, turn, kind[pick]);
    put(pick, 0, 0);
    pick = -1;
    turn = 3 - turn;
  }
}

fn scene() {
  for k in 1..10 { line(0, k * 20, 180, k * 20, 1, 10); }
  for k in 1..9 { line(k * 20, 0, k * 20, 200, 1, 10); }
