// Dominosa: cover the board with dominoes so each pair of numbers 0 to 3 is used once. Tap two
// squares side by side to lay a domino, tap a domino to take it off; repeats show red.
// icon: loop 3 7 21 7 21 17 3 17 line 12 7 12 17 dot 7 12 2 dot 17 10 2 dot 17 14 2
state nums = [2, 1, 0, 2, 2, 0, 1, 3, 3, 3, 3, 0, 2, 0, 1, 2, 0, 3, 1, 1];
state mate = [-1; 20];      // the square each square shares a domino with, -1 if none
state pick = -1;

fn pair(i: int) -> int {
  let a = nums[i];
  let b = nums[mate[i]];
  return min(a, b) * 4 + max(a, b);
}

// Whether the domino on square i has the same numbers as another on the board.
fn repeated(i: int) -> bool {
  for j in 0..20 {
    if mate[j] >= 0 && j != i && j != mate[i] && pair(j) == pair(i) { return true; }
  }
  return false;
}

fn laid() -> int {
  let n = 0;
  for i in 0..20 {
    if mate[i] >= 0 { n += 1; }
  }
  return n / 2;
}

fn solved() -> bool {
  if laid() < 10 { return false; }
  for i in 0..20 {
    if repeated(i) { return false; }
  }
  return true;
}

fn beside(a: int, b: int) -> bool {
  return (abs(a - b) == 1 && a / 5 == b / 5) || abs(a - b) == 5;
}

fn tap(i: int) {
  if mate[i] >= 0 {
    mate[mate[i]] = -1;
    mate[i] = -1;
    pick = -1;
  } else if pick == i {
    pick = -1;
  } else if pick >= 0 && beside(pick, i) {
    mate[i] = pick;
    mate[pick] = i;
    pick = -1;
  } else {
    pick = i;
  }
}

fn hue(i: int) -> int {
  if mate[i] >= 0 { return repeated(i) ? 1 : 2; }
  return i == pick ? 3 : 0;
}

fn scene() {
  for i in 0..20 {
    let x = i % 5 * 24;
    let y = i / 5 * 24;
    rect(x + 1, y + 1, 22, 22, hue(i));
    text(nums[i], x + 12, y + 12, 12, 9);
    if mate[i] == i + 1 { rect(x + 20, y + 10, 8, 4, 9); }
    if mate[i] == i + 5 { rect(x + 10, y + 20, 4, 8, 9); }
  }
}

