// Dominosa: tap two squares side by side to lay a domino, tap a domino to lift it. Cover the grid
// using each domino 0-0 to 2-2 once.
// icon: loop 3 7 21 7 21 17 3 17 line 12 7 12 17 dot 7 12 2 dot 17 10 2 dot 17 14 2
state nums = [2, 0, 1, 1, 2, 0, 1, 2, 1, 2, 0, 0];
state mate = [-1; 12];      // the square each square shares a domino with, -1 if none
state pick = -1;

fn pair(i: int) -> int { return min(nums[i], nums[mate[i]]) * 3 + max(nums[i], nums[mate[i]]); }

fn full() -> bool {
  for i in 0..12 {
    if mate[i] < 0 { return false; }
  }
  return true;
}

fn repeats() -> bool {
  for i in 0..12 {
    for j in 0..12 {
      if j != i && j != mate[i] && pair(i) == pair(j) { return true; }
    }
  }
  return false;
