// Qwirkle alone: click a tile in your hand, then tap a square to place it; lines must share a color
// or a number with no repeats. Done scores the turn and refills the hand from the bag.
// icon: fill 4 4 11 4 11 11 4 11 dot 17 7 4 fill 17 13 21 17 17 21 13 17 loop 4 14 11 14 11 21 4 21
state board = [""; 81];
state hand = ["R1", "R2", "R3", "G1", "B1", "Y4"];
state bag = ["P1", "R4", "C1", "Y1", "R5", "Y5", "R1"];
state placed = [0; 0];       // the squares filled this turn
state held = -1;             // the picked tile's place in the hand
state score = 0;
state over = false;

fn hue(t: string) -> int {
  let names = ["R", "G", "Y", "B", "P", "C"];
  for k in 0..6 {
    if len(t) > 0 && t[0] == names[k] { return k + 1; }
  }
  return 0;
}

fn on(c: int, r: int) -> bool { return c >= 0 && c < 9 && r >= 0 && r < 9 && board[r * 9 + c] != ""; }

// The unbroken run of tiles through square i, going (dc, dr).
fn run(i: int, dc: int, dr: int) -> [string] {
  let c = i % 9;
  let r = i / 9;
  while on(c - dc, r - dr) {
    c -= dc;
    r -= dr;
  }
  let out = [""; 0];
  while on(c, r) {
    push(out, board[r * 9 + c]);
    c += dc;
    r += dr;
  }
  return out;
}

// One color with no number twice, or one number with no color twice.
fn fits(ts: [string]) -> bool {
  let hues = true;
  let shapes = true;
  for a in 0..len(ts) {
    for b in a + 1..len(ts) {
      if ts[a] == ts[b] { return false; }
      if ts[a][0] != ts[b][0] { hues = false; }
      if ts[a][1] != ts[b][1] { shapes = false; }
    }
  }
  return hues || shapes;
}

fn bare() -> bool {
  for i in 0..81 {
    if board[i] != "" { return false; }
  }
  return true;
}

// Whether i lies in one row or column with this turn's tiles, with no empty square between.
fn inline(i: int) -> bool {
  if len(placed) == 0 { return true; }
  let across = true;
  let down = true;
  let lo = i;
  let hi = i;
  for k in 0..len(placed) {
    if placed[k] / 9 != i / 9 { across = false; }
    if placed[k] % 9 != i % 9 { down = false; }
    lo = min(lo, placed[k]);
    hi = max(hi, placed[k]);
  }
  if !across && !down { return false; }
  let j = lo;
  while j <= hi {
    if j != i && board[j] == "" { return false; }
    j += across ? 1 : 9;
  }
  return true;
}

fn place(i: int) {
  if over || held < 0 || board[i] != "" { return; }
  let c = i % 9;
  let r = i / 9;
  if bare() {
    if i != 40 { return; }
  } else if !on(c - 1, r) && !on(c + 1, r) && !on(c, r - 1) && !on(c, r + 1) {
    return;
  }
  if !inline(i) { return; }
  board[i] = hand[held];
  if !fits(run(i, 1, 0)) || !fits(run(i, 0, 1)) {
    board[i] = "";
    return;
  }
  push(placed, i);
  remove(hand, held);
  held = -1;
}

fn worth(i: int, dc: int, dr: int) -> int {
  let n = len(run(i, dc, dr));
  if n < 2 { return 0; }
  return n == 6 ? 12 : n;
}

fn done() {
  if over || len(placed) == 0 { return; }
  let across = len(placed) > 1 && placed[0] / 9 == placed[1] / 9;
  let down = len(placed) > 1 && !across;
  let pts = 0;
  if !down { pts += worth(placed[0], 1, 0); }
  if !across { pts += worth(placed[0], 0, 1); }
  for k in 0..len(placed) {
    if across { pts += worth(placed[k], 0, 1); }
    if down { pts += worth(placed[k], 1, 0); }
  }
  score += max(pts, 1);
  clear(placed);
  held = -1;
  while len(hand) < 6 && len(bag) > 0 {
    push(hand, bag[0]);
    remove(bag, 0);
  }
  if len(hand) == 0 {
    score += 6;
    over = true;
  }
}

fn scene() {
  for i in 0..81 {
    let x = i % 9 * 14;
    let y = i / 9 * 14;
    rect(x + 1, y + 1, 12, 12, hue(board[i]));
    if board[i] != "" { text(board[i][1], x + 7, y + 7, 9, 0); }
  }
  if bare() { ring(63, 63, 6, 1, 8); }
}

