// Qwirkle, one tile at a time: tap a square next to the tiles down to place the next tile; each line
// must be one color or one number with no repeats. Lines score their length, a line of 6 scores 12.
// icon: fill 4 4 11 4 11 11 4 11 dot 17 7 4 fill 17 13 21 17 17 21 13 17 loop 4 14 11 14 11 21 4 21
state hues = [1, 1, 1, 4, 2, 1, 4, 2, 1, 1, 1];   // the tiles in order: color (1 red, 2 green, 4 blue)
state nums = [1, 2, 3, 1, 1, 4, 2, 2, 1, 5, 6];   // and number
state at = [0; 0];                                // the square each tile placed so far went on
state score = 0;

fn tile(i: int) -> int {
  for k in 0..len(at) {
    if at[k] == i { return k; }
  }
  return -1;
}

fn down(c: int, r: int) -> bool { return c >= 0 && c < 7 && r >= 0 && r < 7 && tile(r * 7 + c) >= 0; }

// The tiles in the line through square i going (dc, dr).
fn run(i: int, dc: int, dr: int) -> [int] {
  let c = i % 7;
  let r = i / 7;
  while down(c - dc, r - dr) {
    c -= dc;
    r -= dr;
  }
  let out = [0; 0];
  while down(c, r) {
    push(out, tile(r * 7 + c));
    c += dc;
    r += dr;
  }
  return out;
}

fn fits(ts: [int]) -> bool {
  let one = true;
  let same = true;
  for a in 0..len(ts) {
    for b in a + 1..len(ts) {
      if hues[ts[a]] == hues[ts[b]] && nums[ts[a]] == nums[ts[b]] { return false; }
      if hues[ts[a]] != hues[ts[b]] { one = false; }
      if nums[ts[a]] != nums[ts[b]] { same = false; }
    }
  }
  return one || same;
}

fn worth(n: int) -> int {
  if n < 2 { return 0; }
  return n == 6 ? 12 : n;
}

fn tap(i: int) {
  let c = i % 7;
  let r = i / 7;
  if len(at) == len(hues) || tile(i) >= 0 { return; }
  if len(at) > 0 && !down(c - 1, r) && !down(c + 1, r) && !down(c, r - 1) && !down(c, r + 1) { return; }
  push(at, i);
  let a = run(i, 1, 0);
  let b = run(i, 0, 1);
  if !fits(a) || !fits(b) {
    remove(at, len(at) - 1);
    return;
  }
  score += max(worth(len(a)) + worth(len(b)), 1);
}

fn scene() {
  for k in 1..7 {
    line(k * 16, 0, k * 16, 112, 1, 8);
    line(0, k * 16, 112, k * 16, 1, 8);
  }
  for k in 0..len(at) {
    let x = at[k] % 7 * 16;
    let y = at[k] / 7 * 16;
    rect(x + 1, y + 1, 14, 14, hues[k]);
    text(nums[k], x + 8, y + 8, 10, 0);
  }
}

label "Qwirkle";
canvas 112, 112, scene() { tap(y / 16 * 7 + x / 16); }
if len(at) < len(hues) {
  label "Next: " + ["", "red", "green", "", "blue"][hues[len(at)]] + " " + nums[len(at)];
} else {
