// Mille Bornes against the computer: Start deals; click a card to play it, or Discard and then a
// card. Go to start rolling, fix hazards, mind the speed limit; exactly 700 km wins.
// icon: fill 3 13 6 8 16 8 19 13 21 13 21 17 3 17 dot 8 18 2 dot 16 18 2
state deck = ["Go", "200", "Stop", "Spare tire", "50", "100", "50", "Go", "Flat tire", "25", "Speed limit",
  "Gasoline", "Repairs", "75", "End of limit", "Accident", "Go", "Go", "200", "100", "Go", "25", "100", "50",
  "100", "75", "25", "200", "100", "50", "25", "75"];
state mine = [""; 0];
state its = [""; 0];
state pile = 12;              // the next card to draw
state km = [0, 0];            // 0 me, 1 the computer
state road = [0, 0];          // 0 stopped, 1 rolling, 2 accident, 3 out of gas, 4 flat tire
state limit = [false, false];
state toss = false;
state won = -1;
state dealt = false;

// The trouble a hazard leaves (as a road), or the trouble a repair fixes; 0 if it is neither.
fn trouble(c: string) -> int {
  if c == "Accident" || c == "Repairs" { return 2; }
  if c == "Out of gas" || c == "Gasoline" { return 3; }
  if c == "Flat tire" || c == "Spare tire" { return 4; }
  return 0;
}

fn hazard(c: string) -> bool { return c == "Stop" || c == "Accident" || c == "Out of gas" || c == "Flat tire"; }

fn can(p: int, c: string) -> bool {
  let d = parse(c, 0);
  if d > 0 { return road[p] == 1 && (!limit[p] || d <= 50) && km[p] + d <= 700; }
  if c == "Go" { return road[p] == 0; }
  if hazard(c) { return road[1 - p] == 1; }
  if c == "Speed limit" { return !limit[1 - p]; }
  if c == "End of limit" { return limit[p]; }
  return trouble(c) > 0 && road[p] == trouble(c);
}

fn play(p: int, c: string) {
  let d = parse(c, 0);
  if d > 0 {
    km[p] += d;
  } else if c == "Go" {
    road[p] = 1;
  } else if hazard(c) {
    road[1 - p] = trouble(c);
  } else if c == "Speed limit" {
    limit[1 - p] = true;
  } else if c == "End of limit" {
    limit[p] = false;
  } else {
    road[p] = 0;
  }
  if km[p] == 700 { won = p; }
}

fn draw(p: int) {
  if pile < len(deck) {
    if p == 0 { push(mine, deck[pile]); } else { push(its, deck[pile]); }
    pile += 1;
  }
}

fn computer() {
  draw(1);
  for k in 0..len(its) {
    if can(1, its[k]) {
      let c = its[k];
      remove(its, k);
      play(1, c);
      return;
    }
  }
  if len(its) > 0 { remove(its, 0); }
}

fn deal() {
  clear(mine);
  clear(its);
  for k in 0..6 {
    push(mine, deck[k]);
    push(its, deck[k + 6]);
  }
  pile = 12;
  km = [0, 0];
  road = [0, 0];
  limit = [false, false];
  toss = false;
  won = -1;
  dealt = true;
  draw(0);
}

fn choose(k: int) {
  if !dealt || won >= 0 { return; }
  let c = mine[k];
  if toss {
    toss = false;
  } else if can(0, c) {
    play(0, c);
  } else {
    return;
  }
  remove(mine, k);
  if won < 0 { computer(); }
  if won < 0 { draw(0); }
}

fn status(p: int) -> string {
  let s = ["Stopped", "Rolling", "Accident", "Out of gas", "Flat tire"][road[p]];
  return limit[p] ? s + ", Speed limit" : s;
}

