fn used(i: int) -> bool { return i % 8 < 4 || i / 8 < 4; }

// Whether the row's and the column's things go together.
fn pair(i: int) -> bool {
  let c = i % 8;
  let r = i / 8;
  if r < 4 && c < 4 { return pet[r] == c; }
  if r < 4 { return home[r] == c - 4; }
  for p in 0..4 {
    if home[p] == r - 4 && pet[p] == c { return true; }
  }
  return false;
}

fn mistakes() -> int {
  let n = 0;
  for i in 0..64 {
