// icon: fill 6 4 18 4 18 8 6 8 fill 6 10 10 10 10 14 6 14 fill 14 10 18 10 18 14 14 14 fill 6 16 18 16 18 20 6 20
state blocks = [
  false, false, false,
  false, false, false,
  false, false, false,
  false, false, false,
  false, false, false,
  false, false, false,
  false, false, false,
  false, false, false,
  true, true, true,
  true, true, true,
  true, true, true,
  true, true, true,
  true, true, true,
  true, true, true,
  true, true, true,
  true, true, true,
  true, true, true,
  true, true, true,
  true, true, true,
  true, true, true];   // row * 3 + column: 12 full levels on rows 8 to 19
