fn setup() {
  blocks = [false; 60];
  for i in 24..60 { blocks[i] = true; }
  turn = 1;
  pulled = 0;
  fell = false;
}

fn count(r: int) -> int {
  let n = 0;
  for c in 0..3 {
    if blocks[r * 3 + c] { n += 1; }
  }
  return n;
