// The highest row with a block.
fn top() -> int {
  for r in 0..20 {
    if count(r) > 0 { return r; }
  }
  return 20;
}

fn pull(i: int) {
  if fell || !blocks[i] { return; }
  let t = top();
  let r = i / 3;
  if r == t || (r == t + 1 && count(t) < 3) { return; }
  blocks[i] = false;
  pulled += 1;
  if count(t) == 3 {
    if t > 0 { blocks[t * 3 - 3] = true; }
  } else {
    let c = 0;
    while blocks[t * 3 + c] { c += 1; }
    blocks[t * 3 + c] = true;
  }
  for rr in top() + 1..20 {
    let n = count(rr);
    if n == 0 || (n == 1 && !blocks[rr * 3 + 1]) { fell = true; }
  }
  if !fell { turn = 3 - turn; }
}

