fn count(r: int) -> int {
  let n = 0;
  for c in 0..3 {
    if blocks[r * 3 + c] { n += 1; }
  }
  return n;
}

fn top() -> int {
  for r in 0..16 {
    if count(r) > 0 { return r; }
