// Advanced teeko for two: each puts down 4 pieces, then moves one a square any way a turn. 4 in a
// row, or on the corners of a square of any size, wins.
// icon: dot 7 7 4 ring 17 7 4 ring 7 17 4 dot 17 17 4
state board = [0; 25];
state turn = 1;           // 1 red, 4 blue
state pick = -1;
state winner = 0;

fn at(c: int, r: int, p: int) -> bool {
  return c >= 0 && c < 5 && r >= 0 && r < 5 && board[r * 5 + c] == p;
}

fn count(p: int) -> int {
  let n = 0;
  for i in 0..25 {
    if board[i] == p { n += 1; }
  }
  return n;
}

// Four of p's in a row from (c, r) going (dx, dy).
fn four(c: int, r: int, dx: int, dy: int, p: int) -> bool {
  for k in 0..4 {
    if !at(c + dx * k, r + dy * k, p) { return false; }
  }
  return true;
}

fn wins(p: int) -> bool {
  for i in 0..25 {
    let c = i % 5;
    let r = i / 5;
    if four(c, r, 1, 0, p) || four(c, r, 0, 1, p) || four(c, r, 1, 1, p) || four(c, r, -1, 1, p) {
      return true;
    }
    for s in 1..5 {
      if at(c, r, p) && at(c + s, r, p) && at(c, r + s, p) && at(c + s, r + s, p) { return true; }
    }
  }
  return false;
}

fn done() {
  pick = -1;
  if wins(turn) { winner = turn; } else { turn = 5 - turn; }
}

fn tap(i: int) {
  if winner > 0 { return; }
  if count(turn) < 4 {
    if board[i] == 0 {
      board[i] = turn;
      done();
    }
  } else if board[i] == turn {
    pick = i;
  } else if pick >= 0 && board[i] == 0 && abs(i % 5 - pick % 5) <= 1 && abs(i / 5 - pick / 5) <= 1 {
    board[i] = turn;
    board[pick] = 0;
    done();
  }
}

fn scene() {
  rect(0, 0, 100, 100, 8);
  for i in 0..25 {
    rect(i % 5 * 20, i / 5 * 20, 19, 19, 0);
    if board[i] > 0 { circle(i % 5 * 20 + 10, i / 5 * 20 + 10, 7, board[i]); }
  }
  if pick >= 0 { ring(pick % 5 * 20 + 10, pick / 5 * 20 + 10, 9, 2, 3); }
}

fn status() -> string {
  if winner == 1 { return "Red wins"; }
  if winner == 4 { return "Blue wins"; }
  if turn == 1 { return "Red's turn"; }
  return "Blue's turn";
}

