// Teeko for two: each drops 4 pieces, then moves one a step any way a turn (tap it, then where it
// goes). 4 in a row or in a 2 x 2 square wins.
// icon: dot 7 7 4 ring 17 7 4 ring 7 17 4 dot 17 17 4
state board = [0; 25];
state turn = 1;           // 1 red, 4 blue
state pick = -1;
state winner = 0;
state placed = 0;         // pieces dropped so far, of 8

fn at(c: int, r: int, p: int) -> bool {
  return c >= 0 && c < 5 && r >= 0 && r < 5 && board[r * 5 + c] == p;
}

fn wins(p: int) -> bool {
  for i in 0..25 {
    let c = i % 5;
    let r = i / 5;
    if at(c, r, p) && at(c + 1, r, p) && at(c, r + 1, p) && at(c + 1, r + 1, p) { return true; }
    let a = true;
    let d = true;
    let e = true;
    let f = true;
    for k in 0..4 {
      a = a && at(c + k, r, p);
      d = d && at(c, r + k, p);
      e = e && at(c + k, r + k, p);
      f = f && at(c - k, r + k, p);
    }
    if a || d || e || f { return true; }
  }
  return false;
}

fn tap(i: int) {
  if winner > 0 { return; }
  if placed < 8 {
    if board[i] != 0 { return; }
    board[i] = turn;
    placed += 1;
  } else if board[i] == turn {
    pick = i;
    return;
  } else if pick >= 0 && board[i] == 0 && abs(i % 5 - pick % 5) <= 1 && abs(i / 5 - pick / 5) <= 1 {
    board[i] = turn;
    board[pick] = 0;
    pick = -1;
  } else {
    return;
  }
  if wins(turn) { winner = turn; } else { turn = 5 - turn; }
}

fn scene() {
  rect(0, 0, 100, 100, 8);
  for i in 0..25 {
    rect(i % 5 * 20, i / 5 * 20, 19, 19, 0);
    if board[i] > 0 { circle(i % 5 * 20 + 10, i / 5 * 20 + 10, 7, board[i]); }
  }
  if pick >= 0 { ring(pick % 5 * 20 + 10, pick / 5 * 20 + 10, 9, 2, 3); }
}

fn status() -> string {
  if winner == 1 { return "Red wins"; }
  if winner == 4 { return "Blue wins"; }
  if turn == 1 { return "Red's turn"; }
  return "Blue's turn";
}

