// Pentomino box: tap 5 squares in the shape of a pentomino not yet used to put it in the box; tap
// a piece to take it out. Fit all 12 into the 10 x 6 box.
// icon: fill 3 3 9 3 9 9 15 9 15 15 3 15 loop 9 3 21 3 21 9 9 9 loop 15 9 21 9 21 21 15 21
state box = [0; 60];      // 0 empty, -1 marked, else the piece: 1 F 2 I 3 L 4 N 5 P 6 T 7 U 8 V 9 W 10 X 11 Y 12 Z
state codes = [1250, 31, 47, 110, 103, 1249, 167, 1063, 1126, 2274, 79, 1252];
state pal = [1, 2, 4, 5, 6, 8, 1, 2, 4, 5, 6, 8];

fn count(v: int) -> int {
  let n = 0;
  for i in 0..60 {
    if box[i] == v { n += 1; }
  }
  return n;
}

fn placed() -> int {
