// The marked squares turned by t (0 to 7) and moved to the top left, as a sum of 2 to the power of
// y * 5 + x; -1 if they do not fit in 5 x 5.
fn code(t: int, xs: [int], ys: [int]) -> int {
  let mx = 99;
  let my = 99;
  for k in 0..5 {
    let a = xs[k];
    let b = ys[k];
    if t >= 4 {
      a = ys[k];
      b = xs[k];
    }
    if t % 2 == 1 { a = -a; }
    if t / 2 % 2 == 1 { b = -b; }
    xs[k] = a;
    ys[k] = b;
    mx = min(mx, a);
    my = min(my, b);
  }
  let sum = 0;
  for k in 0..5 {
    if xs[k] - mx > 4 || ys[k] - my > 4 { return -1; }
    let p = 1;
    repeat (ys[k] - my) * 5 + xs[k] - mx { p *= 2; }
    sum += p;
  }
  return sum;
}

// The piece (1 to 12) the marked squares make, or 0.
fn shape() -> int {
  let xs = [0; 0];
  let ys = [0; 0];
  for i in 0..60 {
    if box[i] == -1 {
      push(xs, i % 10);
      push(ys, i / 10);
    }
  }
  let best = -1;
  for t in 0..8 {
    let c = code(t, xs, ys);
    if c < 0 { return 0; }
    if best < 0 || c < best { best = c; }
  }
  for k in 0..12 {
    if codes[k] == best { return k + 1; }
  }
  return 0;
}

fn tap(i: int) {
  if box[i] > 0 {
    let k = box[i];
    for j in 0..60 {
      if box[j] == k { box[j] = 0; }
    }
  } else if box[i] == -1 {
    box[i] = 0;
  } else {
    box[i] = -1;
    if count(-1) == 5 {
      let k = shape();
      if k > 0 && count(k) > 0 { k = 0; }
      for j in 0..60 {
        if box[j] == -1 { box[j] = k; }
      }
    }
  }
}

fn scene() {
  let px = [0; 60];
  for i in 0..60 {
    if box[i] == -1 { px[i] = 3; }
    if box[i] > 0 { px[i] = pal[box[i] - 1]; }
  }
  pixels(px, 0, 0, 10, 16);
  for i in 0..11 { line(i * 16, 0, i * 16, 96, 1, 8); }
  for i in 0..7 { line(0, i * 16, 160, i * 16, 1, 8); }
}

