// Briscola against the computer, dealt from a fixed deck: click a card to play it. The highest
// trump, else the highest of the suit led, takes the trick; over 60 points wins.
// icon: loop 4 3 14 3 14 17 4 17 loop 10 7 20 7 20 21 10 21 dot 15 14 3
state deck = ["7H", "5C", "KS", "JH", "5S", "6D", "KH", "KC", "6S", "2S", "AS", "6H", "7C", "QH",
  "JC", "3H", "AC", "2C", "QC", "5H", "5D", "JD", "2D", "4S", "7S", "3D", "AH", "3S", "JS", "2H",
  "QD", "3C", "4D", "7D", "KD", "AD", "4H", "QS", "6C", "4C"];
state me = ["7H", "5C", "KS"];
state cpu = ["JH", "5S", "6D"];
state next = 7;           // the next card drawn; the turned-up one (6) comes last, as 40
state led = "";           // the card the computer led, waiting for mine
state trick = ["", ""];   // the last trick: mine, the computer's
state score = [0, 0];     // mine, the computer's

// A card's strength in its suit, 0 (2) to 9 (A).
fn strength(c: string) -> int {
  let order = "24567JQK3A";
  for k in 0..10 {
    if order[k] == c[0] { return k; }
  }
  return 0;
}

fn points(c: string) -> int {
  let r = c[0];
  if r == "A" { return 11; }
  if r == "3" { return 10; }
  if r == "K" { return 4; }
  if r == "Q" { return 3; }
  if r == "J" { return 2; }
  return 0;
}

// Whether b, played second, takes the trick from a.
fn beats(b: string, a: string) -> bool {
  if b[1] == a[1] { return strength(b) > strength(a); }
  return b[1] == deck[6][1];
}

// The computer's choice: the first with the fewest points of the cards that take a (all if none
// do, or if it leads).
fn choose(a: string) -> int {
  let any = false;
  for i in 0..len(cpu) {
    if a != "" && beats(cpu[i], a) { any = true; }
  }
  let pick = -1;
  for i in 0..len(cpu) {
    let fits = !any || beats(cpu[i], a);
    if fits && (pick < 0 || points(cpu[i]) < points(cpu[pick])) { pick = i; }
  }
  return pick;
}

fn draw(p: int) {
  if next > 40 { return; }
  let c = next == 40 ? deck[6] : deck[next];
  next += 1;
  if p == 0 { push(me, c); } else { push(cpu, c); }
}

fn settle(mine: string, his: string, win: int) {
  score[win] += points(mine) + points(his);
  trick = [mine, his];
  draw(win);
  draw(1 - win);
  if win == 1 && len(cpu) > 0 {
    let k = choose("");
    led = cpu[k];
    remove(cpu, k);
  }
}

fn play(i: int) {
  let c = me[i];
  remove(me, i);
  if led == "" {
    let k = choose(c);
    let d = cpu[k];
    remove(cpu, k);
    settle(c, d, beats(d, c) ? 1 : 0);
  } else {
    let d = led;
    led = "";
    settle(c, d, beats(c, d) ? 0 : 1);
  }
}

fn verdict() -> string {
  if score[0] > 60 { return "You win"; }
  if score[1] > 60 { return "Computer wins"; }
  return "Draw";
}

// A card face up on the table, centered on x.
fn card(c: string, x: int) {
  rect(x - 20, 4, 40, 52, 7);
  text(c, x, 30, 14, 9);
}

// The card the computer leads, else the last trick: mine, then its.
fn scene() {
  if led != "" {
    card(led, 80);
  } else if trick[0] != "" {
    card(trick[0], 50);
    card(trick[1], 110);
  }
}

