// Briscola against the computer from an unshuffled deck: click a card to play it. The highest
// trump, else the highest of the suit led, takes the trick; over 60 points wins.
// icon: loop 4 3 14 3 14 17 4 17 loop 10 7 20 7 20 21 10 21 dot 15 14 3
state me = [0, 1, 2];     // cards as their place in the deck: rank i % 10, suit i / 10
state cpu = [3, 4, 5];    // the computer's, the longest held first
state next = 7;           // the next card drawn; the turned-up one (6) comes last, as 40
state led = -1;           // the card the computer led, waiting for mine
state score = [0, 0];     // mine, the computer's
state strength = [9, 0, 8, 1, 2, 3, 4, 5, 6, 7];
state points = [11, 0, 10, 0, 0, 0, 0, 2, 3, 4];

fn name(c: int) -> string { return "A234567JQK"[c % 10] + "CDHS"[c / 10]; }

fn pts(c: int) -> int { return points[c % 10]; }

// Whether b, played second, takes the trick from a.
fn beats(b: int, a: int) -> bool {
  if b / 10 == a / 10 { return strength[b % 10] > strength[a % 10]; }
  return b / 10 == 0;
}

fn draw(p: int) {
  if next > 40 { return; }
  let c = next == 40 ? 6 : next;
  next += 1;
  if p == 0 { push(me, c); } else { push(cpu, c); }
}

fn settle(mine: int, his: int, win: int) {
  score[win] += pts(mine) + pts(his);
  draw(win);
  draw(1 - win);
  if win == 1 && len(cpu) > 0 {
    led = cpu[0];
    remove(cpu, 0);
  }
}

fn play(i: int) {
  let c = me[i];
  remove(me, i);
  if led < 0 {
    let d = cpu[0];
    remove(cpu, 0);
    settle(c, d, beats(d, c) ? 1 : 0);
  } else {
    let d = led;
    led = -1;
    settle(c, d, beats(c, d) ? 0 : 1);
  }
}

fn verdict() -> string {
  if score[0] > 60 { return "You win"; }
  if score[1] > 60 { return "Computer wins"; }
  return "Draw";
}

// The card the computer leads, face up.
fn scene() {
  if led >= 0 {
    rect(60, 4, 40, 52, 7);
    text(name(led), 80, 30, 14, 9);
  }
}

