    rect(i % 5 * 20, i / 5 * 20, 19, 19, land[i]);
    for k in 0..crowns[i] { circle(i % 5 * 20 + 5 + k * 6, i / 5 * 20 + 3, 2, 3); }
  }
  if first >= 0 { ring(first % 5 * 20 + 10, first / 5 * 20 + 10, 6, 2, 11); }
}

label "Kingdomino";
canvas 100, 100, scene() { tap((y / 20) * 5 + x / 20); }
if at < 8 { label "Next: " + half(ta[at], ca[at]) + "/" + half(tb[at], cb[at]); }
label "Score: " + score();

// Solo qwixx: cross off the white dice's sum in any row, then a white die plus a row's own die in
// that row, always left to right; Done ends the turn. A row's last box needs 5 crosses and locks it.
// icon: loop 3 6 21 6 21 18 3 18 line 7 9 11 15 line 11 9 7 15 line 13 9 17 15 line 17 9 13 15
state colors = [1, 3, 2, 4];          // the rows: red, yellow, green, blue
state marks = [false; 44];            // row r's box c is r * 11 + c
state locked = [false; 4];
state dice = [2, 2, 4, 3, 5, 6, 3, 4, 2, 6, 1, 5, 2, 3, 1, 2, 6, 6, 6, 3, 6, 5, 4, 2, 5, 5, 1, 3, 5, 2,
  6, 6, 6, 2, 3, 4, 1, 1, 6, 6, 1, 1];  // white, white, red, yellow, green, blue: a turn each
state turn = 0;
state phase = 0;          // 0 nothing crossed this turn, 1 the white sum, 2 done
state pen = 0;

fn value(i: int) -> int { return i / 11 < 2 ? i % 11 + 2 : 12 - i % 11; }

fn die(k: int) -> int { return dice[turn % 7 * 6 + k]; }

fn crosses(r: int) -> int {
  let n = locked[r] ? 1 : 0;
  for c in 0..11 {
    if marks[r * 11 + c] { n += 1; }
  }
  return n;
}

// The column of the last cross in row r, or -1.
fn last(r: int) -> int {
  let at = -1;
  for c in 0..11 {
    if marks[r * 11 + c] { at = c; }
  }
  return at;
}

fn over() -> bool {
  let n = 0;
  for r in 0..4 {
    if locked[r] { n += 1; }
  }
  return pen >= 4 || n >= 2;
}

fn tap(i: int) {
  let r = i / 11;
  let c = i % 11;
  if over() || locked[r] || phase == 2 || c <= last(r) { return; }
  if c == 10 && crosses(r) < 5 { return; }
  let v = value(i);
  if phase == 0 && v == die(0) + die(1) {
    phase = 1;
  } else if v == die(0) + die(2 + r) || v == die(1) + die(2 + r) {
    phase = 2;
  } else {
    return;
  }
  marks[i] = true;
  if c == 10 { locked[r] = true; }
}

fn score() -> int {
  let s = -5 * pen;
  for r in 0..4 { s += crosses(r) * (crosses(r) + 1) / 2; }
  return s;
}

fn scene() {
  for i in 0..44 {
    rect(i % 11 * 20, i / 11 * 20, 19, 19, marks[i] ? 8 : colors[i / 11]);
    text(value(i), i % 11 * 20 + 10, i / 11 * 20 + 10, 8, 9);
  }
}

label "Qwixx";
label "White " + die(0) + " " + die(1) + "   red " + die(2) + "   yellow " + die(3) + "   green " + die(4) + "   blue " + die(5);
canvas 220, 80, scene() { tap((y / 20) * 11 + x / 20); }
label "Score: " + score() + "   Penalties: " + pen;
if over() {
  label "Game over";
} else {
  button "Done" {
    if phase == 0 { pen += 1; }
    phase = 0;
    turn += 1;
  }
}

// Qwixx score pad: tap a number to cross it off, left to right in its row; a row's last number needs
// 5 crosses and locks the row. Penalty takes 5. Rows score 1, 3, 6, 10... for 1, 2, 3, 4... crosses.
// icon: loop 3 6 21 6 21 18 3 18 line 7 9 11 15 line 11 9 7 15 line 13 9 17 15 line 17 9 13 15
state colors = [1, 3, 2, 4];          // the rows: red, yellow, green, blue
state marks = [false; 44];            // row r's box c is r * 11 + c
state locked = [false; 4];
state pen = 0;

fn value(i: int) -> int { return i / 11 < 2 ? i % 11 + 2 : 12 - i % 11; }

fn crosses(r: int) -> int {
  let n = locked[r] ? 1 : 0;
  for c in 0..11 {
    if marks[r * 11 + c] { n += 1; }
  }
  return n;
}

// Crosses box i if nothing is crossed right of it in its row; the row's last number (12 for red and
// yellow, 2 for green and blue) needs 5 crosses, and locks the row.
fn tap(i: int) {
  let r = i / 11;
  if locked[r] { return; }
  for k in i % 11..11 {
    if marks[r * 11 + k] { return; }
  }
  let last = value(i) == (r < 2 ? 12 : 2);
  if last && crosses(r) < 5 { return; }
  marks[i] = true;
  locked[r] = last;
}

fn total() -> int {
  let s = -5 * pen;
  for r in 0..4 { s += crosses(r) * (crosses(r) + 1) / 2; }
  return s;
}

// The pad: each box in its row's color, gray once crossed, with its number.
fn shades() -> [int] {
  let v = [0; 44];
  for i in 0..44 { v[i] = marks[i] ? 8 : colors[i / 11]; }
  return v;
}

fn numbers() -> [string] {
  let v = [""; 44];
  for i in 0..44 { v[i] = "" + value(i); }
  return v;
}

label "Qwixx pad";
grid 11, shades(), numbers() { tap(cell); }
label "Total: " + total();
button "Penalty" { pen += 1; }

// Can't Stop for two: roll, pick a pairing of the dice to move up to 3 runners, then roll again or
// stop to keep the progress; a roll that moves nothing loses it. Claim 3 columns to win.
// icon: line 5 21 5 15 line 9 21 9 9 line 13 21 13 3 line 17 21 17 9 dot 13 6 2 dot 9 12 2
state heights = [3, 5, 7, 9, 11, 13, 11, 9, 7, 5, 3];       // columns 2 to 12
state dice = [1, 1, 6, 6, 1, 1, 5, 6, 1, 1, 6, 6, 1, 2, 3, 4, 2, 2, 2, 2, 1, 1, 1, 2, 1, 1, 4, 4,
  6, 6, 6, 6, 6, 6, 1, 1, 5, 6, 5, 6, 1, 1, 1, 1, 1, 2, 1, 2, 2, 1, 2, 1, 1, 2, 3, 3];
state next = 0;           // the next die rolled
state d = [0, 0, 0, 0];   // the dice now
state marks = [0; 22];    // red's step in each column, then blue's
state owner = [0; 11];    // 0 nobody, 1 red, 2 blue
state runs = [0; 11];     // the runners' steps this turn, 0 none
state rolled = false;     // a roll waits for its pairing
state chosen = false;     // a pairing was chosen this turn
state turn = 0;           // 0 red, 1 blue
state winner = 0;

// The two sums of pairing k: the first die with die k + 1, the other two together.
fn sums(k: int) -> [int] {
  if k == 0 { return [d[0] + d[1], d[2] + d[3]]; }
  if k == 1 { return [d[0] + d[2], d[1] + d[3]]; }
  return [d[0] + d[3], d[1] + d[2]];
}

// The runners after pairing k.
fn after(k: int) -> [int] {
  let r = runs;
  let s = sums(k);
  for j in 0..2 {
    let c = s[j] - 2;
    let out = 0;
    for q in 0..11 {
      if r[q] > 0 { out += 1; }
    }
    let at = r[c] > 0 ? r[c] : marks[turn * 11 + c];
    if owner[c] == 0 && at < heights[c] && (r[c] > 0 || out < 3) { r[c] = at + 1; }
  }
  return r;
}

fn usable(k: int) -> bool {
  let r = after(k);
  for c in 0..11 {
    if r[c] != runs[c] { return true; }
  }
  return false;
}

fn claimed(p: int) -> int {
  let n = 0;
  for c in 0..11 {
    if owner[c] == p { n += 1; }
  }
  return n;
}

fn pass() {
  runs = [0; 11];
  chosen = false;
  turn = 1 - turn;
}

fn roll() {
  for k in 0..4 { d[k] = dice[(next + k) % len(dice)]; }
  next += 4;
  rolled = usable(0) || usable(1) || usable(2);
  if !rolled { pass(); }
}

fn stop() {
  for c in 0..11 {
    if runs[c] > 0 {
      marks[turn * 11 + c] = runs[c];
      if runs[c] >= heights[c] { owner[c] = turn + 1; }
    }
  }
  if claimed(turn + 1) >= 3 { winner = turn + 1; } else { pass(); }
}

// The columns bottom up: a claimed one in its owner's color; each player's marker (purple where
// both are), the runners in ink.
fn scene() {
  let px = [-1; 143];
  for c in 0..11 {
    for s in 1..heights[c] + 1 {
      let v = 7;
      if owner[c] > 0 { v = owner[c] == 1 ? 1 : 4; }
      if marks[c] == s { v = 1; }
      if marks[11 + c] == s { v = marks[c] == s ? 5 : 4; }
      if runs[c] == s { v = 9; }
      px[(13 - s) * 11 + c] = v;
    }
  }
  pixels(px, 0, 0, 11, 10);
  for c in 0..11 { text(c + 2, c * 10 + 5, 135, 6, 10); }
}

label "Can't Stop";
canvas 110, 140, scene();
if winner == 1 { label "Red wins"; }
if winner == 2 { label "Blue wins"; }
if winner == 0 { label turn == 0 ? "Red's turn" : "Blue's turn"; }
label "Red: " + claimed(1) + "   Blue: " + claimed(2);
if rolled { label "Dice: " + d[0] + " " + d[1] + " " + d[2] + " " + d[3]; }
if winner == 0 {
  row {
    if rolled {
      for k in 0..3 {
        if usable(k) {
          button sums(k)[0] + " and " + sums(k)[1] {
            runs = after(k);
            rolled = false;
            chosen = true;
          }
        }
      }
    } else {
      button "Roll" { roll(); }
      if chosen { button "Stop" { stop(); } }
    }
  }
}

// Can't Stop solitaire: roll, pick a pairing of the dice to move up to 3 runners, then roll again or
// stop to keep the progress; a roll that moves nothing loses it. Claim 3 columns.
// icon: line 5 21 5 15 line 9 21 9 9 line 13 21 13 3 line 17 21 17 9 dot 13 6 2 dot 9 12 2
state heights = [3, 5, 7, 9, 11, 13, 11, 9, 7, 5, 3];       // columns 2 to 12
state next = 0;           // dice so far: they go 1 to 6 in turn
state d = [0, 0, 0, 0];
state marks = [0; 11];
state runs = [0; 11];     // the runners' steps this turn, 0 none
state rolled = false;     // a roll waits for its pairing
state chosen = false;     // a pairing was chosen this turn
state turns = 1;

fn sums(k: int) -> [int] {
  if k == 0 { return [d[0] + d[1], d[2] + d[3]]; }
  if k == 1 { return [d[0] + d[2], d[1] + d[3]]; }
  return [d[0] + d[3], d[1] + d[2]];
}

fn claimed() -> int {
  let n = 0;
  for c in 0..11 {
    if marks[c] >= heights[c] { n += 1; }
  }
  return n;
}

// The runners after pairing k.
fn after(k: int) -> [int] {
  let r = runs;
  let s = sums(k);
  for j in 0..2 {
    let c = s[j] - 2;
    let out = 0;
    for q in 0..11 {
      if r[q] > 0 { out += 1; }
    }
    let at = r[c] > 0 ? r[c] : marks[c];
    if at < heights[c] && (r[c] > 0 || out < 3) { r[c] = at + 1; }
  }
  return r;
}

fn usable(k: int) -> bool {
  let r = after(k);
  for c in 0..11 {
    if r[c] != runs[c] { return true; }
  }
  return false;
}

fn roll() {
  for k in 0..4 { d[k] = (next + k) % 6 + 1; }
  next += 4;
  rolled = usable(0) || usable(1) || usable(2);
  if !rolled {
    runs = [0; 11];
    chosen = false;
    turns += 1;
  }
}

fn stop() {
  for c in 0..11 {
    if runs[c] > 0 { marks[c] = runs[c]; }
  }
  runs = [0; 11];
  chosen = false;
  if claimed() < 3 { turns += 1; }
}

// The columns bottom up: claimed ones green, the markers blue, the runners in ink.
fn scene() {
  let px = [-1; 143];
  for c in 0..11 {
    for s in 1..heights[c] + 1 {
      let v = marks[c] >= heights[c] ? 2 : 7;
      if marks[c] == s { v = 4; }
      if runs[c] == s { v = 9; }
      px[(13 - s) * 11 + c] = v;
    }
  }
  pixels(px, 0, 0, 11, 10);
}

label "Can't Stop";
canvas 110, 130, scene();
label "Turn " + turns + "   Dice: " + d[0] + " " + d[1] + " " + d[2] + " " + d[3];
if claimed() >= 3 {
  label "You win in " + turns + " turns";
} else {
  row {
    if rolled {
      for k in 0..3 {
        if usable(k) {
          button sums(k)[0] + "+" + sums(k)[1] {
            runs = after(k);
            rolled = false;
            chosen = true;
          }
        }
      }
    } else {
      button "Roll" { roll(); }
      if chosen { button "Stop" { stop(); } }
    }
  }
}

// The shifting labyrinth: turn the spare tile, push it into a row or column, then tap where your
// piece goes along the joined paths. Reach the treasure.
// icon: line 3 8 9 8 9 3 line 3 15 15 15 15 3 line 21 9 21 21 9 21 dot 9 21 2
state tiles = ["ES", "NEW", "NS", "NW", "SW", "NS", "ESW", "SW", "NSW", "EW", "ESW", "ES", "NES",
  "NS", "NW", "NS", "NS", "NES", "SW", "NW", "NE", "ESW", "ES", "NSW", "NW"];   // their open sides
state spare = "NES";
state piece = 0;
state gem = 11;
state pushed = false;     // this turn's push is done: a tap moves
state last = -1;          // the last push, 0 to 7, as in names
state names = ["Right 2", "Right 4", "Left 2", "Left 4", "Down 2", "Down 4", "Up 2", "Up 4"];
state found = false;

fn open(t: string, side: string) -> bool {
  for k in 0..len(t) {
    if t[k] == side { return true; }
  }
  return false;
}

// The tile turned a quarter clockwise: each open side moves on one, N to E to S to W to N.
fn turned(t: string) -> string {
  let out = "";
  let sides = "NESW";
  for k in 0..4 {
    if open(t, sides[(k + 3) % 4]) { out = out + sides[k]; }
  }
  return out;
}

// Where a thing at i goes along the pushed line: one place on, the end coming round.
fn moved(i: int, places: [int]) -> int {
  for j in 0..5 {
    if places[j] == i { return places[(j + 1) % 5]; }
  }
  return i;
}

// Push p (as in names): the spare goes in at the line's first place, the last tile comes out.
fn shove(p: int) {
  if found || pushed || (abs(p - last) == 2 && p / 4 == last / 4) { return; }
  let k = p % 2 == 0 ? 1 : 3;
  let places = [0; 5];
  for j in 0..5 {
    let at = p % 4 < 2 ? j : 4 - j;
    places[j] = p < 4 ? k * 5 + at : at * 5 + k;
  }
  let out = tiles[places[4]];
  for j in 0..4 { tiles[places[4 - j]] = tiles[places[3 - j]]; }
  tiles[places[0]] = spare;
  spare = out;
  piece = moved(piece, places);
  gem = moved(gem, places);
  last = p;
  pushed = true;
}

// Whether the piece reaches tile goal along joined paths.
fn reaches(goal: int) -> bool {
  let seen = [false; 25];
  let todo = [piece];
  seen[piece] = true;
  let dx = [0, 1, 0, -1];
  let dy = [-1, 0, 1, 0];
  while len(todo) > 0 {
    let i = todo[len(todo) - 1];
    remove(todo, len(todo) - 1);
    if i == goal { return true; }
    for k in 0..4 {
      let c = i % 5 + dx[k];
      let r = i / 5 + dy[k];
      let j = r * 5 + c;
      if c >= 0 && c < 5 && r >= 0 && r < 5 && !seen[j] && open(tiles[i], "NESW"[k]) && open(tiles[j], "NESW"[(k + 2) % 4]) {
        seen[j] = true;
        push(todo, j);
      }
    }
  }
  return false;
}

fn tap(i: int) {
  if found || !pushed || !reaches(i) { return; }
  piece = i;
  pushed = false;
  found = piece == gem;
}

// A tile as a 5 x 5 sprite: gray paths from its middle to its open sides.
fn art(t: string) -> [string] {
  let n = open(t, "N") ? "8" : ".";
  let e = open(t, "E") ? "88" : "..";
  let s = open(t, "S") ? "8" : ".";
  let w = open(t, "W") ? "88" : "..";
  return [".." + n + "..", ".." + n + "..", w + "8" + e, ".." + s + "..", ".." + s + ".."];
}

fn scene() {
  for i in 0..25 { sprite(art(tiles[i]), i % 5 * 20, i / 5 * 20, 4); }
  if !found { circle(gem % 5 * 20 + 10, gem / 5 * 20 + 10, 5, 3); }
  circle(piece % 5 * 20 + 10, piece / 5 * 20 + 10, 4, 1);
}

label "Labyrinth";
canvas 100, 100, scene() { tap((y / 20) * 5 + x / 20); }
if found {
  label "You found it";
} else {
  label "Spare tile: " + spare + (pushed ? "   Tap where to go" : "   Push it in");
  row {
    button "Turn" { spare = turned(spare); }
    for p in 0..8 { button names[p] { shove(p); } }
  }
}

// Theseus and the minotaur: the arrows move you a square, space waits. After each move the minotaur
// takes 2 steps toward you, across first. Reach the exit before it catches you.
// icon: ring 8 12 4 dot 16 12 4 line 3 4 21 4 line 3 20 21 20
state maze = ["#########", "#.#.....#", "#T.#..M.#", "##.#.##.#", "#.......#", "#.#..#.E#", "#########"];
state tx = 1;             // Theseus
state ty = 2;
state mx = 6;             // the minotaur
state my = 2;
state over = "";

fn wall(x: int, y: int) -> bool { return maze[y][x] == "#"; }

// One step of the minotaur: across toward Theseus if it can, else up or down, else none.
fn step() {
  if tx != mx {
    let dx = tx > mx ? 1 : -1;
    if !wall(mx + dx, my) {
      mx += dx;
      return;
    }
  }
  if ty != my {
    let dy = ty > my ? 1 : -1;
    if !wall(mx, my + dy) { my += dy; }
  }
}

fn go(dx: int, dy: int) {
  if over != "" || wall(tx + dx, ty + dy) { return; }
  tx += dx;
  ty += dy;
  if maze[ty][tx] == "E" {
    over = "Escaped!";
    return;
  }
  repeat 2 {
    if tx != mx || ty != my { step(); }
  }
  if tx == mx && ty == my { over = "Caught!"; }
}

fn scene() {
  let px = [0; 63];
  for i in 0..63 {
    let ch = maze[i / 9][i % 9];
    if ch == "#" { px[i] = 8; }
    if ch == "E" { px[i] = 2; }
  }
  px[ty * 9 + tx] = 4;
  px[my * 9 + mx] = 1;
  pixels(px, 0, 0, 9, 10);
}

on key "left" { go(-1, 0); }
on key "right" { go(1, 0); }
on key "up" { go(0, -1); }
on key "down" { go(0, 1); }
on key "space" { go(0, 0); }

label "Theseus and the minotaur";
canvas 90, 70, scene();
label over;

// Defender: the arrows fly the ship (left and right also turn it), space or Fire shoots the
// nearest lander ahead. Stop the landers carrying the humanoids off, in two waves.
// icon: fill 2 8 13 8 20 12 13 16 2 16 line 20 12 22 12 line 6 4 6 8
state hx = [3, 8, 13];         // the humanoids: column, and row (9 while standing)
state hy = [9, 9, 9];
state lx = [0; 0];             // the landers: square, the humanoid each is after, and whether
state ly = [0; 0];             // it has it and rises
state lh = [0; 0];
state rising = [false; 0];
state sx = 1;                  // the ship, and the way it faces (1 right, -1 left)
state sy = 4;
state face = 1;
state score = 0;
state wave = 1;
state speed = 0;               // ms a step; 0 while no game runs
state result = "";

fn lander(c: int, h: int) {
  push(lx, c);
  push(ly, 0);
  push(lh, h);
  push(rising, false);
}

fn begin() {
  clear(lx);
  clear(ly);
  clear(lh);
  clear(rising);
  lander(3, 0);
  if wave == 2 { lander(8, 1); }
  lander(13, 2);
}

fn stop(s: string) {
  result = s;
  speed = 0;
}

fn start() {
  hy = [9, 9, 9];
  sx = 1;
  sy = 4;
  face = 1;
  score = 0;
  wave = 1;
  result = "";
  begin();
  speed = 500;
}

fn crash() {
  for k in 0..len(lx) {
    if lx[k] == sx && ly[k] == sy { stop("Game over"); }
  }
}

fn fly(dx: int, dy: int) {
  if speed == 0 { return; }
  if dx != 0 { face = dx; }
  sx = min(15, max(0, sx + dx));
  sy = min(8, max(0, sy + dy));
  crash();
}

// The laser: the nearest lander in the ship's row, the way it faces.
fn fire() {
  if speed == 0 { return; }
  let hit = -1;
  for k in 0..len(lx) {
    if ly[k] == sy && (lx[k] - sx) * face > 0 {
      if hit < 0 || abs(lx[k] - sx) < abs(lx[hit] - sx) { hit = k; }
    }
  }
  if hit < 0 { return; }
  score += 150;
  hy[lh[hit]] = 9;
  remove(lx, hit);
  remove(ly, hit);
  remove(lh, hit);
  remove(rising, hit);
  if len(lx) == 0 && wave == 2 {
    stop("You win");
  } else if len(lx) == 0 {
    wave = 2;
    begin();
  }
}

every speed {
  for k in 0..len(lx) {
    if rising[k] && ly[k] == 0 {
      stop("Game over");
    } else if rising[k] {
      ly[k] -= 1;
      hy[lh[k]] = ly[k] + 1;
    } else if ly[k] == 8 {
      rising[k] = true;
      ly[k] = 7;
      hy[lh[k]] = 8;
    } else {
      ly[k] += 1;
    }
  }
  crash();
}

on key "left" { fly(-1, 0); }
on key "right" { fly(1, 0); }
on key "up" { fly(0, -1); }
on key "down" { fly(0, 1); }
on key "space" { fire(); }

fn scene() {
  let cells = [-1; 160];
  for i in 0..3 { cells[hy[i] * 16 + hx[i]] = 6; }
  for k in 0..len(lx) { cells[ly[k] * 16 + lx[k]] = 1; }
  cells[sy * 16 + sx] = 2;
  pixels(cells, 0, 0, 16, 10);
  if result != "" { text(result, 80, 40, 16, 11); }
}

// A tap flies the ship a square toward it, across or up and down, whichever is farther.
fn toward(c: int, r: int) {
  if abs(c - sx) > abs(r - sy) {
    fly((c - sx) / abs(c - sx), 0);
  } else if r != sy {
    fly(0, (r - sy) / abs(r - sy));
  }
}

