// Spacewar: two ships circle the star, pulled by its gravity. Green thrusts with W A S D and fires
// with space, blue with the arrows and enter. A hit or a fall into the star is a point; first to 3.
// icon: dot 12 12 3 ring 12 12 8 fill 16 2 22 4 18 8
state px = [7, 7];             // the ships, green then blue: square and speeds
state py = [1, 9];
state vx = [2, -2];
state vy = [0, 0];
state tx = [0, 0];             // their torpedoes: square, way, and squares left (0: none)
state ty = [0, 0];
state tdx = [0, 0];
state tdy = [0, 0];
state tleft = [0, 0];
state score = [0, 0];
state ticks = 0;               // 100 ms ticks since Start
state speed = 0;               // 100 while a game runs, else 0
state result = "";

fn sgn(a: int) -> int {
  if a > 0 { return 1; }
  if a < 0 { return -1; }
  return 0;
}

fn clip(v: int) -> int { return min(2, max(-2, v)); }

fn home() {
  px = [7, 7];
  py = [1, 9];
  vx = [2, -2];
  vy = [0, 0];
  tleft = [0, 0];
}

// Player p scores: a new round, or the game won.
fn point(p: int) {
  score[p] += 1;
  home();
  if score[p] == 3 {
    speed = 0;
    if p == 0 { result = "Green wins"; } else { result = "Blue wins"; }
  }
}

// Torpedo i where it now is: gone past an edge, or a hit on the other ship.
fn land(i: int) {
  if tx[i] < 0 || tx[i] > 14 || ty[i] < 0 || ty[i] > 10 {
    tleft[i] = 0;
  } else if tx[i] == px[1 - i] && ty[i] == py[1 - i] {
    point(i);
  }
}

fn fire(i: int) {
  let dx = sgn(vx[i]);
  let dy = sgn(vy[i]);
  if speed == 0 || tleft[i] > 0 || (dx == 0 && dy == 0) { return; }
  tx[i] = px[i] + dx;
  ty[i] = py[i] + dy;
  tdx[i] = dx;
  tdy[i] = dy;
  tleft[i] = 4;
  land(i);
}

fn thrust(i: int, dx: int, dy: int) {
  if speed == 0 { return; }
  vx[i] = clip(vx[i] + dx);
  vy[i] = clip(vy[i] + dy);
}

// Gravity, then each ship moves by its speeds around the edges; one on the star is lost.
fn step() {
  for i in 0..2 {
    vx[i] = clip(vx[i] + sgn(7 - px[i]));
    vy[i] = clip(vy[i] + sgn(5 - py[i]));
    px[i] = (px[i] + vx[i] + 15) % 15;
    py[i] = (py[i] + vy[i] + 11) % 11;
  }
  for i in 0..2 {
    if speed > 0 && px[i] == 7 && py[i] == 5 { point(1 - i); }
  }
}

every speed {
  ticks += 1;
  for i in 0..2 {
    if tleft[i] > 0 {
      tleft[i] -= 1;
      if tleft[i] > 0 {
        tx[i] += tdx[i];
        ty[i] += tdy[i];
        land(i);
      }
    }
  }
  if speed > 0 && ticks % 5 == 0 { step(); }
}

