// join into the next bigger fruit; a fruit left on the top row ends it.
// icon: ring 12 13 8 line 12 5 14 2 dot 9 11 2
state box = [0; 35];           // the 5 x 7 board, c + 5 * r: 0 empty, else the fruit 1 to 5
