state over = false;

fn start() {
  box = [0; 35];
  hand = 2;
  n = 0;
  score = 0;
  over = false;
  playing = true;
}

// The square i empties; the fruits above it fall one square.
fn empty(i: int) {
  let r = i / 5;
  while r > 1 {
    box[r * 5 + i % 5] = box[(r - 1) * 5 + i % 5];
    r -= 1;
  }
  box[5 + i % 5] = 0;
}

// The fruit on square i joins one of its kind below, left or right, again and again.
fn join(at0: int) -> bool {
  let i = at0;
  let joined = false;
  let going = true;
  while going {
    let k = box[i];
    let j = -1;
    if i / 5 < 6 && box[i + 5] == k {
      j = i + 5;
    } else if i % 5 > 0 && box[i - 1] == k {
      j = i - 1;
    } else if i % 5 < 4 && box[i + 1] == k {
      j = i + 1;
    }
    if j < 0 || k == 5 {
      going = false;
    } else {
      box[j] = k + 1;
      score += k + 1;
      empty(i);
      i = j;
      joined = true;
    }
  }
  return joined;
}

fn drop() {
  if !playing { return; }
  let r = 6;
  while r > 0 && box[r * 5 + hand] > 0 { r -= 1; }
  if r == 0 { return; }
  box[r * 5 + hand] = order[n % 6];
  n += 1;
  if !join(r * 5 + hand) && r == 1 {
    playing = false;
    over = true;
  }
}

fn move(d: int) {
  if playing { hand = min(4, max(0, hand + d)); }
}

