state order = [1, 1, 2, 3, 4, 5];
state names = ["", "cherry", "grape", "orange", "apple", "melon", "watermelon"];
state colors = [0, 1, 5, 3, 2, 6, 4];
state n = 0;
state result = "";

// The fruit on square i merges with one of its kind it touches, again and again.
fn merge(at0: int) {
  let i = at0;
  let going = true;
  while going {
    let k = box[i];
    let j = -1;
    if i < 20 && box[i + 4] == k {
      j = i + 4;
    } else if i % 4 > 0 && box[i - 1] == k {
      j = i - 1;
    } else if i % 4 < 3 && box[i + 1] == k {
      j = i + 1;
    }
    if j < 0 || k == 6 {
      going = false;
    } else {
      box[j] = k + 1;
      box[i] = 0;
      let r = i / 4;
      while r > 0 {
        box[r * 4 + i % 4] = box[(r - 1) * 4 + i % 4];
        r -= 1;
      }
      box[i % 4] = 0;
      if k + 1 == 6 { result = "A watermelon! You win"; }
      i = j;
    }
  }
}

fn drop(c: int) {
  if result != "" { return; }
  if box[c] > 0 {
    result = "Game over";
    return;
  }
  let r = 5;
  while box[r * 4 + c] > 0 { r -= 1; }
  box[r * 4 + c] = order[n % 6];
  n += 1;
  merge(r * 4 + c);
}

