// Love Letter against the computer: tap one of your two cards to play it (a Guard then names a
// card). Be the last one in, or hold the higher card at the end; 3 tokens win.
// icon: loop 3 6 21 6 21 18 3 18 line 3 6 12 13 21 6
state deck = [1, 2, 8, 1, 1, 4, 3, 7, 1, 6, 5, 5, 4, 3, 2, 1];
state names = ["", "Guard", "Priest", "Baron", "Handmaid", "Prince", "King", "Countess", "Princess"];
state top = 0;                 // the next card to draw
state aside = 0;
state mine = [0; 0];
state its = [0; 0];
state safe = [false, false];   // protected by a Handmaid: me, the computer
state guessing = false;        // my Guard waits for its guess
state seen = 0;                // what my last Priest showed
state last = 0;                // the computer's last card played
state tokens = [0, 0];
state phase = 0;               // 0 no game, 1 a round runs, 2 between rounds
state result = "";

fn take() -> int {
  if top < 16 {
    top += 1;
    return deck[top - 1];
  }
  let c = aside;
  aside = 0;
  return c;
}

fn deal() {
  aside = deck[0];
  mine = [deck[1], deck[3]];
  its = [deck[2]];
  top = 4;
  safe = [false, false];
  guessing = false;
  seen = 0;
  last = 0;
  result = "";
  phase = 1;
}

// Player w (0 me, 1 the computer) wins the round.
fn win(w: int) {
  tokens[w] += 1;
  phase = 2;
  if w == 0 { result = "You win the round"; } else { result = "The computer wins the round"; }
  if tokens[w] == 3 {
    phase = 0;
    if w == 0 { result = "You win the game"; } else { result = "The computer wins the game"; }
  }
}

fn hand(p: int) -> int {
  if p == 0 { return mine[0]; }
  return its[0];
}

// Player p plays card c (a Guard naming g); true if the round ended.
fn effect(p: int, c: int, g: int) -> bool {
  let o = 1 - p;
  if c == 8 {
    win(o);
    return true;
  }
  if safe[o] || c == 4 || c == 7 {
    if c == 4 { safe[p] = true; }
    return false;
  }
  if c == 1 && hand(o) == g {
    win(p);
    return true;
  }
  if c == 2 && p == 0 { seen = its[0]; }
  if c == 3 && hand(p) != hand(o) {
    if hand(p) > hand(o) { win(p); } else { win(o); }
    return true;
  }
  if c == 5 {
    let d = hand(o);
    if d == 8 {
      win(p);
      return true;
    }
    if o == 0 { mine[0] = take(); } else { its[0] = take(); }
  }
  if c == 6 {
    let t = mine[0];
    mine[0] = its[0];
    its[0] = t;
  }
  return false;
}

// No card left to draw: the higher card wins.
fn showdown() {
  if mine[0] > its[0] {
    win(0);
  } else if its[0] > mine[0] {
    win(1);
  } else {
    phase = 2;
    result = "A tie: nobody wins the round";
  }
}

fn theirs() {
  if top == 16 {
    showdown();
    return;
  }
  safe[1] = false;
  push(its, take());
  let i = 0;
  if its[1] < its[0] { i = 1; }
  if its[0] == 7 && (its[1] == 5 || its[1] == 6) { i = 0; }
  if its[1] == 7 && (its[0] == 5 || its[0] == 6) { i = 1; }
  if its[i] == 8 { i = 1 - i; }
  last = its[i];
  remove(its, i);
  if effect(1, last, 2) { return; }
  if top == 16 {
    showdown();
    return;
  }
  safe[0] = false;
  push(mine, take());
}

fn play(i: int) {
  let c = mine[i];
  let other = mine[1 - i];
  if (c == 5 || c == 6) && other == 7 { return; }
  seen = 0;
  remove(mine, i);
  if c == 1 {
    guessing = true;
  } else if !effect(0, c, 0) {
    theirs();
  }
}

fn guess(g: int) {
  guessing = false;
  if !effect(0, 1, g) { theirs(); }
}

