// Mini Love Letter: tap one of your two cards to play it; after a Guard press 3, 4 or 8 to guess.
// Knock the computer out, or hold the higher card when the deck runs out.
// icon: loop 3 6 21 6 21 18 3 18 line 3 6 12 13 21 6
state deck = [4, 1, 3, 1, 1, 4, 8];
state names = ["", "Guard", "", "Baron", "Handmaid", "", "", "", "Princess"];
state top = 0;
state mine = [0; 0];
state its = [0; 0];
state safe = [false, false];   // me, the computer
state guessing = false;
state result = "";

fn deal() {
  mine = [deck[0], deck[2]];
  its = [deck[1]];
  top = 3;
  safe = [false, false];
  guessing = false;
  result = "";
}

fn hand(p: int) -> int {
  if p == 0 { return mine[0]; }
  return its[0];
}

// The round won by player w (0 me, 1 the computer).
fn win(w: int) {
  if w == 0 { result = "You win!"; } else { result = "You lose: the computer wins"; }
}

// Player p plays card c (a Guard guessing g); true if the round is over.
fn effect(p: int, c: int, g: int) -> bool {
  let o = 1 - p;
  if c == 8 {
    win(o);
  } else if c == 4 {
    safe[p] = true;
  } else if !safe[o] && c == 1 && hand(o) == g {
    win(p);
  } else if !safe[o] && c == 3 && hand(p) > hand(o) {
    win(p);
  } else if !safe[o] && c == 3 && hand(p) < hand(o) {
    win(o);
  }
  if result == "" && top == len(deck) {
    if mine[0] > its[0] { win(0); } else if its[0] > mine[0] { win(1); } else { result = "A tie"; }
  }
  return result != "";
}

fn theirs() {
  safe[1] = false;
  push(its, deck[top]);
  top += 1;
  let i = 0;
  if its[1] < its[0] { i = 1; }
  let c = its[i];
  remove(its, i);
  if effect(1, c, 3) { return; }
  safe[0] = false;
  push(mine, deck[top]);
  top += 1;
}

fn play(i: int) {
  if result != "" || guessing { return; }
  let c = mine[i];
  remove(mine, i);
  if c == 1 {
    guessing = true;
  } else if !effect(0, c, 0) {
    theirs();
  }
}

fn guess(g: int) {
  if !guessing { return; }
  guessing = false;
  if !effect(0, 1, g) { theirs(); }
}

