// 6 nimmt! against the computer: click a card to play it; the lower card goes first, onto the row
// ending just below it. A sixth card or a card below every row takes the row's bullheads.
// icon: loop 5 3 16 3 16 21 5 21 dot 10 9 2 line 8 15 13 15
state rows = [0; 20];          // row r holds rows[r * 5] .. rows[r * 5 + len - 1]
state lens = [0, 0, 0, 0];
state mine = [0; 0];
state its = [0; 0];
state taken = [0, 0];          // bullheads: me, the computer
state played = 0;              // the computer's card this turn
state waiting = 0;             // the computer's card waiting for my pick (0: none)
state picking = 0;             // my card waiting for my pick (0: none)
state playing = false;
state result = "";

fn bulls(c: int) -> int {
  if c == 55 { return 7; }
  if c % 11 == 0 { return 5; }
  if c % 10 == 0 { return 3; }
  if c % 5 == 0 { return 2; }
  return 1;
}

fn worth(r: int) -> int {
  let n = 0;
  for k in 0..lens[r] { n += bulls(rows[r * 5 + k]); }
  return n;
}

fn last(r: int) -> int { return rows[r * 5 + lens[r] - 1]; }

// Player p takes row r; card c starts it.
fn take(p: int, r: int, c: int) {
  taken[p] += worth(r);
  rows[r * 5] = c;
  lens[r] = 1;
}

// Player p's card c on its row; false if it is mine and below every row (I must pick).
fn place(p: int, c: int) -> bool {
  let best = -1;
  for r in 0..4 {
    if last(r) < c && (best < 0 || last(r) > last(best)) { best = r; }
  }
  if best < 0 && p == 0 { return false; }
  if best < 0 {
    best = 0;
    for r in 1..4 {
      if worth(r) < worth(best) { best = r; }
    }
    take(1, best, c);
  } else if lens[best] == 5 {
    take(p, best, c);
  } else {
    rows[best * 5 + lens[best]] = c;
    lens[best] += 1;
  }
  return true;
}

fn finish() {
  if len(mine) > 0 { return; }
  playing = false;
  if taken[0] < taken[1] { result = "You win"; }
  if taken[0] > taken[1] { result = "The computer wins"; }
  if taken[0] == taken[1] { result = "A tie"; }
}

fn play(i: int) {
  if !playing || picking > 0 { return; }
  let c = mine[i];
  remove(mine, i);
  played = its[0];
  remove(its, 0);
  if played < c {
    place(1, played);
    if !place(0, c) { picking = c; }
  } else if !place(0, c) {
    picking = c;
    waiting = played;
  } else {
    place(1, played);
  }
  if picking == 0 { finish(); }
}

fn pick(r: int) {
  take(0, r, picking);
  picking = 0;
  if waiting > 0 { place(1, waiting); }
  waiting = 0;
  finish();
}

fn shown(r: int) -> string {
  let s = "Row " + (r + 1) + ":";
  for k in 0..lens[r] { s = s + " " + rows[r * 5 + k]; }
  return s;
}

