// 6 nimmt with 2 rows: click a card; both cards go down lowest first, after the row's closest
// lower card. A 6th card or one below both rows takes that row; fewest cards taken wins.
// icon: loop 5 3 16 3 16 21 5 21 dot 10 9 2 line 8 15 13 15
state a = [20];                // the two rows
state b = [50];
state mine = [8, 24, 25, 63, 64];
state its = [34, 3, 47, 54, 73];
state turn = 0;
state points = [0, 0];         // cards taken: me, the computer
state result = "";

fn tail(r: [int]) -> int { return r[len(r) - 1]; }

// Player p puts down card c.
fn put(p: int, c: int) {
  let ta = tail(a);
  let tb = tail(b);
  let toA = ta < c && (tb > c || ta > tb);
  let toB = tb < c && !toA;
  if !toA && !toB {
    toA = len(a) <= len(b);
    toB = !toA;
    if toA { points[p] += len(a); } else { points[p] += len(b); }
    if toA { a = [c]; } else { b = [c]; }
  } else if toA && len(a) == 5 {
    points[p] += 5;
    a = [c];
  } else if toB && len(b) == 5 {
    points[p] += 5;
    b = [c];
  } else if toA {
    push(a, c);
  } else {
    push(b, c);
  }
}

fn play(i: int) {
  if turn == 5 { return; }
  let c = mine[i];
  let d = its[turn];
  remove(mine, i);
  turn += 1;
  if c < d {
    put(0, c);
    put(1, d);
  } else {
    put(1, d);
    put(0, c);
  }
  if turn == 5 && points[0] < points[1] { result = "You win!"; }
  if turn == 5 && points[0] > points[1] { result = "The computer wins"; }
  if turn == 5 && points[0] == points[1] { result = "A tie"; }
}

fn cards(r: [int]) -> string {
  let s = "";
  for k in 0..len(r) { s = s + " " + r[k]; }
  return s;
}

