// Mappy: left and right walk the floor, up and down bounce on a trampoline to the next floor (each
// lasts 3 bounces). Take the 4 stolen things and keep away from the cats, over two levels.
// icon: ring 12 13 6 dot 7 6 3 dot 17 6 3 line 4 21 20 21
state mx = 4;                  // Mappy
state my = 4;
state things = [true, true, true, true];
state tx = [1, 7, 2, 6];
state ty = [0, 0, 2, 4];
state bounces = [3, 3, 3, 3, 3, 3];   // the trampolines at columns 0, 4, 8 of row 1, then row 3
state cx = [0; 0];             // the cats: column, row, way
state cy = [0; 0];
state cd = [0; 0];
state score = 0;
state lives = 3;
state level = 1;
state speed = 0;               // ms a cat step; 0 while no game runs
state result = "";

fn begin() {
  mx = 4;
  my = 4;
  things = [true, true, true, true];
  bounces = [3, 3, 3, 3, 3, 3];
  cx = [8, 0];
  cy = [2, 0];
  cd = [-1, 1];
  if level == 2 {
    push(cx, 0);
    push(cy, 4);
    push(cd, 1);
  }
}

fn start() {
  score = 0;
  lives = 3;
  level = 1;
  result = "";
  begin();
  speed = 500;
}

fn caught() {
  for k in 0..len(cx) {
    if speed > 0 && cx[k] == mx && cy[k] == my {
      lives -= 1;
      mx = 4;
      my = 4;
      if lives == 0 {
        result = "Game over";
        speed = 0;
      }
    }
  }
}

fn grab() {
  let left = 0;
  for i in 0..4 {
    if things[i] && tx[i] == mx && ty[i] == my {
      things[i] = false;
      score += 100;
    }
    if things[i] { left += 1; }
  }
  if left == 0 && level == 2 {
    result = "You win";
    speed = 0;
  } else if left == 0 {
    level = 2;
    begin();
  }
}

fn walk(d: int) {
  if speed == 0 { return; }
  mx = min(8, max(0, mx + d));
  caught();
  grab();
}

// Up (-1) or down (1) a floor at a trampoline column.
fn bounce(d: int) {
  if speed == 0 || mx % 4 != 0 || my + 2 * d < 0 || my + 2 * d > 4 { return; }
  let t = mx / 4 + 3 * ((my + d) / 2);
  if bounces[t] == 0 { return; }
  bounces[t] -= 1;
  my += 2 * d;
  caught();
  grab();
}

every speed {
  for k in 0..len(cx) {
    if cx[k] + cd[k] < 0 || cx[k] + cd[k] > 8 { cd[k] = -cd[k]; }
    cx[k] += cd[k];
  }
  caught();
}

on key "left" { walk(-1); }
on key "right" { walk(1); }
on key "up" { bounce(-1); }
on key "down" { bounce(1); }

fn scene() {
  let cells = [-1; 45];
  let tint = [-1, 5, 2, 6];
  for t in 0..6 { cells[(1 + 2 * (t / 3)) * 9 + 4 * (t % 3)] = tint[bounces[t]]; }
  for i in 0..4 {
    if things[i] { cells[ty[i] * 9 + tx[i]] = 3; }
  }
  for k in 0..len(cx) { cells[cy[k] * 9 + cx[k]] = 1; }
  cells[my * 9 + mx] = 4;
  pixels(cells, 0, 0, 9, 12);
  if result != "" { text(result, 54, 30, 12, 11); }
}

