fn drafting(i: int) -> bool {
  for j in 0..3 {
    if j != i && pos[j] == pos[i] + 1 { return true; }
  }
  return false;
}

every speed {
  let moves = [1, 1, 1];
  for i in 0..3 {
    let cost = 2;
    if drafting(i) { cost = 1; }
    let wants = (i == 0 && sprint) || (i == 1 && drafting(1)) || i == 2;
    if wants && energy[i] >= cost {
      energy[i] -= cost;
      moves[i] = 2;
    } else {
      energy[i] = min(10, energy[i] + 1);
    }
  }
  let done = 0;
  for i in 0..3 {
    pos[i] = min(23, pos[i] + moves[i]);
    if pos[i] == 23 { done += 1; }
  }
  if done > 1 {
    result = "A tie";
  } else if pos[0] == 23 {
    result = "You win";
  } else if pos[1] == 23 {
    result = "Red wins";
  } else if pos[2] == 23 {
    result = "Blue wins";
  }
  if result != "" { speed = 0; }
}

