// top man, straight from the middle, down from the bottom. First to 3 goals against the computer.
// icon: line 3 12 21 12 dot 8 6 3 dot 16 18 3 dot 12 12 2
state me = 2;                  // my rod's top man's row (column 3); men 2 rows apart
state ai = 2;                  // the computer's (column 7)
state bx = 5;                  // the ball, and its way
state by = 4;
state dx = -1;
state dy = 0;
state you = 0;
state cpu = 0;
state steps = 0;
state speed = 0;               // ms a step; 0 while no game runs
state result = "";

fn serve(d: int) {
  bx = 5;
  by = 4;
  dx = d;
  dy = 0;
}

fn start() {
  me = 2;
  ai = 2;
  you = 0;
  cpu = 0;
  steps = 0;
  result = "";
  serve(-1);
  speed = 200;
}

// Which man of a rod (its top man at row top) is on row r: 0 top, 1 middle, 2 bottom, -1 none.
fn man(top: int, r: int) -> int {
  if r < top || r > top + 4 || (r - top) % 2 != 0 { return -1; }
  return (r - top) / 2;
}

fn off(r: int) -> bool { return r < 0 || r > 8; }

every speed {
  steps += 1;
  if off(by + dy) { dy = -dy; }
  let k = -1;
  if bx + dx == 3 { k = man(me, by + dy); }
  if bx + dx == 7 { k = man(ai, by + dy); }
  if k >= 0 {
    dx = -dx;
    dy = k - 1;
    if off(by + dy) { dy = -dy; }
  } else if (bx + dx == 0 || bx + dx == 10) && (by + dy < 3 || by + dy > 5) {
    dx = -dx;
  }
  bx += dx;
  by += dy;
  if bx == 0 {
    cpu += 1;
    serve(-1);
  } else if bx == 10 {
    you += 1;
    serve(1);
  }
  if you == 3 { result = "You win"; }
  if cpu == 3 { result = "You lose"; }
  if result != "" {
    speed = 0;
  } else if steps % 2 == 0 && by + dy < ai + 2 {
    ai = max(0, ai - 1);
  } else if steps % 2 == 0 && by + dy > ai + 2 {
    ai = min(4, ai + 1);
  }
