// Knife Hit: the log turns; space or Throw sticks a knife in the slot facing you. Hit a knife
// already there and the game is over. Two levels; an apple is worth 5 more.
// icon: ring 12 9 7 line 12 13 12 22 line 9 22 15 22
state stuck = [false; 12];     // the slots holding a knife
state apple = -1;              // the apple's slot, -1 when there is none
state facing = 0;              // the slot that faces me
state level = 1;
state knives = 5;
state score = 0;
state ticks = 0;               // 100 ms ticks since the level began
state speed = 0;               // 100 while a game runs, else 0
state result = "";

fn begin(lv: int) {
  level = lv;
  facing = 0;
  ticks = 0;
  stuck = [false; 12];
  apple = -1;
  knives = 5;
  if lv == 2 {
    knives = 7;
    stuck[3] = true;
    stuck[6] = true;
    stuck[9] = true;
    apple = 2;
  }
}

fn start() {
  score = 0;
  result = "";
  speed = 100;
  begin(1);
}

every speed {
  ticks += 1;
  if level == 1 && ticks % 2 == 0 { facing = (facing + 1) % 12; }
  if level == 2 { facing = (facing + 11) % 12; }
}

fn throw() {
  if speed == 0 { return; }
  if stuck[facing] {
    result = "Game over";
    speed = 0;
    return;
  }
  stuck[facing] = true;
  score += 1;
  if facing == apple {
    score += 5;
    apple = -1;
  }
  knives -= 1;
  if knives == 0 && level == 1 {
    begin(2);
  } else if knives == 0 {
    result = "You win";
    speed = 0;
  }
}

on key "space" { throw(); }

// Where slot s is, r units out from the log's middle (80, 50); the facing slot is at the bottom.
fn px(s: int, r: int) -> int { return 80 - r * sin((s - facing) * 30) / 1000; }
fn py(s: int, r: int) -> int { return 50 + r * cos((s - facing) * 30) / 1000; }

fn scene() {
  for s in 0..12 {
    if stuck[s] { line(px(s, 20), py(s, 20), px(s, 44), py(s, 44), 2, 7); }
    if s == apple { circle(px(s, 30), py(s, 30), 5, 1); }
  }
  circle(80, 50, 26, 3);
  if speed > 0 { line(80, 100, 80, 116, 2, 9); }
  text(result, 80, 50, 12, 11);
}

label "Knife Hit";
label "Level: " + level + "   Slot: " + facing + "   Knives: " + knives + "   Score: " + score;
