// Azul, two rounds alone: tap a tile in the market to take all of its color there, then a row of
// your board to lay them in its pattern line (or Floor). Full lines go to the wall and score.
// icon: fill 3 3 11 3 11 11 3 11 fill 13 3 21 3 21 11 13 11 fill 3 13 11 13 11 21 3 21 fill 13 13 21 13 21 21 13 21
state order = [4, 3, 1, 5, 6];           // blue, yellow, red, purple, cyan: the wall's first row
state rounds = [4, 4, 1, 3, 1, 1, 6, 1, 5, 3, 4, 3, 6, 6, 4, 5, 3, 1, 1, 4, 5, 5, 6, 3];
state fac = [4, 4, 1, 3, 1, 1, 6, 1, 5, 3, 4, 3];   // three factories of four (0: taken)
state center = [0; 0];
state lineColor = [0, 0, 0, 0, 0];
state lineCount = [0, 0, 0, 0, 0];
state wall = [0; 25];                    // row * 5 + column, its tile's color (0: none)
state holdColor = 0;
state holdCount = 0;
state round = 1;
state score = 0;
state floor = 0;
state over = false;

fn deal() {
  for i in 0..12 { fac[i] = rounds[(round - 1) * 12 + i]; }
  center = [0; 0];
}

fn newgame() {
  round = 1;
  deal();
  lineColor = [0, 0, 0, 0, 0];
  lineCount = [0, 0, 0, 0, 0];
  wall = [0; 25];
  holdCount = 0;
  score = 0;
  floor = 0;
  over = false;
}

// The wall's column for color k in row r: each row is the one above turned one to the right.
fn slot(r: int, k: int) -> int {
  for i in 0..5 {
    if order[i] == k { return (i + r) % 5; }
  }
  return 0;
}

fn market() -> [int] {
  let m = [0; 36];
  for i in 0..12 { m[(i / 4) * 9 + i % 4] = fac[i]; }
  for j in 0..len(center) { m[27 + j] = center[j]; }
  return m;
}

fn board() -> [int] {
  let b = [0; 50];
  for r in 0..5 {
    for i in 0..lineCount[r] { b[r * 10 + 4 - i] = lineColor[r]; }
    for c in 0..5 { b[r * 10 + 5 + c] = wall[r * 5 + c]; }
  }
  return b;
}

fn take(c: int, r: int) {
  if holdCount > 0 || over { return; }
  let m = market();
  let k = m[r * 9 + c];
  if k == 0 { return; }
  let n = 0;
  if r < 3 {
    for j in 0..4 {
      let t = fac[r * 4 + j];
      if t == k { n += 1; } else if t != 0 { push(center, t); }
      fac[r * 4 + j] = 0;
    }
  } else {
    let i = len(center) - 1;
    while i >= 0 {
      if center[i] == k {
        remove(center, i);
        n += 1;
      }
      i -= 1;
    }
  }
  holdColor = k;
  holdCount = n;
}

// How many tiles run from (r, c) on the wall one way, (dr, dc), not counting it.
fn run(r: int, c: int, dr: int, dc: int) -> int {
  let n = 0;
  let y = r + dr;
  let x = c + dc;
  while y >= 0 && y < 5 && x >= 0 && x < 5 && wall[y * 5 + x] != 0 {
    n += 1;
    y += dr;
    x += dc;
  }
  return n;
}

fn points(r: int, c: int) -> int {
  let h = 1 + run(r, c, 0, -1) + run(r, c, 0, 1);
  let v = 1 + run(r, c, -1, 0) + run(r, c, 1, 0);
  let p = 0;
  if h > 1 { p += h; }
  if v > 1 { p += v; }
  return max(p, 1);
}

// When the market is empty: full lines tile the wall, from the top; then the next round.
fn finish() {
  for i in 0..12 {
    if fac[i] != 0 { return; }
  }
  if len(center) > 0 { return; }
  let gained = 0;
  for r in 0..5 {
    if lineCount[r] == r + 1 {
      let c = slot(r, lineColor[r]);
      wall[r * 5 + c] = lineColor[r];
      lineCount[r] = 0;
      gained += points(r, c);
    }
  }
  score = max(0, score + gained - floor);
  floor = 0;
  if round == 2 {
    over = true;
  } else {
    round = 2;
    deal();
  }
}

fn place(r: int) {
  let k = holdColor;
  let n = lineCount[r];
  if holdCount == 0 || (n > 0 && lineColor[r] != k) || n == r + 1 || wall[r * 5 + slot(r, k)] != 0 { return; }
  let put = min(r + 1 - n, holdCount);
  lineColor[r] = k;
  lineCount[r] = n + put;
  floor += holdCount - put;
  holdCount = 0;
  finish();
}

label "Azul";
label "Round: " + round + "   Score: " + score + "   Floor: " + floor + "   Holding: " + holdCount;
if over { label "Game over"; }
grid 9, market() { take(cell % 9, cell / 9); }
grid 10, board() { place(cell / 10); }
row {
  button "Floor" {
    if holdCount > 0 {
      floor += holdCount;
      holdCount = 0;
      finish();
    }
  }
  button "New game" { newgame(); }
}

// Azul wall: press 1 to 5 to lay the next tile in that row, on its color's spot. A tile scores
// its runs across and down (those longer than 1), or 1 alone.
// icon: fill 3 3 11 3 11 11 3 11 fill 13 3 21 3 21 11 13 11 fill 3 13 11 13 11 21 3 21 fill 13 13 21 13 21 21 13 21
state colors = [4, 3, 1, 5, 6];          // blue, yellow, red, purple, cyan: the top row
state names = ["Blue", "Yellow", "Red", "Purple", "Cyan"];
state tiles = [0, 2, 0, 1, 4, 3, 2, 0, 1, 2, 3, 4];
state next = 0;
state wall = [-1; 25];
state score = 0;

// How many tiles run from (r, c) one way, (dr, dc), not counting it.
fn run(r: int, c: int, dr: int, dc: int) -> int {
  let n = 0;
  let y = r + dr;
  let x = c + dc;
  while y >= 0 && y < 5 && x >= 0 && x < 5 && wall[y * 5 + x] >= 0 {
    n += 1;
    y += dr;
    x += dc;
  }
  return n;
}

fn lay(r: int) {
  if next == len(tiles) { return; }
  let c = (tiles[next] + r) % 5;
  if wall[r * 5 + c] >= 0 { return; }
  wall[r * 5 + c] = colors[tiles[next]];
  let h = 1 + run(r, c, 0, -1) + run(r, c, 0, 1);
  let v = 1 + run(r, c, -1, 0) + run(r, c, 1, 0);
  let p = 0;
  if h > 1 { p += h; }
  if v > 1 { p += v; }
  score += max(p, 1);
  next += 1;
}

on key "1" { lay(0); }
on key "2" { lay(1); }
on key "3" { lay(2); }
on key "4" { lay(3); }
on key "5" { lay(4); }

// Each spot shows its color faintly as a dot until a tile covers it.
fn scene() {
  for i in 0..25 {
    let x = (i % 5) * 20;
