// Warlords: a fireball bounces round four castles; left and right slide your blue shield round
// your castle (bottom left). Bricks break, kings die; be the last king standing.
// icon: fill 3 21 3 13 7 13 7 17 11 17 11 21 dot 17 7 3 line 13 11 9 15
state kings = [110, 0, 10, 120];   // each warlord's king's square: mine, then top left, right, bottom right
state alive = [true, true, true, true];
state paths = [77, 78, 79, 80, 91, 102, 113, 33, 34, 35, 36, 25, 14, 3, 43, 42, 41, 40, 29, 18, 7, 87, 86, 85, 84, 95, 106, 117];
state at = [3, 3, 3, 3];       // each shield's place on its castle's L of 7 squares
state way = [1, 1, 1, 1];      // the computer shields' way along their L
state bricks = [false; 121];
state bx = 5;                  // the fireball, and its way
state by = 5;
state dx = 1;
state dy = -1;
state speed = 0;               // ms a step; 0 while no game runs
state result = "";

fn start() {
  bricks = [false; 121];
  for k in 0..4 {
    let cx = kings[k] % 11;
    let cy = kings[k] / 11;
    for i in 0..3 {
      for j in 0..3 { bricks[(cy + (cy == 0 ? j : -j)) * 11 + cx + (cx == 0 ? i : -i)] = true; }
    }
    bricks[kings[k]] = false;
  }
  alive = [true, true, true, true];
  at = [3, 3, 3, 3];
  way = [1, 1, 1, 1];
  bx = 5;
  by = 5;
  dx = 1;
  dy = -1;
  result = "";
  speed = 150;
}

fn shield(k: int) -> int { return paths[k * 7 + at[k]]; }

fn foes() -> int {
  let n = 0;
  for k in 1..4 {
    if alive[k] { n += 1; }
  }
  return n;
}

// What the fireball would hit on square i: a brick (it breaks), a shield, or a king (he dies).
fn hit(i: int) -> bool {
  if bricks[i] {
    bricks[i] = false;
    return true;
  }
  for k in 0..4 {
    if alive[k] && shield(k) == i { return true; }
    if alive[k] && kings[k] == i {
      alive[k] = false;
      return true;
    }
  }
  return false;
}

every speed {
  if bx + dx < 0 || bx + dx > 10 { dx = -dx; }
  if by + dy < 0 || by + dy > 10 { dy = -dy; }
  if hit((by + dy) * 11 + bx + dx) {
    dy = -dy;
  } else {
    bx += dx;
    by += dy;
  }
  if !alive[0] {
    result = "Game over";
    speed = 0;
  } else if foes() == 0 {
    result = "You win";
    speed = 0;
  } else {
    for k in 1..4 {
      if at[k] + way[k] < 0 || at[k] + way[k] > 6 { way[k] = -way[k]; }
      at[k] += way[k];
    }
  }
}

fn slide(d: int) {
  if speed > 0 { at[0] = min(6, max(0, at[0] + d)); }
}

on key "left" { slide(-1); }
on key "right" { slide(1); }

fn scene() {
  let cells = [-1; 121];
  for i in 0..121 {
    if bricks[i] { cells[i] = 3; }
  }
  for k in 0..4 {
    if alive[k] {
      cells[kings[k]] = 2;
      cells[shield(k)] = k == 0 ? 4 : 1;
    }
  }
  cells[by * 11 + bx] = 5;
  pixels(cells, 0, 0, 11, 10);
  if result != "" { text(result, 55, 55, 14, 11); }
}

label "Warlords";
label "Foes: " + foes();
