// Warlords for two: w and s move the left shield, up and down the right one. The fireball breaks
// bricks and bounces back off anything it meets; hit the other king to win.
// icon: fill 3 21 3 13 7 13 7 17 11 17 11 21 dot 17 7 3 line 13 11 9 15
state bricks = [false; 63];
state shields = [3, 3];        // the left and right shields' rows (columns 2 and 6)
state bx = 4;
state by = 3;
state dx = 1;
state dy = -1;
state speed = 0;               // 200 while the fireball flies
state winner = "";

fn start() {
  bricks = [false; 63];
  for r in 2..5 {
    bricks[r * 9 + 1] = true;
    bricks[r * 9 + 7] = true;
  }
  shields = [3, 3];
  bx = 4;
  by = 3;
  dx = 1;
  dy = -1;
  winner = "";
  speed = 200;
}

// Whether the fireball meets something on (x, y): a brick breaks, a king ends the game.
fn meets(x: int, y: int) -> bool {
  if bricks[y * 9 + x] {
    bricks[y * 9 + x] = false;
    return true;
  }
  if y == 3 && x == 0 { winner = "Right wins!"; }
  if y == 3 && x == 8 { winner = "Left wins!"; }
  return winner != "" || (x == 2 && y == shields[0]) || (x == 6 && y == shields[1]);
}

every speed {
  if bx + dx < 0 || bx + dx > 8 { dx = -dx; }
  if by + dy < 0 || by + dy > 6 { dy = -dy; }
  if meets(bx + dx, by + dy) {
    dx = -dx;
    dy = -dy;
  } else {
    bx += dx;
    by += dy;
  }
  if winner != "" { speed = 0; }
}

fn move(p: int, d: int) {
  if speed > 0 { shields[p] = min(6, max(0, shields[p] + d)); }
}

on key "w" { move(0, -1); }
on key "s" { move(0, 1); }
on key "up" { move(1, -1); }
on key "down" { move(1, 1); }

