  }
  cells[27] = 2;
  cells[35] = 2;
  cells[shields[0] * 9 + 2] = 4;
  cells[shields[1] * 9 + 6] = 1;
  cells[by * 9 + bx] = 5;
  pixels(cells, 0, 0, 9, 10);
}

