// Super Hexagon: walls close in on the six lanes around the middle; left and right move you a lane
// round. Be in a gap when each wall reaches you. Two levels, the second twice as fast.
// icon: loop 12 3 20 7 20 17 12 21 4 17 4 7 fill 12 9 14 13 10 13
state bits = [1, 2, 4, 8, 16, 32];
state gaps = [28, 33, 2, 24, 1, 4, 16, 2, 8, 32, 4, 1, 8, 2];   // each wall's open lanes, as bits
state lane = 0;
state level = 1;
state passed = 0;
state step = 0;                // steps this level
state sent = 0;                // walls sent this level
state wd = [0; 0];             // the walls on their way: distance (5 to 1) and open lanes
state wg = [0; 0];
state speed = 0;               // ms a step; 0 while no game runs
state result = "";

fn count() -> int { return level == 1 ? 6 : 8; }

fn open(g: int, l: int) -> bool { return g / bits[l] % 2 == 1; }

fn start() {
  lane = 0;
  level = 1;
  passed = 0;
  step = 0;
  sent = 0;
  wd = [0; 0];
  wg = [0; 0];
  result = "";
  speed = 200;
}

every speed {
  step += 1;
  let i = 0;
  while i < len(wd) {
    wd[i] -= 1;
    if wd[i] > 0 {
      i += 1;
    } else if open(wg[i], lane) {
      passed += 1;
      remove(wd, i);
      remove(wg, i);
    } else {
      result = "Game over";
      speed = 0;
      return;
    }
  }
  if sent == count() && len(wd) == 0 {
    if level == 2 {
      result = "You win";
      speed = 0;
    } else {
      level = 2;
      step = 0;
      sent = 0;
      speed = 100;
    }
  } else if sent < count() && step % 3 == 1 {
    push(wd, 5);
    push(wg, gaps[(level - 1) * 6 + sent]);
    sent += 1;
  }
}

fn turn(d: int) {
  if speed > 0 { lane = (lane + d + 6) % 6; }
}

on key "left" { turn(-1); }
on key "right" { turn(1); }

// A point a degrees clockwise from the top, r units out from the middle.
fn ax(a: int, r: int) -> int { return 80 + r * sin(a) / 1000; }
fn ay(a: int, r: int) -> int { return 60 - r * cos(a) / 1000; }

// A side of the hexagon r units out across lane l.
fn side(l: int, r: int, w: int, c: int) {
  line(ax(l * 60 - 30, r), ay(l * 60 - 30, r), ax(l * 60 + 30, r), ay(l * 60 + 30, r), w, c);
}

fn scene() {
  for l in 0..6 {
    side(l, 10, 2, 9);
    for i in 0..len(wd) {
      if !open(wg[i], l) { side(l, 8 + wd[i] * 10, 4, 11); }
    }
  }
  circle(ax(lane * 60, 15), ay(lane * 60, 15), 3, 4);
}

