// A point a degrees clockwise from the top, r units from the middle.
fn ax(a: int, r: int) -> int { return 60 + r * sin(a) / 1000; }
fn ay(a: int, r: int) -> int { return 60 - r * cos(a) / 1000; }

// Each wall on its way, a ring with its gap cut out, closing in; you, a dot by the middle.
