  } else {
    mx = [0, 6];
    my = [4, 0];
    md = [0, 3];
    out = [true, true];
  }
  speed = 0;
  steps = 0;
  saved = 0;
}

fn begin(lv: int) {
  level = lv;
  cells = [0; 35];
  if lv == 1 {
    cells[9] = 5;
    cells[18] = 2;
    cells[22] = 1;
    cells[34] = 1;
    left = 2;
  } else {
    cells[10] = 5;
    cells[23] = 5;
    cells[25] = 5;
    cells[17] = 2;
    cells[0] = 1;
    cells[34] = 1;
    left = 2;
  }
  arrows = [-1; 35];
  home();
}

fn blocked(c: int, r: int) -> bool { return c < 0 || c > 6 || r < 0 || r > 4 || cells[r * 7 + c] == 5; }

// A mouse's step: an arrow turns it; a wall or edge turns it right, else left, else back.
fn walk(i: int) {
  let d = md[i];
  if arrows[my[i] * 7 + mx[i]] >= 0 { d = arrows[my[i] * 7 + mx[i]]; }
  let k = 0;
  let tries = [0, 1, 3, 2];
  while blocked(mx[i] + wx[(d + tries[k]) % 4], my[i] + wy[(d + tries[k]) % 4]) && k < 3 { k += 1; }
  d = (d + tries[k]) % 4;
  md[i] = d;
  mx[i] += wx[d];
  my[i] += wy[d];
}

every speed {
  steps += 1;
  for i in 0..len(mx) {
    if out[i] && note == "" {
      walk(i);
      let at = cells[my[i] * 7 + mx[i]];
      if at == 2 {
        out[i] = false;
        saved += 1;
      } else if at == 1 {
        note = "Try again";
      }
    }
  }
  if saved == len(mx) && level == 1 {
    begin(2);
  } else if saved == len(mx) {
    note = "You win";
    speed = 0;
  } else if note != "" || steps == 30 {
    note = "Try again";
    home();
  }
}

fn tap(c: int, r: int) {
  let i = r * 7 + c;
  if speed > 0 || note == "You win" || cells[i] != 0 { return; }
  if arrows[i] < 0 && left == 0 { return; }
  if arrows[i] < 0 { left -= 1; }
  arrows[i] = way;
}

fn scene() {
  let b = [0; 35];
  for i in 0..35 {
    b[i] = cells[i];
    if arrows[i] >= 0 { b[i] = 4; }
  }
  for i in 0..len(mx) {
    if out[i] { b[my[i] * 7 + mx[i]] = 3; }
  }
  pixels(b, 0, 0, 7, 20);
  for i in 0..35 {
    let a = arrows[i];
    if a >= 0 && b[i] == 4 { line(i % 7 * 20 + 10 + wx[a] * 4, i / 7 * 20 + 10 + wy[a] * 4, i % 7 * 20 + 10 + wx[a] * 8, i / 7 * 20 + 10 + wy[a] * 8, 2, 9); }
  }
}

on key "up" { way = 0; }
on key "right" { way = 1; }
on key "down" { way = 2; }
on key "left" { way = 3; }

label "ChuChu Rocket";
label "Level: " + level + "   Arrows: " + left + "   Saved: " + saved + "   Way: " + ways[way];
label note;
canvas 140, 100, scene() { tap(x / 20, y / 20); }
row {
  if speed == 0 && note != "You win" {
    button "Go" {
      note = "";
      home();
      speed = 250;
    }
    button "Clear" {
      for i in 0..35 {
        if arrows[i] >= 0 { left += 1; }
      }
      arrows = [-1; 35];
    }
