  }
}

// ChuChu Rocket: press an arrow key, tap squares to lay up to 3 arrows, then Go. The mouse turns
// at arrows and turns right at the edge; get it into the rocket within 20 seconds.
// icon: fill 12 2 17 9 17 18 7 18 7 9 fill 7 18 4 22 9 20 fill 17 18 20 22 15 20 dot 12 10 2
state wx = [0, 1, 0, -1];      // up, right, down, left
state wy = [-1, 0, 1, 0];
state arrows = [-1; 36];       // each square's arrow way, -1 for none
state laid = 0;
state way = 0;
state mx = 0;
state my = 0;
state md = 1;
state steps = 0;
state speed = 0;               // 500 while the mouse runs
state result = "";

fn reset() {
  arrows = [-1; 36];
  laid = 0;
  mx = 0;
  my = 0;
  md = 1;
  steps = 0;
  speed = 0;
  result = "";
}

fn off(x: int, y: int) -> bool { return x < 0 || x > 5 || y < 0 || y > 5; }

every speed {
  for k in 0..3 {
    if off(mx + wx[md], my + wy[md]) { md = (md + 1) % 4; }
  }
  mx += wx[md];
  my += wy[md];
  steps += 1;
  if arrows[my * 6 + mx] >= 0 { md = arrows[my * 6 + mx]; }
  if mx == 3 && my == 3 {
    result = "You win!";
    speed = 0;
  } else if steps == 40 {
    result = "Time's up: you lose";
    speed = 0;
  }
}

on key "up" { way = 0; }
on key "right" { way = 1; }
on key "down" { way = 2; }
on key "left" { way = 3; }

fn lay(i: int) {
  if speed > 0 || result != "" || i == 21 { return; }
  if arrows[i] < 0 && laid == 3 { return; }
  if arrows[i] < 0 { laid += 1; }
  arrows[i] = way;
}

// The board: the rocket green, the mouse yellow, each arrow a stroke from a square's middle.
fn scene() {
  let b = [0; 36];
  b[21] = 2;
  b[my * 6 + mx] = 3;
  pixels(b, 0, 0, 6, 20);
  for i in 0..36 {
    let cx = i % 6 * 20 + 10;
    let cy = i / 6 * 20 + 10;
    if arrows[i] >= 0 { line(cx, cy, cx + wx[arrows[i]] * 8, cy + wy[arrows[i]] * 8, 3, 4); }
  }
}

label "ChuChu Rocket";
label result;
canvas 120, 120, scene() { lay(y / 20 * 6 + x / 20); }
row {
  if speed == 0 && result == "" { button "Go" { speed = 500; } }
  button "Reset" { reset(); }
}

// Lost Cities against the computer: tap a card to lay it on its expedition (each card higher than
// the last), or Discard then a card. Each expedition scores its cards minus 20.
// icon: line 3 21 8 9 12 15 16 5 21 21 dot 16 4 2
state colors = ["Red", "Green", "Blue"];
state hand = ["Red 4", "Red 7", "Blue 5", "Blue 8", "Green 6"];
state theirs = ["Red 2", "Green 3", "Green 9", "Blue 3", "Blue 10"];
state deck = ["Red 9", "Blue 6", "Green 4", "Red 10", "Blue 9", "Green 7", "Red 3", "Blue 2", "Green 10", "Red 5", "Blue 7", "Green 2"];
state laid = ["", "", ""];     // my expeditions' cards, as text
state tops = [0, 0, 0];        // each expedition's last card (0: none yet), mine then the computer's
state sums = [0, 0, 0];
state ctops = [0, 0, 0];
state csums = [0, 0, 0];
state discarding = false;

fn color(c: string) -> int {
  for k in 0..3 {
    if c[0] == colors[k][0] { return k; }
  }
  return 0;
}

fn number(c: string) -> int {
  let n = 0;
  for i in 0..len(c) {
    let d = parse(c[i], -1);
    if d >= 0 { n = n * 10 + d; }
  }
  return n;
}

fn score(s: [int]) -> int {
  let t = 0;
  for k in 0..3 {
    if s[k] > 0 { t += s[k] - 20; }
  }
  return t;
}

fn deal() {
  hand = ["Red 4", "Red 7", "Blue 5", "Blue 8", "Green 6"];
  theirs = ["Red 2", "Green 3", "Green 9", "Blue 3", "Blue 10"];
  deck = ["Red 9", "Blue 6", "Green 4", "Red 10", "Blue 9", "Green 7", "Red 3", "Blue 2", "Green 10", "Red 5", "Blue 7", "Green 2"];
  laid = ["", "", ""];
  tops = [0, 0, 0];
  sums = [0, 0, 0];
  ctops = [0, 0, 0];
  csums = [0, 0, 0];
  discarding = false;
}

// A card's order: by number, then Red, Green, Blue.
fn rank(c: string) -> int { return number(c) * 3 + color(c); }

// The computer lays the lowest card it can, else discards its lowest; then it draws.
fn computer() {
  let best = -1;
  let low = 0;
  for i in 0..len(theirs) {
    let c = theirs[i];
    if number(c) > ctops[color(c)] && (best < 0 || rank(c) < rank(theirs[best])) { best = i; }
    if rank(c) < rank(theirs[low]) { low = i; }
  }
  if best >= 0 {
    let k = color(theirs[best]);
    ctops[k] = number(theirs[best]);
    csums[k] += ctops[k];
    low = best;
  }
  remove(theirs, low);
  push(theirs, deck[0]);
  remove(deck, 0);
}

fn tap(i: int) {
  let k = color(hand[i]);
  let n = number(hand[i]);
  if len(deck) == 0 || (!discarding && n <= tops[k]) { return; }
  if !discarding {
    tops[k] = n;
    sums[k] += n;
    laid[k] = laid[k] + " " + n;
  }
  discarding = false;
  remove(hand, i);
  push(hand, deck[0]);
  remove(deck, 0);
  if len(deck) > 0 { computer(); }
}

fn result() -> string {
  if len(deck) > 0 { return ""; }
  if score(sums) > score(csums) { return "You win"; }
  if score(sums) < score(csums) { return "You lose"; }
  return "Tie";
}

label "Lost Cities";
label "You: " + score(sums) + "   Computer: " + score(csums) + "   Deck: " + len(deck);
label "Red:" + laid[0] + "   Green:" + laid[1] + "   Blue:" + laid[2];
label result();
row {
  for i in 0..len(hand) { button hand[i] { tap(i); } }
}
row {
  button "Discard" { discarding = true; }
  button "New game" { deal(); }
}
if discarding { label "Tap a card to discard it"; }

// Lost Cities solitaire: Play lays the card on its color's expedition (numbers going up, wagers
// first), Discard throws it away. Each expedition: (its numbers - 20) x (1 + its wagers).
// icon: line 3 21 8 9 12 15 16 5 21 21 dot 16 4 2
state deck = ["Blue wager", "Red 4", "Blue wager", "Red 2", "Blue 6", "Green 7", "Red wager", "Blue 9", "Red 8", "Blue 10", "Red 10", "Green 3"];
state colors = ["Red", "Green", "Blue"];
state next = 0;                // the card on offer
state laid = ["", "", ""];     // each expedition's cards, as text
state last = [0, 0, 0];        // its last number (0: none yet)
state sums = [0, 0, 0];
state wagers = [0, 0, 0];

fn color(c: string) -> int {
  for k in 0..3 {
    if c[0] == colors[k][0] { return k; }
  }
  return 0;
}

fn number(c: string) -> int {
  let n = 0;
  for i in 0..len(c) {
    let d = parse(c[i], -1);
    if d >= 0 { n = n * 10 + d; }
  }
  return n;
}

fn score() -> int {
  let t = 0;
  for k in 0..3 {
    if laid[k] != "" { t += (sums[k] - 20) * (1 + wagers[k]); }
  }
  return t;
}

fn play() {
  let c = deck[next];
  let k = color(c);
  let n = number(c);
  if n == 0 && last[k] == 0 {
    wagers[k] += 1;
  } else if n > last[k] {
    last[k] = n;
    sums[k] += n;
  } else {
    return;
  }
  laid[k] = laid[k] + " " + c[0] + (n == 0 ? "W" : "" + n);
  next += 1;
}

label "Lost Cities Solitaire";
label "Score: " + score();
label "Red:" + laid[0] + "   Green:" + laid[1] + "   Blue:" + laid[2];
if next < len(deck) {
  label "Card: " + deck[next];
  row {
    button "Play" { play(); }
    button "Discard" { next += 1; }
  }
} else {
  label "Game over";
  button "Play again" {
    next = 0;
    laid = ["", "", ""];
    last = [0, 0, 0];
    sums = [0, 0, 0];
    wagers = [0, 0, 0];
  }
}

// Exploding Kittens: play Skip, Attack or Future, then Draw; a Kitten explodes you unless you hold
// a Defuse. The computer skips or attacks when a Kitten is on top.
// icon: dot 11 14 7 line 15 9 18 5 line 18 5 21 4 dot 21 3 1
state deck = ["Taco", "Kitten", "Skip", "Taco", "Future", "Kitten", "Taco", "Defuse", "Attack", "Taco"];
state mine = ["Defuse", "Skip", "Attack", "Future", "Taco"];
state theirs = ["Defuse", "Skip", "Attack"];
state turns = 1;               // my turns left in a row
state peek = "";               // what Future showed, until my turn ends
state result = "";

fn find(hand: [string], card: string) -> int {
  for i in 0..len(hand) {
    if hand[i] == card { return i; }
  }
  return -1;
}

fn holds(card: string) -> bool { return find(mine, card) >= 0; }

fn deal() {
  deck = ["Taco", "Kitten", "Skip", "Taco", "Future", "Kitten", "Taco", "Defuse", "Attack", "Taco"];
  mine = ["Defuse", "Skip", "Attack", "Future", "Taco"];
  theirs = ["Defuse", "Skip", "Attack"];
  turns = 1;
  peek = "";
  result = "";
}

fn spend(card: string) { remove(mine, find(mine, card)); }

// The computer's turns, n of them: a Kitten on top is skipped or passed on with an attack.
fn computer(n: int) {
  turns = 1;
  for k in 0..n {
    if deck[0] == "Kitten" && find(theirs, "Skip") >= 0 {
      remove(theirs, find(theirs, "Skip"));
    } else if deck[0] == "Kitten" && find(theirs, "Attack") >= 0 {
      remove(theirs, find(theirs, "Attack"));
      turns = 2;
      return;
    } else {
      let card = deck[0];
      remove(deck, 0);
      if card != "Kitten" {
        push(theirs, card);
      } else if find(theirs, "Defuse") >= 0 {
        remove(theirs, find(theirs, "Defuse"));
        insert(deck, 0, "Kitten");
      } else {
        result = "The computer exploded: you win";
        return;
      }
    }
  }
}

// One of my turns ends; when none is left the computer plays.
fn done(n: int) {
  peek = "";
  turns -= 1;
  if turns == 0 { computer(n); }
}

fn draw() {
  let card = deck[0];
  remove(deck, 0);
  if card != "Kitten" {
    push(mine, card);
  } else if holds("Defuse") {
    spend("Defuse");
    insert(deck, 0, "Kitten");
  } else {
    result = "You exploded: you lose";
    return;
  }
  done(1);
}

fn future() {
  spend("Future");
  peek = deck[0];
  for i in 1..min(3, len(deck)) { peek = peek + ", " + deck[i]; }
}

fn cards() -> string {
  let s = "";
  for i in 0..len(mine) {
    if i > 0 { s = s + ", "; }
    s = s + mine[i];
  }
  return s;
}

label "Exploding Kittens";
label "Deck: " + len(deck) + "   Hand: " + len(mine) + "   Computer: " + len(theirs);
label "Your cards: " + cards();
if peek != "" { label "Next: " + peek; }
label result;
if result == "" {
  row {
    if holds("Skip") { button "Skip" { spend("Skip"); done(1); } }
    if holds("Attack") { button "Attack" { spend("Attack"); turns = 1; done(2); } }
    if holds("Future") { button "Future" { future(); } }
    button "Draw" { draw(); }
  }
}
button "New game" { deal(); }

// Exploding Kittens for two on one phone: on your turn play your Skip or Draw; a Kitten explodes
// you unless you hold a Defuse, which sends it to the bottom of the deck.
// icon: dot 11 14 7 line 15 9 18 5 line 18 5 21 4 dot 21 3 1
state deck = ["Taco", "Kitten", "Taco", "Skip", "Kitten", "Taco", "Taco"];
state defuses = [1, 1];        // Player 1's, Player 2's
state skips = [1, 1];
state turn = 0;
state winner = "";

fn deal() {
  deck = ["Taco", "Kitten", "Taco", "Skip", "Kitten", "Taco", "Taco"];
  defuses = [1, 1];
  skips = [1, 1];
  turn = 0;
  winner = "";
}

fn draw() {
  let card = deck[0];
  remove(deck, 0);
  if card == "Skip" { skips[turn] += 1; }
  if card == "Kitten" && defuses[turn] > 0 {
    defuses[turn] = 0;
    push(deck, "Kitten");
  } else if card == "Kitten" {
    winner = "Player " + (2 - turn) + " wins!";
    return;
  }
  turn = 1 - turn;
}

label "Exploding Kittens";
if winner == "" {
  label "Player " + (turn + 1) + "'s turn";
  label "Cards in the deck: " + len(deck);
  row {
    button "Draw" { draw(); }
    if skips[turn] > 0 { button "Skip" { skips[turn] -= 1; turn = 1 - turn; } }
  }
} else {
  label winner;
  button "Play again" { deal(); }
}

// Pit stop: Start a 12 lap race; Pit, tap worn tires to change them, Fuel to fill up, Go to race
// on. A tire worn through or an empty tank ends it.
// icon: ring 12 12 9 ring 12 12 4 line 12 3 12 8 line 12 16 12 21 line 3 12 8 12 line 16 12 21 12
state lap = 0;
state fuel = 50;
state wear = [0, 0, 0, 0];      // front left, front right, rear left, rear right
state time = 0;
state speed = 0;                // ms a lap; 0 while the car is not racing
state pits = false;
state result = "";

fn worst() -> int { return max(max(wear[0], wear[1]), max(wear[2], wear[3])); }

fn hue(w: int) -> int {
  if w >= 80 { return 1; }
  if w >= 50 { return 3; }
  return 2;
}

fn tires() {
  let b = [0; 4];
  for i in 0..4 { b[i] = hue(wear[i]); }
  pixels(b, 0, 0, 2, 40);
}

fn start() {
  lap = 0;
  fuel = 50;
  wear = [0, 0, 0, 0];
  time = 0;
  result = "";
  speed = 1000;
}

fn end(what: string) {
  result = what;
  speed = 0;
}

every speed {
  lap += 1;
  fuel -= 10;
  for i in 0..4 { wear[i] += i < 2 ? 10 : 5; }
  time += 60 + worst() / 10;
  if worst() >= 100 {
    end("Puncture");
  } else if lap == 12 {
    end("Finished");
  } else if fuel == 0 {
    end("Out of fuel");
  }
}

// A tap in the pits changes the worn tire under it.
fn change(i: int) {
  if pits && wear[i] > 0 {
    wear[i] = 0;
    time += 4;
  }
}

label "Pit stop";
label "Lap " + lap + " of 12   Fuel " + fuel + "   Time " + time;
canvas 80, 80, tires() { change((y / 40) * 2 + x / 40); }
label result;
row {
  if speed == 0 && !pits { button "Start" { start(); } }
  if speed > 0 { button "Pit" { pits = true; speed = 0; } }
  if pits {
    button "Fuel" {
      if fuel < 100 {
        fuel += 10;
        time += 2;
      }
    }
    button "Go" { pits = false; speed = 1000; }
  }
}

// Pit stop: Lap drives a lap (10 fuel, 20% of the tires); Refuel and New tires in between. An
// empty tank or bald tires end it.
// icon: line 6 21 6 3 fill 6 4 19 4 15 8 19 12 6 12
state laps = 0;
state fuel = 100;
state tires = 100;
