// Harbor: Start opens it; ships arrive and wait in line; tap an empty berth to dock the next one.
// Cranes unload a crate a second each, a coin a crate. Three ships turned away close it.
// icon: line 12 3 12 19 line 7 7 17 7 arc 12 12 8 100 260 line 5 12 7 14 line 19 12 17 14
state berth = [0, 0, 0];        // crates left on the ship at each berth; 0 empty
state queue = [0; 0];           // the crates of each ship waiting, first in line first
state cargo = [3, 5, 2, 4];
state next = 0;                 // ships arrived since opening
state coins = 0;
state missed = 0;
state cranes = 1;
state t = 0;                    // seconds open
state speed = 0;                // ms a second; 0 while closed

fn arrive() {
  let c = cargo[next % 4];
  next += 1;
  if len(queue) < 3 {
    push(queue, c);
  } else {
    missed += 1;
    if missed == 3 { speed = 0; }
  }
}

fn start() {
  berth = [0, 0, 0];
  clear(queue);
  next = 0;
  coins = 0;
  missed = 0;
  cranes = 1;
  t = 0;
  speed = 1000;
  arrive();
}

every speed {
  t += 1;
  for b in 0..3 {
    let n = min(berth[b], cranes);
    berth[b] -= n;
    coins += n;
  }
  if t % 4 == 0 { arrive(); }
}

fn dock(b: int) {
  if speed > 0 && berth[b] == 0 && len(queue) > 0 {
    berth[b] = queue[0];
    remove(queue, 0);
  }
}

fn harbor() {
  let b = [4, 4, 4];
  for i in 0..3 {
    if berth[i] > 0 { b[i] = 1; }
  }
  pixels(b, 0, 0, 3, 40);
  if missed == 3 { text("Closed", 60, 20, 12, 9); }
}

label "Harbor";
label "Waiting " + len(queue) + "   Coins " + coins + "   Missed " + missed + "   Cranes " + cranes;
