// Rampart: Start, then build: tap to lay a 3 square wall (Turn: right or down) before the time
// runs out. Walled in, your castle scores its land, then the enemy fires 5 shots at your walls.
// icon: fill 3 21 3 8 7 8 7 12 10 12 10 8 14 8 14 12 17 12 17 8 21 8 21 21
state walls = [0; 100];
state down = false;
state round = 0;
state time = 0;
state score = 0;
state battle = false;
state shots = 0;
state over = false;
state speed = 0;                // ms a second; 0 while no game is on

fn at(c: int, r: int) -> int { return r * 10 + c; }

// The squares walled in with the castle (at square 64), castle included; none if a path of
// squares without walls leads out to the edge.
fn inside() -> [bool] {
  let seen = [false; 100];
  let todo = [64];
  seen[64] = true;
  let k = 0;
  while k < len(todo) {
    let i = todo[k];
    k += 1;
    let c = i % 10;
    let r = i / 10;
    if c == 0 || c == 9 || r == 0 || r == 9 { return [false; 100]; }
    let near = [i - 1, i + 1, i - 10, i + 10];
    for d in 0..4 {
      let j = near[d];
      if !seen[j] && walls[j] == 0 {
        seen[j] = true;
        push(todo, j);
      }
    }
  }
  return seen;
}

fn count(land: [bool]) -> int {
  let n = 0;
  for i in 0..100 {
    if land[i] { n += 1; }
  }
  return n;
}

fn scene() {
  let land = inside();
  let b = [0; 100];
  for i in 0..100 {
    if land[i] { b[i] = 2; }
    if walls[i] == 1 { b[i] = 1; }
  }
  b[64] = 3;
  pixels(b, 0, 0, 10, 12);
  if over { text("Game over", 60, 60, 16, 9); }
}

fn place(c: int, r: int) {
  if speed == 0 || battle { return; }
  for k in 0..3 {
    let i = down ? at(c, r + k) : at(c + k, r);
    if (down ? r + k : c + k) > 9 || walls[i] == 1 || i == 64 { return; }
  }
  for k in 0..3 { walls[down ? at(c, r + k) : at(c + k, r)] = 1; }
}

fn start() {
  walls = [0; 100];
  down = false;
  round = 1;
  time = 15;
  score = 0;
  battle = false;
  over = false;
  speed = 1000;
}

every speed {
  if battle {
    for i in 0..100 {
      if walls[i] == 1 {
        walls[i] = 0;
        break;
      }
    }
    shots += 1;
    if shots == 5 {
      battle = false;
      round += 1;
      time = 15;
    }
  } else {
    time -= 1;
    if time == 0 {
      let n = count(inside());
      if n > 0 {
        score += n;
        battle = true;
        shots = 0;
      } else {
        over = true;
        speed = 0;
      }
    }
  }
}

label "Rampart";
label "Round " + round + "   Time " + time + "   Score " + score;
canvas 120, 120, scene() { place(x / 12, y / 12); }
row {
  if speed == 0 { button "Start" { start(); } }
  button "Turn" { down = !down; }
}

// Rampart: tap squares to build walls round the castle; the clock runs until no way out is left.
// icon: fill 3 21 3 8 7 8 7 12 10 12 10 8 14 8 14 12 17 12 17 8 21 8 21 21
state walls = [0; 100];
state secs = 0;
state speed = 1000;             // ms a second; 0 once the castle is walled in

fn castle(i: int) -> bool { return i == 44 || i == 45 || i == 54 || i == 55; }

// Whether no path of squares without walls leads from the castle to the edge.
fn walled() -> bool {
  let seen = [false; 100];
  let todo = [44];
  seen[44] = true;
  let k = 0;
  while k < len(todo) {
    let i = todo[k];
    k += 1;
    if i % 10 == 0 || i % 10 == 9 || i < 10 || i >= 90 { return false; }
    let near = [i - 1, i + 1, i - 10, i + 10];
    for d in 0..4 {
      let j = near[d];
      if !seen[j] && walls[j] == 0 {
        seen[j] = true;
        push(todo, j);
      }
    }
  }
  return true;
}

fn scene() {
  let b = [0; 100];
  for i in 0..100 {
    if walls[i] == 1 { b[i] = 1; }
    if castle(i) { b[i] = 3; }
  }
  pixels(b, 0, 0, 10, 12);
}

