// Ticket to ride: Draw two cards or claim a route with cards of its color; connect Madrid to
// Vienna for 10 more. A rival claims a route of its list after each turn; 8 turns.
// icon: line 3 17 12 7 21 14 ring 3 17 2 ring 12 7 2 ring 21 14 2 line 7 20 17 20
state cities = ["Madrid", "Paris", "Berlin", "Rome", "Vienna"];
state cx = [20, 60, 120, 95, 150];
state cy = [80, 30, 20, 95, 60];
state ra = [0, 1, 2, 1, 3, 0, 2];          // each route's two cities
state rb = [1, 2, 4, 3, 4, 3, 3];
state rk = [0, 1, 0, 2, 1, 2, 0];          // its color: 0 red, 1 blue, 2 green
state rl = [3, 2, 1, 4, 2, 3, 2];          // its length
state plan = [5, 1, 2, 6, 4, 3, 0];        // the rival's list
state deck = [1, 2, 2, 0, 0, 1];
state owner = [0, 0, 0, 0, 0, 0, 0];       // 0 free, 1 yours, 2 the rival's
state hand = [1, 1, 2];
state dealt = 0;
state trains = 10;
state turn = 1;
state score = 0;
state rival = 0;
state ticket = false;

fn points(n: int) -> int { return n == 4 ? 7 : (n == 3 ? 4 : n); }

fn hue(k: int) -> int { return k == 0 ? 1 : (k == 1 ? 4 : 2); }

fn route(r: int) -> string { return cities[ra[r]] + "-" + cities[rb[r]]; }

// Whether your routes join Madrid to Vienna.
fn joined() -> bool {
  let reach = [true, false, false, false, false];
  repeat 4 {
    for r in 0..7 {
      if owner[r] == 1 && (reach[ra[r]] || reach[rb[r]]) {
        reach[ra[r]] = true;
        reach[rb[r]] = true;
      }
    }
  }
  return reach[4];
}

fn over() -> bool { return turn > 8; }

fn done() {
  if turn <= 7 {
    let r = plan[turn - 1];
    if owner[r] == 0 {
      owner[r] = 2;
      rival += points(rl[r]);
    }
  }
  turn += 1;
}

fn draw() {
  if over() { return; }
  repeat 2 {
    hand[deck[dealt % 6]] += 1;
    dealt += 1;
  }
  done();
}

fn claim(r: int) {
  let n = rl[r];
  if over() || owner[r] != 0 || hand[rk[r]] < n || trains < n { return; }
  hand[rk[r]] -= n;
  trains -= n;
  owner[r] = 1;
  score += points(n);
  if !ticket && joined() {
    ticket = true;
    score += 10;
  }
  done();
}

fn again() {
  owner = [0, 0, 0, 0, 0, 0, 0];
  hand = [1, 1, 2];
  dealt = 0;
  trains = 10;
  turn = 1;
  score = 0;
  rival = 0;
  ticket = false;
}

fn map() {
  for r in 0..7 {
    let c = owner[r] == 1 ? 5 : (owner[r] == 2 ? 8 : hue(rk[r]));
    line(cx[ra[r]], cy[ra[r]], cx[rb[r]], cy[rb[r]], owner[r] == 0 ? 2 : 4, c);
  }
  for i in 0..5 {
    circle(cx[i], cy[i], 5, 3);
    text(cities[i], cx[i], cy[i] - 10, 7, 9);
  }
}

label "Ticket to ride";
label "Turn " + min(turn, 8) + "   Score " + score + "   Rival " + rival + "   Trains " + trains;
label "Red " + hand[0] + "   Blue " + hand[1] + "   Green " + hand[2];
label "Ticket: Madrid to Vienna" + (ticket ? " (done)" : "");
canvas 170, 110, map();
button "Draw" { draw(); }
row {
  for r in 0..7 { button route(r) { claim(r); } }
}
if over() {
  label score > rival ? "You win" : "Rival wins";
  button "New game" { again(); }
}

