// Baba is you: the arrows move Baba and push word tiles; rules read across or down (WALL IS
// STOP, FLAG IS WIN). Stand on what is WIN. Undo takes a move back; Restart starts over.
// icon: fill 5 8 19 8 19 18 5 18 dot 9 12 2 dot 15 12 2 line 7 18 7 22 line 17 18 17 22
state wx = [1, 1, 1, 1, 2, 3];          // the tiles: column, row, word
state wy = [0, 1, 2, 5, 5, 5];
state ww = ["FLAG", "IS", "WIN", "WALL", "IS", "STOP"];
state bx = 2;
state by = 4;
state won = false;
state moves = 0;
state past = [0; 0];                    // before each move: Baba, then each tile's column and row

fn tile(c: int, r: int) -> int {
  for i in 0..6 {
    if wx[i] == c && wy[i] == r { return i; }
  }
  return -1;
}

fn word(c: int, r: int) -> string {
  let i = tile(c, r);
  return i < 0 ? "" : ww[i];
}

// Whether three tiles, across or down, read thing IS prop.
fn rule(thing: string, prop: string) -> bool {
  for i in 0..6 {
    if ww[i] == "IS" {
      if word(wx[i] - 1, wy[i]) == thing && word(wx[i] + 1, wy[i]) == prop { return true; }
      if word(wx[i], wy[i] - 1) == thing && word(wx[i], wy[i] + 1) == prop { return true; }
    }
  }
  return false;
}

// Whether a thing at (c, r) is prop: the walls fill column 5, the flag is at (7, 3).
fn has(c: int, r: int, prop: string) -> bool {
  return (c == 5 && rule("WALL", prop)) || (c == 7 && r == 3 && rule("FLAG", prop));
}

fn on(c: int, r: int) -> bool { return c >= 0 && c < 9 && r >= 0 && r < 7; }

fn save() {
  push(past, bx);
  push(past, by);
  for i in 0..6 {
    push(past, wx[i]);
    push(past, wy[i]);
  }
}

fn go(dx: int, dy: int) {
  let c = bx + dx;
  let r = by + dy;
  if won || !on(c, r) || has(c, r, "STOP") { return; }
  let n = 0;
  while tile(c + n * dx, r + n * dy) >= 0 { n += 1; }
  let ec = c + n * dx;
  let er = r + n * dy;
  if n > 0 && (!on(ec, er) || has(ec, er, "STOP")) { return; }
  save();
  for k in 0..n {
    let i = tile(c + (n - 1 - k) * dx, r + (n - 1 - k) * dy);
    wx[i] += dx;
    wy[i] += dy;
  }
  bx = c;
  by = r;
  moves += 1;
  won = has(bx, by, "WIN");
}

fn undo() {
  if won || moves == 0 { return; }
  let b = len(past) - 14;
  bx = past[b];
  by = past[b + 1];
  for i in 0..6 {
    wx[i] = past[b + 2 + i * 2];
    wy[i] = past[b + 3 + i * 2];
  }
  repeat 14 { remove(past, b); }
  moves -= 1;
}

fn restart() {
  wx = [1, 1, 1, 1, 2, 3];
  wy = [0, 1, 2, 5, 5, 5];
  bx = 2;
  by = 4;
  won = false;
  moves = 0;
  clear(past);
}

fn scene() {
  let b = [0; 63];
  for r in 0..7 { b[r * 9 + 5] = 4; }
  b[34] = 3;
  for i in 0..6 { b[wy[i] * 9 + wx[i]] = 2; }
  b[by * 9 + bx] = 1;
  pixels(b, 0, 0, 9, 16);
  for i in 0..6 { text(ww[i], wx[i] * 16 + 8, wy[i] * 16 + 8, 5, 9); }
  if won { text("You win", 72, 56, 16, 9); }
}

on key "left" { go(-1, 0); }
on key "right" { go(1, 0); }
on key "up" { go(0, -1); }
on key "down" { go(0, 1); }

