// Baba is you: the arrows move Baba and push the words; step on the flag while FLAG IS WIN reads
// left to right.
// icon: line 7 21 7 3 fill 7 3 19 7 7 11 dot 15 18 3
state wx = [0, 1, 2];           // the words FLAG, IS, WIN: column and row
state wy = [2, 2, 2];
state ww = ["FLAG", "IS", "WIN"];
state bx = 0;
state by = 4;
state won = false;

fn tile(c: int, r: int) -> int {
  for i in 0..3 {
    if wx[i] == c && wy[i] == r { return i; }
  }
  return -1;
}

fn on(c: int, r: int) -> bool { return c >= 0 && c < 5 && r >= 0 && r < 5; }

fn rule() -> bool { return wy[1] == wy[0] && wy[2] == wy[0] && wx[1] == wx[0] + 1 && wx[2] == wx[0] + 2; }

// A step, pushing the words in the way unless the last would leave the grid.
fn go(dx: int, dy: int) {
  let c = bx + dx;
  let r = by + dy;
  if won || !on(c, r) { return; }
  let n = 0;
  while tile(c + n * dx, r + n * dy) >= 0 { n += 1; }
  if !on(c + n * dx, r + n * dy) { return; }
  for k in 0..n {
    let i = tile(c + (n - 1 - k) * dx, r + (n - 1 - k) * dy);
    wx[i] += dx;
    wy[i] += dy;
  }
  bx = c;
  by = r;
  won = bx == 4 && by == 0 && rule();
}

fn scene() {
  let b = [0; 25];
  b[4] = 3;
  for i in 0..3 { b[wy[i] * 5 + wx[i]] = 2; }
  b[by * 5 + bx] = 1;
  pixels(b, 0, 0, 5, 20);
  for i in 0..3 { text(ww[i], wx[i] * 20 + 10, wy[i] * 20 + 10, 6, 9); }
}

