// Migration: Fly the flock south stop by stop, or Rest to gain energy; storms every 3rd day
// double a leg's cost, and flying short of energy costs birds. Arrive before winter (day 16).
// icon: line 3 10 8 14 12 9 16 14 21 10 line 6 17 9 19 12 17
state legs = [3, 2, 4, 3, 5, 2, 4];
state day = 1;
state birds = 20;
state energy = 10;
state stop = 0;
state result = "";

fn storm() -> bool { return day % 3 == 0; }

fn next() {
  day += 1;
  if stop == 7 {
    result = "Arrived";
  } else if birds == 0 {
    result = "Flock lost";
  } else if day == 16 {
    result = "Winter";
  }
}

fn fly() {
  if result != "" { return; }
  let cost = legs[stop] * (storm() ? 2 : 1);
  if energy >= cost {
    energy -= cost;
  } else {
    birds = max(0, birds - 2 * (cost - energy));
    energy = 0;
  }
  stop += 1;
  next();
}

fn rest() {
  if result != "" { return; }
  energy = min(10, energy + 4);
  next();
}

fn again() {
  day = 1;
  birds = 20;
  energy = 10;
  stop = 0;
  result = "";
}

fn map() {
  let b = [4; 8];
  for i in 0..stop { b[i] = 2; }
  b[stop] = 1;
  pixels(b, 0, 0, 8, 20);
}

