// Courtroom: step through a testimony with Next and Back, Press for more, and Present the
// evidence that contradicts a statement. Three wrong presentations and the verdict is Guilty.
// icon: line 12 4 12 20 line 4 7 20 7 arc 6 11 4 90 270 arc 18 11 4 90 270 line 7 20 17 20
state names = ["Mr. Gray", "Ms. Plum"];
