fn press() {
  if result == "" && witness == 1 && at == 2 && !pressed {
    insert(talk, 3, "I saw the defendant at 9");
    pressed = true;
  }
}

fn present(item: string) {
  if result != "" { return; }
  if witness == 0 && talk[at] == "It was raining hard" && item == "Weather report" {
    witness = 1;
    talk = plum;
    at = 0;
  } else if witness == 1 && talk[at] == "I saw the defendant at 9" && item == "Receipt" {
    result = "Not guilty";
  } else {
    hearts -= 1;
    if hearts == 0 { result = "Guilty"; }
  }
