  talk = gray;
  witness = 0;
  at = 0;
  pressed = false;
  hearts = 3;
  result = "";
}

fn heartrow() {
  let b = [8, 8, 8];
  for i in 0..hearts { b[i] = 1; }
  pixels(b, 0, 0, 3, 20);
}

