// What is at (c, r): "." open, D dirt, G gold, J a jewel, R rock.
fn kind(c: int, r: int) -> string {
  if dug[r * 8 + c] { return "."; }
  return land[r][c];
}

fn shade(k: string) -> int {
  if k == "D" { return 8; }
  if k == "G" { return 3; }
  if k == "J" { return 4; }
  if k == "R" { return 5; }
  return -1;
}

fn move(dx: int, dy: int) {
  let c = px + dx;
  let r = py + dy;
  if over || fuel == 0 || c < 0 || c > 7 || r < 0 || r > 7 { return; }
  let k = kind(c, r);
  if k == "R" || (dy < 0 && k != ".") { return; }
  if k == "G" { gold += 1; }
  if k == "J" { jewels += 1; }
  dug[r * 8 + c] = true;
  px = c;
  py = r;
  fuel -= 1;
  if py == 0 {
    money += gold * 10 + jewels * 30;
    gold = 0;
    jewels = 0;
  } else if fuel == 0 {
    over = true;
  }
}

// A tap steers one square toward it, across or down, whichever is farther.
fn toward(c: int, r: int) {
  let ax = c - px;
  let ay = r - py;
  if abs(ax) > abs(ay) {
    move(ax / abs(ax), 0);
  } else if ay != 0 {
    move(0, ay / abs(ay));
  }
}

fn scene() {
  let cells = [-1; 64];
  for i in 0..8 { cells[i] = 6; }
  for r in 1..8 {
    for c in 0..8 {
      let s = shade(kind(c, r));
      if s >= 0 { cells[r * 8 + c] = s; }
    }
  }
  cells[py * 8 + px] = 1;
  pixels(cells, 0, 0, 8, 16);
  if over { text("Out of fuel", 64, 64, 14, 11); }
}

