// Storm royale: Start, walk with the arrows, open chests for ammo and Fire the way you face. The
// storm closes a ring every 5 seconds: last one standing wins.
// icon: ring 12 12 9 ring 12 12 4 line 12 2 12 7 line 12 17 12 22 line 2 12 7 12 line 17 12 22 12
state bc = [9, 1, 9, 5, 5];    // the bots' columns and rows
state br = [1, 9, 9, 2, 5];
state cc = [3, 7];             // the chests'
state cr = [1, 7];
state mc = 1;                  // me
state mr = 1;
state fc = 1;                  // the way I face
state fr = 0;
state health = 100;
state ammo = 3;
state secs = 0;
state ring = 0;                // rings of storm
state speed = 0;
state result = "";

fn bot(c: int, r: int) -> int {
  for i in 0..len(bc) {
    if bc[i] == c && br[i] == r { return i; }
  }
  return -1;
}

fn storm(c: int, r: int) -> bool { return min(min(c, r), min(10 - c, 10 - r)) < ring; }

fn check() {
  if len(bc) == 0 {
    result = "Victory!";
    speed = 0;
  } else if health <= 0 {
    health = 0;
    result = "Eliminated";
    speed = 0;
  }
}

fn walk(dc: int, dr: int) {
  if speed == 0 { return; }
  fc = dc;
  fr = dr;
  let c = mc + dc;
  let r = mr + dr;
  if c < 0 || c > 10 || r < 0 || r > 10 || bot(c, r) >= 0 { return; }
  mc = c;
  mr = r;
  for i in 0..len(cc) {
    if cc[i] == c && cr[i] == r {
      remove(cc, i);
      remove(cr, i);
      ammo += 2;
      return;
    }
  }
}

fn fire() {
  if speed == 0 || ammo == 0 { return; }
  ammo -= 1;
  for k in 1..5 {
    let i = bot(mc + fc * k, mr + fr * k);
    if i >= 0 {
      remove(bc, i);
      remove(br, i);
      check();
      return;
    }
  }
}

every speed {
  secs += 1;
  if secs % 5 == 0 && ring < 5 { ring += 1; }
  let i = 0;
  while i < len(bc) {
    if storm(bc[i], br[i]) {
      remove(bc, i);
      remove(br, i);
    } else {
      i += 1;
    }
  }
  check();
  if speed > 0 && storm(mc, mr) {
    health -= 10;
    check();
  }
}

fn fresh() {
  bc = [9, 1, 9, 5, 5];
  br = [1, 9, 9, 2, 5];
  cc = [3, 7];
  cr = [1, 7];
  mc = 1;
  mr = 1;
  fc = 1;
  fr = 0;
  health = 100;
  ammo = 3;
  secs = 0;
  ring = 0;
  result = "";
}

fn scene() {
  let cells = [-1; 121];
  for i in 0..121 {
    if storm(i % 11, i / 11) { cells[i] = 5; }
  }
  for i in 0..len(cc) { cells[cr[i] * 11 + cc[i]] = 3; }
  for i in 0..len(bc) { cells[br[i] * 11 + bc[i]] = 1; }
  cells[mr * 11 + mc] = 4;
  pixels(cells, 0, 0, 11, 10);
  line(mc * 10 + 5, mr * 10 + 5, mc * 10 + 5 + fc * 6, mr * 10 + 5 + fr * 6, 2, 9);
  text(result, 55, 55, 14, 11);
}

