// Duo royale: blue walks with WASD and shoots with space, red with the arrows and enter; a shot
// hits the other in line for 20. The storm closes in every 5 seconds: last one alive wins.
// icon: ring 12 12 9 dot 8 12 2 dot 16 12 2
state px = [0, 8];          // the players: columns, rows, the way each last moved, health
state py = [0, 8];
state fx = [1, -1];
state fy = [0, 0];
state hp = [100, 100];
state secs = 0;
state ring = 0;
state winner = "";

fn storm(c: int, r: int) -> bool { return min(min(c, r), min(8 - c, 8 - r)) < ring; }

fn walk(p: int, dx: int, dy: int) {
  if winner != "" { return; }
  fx[p] = dx;
  fy[p] = dy;
  px[p] = min(8, max(0, px[p] + dx));
  py[p] = min(8, max(0, py[p] + dy));
}

fn over() {
  if hp[0] <= 0 && hp[1] <= 0 {
    winner = "Nobody wins";
  } else if hp[1] <= 0 {
    winner = "Blue wins!";
  } else if hp[0] <= 0 {
    winner = "Red wins!";
  }
}

// A shot from player p straight ahead: the other is hit if anywhere in that line.
fn shoot(p: int) {
  if winner != "" { return; }
  let o = 1 - p;
  let ax = px[o] - px[p];
  let ay = py[o] - py[p];
  let ahead = false;
  if fx[p] != 0 { ahead = ay == 0 && ax * fx[p] > 0; }
  if fy[p] != 0 { ahead = ax == 0 && ay * fy[p] > 0; }
  if ahead {
    hp[o] = max(0, hp[o] - 20);
    over();
  }
}

every 1000 {
  if winner == "" {
    secs += 1;
    if secs % 5 == 0 && ring < 4 { ring += 1; }
    for p in 0..2 {
      if storm(px[p], py[p]) { hp[p] = max(0, hp[p] - 10); }
    }
    over();
  }
}

fn scene() {
  let cells = [-1; 81];
  for i in 0..81 {
    if storm(i % 9, i / 9) { cells[i] = 5; }
  }
  cells[py[0] * 9 + px[0]] = 4;
  cells[py[1] * 9 + px[1]] = 1;
  pixels(cells, 0, 0, 9, 12);
  text(winner, 54, 54, 14, 11);
}

