// Shapes: add squares and circles, tap one to select it, then recolor, resize, move it (arrows,
// or tap where it should go), bring it to the Front or Delete it.
// icon: fill 3 9 13 9 13 19 3 19 ring 15 9 6 line 4 21 20 21
state round = [false; 0];   // each shape: a circle or a square, center, size (side or radius), color
state sx = [0; 0];
state sy = [0; 0];
state size = [0; 0];
state hue = [0; 0];
state sel = -1;
state color = 1;

fn add(circle: bool) {
  push(round, circle);
  push(sx, 80);
  push(sy, 60);
  push(size, circle ? 10 : 20);
  push(hue, color);
  sel = len(sx) - 1;
}

fn under(i: int, x: int, y: int) -> bool {
  if round[i] { return (x - sx[i]) * (x - sx[i]) + (y - sy[i]) * (y - sy[i]) <= size[i] * size[i]; }
  return abs(x - sx[i]) * 2 < size[i] && abs(y - sy[i]) * 2 < size[i];
}

fn tap(x: int, y: int) {
  for k in 0..len(sx) {
    let i = len(sx) - 1 - k;
    if under(i, x, y) {
      sel = i;
      return;
    }
  }
  if sel >= 0 {
    sx[sel] = x;
    sy[sel] = y;
  }
}

fn paint(c: int) {
  color = c;
  if sel >= 0 { hue[sel] = c; }
}

fn grow(steps: int) {
  if sel < 0 { return; }
  if round[sel] {
    size[sel] = min(30, max(10, size[sel] + steps * 10));
  } else {
    size[sel] = min(60, max(20, size[sel] + steps * 20));
  }
}

fn nudge(dx: int, dy: int) {
  if sel >= 0 {
    sx[sel] += dx;
    sy[sel] += dy;
  }
}

// The selected shape moved to the end of every list: drawn over the others.
fn front() {
  if sel < 0 { return; }
  push(round, round[sel]);
  push(sx, sx[sel]);
  push(sy, sy[sel]);
  push(size, size[sel]);
  push(hue, hue[sel]);
  drop(sel);
  sel = len(sx) - 1;
}

fn drop(i: int) {
  remove(round, i);
  remove(sx, i);
  remove(sy, i);
  remove(size, i);
  remove(hue, i);
}

fn scene() {
  for i in 0..len(sx) {
    if round[i] {
      circle(sx[i], sy[i], size[i], hue[i]);
    } else {
      rect(sx[i] - size[i] / 2, sy[i] - size[i] / 2, size[i], size[i], hue[i]);
    }
  }
  if sel >= 0 {
    if round[sel] {
      ring(sx[sel], sy[sel], size[sel] + 2, 1, 9);
    } else {
      let h = size[sel] / 2 + 1;
      line(sx[sel] - h, sy[sel] - h, sx[sel] + h, sy[sel] - h, 1, 9);
      line(sx[sel] + h, sy[sel] - h, sx[sel] + h, sy[sel] + h, 1, 9);
      line(sx[sel] + h, sy[sel] + h, sx[sel] - h, sy[sel] + h, 1, 9);
      line(sx[sel] - h, sy[sel] + h, sx[sel] - h, sy[sel] - h, 1, 9);
    }
  }
}

