// Lines: each tap drops a point joined to the last by a straight line in the color picked;
// Undo takes back the last point, Clear wipes it all.
// icon: line 3 19 9 6 15 15 21 4 dot 3 19 2 dot 21 4 2
state px = [0; 0];          // the points, and the color of the line to each
state py = [0; 0];
state pc = [0; 0];
state color = 9;

fn scene() {
  for i in 1..len(px) { line(px[i - 1], py[i - 1], px[i], py[i], 2, pc[i]); }
  for i in 0..len(px) { circle(px[i], py[i], 1, pc[i]); }
}

fn drop(x: int, y: int) {
  let n = len(px);
  if n == 0 || px[n - 1] != x || py[n - 1] != y {
    push(px, x);
    push(py, y);
    push(pc, color);
  }
}

