// Merge orders: Spawn level 1 items (1 energy each), tap one then a match to merge them up a
// level, and Deliver what each order asks for.
// icon: fill 4 14 10 14 10 20 4 20 fill 14 14 20 14 20 20 14 20 line 7 11 12 5 17 11
state board = [0; 25];      // each square's level, 0 empty
state sel = -1;
state energy = 10;
state coins = 0;
state order = 0;
state wants = [3, 4, 2];
state pays = [20, 50, 10];

fn spawn() {
  if energy == 0 { return; }
  for i in 0..25 {
    if board[i] == 0 {
      board[i] = 1;
      energy -= 1;
      return;
    }
  }
}

fn tap(i: int) {
  if sel < 0 {
    if board[i] > 0 { sel = i; }
  } else if i == sel {
    sel = -1;
  } else if board[i] == 0 {
    board[i] = board[sel];
    board[sel] = 0;
    sel = -1;
  } else if board[i] == board[sel] && board[i] < 5 {
    board[i] += 1;
    board[sel] = 0;
    sel = -1;
  } else {
    sel = i;
  }
}

fn deliver() {
  if sel >= 0 && order < len(wants) && board[sel] == wants[order] {
    board[sel] = 0;
    sel = -1;
    coins += pays[order];
    order += 1;
  }
}

fn scene() {
  let cells = [-1; 25];
  for i in 0..25 {
    if board[i] > 0 { cells[i] = board[i]; }
  }
  pixels(cells, 0, 0, 5, 20);
  for i in 0..6 {
    line(i * 20, 0, i * 20, 100, 1, 8);
    line(0, i * 20, 100, i * 20, 1, 8);
  }
  if sel >= 0 { ring(sel % 5 * 20 + 10, sel / 5 * 20 + 10, 9, 2, 9); }
}

every 3000 { energy = min(10, energy + 1); }

