// Merge: New piece drops a level 1 on an empty spot; tap two pieces of a level, one after the
// other, to merge them up a level where you tapped second. Each level has its color.
// icon: fill 3 13 10 13 10 20 3 20 fill 14 13 21 13 21 20 14 20 line 6 10 12 4 18 10
state board = [0; 16];      // each spot's level, 0 empty
state sel = -1;
state best = 0;

fn spawn() {
  let k = random(16);
  for j in 0..16 {
    let i = (k + j) % 16;
    if board[i] == 0 {
      board[i] = 1;
      best = max(best, 1);
      return;
    }
  }
}

fn tap(i: int) {
  if sel >= 0 && sel != i && board[i] > 0 && board[i] == board[sel] {
    board[i] += 1;
    board[sel] = 0;
    best = max(best, board[i]);
    sel = -1;
  } else if board[i] > 0 && sel != i {
    sel = i;
  } else {
    sel = -1;
  }
}

fn pieces() -> int {
  let n = 0;
  for i in 0..16 {
    if board[i] > 0 { n += 1; }
  }
  return n;
}

fn scene() {
  let cells = [-1; 16];
  for i in 0..16 {
    if board[i] > 0 { cells[i] = min(board[i], 11); }
  }
  pixels(cells, 0, 0, 4, 30);
  if sel >= 0 { ring(sel % 4 * 30 + 15, sel / 4 * 30 + 15, 13, 2, 9); }
}

label "Merge";
label "Pieces " + pieces() + "   Highest level " + best;
