// back. Upkeep is $50 a plane every 10 s. Reach $3000 before going broke.
// icon: line 12 3 12 21 line 3 15 12 9 21 15 line 8 21 12 18 16 21
state money = 1000;
state planes = 0;
state dest = [0; 0];        // each plane in the air: where to, and seconds flown
state flown = [0; 0];
state secs = 0;
state over = "";
state cx = [80, 40, 132, 124];   // the hub, Oslo, Rome and Cairo on the map
state cy = [60, 20, 40, 100];

fn trip(d: int) -> int { return d * 2 + 2; }

fn fly(d: int) {
  let fuel = [50, 100, 150];
  if over == "" && planes > len(dest) && money >= fuel[d] {
    money -= fuel[d];
    push(dest, d);
    push(flown, 0);
  }
}

fn end() {
  if money >= 3000 { over = "Top airline!"; }
  if money < 0 { over = "Bankrupt"; }
}

every 1000 {
  if over == "" {
    secs += 1;
    let fare = [150, 300, 500];
    let i = 0;
    while i < len(dest) {
      flown[i] += 1;
      if flown[i] == trip(dest[i]) {
        money += fare[dest[i]];
        remove(dest, i);
        remove(flown, i);
      } else {
        i += 1;
      }
    }
    if secs % 10 == 0 { money -= planes * 50; }
    end();
  }
}

// Where plane i is along one axis (at: the hub's, then the cities'), out and back.
fn spot(at: [int], i: int) -> int {
  let t = trip(dest[i]);
  let k = min(flown[i], t - flown[i]);
  return at[0] + (at[dest[i] + 1] - at[0]) * k * 2 / t;
}

// The map: the hub, the cities on their lines from it, and the planes in the air.
fn scene() {
  for d in 0..4 {
    line(cx[0], cy[0], cx[d], cy[d], 1, 8);
    circle(cx[d], cy[d], 5, 4);
  }
  for i in 0..len(dest) { circle(spot(cx, i), spot(cy, i), 3, 1); }
}

