// Terraform: pick Ocean, Greenery or City and tap the map to place it; Heat warms the planet;
// Next generation pays Income plus Rating. Fill the oceans, the air and the heat to win.
// icon: ring 12 12 9 fill 7 8 12 6 14 10 10 13 fill 13 15 17 13 18 17
state tiles = [1, 1, 1, 1, 1,
  1, 6, 1, 6, 1,
  1, 1, 1, 1, 1,
  1, 1, 6, 1, 1,
  1, 1, 1, 1, 1];           // 1 bare, 6 an ocean spot, 4 ocean, 2 greenery, 3 city
state placing = 4;
state money = 40;
state income = 5;
state rating = 10;
state oceans = 0;
state oxygen = 0;
state temp = -6;
state gen = 1;
state done = false;

// How many squares beside (c, r) hold k.
fn beside(c: int, r: int, k: int) -> int {
  let n = 0;
  let dc = [0, 1, 0, -1];
  let dr = [-1, 0, 1, 0];
  for s in 0..4 {
    let a = c + dc[s];
    let b = r + dr[s];
    if a >= 0 && a < 5 && b >= 0 && b < 5 && tiles[b * 5 + a] == k { n += 1; }
  }
  return n;
}

fn place(c: int, r: int) {
  let i = r * 5 + c;
  let costs = [0, 0, 20, 25, 15];
  if done || money < costs[placing] { return; }
  if placing == 4 && tiles[i] != 6 { return; }
  if placing != 4 && tiles[i] != 1 { return; }
  if placing == 3 && beside(c, r, 3) > 0 { return; }
  money -= costs[placing];
  tiles[i] = placing;
  money += beside(c, r, 4) * 2;
  if placing == 4 {
    oceans += 1;
    rating += 1;
  } else if placing == 2 && oxygen < 4 {
    oxygen += 1;
    rating += 1;
  } else if placing == 3 {
    income += 2;
  }
  check();
}

fn check() {
  if oceans == 3 && oxygen == 4 && temp == 0 { done = true; }
}

fn scene() {
  pixels(tiles, 0, 0, 5, 24);
  if done { text("Terraformed!", 60, 60, 14, 9); }
}

label "Terraform";
label "Money $" + money + "   Income " + income + "   Rating " + rating + "   Generation " + gen;
