// Hopscotch: press Hop to hop up the court from 1 to 8, back down to 1 and off again.
// icon: loop 7 2 17 2 17 22 7 22 line 7 9 17 9 line 7 15 17 15 dot 12 18 2
state at = 0;             // the square stood on, 1 to 8; 0 off the court
state up = true;          // whether the hops go up the court
state hops = 0;

// Square k (1 to 8), square 1 at the bottom: blue where the player stands, else gray.
fn square(k: int) {
  let c = 8;
  if k == at { c = 4; }
  let top = (8 - k) * 20;
  rect(2, top + 2, 36, 16, c);
  text(k, 20, top + 10, 10, 9);
}

fn court() {
  for k in 1..9 { square(k); }
}

// Up to 8, back down, off the court below 1, then up again.
fn hop() {
  hops += 1;
  if at == 0 { up = true; }
  if at == 8 { up = false; }
  if up { at += 1; } else { at -= 1; }
}

label "Hopscotch";
canvas 40, 160, court();
label "Square: " + at;
label "Hops: " + hops;
