// Pi quiz: press the next decimal of pi; a right one joins the number, a wrong one says Try
// again. It goes to 20 decimals.
// icon: line 4 7 20 7 line 9 7 8 20 line 15 7 15 18 19 20
state found = 0;          // decimals found, 0 to 20
state wrong = false;      // whether the last guess was wrong

fn decimals() -> string { return "14159265358979323846"; }

// Pi to the decimals found.
fn pi() -> string {
  let ds = decimals();
  let s = "3.";
  for i in 0..found { s = s + ds[i]; }
  return s;
}

fn guess(d: int) {
  let ds = decimals();
  if found >= len(ds) { return; }
  if parse(ds[found], -1) == d {
    found += 1;
    wrong = false;
  } else {
    wrong = true;
  }
}

label "Pi quiz";
label pi();
label "Digits: " + found;
if wrong { label "Try again"; }
row {
  for d in 0..10 { button "" + d { guess(d); } }
}

