// Coordinates: move the point with Left, Right, Up and Down; it shows its x and y, each -4 to 4.
// icon: line 12 3 12 21 line 3 12 21 12 dot 17 7 3
state px = 0;             // the point, -4 to 4 each way, y up
state py = 0;

// The plane: the axes silver, the point blue; row 0 is y 4, column 0 x -4.
fn plane() -> [int] {
  let b = [8; 81];
  for i in 0..9 {
    b[4 * 9 + i] = 7;
    b[i * 9 + 4] = 7;
  }
  b[(4 - py) * 9 + px + 4] = 4;
  return b;
}

fn go(dx: int, dy: int) {
  px = min(4, max(-4, px + dx));
  py = min(4, max(-4, py + dy));
}

