// Quadrants: tap a square of the plane to pick that point; it shows the point's x and y and
// which quadrant it is in.
// icon: line 12 2 12 22 line 2 12 22 12 dot 17 7 3
state px = 0;             // the point, -10 to 10 each way, y up
state py = 0;

fn quadrant() -> string {
  if px == 0 || py == 0 { return "On an axis"; }
  if py > 0 { return px > 0 ? "Quadrant: 1" : "Quadrant: 2"; }
  return px < 0 ? "Quadrant: 3" : "Quadrant: 4";
}

// The plane, 21 x 21 squares of 10 units, x -10 at the left and y 10 at the top: the axes
// silver, the point blue.
fn plane() {
  let b = [-1; 441];
  for i in 0..21 {
    b[10 * 21 + i] = 7;
    b[i * 21 + 10] = 7;
  }
  b[(10 - py) * 21 + px + 10] = 4;
  pixels(b, 0, 0, 21, 10);
}

label "Quadrants";
