// Board cuts: type the board's length and a piece's length in mm, then press Cut; each cut also
// loses 3 mm to the blade. New board starts again.
// icon: fill 2 8 11 8 11 16 2 16 fill 14 8 22 8 22 16 14 16 line 12 3 13 21
state board = "";
state piece = "";
state cuts = [0; 0];      // the pieces cut, in order

fn size(s: string) -> int { return min(1000000, parse(s, 0)); }

// The board less the pieces and 3 mm of sawdust for each cut.
fn left() -> int {
  let n = size(board);
  for i in 0..len(cuts) { n -= cuts[i] + 3; }
  return n;
}

fn cut() {
  let p = size(piece);
  if p > 0 && p + 3 <= left() && len(cuts) < 1000 { push(cuts, p); }
}

label "Board cuts";
row {
  label "Board (mm)";
  input board;
}
row {
  label "Piece (mm)";
  input piece;
  button "Cut" { cut(); }
}
for i in 0..len(cuts) { label (i + 1) + ". " + cuts[i] + " mm"; }
label "Left: " + left() + " mm";
label "Pieces: " + len(cuts);
label "Sawdust: " + len(cuts) * 3 + " mm";
button "New board" { clear(cuts); }

// Lumber buying: type the board's and the piece's lengths in inches, how many pieces you need and
// a board's price; it works out how many boards to buy and what is left over.
// icon: fill 2 5 22 5 22 9 2 9 fill 2 11 22 11 22 15 2 15 fill 2 17 22 17 22 21 2 21
state board = "";
state piece = "";
state count = "";
state price = "";

fn num(s: string) -> int { return min(100000, parse(s, 0)); }

fn yields() -> int { return num(board) / num(piece); }

// The fewest boards that give all the pieces: the count over the yield, rounded up.
fn boards() -> int { return (num(count) + yields() - 1) / yields(); }

label "Lumber buying";
row {
  label "Board (in)";
  input board;
}
row {
  label "Piece (in)";
  input piece;
}
row {
  label "Pieces needed";
  input count;
}
row {
  label "Board price ($)";
  input price;
}
if num(board) <= 0 || num(piece) <= 0 || num(count) <= 0 {
  label "Fill in the sizes";
} else if num(piece) > num(board) {
  label "Too long";
} else {
  label "Yield: " + yields();
  label "Boards: " + boards();
  label "Spare: " + (boards() * yields() - num(count));
  label "Offcut: " + (num(board) - yields() * num(piece)) + " in";
  label "Total: $" + boards() * max(0, num(price));
}

// NATO speller: type a word and it is spelled out in the NATO alphabet, Alfa to Zulu; anything
// that is not a letter is left out.
// icon: loop 3 4 21 4 21 15 11 15 6 20 7 15 3 15 line 7 8 9 12 11 8 line 13 8 17 12 line 17 8 13 12
state word = "";
state small = "abcdefghijklmnopqrstuvwxyz";
state big = "ABCDEFGHIJKLMNOPQRSTUVWXYZ";
state codes = ["Alfa", "Bravo", "Charlie", "Delta", "Echo", "Foxtrot", "Golf", "Hotel", "India",
  "Juliett", "Kilo", "Lima", "Mike", "November", "Oscar", "Papa", "Quebec", "Romeo", "Sierra",
  "Tango", "Uniform", "Victor", "Whiskey", "X-ray", "Yankee", "Zulu"];

// A letter's place in the alphabet, capital or small, or -1 for anything else.
fn place(c: string) -> int {
  for i in 0..26 {
    if small[i] == c || big[i] == c { return i; }
  }
  return -1;
}

fn spelled() -> string {
  let s = "";
  for i in 0..min(len(word), 200) {
    let k = place(word[i]);
    if k >= 0 {
      if s != "" { s = s + " "; }
      s = s + codes[k];
    }
  }
  return s;
}

fn letters() -> int {
  let n = 0;
  for i in 0..min(len(word), 200) {
    if place(word[i]) >= 0 { n += 1; }
  }
  return n;
}

label "NATO speller";
input word;
label spelled();
label "Letters: " + letters();

// NATO decoder: type NATO code words with spaces between them, like Hotel Echo Lima Lima Oscar,
// and it shows the letters they spell; a word it does not know shows as ?.
// icon: loop 3 4 21 4 21 15 11 15 6 20 7 15 3 15 line 7 12 9 7 11 12 line 8 10 10 10 line 14 7 14 12 17 12
state typed = "";
state small = "abcdefghijklmnopqrstuvwxyz";
state big = "ABCDEFGHIJKLMNOPQRSTUVWXYZ";
state codes = ["alfa", "bravo", "charlie", "delta", "echo", "foxtrot", "golf", "hotel", "india",
  "juliett", "kilo", "lima", "mike", "november", "oscar", "papa", "quebec", "romeo", "sierra",
  "tango", "uniform", "victor", "whiskey", "x-ray", "yankee", "zulu"];

fn lower(c: string) -> string {
  for i in 0..26 {
    if big[i] == c { return small[i]; }
  }
  return c;
}

// The words typed, in small letters: any run of spaces parts two.
fn words() -> [string] {
  let ws = [""; 0];
  let w = "";
  for i in 0..min(len(typed), 500) {
    if typed[i] == " " {
      if w != "" { push(ws, w); }
      w = "";
    } else {
      w = w + lower(typed[i]);
    }
  }
  if w != "" { push(ws, w); }
  return ws;
}

fn letter(w: string) -> string {
  if w == "alpha" { return "A"; }
  if w == "juliet" { return "J"; }
  for i in 0..26 {
    if codes[i] == w { return big[i]; }
  }
  return "?";
}

fn decoded() -> string {
  let ws = words();
  let s = "";
  for i in 0..len(ws) { s = s + letter(ws[i]); }
  return s;
}

label "NATO decoder";
input typed;
label "Letters: " + decoded();
label "Words: " + len(words());

