// Delivery date: pick the day you order and how many working days shipping takes; it tells the
// weekday the parcel arrives, skipping weekends.
// icon: loop 3 5 21 5 21 21 3 21 line 3 10 21 10 line 8 2 8 7 line 16 2 16 7 fill 12 13 18 13 18 18 12 18
state names = ["Monday", "Tuesday", "Wednesday", "Thursday", "Friday", "Saturday", "Sunday"];
state abbr = ["Mon", "Tue", "Wed", "Thu", "Fri", "Sat", "Sun"];
state ordered = 0;        // the order day, Monday 0
state working = 3;        // the shipping time in working days

// The days from the order to the Nth working day after it (Monday to Friday are 0 to 4).
fn days() -> int {
  let d = ordered;
  let t = 0;
  let k = 0;
  while k < working {
    t += 1;
    d = (d + 1) % 7;
    if d < 5 { k += 1; }
  }
  return t;
}

fn plural(n: int) -> string {
  if n == 1 { return "In 1 day"; }
  return "In " + n + " days";
}

label "Delivery date";
row {
  for i in 0..7 { button abbr[i] { ordered = i; } }
}
label "Ordered: " + names[ordered];
row {
  button "-" { working = max(1, working - 1); }
  label "Shipping: " + working + " working days";
  button "+" { working = min(10, working + 1); }
}
label "Arrives: " + names[(ordered + days()) % 7];
label plural(days());

// Ohm's law: type a voltage and a resistance; it shows the current through the resistor and the
// power it gives off as heat.
// icon: line 2 12 6 12 7 8 9 16 11 8 13 16 15 8 17 16 18 12 22 12
state volts = "";
state ohms = "";

fn num(s: string) -> int { return min(100000, max(0, parse(s, 0))); }

// Milliamps and milliwatts, rounded down.
fn current() -> int { return num(volts) * 1000 / num(ohms); }
fn power() -> int { return num(volts) * num(volts) * 1000 / num(ohms); }

label "Ohm's law";
row {
  label "Voltage (V)";
  input volts;
}
row {
  label "Resistance (ohms)";
  input ohms;
}
if num(ohms) <= 0 {
  label "No resistance";
} else {
  label "Current: " + current() + " mA";
  label "Power: " + power() + " mW";
  if current() > 1000 { label "Too much current"; }
}

// LED resistor: type the supply voltage and the current, and pick the LED's color; it works out
// the resistor to put in series and the nearest standard one at or above it.
// icon: fill 8 3 16 3 16 13 8 13 line 6 13 18 13 line 10 13 10 21 line 14 13 14 21
state supply = "";
state current = "";
state colors = ["Red", "Yellow", "Green", "Blue", "White"];
state drops = [1800, 2000, 2200, 3000, 3200];   // each color's drop in mV
state led = 0;
state e12 = [10, 12, 15, 18, 22, 27, 33, 39, 47, 56, 68, 82];

fn num(s: string, most: int) -> int { return min(most, parse(s, 0)); }

// The volts the resistor takes, in mV.
fn spare() -> int { return num(supply, 1000) * 1000 - drops[led]; }
fn ma() -> int { return num(current, 10000); }

// Ohms, rounded up.
fn ohms() -> int { return (spare() + ma() - 1) / ma(); }

// The smallest standard value at or above r.
fn standard(r: int) -> int {
  let scale = 1;
  repeat 8 {
    for i in 0..12 {
      if e12[i] * scale >= r { return e12[i] * scale; }
    }
    scale *= 10;
  }
  return r;
}

label "LED resistor";
row {
  label "Supply (V)";
  input supply;
}
row {
  for i in 0..5 { button colors[i] { led = i; } }
}
label "LED: " + colors[led];
row {
  label "Current (mA)";
  input current;
}
if spare() <= 0 || ma() <= 0 {
  label "Check the values";
} else {
  label "Resistor: " + ohms() + " ohms";
  label "Use: " + standard(ohms()) + " ohms";
  label "Heat: " + spare() * ma() / 1000 + " mW";
}

// ABV calculator: type the original and final gravity as four digits (1050 for 1.050); it shows
// the beer's alcohol by volume and how much of the sugar the yeast ate.
// icon: fill 6 7 16 7 16 21 6 21 loop 16 10 20 10 20 17 16 17 fill 6 3 16 3 16 6 6 6
state og = "";
state fg = "";

fn num(s: string) -> int { return min(100000, parse(s, -1)); }

// ABV in tenths of a percent, cut: the drop times 131.25 over 1000.
fn tenths() -> int { return (num(og) - num(fg)) * 13125 / 10000; }

fn sane() -> bool { return num(og) > 1000 && num(fg) >= 0 && num(fg) <= num(og); }

label "ABV calculator";
row {
  label "Original gravity";
  input og;
}
row {
  label "Final gravity";
  input fg;
}
if sane() {
  label "ABV: " + tenths() / 10 + "." + tenths() % 10 + "%";
  label "Attenuation: " + (num(og) - num(fg)) * 100 / (num(og) - 1000) + "%";
} else {
  label "Check the gravities";
}

// Hop timer: set the boil's length and press Start when the wort boils; it counts down and says
