state boil = 60;          // minutes
state left = 0;           // seconds left once started
state started = false;
state speed = 0;          // ms a step; 0 while it is stopped

fn clock(s: int) -> string {
  let r = s % 60;
  if r < 10 { return s / 60 + ":0" + r; }
  return s / 60 + ":" + r;
}

fn hops() -> string {
  if left == 0 { return "Flame out"; }
  if left <= 300 { return "Add aroma hops"; }
  if left <= 900 { return "Add flavor hops"; }
  return "Add bittering hops";
}

every speed {
  if left > 0 { left -= 1; }
  if left == 0 { speed = 0; }
}

label "Hop timer";
row {
  button "-" { boil = max(30, boil - 15); }
  label "Boil: " + boil + " min";
  button "+" { boil = min(90, boil + 15); }
}
if started {
  label "Left: " + clock(left);
  label hops();
} else {
  label "Left: " + clock(boil * 60);
}
button "Start" {
  left = boil * 60;
  started = true;
  speed = 1000;
}

