// Dues planner: type the year's costs and how many adult and junior members there are; it finds
// the smallest dues that cover the costs, juniors paying half.
// icon: dot 8 7 3 dot 17 9 2 fill 3 20 3 15 5 12 11 12 13 15 13 20 fill 13 20 14 16 20 16 21 20
state costs = "";
state adults = "";
state juniors = "";

fn num(s: string) -> int { return min(1000000, max(0, parse(s, 0))); }

// What everyone pays when the adult dues are d: juniors pay half, rounded up.
fn raised(d: int) -> int { return num(adults) * d + num(juniors) * ((d + 1) / 2); }

// The smallest dues that cover the costs: the costs over the members' shares (a junior half an
// adult), rounded up, or a dollar less when a junior's rounding up makes that enough.
fn dues() -> int {
  let shares = 2 * num(adults) + num(juniors);
  let d = (2 * num(costs) + shares - 1) / shares;
  if d > 0 && raised(d - 1) >= num(costs) { d -= 1; }
  return d;
}

label "Dues planner";
row {
  label "Costs ($)";
  input costs;
}
row {
  label "Adult members";
  input adults;
}
row {
  label "Junior members";
  input juniors;
}
if num(adults) + num(juniors) == 0 {
  label "No members";
} else {
  label "Adult dues: $" + dues();
  label "Junior dues: $" + (dues() + 1) / 2;
  label "Raised: $" + raised(dues());
  label "Spare: $" + (raised(dues()) - num(costs));
}

