// Stock watch: type a ticker and its price and press Track; each ticker shows its latest price
// and how far it has moved since you first tracked it.
// icon: line 3 18 9 12 13 15 21 6 line 16 6 21 6 21 11 line 3 21 21 21
state ticker = "";
state price = "";
state names = [""; 0];
state firsts = [0; 0];    // each ticker's first price
state lasts = [0; 0];     // and its latest

fn find(s: string) -> int {
  for i in 0..len(names) {
    if names[i] == s { return i; }
  }
  return -1;
}

fn track() {
  let p = min(1000000, parse(price, 0));
  if ticker == "" || p <= 0 { return; }
  let i = find(ticker);
  if i >= 0 {
    lasts[i] = p;
  } else if len(names) < 500 {
    push(names, ticker);
    push(firsts, p);
    push(lasts, p);
  }
}

fn change(i: int) -> string {
  let d = lasts[i] - firsts[i];
  if d > 0 { return "(+" + d + ")"; }
  return "(" + d + ")";
}

// How many tickers have moved the way of sign: 1 up, -1 down.
fn moved(sign: int) -> int {
  let n = 0;
  for i in 0..len(names) {
    if (lasts[i] - firsts[i]) * sign > 0 { n += 1; }
  }
  return n;
}

