// Protractor: tap above the base line to point the arm; it reads the angle from the right-hand
// base line to the nearest degree, its kind, and its supplement and complement.
// icon: arc 12 15 8 270 90 line 3 15 21 15 line 12 15 17 8
state angle = 0;          // degrees counterclockwise from the right

// The whole degree from 0 to 180 nearest the way (ax, up): the one whose sine and cosine line
// up best with it, on its side of the center.
fn nearest(ax: int, up: int) -> int {
  let best = 0;
  let off = 1000000000;
  for d in 0..181 {
    let along = ax * cos(d) + up * sin(d);
    let across = abs(ax * sin(d) - up * cos(d));
    if along > 0 && across < off {
      best = d;
      off = across;
    }
  }
  return best;
}

fn aim(px: int, py: int) {
  if py > 100 || (px == 100 && py == 100) { return; }
  angle = nearest(px - 100, 100 - py);
}

fn kind() -> string {
  if angle == 0 { return "Zero"; }
  if angle < 90 { return "Acute"; }
  if angle == 90 { return "Right"; }
  if angle < 180 { return "Obtuse"; }
  return "Straight";
}

// The half disc (a disc with its lower half covered), then the arm over it.
fn scene() {
  circle(100, 100, 90, 3);
  rect(0, 101, 200, 19, 0);
  line(100, 100, 100 + 90 * cos(angle) / 1000, 100 - 90 * sin(angle) / 1000, 2, 1);
}

label "Protractor";
canvas 200, 120, scene() { aim(x, y); }
label "Angle: " + angle + "°";
label "Kind: " + kind();
label "Supplement: " + (180 - angle) + "°";
if angle <= 90 { label "Complement: " + (90 - angle) + "°"; }

// Two-arm protractor: pick Arm A or Arm B and tap where it should point; it shows the angle
// between the arms and the reflex angle around the other way.
// icon: ring 12 12 10 line 12 12 21 12 line 12 12 7 4
state arms = [0, 90];     // each arm's direction in degrees, counterclockwise from the right
state moving = 0;         // the arm a tap moves: 0 A, 1 B

// The whole degree nearest the way (ax, up): the one whose sine and cosine line up best with it,
// on its side of the center.
fn nearest(ax: int, up: int) -> int {
  let best = 0;
  let off = 1000000000;
  for d in 0..360 {
    let along = ax * cos(d) + up * sin(d);
    let across = abs(ax * sin(d) - up * cos(d));
    if along > 0 && across < off {
      best = d;
      off = across;
    }
  }
  return best;
}

fn aim(px: int, py: int) {
  if px == 100 && py == 100 { return; }
  arms[moving] = nearest(px - 100, 100 - py);
}

fn between() -> int {
  let d = abs(arms[0] - arms[1]);
  return min(d, 360 - d);
}

fn arm(d: int, color: int) {
  line(100, 100, 100 + 90 * cos(d) / 1000, 100 - 90 * sin(d) / 1000, 2, color);
}

fn scene() {
  circle(100, 100, 90, 3);
  arm(arms[1], 4);
  arm(arms[0], 1);
}

label "Two-arm protractor";
canvas 200, 200, scene() { aim(x, y); }
row {
  button "Arm A" { moving = 0; }
  button "Arm B" { moving = 1; }
}
label "Angle: " + between() + "°";
label "Reflex: " + (360 - between()) + "°";

// Anagram checker: type two words or phrases in small letters; it says whether they use the
// same letters, spaces not counting.
// icon: loop 3 3 11 3 11 11 3 11 loop 13 13 21 13 21 21 13 21 line 14 6 19 6 19 10 line 17 8 19 10 21 8 line 10 18 5 18 5 14 line 3 16 5 14 7 16
state first = "";
state second = "";

// How many times a letter is in a phrase.
fn count(s: string, ch: string) -> int {
  let n = 0;
  for i in 0..len(s) {
    if s[i] == ch { n += 1; }
  }
  return n;
}

fn letters(s: string) -> int { return len(s) - count(s, " "); }

// Each letter of either phrase is in both as many times.
fn same(a: string, b: string) -> bool {
  for i in 0..len(a) {
    if a[i] != " " && count(a, a[i]) != count(b, a[i]) { return false; }
  }
  for i in 0..len(b) {
    if b[i] != " " && count(a, b[i]) != count(b, b[i]) { return false; }
  }
  return true;
}

label "Anagram checker";
input first;
input second;
label "Letters: " + letters(first);
if letters(first) > 0 && letters(second) > 0 {
  if same(first, second) {
    label "They are anagrams";
  } else {
    label "Not anagrams";
  }
}

// Anagram hunt: find rearrangements of listen; type one and press Check to add it to the list.
// icon: ring 10 10 7 line 15 15 21 21 line 7 7 7 13 10 13
state guess = "";
state found = [""; 0];
state note = "";

fn count(s: string, ch: string) -> int {
  let n = 0;
  for i in 0..len(s) {
    if s[i] == ch { n += 1; }
  }
  return n;
}

// The same letters as the word, each as many times.
fn anagram(s: string, w: string) -> bool {
  if len(s) != len(w) { return false; }
  for i in 0..len(w) {
    if count(s, w[i]) != count(w, w[i]) { return false; }
  }
  return true;
}

fn known(s: string) -> bool {
  for i in 0..len(found) {
    if found[i] == s { return true; }
  }
  return false;
}

fn check() {
  if guess == "listen" {
    note = "That's the word itself";
  } else if !anagram(guess, "listen") {
    note = "Not an anagram";
  } else if known(guess) {
    note = "Already found";
  } else {
    push(found, guess);
    note = "Found one!";
  }
  guess = "";
}

label "Anagram hunt";
label "Rearrange: listen";
row {
  input guess;
  button "Check" { check(); }
}
label note;
label "Found: " + len(found);
for i in 0..len(found) { label found[i]; }

