// Division helper: type a whole number and what to divide it by; it shows the quotient, the
// remainder and the answer as a mixed number in lowest terms.
// icon: line 4 12 20 12 dot 12 6 2 dot 12 18 2
state top = "";
state bottom = "";

fn num(s: string) -> int { return min(max(parse(s, 0), 0), 1000000000); }

// The greatest common divisor, by Euclid.
fn gcd(a: int, b: int) -> int {
  let p = a;
  let q = b;
  while q != 0 {
    let t = p % q;
    p = q;
    q = t;
  }
  return p;
}

fn mixed(a: int, b: int) -> string {
  let whole = a / b;
  let r = a % b;
  if r == 0 { return "" + whole; }
  let g = gcd(r, b);
  let f = r / g + "/" + b / g;
  if whole == 0 { return f; }
  return whole + " " + f;
}

label "Division helper";
row {
  label "Divide";
  input top;
}
row {
  label "by";
  input bottom;
}
if num(bottom) == 0 {
  label "Can't divide by 0";
} else {
  label "Quotient: " + num(top) / num(bottom);
  label "Remainder: " + num(top) % num(bottom);
  label "Mixed: " + mixed(num(top), num(bottom));
}

// Long division: type a whole number and what to divide it by; it divides to as many decimal
// places as you choose with More and Fewer, cut off rather than rounded.
// icon: line 4 5 21 5 line 4 5 7 10 7 15 4 20 dot 12 13 2 dot 17 13 2
state top = "";
state bottom = "";
state places = 2;

fn num(s: string) -> int { return min(max(parse(s, 0), 0), 1000000000); }

// The whole part, then one digit per place: the remainder times ten, divided again.
fn divide(a: int, b: int, p: int) -> string {
  let s = "" + a / b;
  let r = a % b;
  if p > 0 { s = s + "."; }
  repeat p {
    r = r * 10;
    s = s + r / b;
    r = r % b;
  }
  return s;
}

label "Long division";
row {
  input top;
  label "divided by";
  input bottom;
}
row {
  button "Fewer" { places = max(0, places - 1); }
  label "Places: " + places;
  button "More" { places = min(8, places + 1); }
}
if num(bottom) == 0 {
  label "Can't divide by 0";
} else {
  label "Result: " + divide(num(top), num(bottom), places);
}

// Download time: type a file's size in MB and the speed in Mbps; it shows how long the download
// takes, rounded up to a second.
