state size = "";
state speed = "";

fn num(s: string) -> int { return min(max(parse(s, 0), 0), 1000000000); }

// Megabits over megabits a second, rounded up.
fn seconds() -> int {
  let bits = num(size) * 8;
  return (bits + num(speed) - 1) / num(speed);
}

fn two(n: int) -> string {
  if n < 10 { return "0" + n; }
  return "" + n;
}

fn clock(t: int) -> string { return t / 3600 + ":" + two(t / 60 % 60) + ":" + two(t % 60); }

label "Download time";
row {
  label "Size (MB)";
  input size;
}
row {
  label "Speed (Mbps)";
  input speed;
}
if num(size) > 0 && num(speed) > 0 {
  label "Seconds: " + seconds();
  label "Time: " + clock(seconds());
}

// Download simulator: type a size in MB and a speed in MB a second, then Start; it shows how much
// is in and the seconds left. Pause and Resume.
// icon: loop 3 9 21 9 21 15 3 15 fill 3 9 13 9 13 15 3 15 line 12 3 12 6 line 10 19 14 19
state size = "";
state speed = "";
state got = 0;
state tick = 0;          // ms a step: 1000 while it downloads, else 0
state paused = false;
state started = false;

fn num(s: string) -> int { return min(max(parse(s, 0), 0), 1000000000); }

fn total() -> int { return num(size); }

// The seconds still to go, rounded up.
fn left() -> int {
  if num(speed) == 0 { return 0; }
  return (max(0, total() - got) + num(speed) - 1) / num(speed);
}

fn begin() {
  got = 0;
  started = true;
  paused = false;
  tick = 1000;
}

every tick {
  got = min(total(), got + num(speed));
  if got >= total() { tick = 0; }
}

label "Download simulator";
row {
  label "Size (MB)";
  input size;
}
row {
  label "Speed (MB/s)";
  input speed;
}
label "Got: " + got + " of " + total() + " MB";
label "Left: " + left() + " s";
if started && got >= total() { label "Download complete"; }
row {
  button "Start" { begin(); }
  if tick > 0 {
    button "Pause" {
      tick = 0;
      paused = true;
    }
  }
  if paused {
    button "Resume" {
      paused = false;
      tick = 1000;
    }
  }
}

