state starts = [0, 31, 59, 90, 120, 151, 181, 212, 243, 273, 304, 334];

fn num(s: string) -> int { return parse(s, 0); }

fn valid(m: int, d: int) -> bool { return m >= 1 && m <= 12 && d >= 1 && d <= 31; }

// The day of the year, 1 to 365.
fn yday(m: int, d: int) -> int { return starts[m - 1] + d; }

// Days from today to friend i's next birthday.
fn until(i: int) -> int {
  return (yday(months[i], days[i]) - yday(num(tm), num(td)) + 365) % 365;
}

fn soonest() -> int {
  let best = 0;
  for i in 1..len(names) {
    if until(i) < until(best) { best = i; }
  }
  return best;
}

fn add() {
  if who != "" && valid(num(bm), num(bd)) {
    push(names, who);
    push(months, num(bm));
    push(days, num(bd));
    who = "";
  }
}

