fn phtext() -> string { return "pH: " + ph / 10 + "." + ph % 10; }

fn phok() -> bool { return ph >= 72 && ph <= 78; }

fn clok() -> bool { return cl >= 1 && cl <= 3; }

fn phsays() -> string {
  if ph < 72 { return "pH low"; }
  if ph > 78 { return "pH high"; }
  return "pH ok";
}

fn clsays() -> string {
  if cl < 1 { return "Chlorine low"; }
  if cl > 3 { return "Chlorine high"; }
  return "Chlorine ok";
}

