// Chlorine dose: type the pool's liters, the chlorine it has and the chlorine wanted in ppm; it
// says how many grams of 65% product to add.
// icon: loop 6 3 18 3 20 21 4 21 line 6 9 18 9 dot 12 15 3
state volume = "";
state now = "";
state want = "";

fn num(s: string) -> int { return min(max(parse(s, 0), 0), 100000000); }

// 1 g of chlorine a ppm per 1,000 L, and 100 g of product hold 65 g: liters x ppm / 650,
// rounded up.
fn grams() -> int {
  let d = min(num(want), 1000) - min(num(now), 1000);
  return (num(volume) * d + 649) / 650;
}

