// Cornhole: record each bag as Hole, Board or Miss; after both teams' four bags the inning is
// scored by cancellation. The first team at 21 or more after an inning wins.
// icon: loop 7 3 17 3 20 21 4 21 ring 12 8 3
state names = ["Red", "Blue"];
state score = [0, 0];     // the game's scores: Red, Blue
state pts = [0, 0];       // this inning's points
state lead = 0;           // the team that throws first this inning: 0 Red, 1 Blue
state bags = 0;           // the bags thrown this inning
state inning = 1;
state winner = -1;

fn thrower() -> int { return (lead + bags) % 2; }

// Cancellation: the difference goes to the team with more; the next inning starts with them.
fn settle() {
  let d = pts[0] - pts[1];
  if d > 0 {
    score[0] += d;
    lead = 0;
  } else if d < 0 {
    score[1] -= d;
    lead = 1;
  }
  pts = [0, 0];
  bags = 0;
  inning += 1;
  if score[0] >= 21 { winner = 0; }
  if score[1] >= 21 { winner = 1; }
}

fn throw(p: int) {
  if winner >= 0 { return; }
  pts[thrower()] += p;
  bags += 1;
  if bags == 8 { settle(); }
}

label "Cornhole";
label "Red: " + score[0] + "   Blue: " + score[1];
label "Inning: " + inning;
if winner >= 0 {
  label names[winner] + " wins";
  button "New game" {
    score = [0, 0];
    pts = [0, 0];
    lead = 0;
    bags = 0;
    inning = 1;
    winner = -1;
  }
} else {
  label names[thrower()] + " to throw";
}
row {
  button "Hole" { throw(3); }
  button "Board" { throw(1); }
  button "Miss" { throw(0); }
}

