// Sim: tap a dot, then another, to join them in your color; Red and Blue take turns. Whoever
// makes a triangle of their own color loses.
// icon: line 12 3 20 8 20 16 12 21 4 16 4 8 12 3 line 12 3 20 16 line 4 8 20 8
state px = [104, 184, 184, 104, 24, 24];   // the dots
state py = [14, 54, 154, 194, 154, 54];
state own = [0; 36];      // the line between dots a and b: 0 none, 1 red, 4 blue
state turn = 1;           // the player's color: 1 Red, 4 Blue
state pick = -1;
state loser = 0;

fn who(c: int) -> string { return c == 1 ? "Red" : "Blue"; }

// The dot within 10 units of (u, v), else -1.
fn dot(u: int, v: int) -> int {
  for i in 0..6 {
    if (u - px[i]) * (u - px[i]) + (v - py[i]) * (v - py[i]) <= 100 { return i; }
  }
  return -1;
}

fn join(a: int, b: int) {
  pick = -1;
  if own[a * 6 + b] != 0 { return; }
  own[a * 6 + b] = turn;
  own[b * 6 + a] = turn;
  for k in 0..6 {
    if own[a * 6 + k] == turn && own[b * 6 + k] == turn { loser = turn; }
  }
  if loser == 0 { turn = 5 - turn; }
}

fn tap(u: int, v: int) {
  let d = dot(u, v);
  if loser != 0 || d < 0 { return; }
  if pick < 0 {
    pick = d;
  } else if pick == d {
    pick = -1;
  } else {
    join(pick, d);
  }
}

fn scene() {
  for a in 0..6 {
    for b in a + 1..6 {
      if own[a * 6 + b] != 0 { line(px[a], py[a], px[b], py[b], 3, own[a * 6 + b]); }
    }
  }
  for i in 0..6 { circle(px[i], py[i], 6, i == pick ? 3 : 9); }
}

label "Sim";
