}

// Sim: tap two dot numbers to join them in your color, red first, then blue. A line can be
// drawn once; whoever makes a triangle all in their own color loses.
// icon: line 12 3 20 8 20 16 12 21 4 16 4 8 12 3 line 12 3 20 16 line 4 8 20 8
state own = [0; 36];      // the line between dots a and b: 0 none, 1 red, 4 blue
state turn = 1;
state pick = -1;
state loser = 0;

fn who(c: int) -> string { return c == 1 ? "Red" : "Blue"; }

// Dot i's place, round a circle.
fn ax(i: int) -> int { return 60 + sin(i * 60) / 20; }
fn ay(i: int) -> int { return 60 - cos(i * 60) / 20; }

fn choose(d: int) {
  if loser != 0 { return; }
  if pick < 0 {
    pick = d;
    return;
  }
  let a = pick;
  pick = -1;
  if a == d || own[a * 6 + d] != 0 { return; }
  own[a * 6 + d] = turn;
  own[d * 6 + a] = turn;
  for k in 0..6 {
    if own[a * 6 + k] == turn && own[d * 6 + k] == turn { loser = turn; }
  }
  if loser == 0 { turn = 5 - turn; }
}

fn scene() {
  for a in 0..6 {
    for b in 0..6 {
      if own[a * 6 + b] != 0 { line(ax(a), ay(a), ax(b), ay(b), 2, own[a * 6 + b]); }
    }
  }
  for i in 0..6 {
    circle(ax(i), ay(i), 7, i == pick ? 3 : 7);
    text(i + 1, ax(i), ay(i), 8, 9);
  }
}

label "Sim";
canvas 120, 120, scene();
row {
  for i in 0..6 { button "" + (i + 1) { choose(i); } }
}
if loser != 0 { label who(loser) + " loses!"; } else { label who(turn) + " to play"; }

// Bunco solitaire: Roll three dice; the target is the round's number. A bunco (three targets)
// scores 21, three of a kind 5, else a point a target; a roll scoring nothing ends the round.
// icon: loop 3 6 13 6 13 16 3 16 dot 8 11 2 loop 11 9 21 9 21 19 11 19 dot 14 12 1 dot 18 16 1
state order = [1, 3, 1, 4, 4, 4, 2, 5, 6, 1, 1, 1, 3, 2, 3, 6, 6, 2, 5, 5, 5, 2, 2, 2, 3, 4, 5, 6, 1, 4];
state k = 0;              // the next die of the first game's order
state first = true;
state dice = [0, 0, 0];
state rnd = 1;
state pts = 0;
state total = 0;
state buncos = 0;
state over = false;

fn die() -> int {
  if !first { return 1 + random(6); }
  let d = order[k % len(order)];
  k += 1;
  return d;
}

fn points() -> int {
  if dice[0] == dice[1] && dice[1] == dice[2] {
    if dice[0] == rnd { return 21; }
    return 5;
  }
  let n = 0;
  for i in 0..3 {
    if dice[i] == rnd { n += 1; }
  }
  return n;
}

fn roll() {
  if over { return; }
  for i in 0..3 { dice[i] = die(); }
  let s = points();
  if s == 21 { buncos += 1; }
  if s > 0 {
    pts += s;
    total += s;
  } else if rnd == 6 {
    over = true;
  } else {
    rnd += 1;
    pts = 0;
  }
}

label "Bunco solitaire";
label "Round: " + rnd;
if dice[0] > 0 { label "Rolled: " + dice[0] + " " + dice[1] + " " + dice[2]; }
label "Round points: " + pts;
label "Total: " + total;
label "Buncos: " + buncos;
if over {
  label "Game over: " + total + " points";
  button "New game" {
    first = false;
    dice = [0, 0, 0];
    rnd = 1;
    pts = 0;
    total = 0;
    buncos = 0;
    over = false;
  }
} else {
  button "Roll" { roll(); }
}

// Bunco scorer: tap the three dice you rolled; they score for the round (a point a die showing
// it, 5 for three of a kind, 21 for a bunco). Next round moves on, up to round 6.
// icon: loop 3 6 13 6 13 16 3 16 dot 8 11 2 loop 11 9 21 9 21 19 11 19 dot 14 12 1 dot 18 16 1
state rnd = 1;
state total = 0;
state dice = [0; 0];

fn score() -> int {
  if dice[0] == dice[1] && dice[1] == dice[2] { return dice[0] == rnd ? 21 : 5; }
  let n = 0;
  for i in 0..3 {
    if dice[i] == rnd { n += 1; }
  }
  return n;
}

fn tapped(d: int) {
  if len(dice) == 3 { clear(dice); }
  push(dice, d);
  if len(dice) == 3 { total += score(); }
}

fn shown() -> string {
  let s = "";
  for i in 0..len(dice) { s = s + dice[i] + " "; }
  return s;
}

label "Bunco";
label "Round " + rnd;
row {
  for d in 1..7 { button "" + d { tapped(d); } }
}
label "Dice: " + shown();
label "Total: " + total;
button "Next round" {
  if rnd < 6 {
    rnd += 1;
    clear(dice);
  }
}

// Sandpile: Start drops a grain on the middle square every 200 ms; a square with 4 grains
// topples one onto each neighbor. Yellow 1, green 2, blue 3 grains.
// icon: fill 12 4 21 20 3 20 line 6 15 18 15
state board = [0; 81];
state grains = 0;
state topples = 0;
state speed = 0;          // 200 while it runs
state tint = [-1, 3, 2, 4];

fn settle() {
  let busy = true;
  while busy {
    busy = false;
    for i in 0..81 {
      if board[i] >= 4 {
        board[i] -= 4;
        topples += 1;
        busy = true;
        let c = i % 9;
        let r = i / 9;
        if c > 0 { board[i - 1] += 1; }
        if c < 8 { board[i + 1] += 1; }
        if r > 0 { board[i - 9] += 1; }
        if r < 8 { board[i + 9] += 1; }
      }
    }
  }
}

fn scene() {
  let b = [-1; 81];
  for i in 0..81 { b[i] = tint[board[i]]; }
  pixels(b, 0, 0, 9, 12);
}

every speed {
  board[40] += 1;
  grains += 1;
  settle();
}

label "Sandpile";
canvas 108, 108, scene();
label "Grains: " + grains + "   Topples: " + topples;
row {
  if speed == 0 { button "Start" { speed = 200; } } else { button "Stop" { speed = 0; } }
  button "Clear" {
    board = [0; 81];
    grains = 0;
    topples = 0;
    speed = 0;
  }
}

// Sandpile: tap a square to drop a grain on it. A square with 4 grains topples one onto each
// neighbor; grains off the edge are lost. Yellow 1, green 2, blue 3.
// icon: fill 12 4 21 20 3 20 line 6 15 18 15
state sand = [0; 49];
state tint = [0, 3, 2, 4];

fn drop(i: int) {
  sand[i] += 1;
  let busy = true;
  while busy {
    busy = false;
    for j in 0..49 {
      if sand[j] >= 4 {
        sand[j] -= 4;
        busy = true;
        if j % 7 > 0 { sand[j - 1] += 1; }
        if j % 7 < 6 { sand[j + 1] += 1; }
        if j >= 7 { sand[j - 7] += 1; }
        if j < 42 { sand[j + 7] += 1; }
      }
    }
  }
}

fn shades() -> [int] {
  let b = [0; 49];
  for i in 0..49 { b[i] = tint[sand[i]]; }
  return b;
}

label "Sandpile";
grid 7, shades() { drop(cell); }

// Table plan: tap a guest, then a table, to seat them (or move them) there; three to a table.
// Cal and Dot must not share one.
// icon: ring 12 12 5 dot 12 3 2 dot 20 12 2 dot 12 21 2 dot 4 12 2
state names = ["Ann", "Ben", "Cal", "Dot", "Eve", "Fin", "Gus", "Hen"];
state seat = [0; 8];      // each guest's table, 0 not seated
state order = [0; 0];     // the guests in the order they sat down
state picked = -1;
state full = 0;           // the table just found full, 0 none

fn count(t: int) -> int {
  let n = 0;
  for g in 0..8 {
    if seat[g] == t { n += 1; }
  }
  return n;
}

fn listed(t: int) -> string {
  let s = "";
  for k in 0..len(order) {
    if seat[order[k]] == t { s = s + (s == "" ? "" : ", ") + names[order[k]]; }
  }
  return s == "" ? "empty" : s;
}

fn sit(t: int) {
  full = 0;
  if picked < 0 || seat[picked] == t {
    picked = -1;
    return;
  }
  if count(t) >= 3 {
    full = t;
    return;
  }
  for k in 0..len(order) {
    if order[k] == picked {
      remove(order, k);
      break;
