// Sieve of Eratosthenes, 1 to 100: each Step makes the smallest undecided number a prime
// (green) and crosses out its multiples (red); past 10 the rest are primes.
// icon: loop 3 3 21 3 21 21 3 21 line 3 12 21 12 line 12 3 12 21 fill 5 5 10 5 10 10 5 10
state hue = [4; 100];     // number n's color at n - 1: 4 undecided, 2 prime, 1 crossed out
state prime = 0;          // the last prime found, 0 none
