fn count(c: int) -> int {
  let k = 0;
  for i in 1..100 {
    if hue[i] == c { k += 1; }
  }
  return k;
}

fn step() {
  if done { return; }
  let p = 2;
  while hue[p - 1] != 4 { p += 1; }
  if p > 10 {
    for i in 1..100 {
      if hue[i] == 4 { hue[i] = 2; }
    }
    done = true;
    return;
  }
  prime = p;
  hue[p - 1] = 2;
  for m in p * 2..101 {
    if m % p == 0 && hue[m - 1] == 4 { hue[m - 1] = 1; }
  }
}

// The board's colors: 1 is gray, neither prime nor crossed out.
fn colors() -> [int] {
  let b = hue;
  b[0] = 8;
  return b;
}

fn numbers() -> [string] {
  let s = [""; 100];
  for i in 0..100 { s[i] = "" + (i + 1); }
  return s;
}

