// Sieve of Eratosthenes: type a number and press Go to list every prime up to it, and how
// many there are.
// icon: loop 3 3 21 3 21 21 3 21 line 3 12 21 12 line 12 3 12 21 fill 5 5 10 5 10 10 5 10
state typed = "";
