fn sieve(n: int) {
  clear(found);
  let out = [false; 0];
  for i in 0..n + 1 { push(out, i < 2); }
  for p in 2..n + 1 {
    if !out[p] {
      push(found, p);
      let m = p * p;
      while m <= n {
        out[m] = true;
        m += p;
      }
    }
  }
}

fn listed() -> string {
  let s = "";
  for i in 0..len(found) { s = s + found[i] + " "; }
  return s;
}

