// Mu torere: tap one of your red pieces to slide it into the empty square; the computer plays
// blue. A piece goes into the centre only beside an enemy piece. Whoever cannot move loses.
// icon: line 12 2 12 22 line 2 12 22 12 line 5 5 19 19 line 19 5 5 19 dot 12 12 3
state board = [1, 1, 1, 1, 4, 4, 4, 4, 0];   // the ring clockwise from the top left, then the centre
state cols = [0, 1, 2, 2, 2, 1, 0, 0, 1];      // each square's column and row on the 3 x 3 board
state rows = [0, 0, 0, 1, 2, 2, 2, 1, 1];
state over = 0;                                // 0 playing, 1 you won, 2 you lost
state won = 0;
state lost = 0;

fn gap(b: [int]) -> int {
  for i in 0..9 {
    if b[i] == 0 { return i; }
  }
  return 8;
}

// Whether the piece on square i may move into the empty square.
fn may(b: [int], i: int) -> bool {
  let g = gap(b);
  if b[i] == 0 { return false; }
  if i == 8 { return true; }
  if g == 8 { return b[(i + 1) % 8] == 5 - b[i] || b[(i + 7) % 8] == 5 - b[i]; }
  return (i + 1) % 8 == g || (i + 7) % 8 == g;
}

// The first piece of color p that may move: the centre, then round the ring; -1 if none.
fn first(b: [int], p: int) -> int {
  for k in 0..9 {
    let i = (k + 8) % 9;
    if b[i] == p && may(b, i) { return i; }
  }
  return -1;
}

fn moved(b: [int], i: int) -> [int] {
  let c = b;
  c[gap(b)] = b[i];
  c[i] = 0;
  return c;
}

// Blue's move: one that leaves red stuck, else its first piece that may move.
fn answer() {
  let pick = -1;
  for k in 0..9 {
    let i = (k + 8) % 9;
    if pick < 0 && board[i] == 4 && may(board, i) && first(moved(board, i), 1) < 0 { pick = i; }
  }
  if pick < 0 { pick = first(board, 4); }
  board = moved(board, pick);
  if first(board, 1) < 0 {
    over = 2;
    lost += 1;
  }
}

fn play(c: int, r: int) {
  if over > 0 { return; }
  for i in 0..9 {
    if cols[i] == c && rows[i] == r && board[i] == 1 && may(board, i) {
      board = moved(board, i);
      if first(board, 4) < 0 {
        over = 1;
        won += 1;
      } else {
        answer();
      }
      return;
    }
  }
}

fn px(i: int) -> int { return 20 + cols[i] * 40; }
fn py(i: int) -> int { return 20 + rows[i] * 40; }

// The board: the ring and its spokes to the centre, a piece on each square but the empty one.
fn scene() {
  for i in 0..8 {
    line(px(i), py(i), px((i + 1) % 8), py((i + 1) % 8), 1, 8);
    line(px(i), py(i), 60, 60, 1, 8);
  }
  for i in 0..9 {
    if board[i] > 0 { circle(px(i), py(i), 15, board[i]); } else { ring(px(i), py(i), 15, 1, 8); }
  }
}

