// Mu torere for two: red goes first; tap one of your pieces to slide it into the empty square.
// A piece goes into the centre only beside an enemy piece. Whoever cannot move loses.
// icon: line 12 2 12 22 line 2 12 22 12 line 5 5 19 19 line 19 5 5 19 dot 12 12 3
state board = [1, 1, 1, 1, 4, 4, 4, 4, 0];   // the ring clockwise from the top left, then the centre
state cols = [0, 1, 2, 2, 2, 1, 0, 0, 1];
state rows = [0, 0, 0, 1, 2, 2, 2, 1, 1];
state turn = 1;                                // 1 red, 4 blue
state winner = 0;

fn gap() -> int {
  for i in 0..9 {
    if board[i] == 0 { return i; }
  }
  return 8;
}

// Whether the piece on square i may move into the empty square.
fn may(i: int) -> bool {
  let g = gap();
  if board[i] == 0 { return false; }
  if i == 8 { return true; }
  if g == 8 { return board[(i + 1) % 8] == 5 - board[i] || board[(i + 7) % 8] == 5 - board[i]; }
  return (i + 1) % 8 == g || (i + 7) % 8 == g;
}

fn stuck(p: int) -> bool {
  for i in 0..9 {
    if board[i] == p && may(i) { return false; }
  }
  return true;
}

fn play(c: int, r: int) {
  if winner > 0 { return; }
  for i in 0..9 {
    if cols[i] == c && rows[i] == r && board[i] == turn && may(i) {
      board[gap()] = turn;
      board[i] = 0;
      turn = 5 - turn;
      if stuck(turn) { winner = 5 - turn; }
      return;
    }
  }
}

fn px(i: int) -> int { return 20 + cols[i] * 40; }
fn py(i: int) -> int { return 20 + rows[i] * 40; }

fn scene() {
  for i in 0..8 {
    line(px(i), py(i), px((i + 1) % 8), py((i + 1) % 8), 1, 8);
    line(px(i), py(i), 60, 60, 1, 8);
  }
  for i in 0..9 {
    if board[i] > 0 { circle(px(i), py(i), 15, board[i]); }
  }
}

fn named(p: int) -> string { return p == 1 ? "Red" : "Blue"; }

