state secs = 0;
state count = 0;
state speed = 0;          // 1000 while the workout runs

fn total() -> int {
  let t = 0;
  for i in 0..len(rounds) { t += rounds[i]; }
  return t;
}

every speed {
  secs -= 1;
  if secs > 0 { return; }
