// Pascal's triangle by divisibility: each number is blue if the divisor (2, 3, 5 or 7)
// divides it, red if not. Tap a number to read it.
// icon: dot 12 4 2 dot 8 10 2 dot 16 10 2 dot 4 16 2 dot 12 16 2 dot 20 16 2
state d = 2;              // the divisor
state picked = 1;         // the number tapped last
state divisors = [2, 3, 5, 7];

// C(n, k): each step's product divides evenly by i + 1.
fn choose(n: int, k: int) -> int {
  let c = 1;
  for i in 0..k { c = c * (n - i) / (i + 1); }
  return c;
}

// Squares of the 16 x 16 board, row n's numbers in its first n + 1 squares.
fn board() -> [int] {
  let b = [-1; 256];
  for n in 0..16 {
    for k in 0..n + 1 { b[n * 16 + k] = choose(n, k) % d == 0 ? 4 : 1; }
  }
  return b;
}

fn divisible() -> int {
  let c = 0;
  for n in 0..16 {
    for k in 0..n + 1 {
      if choose(n, k) % d == 0 { c += 1; }
    }
  }
  return c;
}

fn scene() { pixels(board(), 0, 0, 16, 8); }

label "Pascal's triangle";
row {
  for i in 0..4 { button "" + divisors[i] { d = divisors[i]; } }
}
label "Divisor: " + d + "   Divisible: " + divisible();
canvas 128, 128, scene() {
  if x / 8 <= y / 8 { picked = choose(y / 8, x / 8); }
}
label "Value: " + picked;

// Pascal's triangle: each number is the sum of the two above it. Add row and Remove row make
