// C(n, k): each step's product divides evenly by i + 1.
fn choose(n: int, k: int) -> int {
  let c = 1;
  for i in 0..k { c = c * (n - i) / (i + 1); }
  return c;
}

fn numbers(n: int) -> string {
  let s = "1";
  for k in 1..n + 1 { s = s + "  " + choose(n, k); }
  return s;
}

// Each row centred under the one above.
