fn up(i: int) -> bool { return cells[i] >= 0 && day - sown[i] >= grow[cells[i]]; }

// The tray's squares: gray while a seed waits, its plant's color once it is up.
fn tray() -> [int] {
  let b = [0; 24];
  for i in 0..24 {
    if up(i) { b[i] = cells[i] + 1; } else if cells[i] >= 0 { b[i] = 8; }
  }
  return b;
}

fn count(sprouted: bool) -> int {
  let n = 0;
  for i in 0..24 {
    if cells[i] >= 0 && (!sprouted || up(i)) { n += 1; }
  }
  return n;
}

