// Estimation: press Start; each round's dots show for 3 seconds. Type how many you think there
// were and press Guess: 10 points, less one for each you are off. Five rounds.
// icon: dot 6 7 2 dot 13 5 2 dot 18 10 2 dot 8 14 2 dot 15 17 2 dot 5 20 2 dot 20 19 2
state counts = [23, 41, 17, 56, 34];
state dots = [0; 100];    // 4 where a dot is
state round = -1;         // -1 before the first game
state left = 0;           // tenths of a second the dots still show
state speed = 0;          // 100 while they show
state guessed = false;
state typed = "";
state points = 0;
state total = 0;

// A round: its dots on squares chosen at random, each the first free one from a random place.
fn deal() {
  dots = [0; 100];
  for j in 0..counts[round] {
    let k = random(100);
    let placed = false;
    for i in 0..100 {
      if !placed && dots[(k + i) % 100] == 0 {
        dots[(k + i) % 100] = 4;
        placed = true;
      }
    }
  }
  guessed = false;
  typed = "";
  left = 30;
  speed = 100;
}

every speed {
  left -= 1;
  if left == 0 { speed = 0; }
}

fn guess() {
  let g = parse(typed, -1);
  if round < 0 || guessed || g < 0 { return; }
  guessed = true;
  speed = 0;
  points = max(0, 10 - abs(g - counts[round]));
  total += points;
}

fn board() -> [int] {
  if speed > 0 || guessed { return dots; }
  return [0; 100];
}

label "Estimation";
grid 10, board();
if round >= 0 && round < 5 {
  row {
    input typed;
    button "Guess" { guess(); }
  }
}
if guessed { label "Answer: " + counts[round] + "   Points: " + points; }
label "Total: " + total;
if guessed && round == 4 { label "Final: " + total; }
