// Shiritori for two: Red, then Blue, each plays a word that starts with the last letter of the
// one before, within 15 seconds. A repeat, a wrong letter or a word ending in n loses.
// icon: loop 3 5 13 5 13 12 8 12 5 15 5 12 3 12 loop 11 10 21 10 21 17 19 17 19 20 16 17 11 17
state names = ["Red", "Blue"];
state words = [""; 0];    // the chain, in order
state typed = "";
state turn = 0;           // 0 Red, 1 Blue
state winner = -1;
state secs = 15;
state speed = 0;          // 1000 while a game runs

fn last(w: string) -> string { return w[len(w) - 1]; }

fn used(w: string) -> bool {
  for i in 0..len(words) {
    if words[i] == w { return true; }
  }
  return false;
}

fn lose() {
  winner = 1 - turn;
  speed = 0;
}

fn play() {
  if speed == 0 || len(typed) < 2 { return; }
  if len(words) > 0 && typed[0] != last(words[len(words) - 1]) || used(typed) || last(typed) == "n" {
    lose();
    return;
  }
  push(words, typed);
  typed = "";
  turn = 1 - turn;
  secs = 15;
}

every speed {
  secs -= 1;
  if secs == 0 { lose(); }
}

on key "enter" { play(); }

fn chain() -> string {
  let s = "";
  for i in 0..len(words) { s = s + words[i] + " "; }
  return s;
}

label "Shiritori";
if winner >= 0 {
  label names[winner] + " wins!";
} else if speed > 0 {
  label names[turn] + "'s turn   Time: " + secs;
}
if len(words) > 0 && winner < 0 { label "Next letter: " + last(words[len(words) - 1]); }
label chain();
row {
