// Shiritori: type a word and press OK (or enter); each must start with the last letter of the
// one before, and none twice. A broken rule ends the chain; Start again begins a new one.
// icon: loop 3 5 13 5 13 12 8 12 5 15 5 12 3 12 loop 11 10 21 10 21 17 19 17 19 20 16 17 11 17
state words = [""; 0];    // the chain so far
state typed = "";
state over = "";          // why the chain ended; "" while it runs

fn last(w: string) -> string { return w[len(w) - 1]; }

fn used(w: string) -> bool {
  for i in 0..len(words) {
    if words[i] == w { return true; }
  }
  return false;
}

fn say() {
  if over != "" || typed == "" { return; }
  if len(words) > 0 && typed[0] != last(words[len(words) - 1]) {
    over = typed + " doesn't start with " + last(words[len(words) - 1]);
  } else if used(typed) {
    over = typed + " was used already";
  } else {
    push(words, typed);
  }
  typed = "";
}

on key "enter" { say(); }

label "Shiritori";
for i in 0..len(words) { label words[i]; }
if over == "" {
  row {
    input typed;
    button "OK" { say(); }
  }
