// Virus drop: pills fall into the bottle; left and right move them, up turns, down steps, space
// drops. Four of a color in a line vanish; clear every virus to win.
// icon: fill 3 8 12 8 12 16 3 16 loop 12 8 21 8 21 16 12 16
state cells = [0; 96];        // the bottle, 8 x 12: 0 empty, 1 red, 3 yellow, 4 blue
state germ = [false; 96];     // which of them are viruses
state mate = [-1; 96];        // a landed half's other half, -1 none
state pa = [4, 1, 3, 3, 1];   // the pills as they come, left halves
state pb = [3, 1, 4, 3, 4];   // and right halves
state nxt = 0;                // pills dealt
state hx = [0, 0];            // the falling pill's halves: the first is the left one lying,
state hy = [0, 0];            // the top one standing
state hc = [0, 0];
state falling = false;
state speed = 0;              // ms a row; 0 while nothing falls
state won = false;
state over = false;

fn free(c: int, r: int) -> bool {
  return c >= 0 && c < 8 && r >= 0 && r < 12 && cells[r * 8 + c] == 0;
}

fn viruses() -> int {
  let n = 0;
  for i in 0..96 {
    if germ[i] { n += 1; }
  }
  return n;
}

fn spawn() {
  hx = [3, 4];
  hy = [0, 0];
  hc = [pa[nxt % 5], pb[nxt % 5]];
  nxt += 1;
  falling = cells[3] == 0 && cells[4] == 0;
  over = !falling;
  if over { speed = 0; }
}

fn setup() {
  cells = [0; 96];
  germ = [false; 96];
  mate = [-1; 96];
  let at = [89, 90, 91, 86, 94, 79, 87, 95];
  let hue = [1, 1, 1, 4, 4, 3, 3, 3];
  for k in 0..8 {
    cells[at[k]] = hue[k];
    germ[at[k]] = true;
  }
  nxt = 0;
  won = false;
  speed = 1000;
  spawn();
}

fn shift(dc: int, dr: int) -> bool {
  if !falling || !free(hx[0] + dc, hy[0] + dr) || !free(hx[1] + dc, hy[1] + dr) { return false; }
  hx = [hx[0] + dc, hx[1] + dc];
  hy = [hy[0] + dr, hy[1] + dr];
  return true;
}

// A quarter turn clockwise keeping the bottom left square: lying, the left half goes on top of
// the right one; standing, the bottom half goes left of the top one.
fn turn() {
  if !falling { return; }
  if hy[0] == hy[1] {
    if free(hx[0], hy[0] - 1) {
      hx = [hx[0], hx[0]];
      hy = [hy[0] - 1, hy[0]];
    }
  } else if free(hx[1] + 1, hy[1]) {
    hx = [hx[1], hx[1] + 1];
    hy = [hy[1], hy[1]];
    hc = [hc[1], hc[0]];
  }
}

// Fours or more of a color in a line, across or down.
fn lines() -> [bool] {
  let hit = [false; 96];
  for i in 0..96 {
    let k = cells[i];
    if k > 0 {
      let n = 1;
      while i % 8 + n < 8 && cells[i + n] == k { n += 1; }
      if n >= 4 { for m in 0..n { hit[i + m] = true; } }
      n = 1;
      while i + n * 8 < 96 && cells[i + n * 8] == k { n += 1; }
      if n >= 4 { for m in 0..n { hit[i + m * 8] = true; } }
    }
  }
  return hit;
}

fn lower(i: int) {
  cells[i + 8] = cells[i];
  cells[i] = 0;
  let j = mate[i];
  mate[i + 8] = j;
  mate[i] = -1;
  if j >= 0 { mate[j] = i + 8; }
}

// Halves with nothing under them fall, a row at a time; a pill's halves fall together.
fn sink() {
  let moved = true;
  while moved {
    moved = false;
    for k in 0..88 {
      let i = 87 - k;
      let j = mate[i];
      if cells[i] > 0 && !germ[i] && cells[i + 8] == 0 {
        if j < 0 {
          lower(i);
          moved = true;
        } else if j == i - 8 || (j == i + 1 && cells[j + 8] == 0) {
          lower(i);
          lower(j);
          moved = true;
        }
      }
    }
  }
}

// Lines vanish, what they held up falls, and again while that makes lines.
fn settle() {
  let going = true;
  while going {
    let hit = lines();
    going = false;
    for i in 0..96 {
      if hit[i] {
        going = true;
        cells[i] = 0;
        germ[i] = false;
        if mate[i] >= 0 { mate[mate[i]] = -1; }
        mate[i] = -1;
      }
    }
    if going { sink(); }
  }
}

fn land() {
  let i = hy[0] * 8 + hx[0];
  let j = hy[1] * 8 + hx[1];
  cells[i] = hc[0];
  cells[j] = hc[1];
  mate[i] = j;
  mate[j] = i;
  falling = false;
  settle();
  won = viruses() == 0;
  if won { speed = 0; } else { spawn(); }
}

fn step(dc: int, dr: int) {
  let moved = shift(dc, dr);
}

// The bottle from what it holds, the falling pill over it; viruses have two dark eyes.
fn scene() {
  let px = cells;
  if falling {
    for k in 0..2 { px[hy[k] * 8 + hx[k]] = hc[k]; }
  }
  pixels(px, 0, 0, 8, 10);
  for i in 0..96 {
    if germ[i] {
      rect(i % 8 * 10 + 2, i / 8 * 10 + 2, 2, 2, 9);
      rect(i % 8 * 10 + 6, i / 8 * 10 + 2, 2, 2, 9);
    }
  }
  if nxt == 0 { text("Virus drop", 40, 60, 10, 11); }
  if won { text("You win", 40, 60, 12, 11); }
  if over { text("Game over", 40, 60, 12, 11); }
}

every speed {
  if falling && !shift(0, 1) { land(); }
}

on key "left" { step(-1, 0); }
on key "right" { step(1, 0); }
on key "down" { step(0, 1); }
on key "up" { turn(); }
on key "space" {
  if falling {
    while shift(0, 1) { }
    land();
  }
}

label "Virus drop";
label "Viruses: " + viruses();
canvas 80, 120, scene();
if speed == 0 { button "Start" { setup(); } }

