}

// Halves with nothing under them fall; a pill's two halves fall together.
fn sink() {
  let moved = true;
  while moved {
    moved = false;
    for k in 0..120 {
      let i = 119 - k;
      let j = mate[i];
      if cells[i] > 0 && !germ[i] && cells[i + 8] == 0 {
        if j < 0 {
          lower(i);
          moved = true;
        } else if j == i - 8 || (j == i + 1 && cells[j + 8] == 0) {
          lower(i);
          lower(j);
          moved = true;
        }
      }
    }
  }
}

fn land() {
  let i = hy[0] * 8 + hx[0];
  let j = hy[1] * 8 + hx[1];
  cells[i] = hc[0];
  cells[j] = hc[1];
  mate[i] = j;
  mate[j] = i;
  falling = false;
  let going = true;
  while going {
    let hit = lines();
    going = false;
    for k in 0..128 {
      if hit[k] {
        going = true;
        cells[k] = 0;
        germ[k] = false;
        if mate[k] >= 0 { mate[mate[k]] = -1; }
        mate[k] = -1;
      }
    }
    if going { sink(); }
  }
  won = viruses() == 0;
  if won { speed = 0; } else { spawn(); }
}

fn step(dc: int, dr: int) {
  let moved = shift(dc, dr);
}

fn scene() {
  let px = cells;
  if falling {
    for k in 0..2 { px[hy[k] * 8 + hx[k]] = hc[k]; }
  }
  pixels(px, 0, 0, 8, 10);
  for i in 0..128 {
    if germ[i] { rect(i % 8 * 10 + 2, i / 8 * 10 + 2, 6, 2, 9); }
  }
  if won { text("You win!", 40, 80, 12, 11); }
  if over { text("Game over", 40, 80, 12, 11); }
}

every speed {
  if falling && !shift(0, 1) { land(); }
}

on key "left" { step(-1, 0); }
on key "right" { step(1, 0); }
on key "down" { step(0, 1); }
on key "up" { turn(); }

label "Virus drop";
canvas 80, 160, scene();
if speed == 0 { button "Start" { setup(); } }

// Tak on 4 x 4: tap an empty square to place a flat (or a wall after Wall), or tap your stack, then
// the squares along a line to drop its stones one by one. A road of your flats across wins.
// icon: fill 3 15 21 15 21 21 3 21 fill 5 9 19 9 19 14 5 14 fill 10 2 14 2 14 8 10 8
state st = ["", "", "", "", "", "", "", "", "", "", "", "", "", "", "", ""];   // r b flats, R B walls
state left = [15, 15];
state turn = 0;           // 0 red, 1 blue
state wall = false;       // the next stone placed is a wall
state held = "";          // stones in hand, lowest first
state src = -1;           // the square they came from
state last = -1;          // the last drop, -1 none yet
state step = 0;           // the line's step, as a change of square
state winner = -1;

fn top(i: int) -> string {
  if len(st[i]) == 0 { return ""; }
  return st[i][len(st[i]) - 1];
}

fn whose(i: int) -> int {
  let t = top(i);
  if t == "r" || t == "R" { return 0; }
  if t == "b" || t == "B" { return 1; }
  return -1;
}

fn walled(i: int) -> bool { return top(i) == "R" || top(i) == "B"; }

// Letters a to b - 1 of s.
fn part(s: string, a: int, b: int) -> string {
  let out = "";
  for k in a..b { out = out + s[k]; }
  return out;
}

fn next(i: int, d: int) -> bool {
  if d == 1 { return i % 4 < 3; }
  if d == -1 { return i % 4 > 0; }
  return i + d >= 0 && i + d < 16;
}

// A road: flats of p joined from one edge to the opposite one.
fn road(p: int) -> bool {
  let flat = p == 0 ? "r" : "b";
  for way in 0..2 {
    let seen = [false; 16];
    let todo = [0; 0];
    for k in 0..4 {
      let i = way == 0 ? k * 4 : k;
      if top(i) == flat { seen[i] = true; push(todo, i); }
    }
    while len(todo) > 0 {
      let i = todo[len(todo) - 1];
      remove(todo, len(todo) - 1);
      if (way == 0 && i % 4 == 3) || (way == 1 && i / 4 == 3) { return true; }
      let ds = [1, -1, 4, -4];
      for k in 0..4 {
        if next(i, ds[k]) && !seen[i + ds[k]] && top(i + ds[k]) == flat {
          seen[i + ds[k]] = true;
          push(todo, i + ds[k]);
        }
      }
    }
  }
  return false;
}

fn done() {
  let mine = road(turn);
  let theirs = road(1 - turn);
  if mine { winner = turn; } else if theirs { winner = 1 - turn; }
  turn = 1 - turn;
  wall = false;
}

fn drop(i: int) {
  st[i] = st[i] + held[0];
  held = part(held, 1, len(held));
  last = i;
  if len(held) == 0 {
    src = -1;
    last = -1;
    done();
  }
}

fn tap(i: int) {
  if winner >= 0 { return; }
  if len(held) > 0 {
    if last < 0 && i == src {
      st[i] = st[i] + held;
      held = "";
      src = -1;
    } else if !walled(i) {
      if last < 0 && (i - src == 4 || i - src == -4 || (i - src == 1 && next(src, 1)) || (i - src == -1 && next(src, -1))) {
        step = i - src;
        drop(i);
      } else if last >= 0 && (i == last || (i == last + step && next(last, step))) {
        drop(i);
      }
    }
  } else if len(st[i]) == 0 {
    if left[turn] > 0 {
      st[i] = wall ? (turn == 0 ? "R" : "B") : (turn == 0 ? "r" : "b");
      left[turn] -= 1;
      done();
    }
  } else if whose(i) == turn {
    let k = max(0, len(st[i]) - 4);
    held = part(st[i], k, len(st[i]));
    st[i] = part(st[i], 0, k);
    src = i;
    last = -1;
  }
}

// Each square's top stone: a flat as a disc, a wall as an upright bar; a stack's height in its corner.
fn scene() {
  for i in 0..16 {
    let cx = i % 4 * 25 + 12;
    let cy = i / 4 * 25 + 12;
    rect(cx - 11, cy - 11, 23, 23, 7);
    let hue = whose(i) == 0 ? 1 : 4;
    if walled(i) { rect(cx - 3, cy - 9, 7, 19, hue); } else if whose(i) >= 0 { circle(cx, cy, 8, hue); }
    if len(st[i]) > 1 { text(len(st[i]), cx + 8, cy + 8, 6, 9); }
  }
}

label "Tak";
canvas 100, 100, scene() { tap((y / 25) * 4 + x / 25); }
if winner >= 0 {
  label winner == 0 ? "Red wins" : "Blue wins";
} else {
  label (turn == 0 ? "Red's turn" : "Blue's turn") + (len(held) > 0 ? ", holding " + len(held) : "");
  row {
    button "Wall" { if len(held) == 0 { wall = !wall; } }
