}

// Tak, flats only: tap an empty square to place a stone, or your stack then a square next to it
// to move the whole stack there. A road of your stones on top from side to side wins.
// icon: fill 3 15 21 15 21 21 3 21 fill 5 9 19 9 19 14 5 14 fill 10 2 14 2 14 8 10 8
state st = [""; 25];      // each square's stack, bottom first: r red, b blue
state turn = 0;           // 0 red, 1 blue
state picked = -1;        // the stack about to move
state winner = -1;

fn side(i: int) -> int {
  if len(st[i]) == 0 { return -1; }
  return st[i][len(st[i]) - 1] == "r" ? 0 : 1;
}

fn near(i: int, j: int) -> bool {
  return (j == i - 5 || j == i + 5 || (j == i - 1 && i % 5 > 0) || (j == i + 1 && i % 5 < 4)) && j >= 0 && j < 25;
}

// A road: stones of p on top, joined from the left side to the right, or the top to the bottom.
fn road(p: int) -> bool {
  for way in 0..2 {
    let seen = [false; 25];
    let todo = [0; 0];
    for k in 0..5 {
      let i = way == 0 ? k * 5 : k;
      if side(i) == p { seen[i] = true; push(todo, i); }
    }
    while len(todo) > 0 {
      let i = todo[len(todo) - 1];
      remove(todo, len(todo) - 1);
      if (way == 0 && i % 5 == 4) || (way == 1 && i / 5 == 4) { return true; }
      for j in i - 5..i + 6 {
        if j >= 0 && j < 25 && near(i, j) && !seen[j] && side(j) == p {
          seen[j] = true;
          push(todo, j);
        }
      }
    }
  }
  return false;
}

fn done() {
  if road(turn) { winner = turn; } else if road(1 - turn) { winner = 1 - turn; }
  turn = 1 - turn;
  picked = -1;
}

fn tap(i: int) {
  if winner >= 0 { return; }
  if picked >= 0 && near(picked, i) {
    st[i] = st[i] + st[picked];
    st[picked] = "";
    done();
  } else if picked == i {
    picked = -1;
  } else if len(st[i]) == 0 {
    st[i] = turn == 0 ? "r" : "b";
    done();
  } else if side(i) == turn {
    picked = i;
  }
}

fn scene() {
  for i in 0..25 {
    let cx = i % 5 * 20 + 10;
    let cy = i / 5 * 20 + 10;
    rect(cx - 9, cy - 9, 19, 19, i == picked ? 3 : 7);
    if side(i) >= 0 { circle(cx, cy, 7, side(i) == 0 ? 1 : 4); }
    if len(st[i]) > 1 { text(len(st[i]), cx + 6, cy + 6, 6, 9); }
  }
}

label "Tak";
canvas 100, 100, scene() { tap((y / 20) * 5 + x / 20); }
if winner >= 0 {
  label winner == 0 ? "Red wins" : "Blue wins";
} else {
  label turn == 0 ? "Red's turn" : "Blue's turn";
}

// Spiral galaxies: pick a galaxy's color and tap squares to paint them. Each galaxy must be one
// piece around its dot that looks the same turned half around it.
// icon: fill 3 3 12 3 12 12 3 12 dot 12 12 2 loop 12 12 21 12 21 21 12 21 dot 17 17 2
state paint = [0; 36];               // 0 blank, else the galaxy's color, 1 to 6
state gx = [2, 3, 7, 10, 9, 11];     // the dots in half squares from the top left: across
state gy = [2, 7, 6, 4, 8, 9];       // and down
state names = ["Red", "Green", "Yellow", "Blue", "Purple", "Cyan"];
state pick = 1;

// Galaxy g's squares are joined, hold the squares its dot touches and turn into themselves.
fn galaxy(g: int) -> bool {
  let first = -1;
  let n = 0;
  for i in 0..36 {
    if paint[i] == g + 1 {
      let mc = gx[g] - 1 - i % 6;
      let mr = gy[g] - 1 - i / 6;
      if mc < 0 || mc > 5 || mr < 0 || mr > 5 || paint[mr * 6 + mc] != g + 1 { return false; }
      if first < 0 { first = i; }
      n += 1;
    }
  }
  for dc in 0..2 {
    for dr in 0..2 {
      let c = (gx[g] - 1 + dc) / 2;
      let r = (gy[g] - 1 + dr) / 2;
      if paint[r * 6 + c] != g + 1 { return false; }
    }
  }
  let seen = [false; 36];
  let todo = [first];
  seen[first] = true;
  let reached = 0;
  while len(todo) > 0 {
    let i = todo[len(todo) - 1];
    remove(todo, len(todo) - 1);
    reached += 1;
    let next = [i - 6, i + 6, i % 6 > 0 ? i - 1 : -1, i % 6 < 5 ? i + 1 : -1];
    for k in 0..4 {
      let j = next[k];
      if j >= 0 && j < 36 && !seen[j] && paint[j] == g + 1 {
        seen[j] = true;
        push(todo, j);
      }
    }
  }
  return reached == n;
}

fn solved() -> bool {
  for i in 0..36 {
    if paint[i] == 0 { return false; }
  }
  for g in 0..6 {
    if !galaxy(g) { return false; }
  }
  return true;
}

// The paint as squares, faint edges between them, each dot in its color ringed in ink.
fn scene() {
  pixels(paint, 0, 0, 6, 20);
  for k in 1..6 {
    line(k * 20, 0, k * 20, 120, 1, 8);
    line(0, k * 20, 120, k * 20, 1, 8);
  }
  for g in 0..6 {
    circle(gx[g] * 10, gy[g] * 10, 4, g + 1);
    ring(gx[g] * 10, gy[g] * 10, 4, 1, 9);
  }
}

label "Spiral galaxies";
canvas 120, 120, scene() { paint[(y / 20) * 6 + x / 20] = pick; }
row {
  for g in 0..6 { button names[g] { pick = g + 1; } }
}
label "Painting " + names[pick - 1];
