// Spiral galaxies: tap a dot to pick its galaxy, then tap squares to give them to it. Each galaxy
// must be one piece that looks the same turned half around its dot.
// icon: fill 3 3 12 3 12 12 3 12 dot 12 12 2 loop 12 12 21 12 21 21 12 21 dot 17 17 2
state dots = [11, 20, 13, 9, 19];   // the squares holding the dots, one a galaxy
state owner = [-1; 25];             // the galaxy each other square was given, -1 none
state pick = -1;

fn dotAt(i: int) -> int {
  for g in 0..5 {
    if dots[g] == i { return g; }
  }
  return -1;
}

// A dot's square is its galaxy's; any other is the one it was given.
fn galaxy(i: int) -> int {
  let g = dotAt(i);
  return g >= 0 ? g : owner[i];
}

fn tap(i: int) {
  if dotAt(i) >= 0 {
    pick = dotAt(i);
  } else if pick >= 0 {
    owner[i] = pick;
  }
}

// Galaxy g turns into itself around its dot, and its squares are all joined.
fn whole(g: int) -> bool {
  let n = 0;
  for i in 0..25 {
    if galaxy(i) == g {
      let mc = 2 * (dots[g] % 5) - i % 5;
      let mr = 2 * (dots[g] / 5) - i / 5;
      if mc < 0 || mc > 4 || mr < 0 || mr > 4 || galaxy(mr * 5 + mc) != g { return false; }
      n += 1;
    }
  }
  let seen = [false; 25];
  let todo = [dots[g]];
  seen[dots[g]] = true;
  let reached = 0;
  while len(todo) > 0 {
    let i = todo[len(todo) - 1];
    remove(todo, len(todo) - 1);
    reached += 1;
    let next = [i - 5, i + 5, i % 5 > 0 ? i - 1 : -1, i % 5 < 4 ? i + 1 : -1];
    for k in 0..4 {
      let j = next[k];
      if j >= 0 && j < 25 && !seen[j] && galaxy(j) == g {
        seen[j] = true;
        push(todo, j);
      }
    }
  }
  return reached == n;
}

fn solved() -> bool {
  for i in 0..25 {
    if galaxy(i) < 0 { return false; }
  }
  for g in 0..5 {
    if !whole(g) { return false; }
  }
  return true;
}

// Each square in its galaxy's color, the dots in ink, the picked one ringed.
fn scene() {
  let px = [0; 25];
  for i in 0..25 { px[i] = galaxy(i) + 1; }
  pixels(px, 0, 0, 5, 20);
  for g in 0..5 {
    let cx = dots[g] % 5 * 20 + 10;
    let cy = dots[g] / 5 * 20 + 10;
    circle(cx, cy, 3, 9);
    if g == pick { ring(cx, cy, 6, 1, 11); }
  }
}

