// Zoop: pieces creep along 16 lanes toward the middle. The arrows move and turn the shooter, space
// shoots: it clears pieces of its own color and swaps colors with the first other one.
// icon: loop 8 8 16 8 16 16 8 16 dot 12 3 2 dot 12 21 2 dot 3 12 2 dot 21 12 2
state lane = [0; 64];          // 16 lanes of 4, from the outer end: 0 none, else the piece's color
state comeLane = [1, 1, 1, 9, 6, 14, 9];       // the arrivals in turn: lane (left rows 4-7, right
state comeColor = [1, 1, 4, 2, 3, 2, 2];       // rows 4-7, top columns 4-7, bottom columns 4-7)
state come = 0;
state sx = 5;                  // the shooter, its facing (0 left, 1 right, 2 up, 3 down) and color
state sy = 5;
state face = 2;
state hue = 1;
state score = 0;
state speed = 0;               // ms between pieces; 0 before Start and after Game over
state over = false;

// The board square of lane l's place k (0 at the outer end), as y * 12 + x.
fn square(l: int, k: int) -> int {
  let i = l % 4 + 4;
  if l < 4 { return i * 12 + k; }
  if l < 8 { return i * 12 + 11 - k; }
  if l < 12 { return k * 12 + i; }
  return (11 - k) * 12 + i;
}

fn count(l: int) -> int {
  let n = 0;
  while n < 4 && lane[l * 4 + n] > 0 { n += 1; }
  return n;
}

fn start() {
  lane = [0; 64];
  come = 0;
  sx = 5;
  sy = 5;
  face = 2;
  hue = 1;
  score = 0;
  over = false;
  speed = 2000;
}

// A piece comes in at the outer end, pushing the lane on; a fifth goes into the middle.
fn arrive() {
  let l = comeLane[come % len(comeLane)];
  let c = comeColor[come % len(comeColor)];
  come += 1;
  if count(l) == 4 {
    over = true;
    speed = 0;
    return;
  }
  for j in 0..3 { lane[l * 4 + 3 - j] = lane[l * 4 + 2 - j]; }
  lane[l * 4] = c;
}

fn steer(f: int, dx: int, dy: int) {
  if speed == 0 { return; }
  face = f;
  if sx + dx >= 4 && sx + dx <= 7 && sy + dy >= 4 && sy + dy <= 7 {
    sx += dx;
    sy += dy;
  }
}

fn shoot() {
  if speed == 0 { return; }
  let l = face * 4 + (face < 2 ? sy : sx) - 4;
  let n = count(l);
  while n > 0 {
    let k = l * 4 + n - 1;
    if lane[k] == hue {
      lane[k] = 0;
      score += 1;
      n -= 1;
    } else {
      let c = lane[k];
      lane[k] = hue;
      hue = c;
      return;
    }
  }
}

// The lanes silver, the middle gray, the corners empty; the shooter's facing a dark dot.
fn scene() {
  let px = [-1; 144];
  for i in 0..144 {
    let x = i % 12;
    let y = i / 12;
    if (x >= 4 && x <= 7) || (y >= 4 && y <= 7) { px[i] = x >= 4 && x <= 7 && y >= 4 && y <= 7 ? 8 : 7; }
  }
  for l in 0..16 {
    for k in 0..4 {
      if lane[l * 4 + k] > 0 { px[square(l, k)] = lane[l * 4 + k]; }
    }
  }
  px[sy * 12 + sx] = hue;
  pixels(px, 0, 0, 12, 10);
  let dx = [-3, 3, 0, 0];
  let dy = [0, 0, -3, 3];
  circle(sx * 10 + 5 + dx[face], sy * 10 + 5 + dy[face], 1, 9);
  if over { text("Game over", 60, 60, 14, 11); }
}

