// The Royal Game of Ur: roll, then tap a piece to move it, or bring a new one on. Rosettes roll
// again and the middle one is safe; landing on the other's piece in the middle row sends it back.
// icon: loop 3 7 21 7 21 17 3 17 ring 8 12 3 dot 16 12 3
state pos = [0, 0, 0, 0, 0, 0];   // red's 3 pieces, then blue's: 0 waiting, 1 to 14 on the way, 15 off
state rolls = [4, 2, 0, 2, 1, 4, 4, 3, 3, 1, 1, 2, 4, 3, 4, 4, 4, 3, 2, 2, 2, 1, 1, 4, 2, 4, 4, 0, 3];
state next = 0;
state rolled = -1;                // the last roll
state pending = false;            // a roll waits for its move
state turn = 0;                   // 0 red, 1 blue
state winner = -1;

// The square (row * 8 + column) of step p of player t's way.
fn square(t: int, p: int) -> int {
  let row = t == 0 ? 0 : 16;
  if p <= 4 { return row + 4 - p; }
  if p <= 12 { return 8 + p - 5; }
  return row + 20 - p;
}

// The piece on square sq, -1 none.
fn at(sq: int) -> int {
  for k in 0..6 {
    if pos[k] >= 1 && pos[k] <= 14 && square(k / 3, pos[k]) == sq { return k; }
  }
  return -1;
}

fn count(t: int, p: int) -> int {
  let n = 0;
  for j in 0..3 {
    if pos[t * 3 + j] == p { n += 1; }
  }
  return n;
}

// Piece k may move the roll: not onto its own side, nor onto the middle rosette when taken, and
// off only by the exact roll.
fn can(k: int) -> bool {
  let q = pos[k] + rolled;
  if rolled == 0 || pos[k] == 15 || q > 15 { return false; }
  if q == 15 { return true; }
  let o = at(square(k / 3, q));
  return o < 0 || (o / 3 != k / 3 && q != 8);
}

fn movable() -> bool {
  for j in 0..3 {
    if can(turn * 3 + j) { return true; }
  }
  return false;
}

fn roll() {
  rolled = rolls[next % len(rolls)];
  next += 1;
  pending = movable();
  if !pending { turn = 1 - turn; }
}

fn go(k: int) {
  let q = pos[k] + rolled;
  if q < 15 {
    let o = at(square(k / 3, q));
    if o >= 0 { pos[o] = 0; }
  }
  pos[k] = q;
  pending = false;
  if count(turn, 15) == 3 {
    winner = turn;
  } else if q != 4 && q != 8 && q != 14 {
    turn = 1 - turn;
  }
}

fn tap(sq: int) {
  let k = at(sq);
  if pending && k >= 0 && k / 3 == turn && can(k) { go(k); }
}

fn enter() {
  for j in 0..3 {
    let k = turn * 3 + j;
    if pending && pos[k] == 0 && can(k) {
      go(k);
      return;
    }
  }
}

// The board without the gap's squares, the rosettes ringed, the pieces on top.
fn scene() {
  for sq in 0..24 {
    if sq / 8 == 1 || sq % 8 < 4 || sq % 8 > 5 { rect(sq % 8 * 20 + 1, sq / 8 * 20 + 1, 18, 18, 7); }
  }
  let ros = [0, 6, 11, 16, 22];
  for i in 0..5 { ring(ros[i] % 8 * 20 + 10, ros[i] / 8 * 20 + 10, 8, 2, 11); }
  for k in 0..6 {
    if pos[k] >= 1 && pos[k] <= 14 {
      let sq = square(k / 3, pos[k]);
      circle(sq % 8 * 20 + 10, sq / 8 * 20 + 10, 6, k < 3 ? 1 : 4);
    }
  }
}

