// The Royal Game of Ur, 2 pieces each: roll, then tap a piece to move it, or the square a new one
// would land on. Rosettes roll again; landing on the other color in the middle row knocks it back.
// icon: loop 3 7 21 7 21 17 3 17 ring 8 12 3 dot 16 12 3
state pos = [0, 0, 0, 0];   // red's 2 pieces, then blue's: 0 waiting, 1 to 14 on the way, 15 off
state rolled = 0;           // the roll, 0 before one
state turn = 0;             // 0 red, 1 blue
state throws = 0;
state winner = -1;

// The square (row * 8 + column) of step p of player t's way.
fn square(t: int, p: int) -> int {
  let row = t == 0 ? 0 : 16;
  if p <= 4 { return row + 4 - p; }
  if p <= 12 { return 8 + p - 5; }
  return row + 20 - p;
}

fn at(sq: int) -> int {
  for k in 0..4 {
    if pos[k] >= 1 && pos[k] <= 14 && square(k / 2, pos[k]) == sq { return k; }
  }
  return -1;
}

fn can(k: int) -> bool {
  let q = pos[k] + rolled;
  if rolled == 0 || pos[k] == 15 || q > 15 { return false; }
  if q == 15 { return true; }
  let o = at(square(k / 2, q));
  return o < 0 || (o / 2 != k / 2 && q != 8);
}

fn roll() {
  rolled = throws % 4 + 1;
  throws += 1;
  if !can(turn * 2) && !can(turn * 2 + 1) {
    rolled = 0;
    turn = 1 - turn;
  }
}

fn go(k: int) {
  let q = pos[k] + rolled;
  if q < 15 && at(square(turn, q)) >= 0 { pos[at(square(turn, q))] = 0; }
  pos[k] = q;
  rolled = 0;
  if pos[turn * 2] == 15 && pos[turn * 2 + 1] == 15 {
    winner = turn;
  } else if q != 4 && q != 8 && q != 14 {
    turn = 1 - turn;
  }
}

// A tap on a piece of the turn's player moves it; on the square a new piece would land, brings one on.
fn tap(sq: int) {
  if winner >= 0 || rolled == 0 { return; }
  for j in 0..2 {
    let k = turn * 2 + j;
    let mine = pos[k] >= 1 && pos[k] <= 14 && square(turn, pos[k]) == sq;
    let fresh = pos[k] == 0 && square(turn, rolled) == sq;
    if (mine || fresh) && can(k) {
      go(k);
      return;
    }
  }
}

fn scene() {
  for sq in 0..24 {
    if sq / 8 == 1 || sq % 8 < 4 || sq % 8 > 5 { rect(sq % 8 * 20 + 1, sq / 8 * 20 + 1, 18, 18, 7); }
  }
  let ros = [0, 6, 11, 16, 22];
  for i in 0..5 { ring(ros[i] % 8 * 20 + 10, ros[i] / 8 * 20 + 10, 8, 2, 11); }
  for k in 0..4 {
    if pos[k] >= 1 && pos[k] <= 14 {
      let sq = square(k / 2, pos[k]);
      circle(sq % 8 * 20 + 10, sq / 8 * 20 + 10, 6, k < 2 ? 1 : 4);
    }
  }
}

