// Pylos: tap a free spot to put a ball there, or tap your loose ball and then a higher spot to move
// it up. A 2x2 block of your color takes back one or two balls. The top ball wins.
// icon: dot 7 17 4 dot 17 17 4 dot 12 8 4
state owner = [-1; 30];   // the 4x4 level, then 3x3, 2x2 and the top: -1 empty, 0 red, 1 blue
state left = [15, 15];
state turn = 0;           // 0 red, 1 blue
state chosen = -1;        // a ball picked to move up
state taking = false;     // taking back balls after a block
state took = 0;
state winner = -1;
state base = [0, 16, 25, 29];
state sizes = [4, 3, 2, 1];
state col0 = [0, 5, 9, 12];   // each level's first column on the board

fn lvl(i: int) -> int {
  if i < 16 { return 0; }
  if i < 25 { return 1; }
  if i < 29 { return 2; }
  return 3;
}

fn at(l: int, c: int, r: int) -> int { return base[l] + r * sizes[l] + c; }

// The spot shown on board square (x, y), -1 none.
fn spot(x: int, y: int) -> int {
  for l in 0..4 {
    let c = x - col0[l];
    if c >= 0 && c < sizes[l] && y < sizes[l] { return at(l, c, y); }
  }
  return -1;
}

// The four spots under i (none on the bottom level).
fn under(i: int) -> [int] {
  let l = lvl(i);
  if l == 0 { return [0; 0]; }
  let c = (i - base[l]) % sizes[l];
  let r = (i - base[l]) / sizes[l];
  return [at(l - 1, c, r), at(l - 1, c + 1, r), at(l - 1, c, r + 1), at(l - 1, c + 1, r + 1)];
}

fn rests(i: int, j: int) -> bool {
  let u = under(i);
  for k in 0..len(u) {
    if u[k] == j { return true; }
  }
  return false;
}

fn loose(j: int) -> bool {
  for i in 16..30 {
    if owner[i] >= 0 && rests(i, j) { return false; }
  }
  return true;
}

fn open(i: int) -> bool {
  if owner[i] >= 0 { return false; }
  let u = under(i);
  for k in 0..len(u) {
    if owner[u[k]] < 0 { return false; }
  }
  return true;
}

// Whether ball i is in a 2x2 block of its color on its level.
fn block(i: int) -> bool {
  let l = lvl(i);
  let c = (i - base[l]) % sizes[l];
  let r = (i - base[l]) / sizes[l];
  for dc in 0..2 {
    for dr in 0..2 {
      let x = c - dc;
      let y = r - dr;
      if x >= 0 && y >= 0 && x + 1 < sizes[l] && y + 1 < sizes[l] {
        let p = owner[i];
        if owner[at(l, x, y)] == p && owner[at(l, x + 1, y)] == p && owner[at(l, x, y + 1)] == p && owner[at(l, x + 1, y + 1)] == p { return true; }
      }
    }
  }
  return false;
}

fn pass() {
  turn = 1 - turn;
  taking = false;
  chosen = -1;
  if left[turn] == 0 { winner = 1 - turn; }
}

fn put(i: int) {
  owner[i] = turn;
  if i == 29 {
    winner = turn;
  } else if block(i) {
    taking = true;
    took = 0;
  } else {
    pass();
  }
}

fn tap(i: int) {
  if winner >= 0 || i < 0 { return; }
  if taking {
    if owner[i] == turn && loose(i) {
      owner[i] = -1;
      left[turn] += 1;
      took += 1;
      if took == 2 { pass(); }
    }
  } else if chosen >= 0 {
    if i == chosen {
      chosen = -1;
    } else if lvl(i) > lvl(chosen) && !rests(i, chosen) && open(i) {
      owner[chosen] = -1;
      chosen = -1;
      put(i);
    }
  } else if open(i) {
    if left[turn] > 0 {
      left[turn] -= 1;
      put(i);
    }
  } else if owner[i] == turn && loose(i) && lvl(i) < 3 {
    chosen = i;
  }
}

// The levels side by side: free spots silver, balls in their colors, a ball to move ringed.
fn scene() {
  let px = [-1; 52];
  for i in 0..30 {
    let l = lvl(i);
    let k = (i - base[l]) / sizes[l] * 13 + col0[l] + (i - base[l]) % sizes[l];
    px[k] = owner[i] < 0 ? 7 : (owner[i] == 0 ? 1 : 4);
  }
  pixels(px, 0, 0, 13, 10);
  if chosen >= 0 {
    let l = lvl(chosen);
    let c = col0[l] + (chosen - base[l]) % sizes[l];
    let r = (chosen - base[l]) / sizes[l];
    ring(c * 10 + 5, r * 10 + 5, 5, 1, 11);
  }
}

