// No Thanks for three: take the card up with its chips, or pay a chip to pass it on. The lowest
// score wins: your cards (a run counts only its lowest) less your chips.
// icon: loop 4 3 15 3 15 20 4 20 line 7 8 12 8 line 7 13 12 13 dot 19 17 3
state deck = [24, 25, 8, 26, 31, 9, 15, 35, 23];
state names = ["Ann", "Bob", "Cy"];
state owner = [-1, -1, -1, -1, -1, -1, -1, -1, -1];   // who took each card, -1 nobody yet
state chips = [3, 3, 3];
state up = 0;             // the card turned up
state pot = 0;            // the chips on it
state turn = 0;

fn holds(p: int, c: int) -> bool {
  for i in 0..len(deck) {
    if owner[i] == p && deck[i] == c { return true; }
  }
  return false;
}

// The cards of player p, low to high.
fn hand(p: int) -> string {
  let out = "";
  for c in 3..36 {
    if holds(p, c) { out = out + " " + c; }
  }
  return out;
}

// A run of cards in a row counts only its lowest; chips count against the cards.
fn score(p: int) -> int {
  let s = 0;
  for i in 0..len(deck) {
    if owner[i] == p && !holds(p, deck[i] - 1) { s += deck[i]; }
  }
  return s - chips[p];
}

fn best() -> int {
  let w = 0;
  for p in 1..3 {
    if score(p) < score(w) { w = p; }
  }
  return w;
}

// The taker keeps the turn and decides on the next card.
fn take() {
  owner[up] = turn;
  chips[turn] += pot;
  pot = 0;
  up += 1;
}

fn pass() {
  if chips[turn] == 0 { return; }
  chips[turn] -= 1;
  pot += 1;
  turn = (turn + 1) % 3;
}

// The card up, its chips beside it; at the end, who won.
fn scene() {
  if up < len(deck) {
    rect(60, 6, 40, 56, 9);
    rect(62, 8, 36, 52, 0);
    text(deck[up], 80, 34, 16, 9);
    for k in 0..pot { circle(112 + k % 4 * 9, 14 + k / 4 * 9, 3, 3); }
  } else {
    text(names[best()] + " wins", 80, 34, 12, 11);
  }
}

