fn score(p: int) -> int {
  let s = -chips[p];
  for c in 3..36 {
    if owner[c] == p && owner[c - 1] != p { s += c; }
  }
  return s;
}

fn best() -> int {
  let w = 0;
  for p in 1..3 {
    if score(p) < score(w) { w = p; }
  }
  return w;
}

fn scene() {
  if up <= 35 {
    rect(60, 6, 40, 56, 9);
