label winner != "" ? winner : (turn == 1 ? "Red's turn" : "Blue's turn");

// Squadro against the computer: tap one of your yellow pieces to move it across and back; jump
// the red pieces to send them back. Bring 4 of 5 home first.
// icon: line 3 8 21 8 line 3 16 21 16 dot 8 8 3 dot 16 16 3
state pos = [0; 10];      // 0-4 my yellow pieces (rows 1-5), 5-9 the red ones (columns 1-5)
state back = [false; 10]; // on the way back
state done = [false; 10]; // home, off the board
state speeds = [1, 3, 2, 3, 1, 3, 1, 2, 1, 3];
state returns = [3, 1, 2, 1, 3, 1, 3, 2, 3, 1];
state result = "";

// The square of piece k at place n of its lane: yellow across a row, red up a column.
fn sq(k: int, n: int) -> int {
  if k < 5 { return (k + 1) * 7 + n; }
  return (6 - n) * 7 + k - 4;
}

// The piece on square s of the side that is not k's, or -1.
fn rival(k: int, s: int) -> int {
  let from = k < 5 ? 5 : 0;
  for m in from..from + 5 {
    if !done[m] && sq(m, pos[m]) == s { return m; }
  }
  return -1;
}

fn jumps(k: int) -> bool {
  let d = back[k] ? -1 : 1;
  let p = pos[k];
  let left = back[k] ? returns[k] : speeds[k];
  while left > 0 {
    if rival(k, sq(k, p + d)) >= 0 { return true; }
    p += d;
    left -= 1;
    if p == 0 || p == 6 { return false; }
  }
  return false;
}

// Piece k moves its speed, stopping at its lane's end; it jumps a run of rival pieces, which go
// back to the start of their way, and stops just past them.
fn go(k: int) {
  let d = back[k] ? -1 : 1;
  let p = pos[k];
  let left = back[k] ? returns[k] : speeds[k];
  while left > 0 {
    let m = rival(k, sq(k, p + d));
    if m >= 0 {
      while m >= 0 {
        pos[m] = back[m] ? 6 : 0;
        p += d;
        m = rival(k, sq(k, p + d));
      }
      p += d;
      left = 0;
    } else {
      p += d;
      left -= 1;
      if p == 0 || p == 6 { left = 0; }
    }
  }
  pos[k] = p;
  if p == 6 { back[k] = true; }
  if p == 0 && back[k] { done[k] = true; }
}

fn home(from: int) -> int {
  let n = 0;
  for k in from..from + 5 {
    if done[k] { n += 1; }
  }
  return n;
}

// The computer: its leftmost piece that jumps one of mine, else its leftmost piece in play.
fn computer() {
  let pick = -1;
  for k in 5..10 {
    if pick < 0 && !done[k] && jumps(k) { pick = k; }
  }
  for k in 5..10 {
    if pick < 0 && !done[k] { pick = k; }
  }
  go(pick);
  if home(5) >= 4 { result = "You lose"; }
}

fn tap(s: int) {
  if result != "" { return; }
  for k in 0..5 {
    if !done[k] && sq(k, pos[k]) == s {
      go(k);
      if home(0) >= 4 {
        result = "You win";
      } else {
        computer();
      }
      return;
    }
  }
}

fn scene() {
  for i in 1..6 {
    line(10, i * 20 + 10, 130, i * 20 + 10, 1, 8);
    line(i * 20 + 10, 10, i * 20 + 10, 130, 1, 8);
    text(speeds[i - 1], 4, i * 20 + 4, 6, 10);
    text(speeds[i + 4], i * 20 + 10, 136, 6, 10);
  }
  for k in 0..10 {
    if !done[k] {
      let s = sq(k, pos[k]);
      circle(s % 7 * 20 + 10, s / 7 * 20 + 10, 7, k < 5 ? 3 : 1);
      if back[k] { ring(s % 7 * 20 + 10, s / 7 * 20 + 10, 9, 2, 9); }
    }
  }
}

