// SpellTower: tap touching letters to spell a word, then Submit. Listed words vanish and the
// letters above fall; a word of 5 or more also clears the letters beside it. Clear the tower.
// icon: loop 7 3 17 3 17 21 7 21 line 7 9 17 9 line 7 15 17 15 line 12 3 12 21
state tower = ["T", "I", "A", "N", "S", "I", "K", "V", "L", "A", "J", "N", "C", "U", "T",
  "M", "A", "K", "K", "D", "L", "B", "M", "P", "H", "B", "R", "I", "C", "K"];
state words = ["BRICK", "INK", "KIT", "JAM", "DUCK", "VAN", "SALT", "TAN", "MILK", "CAT", "SKI"];
state picked = [0; 0];
state score = 0;

fn word() -> string {
  let w = "";
  for k in 0..len(picked) { w = w + tower[picked[k]]; }
  return w;
}

fn has(xs: [int], v: int) -> bool {
  for k in 0..len(xs) {
    if xs[k] == v { return true; }
  }
  return false;
}

// A letter joins the word if it is not used yet and touches the last one (diagonals too).
fn tap(i: int) {
  if tower[i] == "" || has(picked, i) { return; }
  if len(picked) > 0 {
    let j = picked[len(picked) - 1];
    if abs(i % 5 - j % 5) > 1 || abs(i / 5 - j / 5) > 1 { return; }
  }
  push(picked, i);
}

fn listed(w: string) -> bool {
  for k in 0..len(words) {
    if words[k] == w { return true; }
  }
  return false;
}

// Each column's letters drop to the bottom, keeping their order.
fn fall() {
  for c in 0..5 {
    let r = 5;
    for k in 0..6 {
      let at = (5 - k) * 5 + c;
      if tower[at] != "" {
        let ch = tower[at];
        tower[at] = "";
        tower[r * 5 + c] = ch;
        r -= 1;
      }
    }
  }
}

fn submit() {
  if len(picked) >= 3 && listed(word()) {
    let gone = picked;
    if len(picked) >= 5 {
      for k in 0..len(picked) {
        let i = picked[k];
        if i % 5 > 0 { push(gone, i - 1); }
        if i % 5 < 4 { push(gone, i + 1); }
        if i >= 5 { push(gone, i - 5); }
        if i < 25 { push(gone, i + 5); }
      }
    }
    for k in 0..len(gone) {
      if tower[gone[k]] != "" {
        tower[gone[k]] = "";
        score += 1;
      }
    }
    fall();
  }
  clear(picked);
}

fn left() -> int {
  let n = 0;
  for i in 0..30 {
    if tower[i] != "" { n += 1; }
  }
  return n;
}

fn scene() {
  for i in 0..30 {
    if tower[i] != "" {
      rect(i % 5 * 20 + 1, i / 5 * 20 + 1, 18, 18, has(picked, i) ? 3 : 7);
      text(tower[i], i % 5 * 20 + 10, i / 5 * 20 + 10, 12, 9);
    }
  }
}

