state words = ["HILL", "KIT", "MAP", "FERN", "KEY", "RAT", "TEA", "ART", "PIE"];
state picked = [0; 0];

fn word() -> string {
  let w = "";
  for k in 0..len(picked) { w = w + tower[picked[k]]; }
  return w;
}

fn tap(i: int) {
  if tower[i] == "" { return; }
  for k in 0..len(picked) {
    if picked[k] == i { return; }
  }
  if len(picked) > 0 {
    let j = picked[len(picked) - 1];
    if abs(i % 4 - j % 4) > 1 || abs(i / 4 - j / 4) > 1 { return; }
  }
  push(picked, i);
}

fn play() {
  let ok = false;
  for k in 0..len(words) {
    if words[k] == word() { ok = true; }
  }
  if ok {
    for k in 0..len(picked) { tower[picked[k]] = ""; }
    for c in 0..4 {
      let r = 4;
      for k in 0..5 {
        let at = (4 - k) * 4 + c;
        if tower[at] != "" {
          let ch = tower[at];
          tower[at] = "";
          tower[r * 4 + c] = ch;
          r -= 1;
        }
      }
    }
  }
  clear(picked);
}

fn empty() -> bool {
  for i in 0..20 {
    if tower[i] != "" { return false; }
  }
  return true;
}

