// Driller: the arrows (or the buttons) move the driller and drill the blocks beside and under it;
// a block takes its whole same-color patch with it, loose blocks fall. Mind your air; reach the bottom.
// icon: fill 4 4 20 4 20 20 4 20 ring 12 9 4 line 12 13 12 21
state start = [0, 0, 0, 0, 0, 0, 0, 1, 1, 2, 2, 4, 4, 3, 1, 3, 3, 2, 4, 3, 3, 4, 4, 3, 2, 2, 1, 1, 2, 4, 6, 3, 1, 1, 4, 2, 2, 3, 3, 4, 1, 4, 1, 2, 4, 4, 3, 3, 2, 1, 1, 4, 6, 3, 2, 2, 3, 1, 1, 4, 4, 2, 3, 3, 3, 2, 4, 1, 1, 3];
state field = [0; 70];    // 7 x 10: 0 empty, 1-4 blocks, 6 an air capsule
state dc = 3;             // the driller's column and row
state dr = 0;
state air = 20;
state over = "";
state playing = false;

fn restart() {
  playing = true;
  field = start;
  dc = 3;
  dr = 0;
  air = 20;
  over = "";
}

// Drills square i: a capsule gives 10 air; a block goes with every block of its color joined to it
// side by side.
fn drill(i: int) {
  let v = field[i];
  field[i] = 0;
  if v == 6 {
    air += 10;
    return;
  }
  let todo = [i];
  while len(todo) > 0 {
    let j = todo[len(todo) - 1];
    remove(todo, len(todo) - 1);
    if j % 7 > 0 && field[j - 1] == v { field[j - 1] = 0; push(todo, j - 1); }
    if j % 7 < 6 && field[j + 1] == v { field[j + 1] = 0; push(todo, j + 1); }
    if j >= 7 && field[j - 7] == v { field[j - 7] = 0; push(todo, j - 7); }
    if j < 63 && field[j + 7] == v { field[j + 7] = 0; push(todo, j + 7); }
  }
}

// The driller and every block with nothing under it drop, until nothing more drops.
fn settle() {
  let moved = true;
  while moved {
    moved = false;
    while dr < 9 && field[(dr + 1) * 7 + dc] == 0 {
      dr += 1;
      moved = true;
    }
    for k in 0..63 {
      let i = 62 - k;
      if field[i] != 0 && field[i + 7] == 0 && i + 7 != dr * 7 + dc {
        field[i + 7] = field[i];
        field[i] = 0;
        moved = true;
      }
    }
  }
}

fn press(dx: int, down: bool) {
  if !playing || over != "" { return; }
  air -= 1;
  if down {
    if dr < 9 && field[(dr + 1) * 7 + dc] != 0 { drill((dr + 1) * 7 + dc); }
  } else if dc + dx >= 0 && dc + dx < 7 {
    if field[dr * 7 + dc + dx] == 0 { dc += dx; } else { drill(dr * 7 + dc + dx); }
  }
  settle();
  if dr == 9 {
    over = "You made it";
  } else if air <= 0 {
    over = "Out of air";
  }
}

fn scene() {
  let px = [-1; 70];
  for i in 0..70 {
    if field[i] != 0 { px[i] = field[i]; }
  }
  px[dr * 7 + dc] = 5;
  pixels(px, 0, 0, 7, 12);
}

