// follows the paths. Stay on the board as long as you can.
// icon: loop 3 3 21 3 21 21 3 21 line 9 3 9 21 line 3 15 21 9 dot 9 3 2
// The pile: each tile as the end each of its ends 0-7 is joined to (clockwise from the top left).
state pile = [7, 5, 4, 6, 2, 1, 3, 0, 4, 3, 6, 1, 0, 7, 2, 5, 4, 7, 5, 6, 0, 2, 3, 1,
  5, 2, 1, 7, 6, 0, 4, 3, 2, 3, 0, 1, 7, 6, 5, 4, 2, 4, 0, 7, 1, 6, 5, 3, 3, 6, 7, 0, 5, 4, 1, 2,
  7, 5, 4, 6, 2, 1, 3, 0, 1, 0, 4, 7, 2, 6, 5, 3, 6, 7, 4, 5, 2, 3, 0, 1, 1, 0, 7, 6, 5, 4, 3, 2,
  1, 0, 4, 7, 2, 6, 5, 3, 7, 6, 4, 5, 2, 3, 1, 0, 1, 0, 4, 6, 2, 7, 3, 5, 3, 5, 7, 0, 6, 1, 4, 2,
  3, 2, 1, 0, 5, 4, 7, 6];
state ex = [6, 12, 18, 18, 12, 6, 0, 0];    // where each end is on an 18-unit square
state ey = [0, 0, 6, 12, 18, 18, 12, 6];
