// The end joined to end p of tile t turned n quarter turns clockwise.
fn mate(t: int, n: int, p: int) -> int {
  return (pile[t * 8 + (p + 8 - 2 * n) % 8] + 2 * n) % 8;
}

// The stone runs along the paths of every tile it reaches; off the board it is out.
fn follow() {
  while !over && tileat[sr * 6 + sc] >= 0 {
    let q = mate(tileat[sr * 6 + sc], turnat[sr * 6 + sc], sp);
    let c = sc + [0, 0, 1, 1, 0, 0, -1, -1][q];
    let r = sr + [-1, -1, 0, 0, 1, 1, 0, 0][q];
    if c < 0 || c > 5 || r < 0 || r > 5 {
      sp = q;
      over = true;
    } else {
      sc = c;
      sr = r;
      sp = [5, 4, 7, 6, 1, 0, 3, 2][q];
    }
  }
}

fn place() {
  if over { return; }
  tileat[sr * 6 + sc] = hand[pick];
  turnat[sr * 6 + sc] = turns[pick];
  placed += 1;
  hand[pick] = drawn % 16;
  turns[pick] = 0;
  drawn += 1;
  follow();
}

// Tile t turned n, its paths in ink on silver, at x, y.
fn tile(t: int, n: int, x: int, y: int) {
  rect(x, y, 18, 18, 7);
  for p in 0..8 {
    let q = mate(t, n, p);
    if q > p { line(x + ex[p], y + ey[p], x + ex[q], y + ey[q], 1, 9); }
  }
}

fn board() {
  for i in 0..36 {
    if tileat[i] >= 0 { tile(tileat[i], turnat[i], i % 6 * 18, i / 6 * 18); }
  }
  for k in 0..7 {
    line(k * 18, 0, k * 18, 108, 1, 8);
    line(0, k * 18, 108, k * 18, 1, 8);
  }
  circle(sc * 18 + ex[sp], sr * 18 + ey[sp], 2, 1);
}

fn shelf() {
  for k in 0..3 {
    if k == pick { rect(k * 26, 0, 22, 22, 11); }
    tile(hand[k], turns[k], k * 26 + 2, 2);
  }
}

