// Polarity: place magnets so each row and column has its count of + and - poles, and no two
// equal poles touch. Tap a blank domino's square for + there; tap a + to flip, a - to clear.
// icon: loop 3 7 21 7 21 17 3 17 line 12 7 12 17 line 5 12 10 12 line 7 10 7 14 line 14 12 19 12
state partner = [1, 0, 3, 2, 5, 4, 12, 13, 14, 10, 9, 17, 6, 7, 8, 16, 15, 11, 24, 20, 19, 27, 23, 22, 18, 26, 25, 21, 29, 28, 31, 30, 33, 32, 35, 34];
state pole = [0; 36];     // 0 blank, 1 +, 2 -
state rowplus = [1, 3, 1, 0, 3, 2];
state rowminus = [1, 2, 2, 2, 1, 2];
state colplus = [2, 2, 0, 2, 2, 2];
state colminus = [3, 1, 0, 1, 2, 3];

fn tap(i: int) {
  let j = partner[i];
  if pole[i] == 0 {
    pole[i] = 1;
    pole[j] = 2;
  } else if pole[i] == 1 {
    pole[i] = 2;
    pole[j] = 1;
  } else {
    pole[i] = 0;
    pole[j] = 0;
  }
}

// How many squares of row (or column) k hold pole v.
fn inrow(k: int, v: int) -> int {
  let n = 0;
  for x in 0..6 {
    if pole[k * 6 + x] == v { n += 1; }
  }
  return n;
}

fn incol(k: int, v: int) -> int {
  let n = 0;
  for r in 0..6 {
    if pole[r * 6 + k] == v { n += 1; }
  }
  return n;
}

fn solved() -> bool {
  for k in 0..6 {
    if inrow(k, 1) != rowplus[k] || inrow(k, 2) != rowminus[k] { return false; }
    if incol(k, 1) != colplus[k] || incol(k, 2) != colminus[k] { return false; }
  }
  for i in 0..36 {
    if pole[i] > 0 && i % 6 < 5 && pole[i + 1] == pole[i] { return false; }
    if pole[i] > 0 && i < 30 && pole[i + 6] == pole[i] { return false; }
  }
  return true;
}

fn spaced(xs: [int]) -> string {
  let s = "";
  for i in 0..len(xs) { s = s + " " + xs[i]; }
  return s;
}

// Each domino a gray tile over its two squares; a pole fills its square red (+) or blue (-).
fn scene() {
  for i in 0..36 {
    let j = partner[i];
    if j > i {
      let x = min(i % 6, j % 6) * 20 + 2;
      let y = min(i / 6, j / 6) * 20 + 2;
      rect(x, y, j == i + 1 ? 36 : 16, j == i + 1 ? 16 : 36, 8);
    }
  }
  for i in 0..36 {
    if pole[i] > 0 {
      rect(i % 6 * 20 + 3, i / 6 * 20 + 3, 14, 14, pole[i] == 1 ? 1 : 4);
      text(pole[i] == 1 ? "+" : "-", i % 6 * 20 + 10, i / 6 * 20 + 10, 10, 9);
    }
  }
}

label "Polarity";
canvas 120, 120, scene() { tap(y / 20 * 6 + x / 20); }
label "Rows, top to bottom: +" + spaced(rowplus) + "   -" + spaced(rowminus);
label "Columns, left to right: +" + spaced(colplus) + "   -" + spaced(colminus);
if solved() { label "Solved!"; }

// Magnets: tap a square to make it the + end of its magnet (the other end -), tap a + to take the
// magnet off. Match each row's and column's + and - counts with no equal poles touching.
// icon: loop 3 7 21 7 21 17 3 17 line 12 7 12 17 line 5 12 10 12 line 7 10 7 14 line 14 12 19 12
state partner = [4, 5, 6, 7, 0, 1, 2, 3, 9, 8, 14, 15, 13, 12, 10, 11];
state pole = [0; 16];     // 0 none, 1 +, 2 -
state rowplus = [1, 2, 2, 2];
state rowminus = [2, 1, 2, 2];
state colplus = [1, 2, 2, 2];
state colminus = [1, 2, 2, 2];

fn tap(i: int) {
  if pole[i] == 1 {
    pole[i] = 0;
    pole[partner[i]] = 0;
  } else {
    pole[i] = 1;
    pole[partner[i]] = 2;
  }
}

fn solved() -> bool {
  for k in 0..4 {
    let rp = 0;
    let rm = 0;
    let cp = 0;
    let cm = 0;
    for j in 0..4 {
      if pole[k * 4 + j] == 1 { rp += 1; }
      if pole[k * 4 + j] == 2 { rm += 1; }
      if pole[j * 4 + k] == 1 { cp += 1; }
      if pole[j * 4 + k] == 2 { cm += 1; }
    }
    if rp != rowplus[k] || rm != rowminus[k] || cp != colplus[k] || cm != colminus[k] { return false; }
  }
  for i in 0..16 {
    if pole[i] > 0 && i % 4 < 3 && pole[i + 1] == pole[i] { return false; }
    if pole[i] > 0 && i < 12 && pole[i + 4] == pole[i] { return false; }
  }
  return true;
}

fn nums(xs: [int]) -> string {
  let s = "";
  for i in 0..len(xs) { s = s + " " + xs[i]; }
  return s;
}

