// Sequence against the computer: pick a card, then tap an empty square showing it. Two-eyed jacks
// (JD, JC) go on any empty square, one-eyed jacks (JS, JH) take off a blue chip. Five in a row wins.
// icon: loop 3 3 21 3 21 21 3 21 dot 7 17 2 dot 10 14 2 dot 13 11 2 dot 16 8 2
state deck = ["6H", "2C", "KC", "JS", "9D", "4D", "7C", "8C", "JH", "3S", "4D", "5S", "JD", "6S", "2H", "7S", "3H", "8S", "4H", "9S"];
state names = ["AS", "2S", "3S", "4S", "5S", "6S", "7S", "8S", "9S", "10S", "QS", "KS",
  "AH", "2H", "3H", "4H", "5H", "6H", "7H", "8H", "9H", "10H", "QH", "KH",
  "AD", "2D", "3D", "4D", "5D", "6D", "7D", "8D", "9D", "10D", "QD", "KD",
  "AC", "2C", "3C", "4C", "5C", "6C", "7C", "8C", "9C", "10C", "QC", "KC"];
state mine = ["6H", "2C", "KC", "JS", "9D"];
state theirs = ["4D", "7C", "8C", "JH", "3S"];
state drawn = 10;
state chips = [0; 100];   // 1 mine (red), 4 the computer's (blue)
state picked = -1;
state result = "";

fn corner(i: int) -> bool { return i == 0 || i == 9 || i == 90 || i == 99; }

// The card on square i: the 48 cards row by row, twice over, the corners skipped.
fn cardat(i: int) -> string {
  if corner(i) { return ""; }
  let k = i - 1;
  if i > 9 { k -= 1; }
  if i > 90 { k -= 1; }
  return names[k % 48];
}

fn draw() -> string {
  let c = deck[drawn % len(deck)];
  drawn += 1;
  return c;
}

fn owns(who: int, x: int, y: int) -> bool {
  if x < 0 || x > 9 || y < 0 || y > 9 { return false; }
  return corner(y * 10 + x) || chips[y * 10 + x] == who;
}

fn five(who: int) -> bool {
  for i in 0..100 {
    for d in 0..4 {
      let dx = [1, 0, 1, 1][d];
      let dy = [0, 1, 1, -1][d];
      let n = 0;
      for k in 0..5 {
        if owns(who, i % 10 + k * dx, i / 10 + k * dy) { n += 1; }
      }
      if n == 5 { return true; }
    }
  }
  return false;
}

// Whether card c may go on square i for player who (a one-eyed jack takes a rival's chip).
fn fits(c: string, i: int, who: int) -> bool {
  if corner(i) { return false; }
  if c == "JS" || c == "JH" { return chips[i] == 5 - who; }
  if c == "JD" || c == "JC" { return chips[i] == 0; }
  return chips[i] == 0 && cardat(i) == c;
}

fn put(c: string, i: int, who: int) {
  if c == "JS" || c == "JH" { chips[i] = 0; } else { chips[i] = who; }
}

// The computer: the first card it holds that fits somewhere, on the first square it fits.
fn computer() {
  for k in 0..len(theirs) {
    for i in 0..100 {
      if fits(theirs[k], i, 4) {
        put(theirs[k], i, 4);
        remove(theirs, k);
        push(theirs, draw());
        if five(4) { result = "You lose"; }
        return;
      }
    }
  }
}

fn tap(i: int) {
  if result != "" || picked < 0 || !fits(mine[picked], i, 1) { return; }
  put(mine[picked], i, 1);
  remove(mine, picked);
  push(mine, draw());
  picked = -1;
  if five(1) {
    result = "You win";
  } else {
    computer();
  }
}

fn scene() {
  for i in 0..100 {
    let x = i % 10 * 20;
    let y = i / 10 * 20;
    rect(x, y, 19, 19, corner(i) ? 8 : 7);
    text(cardat(i), x + 10, y + 5, 6, 10);
    if chips[i] > 0 { circle(x + 10, y + 11, 6, chips[i]); }
  }
}

