state broken = [false; 7];
state drop = 3;                   // the dropper's column
state bx = -1;                    // the ball's column (-1: none falling) and row
state by = 0;
state balls = 3;
state score = 0;
state note = "";

fn peg(c: int, r: int) -> int {
  for i in 0..7 {
    if px[i] == c && py[i] == r && !broken[i] { return i; }
  }
  return -1;
}

fn start() {
  broken = [false; 7];
  bx = -1;
  balls = 3;
  score = 0;
  note = "";
}

// A step of the ball: onto a peg (it breaks, the ball rolls aside), down, or out at the bottom.
every 200 {
  let p = peg(bx, by + 1);
  if bx < 0 {
    return;
  } else if by == 6 {
    bx = -1;
    if balls == 0 { note = "Game over"; }
  } else if p >= 0 {
    broken[p] = true;
    score += p < 2 ? 100 : 10;
    bx = bx == 6 ? 5 : bx + 1;
    if broken[0] && broken[1] {
      bx = -1;
      note = "You win!";
    }
  } else {
    by += 1;
  }
}

on key "left" { drop = max(0, drop - 1); }
on key "right" { drop = min(6, drop + 1); }
on key "space" {
  if bx < 0 && balls > 0 && note == "" {
    balls -= 1;
    bx = drop;
    by = 0;
  }
}

