  let b = [-1; 49];
  for i in 0..7 {
    if !broken[i] { b[py[i] * 7 + px[i]] = i < 2 ? 1 : 4; }
  }
  b[drop] = 2;
  if bx >= 0 { b[by * 7 + bx] = 3; }
  pixels(b, 0, 0, 7, 10);
}

