// Frostbite: jump down and up across the drifting ice with the arrows; each fresh row you land on
// adds a block to the igloo. With 6 blocks, get back to the shore before you freeze.
// icon: fill 4 18 4 12 8 7 12 5 16 7 20 12 20 18 fill 10 18 10 14 14 14 14 18
state lay1 = [1, 1, 1, 0, 1, 1, 1, 0, 0, 1, 1, 1, 0, 1, 1, 1];  // rows 1 and 2 (3 and 4 alike)
state lay2 = [1, 1, 0, 0, 1, 1, 0, 0, 0, 0, 1, 1, 0, 0, 1, 1];
state ice = [0; 32];           // rows 1 to 4, 8 squares each: 1 a floe
state fresh = [true, true, true, true];
state pc = 3;                  // the player: column, and row (0 the shore)
state pr = 0;
state level = 1;
state lives = 3;
state igloo = 0;
state temp = 40;
state score = 0;
state speed = 0;               // 500 while a game runs
state note = "";

fn home() {
  pc = 3;
  pr = 0;
  temp = 40;
}

fn begin(lv: int) {
  level = lv;
  for i in 0..32 { ice[i] = lv == 1 ? lay1[i % 16] : lay2[i % 16]; }
  fresh = [true, true, true, true];
  igloo = 0;
  home();
}

fn start() {
  lives = 3;
  score = 0;
  note = "";
  speed = 500;
  begin(1);
}

fn lose() {
  lives -= 1;
  home();
  if lives == 0 {
    note = "Game over";
    speed = 0;
  }
}

fn drift() {
  let old = ice;
  for i in 0..32 {
    let c = i % 8;
    ice[i] = old[i - c + (i / 8 % 2 == 0 ? (c + 7) % 8 : (c + 1) % 8)];
  }
}

every speed {
  drift();
  if pr > 0 {
    pc += pr % 2 == 1 ? 1 : -1;
    if pc < 0 || pc > 7 { lose(); }
  }
  temp -= 1;
  if temp <= 0 { lose(); }
}

// Where a jump lands: the shore (in, with a whole igloo), water, or a floe.
fn land() {
  if pr == 0 && igloo == 6 {
    score += temp;
    if level == 1 {
      begin(2);
    } else {
      note = "You win";
      speed = 0;
    }
  } else if pr > 0 && ice[(pr - 1) * 8 + pc] == 0 {
    lose();
  } else if pr > 0 && fresh[pr - 1] {
    fresh[pr - 1] = false;
    score += 10;
    igloo = min(6, igloo + 1);
    if !fresh[0] && !fresh[1] && !fresh[2] && !fresh[3] { fresh = [true, true, true, true]; }
  }
}

fn jump(d: int) {
  if speed > 0 && pr + d >= 0 && pr + d <= 4 {
    pr += d;
    land();
  }
}

fn walk(d: int) {
  if speed > 0 && pr == 0 { pc = min(7, max(0, pc + d)); }
}

on key "left" { walk(-1); }
on key "right" { walk(1); }
on key "up" { jump(-1); }
on key "down" { jump(1); }

