  let b = [0; 40];
  for i in 0..32 {
    if ice[i] > 0 { b[i + 8] = fresh[i / 8] ? 6 : 4; }
  }
  b[pr * 8 + pc] = 1;
  pixels(b, 0, 0, 8, 12);
}

