// Euchre, Hearts trump: tap a card to play it (following suit when you can); West, North and East
// play at once. Win 3 of the 5 tricks with your partner North.
// icon: loop 5 4 14 4 14 18 5 18 loop 10 6 19 6 19 20 10 20 dot 14 13 2
state ranks = ["9", "10", "J", "Q", "K", "A"];
state suits = ["Clubs", "Diamonds", "Spades", "Hearts"];
// The cards dealt, a card being suit * 6 + rank: South's five, then West's, North's and East's.
state deal = [17, 4, 6, 18, 8, 16, 0, 5, 19, 9, 12, 15, 23, 10, 1, 14, 21, 11, 13, 3];
state played = [false; 20];
state table = [0; 0];          // the trick under way: the cards, and who played each (0 South)
state who = [0; 0];
state leader = 0;
state us = 0;
state them = 0;
state last = "";

fn name(c: int) -> string { return ranks[c % 6] + " " + suits[c / 6]; }

// A card's suit for play: J Diamonds (8) is a Heart.
fn suit(c: int) -> int { return c == 8 ? 3 : c / 6; }

fn led() -> int { return suit(table[0]); }

fn power(c: int, s: int) -> int {
  if c == 20 { return 200; }
  if c == 8 { return 199; }
  if c / 6 == 3 { return 100 + c % 6; }
  if c / 6 == s { return 50 + c % 6; }
  return 0;
}

// Lowest first: cards not trump by rank, Clubs before Diamonds before Spades; then trumps.
fn low(c: int) -> int { return suit(c) == 3 ? 1000 + power(c, 3) : c % 6 * 4 + c / 6; }

// A lead, highest first: cards not trump by rank, Clubs first on a tie; trumps only when all are.
fn high(c: int) -> int { return suit(c) == 3 ? power(c, 3) - 1000 : c % 6 * 4 + 2 - c / 6; }

fn holds(p: int, s: int) -> bool {
  for k in p * 5..p * 5 + 5 {
    if !played[k] && suit(deal[k]) == s { return true; }
  }
  return false;
}

fn legal(p: int, k: int) -> bool {
  return !played[k] && (len(table) == 0 || suit(deal[k]) == led() || !holds(p, led()));
}

fn best() -> int {
  let b = 0;
  for i in 1..len(table) {
    if power(table[i], led()) > power(table[b], led()) { b = i; }
  }
  return b;
}

fn turn() -> int { return (leader + len(table)) % 4; }

fn choose(p: int) -> int {
  let pick = -1;
  if len(table) == 0 {
    for k in p * 5..p * 5 + 5 {
      if !played[k] && (pick < 0 || high(deal[k]) > high(deal[pick])) { pick = k; }
    }
    return pick;
  }
  let top = power(table[best()], led());
  if who[best()] != (p + 2) % 4 {
    for k in p * 5..p * 5 + 5 {
      let v = power(deal[k], led());
      if legal(p, k) && v > top && (pick < 0 || v < power(deal[pick], led())) { pick = k; }
    }
  }
  if pick >= 0 { return pick; }
  for k in p * 5..p * 5 + 5 {
    if legal(p, k) && (pick < 0 || low(deal[k]) < low(deal[pick])) { pick = k; }
  }
  return pick;
}

fn cards(xs: [int]) -> string {
  let s = "";
  for i in 0..len(xs) { s = s + (i > 0 ? ", " : "") + name(xs[i]); }
  return s;
}

fn play(p: int, k: int) {
  played[k] = true;
  push(table, deal[k]);
  push(who, p);
  if len(table) == 4 {
    leader = who[best()];
    if leader % 2 == 0 { us += 1; } else { them += 1; }
    last = cards(table);
    clear(table);
    clear(who);
  }
}

fn mine(k: int) {
  if us + them == 5 || turn() != 0 || !legal(0, k) { return; }
  play(0, k);
  while us + them < 5 && turn() != 0 { play(turn(), choose(turn())); }
}

fn result() -> string {
  if us + them < 5 { return ""; }
  return us >= 3 ? "We win the hand" : "They win the hand";
}

