// Two-handed euchre, hearts trump: tap a card to play it, following suit when you can. The
// computer answers with the cheapest card that wins, and leads its highest. Most of 5 tricks wins.
// icon: loop 5 4 14 4 14 18 5 18 loop 10 6 19 6 19 20 10 20 dot 14 13 2
state ranks = ["9", "10", "J", "Q", "K", "A"];
state suits = ["C", "D", "S", "H"];
state mine = [17, 16, 1, 8, 21];   // a card is suit * 6 + rank
state cpu = [23, 12, 2, 4, 7];
state led = -1;                    // the card the computer led, waiting for mine
state shown = -1;                  // the card it played last
state me = 0;                      // tricks won
state it = 0;

fn name(c: int) -> string { return ranks[c % 6] + suits[c / 6]; }

// Its suit for play: JD (8) counts as a heart.
fn suit(c: int) -> int { return c == 8 ? 3 : c / 6; }

fn power(c: int, s: int) -> int {
  if c == 20 { return 200; }
  if c == 8 { return 199; }
  if c / 6 == 3 { return 100 + c % 6; }
  if c / 6 == s { return 50 + c % 6; }
  return 0;
}

fn holds(h: [int], s: int) -> bool {
  for i in 0..len(h) {
    if suit(h[i]) == s { return true; }
  }
  return false;
}

fn may(h: [int], c: int, first: int) -> bool { return suit(c) == suit(first) || !holds(h, suit(first)); }

// Its answer to the card c: the cheapest that beats it, else its lowest.
fn answer(c: int) -> int {
  let pick = -1;
  for i in 0..len(cpu) {
    let v = power(cpu[i], suit(c));
    if may(cpu, cpu[i], c) && v > power(c, suit(c)) && (pick < 0 || v < power(cpu[pick], suit(c))) { pick = i; }
  }
  if pick >= 0 { return pick; }
  for i in 0..len(cpu) {
    if may(cpu, cpu[i], c) && (pick < 0 || cpu[i] % 6 < cpu[pick] % 6) { pick = i; }
  }
  return pick;
}

fn computerleads() {
  let pick = 0;
  for i in 1..len(cpu) {
    if power(cpu[i], suit(cpu[i])) > power(cpu[pick], suit(cpu[pick])) { pick = i; }
  }
  led = cpu[pick];
  shown = led;
  remove(cpu, pick);
}

fn tap(i: int) {
  let c = mine[i];
  if me + it == 5 || (led >= 0 && !may(mine, c, led)) { return; }
  remove(mine, i);
  let first = led;
  let other = led;
  if led < 0 {
    let k = answer(c);
    other = cpu[k];
    shown = other;
    remove(cpu, k);
    first = c;
  }
  led = -1;
  if power(c, suit(first)) > power(other, suit(first)) {
    me += 1;
  } else {
    it += 1;
    if me + it < 5 { computerleads(); }
  }
}

fn deal() {
  mine = [17, 16, 1, 8, 21];
  cpu = [23, 12, 2, 4, 7];
  led = -1;
  shown = -1;
  me = 0;
  it = 0;
}

