// Camelot: tap a piece of yours, then where it goes: a step, a canter over your own piece or a jump
// over the computer's (jumps are a must). Get a piece onto the computer's castle at the top.
// icon: fill 4 20 4 8 8 8 8 12 10 12 10 8 14 8 14 12 16 12 16 8 20 8 20 20
state board = [0; 35];         // row * 5 + column: 0 empty, 4 mine, 1 the computer's
state dx = [0, -1, 1, -1, 1, -1, 1, 0];   // down, down-left, down-right, left, right, up-left, up-right, up
state dy = [1, 1, 1, 0, 0, -1, -1, -1];
state sel = -1;
state playing = false;
state note = "";

fn inside(c: int, r: int) -> bool { return c >= 0 && c < 5 && r >= 0 && r < 7; }

// The square a jump in way d from square i lands on, or -1: over a piece of `them`, onto an empty
// square that is not the castle `own`.
fn jump(i: int, d: int, them: int, own: int) -> int {
  let c = i % 5 + dx[d] * 2;
  let r = i / 5 + dy[d] * 2;
  if !inside(c, r) || board[i + dy[d] * 5 + dx[d]] != them || board[r * 5 + c] != 0 || r * 5 + c == own { return -1; }
  return r * 5 + c;
}

fn canjump(side: int, them: int, own: int) -> bool {
  for i in 0..35 {
    for d in 0..8 {
      if board[i] == side && jump(i, d, them, own) >= 0 { return true; }
    }
  }
  return false;
}

fn count(side: int) -> int {
  let n = 0;
  for i in 0..35 {
    if board[i] == side { n += 1; }
  }
  return n;
}

fn setup() {
  board = [0; 35];
  board[26] = 4;
  board[27] = 4;
  board[28] = 4;
  board[22] = 4;
  board[6] = 1;
  board[7] = 1;
  board[8] = 1;
  board[12] = 1;
  sel = -1;
  playing = true;
  note = "";
}

fn judge() {
  if board[2] == 4 || count(1) == 0 { note = "You win"; }
  if board[32] == 1 || count(4) == 0 { note = "You lose"; }
  playing = note == "";
}

fn computer() {
  for i in 0..35 {
    for d in 0..8 {
      let t = jump(i, d, 4, 2);
      if board[i] == 1 && t >= 0 {
        board[(i + t) / 2] = 0;
        board[t] = 1;
        board[i] = 0;
        return;
      }
    }
  }
  for k in 0..35 {
    let i = (6 - k / 5) * 5 + k % 5;
    for d in 0..3 {
      let c = i % 5 + dx[d];
      let t = i + 5 + dx[d];
      if board[i] == 1 && inside(c, i / 5 + 1) && board[t] == 0 && t != 2 {
        board[t] = 1;
        board[i] = 0;
        return;
      }
    }
  }
}

// My piece from square s to square t, if it may go there.
fn move(s: int, t: int) {
  let ac = t % 5 - s % 5;
  let ar = t / 5 - s / 5;
  let far = max(abs(ac), abs(ar));
  if board[t] != 0 || t == 32 || far > 2 || (far == 2 && (ac % 2 != 0 || ar % 2 != 0)) { return; }
  let over = board[(s + t) / 2];
  let must = canjump(4, 1, 32);
  if (far == 1 && must) || (far == 2 && over != 1 && (over != 4 || must)) { return; }
  if far == 2 && over == 1 { board[(s + t) / 2] = 0; }
  board[t] = 4;
  board[s] = 0;
  sel = -1;
  judge();
  if playing {
    computer();
    judge();
  }
}

fn tap(c: int, r: int) {
  let i = r * 5 + c;
  if !playing || !inside(c, r) { return; }
  if board[i] == 4 {
    sel = i;
  } else if sel >= 0 {
    move(sel, i);
  }
}

fn scene() {
  let b = board;
  if b[2] == 0 { b[2] = 2; }
  if b[32] == 0 { b[32] = 2; }
  if sel >= 0 { b[sel] = 3; }
  pixels(b, 0, 0, 5, 16);
}

label "Camelot";
label "Mine: " + count(4) + "   Computer: " + count(1);
canvas 80, 112, scene() { tap(x / 16, y / 16); }
label note;
button "New game" { setup(); }

// Camelot for two: tap a man, then where it goes: a step, a canter over a friend or a jump over an
// enemy (captured). Blue starts. A man in the enemy castle, or every enemy taken, wins.
// icon: fill 4 20 4 8 8 8 8 12 10 12 10 8 14 8 14 12 16 12 16 8 20 8 20 20
state blue = [26, 27, 28];     // the men's squares, row * 5 + column
state red = [6, 7, 8];
state turn = 0;                // 0 blue, 1 red
state sel = -1;                // the square of the man picked
state note = "";

fn find(xs: [int], i: int) -> int {
  for k in 0..len(xs) {
    if xs[k] == i { return k; }
  }
  return -1;
}

fn mine(i: int) -> bool { return find(turn == 0 ? blue : red, i) >= 0; }

fn theirs(i: int) -> bool { return find(turn == 0 ? red : blue, i) >= 0; }

fn shift(from: int, to: int) {
  if turn == 0 { blue[find(blue, from)] = to; } else { red[find(red, from)] = to; }
}

fn take(i: int) {
  if turn == 0 { remove(red, find(red, i)); } else { remove(blue, find(blue, i)); }
}

// The man on s to t: a step, or two squares straight or slantwise over a man of either side.
fn go(s: int, t: int) {
  let ac = t % 5 - s % 5;
  let ar = t / 5 - s / 5;
  let far = max(abs(ac), abs(ar));
  let home = turn == 0 ? 32 : 2;
  if mine(t) || theirs(t) || t == home || far > 2 || (far == 2 && (ac % 2 != 0 || ar % 2 != 0)) { return; }
  let mid = (s + t) / 2;
  if far == 2 && !mine(mid) && !theirs(mid) { return; }
  if far == 2 && theirs(mid) { take(mid); }
  shift(s, t);
  sel = -1;
  if t == 34 - home || len(blue) == 0 || len(red) == 0 {
    note = turn == 0 ? "Blue wins!" : "Red wins!";
  } else {
    turn = 1 - turn;
  }
}

fn tap(i: int) {
  if note != "" { return; }
  if mine(i) {
    sel = i;
  } else if sel >= 0 {
    go(sel, i);
  }
}

fn scene() {
  let b = [0; 35];
  b[2] = 8;
  b[32] = 8;
  for k in 0..len(blue) { b[blue[k]] = 4; }
  for k in 0..len(red) { b[red[k]] = 1; }
  if sel >= 0 { b[sel] = 3; }
  pixels(b, 0, 0, 5, 16);
}

