// Manhole: the arrows move the lid between the manholes of the two streets; cover each one as a
// walker steps onto it. Three falls end it; 15 safe steps win. Level 2 has three manholes a street.
// icon: line 3 9 21 9 line 3 17 21 17 fill 8 15 14 15 14 19 8 19 dot 11 6 3
state px = [0; 0];             // the walkers: column, and street (0 upper, 1 lower)
state ps = [0; 0];
state level = 1;
state score = 0;
state misses = 0;
state ls = 0;                  // the lid: street, and which manhole along it
state lk = 0;
state steps = 0;               // the level's steps so far
state speed = 0;               // 500 while a game runs
state note = "";

fn holes() -> int { return level == 1 ? 2 : 3; }

fn hole(k: int) -> int {
  if level == 1 { return k == 0 ? 2 : 5; }
  if k == 0 { return 1; }
  return k == 1 ? 4 : 6;
}

fn ishole(c: int) -> bool {
  for k in 0..holes() {
    if hole(k) == c { return true; }
  }
  return false;
}

fn begin(lv: int) {
  level = lv;
  clear(px);
  clear(ps);
  ls = 0;
  lk = 0;
  steps = 0;
}

fn start() {
  score = 0;
  misses = 0;
  note = "";
  speed = 500;
  begin(1);
}

fn enter(street: int) {
  push(px, street == 0 ? 0 : 7);
  push(ps, street);
}

every speed {
  steps += 1;
  let n = len(px);
  for k in 0..n {
    let i = n - 1 - k;
    px[i] += ps[i] == 0 ? 1 : -1;
    let gone = px[i] < 0 || px[i] > 7;
    if !gone && ishole(px[i]) {
      if ps[i] == ls && px[i] == hole(lk) {
        score += 1;
      } else {
        misses += 1;
        gone = true;
      }
    }
    if gone {
      remove(px, i);
      remove(ps, i);
    }
  }
  let gap = level == 1 ? 4 : 6;
  if steps % gap == 1 { enter(0); }
  if steps % gap == 3 { enter(1); }
  if misses >= 3 {
    note = "Game over";
    speed = 0;
  } else if score >= 15 {
    note = "You win";
    speed = 0;
  } else if level == 1 && score >= 6 {
    begin(2);
  }
}

on key "left" { if speed > 0 { lk = max(0, lk - 1); } }
on key "right" { if speed > 0 { lk = min(holes() - 1, lk + 1); } }
on key "up" { if speed > 0 { ls = 0; } }
