// Manhole: press 1, 2 or 3 to put the lid on that manhole before a walker steps onto it.
// Three falls and it's over.
// icon: line 3 12 21 12 fill 8 10 16 10 16 15 8 15 dot 6 6 3
state walkers = [0; 0];        // each walker's square
state lid = 1;                 // the manhole the lid is on: 1 to 3
state secs = 0;
state score = 0;
state falls = 0;
state playing = false;

fn start() {
  clear(walkers);
  push(walkers, 0);
  secs = 0;
  score = 0;
  falls = 0;
  playing = true;
}

every 1000 {
  if playing {
    secs += 1;
    let n = len(walkers);
    for k in 0..n {
      let i = n - 1 - k;
      walkers[i] += 1;
      let m = walkers[i] / 2;
      if walkers[i] > 8 {
        remove(walkers, i);
      } else if walkers[i] % 2 == 0 && m >= 1 && m <= 3 && m == lid {
        score += 1;
      } else if walkers[i] % 2 == 0 && m >= 1 && m <= 3 {
        falls += 1;
        remove(walkers, i);
      }
    }
    if secs % 6 == 0 { push(walkers, 0); }
    playing = falls < 3;
  }
}

on key "1" { lid = 1; }
on key "2" { lid = 2; }
on key "3" { lid = 3; }

fn scene() {
  let b = [8; 9];
  for m in 1..4 { b[m * 2] = m == lid ? 2 : 4; }
  for i in 0..len(walkers) { b[walkers[i]] = 3; }
  pixels(b, 0, 0, 9, 10);
}

