// Snowball fight: left and right move you, space or Throw throws. Knock out every kid; dodge
// their snowballs, which come down in turn. Walls stop one snowball each. Two levels.
// icon: dot 8 8 4 dot 16 16 4 line 4 21 20 21
state kids = [0; 0];           // the kids' columns, in row 0
state walls = [0; 0];          // the walls' columns, in row 5
state bx = [0; 0];             // their snowballs: column and row
state by = [0; 0];
state mx = -1;                 // my snowball: column (-1: none) and row
state my = 0;
state me = 4;
state last = -1;               // the column of the kid that threw last
state level = 1;
state steps = 0;
state lives = 3;
state score = 0;
state speed = 0;               // 200 while a game runs
state note = "";

fn find(xs: [int], v: int) -> int {
  for i in 0..len(xs) {
    if xs[i] == v { return i; }
  }
  return -1;
}

fn begin(lv: int) {
  level = lv;
  kids = lv == 1 ? [1, 4, 7] : [0, 3, 5, 8];
  walls = lv == 1 ? [1, 5] : [1, 4, 7];
  clear(bx);
  clear(by);
  mx = -1;
  last = -1;
  steps = 0;
}

fn start() {
  lives = 3;
  score = 0;
  me = 4;
  note = "";
  speed = 200;
  begin(1);
}

// The next kid to throw: the first still in to the right of the last thrower, else the leftmost.
fn next() -> int {
  let pick = -1;
  let low = -1;
  for i in 0..len(kids) {
    if kids[i] > last && (pick < 0 || kids[i] < pick) { pick = kids[i]; }
    if low < 0 || kids[i] < low { low = kids[i]; }
  }
  return pick >= 0 ? pick : low;
}

every speed {
  steps += 1;
  if mx >= 0 {
    my -= 1;
    if my == 5 && find(walls, mx) >= 0 {
      remove(walls, find(walls, mx));
      mx = -1;
    } else if my == 0 {
      if find(kids, mx) >= 0 {
        remove(kids, find(kids, mx));
        score += 1;
      }
      mx = -1;
    }
  }
  let n = len(bx);
  for k in 0..n {
    let i = n - 1 - k;
    by[i] += 1;
    let hitwall = by[i] == 5 && find(walls, bx[i]) >= 0;
    if hitwall { remove(walls, find(walls, bx[i])); }
    if by[i] == 7 && bx[i] == me { lives -= 1; }
    if hitwall || by[i] == 7 {
      remove(bx, i);
      remove(by, i);
    }
  }
  if len(kids) == 0 && level == 1 {
    begin(2);
  } else if len(kids) == 0 {
    note = "You win";
    speed = 0;
  } else if lives == 0 {
    note = "Game over";
    speed = 0;
  } else if steps % (level == 1 ? 4 : 3) == 0 {
    last = next();
    push(bx, last);
    push(by, 1);
  }
}

fn throw() {
  if speed > 0 && mx < 0 {
    mx = me;
    my = 6;
  }
}

on key "left" { if speed > 0 { me = max(0, me - 1); } }
on key "right" { if speed > 0 { me = min(8, me + 1); } }
on key "space" { throw(); }

fn scene() {
  let b = [0; 72];
  for i in 0..len(kids) { b[kids[i]] = 1; }
  for i in 0..len(walls) { b[45 + walls[i]] = 2; }
  for i in 0..len(bx) { b[by[i] * 9 + bx[i]] = 6; }
  if mx >= 0 { b[my * 9 + mx] = 3; }
  b[63 + me] = 4;
  pixels(b, 0, 0, 9, 10);
  text(note, 45, 86, 8, 11);
}

