// Snowball duel: space throws, down ducks, up stands. He throws every 3 seconds and dodges every
// second snowball of yours. First to 3 hits wins.
// icon: dot 6 12 3 dot 18 12 3 dot 12 9 2
state mine = [0; 0];           // my snowballs' squares, from 0 (me) to 6 (him)
state dodged = [false; 0];     // whether he dodges each of mine
state his = [0; 0];
state thrown = 0;
state ducking = false;
state ticks = 0;               // quarter seconds since Start
state me = 0;                  // hits
state him = 0;
state playing = false;
state note = "";

fn start() {
  clear(mine);
  clear(dodged);
  clear(his);
  thrown = 0;
  ducking = false;
  ticks = 0;
  me = 0;
  him = 0;
  note = "";
  playing = true;
}

fn finish() {
  if me == 3 { note = "You win!"; }
  if him == 3 { note = "You lose"; }
  playing = note == "";
}

every 250 {
  if playing {
    ticks += 1;
    let n = len(mine);
    for k in 0..n {
      let i = n - 1 - k;
      mine[i] += 1;
      if mine[i] == 6 {
        if !dodged[i] { me += 1; }
        remove(mine, i);
        remove(dodged, i);
      }
    }
    let m = len(his);
    for k in 0..m {
      let i = m - 1 - k;
      his[i] -= 1;
      if his[i] == 0 {
        if !ducking { him += 1; }
        remove(his, i);
      }
    }
    if ticks % 12 == 0 { push(his, 6); }
    finish();
  }
}

on key "space" {
  if playing && !ducking {
    thrown += 1;
    push(mine, 0);
    push(dodged, thrown % 2 == 0);
  }
}
on key "down" { ducking = true; }
on key "up" { ducking = false; }

