// Amidar: the arrows (or a tap beside you) point the way you run along the tracks; paint them all
// to fill the boxes, two levels. The red guard walks the edge; meeting it costs one of 3 lives.
// icon: loop 3 3 21 3 21 21 3 21 line 12 3 12 21 line 3 12 21 12 dot 12 21 3
state paint = [false; 49];      // whether square c + 7 * r is painted
state px = 3;                   // the player's square, and the way it points
state py = 6;
state dx = 0;
state dy = 0;
state gx = 3;                   // the guard's square
state gy = 0;
state steps = 0;                // steps since Start
state level = 1;
state lives = 3;
state speed = 0;                // ms a step; 0 while no game runs
state result = "";

fn track(c: int, r: int) -> bool {
  return c >= 0 && c < 7 && r >= 0 && r < 7 && (c % 2 == 0 || r % 2 == 0);
}

// Whether every track square around box (c, r) is painted.
fn full(c: int, r: int) -> bool {
  for i in 0..3 {
    for j in 0..3 {
      if !paint[(r + j - 1) * 7 + c + i - 1] && (i != 1 || j != 1) { return false; }
    }
  }
  return true;
}

fn boxes() -> int {
  let n = 0;
  for i in 0..9 {
    if full(1 + 2 * (i % 3), 1 + 2 * (i / 3)) { n += 1; }
  }
  return n;
}

fn painted() -> int {
  let n = 0;
  for i in 0..49 {
    if paint[i] { n += 1; }
  }
  return n;
}

fn home() {
  px = 3;
  py = 6;
  dx = 0;
  dy = 0;
  gx = 3;
  gy = 0;
}

fn begin(l: int) {
  level = l;
  paint = [false; 49];
  paint[45] = true;
  home();
}

fn start() {
  begin(1);
  lives = 3;
  steps = 0;
  result = "";
  speed = 200;
}

// On one square: a life lost and both back at their starts.
fn meet() {
  if px == gx && py == gy {
    lives -= 1;
    home();
    if lives == 0 {
      result = "Game over";
      speed = 0;
    }
  }
}

// The guard one square clockwise around the edge.
fn walk() {
  if gy == 0 && gx < 6 {
    gx += 1;
  } else if gx == 6 && gy < 6 {
    gy += 1;
  } else if gy == 6 && gx > 0 {
    gx -= 1;
  } else {
    gy -= 1;
  }
}

fn step() {
  steps += 1;
  if track(px + dx, py + dy) {
    px += dx;
    py += dy;
  }
  paint[py * 7 + px] = true;
  let l = lives;
  if painted() == 40 && level == 2 {
    result = "You win";
    speed = 0;
  } else if painted() == 40 {
    begin(2);
  } else {
    meet();
    if lives == l && (level == 2 || steps % 2 == 0) {
      walk();
      meet();
    }
  }
}

every speed { step(); }

fn point(x: int, y: int) {
  if speed > 0 {
    dx = x;
    dy = y;
  }
}

on key "left" { point(-1, 0); }
on key "right" { point(1, 0); }
on key "up" { point(0, -1); }
on key "down" { point(0, 1); }

fn scene() {
  let cells = [-1; 49];
  for i in 0..49 {
    let c = i % 7;
    let r = i / 7;
    if track(c, r) && paint[i] {
      cells[i] = 2;
    } else if track(c, r) {
      cells[i] = 8;
    } else if full(c, r) {
      cells[i] = 4;
    }
  }
  cells[gy * 7 + gx] = 1;
  cells[py * 7 + px] = 3;
  pixels(cells, 0, 0, 7, 10);
  if result != "" { text(result, 35, 35, 10, 11); }
}

