// Amidar: the arrows run you along the lines from corner to corner, painting them; a box whose
// four sides are painted fills. Fill all 9 to win; the guard on the edge takes a life a catch.
// icon: loop 3 3 21 3 21 21 3 21 line 12 3 12 21 line 3 12 21 12 dot 3 21 3
state across = [false; 12];     // the line from corner (c, r) to (c + 1, r): r * 3 + c
state down = [false; 12];       // the line from corner (c, r) to (c, r + 1): c * 3 + r
state mx = 0;                   // my corner
state my = 3;
state gx = 3;                   // the guard's corner
state gy = 0;
state lives = 3;
state speed = 0;                // ms a guard's step; 0 while no game runs
state said = "";

fn full(c: int, r: int) -> bool {
  return across[r * 3 + c] && across[r * 3 + 3 + c] && down[c * 3 + r] && down[c * 3 + 3 + r];
}

fn filled() -> int {
  let n = 0;
  for i in 0..9 {
    if full(i % 3, i / 3) { n += 1; }
  }
  return n;
}

fn home() {
  mx = 0;
  my = 3;
  gx = 3;
  gy = 0;
}

fn caught() {
  if mx == gx && my == gy {
    lives -= 1;
    home();
    if lives == 0 {
      said = "Game over";
      speed = 0;
    }
  }
}

fn run(x: int, y: int) {
  let c = mx + x;
  let r = my + y;
  if speed == 0 || c < 0 || c > 3 || r < 0 || r > 3 { return; }
  if y == 0 { across[my * 3 + min(c, mx)] = true; }
  if x == 0 { down[mx * 3 + min(r, my)] = true; }
  mx = c;
  my = r;
  if filled() == 9 {
    said = "You win";
    speed = 0;
  }
  caught();
}

// The guard a corner clockwise round the edge.
every speed {
  if gy == 0 && gx < 3 {
    gx += 1;
  } else if gx == 3 && gy < 3 {
    gy += 1;
  } else if gy == 3 && gx > 0 {
    gx -= 1;
  } else {
    gy -= 1;
  }
  caught();
}

on key "left" { run(-1, 0); }
on key "right" { run(1, 0); }
on key "up" { run(0, -1); }
on key "down" { run(0, 1); }

fn tint(on: bool) -> int {
  if on { return 2; }
  return 8;
}

fn scene() {
  for i in 0..9 {
    if full(i % 3, i / 3) { rect(10 + 30 * (i % 3), 10 + 30 * (i / 3), 30, 30, 4); }
  }
  for i in 0..12 {
    let a = i % 3;
    let b = i / 3;
    line(10 + 30 * a, 10 + 30 * b, 40 + 30 * a, 10 + 30 * b, 3, tint(across[i]));
    line(10 + 30 * b, 10 + 30 * a, 10 + 30 * b, 40 + 30 * a, 3, tint(down[i]));
  }
  circle(10 + 30 * gx, 10 + 30 * gy, 5, 1);
  circle(10 + 30 * mx, 10 + 30 * my, 5, 3);
  if said != "" { text(said, 55, 55, 14, 11); }
}

