  if sel >= 0 { cells[sel] = 3; }
  pixels(cells, 0, 0, 5, 20);
  for i in 0..25 {
    if side[i] > 0 { text(letters[kind[i]], 10 + 20 * (i % 5), 10 + 20 * (i / 5), 12, 0); }
  }
  if over != "" { text(over, 50, 50, 14, 11); }
}

