// Tag: the arrows (or a tap beside you) point the way you run. Whoever is it chases; on the same
// square the other becomes it. Whoever is it when the 20 seconds run out loses.
// icon: dot 7 12 4 dot 17 12 4 line 10 6 14 6 line 12 4 14 6 12 8
state mx = 0;                   // me, and the way I point
state my = 0;
state dx = 0;
state dy = 0;
state cx = 8;                   // the computer
state cy = 8;
state meit = true;
state steps = 0;                // steps since Start
state speed = 0;                // ms a step; 0 while no game runs
state result = "";
state wx = [0, 1, 0, -1];       // up, right, down, left
state wy = [-1, 0, 1, 0];

fn far(x: int, y: int) -> int { return abs(x - mx) + abs(y - my); }

fn on(x: int, y: int) -> bool { return x >= 0 && x < 9 && y >= 0 && y < 9; }

fn home() {
  mx = 0;
  my = 0;
  dx = 0;
  dy = 0;
  cx = 8;
  cy = 8;
}

// On one square: the other becomes it, and both go back to their corners.
fn tag() {
  if mx == cx && my == cy {
    meit = !meit;
    home();
  }
}

// The computer's square: nearest me when it is it, else farthest (or it stays).
fn run() {
  let bx = cx;
  let by = cy;
  let best = -1;
  for k in 0..4 {
    let x = cx + wx[k];
    let y = cy + wy[k];
    if on(x, y) && (best < 0 || meit && far(x, y) > best || !meit && far(x, y) < best) {
      best = far(x, y);
      bx = x;
      by = y;
    }
  }
  if !meit || best > far(cx, cy) {
    cx = bx;
    cy = by;
  }
}

every speed {
  steps += 1;
  if on(mx + dx, my + dy) {
    mx += dx;
    my += dy;
  }
  let was = meit;
  tag();
  if meit == was && steps % 2 == 0 {
    run();
    tag();
  }
  if steps == 100 {
    speed = 0;
    result = meit ? "You lose" : "You win";
  }
}

fn point(x: int, y: int) {
  if speed > 0 {
    dx = x;
    dy = y;
  }
}

on key "left" { point(-1, 0); }
on key "right" { point(1, 0); }
on key "up" { point(0, -1); }
on key "down" { point(0, 1); }

fn scene() {
  let cells = [-1; 81];
  cells[cy * 9 + cx] = 1;
  cells[my * 9 + mx] = 4;
  pixels(cells, 0, 0, 9, 10);
  if result != "" { text(result, 45, 45, 14, 11); }
}

label "Tag";
label "Time: " + (20 - steps / 5) + "   It: " + (meit ? "You" : "Computer");
canvas 90, 90, scene() {
  let ax = x / 10 - mx;
  let ay = y / 10 - my;
  if abs(ax) > abs(ay) {
    point(ax / abs(ax), 0);
  } else if ay != 0 {
    point(0, ay / abs(ay));
  }
}
if speed == 0 {
  button "Start" {
    home();
    meit = true;
    steps = 0;
    result = "";
    speed = 200;
  }
}

// Tag: the arrows move you a square; whoever is it chases, and touching passes it (both back to
// their corners). Whoever is it when the 30 seconds run out loses.
// icon: dot 7 12 4 dot 17 12 4 line 10 6 14 6 line 12 4 14 6 12 8
state mx = 0;
state my = 0;
state cx = 7;
state cy = 7;
state meit = true;
state ticks = 0;                // half seconds since the game began
state speed = 500;
state said = "";

fn touch() {
  if mx == cx && my == cy {
    meit = !meit;
    mx = 0;
    my = 0;
    cx = 7;
    cy = 7;
  }
}

fn sign(n: int) -> int {
  if n > 0 { return 1; }
  if n < 0 { return -1; }
  return 0;
}

// The computer a square: toward me when it is it, else away from me, along the wider gap.
every speed {
  let ax = sign(mx - cx);
  let ay = sign(my - cy);
  if meit {
    ax = -ax;
    ay = -ay;
  }
  if abs(mx - cx) >= abs(my - cy) && cx + ax >= 0 && cx + ax < 8 && ax != 0 {
    cx += ax;
  } else if cy + ay >= 0 && cy + ay < 8 && ay != 0 {
    cy += ay;
  } else if cx + ax >= 0 && cx + ax < 8 {
    cx += ax;
  }
  touch();
  ticks += 1;
  if ticks == 60 {
    said = meit ? "You lose" : "You win";
    speed = 0;
  }
}

fn step(x: int, y: int) {
  if speed > 0 && mx + x >= 0 && mx + x < 8 && my + y >= 0 && my + y < 8 {
    mx += x;
    my += y;
    touch();
  }
}

on key "left" { step(-1, 0); }
on key "right" { step(1, 0); }
on key "up" { step(0, -1); }
on key "down" { step(0, 1); }

fn scene() {
  let cells = [-1; 64];
  cells[cy * 8 + cx] = 1;
  cells[my * 8 + mx] = 4;
  pixels(cells, 0, 0, 8, 10);
  if said != "" { text(said, 40, 40, 12, 11); }
}

