// Cheat: play a card face down as the next number, truthfully or not; the computer may call
// cheat, and you judge its cards with Cheat or Pass. A wrong call costs the caller the pile.
// icon: loop 4 5 13 5 13 19 4 19 fill 11 7 20 7 20 21 11 21
state mine = [1, 2, 4, 5];
state its = [1, 2, 3, 3, 5, 5];
state pile = [0; 0];
state rank = 1;                 // the number said for the card being played or judged
state judging = false;          // whether I am judging the computer's card
state over = "";

fn has(xs: [int], n: int) -> int {
  let k = 0;
  for i in 0..len(xs) {
    if xs[i] == n { k += 1; }
  }
  return k;
}

fn lowest() -> int {
  let at = 0;
  for i in 0..len(its) {
    if its[i] < its[at] { at = i; }
  }
  return at;
}

fn next() { rank = rank % 5 + 1; }

// The pile goes to my hand (true) or the computer's.
fn take(me: bool) {
  for i in 0..len(pile) {
    if me { push(mine, pile[i]); } else { push(its, pile[i]); }
  }
  clear(pile);
}

fn play(i: int) {
  if over != "" || judging { return; }
  let card = mine[i];
  remove(mine, i);
  push(pile, card);
  if has(its, rank) >= 2 { take(card != rank); }
  if len(mine) == 0 {
    over = "You win";
    return;
  }
  next();
  let at = lowest();
  for j in 0..len(its) {
    if its[j] == rank { at = j; }
  }
  push(pile, its[at]);
  remove(its, at);
  judging = true;
}

fn judge(call: bool) {
  if call { take(pile[len(pile) - 1] == rank); }
  judging = false;
  if len(its) == 0 {
    over = "You lose";
    return;
  }
  next();
}

label "Cheat";
label "Rank: " + rank + "   Pile: " + len(pile) + "   Hand: " + len(mine) + "   Computer: " + len(its);
if over != "" { label over; }
if over == "" && !judging {
  row {
    for i in 0..len(mine) { button "" + mine[i] { play(i); } }
  }
}
if over == "" && judging {
  label "The computer says its card is a " + rank;
  row {
    button "Cheat" { judge(true); }
    button "Pass" { judge(false); }
  }
}
button "New game" {
  mine = [1, 2, 4, 5];
  its = [1, 2, 3, 3, 5, 5];
  clear(pile);
  rank = 1;
  judging = false;
  over = "";
}

// Cheat for two: on your turn tap a card to put it down as the next number; the other player
// then calls Cheat or lets it go. A caught liar, or a wrong caller, takes the pile.
// icon: loop 4 5 13 5 13 19 4 19 fill 11 7 20 7 20 21 11 21
state one = [1, 3, 4, 7, 9];
state two = [5, 6];
state pile = [0; 0];
state said = 1;                 // the number the next card is said to be
state turn = 1;                 // whose card is next
state judging = false;          // whether the other player is judging the last card
state winner = 0;

// Player p picks up the pile.
fn pick(p: int) {
  for i in 0..len(pile) {
    if p == 1 { push(one, pile[i]); } else { push(two, pile[i]); }
  }
  clear(pile);
}

fn put(i: int) {
  if turn == 1 {
    push(pile, one[i]);
    remove(one, i);
  } else {
    push(pile, two[i]);
    remove(two, i);
  }
  judging = true;
}

// The last card is judged: a call, or let go. Then the other player's turn.
fn judge(call: bool) {
  let lie = pile[len(pile) - 1] != said;
  if call && lie { pick(turn); }
  if call && !lie { pick(3 - turn); }
  if len(one) == 0 { winner = 1; }
  if len(two) == 0 { winner = 2; }
  judging = false;
  said += 1;
  turn = 3 - turn;
}

label "Cheat";
if winner > 0 {
  label "Player " + winner + " wins!";
} else if judging {
  label "Player " + turn + " says it's a " + said + ". Player " + (3 - turn) + ": cheat?";
  row {
    button "Cheat!" { judge(true); }
    button "Let it go" { judge(false); }
  }
} else {
  label "Player " + turn + ": put down a " + said;
  row {
    if turn == 1 {
      for i in 0..len(one) { button "" + one[i] { put(i); } }
    } else {
      for i in 0..len(two) { button "" + two[i] { put(i); } }
    }
  }
}
label "Pile: " + len(pile) + "   Player 1: " + len(one) + " cards   Player 2: " + len(two) + " cards";

// Bottle Flip: set the power with - and +, then Flip; the bottle spins as it flies and must land
// standing up: on the floor, then a table, then a shelf. Three lives.
// icon: fill 10 21 14 21 14 10 13 7 13 4 11 4 11 7 10 10 line 4 7 6 3 line 18 3 20 7
state level = 1;
state lives = 3;
state power = 3;
state h = 0;                    // the bottle's height, its speed, and how far it has turned
state v = 0;
state turn = 0;
state top = 0;                  // the highest it went this flip
state bx = 30;                  // where it is across the canvas
state lying = false;
state speed = 0;                // ms a step; 0 while it rests
state playing = false;
state said = "";
state tables = [0, 10, 20];     // each level's surface

fn land() {
  speed = 0;
  h = tables[level - 1];
  if top > h && (turn == 0 || turn == 30 || turn == 330) {
    said = "Upright!";
    turn = 0;
    if level == 3 {
      said = "You win";
      playing = false;
    } else {
      level += 1;
      h = 0;
      bx = 30;
    }
  } else {
    said = "Fell over";
    lying = true;
    lives -= 1;
    if lives == 0 {
      said = "Fell over. Game over";
      playing = false;
    }
  }
}

every speed {
  h += v;
  turn = (turn + 30) % 360;
  let down = v < 0;
  v -= 1;
  top = max(top, h);
  bx = min(90, bx + 5);
  if down && h <= tables[level - 1] { land(); }
}

fn flip() {
  if playing && speed == 0 {
    h = 0;
    v = power;
    turn = 0;
    top = 0;
    bx = 30;
    lying = false;
    said = "";
    speed = 50;
  }
}

fn setpower(p: int) {
  if playing && speed == 0 { power = max(1, min(9, p)); }
}

fn scene() {
  rect(0, 112, 120, 8, 8);
  let t = tables[level - 1];
  if t > 0 { rect(70, 112 - 2 * t, 40, 2 * t, 8); }
  let lean = lying ? 90 : turn;
  let by = 112 - 2 * h;
  line(bx, by, bx + 14 * sin(lean) / 1000, by - 14 * cos(lean) / 1000, 5, 6);
}

label "Bottle Flip";
label "Level: " + level + "   Lives: " + lives + "   Power: " + power;
canvas 120, 120, scene();
label said;
if playing {
  row {
    button "-" { setpower(power - 1); }
    button "+" { setpower(power + 1); }
    button "Flip" { flip(); }
  }
} else {
  button "Start" {
    level = 1;
    lives = 3;
    power = 3;
    h = 0;
    turn = 0;
    bx = 30;
    lying = false;
    said = "";
    playing = true;
  }
}

// Bottle Flip: pick the power with - and +, then Flip. It spins half a turn per point of power,
// so even powers land standing. Count your landings in a row, and your best.
// icon: fill 10 21 14 21 14 10 13 7 13 4 11 4 11 7 10 10 line 4 7 6 3 line 18 3 20 7
state power = 5;
state air = 0;                  // steps of the flight still to go, of 20
state speed = 0;                // ms a step; 0 while it rests
state run = 0;
state best = 0;
state fallen = false;

every speed {
  air -= 1;
  if air == 0 {
    speed = 0;
    fallen = power % 2 == 1;
    run = fallen ? 0 : run + 1;
    best = max(best, run);
  }
}

// The bottle: half a turn per point of power over the flight, on a high arc; lying if it fell.
fn scene() {
  let a = fallen ? 90 : 9 * power * (20 - air);
  let y = 100 - air * (20 - air) / 2;
  line(60, y, 60 + sin(a) / 60, y - cos(a) / 60, 5, 6);
}

label "Bottle Flip";
