canvas 120, 120, scene();
label "In a row: " + run + "   Best: " + best;
row {
  button "-" { if speed == 0 { power = max(1, power - 1); } }
  button "+" { if speed == 0 { power = min(10, power + 1); } }
  button "Flip" {
    if speed == 0 {
      air = 20;
      fallen = false;
      speed = 50;
    }
  }
}

// Car Soccer: the arrows drive your blue car; drive into the ball to kick it, and it rolls four
// squares. Score in the computer's goal on the right; the first to 3 goals wins.
// icon: fill 2 16 22 16 20 11 15 10 13 7 7 7 5 11 2 12 dot 7 17 3 dot 17 17 3 ring 18 5 3
state mx = 3;                   // my car
state my = 3;
state cx = 7;                   // the computer's car
state cy = 3;
state bx = 5;                   // the ball: its square, the way it rolls, and steps left to roll
state by = 3;
state dx = 0;
state dy = 0;
state roll = 0;
state me = 0;
state cpu = 0;
state steps = 0;
state speed = 0;                // ms a step; 0 while no game runs
state result = "";

fn mouth(c: int, r: int) -> bool { return (c == 0 || c == 10) && r >= 2 && r <= 4; }

fn field(c: int, r: int) -> bool { return r >= 0 && r <= 6 && (c >= 1 && c <= 9 || mouth(c, r)); }

fn car(c: int, r: int) -> bool { return c == mx && r == my || c == cx && r == cy; }

fn kickoff() {
  mx = 3;
  my = 3;
  cx = 7;
  cy = 3;
  bx = 5;
  by = 3;
  roll = 0;
}

// A car at (x, y) drives a square that way: onto the ball it kicks it; returns where it ends.
fn drive(x: int, y: int, wx: int, wy: int) -> int {
  let c = x + wx;
  let r = y + wy;
  if c < 1 || c > 9 || r < 0 || r > 6 || car(c, r) { return y * 11 + x; }
  if c == bx && r == by {
    dx = wx;
    dy = wy;
    roll = 4;
    return y * 11 + x;
  }
  return r * 11 + c;
}

fn goal(mine: bool) {
  if mine { me += 1; } else { cpu += 1; }
  kickoff();
  if me == 3 || cpu == 3 {
    result = me == 3 ? "You win" : "You lose";
    speed = 0;
  }
}

every speed {
  steps += 1;
  let scored = false;
  if roll > 0 {
    roll -= 1;
    if !field(bx + dx, by + dy) {
      dx = -dx;
      dy = -dy;
    }
    if car(bx + dx, by + dy) {
      dx = -dx;
      dy = -dy;
    } else {
      bx += dx;
      by += dy;
      if mouth(bx, by) {
        goal(bx == 10);
        scored = true;
      }
    }
  }
  if !scored && speed > 0 && steps % 2 == 0 {
    let at = 0;
    if cx != bx { at = drive(cx, cy, (bx - cx) / abs(bx - cx), 0); }
    else { at = drive(cx, cy, 0, (by - cy) / abs(by - cy)); }
    cx = at % 11;
    cy = at / 11;
  }
}

fn steer(wx: int, wy: int) {
  if speed > 0 {
    let at = drive(mx, my, wx, wy);
    mx = at % 11;
    my = at / 11;
  }
}

on key "left" { steer(-1, 0); }
on key "right" { steer(1, 0); }
on key "up" { steer(0, -1); }
on key "down" { steer(0, 1); }

fn scene() {
  let cells = [-1; 77];
  for r in 2..5 {
    cells[r * 11] = 5;
    cells[r * 11 + 10] = 5;
  }
  cells[by * 11 + bx] = 3;
  cells[cy * 11 + cx] = 1;
  cells[my * 11 + mx] = 4;
  pixels(cells, 0, 0, 11, 10);
  if result != "" { text(result, 55, 35, 14, 11); }
}

label "Car Soccer";
