  }
}

// Car Soccer practice: the arrows drive your car; drive into the ball to kick it three squares.
// Put it through the middle of the right wall three times within 60 seconds.
// icon: fill 2 16 22 16 20 11 15 10 13 7 7 7 5 11 2 12 dot 7 17 3 dot 17 17 3 ring 18 5 3
state mx = 0;                   // my car
state my = 2;
state bx = 4;                   // the ball, the way it rolls, and squares still to roll
state by = 2;
state dx = 0;
state dy = 0;
state left = 0;
state goals = 0;
state ticks = 0;                // tenths of a second played
state speed = 100;              // ms a tick; 0 once the game is over
state said = "";

fn reset() {
  mx = 0;
  my = 2;
  bx = 4;
  by = 2;
  left = 0;
}

every speed {
  ticks += 1;
  if left > 0 {
    left -= 1;
    if bx + dx == 9 && by == 2 {
      goals += 1;
      reset();
      if goals == 3 {
        said = "You win";
        speed = 0;
      }
    } else {
      if bx + dx < 0 || bx + dx > 8 { dx = -dx; }
      if by + dy < 0 || by + dy > 4 { dy = -dy; }
      bx += dx;
      by += dy;
    }
  }
  if ticks == 600 && speed > 0 {
    said = "Time's up: game over";
    speed = 0;
  }
}

fn drive(x: int, y: int) {
  let c = mx + x;
  let r = my + y;
  if speed == 0 || c < 0 || c > 8 || r < 0 || r > 4 { return; }
  if c == bx && r == by {
    dx = x;
    dy = y;
    left = 3;
  } else {
    mx = c;
    my = r;
  }
}

on key "left" { drive(-1, 0); }
on key "right" { drive(1, 0); }
on key "up" { drive(0, -1); }
on key "down" { drive(0, 1); }

fn scene() {
  let cells = [-1; 45];
  cells[by * 9 + bx] = 3;
  cells[my * 9 + mx] = 4;
