}

// Pooyan: Mama Pig rides up and down (arrows) and shoots arrows (space) at the wolves floating
// down on balloons. Pop 6 for level 2 and 12 to win; three wolves landing end it.
// icon: dot 9 6 4 line 9 10 9 18 line 9 13 5 16 line 9 13 13 16 line 14 12 21 12 dot 19 18 3
state wx = [0; 0];              // the wolves' squares
state wy = [0; 0];
state ax = -1;                  // the arrow's square; -1: none flying
state ay = 0;
state py = 3;                   // Mama Pig's row
state next = 0;                 // how many wolves have appeared
state cols = [2, 5, 3, 6, 1, 4];
state level = 1;
state lives = 3;
state score = 0;
state steps = 0;
state speed = 0;                // ms a step; 0 while no game runs
state result = "";

fn spawn() {
  push(wx, cols[next % 6]);
  push(wy, 0);
  next += 1;
}

// The arrow and wolf i on one square: it pops.
fn hit(i: int) -> bool {
  if ax != wx[i] || ay != wy[i] { return false; }
  remove(wx, i);
  remove(wy, i);
  ax = -1;
  score += 1;
  if score == 6 { level = 2; }
  if score == 12 {
    result = "You win";
    speed = 0;
  }
  return true;
}

fn arrow() {
  if ax < 0 { return; }
  ax -= 1;
  for i in 0..len(wx) {
    if hit(i) { return; }
  }
}

fn fall() {
  let i = 0;
  while i < len(wx) {
    wy[i] += 1;
    if hit(i) {
      continue;
    }
    if wy[i] == 7 {
      remove(wx, i);
      remove(wy, i);
      lives -= 1;
      if lives == 0 {
        result = "Game over";
        speed = 0;
        return;
      }
      continue;
    }
    i += 1;
  }
}

every speed {
  steps += 1;
  arrow();
  if speed > 0 && (level == 2 || steps % 2 == 0) { fall(); }
  if speed > 0 && steps % 8 == 0 { spawn(); }
}

on key "up" { if speed > 0 { py = max(1, py - 1); } }
on key "down" { if speed > 0 { py = min(6, py + 1); } }
on key "space" {
  if speed > 0 && ax < 0 {
    ax = 7;
    ay = py;
  }
}

fn scene() {
  let cells = [-1; 72];
  for r in 0..8 { cells[r * 9 + 8] = 8; }
  for i in 0..len(wx) { cells[wy[i] * 9 + wx[i]] = 1; }
  if ax >= 0 { cells[ay * 9 + ax] = 6; }
  cells[py * 9 + 8] = 3;
  pixels(cells, 0, 0, 9, 10);
  if result != "" { text(result, 40, 40, 12, 11); }
}

label "Pooyan";
label "Level: " + level + "   Lives: " + lives + "   Score: " + score;
canvas 90, 80, scene();
if speed == 0 {
  button "Start" {
    clear(wx);
    clear(wy);
    ax = -1;
