state alt = 1000;
state sink = 0;
state speed = 180;
state drift = 0;
state gear = false;
state flying = false;
state result = "";

fn begin() {
  alt = 1000;
  sink = 0;
  speed = 180;
  drift = 0;
  gear = false;
  result = "";
  flying = true;
}

fn touchdown() {
  flying = false;
  if gear && speed <= 150 && sink <= 100 && abs(drift) <= 1 {
    result = "Landed!";
  } else {
    result = "Crashed!";
  }
}

every flying ? 1000 : 0 {
  drift += 1;
  alt = max(0, alt - sink);
  if alt == 0 { touchdown(); }
}

fn set_sink(d: int) { if flying { sink = min(200, max(0, sink + d)); } }
fn set_speed(d: int) { if flying { speed = min(200, max(120, speed + d)); } }
fn steer(d: int) { if flying { drift += d; } }

// The runway ahead, narrowing to the horizon, and the plane: lower as it descends, beside the
// runway as it drifts.
