// Manhunt: move with the arrows or the buttons and Search where you stand. Distance is how far
// the fugitive is, across plus down; it slips a square right every 5 turns. 30 turns to catch it.
// icon: ring 10 10 6 line 14 14 20 20
state hx = 0;               // the hunter
state hy = 7;
state fx = 5;               // the fugitive, never drawn
state fy = 2;
state turns = 0;
state searched = [false; 64];
state over = "";

fn dist() -> int { return abs(fx - hx) + abs(fy - hy); }

fn turn() {
  turns += 1;
  if turns % 5 == 0 { fx = (fx + 1) % 8; }
  if turns == 30 { over = "Escaped!"; }
}

fn step(dx: int, dy: int) {
  let nx = hx + dx;
  let ny = hy + dy;
  if over == "" && nx >= 0 && nx < 8 && ny >= 0 && ny < 8 {
    hx = nx;
    hy = ny;
    turn();
  }
}

fn search() {
  if over != "" { return; }
  if hx == fx && hy == fy {
    over = "Caught!";
  } else {
    searched[hy * 8 + hx] = true;
    turn();
  }
}

fn restart() {
  hx = 0;
  hy = 7;
  fx = 5;
  fy = 2;
  turns = 0;
  searched = [false; 64];
  over = "";
}

// The searched squares in gray, the hunter in blue.
