  let cells = [0; 64];
  for i in 0..64 {
    if searched[i] { cells[i] = 8; }
  }
  cells[hy * 8 + hx] = 4;
  pixels(cells, 0, 0, 8, 15);
}

on key "up" { step(0, -1); }
on key "down" { step(0, 1); }
on key "left" { step(-1, 0); }
