// The hider is in row 1, column 4: square 10.
fn seek(i: int) {
  if over != "" || seen[i] >= 0 { return; }
  taps += 1;
  seen[i] = abs(i % 6 - 4) + abs(i / 6 - 1);
  if seen[i] == 0 {
    score = (10 - taps) * 10;
    best = max(best, score);
    over = "Found them!";
  } else if taps == 10 {
    over = "Out of taps: they got away.";
  }
}

fn scene() {
  let cells = [8; 36];
  for i in 0..36 {
    if seen[i] >= 0 { cells[i] = 0; }
  }
  pixels(cells, 0, 0, 6, 20);
