// Vault: Start, then crack the code: tap digits 1 to 6, Back to fix one, Try to test four. Right
// counts digits in their spots, Close the others in the code. Two vaults, 6 tries and 60 s each.
// icon: ring 12 12 9 ring 12 12 4 line 12 3 12 8 line 12 16 12 21 line 3 12 8 12 line 16 12 21 12
state codes = ["3142", "6611"];
state mission = 1;
state entry = [""; 0];      // the digits typed, one letter each
state tries = 6;
state alarm = 60;
state result = "";          // what the last try scored
state over = "";
state running = false;

fn typed() -> string {
  let s = "";
  for i in 0..len(entry) { s = s + entry[i]; }
  return s;
}

// How many of digit d the string s holds.
fn many(s: string, d: string) -> int {
  let n = 0;
  for i in 0..4 {
    if s[i] == d { n += 1; }
  }
  return n;
}

fn attempt() {
  if !running || len(entry) < 4 { return; }
  let code = codes[mission - 1];
  let guess = typed();
  let right = 0;
  for i in 0..4 {
    if code[i] == guess[i] { right += 1; }
  }
  let common = 0;
  for d in 1..7 { common += min(many(code, "" + d), many(guess, "" + d)); }
  result = "Right " + right + "   Close " + (common - right);
  clear(entry);
  tries -= 1;
  if right == 4 && mission == 2 {
    over = "Vault open!";
    running = false;
  } else if right == 4 {
    mission = 2;
    tries = 6;
    alarm = 60;
  } else if tries == 0 {
    over = "Caught!";
    running = false;
  }
}

every running ? 1000 : 0 {
  alarm -= 1;
  if alarm == 0 {
    over = "Caught!";
    running = false;
  }
}

// The vault door: its dial turns a notch for each digit typed.
fn scene() {
  rect(10, 5, 100, 90, 8);
  ring(60, 50, 30, 4, 7);
  let a = len(entry) * 90;
  line(60, 50, 60 + sin(a) * 26 / 1000, 50 - cos(a) * 26 / 1000, 3, 9);
  circle(60, 50, 5, over == "Vault open!" ? 2 : 1);
}

label "Vault";
