// Sneak: Step while the guard faces the wall (3 seconds); then he turns and watches for 2, and a
// step sends you back to the door. Ten steps reach the documents.
// icon: fill 4 13 20 13 17 8 7 8 line 2 14 22 14 ring 12 18 3
state steps = 0;
state secs = 0;
state done = false;

fn watching() -> bool { return secs % 5 >= 3; }

every done ? 0 : 1000 { secs += 1; }

fn sneak() {
  if done {
    return;
  } else if watching() {
    steps = 0;
  } else {
    steps += 1;
    done = steps == 10;
  }
}

// The spy crossing the room toward the guard and the documents; the guard red while he watches.
fn scene() {
  sprite(["9"], steps * 12, 0, 10);
  sprite([watching() ? "1" : "8"], 130, 0, 10);
}

label "Sneak";
label watching() ? "The guard is watching!" : "The guard faces the wall.";
if done { label "You reached the documents!"; }
canvas 140, 10, scene();
button "Step" { sneak(); }

// Cozy garden: pick Plant, Water or Pick and tap the plots; Sleep, and what you watered grows.
// Sell flowers for coins or Gift Mia one a day: three hearts make her your best friend.
// icon: dot 12 8 5 line 12 13 12 21 line 12 17 17 14 line 12 18 7 15
state plots = [0; 15];      // 5 x 3: 0 soil, 3 a seed, 2 a sprout, 5 a bloom
state wet = [false; 15];    // watered today
state tool = 0;             // 0 plant, 1 water, 2 pick
state day = 1;
state coins = 20;
state flowers = 0;
state hearts = 0;
state gifted = false;       // a gift given today

fn tend(i: int) {
  if tool == 0 && plots[i] == 0 && coins >= 5 {
    coins -= 5;
    plots[i] = 3;
  } else if tool == 1 && (plots[i] == 3 || plots[i] == 2) {
    wet[i] = true;
  } else if tool == 2 && plots[i] == 5 {
    plots[i] = 0;
    flowers += 1;
  }
}

fn sleep() {
  for i in 0..15 {
    if wet[i] { plots[i] = plots[i] == 3 ? 2 : 5; }
  }
  wet = [false; 15];
  gifted = false;
  day += 1;
}

// The plots, with a blue ring round each one watered today.
fn scene() {
  pixels(plots, 0, 0, 5, 20);
  for i in 0..15 {
    if wet[i] { ring(i % 5 * 20 + 10, i / 5 * 20 + 10, 9, 2, 4); }
  }
}

label "Cozy garden";
label "Day " + day + "   Coins " + coins + "   Flowers " + flowers + "   Hearts " + hearts;
if hearts >= 3 { label "Mia is your best friend!"; }
canvas 100, 60, scene() { tend(y / 20 * 5 + x / 20); }
row {
  button "Plant" { tool = 0; }
  button "Water" { tool = 1; }
  button "Pick" { tool = 2; }
  button "Sleep" { sleep(); }
}
row {
  button "Sell flower" {
    if flowers > 0 {
      flowers -= 1;
      coins += 8;
    }
  }
  button "Gift" {
    if flowers > 0 && !gifted {
      flowers -= 1;
      hearts += 1;
      gifted = true;
    }
  }
}

