// Bakery rush: Open, then bake what each customer orders (one thing in the oven at a time) and
// Serve it before they give up after 15 seconds. Six customers a day.
// icon: fill 6 12 18 12 16 21 8 21 loop 5 12 7 7 12 4 17 7 19 12
state names = ["bread", "cake", "pie"];
state orders = [0, 1, 0, 2, 1, 2];
state shelf = [0, 0, 0];
state customer = 6;         // the one being served; 6 while closed
state patience = 15;
state oven = -1;            // what is baking; -1 empty
state baking = 0;           // its seconds left
state money = 10;
state stars = 3;
state days = 0;

fn next_customer() {
  customer += 1;
  patience = 15;
  if customer == 6 { oven = -1; }
}

every customer < 6 ? 1000 : 0 {
  if oven >= 0 {
    baking -= 1;
    if baking == 0 {
      shelf[oven] += 1;
      oven = -1;
    }
  }
  patience -= 1;
  if patience == 0 {
    stars = max(0, stars - 1);
    next_customer();
  }
}

fn bake(k: int) {
  let costs = [1, 3, 2];
  let times = [2, 4, 3];
  if customer < 6 && oven < 0 && money >= costs[k] {
    money -= costs[k];
    oven = k;
    baking = times[k];
  }
}

fn serve() {
  let prices = [4, 10, 7];
  if customer == 6 { return; }
  let k = orders[customer];
  if shelf[k] > 0 {
    shelf[k] -= 1;
    money += prices[k];
    next_customer();
  }
}

// The counter: the customer's order over it, and the oven glowing while it bakes.
fn scene() {
  rect(0, 50, 160, 30, 8);
  if customer < 6 {
    circle(40, 30, 12, 6);
    sprite(["333", "3.3", "333"], 34, 4, 4);
  }
  rect(110, 20, 40, 30, oven >= 0 ? 1 : 7);
}

label "Bakery rush";
label "Money $" + money + "   Stars " + stars;
if customer < 6 { label "Order " + names[orders[customer]] + "   Waiting " + patience; }
label oven < 0 ? "Oven empty" : "Oven " + names[oven] + " " + baking;
label "Loaves " + shelf[0] + "   Cakes " + shelf[1] + "   Pies " + shelf[2];
if customer == 6 && days > 0 { label "Closed"; }
canvas 160, 80, scene();
row {
  button "Bake bread" { bake(0); }
  button "Bake cake" { bake(1); }
  button "Bake pie" { bake(2); }
  button "Serve" { serve(); }
}
if customer == 6 {
  button "Open" {
    customer = 0;
    patience = 15;
    shelf = [0, 0, 0];
    oven = -1;
    money = 10;
    stars = 3;
    days += 1;
  }
}

// Till: tap Cupcake, Cookie or Loaf to ring up an order (cookies $1, or $10 a dozen), then Pay
// to add it to today's sales. Nothing sold out can be added.
// icon: loop 3 11 21 11 21 21 3 21 loop 6 4 18 4 18 11 6 11 line 7 16 17 16
state left = [10, 30, 5];   // cupcakes, cookies, loaves on hand
state order = [0, 0, 0];
state sales = 0;
state orders = 0;

fn total() -> int { return order[0] * 3 + order[1] / 12 * 10 + order[1] % 12 + order[2] * 4; }

fn add(k: int) {
  if left[k] > 0 {
    left[k] -= 1;
    order[k] += 1;
  }
}

label "Till";
row {
  button "Cupcake" { add(0); }
  button "Cookie" { add(1); }
