label "Left: " + left[0] + " cupcakes, " + left[1] + " cookies, " + left[2] + " loaves";
label "Today: $" + sales + " from " + orders + " orders";

// Game studio: pick a genre and a topic, Develop ($60) and wait 5 seconds for the reviews. Good
// pairs score 9, others 5, a repeat of the last game 3 less. $500 is a hit; under $60, bankrupt.
// icon: loop 3 7 21 7 21 17 3 17 line 6 12 10 12 line 8 10 8 14 dot 15 11 2 dot 18 14 2
state genres = ["Action", "Puzzle", "RPG"];
state topics = ["Space", "Fantasy", "Cats"];
state great = [0, 2, 1];      // the topic that suits each genre
state genre = -1;
state topic = -1;
state lastg = -1;             // the last game released
state lastt = -1;
state money = 100;
state fans = 0;
state games = 0;
state score = 0;
state secs = 0;
state speed = 0;              // 1000 while a game is in the making
state result = "";

fn free() -> bool { return speed == 0 && result == ""; }

fn review() -> int {
  let s = great[genre] == topic ? 9 : 5;
  if genre == lastg && topic == lastt { s -= 3; }
  return s;
}

fn develop() {
  if free() && genre >= 0 && topic >= 0 && money >= 60 {
    money -= 60;
    secs = 0;
    speed = 1000;
  }
}

fn release() {
  speed = 0;
  secs = 0;
  score = review();
  lastg = genre;
  lastt = topic;
  money += score * 20;
  fans += score * 10;
  games += 1;
  if money >= 500 {
    result = "Hit studio!";
  } else if money < 60 {
    result = "Bankrupt";
  }
}

every speed {
  secs += 1;
  if secs == 5 { release(); }
}

fn fresh() {
  genre = -1;
  topic = -1;
  lastg = -1;
  lastt = -1;
  money = 100;
  fans = 0;
  games = 0;
  score = 0;
  secs = 0;
  speed = 0;
  result = "";
}

fn bar() {
  let b = [8, 8, 8, 8, 8];
  for i in 0..secs { b[i] = 2; }
  pixels(b, 0, 0, 5, 20);
}

fn named(names: [string], i: int) -> string { return i < 0 ? "-" : names[i]; }

label "Game studio";
label "Money $" + money + "   Fans " + fans + "   Games " + games;
label "Genre " + named(genres, genre) + "   Topic " + named(topics, topic);
if games > 0 { label "Score " + score + "/10"; }
canvas 100, 20, bar();
label result;
row {
  for i in 0..3 { button genres[i] { if free() { genre = i; } } }
}
row {
  for i in 0..3 { button topics[i] { if free() { topic = i; } } }
}
row {
  button "Develop" { develop(); }
  if result != "" { button "New studio" { fresh(); } }
}

