// Hanukkah candles: step through the eight nights; it shows the candles lit tonight and all those
// lit so far, the shamash each night.
// icon: line 4 9 4 13 12 17 20 13 20 9 line 12 7 12 21 line 7 21 17 21 dot 4 6 2 dot 20 6 2 dot 12 4 2
state night = 1;

// Nights 1 to n light 1 + 2 + ... + n candles, and the shamash n times.
fn sofar() -> int { return night * (night + 1) / 2 + night; }

label "Hanukkah candles";
label "Night: " + night;
label "Tonight: " + (night + 1) + " candles";
label "So far: " + sofar() + " candles";
