  button "Back" { night = max(1, night - 1); }
  button "Next night" { night = min(8, night + 1); }
}

// Greater gator: set the two numbers with their + and - buttons; the gator's mouth, < > or =,
// opens toward the greater one.
// icon: line 4 5 20 12 4 19 dot 16 6 2
state a = 3;                             // the left number
state b = 7;                             // the right one

fn mouth() -> string {
  if a < b { return "<"; }
  if a > b { return ">"; }
  return "=";
}

// n moved by d, kept 0 to 20.
fn step(n: int, d: int) -> int { return min(20, max(0, n + d)); }

label "Greater gator";
label a + " " + mouth() + " " + b;
row {
  button "Left -" { a = step(a, -1); }
  button "Left +" { a = step(a, 1); }
}
row {
  button "Right -" { b = step(b, -1); }
  button "Right +" { b = step(b, 1); }
}

// Gator quiz: is the first number less than, greater than or equal to the second? Answer each
// of five pairs with <, > or =.
// icon: line 4 5 20 12 4 19 dot 16 6 2 line 19 17 21 21
state lefts = [3, 9, 5, 12, 6];
state rights = [8, 2, 5, 7, 10];
state asked = 0;                         // the pair asked; 5 once all are answered
state score = 0;

// The sign that is right for the pair asked.
fn truth() -> string {
  if lefts[asked] < rights[asked] { return "<"; }
  if lefts[asked] > rights[asked] { return ">"; }
  return "=";
}

fn answer(sign: string) {
  if sign == truth() { score += 1; }
  asked += 1;
}

label "Gator quiz";
label "Score: " + score;
if asked < 5 {
  label lefts[asked] + " ? " + rights[asked];
  row {
    button "<" { answer("<"); }
    button ">" { answer(">"); }
    button "=" { answer("="); }
  }
} else {
  label "All done";
  button "Again" {
