// Letter c moved k places (0 to 25) along the alphabet, keeping its case; anything else as it is.
fn moved(c: string, k: int) -> string {
  let lower = "abcdefghijklmnopqrstuvwxyz";
  let upper = "ABCDEFGHIJKLMNOPQRSTUVWXYZ";
  for i in 0..26 {
    if lower[i] == c { return lower[(i + k) % 26]; }
    if upper[i] == c { return upper[(i + k) % 26]; }
  }
  return c;
}

fn coded() -> string {
  let k = (parse(shift, 0) % 26 + 26) % 26;
  let out = "";
  for i in 0..len(msg) { out = out + moved(msg[i], k); }
  return out;
}

