// you can spot the one that reads.
// icon: ring 10 10 7 line 15 15 21 21 line 7 10 13 10
state msg = "";

// Letter c moved back k places (1 to 25), keeping its case; anything else as it is.
fn back(c: string, k: int) -> string {
  let lower = "abcdefghijklmnopqrstuvwxyz";
  let upper = "ABCDEFGHIJKLMNOPQRSTUVWXYZ";
  for i in 0..26 {
    if lower[i] == c { return lower[(i + 26 - k) % 26]; }
    if upper[i] == c { return upper[(i + 26 - k) % 26]; }
  }
  return c;
}

fn decoded(k: int) -> string {
  let out = "";
  for i in 0..len(msg) { out = out + back(msg[i], k); }
  return out;
}

