fn num(s: string) -> int { return min(max(parse(s, 0), 0), 1000); }

fn month_days(m: int) -> int {
  let lens = [31, 28, 31, 30, 31, 30, 31, 31, 30, 31, 30, 31];
  return lens[m - 1];
}

fn real(m: int, d: int) -> bool { return m >= 1 && m <= 12 && d >= 1 && d <= month_days(m); }

// Day of the year, Jan 1 being 1.
fn yday(m: int, d: int) -> int {
  let n = d;
  for i in 1..m { n += month_days(i); }
  return n;
}

fn date(m: int, d: int) -> string {
  let names = ["Jan", "Feb", "Mar", "Apr", "May", "Jun", "Jul", "Aug", "Sep", "Oct", "Nov", "Dec"];
  return names[m - 1] + " " + d;
}

fn add() {
  let m1 = num(am);
  let d1 = num(ad);
  let m2 = num(lm);
  let d2 = num(ld);
  if !real(m1, d1) || !real(m2, d2) { return; }
  let n = yday(m2, d2) - yday(m1, d1) + 1;
  if n < 1 { return; }
  let unit = n == 1 ? " day)" : " days)";
  push(trips, date(m1, d1) + " - " + date(m2, d2) + " (" + n + unit);
  push(days, n);
}

fn used() -> int {
  let n = 0;
  for i in 0..len(days) { n += days[i]; }
  return n;
}

