fn num(s: string) -> int { return min(max(parse(s, 0), 0), 100000); }

fn month_days(m: int) -> int {
  let lens = [31, 28, 31, 30, 31, 30, 31, 31, 30, 31, 30, 31];
  return lens[m - 1];
}

fn real(m: int, d: int) -> bool { return m >= 1 && m <= 12 && d >= 1 && d <= month_days(m); }

// The date t days after Jan 1 (0 is Jan 1), wrapping round the year.
fn date(t: int) -> string {
  let names = ["Jan", "Feb", "Mar", "Apr", "May", "Jun", "Jul", "Aug", "Sep", "Oct", "Nov", "Dec"];
  let d = t % 365;
  let m = 1;
  while d >= month_days(m) {
