// ISBN-10 check: type an ISBN-10 to see whether it is valid, or its first 9 digits to get its
// check digit. Hyphens and spaces are ignored.
// icon: loop 5 3 17 3 19 5 19 21 5 21 line 9 8 9 16 line 12 8 12 16 line 15 8 15 16
state code = "";

// The input without hyphens and spaces, a character each.
fn chars() -> [string] {
  let out = [""; 0];
  for i in 0..len(code) {
    if code[i] != "-" && code[i] != " " { push(out, code[i]); }
  }
  return out;
}

fn digit(c: string) -> int {
  let ds = "0123456789";
  for i in 0..10 {
    if ds[i] == c { return i; }
  }
  return -1;
}

// The first 9 times 10 down to 2, or -1 if one is not a digit.
fn weighed(cs: [string]) -> int {
  let s = 0;
  for i in 0..9 {
    let d = digit(cs[i]);
    if d < 0 { return -1; }
    s += d * (10 - i);
  }
  return s;
}

fn valid(cs: [string]) -> bool {
  if len(cs) != 10 || weighed(cs) < 0 { return false; }
  let last = digit(cs[9]);
  if cs[9] == "X" || cs[9] == "x" { last = 10; }
  return last >= 0 && (weighed(cs) + last) % 11 == 0;
}

fn check_digit(cs: [string]) -> string {
  let c = (11 - weighed(cs) % 11) % 11;
  if c == 10 { return "X"; }
  return "" + c;
}

fn verdict() -> string {
  let cs = chars();
  if len(cs) == 9 && weighed(cs) >= 0 { return "Check digit: " + check_digit(cs); }
  if valid(cs) { return "Valid ISBN"; }
  return "Not valid";
}

label "ISBN-10 check";
input code;
if len(chars()) > 0 { label verdict(); }

// ISBN-10 to 13: type an ISBN-10 (hyphens and spaces are fine); it shows the same book's
// ISBN-13, or says the ISBN-10 is not valid.
// icon: loop 2 5 8 5 8 19 2 19 loop 16 5 22 5 22 19 16 19 line 10 12 14 12 line 12 9 14 12 12 15
state code = "";

// The input without hyphens and spaces, a character each.
fn chars() -> [string] {
  let out = [""; 0];
  for i in 0..len(code) {
    if code[i] != "-" && code[i] != " " { push(out, code[i]); }
  }
