}

// The digit c, X (or x) as 10 when it may be, or -1.
fn worth(c: string, x_ok: bool) -> int {
  let ds = "0123456789";
  for i in 0..10 {
    if ds[i] == c { return i; }
  }
  if x_ok && (c == "X" || c == "x") { return 10; }
  return -1;
}

fn valid(cs: [string]) -> bool {
  if len(cs) != 10 { return false; }
  let s = 0;
  for i in 0..10 {
    let d = worth(cs[i], i == 9);
    if d < 0 { return false; }
    s += d * (10 - i);
  }
  return s % 11 == 0;
}

fn isbn13(cs: [string]) -> string {
  let ds = [9, 7, 8];
  for i in 0..9 { push(ds, worth(cs[i], false)); }
  let s = 0;
  let out = "";
  for i in 0..12 {
    s += i % 2 == 0 ? ds[i] : ds[i] * 3;
    out = out + ds[i];
  }
  return out + (10 - s % 10) % 10;
}

