// Checkout: type the score left to see the fewest darts that finish it, the last one on a
// double or the bull.
// icon: ring 12 12 9 ring 12 12 4 line 3 21 10 14 line 3 16 3 21 8 21
state typed = "";

// Whether one dart can score n: 1 to 20, a double, a treble, 25 or 50.
fn one(n: int) -> bool {
  if n >= 1 && n <= 20 { return true; }
  if n == 25 || n == 50 { return true; }
  if n % 2 == 0 && n >= 2 && n <= 40 { return true; }
  return n % 3 == 0 && n >= 3 && n <= 60;
}

// Whether the last dart can score n: a double or the bull.
fn last(n: int) -> bool { return n == 50 || (n % 2 == 0 && n >= 2 && n <= 40); }

// The fewest darts that score n ending on a double, or 0 when three cannot.
fn darts(n: int) -> int {
  if n < 2 || n > 170 { return 0; }
  if last(n) { return 1; }
  for d in 2..51 {
    if last(d) && one(n - d) { return 2; }
  }
  for d in 2..51 {
    if last(d) {
      for a in 1..61 {
        if one(a) && one(n - d - a) { return 3; }
      }
    }
  }
  return 0;
}

fn verdict() -> string {
  let n = darts(parse(typed, 0));
  if n == 0 { return "No checkout"; }
  if n == 1 { return "Checkout in 1 dart"; }
  return "Checkout in " + n + " darts";
}

