// Easter date: type a year to see the date of Easter Sunday (Western, Gregorian calendar).
// icon: loop 12 3 17 7 19 14 17 19 12 21 7 19 5 14 7 7 line 6 12 18 12
state year = "";

// Easter Sunday of year y as month * 100 + day: the anonymous Gregorian computus.
fn easter(y: int) -> int {
  let a = y % 19;
  let b = y / 100;
  let c = y % 100;
  let g = (b - (b + 8) / 25 + 1) / 3;
  let h = (19 * a + b - b / 4 - g + 15) % 30;
  let l = (32 + 2 * (b % 4) + 2 * (c / 4) - h - c % 4) % 7;
  let m = (a + 11 * h + 22 * l) / 451;
  let n = h + l - 7 * m + 114;
  return n / 31 * 100 + n % 31 + 1;
}

fn shown() -> string {
  let y = parse(year, 0);
  if y < 1583 || y > 4099 { return "Type a year from 1583 to 4099"; }
  let e = easter(y);
  if e / 100 == 3 { return "Easter Sunday: " + e % 100 + " March"; }
  return "Easter Sunday: " + e % 100 + " April";
}

