// Moveable feasts: step through the years with - and + to see Ash Wednesday, Good Friday,
// Easter Sunday and Pentecost (Western, Gregorian calendar).
// icon: loop 4 3 20 3 20 21 4 21 line 4 8 20 8 line 12 11 12 19 line 9 14 15 14
state year = 2026;
state months = ["January", "February", "March", "April", "May", "June", "July", "August",
  "September", "October", "November", "December"];
state lengths = [31, 28, 31, 30, 31, 30, 31, 31, 30, 31, 30, 31];

fn leap(y: int) -> bool { return y % 4 == 0 && (y % 100 != 0 || y % 400 == 0); }

// The days in month m (0 is January) of year y.
fn days(y: int, m: int) -> int {
  if m == 1 && leap(y) { return 29; }
  return lengths[m];
}

// Easter Sunday of year y as a day of the year (1 is 1 January): the anonymous Gregorian
// computus.
fn easter(y: int) -> int {
  let a = y % 19;
  let b = y / 100;
  let c = y % 100;
  let g = (b - (b + 8) / 25 + 1) / 3;
  let h = (19 * a + b - b / 4 - g + 15) % 30;
  let l = (32 + 2 * (b % 4) + 2 * (c / 4) - h - c % 4) % 7;
  let m = (a + 11 * h + 22 * l) / 451;
  let n = h + l - 7 * m + 114;
  let d = n % 31 + 1;
  if n / 31 == 4 { d += 31; }
  return days(y, 0) + days(y, 1) + d;
}

// Day n of year y as day and month.
fn date(y: int, n: int) -> string {
  let m = 0;
  let d = n;
  while d > days(y, m) {
    d -= days(y, m);
    m += 1;
  }
  return d + " " + months[m];
}

fn feast(name: string, shift: int) -> string { return name + ": " + date(year, easter(year) + shift); }

