state big = "ABCDEFGHIJKLMNOPQRSTUVWXYZ";
state small = "abcdefghijklmnopqrstuvwxyz";

// Where letter c is in the alphabet, or -1 for any other character.
fn place(c: string) -> int {
  for i in 0..26 {
    if big[i] == c || small[i] == c { return i; }
  }
  return -1;
}

fn capital(c: string) -> bool {
  let i = place(c);
  return i >= 0 && big[i] == c;
}

// c as a capital or small letter; anything else as it is.
fn cased(c: string, up: bool) -> string {
  let i = place(c);
  if i < 0 { return c; }
  if up { return big[i]; }
  return small[i];
}

// The text typed in a case: 1 upper, 2 lower, 3 title, 4 swapped.
fn change(mode: int) {
  let out = "";
  for i in 0..len(typed) {
    let c = typed[i];
    let up = mode == 1;
    if mode == 3 { up = i == 0 || typed[i - 1] == " "; }
    if mode == 4 { up = !capital(c); }
    out = out + cased(c, up);
  }
  result = out;
}

fn capitals() -> int {
  let n = 0;
  for i in 0..len(result) {
    if capital(result[i]) { n += 1; }
  }
  return n;
}

