// Name styles: type a name in camelCase, PascalCase, snake_case, kebab-case or plain words to
// see it in snake_case and kebab-case.
// icon: line 2 16 7 16 line 9 16 15 16 line 17 16 22 16 line 4 8 20 8
state name = "";
state big = "ABCDEFGHIJKLMNOPQRSTUVWXYZ";
state small = "abcdefghijklmnopqrstuvwxyz";

fn capital(c: string) -> bool {
  for i in 0..26 {
    if big[i] == c { return true; }
  }
  return false;
}

fn tiny(c: string) -> bool {
  for i in 0..26 {
    if small[i] == c { return true; }
  }
  return false;
}

// c with a capital made small.
fn low(c: string) -> string {
  for i in 0..26 {
    if big[i] == c { return small[i]; }
  }
  return c;
}

// The words of the name, in small letters.
fn words() -> [string] {
  let out = [""; 0];
  let w = "";
  for i in 0..len(name) {
    let c = name[i];
    if c == " " || c == "_" || c == "-" {
      if w != "" { push(out, w); }
      w = "";
    } else {
      if i > 0 && capital(c) && tiny(name[i - 1]) && w != "" {
        push(out, w);
        w = "";
      }
      w = w + low(c);
    }
  }
  if w != "" { push(out, w); }
  return out;
}

// The words joined by sep.
fn joined(sep: string) -> string {
  let ws = words();
  let out = "";
  for i in 0..len(ws) {
    if i > 0 { out = out + sep; }
    out = out + ws[i];
  }
  return out;
}

