// Knucklebones: Red and Blue take turns putting the die shown into a column of their own board.
// Matching dice in a column multiply; a die knocks the same number out of the column facing it.
// icon: loop 4 4 20 4 20 20 4 20 dot 9 9 2 dot 15 9 2 dot 9 15 2 dot 15 15 2
state dice = [3, 5, 3, 2, 6, 3, 4, 1, 5, 5, 2, 6, 4, 6, 1, 2];
state names = ["Red", "Blue"];
state cells = [0; 18];    // Red's 9 squares, then Blue's; 0 empty
state turn = 0;           // 0 Red, 1 Blue
state rolled = 0;         // dice placed so far
state over = false;

// Player p's column c, square s from the top.
fn at(p: int, c: int, s: int) -> int { return p * 9 + c * 3 + s; }

fn count(p: int, c: int, v: int) -> int {
  let n = 0;
  for s in 0..3 {
    if cells[at(p, c, s)] == v { n += 1; }
  }
  return n;
}

fn score(p: int) -> int {
  let t = 0;
  for c in 0..3 {
    for s in 0..3 {
      let v = cells[at(p, c, s)];
      t += v * count(p, c, v);
    }
  }
  return t;
}

fn full(p: int) -> bool {
  for c in 0..3 {
    if count(p, c, 0) > 0 { return false; }
  }
  return true;
}

// Every v out of player p's column c; the dice left close up from the top.
fn knock(p: int, c: int, v: int) {
  let kept = [0; 3];
  let n = 0;
  for s in 0..3 {
    let d = cells[at(p, c, s)];
    if d != 0 && d != v {
      kept[n] = d;
      n += 1;
    }
  }
  for s in 0..3 { cells[at(p, c, s)] = kept[s]; }
}

fn place(c: int) {
  if over || count(turn, c, 0) == 0 { return; }
  let v = dice[rolled % 16];
  cells[at(turn, c, 3 - count(turn, c, 0))] = v;
  knock(1 - turn, c, v);
  rolled += 1;
  if full(0) || full(1) {
    over = true;
  } else {
    turn = 1 - turn;
  }
}

fn said() -> string {
  if !over { return names[turn] + " rolled " + dice[rolled % 16]; }
  if score(0) > score(1) { return "Red wins"; }
  if score(1) > score(0) { return "Blue wins"; }
  return "Draw";
}

// A board: its name over three columns of three squares, each die written on its square.
fn board(p: int, x0: int) {
  text(names[p], x0 + 38, 6, 8, 9);
  for c in 0..3 {
    for s in 0..3 {
      let v = cells[at(p, c, s)];
      let shade = 7;
      if v > 0 { shade = p == 0 ? 1 : 4; }
      rect(x0 + c * 26, 14 + s * 26, 24, 24, shade);
      if v > 0 { text(v, x0 + c * 26 + 12, 26 + s * 26, 14, 0); }
    }
  }
}

fn scene() {
  board(0, 10);
  board(1, 112);
}

