// Left Right Center: press Roll for the player whose turn it is. L passes a chip left, R right,
// C into the pot, a dot keeps it. The last one with chips wins. The dice turn up dot L R dot C dot.
// icon: loop 3 3 21 3 21 21 3 21 line 9 7 9 17 16 17
state names = ["Ann", "Ben", "Cal"];
state faces = [".", "L", "R", ".", "C", "."];   // the order the dice turn up, over and over
state chips = [3, 3, 3];
state pot = 0;
state turn = 0;
state deal = 0;           // how many dice have been thrown this game
state threw = "";
state winner = -1;

fn holders() -> int {
  let n = 0;
  for i in 0..3 {
    if chips[i] > 0 { n += 1; }
  }
  return n;
}

// A chip from one player to another, or to the pot (-1).
fn give(from: int, to: int) {
  chips[from] -= 1;
  if to < 0 { pot += 1; } else { chips[to] += 1; }
}

// One die a chip, at most 3; then the turn passes left to the next player with chips.
fn roll() {
  let dice = min(3, chips[turn]);
  threw = "";
  for d in 0..dice {
    let f = faces[deal % 6];
    deal += 1;
    threw = threw + " " + f;
    if f == "L" {
      give(turn, (turn + 1) % 3);
    } else if f == "R" {
      give(turn, (turn + 2) % 3);
    } else if f == "C" {
      give(turn, -1);
    }
  }
  if holders() == 1 {
    for i in 0..3 {
      if chips[i] > 0 { winner = i; }
    }
  } else {
    turn = (turn + 1) % 3;
    while chips[turn] == 0 { turn = (turn + 1) % 3; }
  }
}

label "Left Right Center";
label "Ann: " + chips[0] + "   Ben: " + chips[1] + "   Cal: " + chips[2] + "   Pot: " + pot;
if winner >= 0 {
  label names[winner] + " wins";
} else {
  label "Turn: " + names[turn];
}
if threw != "" { label "Threw:" + threw; }
row {
  if winner < 0 { button "Roll" { roll(); } }
  button "New game" {
    chips = [3, 3, 3];
    pot = 0;
    turn = 0;
    deal = 0;
    threw = "";
    winner = -1;
  }
}

// LCR tracker: tap what each die showed for the player whose turn it is (one die a chip, up to
// 3); the chips move and the turn passes on by itself. The last one with chips wins.
// icon: dot 6 12 3 dot 12 12 3 dot 18 12 3 line 3 5 9 5 line 15 19 21 19
state names = ["Me", "Mom", "Dad"];
state chips = [3, 3, 3];
state middle = 0;
state turn = 0;
state dice = 3;           // dice to tap this turn
state winner = -1;

fn holders() -> int {
  let n = 0;
  for i in 0..3 {
    if chips[i] > 0 { n += 1; }
  }
  return n;
}

// A die's face for the player whose turn it is: 1 L, 2 R, 3 C, 0 a dot.
fn face(f: int) {
  if winner >= 0 { return; }
  if f > 0 { chips[turn] -= 1; }
  if f == 1 { chips[(turn + 1) % 3] += 1; }
  if f == 2 { chips[(turn + 2) % 3] += 1; }
  if f == 3 { middle += 1; }
  dice -= 1;
  if holders() == 1 {
    for i in 0..3 {
      if chips[i] > 0 { winner = i; }
    }
  } else if dice == 0 {
    turn = (turn + 1) % 3;
    while chips[turn] == 0 { turn = (turn + 1) % 3; }
    dice = min(3, chips[turn]);
  }
}

label "Left Right Center";
label "Me " + chips[0] + "   Mom " + chips[1] + "   Dad " + chips[2] + "   Middle " + middle;
if winner >= 0 {
  label names[winner] + " wins!";
} else {
  label names[turn] + "'s turn: " + dice + " to go";
  row {
    button "L" { face(1); }
    button "R" { face(2); }
    button "C" { face(3); }
    button "dot" { face(0); }
  }
}

// Balance the equation: tap a formula to raise its coefficient (1 to 9, then 1 again) until
// every element has as many atoms on each side; then Next. Five equations.
// icon: line 3 12 9 12 line 6 9 6 15 line 13 10 20 10 line 13 14 20 14
state forms = ["H2", "O2", "H2O", "N2", "H2", "NH3", "CH4", "O2", "CO2", "H2O", "Al", "O2", "Al2O3", "Fe", "Cl2", "FeCl3"];
state first = [0, 3, 6, 10, 13];   // each equation's first formula
state sizes = [3, 3, 4, 3, 3];     // its formulas: two left of the arrow, the rest right
state elems = ["H", "O", "", "N", "H", "", "C", "H", "O", "Al", "O", "", "Fe", "Cl", ""];
// Each formula's atoms of its equation's elements, three a formula.
state atoms = [2, 0, 0, 0, 2, 0, 2, 1, 0, 2, 0, 0, 0, 2, 0, 1, 3, 0, 1, 4, 0, 0, 0, 2, 1, 0, 2, 0, 2, 1, 1, 0, 0, 0, 2, 0, 2, 3, 0, 1, 0, 0, 0, 2, 0, 1, 3, 0];
state coef = [1, 1, 1, 1];
state eq = 0;

fn left(k: int) -> bool { return k < 2; }

fn count(e: int, onleft: bool) -> int {
  let n = 0;
  for k in 0..sizes[eq] {
    if left(k) == onleft { n += coef[k] * atoms[(first[eq] + k) * 3 + e]; }
  }
  return n;
}

fn balanced() -> bool {
  for e in 0..3 {
    if count(e, true) != count(e, false) { return false; }
  }
  return true;
}

fn equation() -> string {
  let s = "";
  for k in 0..sizes[eq] {
    if k == 2 { s = s + " -> "; } else if k > 0 { s = s + " + "; }
    s = s + coef[k] + " " + forms[first[eq] + k];
  }
  return s;
}

label "Balance the equation";
label "Equation " + (eq + 1) + " of 5";
label equation();
for e in 0..3 {
  if elems[eq * 3 + e] != "" {
    label elems[eq * 3 + e] + ": " + count(e, true) + " left, " + count(e, false) + " right";
  }
}
row {
  for k in 0..sizes[eq] {
    button forms[first[eq] + k] { coef[k] = coef[k] % 9 + 1; }
  }
}
if balanced() {
  label "Balanced!";
  if eq < 4 {
    button "Next" {
      eq += 1;
      coef = [1, 1, 1, 1];
    }
  }
}

// Balance checker: type an equation like 2H2 + O2 -> 2H2O and press Check; it says whether every
// element has as many atoms on each side. Without: brackets, like Ca(OH)2.
// icon: line 12 4 12 20 line 4 8 20 8 line 4 8 2 14 line 4 8 6 14 line 20 8 18 14 line 20 8 22 14
state typed = "";
state said = "";
state caps = "ABCDEFGHIJKLMNOPQRSTUVWXYZ";
state smalls = "abcdefghijklmnopqrstuvwxyz";
state names = [""; 0];    // the elements met, and their atoms on the left and on the right
state lefts = [0; 0];
state rights = [0; 0];

fn among(c: string, set: string) -> bool {
  for i in 0..len(set) {
    if set[i] == c { return true; }
  }
  return false;
}

// Adds n atoms of element e to a side (0 left, 1 right).
fn add(e: string, n: int, side: int) {
  let k = -1;
  for i in 0..len(names) {
    if names[i] == e { k = i; }
  }
  if k < 0 {
    push(names, e);
    push(lefts, 0);
    push(rights, 0);
    k = len(names) - 1;
  }
  if side == 0 { lefts[k] += n; } else { rights[k] += n; }
}

// Reads each term's coefficient, then its elements, each with its count.
fn check() {
  clear(names);
  clear(lefts);
  clear(rights);
  let side = 0;
  let coef = 0;
  let elem = "";
  let sub = 0;
  let s = typed + " ";
  for i in 0..len(s) {
    let c = s[i];
    let d = parse(c, -1);
    if among(c, smalls) && elem != "" {
      elem = elem + c;
    } else if d >= 0 && elem == "" {
      coef = coef * 10 + d;
    } else if d >= 0 {
      sub = sub * 10 + d;
    } else {
      if elem != "" { add(elem, max(1, coef) * max(1, sub), side); }
      elem = "";
      sub = 0;
      if among(c, caps) { elem = c; }
      if c == "+" { coef = 0; }
      if c == "-" || c == "=" || c == ">" {
        coef = 0;
        side = 1;
      }
    }
  }
  let even = len(names) > 0;
  for k in 0..len(names) {
    if lefts[k] != rights[k] { even = false; }
  }
  said = even ? "Balanced!" : "Not balanced";
}

label "Balance checker";
row {
  input typed;
  button "Check" { check(); }
}
label said;

// Tenzi: press Roll, then tap dice to hold them, and roll the rest until all ten match. The faces
// are not random: they come 3 5 1 3 6 2 3 4 3 1 5 2 6 3, over and over.
// icon: loop 3 3 12 3 12 12 3 12 loop 12 12 21 12 21 21 12 21 dot 7 7 2 dot 16 16 2
state faces = [3, 5, 1, 3, 6, 2, 3, 4, 3, 1, 5, 2, 6, 3];
state dice = [0; 10];     // each die's face; 0 before the first roll
state held = [false; 10];
state deal = 0;           // faces thrown so far this game
state rolls = 0;
state won = false;

fn roll() {
  for i in 0..10 {
    if !held[i] {
      dice[i] = faces[deal % 14];
      deal += 1;
    }
  }
  rolls += 1;
  won = true;
  for i in 0..10 {
    if dice[i] != dice[0] { won = false; }
  }
}

fn hold(i: int) {
  if dice[i] > 0 { held[i] = true; }
}

// Each die a square in its face's color (gray before the first roll); a dot marks one held.
fn scene() {
  for i in 0..10 {
    rect(i * 20 + 1, 1, 18, 18, dice[i] > 0 ? dice[i] : 8);
    if held[i] { circle(i * 20 + 4, 4, 2, 9); }
  }
}

label "Tenzi";
canvas 200, 20, scene() { hold(min(9, x / 20)); }
label "Rolls: " + rolls;
if won { label "You win!"; }
row {
  if !won { button "Roll" { roll(); } }
  button "New game" {
    dice = [0; 10];
    held = [false; 10];
    deal = 0;
    rolls = 0;
    won = false;
  }
}

// Tenzi race: press Start and everyone rolls their real dice; whoever gets tenzi taps their name
// to stop their time. Each round's times show, and everyone's best.
// icon: ring 12 13 8 line 12 13 12 8 line 9 3 15 3
state names = ["Me", "Ella", "Sam"];
state tenths = 0;         // since Start
state speed = 0;          // 100 while a round runs
state times = [-1, -1, -1];
saved state best = [-1, -1, -1];

fn shown(t: int) -> string {
