  return t / 10 + "." + t % 10 + " s";
}

fn stop(i: int) {
  if speed == 0 || times[i] >= 0 { return; }
  times[i] = tenths;
  if best[i] < 0 || tenths < best[i] { best[i] = tenths; }
  if times[0] >= 0 && times[1] >= 0 && times[2] >= 0 { speed = 0; }
}

every speed { tenths += 1; }

