// Each word whole (1: only its first letter), separated by spaces; from word a up to word b.
fn words(a: int, b: int, first: bool) -> string {
  let s = "";
  for i in a..b {
    if i > a { s = s + " "; }
    s = s + (first ? verse[i][0] : verse[i]);
  }
  return s;
}

fn check() {
  if found == 15 { return; }
  if typed == verse[found] {
    found += 1;
    hint = false;
    typed = "";
  } else {
    misses += 1;
  }
}

