// Verse memory: type a verse and press Use. Each press of Hide a word blanks out one more word,
// at random, till all are blanks; Show all brings them back.
// icon: loop 4 3 20 3 20 21 4 21 line 8 8 16 8 line 8 12 11 12 line 13 12 16 12 line 8 16 16 16
state typed = "";
state words = [""; 0];
state hidden = [false; 0];

// The typed verse, split at spaces.
fn learn() {
  clear(words);
  clear(hidden);
  let w = "";
  let s = typed + " ";
  for i in 0..len(s) {
    if s[i] != " " {
      w = w + s[i];
    } else if w != "" {
      push(words, w);
      push(hidden, false);
      w = "";
    }
  }
}

// One more word blanked: the first still showing from a random place on.
fn blank() {
  let n = len(words);
  let k = random(max(1, n));
  for j in 0..n {
    let i = (k + j) % n;
    if !hidden[i] {
      hidden[i] = true;
      return;
    }
  }
}

fn shown() -> string {
  let s = "";
  for i in 0..len(words) {
    let w = words[i];
    if hidden[i] {
      w = "";
      for c in 0..len(words[i]) { w = w + "_"; }
    }
    s = s + w + " ";
  }
  return s;
}

