// Taxman: tap a number that still has a divisor in play; you get it, and the taxman gets all
// its divisors still in play. When no such number is left, the taxman takes the rest.
// icon: ring 12 12 9 line 12 6 12 18 line 15 8 10 8 9 11 15 13 14 16 9 16
state owner = [0; 24];    // each number's: 0 in play, 1 the taxman's, 2 yours
state takes = [0; 0];     // each take's numbers, yours first, then a 0
state over = false;

fn free(n: int) -> bool { return owner[n - 1] == 0; }

// How many of n's divisors are still in play.
fn divisors(n: int) -> int {
  let k = 0;
  for d in 1..n {
    if n % d == 0 && free(d) { k += 1; }
  }
  return k;
}

fn take(n: int) {
  if over || !free(n) || divisors(n) == 0 { return; }
  owner[n - 1] = 2;
  push(takes, n);
  for d in 1..n {
    if n % d == 0 && free(d) {
      owner[d - 1] = 1;
      push(takes, d);
    }
  }
  push(takes, 0);
  let left = false;
  for m in 1..25 {
    if free(m) && divisors(m) > 0 { left = true; }
  }
  if !left {
    over = true;
    for i in 0..24 {
      if owner[i] == 0 { owner[i] = 1; }
    }
  }
}

// The last take back into play.
fn undo() {
  if over || len(takes) == 0 { return; }
  remove(takes, len(takes) - 1);
  while len(takes) > 0 && takes[len(takes) - 1] != 0 {
    owner[takes[len(takes) - 1] - 1] = 0;
    remove(takes, len(takes) - 1);
  }
}

fn total(who: int) -> int {
  let s = 0;
  for i in 0..24 {
    if owner[i] == who { s += i + 1; }
  }
  return s;
}

// Squares of 30 units: in play silver, yours green, the taxman's red; each with its number.
fn scene() {
  let tint = [7, 1, 2];
  for i in 0..24 {
    rect(i % 6 * 30 + 1, i / 6 * 30 + 1, 28, 28, tint[owner[i]]);
    text(i + 1, i % 6 * 30 + 15, i / 6 * 30 + 15, 10, 9);
  }
}

label "Taxman";
canvas 180, 120, scene() { take(min(5, x / 30) + min(3, y / 30) * 6 + 1); }
label "You: " + total(2) + "   Taxman: " + total(1);
if over {
  if total(2) > total(1) {
    label "You win";
  } else if total(2) < total(1) {
    label "Taxman wins";
  } else {
    label "Tie";
  }
}
row {
  button "Undo" { undo(); }
  button "New game" {
    owner = [0; 24];
    clear(takes);
    over = false;
  }
}

// Taxman: tap a number that still has a factor in play; you get it and the taxman gets its
// factors. When you can take nothing more, the taxman gets the rest.
// icon: ring 12 12 9 line 12 6 12 18 line 15 8 10 8 9 11 15 13 14 16 9 16
