fn factors(n: int) -> int {
  let k = 0;
  for d in 1..n {
    if n % d == 0 && owner[d - 1] == 0 { k += 1; }
  }
  return k;
}

fn take(n: int) {
  if owner[n - 1] != 0 || factors(n) == 0 { return; }
  owner[n - 1] = 2;
  for d in 1..n {
    if n % d == 0 && owner[d - 1] == 0 { owner[d - 1] = 1; }
  }
  let left = false;
  for m in 1..21 {
    if owner[m - 1] == 0 && factors(m) > 0 { left = true; }
  }
  if !left {
    for i in 0..20 {
      if owner[i] == 0 { owner[i] = 1; }
    }
  }
}

fn score(who: int) -> int {
  let s = 0;
  for i in 0..20 {
    if owner[i] == who { s += i + 1; }
  }
  return s;
}

fn colors() -> [int] {
  let tint = [0, 1, 2];
  let b = [0; 20];
  for i in 0..20 { b[i] = tint[owner[i]]; }
  return b;
}

