// The straight-line distance to 170, 60, rounded down.
fn far(i: int) -> int {
  let d2 = (tx[i] - 170) * (tx[i] - 170) + (ty[i] - 60) * (ty[i] - 60);
  let r = 0;
  while (r + 1) * (r + 1) <= d2 { r += 1; }
