// Drop7: tap a column to drop the next disc. A disc pops when its number equals the discs in its
// column or in its row's unbroken run; every 5 drops a row of gray discs rises from the bottom.
// icon: ring 12 12 9 line 8 8 16 8 11 17
state seq = [3, 2, 5, 1, 2, 2, 2, 3, 3, 5, 4, 6, 2, 5, 1, 2, 3, 2, 3, 6];
state hid = [3, 6, 1, 4, 7, 2, 5];
state num = [0; 49];
state kind = [0; 49];      // 0 empty, 1 numbered, 2 cracked, 3 gray
state k = 0;
state drops = 0;
state score = 0;
state over = false;

fn tall(c: int) -> int {
  let n = 0;
  for r in 0..7 {
    if kind[r * 7 + c] > 0 { n += 1; }
  }
  return n;
}

fn span(i: int) -> int {
  let a = i % 7;
  let b = i % 7;
  while a > 0 && kind[i - i % 7 + a - 1] > 0 { a -= 1; }
  while b < 6 && kind[i - i % 7 + b + 1] > 0 { b += 1; }
  return b - a + 1;
}

fn hit(p: [bool], i: int) -> bool {
  let c = i % 7;
  return (c > 0 && p[i - 1]) || (c < 6 && p[i + 1]) || (i >= 7 && p[i - 7]) || (i < 42 && p[i + 7]);
}

fn fall() {
  for c in 0..7 {
    let r = 6;
    for s in 0..7 {
      let j = (6 - s) * 7 + c;
      if kind[j] > 0 {
        let t = kind[j];
        let v = num[j];
        kind[j] = 0;
        kind[r * 7 + c] = t;
        num[r * 7 + c] = v;
        r -= 1;
      }
    }
  }
}

fn waves() {
  let w = 1;
  while true {
    let p = [false; 49];
    let any = false;
    for i in 0..49 {
      if kind[i] == 1 && (num[i] == tall(i % 7) || num[i] == span(i)) {
        p[i] = true;
        any = true;
      }
    }
    if !any { break; }
    for i in 0..49 {
      if p[i] {
        score += w;
        kind[i] = 0;
      } else if kind[i] >= 2 && hit(p, i) {
        kind[i] -= 1;
      }
    }
    fall();
    w += 1;
  }
}

fn rise() {
  for c in 0..7 {
    if kind[c] > 0 { over = true; }
  }
  if over { return; }
  for i in 0..42 {
    kind[i] = kind[i + 7];
    num[i] = num[i + 7];
  }
  for c in 0..7 {
    kind[42 + c] = 3;
    num[42 + c] = hid[c];
  }
  waves();
}

fn drop(c: int) {
  if over || kind[c] > 0 { return; }
  let r = 6;
  while kind[r * 7 + c] > 0 { r -= 1; }
  kind[r * 7 + c] = 1;
  num[r * 7 + c] = seq[k % len(seq)];
  k += 1;
  drops += 1;
  waves();
  if drops % 5 == 0 { rise(); }
}

fn scene() {
  for i in 0..49 {
    let x = i % 7 * 10 + 5;
    let y = i / 7 * 10 + 5;
    if kind[i] == 1 {
      circle(x, y, 4, num[i] < 7 ? num[i] : 11);
      text(num[i], x, y, 6, 9);
    } else if kind[i] > 1 {
      circle(x, y, 4, 5 + kind[i]);
    }
  }
  if over { text("Game over", 35, 35, 12, 9); }
}

