fn tall(c: int) -> int {
  let n = 0;
  for r in 0..7 {
    if num[r * 7 + c] > 0 { n += 1; }
  }
  return n;
}

fn span(i: int) -> int {
  let a = i % 7;
  let b = i % 7;
  while a > 0 && num[i - i % 7 + a - 1] > 0 { a -= 1; }
  while b < 6 && num[i - i % 7 + b + 1] > 0 { b += 1; }
  return b - a + 1;
}

fn fall() {
  for c in 0..7 {
    let r = 6;
    for s in 0..7 {
      let v = num[(6 - s) * 7 + c];
      if v > 0 {
        num[(6 - s) * 7 + c] = 0;
        num[r * 7 + c] = v;
        r -= 1;
      }
    }
  }
}

fn waves() {
  while true {
    let p = [false; 49];
    let any = false;
    for i in 0..49 {
      if num[i] > 0 && (num[i] == tall(i % 7) || num[i] == span(i)) {
