// Gobblet: pick a stack (or one of your pieces on the board), then tap where it goes; bigger pieces
// gobble smaller ones. Four of your color on top in a line wins.
// icon: ring 12 12 9 ring 12 12 5 dot 12 12 2
state board = [0; 64];     // 4 levels a square, bottom first: size, + 4 for blue
state dep = [0; 16];
state left = [4, 4, 4, 4, 4, 4];   // pieces left in red's 3 stacks, then blue's
state turn = 0;            // 0 red, 1 blue
state pick = -1;           // 0-2 a stack, 10 + square a piece on the board
state win = 0;             // 1 red, 2 blue

fn top(s: int) -> int { return dep[s] == 0 ? 0 : board[s * 4 + dep[s] - 1]; }
fn who(p: int) -> int { return p == 0 ? -1 : (p > 4 ? 1 : 0); }
fn size(p: int) -> int { return p > 4 ? p - 4 : p; }

// Square j of line k: rows 0-3, columns 4-7, then the two diagonals.
fn sq(k: int, j: int) -> int {
  if k < 4 { return k * 4 + j; }
  if k < 8 { return j * 4 + k - 4; }
  return k == 8 ? j * 5 : j * 3 + 3;
}

fn tops(k: int, p: int) -> int {
  let n = 0;
  for j in 0..4 {
    if who(top(sq(k, j))) == p { n += 1; }
  }
  return n;
}

fn three(s: int, p: int) -> bool {
  for k in 0..10 {
    for j in 0..4 {
      if sq(k, j) == s && tops(k, p) >= 3 { return true; }
    }
  }
  return false;
}

fn full(p: int) -> bool {
  for k in 0..10 {
    if tops(k, p) == 4 { return true; }
  }
  return false;
}

fn fits(s: int) -> bool {
  let t = top(s);
  if pick < 10 {
    return t == 0 || (who(t) != turn && size(t) < left[turn * 3 + pick] && three(s, 1 - turn));
  }
  return s != pick - 10 && (t == 0 || size(t) < size(top(pick - 10)));
}

fn place(s: int) {
  let p = 0;
  if pick < 10 {
    p = left[turn * 3 + pick] + turn * 4;
    left[turn * 3 + pick] -= 1;
  } else {
    p = top(pick - 10);
    dep[pick - 10] -= 1;
  }
  board[s * 4 + dep[s]] = p;
  dep[s] += 1;
  pick = -1;
  if full(turn) {
    win = turn + 1;
  } else if full(1 - turn) {
    win = 2 - turn;
  }
  turn = 1 - turn;
}

fn tap(s: int) {
  if win > 0 { return; }
  if pick >= 0 && fits(s) {
    place(s);
  } else if who(top(s)) == turn {
    pick = 10 + s;
  }
}

fn scene() {
  for g in 1..4 {
    line(g * 20, 0, g * 20, 80, 1, 8);
    line(0, g * 20, 80, g * 20, 1, 8);
  }
  for s in 0..16 {
