// Gobblet Gobblers: pick a size (or one of your pieces on the board), then tap a square; bigger
// pieces cover smaller ones. Three of your color on top in a row wins.
// icon: ring 12 12 9 ring 12 12 5 dot 12 12 2
state board = [0; 27];     // 3 levels a square: size 1-3, + 3 for blue
state dep = [0; 9];
state left = [2, 2, 2, 2, 2, 2];   // red's small, medium, large left, then blue's
state turn = 0;
state pick = -1;           // 0-2 a size, 10 + square a piece on the board
state win = 0;

fn top(s: int) -> int { return dep[s] == 0 ? 0 : board[s * 3 + dep[s] - 1]; }
fn who(p: int) -> int { return p == 0 ? -1 : (p > 3 ? 1 : 0); }
fn size(p: int) -> int { return p > 3 ? p - 3 : p; }

fn three(p: int) -> bool {
  let ls = [0, 1, 2, 3, 4, 5, 6, 7, 8, 0, 3, 6, 1, 4, 7, 2, 5, 8, 0, 4, 8, 2, 4, 6];
  for k in 0..8 {
    if who(top(ls[k * 3])) == p && who(top(ls[k * 3 + 1])) == p && who(top(ls[k * 3 + 2])) == p { return true; }
  }
  return false;
}

fn tap(s: int) {
  if win > 0 { return; }
  let big = pick < 0 ? 0 : (pick < 10 ? pick + 1 : size(top(pick - 10)));
  if big > size(top(s)) && pick != 10 + s {
    let p = big + turn * 3;
    if pick < 10 {
      left[turn * 3 + pick] -= 1;
    } else {
      dep[pick - 10] -= 1;
    }
    board[s * 3 + dep[s]] = p;
    dep[s] += 1;
    pick = -1;
    if three(turn) {
      win = turn + 1;
    } else if three(1 - turn) {
      win = 2 - turn;
    }
    turn = 1 - turn;
  } else if who(top(s)) == turn {
    pick = 10 + s;
  }
}

fn scene() {
  for s in 0..9 {
    rect(s % 3 * 20 + 1, s / 3 * 20 + 1, 18, 18, 7);
    let t = top(s);
    if t > 0 { circle(s % 3 * 20 + 10, s / 3 * 20 + 10, size(t) * 3, who(t) == 0 ? 1 : 4); }
  }
}

