// Skip-Bo solitaire: pick a hand card, the stock or a discard top, then a building pile B1-B4; a hand
// card on D1-D4 is discarded and ends the turn. Empty your stock to win.
// icon: loop 4 6 14 6 14 20 4 20 loop 10 3 20 3 20 17 line 17 7 13 11
state stock = [3, 5, 1, 8, 3, 9, 1, 6];
state hand = [1, 2, 0, 7, 4];      // 0 is SB
state draw = [6, 2, 0, 10, 12, 5, 11, 6, 2, 7, 8, 9, 0, 10];
state bp = [0, 0, 0, 0];           // the number each building pile stands at
state dp = [0; 0];                 // discarded cards, and the pile each is on
state dpi = [0; 0];
state pick = -1;                   // a hand card, 10 the stock, 20 + a discard pile
state won = false;

fn name(c: int) -> string { return c == 0 ? "SB" : "" + c; }

fn dtop(i: int) -> int {
  let t = -1;
  for j in 0..len(dp) {
    if dpi[j] == i { t = j; }
  }
  return t;
}

fn card() -> int {
  if pick >= 0 && pick < 10 { return hand[pick]; }
  if pick == 10 && len(stock) > 0 { return stock[0]; }
  if pick >= 20 && dtop(pick - 20) >= 0 { return dp[dtop(pick - 20)]; }
  return -1;
}

fn refill() {
  while len(hand) < 5 && len(draw) > 0 {
    push(hand, draw[0]);
    remove(draw, 0);
  }
}

fn build(i: int) {
  let c = card();
  if won || c < 0 || (c > 0 && c != bp[i] + 1) { return; }
  if pick < 10 {
    remove(hand, pick);
  } else if pick == 10 {
    remove(stock, 0);
  } else {
    let t = dtop(pick - 20);
    remove(dp, t);
    remove(dpi, t);
  }
  bp[i] = bp[i] == 11 ? 0 : bp[i] + 1;
  pick = -1;
  if len(hand) == 0 { refill(); }
  won = len(stock) == 0;
}

fn discard(i: int) {
  if won { return; }
  if pick >= 0 && pick < 10 {
    push(dp, hand[pick]);
    push(dpi, i);
    remove(hand, pick);
    pick = -1;
    refill();
  } else if dtop(i) >= 0 {
    pick = 20 + i;
  }
}

fn piles() -> string {
  let s = "Build:";
  for i in 0..4 { s = s + " " + (bp[i] == 0 ? "-" : "" + bp[i]); }
  return s;
}

fn tops() -> string {
  let s = "Discards:";
  for i in 0..4 { s = s + " " + (dtop(i) < 0 ? "-" : name(dp[dtop(i)])); }
  return s;
}

