// Skip-Bo for two: pick a hand card or Stock, then B1-B4 to build; D1-D4 discards a hand card and
// ends the turn. First to empty their stockpile wins.
// icon: loop 4 6 14 6 14 20 4 20 loop 10 3 20 3 20 17 line 17 7 13 11
state stock1 = [3, 6, 3, 8, 4];
state stock2 = [5, 2, 12, 9, 1];
state hand1 = [1, 2, 9, 0, 5];     // 0 is SB
state hand2 = [4, 1, 7, 11, 10];
state draw = [8, 12, 10, 6, 6, 7, 2, 3];
state bp = [0, 0, 0, 0];
state dtop = [-1, -1, -1, -1, -1, -1, -1, -1];   // the top of each discard pile, player 1's first
state p = 0;
state pick = -1;                   // a hand card, or 10 the stock
state win = 0;

fn name(c: int) -> string { return c == 0 ? "SB" : "" + c; }
fn hand() -> [int] { return p == 0 ? hand1 : hand2; }
fn stock() -> [int] { return p == 0 ? stock1 : stock2; }

fn take(i: int) {
  if p == 0 { remove(hand1, i); } else { remove(hand2, i); }
}

fn fill() {
  while len(hand()) < 5 && len(draw) > 0 {
    if p == 0 { push(hand1, draw[0]); } else { push(hand2, draw[0]); }
    remove(draw, 0);
  }
}

fn build(i: int) {
  if win > 0 || pick < 0 { return; }
  let c = pick == 10 ? stock()[0] : hand()[pick];
  if c > 0 && c != bp[i] + 1 { return; }
  if pick == 10 {
    if p == 0 { remove(stock1, 0); } else { remove(stock2, 0); }
  } else {
    take(pick);
  }
  bp[i] = bp[i] == 11 ? 0 : bp[i] + 1;
  pick = -1;
  if len(hand()) == 0 { fill(); }
  if len(stock()) == 0 { win = p + 1; }
}

fn discard(i: int) {
  if win > 0 || pick < 0 || pick == 10 { return; }
  dtop[p * 4 + i] = hand()[pick];
  take(pick);
  pick = -1;
  p = 1 - p;
  fill();
}

fn line4(xs: [int]) -> string {
  let s = "";
  for i in 0..4 { s = s + " " + (xs[i] < 0 ? "-" : name(xs[i])); }
  return s;
}

fn piles() -> string {
  let s = "Building piles:";
  for i in 0..4 { s = s + " " + (bp[i] == 0 ? "-" : "" + bp[i]); }
  return s;
}

fn mine() -> [int] { return [dtop[p * 4], dtop[p * 4 + 1], dtop[p * 4 + 2], dtop[p * 4 + 3]]; }

