// TwixT: tap a hole to place a peg; pegs a knight's move apart link unless a link is in the way.
// Red joins top to bottom, blue left to right. Blue may Swap red's first peg.
// icon: dot 6 6 3 dot 12 18 3 line 6 6 12 18 dot 18 8 3
state peg = [0; 64];       // 0 empty, 1 red, 2 blue
state la = [0; 0];         // links: the two holes, and the color
state lb = [0; 0];
state lc = [0; 0];
state turn = 1;
state moves = 0;
state win = 0;
state kx = [1, 2, 2, 1, -1, -2, -2, -1];
state ky = [2, 1, -1, -2, -2, -1, 1, 2];

fn side(a: int, b: int, c: int) -> int {
  let v = (b % 8 - a % 8) * (c / 8 - a / 8) - (b / 8 - a / 8) * (c % 8 - a % 8);
  return v > 0 ? 1 : (v < 0 ? -1 : 0);
}

fn cross(a: int, b: int, c: int, d: int) -> bool {
  if a == c || a == d || b == c || b == d { return false; }
  return side(a, b, c) * side(a, b, d) < 0 && side(c, d, a) * side(c, d, b) < 0;
}

fn free(a: int, b: int) -> bool {
  for i in 0..len(la) {
    if cross(a, b, la[i], lb[i]) { return false; }
  }
  return true;
}

fn ok(i: int) -> bool {
  let c = i % 8;
  let r = i / 8;
  if peg[i] != 0 || ((c == 0 || c == 7) && (r == 0 || r == 7)) { return false; }
  return turn == 1 ? c > 0 && c < 7 : r > 0 && r < 7;
}

// Whether p's pegs on its first edge reach its last through links.
fn joined(p: int) -> bool {
  let seen = [false; 64];
  let todo = [0; 0];
  for i in 0..64 {
    let edge = p == 1 ? i / 8 : i % 8;
    if peg[i] == p && edge == 0 {
      seen[i] = true;
      push(todo, i);
    }
  }
  while len(todo) > 0 {
    let i = todo[len(todo) - 1];
    remove(todo, len(todo) - 1);
    if (p == 1 ? i / 8 : i % 8) == 7 { return true; }
    for k in 0..len(la) {
      let j = la[k] == i ? lb[k] : (lb[k] == i ? la[k] : -1);
      if lc[k] == p && j >= 0 && !seen[j] {
        seen[j] = true;
        push(todo, j);
      }
    }
  }
  return false;
}

fn place(i: int) {
  if win > 0 || !ok(i) { return; }
  peg[i] = turn;
  moves += 1;
  for k in 0..8 {
    let c = i % 8 + kx[k];
    let r = i / 8 + ky[k];
    if c >= 0 && c < 8 && r >= 0 && r < 8 && peg[r * 8 + c] == turn && free(i, r * 8 + c) {
      push(la, i);
      push(lb, r * 8 + c);
      push(lc, turn);
    }
  }
  if joined(turn) { win = turn; }
  turn = 3 - turn;
}

fn swap() {
  for i in 0..64 {
    if peg[i] == 1 {
      peg[i] = 0;
      peg[i % 8 * 8 + i / 8] = 2;
    }
  }
  moves = 2;
  turn = 1;
}

fn scene() {
  line(10, 0, 70, 0, 2, 1);
  line(10, 80, 70, 80, 2, 1);
  line(0, 10, 0, 70, 2, 4);
  line(80, 10, 80, 70, 2, 4);
  for k in 0..len(la) {
    line(la[k] % 8 * 10 + 5, la[k] / 8 * 10 + 5, lb[k] % 8 * 10 + 5, lb[k] / 8 * 10 + 5, 1, lc[k] == 1 ? 1 : 4);
  }
  for i in 0..64 {
    circle(i % 8 * 10 + 5, i / 8 * 10 + 5, peg[i] == 0 ? 1 : 3, [8, 1, 4][peg[i]]);
  }
}

