// the other player's tile is defended (surrounded by its own color). Most tiles when all are colored wins.
// icon: loop 3 3 21 3 21 21 3 21 line 8 16 8 8 12 13 16 8 16 16
state abc = ["S", "T", "A", "R", "E", "L", "I", "N", "E", "D", "C", "O", "A", "T", "S", "P", "R", "I", "M", "E", "B", "O", "N", "D", "S"];
