fn word() -> string {
  let w = "";
  for k in 0..len(cur) { w = w + abc[cur[k]]; }
  return w;
}

fn starts(a: string, b: string) -> bool {
  if len(b) > len(a) { return false; }
  for i in 0..len(b) {
    if a[i] != b[i] { return false; }
  }
  return true;
}

fn allowed(w: string) -> bool {
  let ok = false;
  for i in 0..len(words) {
    if words[i] == w { ok = true; }
  }
  for i in 0..len(played) {
    if starts(played[i], w) { ok = false; }
  }
  return ok;
}

fn safe(i: int) -> bool {
  let c = i % 5;
  return (c == 0 || own[i - 1] == own[i]) && (c == 4 || own[i + 1] == own[i]) && (i < 5 || own[i - 5] == own[i]) && (i >= 20 || own[i + 5] == own[i]);
}

fn count(p: int) -> int {
  let n = 0;
  for i in 0..25 {
    if own[i] == p { n += 1; }
  }
  return n;
}

fn pick(i: int) {
  if done { return; }
  for k in 0..len(cur) {
    if cur[k] == i { return; }
  }
  push(cur, i);
}

fn play() {
  let w = word();
  if done || !allowed(w) { return; }
  let keep = [false; 25];
  for i in 0..25 { keep[i] = own[i] == 5 - turn && safe(i); }
  for k in 0..len(cur) {
    if !keep[cur[k]] { own[cur[k]] = turn; }
  }
  push(played, w);
  clear(cur);
  turn = 5 - turn;
  done = count(0) == 0;
}

