// Coloretto against the computer: Draw a card and put it on a row, or Take a row and sit out the
// round. Three best colors score plus, the rest minus; +2 cards add 2.
// icon: loop 4 6 12 6 12 20 4 20 loop 9 4 17 4 17 18 9 18 loop 14 6 21 6 21 20 14 20
state deck = ["red", "blue", "red", "+2", "green", "green", "yellow", "red", "purple", "blue", "blue", "green", "yellow", "+2", "red", "purple"];
state kinds = ["red", "blue", "green", "yellow", "purple", "+2"];
state rows = [""; 6];      // row i's cards at 3 * i to 3 * i + 2
state rn = [0, 0];
state taken = [false, false];
state out = [false, false];
state pile = [0; 12];      // each player's cards by kind: mine, then the computer's
state k = 0;               // cards drawn
state card = "";
state turn = 0;
state over = false;

fn kind(c: string) -> int {
  for i in 0..6 {
    if kinds[i] == c { return i; }
  }
  return 0;
}

fn room() -> int {
  for i in 0..2 {
    if !taken[i] && rn[i] < 3 { return i; }
  }
  return -1;
}

fn pass() {
  if !out[1 - turn] { turn = 1 - turn; }
}

fn place(i: int) {
  if over || card == "" || taken[i] || rn[i] == 3 { return; }
  rows[i * 3 + rn[i]] = card;
  rn[i] += 1;
  card = "";
  pass();
}

fn ends() {
  rn = [0, 0];
  taken = [false, false];
  out = [false, false];
  turn = 0;
  over = k == len(deck);
}

// The round also ends when the player to move can neither draw nor take a row.
fn settle() {
  let can = card != "" || (k < len(deck) && room() >= 0);
  for i in 0..2 {
    if !taken[i] && rn[i] > 0 { can = true; }
  }
  if !over && !can { ends(); }
}

fn take(i: int) {
  if over || card != "" || taken[i] || rn[i] == 0 { return; }
  for j in 0..rn[i] { pile[turn * 6 + kind(rows[i * 3 + j])] += 1; }
  rn[i] = 0;
  taken[i] = true;
  out[turn] = true;
  if out[0] && out[1] { ends(); } else { pass(); }
}

fn draw() {
  if !over && card == "" && k < len(deck) && room() >= 0 {
    card = deck[k];
    k += 1;
  }
}

fn bot() {
  settle();
  while !over && turn == 1 {
    let full = rn[0] == 3 && !taken[0] ? 0 : (rn[1] == 3 && !taken[1] ? 1 : -1);
    if full >= 0 {
      take(full);
    } else if k < len(deck) && room() >= 0 {
      draw();
      place(room());
    } else {
      take(!taken[0] && (taken[1] || rn[0] >= rn[1]) ? 0 : 1);
    }
    settle();
  }
}

fn score(p: int) -> int {
  let tab = [0, 1, 3, 6, 10, 15, 21];
  let all = 0;
  let lo = 99;
  let lo2 = 99;
  for c in 0..5 {
    let v = tab[min(pile[p * 6 + c], 6)];
    all += v;
    if v < lo {
      lo2 = lo;
      lo = v;
    } else if v < lo2 {
      lo2 = v;
    }
  }
  return all - 2 * (lo + lo2) + 2 * pile[p * 6 + 5];
}

fn show(i: int) -> string {
  if taken[i] { return "Row " + (i + 1) + ": taken"; }
  let s = "Row " + (i + 1) + ":";
  for j in 0..rn[i] { s = s + " " + rows[i * 3 + j]; }
  return s;
}

label "Coloretto";
