label "You: " + score(0) + "   Computer: " + score(1);
if over {
  label score(0) > score(1) ? "You win" : (score(0) < score(1) ? "You lose" : "Tie");
} else {
  row {
    button "Draw" { draw(); }
    button "Row 1" { place(0); bot(); }
    button "Row 2" { place(1); bot(); }
