}

// Coloretto for three: Draw and put the card on a row, or Take a row and sit out the round. Three
// best colors score plus, the rest minus; +2 cards add 2.
// icon: loop 4 6 12 6 12 20 4 20 loop 9 4 17 4 17 18 9 18 loop 14 6 21 6 21 20 14 20
state deck = ["red", "blue", "green", "red", "+2", "yellow", "blue", "blue", "purple", "green", "red", "yellow", "green", "+2", "purple", "red", "blue", "yellow"];
state kinds = ["red", "blue", "green", "yellow", "purple", "+2"];
state rows = [""; 9];
state rn = [0, 0, 0];
state taken = [false, false, false];
state out = [false, false, false];
state pile = [0; 18];
state k = 0;
state card = "";
state turn = 0;
state over = false;

fn kind(c: string) -> int {
  for i in 0..6 {
    if kinds[i] == c { return i; }
  }
  return 0;
}

fn pass() {
  for s in 1..4 {
    if !out[(turn + s) % 3] {
      turn = (turn + s) % 3;
      return;
    }
  }
}

fn put(i: int) {
  if card == "" || taken[i] || rn[i] == 3 { return; }
  rows[i * 3 + rn[i]] = card;
  rn[i] += 1;
  card = "";
  pass();
}

fn take(i: int) {
  if over || card != "" || taken[i] || rn[i] == 0 { return; }
  for j in 0..rn[i] { pile[turn * 6 + kind(rows[i * 3 + j])] += 1; }
  rn[i] = 0;
  taken[i] = true;
  out[turn] = true;
  if out[0] && out[1] && out[2] {
    rn = [0, 0, 0];
    taken = [false, false, false];
    out = [false, false, false];
    turn = 0;
    over = k == len(deck);
  } else {
    pass();
  }
}

fn draw() {
  let room = false;
  for i in 0..3 {
    if !taken[i] && rn[i] < 3 { room = true; }
  }
  if !over && card == "" && k < len(deck) && room {
    card = deck[k];
    k += 1;
  }
}

fn score(p: int) -> int {
  let tab = [0, 1, 3, 6, 10, 15, 21];
  let all = 0;
  let lo = 99;
  let lo2 = 99;
  for c in 0..5 {
    let v = tab[min(pile[p * 6 + c], 6)];
    all += v;
    if v < lo {
      lo2 = lo;
      lo = v;
    } else if v < lo2 {
      lo2 = v;
    }
  }
  return all - 2 * (lo + lo2) + 2 * pile[p * 6 + 5];
}

fn show(i: int) -> string {
  let s = "Row " + (i + 1) + ":";
  if taken[i] { return s + " taken"; }
  for j in 0..rn[i] { s = s + " " + rows[i * 3 + j]; }
  return s;
}

fn best() -> int {
  let b = 0;
  for p in 1..3 {
    if score(p) > score(b) { b = p; }
  }
  return b;
}

