// Rack-O against the computer: get your 10 cards going up from left to right. Tap a card to swap in
// the face-up discard, or Draw, then tap a card (or Discard). The computer plays after you.
// icon: fill 3 15 8 15 8 21 3 21 fill 10 10 15 10 15 21 10 21 fill 17 4 22 4 22 21 17 21
state mine = [2, 7, 30, 12, 16, 21, 5, 28, 1, 38];
state its = [4, 8, 10, 15, 40, 22, 26, 37, 34, 18];
state pile = [13];          // the discard pile, its top last
state deck = [9, 24, 25, 29, 19, 27, 23, 20, 31, 6, 17, 33, 11, 35, 3, 36, 14, 39, 32];
state drawn = 0;
state result = "";

fn deal() {
  mine = [2, 7, 30, 12, 16, 21, 5, 28, 1, 38];
  its = [4, 8, 10, 15, 40, 22, 26, 37, 34, 18];
  pile = [13];
  deck = [9, 24, 25, 29, 19, 27, 23, 20, 31, 6, 17, 33, 11, 35, 3, 36, 14, 39, 32];
  drawn = 0;
  result = "";
}

fn home(c: int) -> int { return (c + 3) / 4 - 1; }

fn ordered(r: [int]) -> bool {
  for i in 0..9 {
    if r[i] > r[i + 1] { return false; }
  }
  return true;
}

fn top() -> int { return pile[len(pile) - 1]; }

// The computer: the discard if its home slot holds a card not at home, else the deck's top card,
// into its home slot if that holds a card not at home, else onto the discard pile.
fn computer() {
  let h = home(top());
  if home(its[h]) != h {
    let c = top();
    remove(pile, len(pile) - 1);
    push(pile, its[h]);
    its[h] = c;
    return;
  }
  let c = deck[0];
  remove(deck, 0);
  h = home(c);
  if home(its[h]) != h {
    push(pile, its[h]);
    its[h] = c;
  } else {
    push(pile, c);
  }
}

fn judge() {
  if ordered(mine) {
    result = "You win";
  } else if ordered(its) {
    result = "You lose";
  } else if len(deck) == 0 {
    result = "Game over";
  }
}

fn endturn() {
  judge();
  if result == "" {
    computer();
    judge();
  }
}

fn slot(i: int) {
  if result != "" { return; }
  let c = drawn;
  if c == 0 {
    c = top();
    remove(pile, len(pile) - 1);
  }
  push(pile, mine[i]);
  mine[i] = c;
  drawn = 0;
  endturn();
}

fn cards() -> [string] {
  let out = [""; 0];
  for i in 0..10 { push(out, "" + mine[i]); }
  return out;
}

