}

// Rack-O solitaire: get your 10 cards going up from left to right. Tap a card to swap in the top
// discard, or Draw first and tap a card to swap the drawn one in (or Discard it).
// icon: fill 3 15 8 15 8 21 3 21 fill 10 10 15 10 15 21 10 21 fill 17 4 22 4 22 21 17 21
state rack = [3, 9, 31, 14, 18, 22, 6, 29, 2, 37];
state pile = [25];
state deck = [40, 11, 16, 10, 33, 15, 13, 38, 23, 28, 39, 30, 21, 36, 24, 35, 1, 12, 26, 34, 19, 7, 27, 5, 4, 32, 20, 8, 17];
state drawn = 0;
state won = false;

fn top() -> int { return pile[len(pile) - 1]; }

fn sorted() -> bool {
  for i in 0..9 {
    if rack[i] > rack[i + 1] { return false; }
  }
  return true;
}

fn swap(i: int) {
  if won { return; }
  let c = drawn;
  if c == 0 {
    c = top();
    remove(pile, len(pile) - 1);
  }
  push(pile, rack[i]);
  rack[i] = c;
  drawn = 0;
  won = sorted();
}

fn cards() -> [string] {
  let out = [""; 0];
  for i in 0..10 { push(out, "" + rack[i]); }
  return out;
}

