// Two Dots: tap dots of one color side by side to link them, then Pop. Close a loop of four or more
// (back on its first dot) and Pop takes every dot of that color. 8 moves.
// icon: dot 7 7 3 dot 17 7 3 dot 7 17 3 dot 17 17 3 loop 7 7 17 7 17 17 7 17
state dots = [1, 2, 4, 3, 5, 1, 2, 2, 4, 3, 3, 1, 4, 1, 1, 5, 3, 2,
  4, 1, 1, 5, 2, 2, 3, 5, 4, 4, 2, 1, 3, 5, 5, 4, 1, 1];   // 1 red 2 green 3 yellow 4 blue 5 purple
state chain = [0; 0];
state closed = false;
state score = 0;
state moves = 8;
state next = 0;           // the next new dot's place in red, green, yellow, blue, purple

fn has(i: int) -> bool {
  for k in 0..len(chain) {
    if chain[k] == i { return true; }
  }
  return false;
}

fn beside(a: int, b: int) -> bool {
  return (a / 6 == b / 6 && abs(a - b) == 1) || abs(a - b) == 6;
}

fn tap(i: int) {
  if moves == 0 || (closed && has(i)) { return; }
  let k = len(chain);
  if !closed && k > 0 {
    if chain[k - 1] == i { return; }
    if beside(i, chain[k - 1]) && dots[i] == dots[chain[0]] {
      if !has(i) {
        push(chain, i);
      } else if i == chain[0] && k >= 4 {
        closed = true;
      }
      return;
    }
  }
  chain = [i];
  closed = false;
}

// Dots fall into the gaps below them; new ones fill each column from the left, lowest gap first.
fn settle() {
  for x in 0..6 {
    let w = 5;
    for k in 0..6 {
      let y = 5 - k;
      if dots[y * 6 + x] != 0 {
        dots[w * 6 + x] = dots[y * 6 + x];
        w -= 1;
      }
    }
    for y in 0..w + 1 { dots[y * 6 + x] = 0; }
  }
  for x in 0..6 {
    for k in 0..6 {
      if dots[(5 - k) * 6 + x] == 0 {
        dots[(5 - k) * 6 + x] = 1 + next % 5;
        next += 1;
      }
    }
  }
}

fn pop() {
  if moves == 0 { return; }
  if closed {
    let c = dots[chain[0]];
    for i in 0..36 {
      if dots[i] == c {
        dots[i] = 0;
        score += 1;
      }
    }
  } else if len(chain) >= 2 {
    for k in 0..len(chain) { dots[chain[k]] = 0; }
    score += len(chain);
  } else {
    return;
  }
  moves -= 1;
  clear(chain);
  closed = false;
  settle();
}

fn scene() {
  for k in 1..len(chain) {
    let a = chain[k - 1];
    let b = chain[k];
    line(a % 6 * 20 + 10, a / 6 * 20 + 10, b % 6 * 20 + 10, b / 6 * 20 + 10, 3, 9);
  }
  for i in 0..36 {
    if has(i) { ring(i % 6 * 20 + 10, i / 6 * 20 + 10, 9, 2, closed ? 11 : 9); }
    circle(i % 6 * 20 + 10, i / 6 * 20 + 10, 6, dots[i]);
  }
  if moves == 0 { text("Game over", 60, 60, 16, 9); }
}

