// Two Dots: tap dots of one color next to each other to link them, then Pop. Dots above fall and new
// ones drop in; a point a dot.
// icon: dot 7 7 3 dot 17 7 3 dot 7 17 3 dot 17 17 3 loop 7 7 17 7 17 17 7 17
state dots = [5, 3, 2, 4, 1, 2, 4, 3, 2, 4, 1, 2, 1, 1, 2, 3, 3, 5,
  4, 2, 4, 3, 5, 5, 4, 2, 4, 1, 1, 5, 3, 3, 4, 2, 2, 1];   // 1 red 2 green 3 yellow 4 blue 5 purple
state chain = [0; 0];
state score = 0;

fn linked(i: int) -> bool {
  for k in 0..len(chain) {
    if chain[k] == i { return true; }
  }
  return false;
}

fn tap(i: int) {
  let k = len(chain);
  if k > 0 {
    let last = chain[k - 1];
    if last == i { return; }
    let beside = (i / 6 == last / 6 && abs(i - last) == 1) || abs(i - last) == 6;
    if beside && dots[i] == dots[last] && !linked(i) {
      push(chain, i);
      return;
    }
  }
  chain = [i];
}

fn pop() {
  if len(chain) < 2 { return; }
  for k in 0..len(chain) { dots[chain[k]] = 0; }
  score += len(chain);
  clear(chain);
  for x in 0..6 {
    let w = 5;
    for k in 0..6 {
      let y = 5 - k;
      if dots[y * 6 + x] != 0 {
        dots[w * 6 + x] = dots[y * 6 + x];
        w -= 1;
      }
    }
    for y in 0..w + 1 { dots[y * 6 + x] = 1 + random(5); }
  }
}

fn scene() {
  for i in 0..36 {
    if linked(i) { ring(i % 6 * 20 + 10, i / 6 * 20 + 10, 9, 2, 9); }
    circle(i % 6 * 20 + 10, i / 6 * 20 + 10, 6, dots[i]);
  }
}

