state broken = false;
state taken = [0, 0];       // North-South, East-West

fn name(c: int) -> string { return ranks[c % 13] + suits[c / 13]; }
fn turn() -> int { return (lead + len(trick)) % 4; }

fn holds(seat: int, s: int) -> bool {
