// L game: tap the 4 squares of your red L's new place, then move a yellow neutral piece (tap it,
// then an empty square) or press Done. The computer moves its blue L; who cannot move their L loses.
// icon: fill 5 3 10 3 10 16 15 16 15 21 5 21 dot 18 6 3
state mine = [1, 2, 6, 10];     // squares, sorted
state its = [5, 9, 13, 14];
state nps = [0, 15];            // the neutral pieces
state marks = [0; 0];
state phase = 0;                // 0 my L moves, 1 a neutral may move
state held = -1;
state result = "";

fn has(xs: [int], i: int) -> bool {
  for k in 0..len(xs) {
    if xs[k] == i { return true; }
  }
  return false;
}

fn same(a: [int], b: [int]) -> bool {
  for k in 0..4 {
    if a[k] != b[k] { return false; }
  }
  return true;
}

// Four squares make an L: a 3 x 2 (or 2 x 3) box, one long side full, the fourth square at an end.
fn isl(p: [int]) -> bool {
  let x0 = 9;
  let x1 = -1;
  let y0 = 9;
  let y1 = -1;
  for k in 0..4 {
    x0 = min(x0, p[k] % 4);
    x1 = max(x1, p[k] % 4);
    y0 = min(y0, p[k] / 4);
    y1 = max(y1, p[k] / 4);
  }
  if (x1 - x0 + 1) * (y1 - y0 + 1) != 6 { return false; }
  let tall = y1 - y0 == 2;
  let mid = 0;
  let side = 0;
  for k in 0..4 {
    if (tall && p[k] / 4 == y0 + 1) || (!tall && p[k] % 4 == x0 + 1) { mid += 1; }
    if (tall && p[k] % 4 == x0) || (!tall && p[k] / 4 == y0) { side += 1; }
  }
  return mid == 1 && (side == 1 || side == 3);
}

// Whether p is a place the L now on `now` may go, the other L being on `other`.
fn fits(p: [int], now: [int], other: [int]) -> bool {
  for k in 0..4 {
    if has(other, p[k]) || has(nps, p[k]) { return false; }
  }
  return isl(p) && !same(p, now);
}

// The first place in order (by its squares in reading order), or [] if none.
fn first(now: [int], other: [int]) -> [int] {
  for a in 0..13 {
    for b in a + 1..14 {
      for c in b + 1..15 {
        for d in c + 1..16 {
          if fits([a, b, c, d], now, other) { return [a, b, c, d]; }
        }
      }
    }
  }
  return [0; 0];
}

fn sorted(xs: [int]) -> [int] {
  let p = xs;
  for i in 0..4 {
    for j in 0..3 {
      if p[j] > p[j + 1] {
        let t = p[j];
        p[j] = p[j + 1];
        p[j + 1] = t;
      }
    }
  }
  return p;
}

fn endturn() {
  phase = 0;
  held = -1;
  let p = first(its, mine);
  if len(p) == 0 {
    result = "You win";
    return;
  }
  its = p;
  if len(first(mine, its)) == 0 { result = "You lose"; }
}

fn tap(i: int) {
  if result != "" { return; }
  if phase == 0 {
    if has(marks, i) { return; }
    push(marks, i);
    if len(marks) == 4 {
      let p = sorted(marks);
      if fits(p, mine, its) {
        mine = p;
        phase = 1;
      }
      clear(marks);
    }
  } else if nps[0] == i || nps[1] == i {
    held = nps[0] == i ? 0 : 1;
  } else if held >= 0 && !has(mine, i) && !has(its, i) {
    nps[held] = i;
    endturn();
  }
}

fn scene() {
  for i in 0..16 {
    let c = has(mine, i) ? 1 : has(its, i) ? 4 : 7;
    rect(i % 4 * 20, i / 4 * 20, 19, 19, c);
    if has(nps, i) { circle(i % 4 * 20 + 9, i / 4 * 20 + 9, 6, 3); }
    if has(marks, i) { ring(i % 4 * 20 + 9, i / 4 * 20 + 9, 8, 2, 11); }
  }
  if held >= 0 { ring(nps[held] % 4 * 20 + 9, nps[held] / 4 * 20 + 9, 9, 2, 11); }
}

