fn get(x: int, y: int) -> int {
  if x < 0 || x > 5 || y < 0 || y > 5 { return -1; }
  return cells[y * 6 + x];
}

fn five() -> bool {
  for i in 0..36 {
    for d in 0..4 {
      let dx = [1, 0, 1, 1][d];
      let dy = [0, 1, 1, -1][d];
      let n = 0;
      for k in 0..5 {
        if cells[i] > 0 && get(i % 6 + dx * k, i / 6 + dy * k) == cells[i] { n += 1; }
      }
      if n == 5 { return true; }
    }
  }
  return false;
}

fn full() -> bool {
  for i in 0..36 {
    if cells[i] == 0 { return false; }
  }
  return true;
}

// Chaos: the other kind, on the first empty square around my mark in reading order, else the
// first empty square of the board.
fn chaos(i: int) {
  let other = 3 - cells[i];
  for k in 0..9 {
    let x = i % 6 + k % 3 - 1;
    let y = i / 6 + k / 3 - 1;
    if k != 4 && get(x, y) == 0 {
      cells[y * 6 + x] = other;
      return;
    }
  }
  for j in 0..36 {
    if cells[j] == 0 {
      cells[j] = other;
      return;
    }
  }
}

fn place(i: int) {
  if result != "" || cells[i] != 0 { return; }
  cells[i] = sym;
  if !five() { chaos(i); }
  if five() {
    result = "Order wins";
  } else if full() {
    result = "Chaos wins";
  }
}

