      let n = 0;
      for k in 0..5 {
        if cells[i] > 0 && get(i % 6 + [1, 0, 1, 1][d] * k, i / 6 + [0, 1, 1, -1][d] * k) == cells[i] { n += 1; }
      }
      if n == 5 { return true; }
    }
  }
  return false;
}

fn place(i: int) {
  if result != "" || cells[i] != 0 { return; }
  cells[i] = sym;
  let full = true;
  for j in 0..36 {
    if cells[j] == 0 { full = false; }
  }
  if five() {
    result = "Order wins";
  } else if full {
    result = "Chaos wins";
  }
}

fn scene() {
  for i in 0..36 {
    let x = i % 6 * 20;
    let y = i / 6 * 20;
    rect(x, y, 19, 19, 7);
    if cells[i] == 1 {
      line(x + 4, y + 4, x + 14, y + 14, 3, 1);
      line(x + 14, y + 4, x + 4, y + 14, 3, 1);
    }
    if cells[i] == 2 { ring(x + 9, y + 9, 6, 2, 4); }
  }
}

