// Sagrada solo: ten rounds of three dice. Pick a die, then tap a square of your window to place it
// (two a round, or Pass). Keep the window's colors and values, and like dice apart.
// icon: loop 3 3 21 3 21 21 3 21 dot 8 8 2 dot 12 12 2 dot 16 16 2
state pat = ["3", "", "R", "", "5", "", "G", "", "1", "", "B", "", "6", "", "Y", "", "2", "", "P", ""];
state all = ["P3", "Y4", "G1", "B6", "G2", "Y3", "R4", "B3", "Y4", "R4", "G6", "G5", "Y2", "B4", "P1",
  "G2", "B1", "R6", "G6", "R3", "P4", "B5", "P6", "Y1", "R5", "G3", "B2", "P2", "Y5", "R1"];
state names = ["R", "G", "Y", "B", "P"];
state win = [""; 20];
state round = 1;
state offer = ["P3", "Y4", "G1"];
state picked = -1;
state placed = 0;

fn code(d: string) -> int {
  for k in 0..5 {
    if names[k] == d[0] { return k + 1; }
  }
  return 0;
}

fn used() -> int {
  let n = 0;
  for i in 0..20 {
    if win[i] != "" { n += 1; }
  }
  return n;
}

fn at(x: int, y: int) -> string {
  if x < 0 || x > 4 || y < 0 || y > 3 { return ""; }
  return win[y * 5 + x];
}

fn legal(d: string, i: int) -> bool {
  let x = i % 5;
  let y = i / 5;
  let p = pat[i];
  if win[i] != "" { return false; }
  if p != "" && parse(p, 0) == 0 && p != d[0] { return false; }
  if p != "" && parse(p, 0) > 0 && p != d[1] { return false; }
  if used() == 0 {
    if x > 0 && x < 4 && y > 0 && y < 3 { return false; }
  } else {
    let near = false;
    for k in 0..9 {
      if k != 4 && at(x + k % 3 - 1, y + k / 3 - 1) != "" { near = true; }
    }
    if !near { return false; }
  }
  for k in 0..4 {
    let o = at(x + [1, -1, 0, 0][k], y + [0, 0, 1, -1][k]);
    if o != "" && (o[0] == d[0] || o[1] == d[1]) { return false; }
  }
  return true;
}

fn nextround() {
  round += 1;
  picked = -1;
  placed = 0;
  clear(offer);
  if round <= 10 {
    for k in 0..3 { push(offer, all[(round - 1) * 3 + k]); }
  }
}

fn tap(i: int) {
  if picked < 0 || !legal(offer[picked], i) { return; }
  win[i] = offer[picked];
  remove(offer, picked);
  picked = -1;
  placed += 1;
  if placed == 2 { nextround(); }
}

fn score() -> int {
  let s = used() - 20;
  for i in 0..20 {
    if win[i] != "" && win[i][0] == "P" { s += parse(win[i][1], 0); }
  }
  for x in 0..5 {
    let ok = true;
    for a in 0..4 {
      if at(x, a) == "" { ok = false; }
    }
    for a in 0..4 {
      for b in 0..4 {
        if ok && a != b && at(x, a)[0] == at(x, b)[0] { ok = false; }
      }
    }
    if ok { s += 5; }
  }
  return s;
}

fn scene() {
  for i in 0..20 {
    let x = i % 5 * 20;
    let y = i / 5 * 20;
    if win[i] != "" {
      rect(x, y, 19, 19, code(win[i]));
      text(win[i][1], x + 10, y + 10, 10, 9);
    } else {
      rect(x, y, 19, 19, 7);
      text(pat[i], x + 10, y + 10, 8, 10);
    }
  }
}

