state picked = -1;

fn at(x: int, y: int) -> string {
  if x < 0 || x > 4 || y < 0 || y > 3 { return ""; }
  return win[y * 5 + x];
}

fn empty() -> int {
  let n = 0;
  for i in 0..20 {
    if win[i] == "" { n += 1; }
  }
  return n;
}

fn fits(d: string, i: int) -> bool {
  let x = i % 5;
  let y = i / 5;
  if win[i] != "" { return false; }
  let near = empty() == 20 && (x == 0 || x == 4 || y == 0 || y == 3);
  for k in 0..9 {
    if k != 4 && at(x + k % 3 - 1, y + k / 3 - 1) != "" { near = true; }
  }
  for k in 0..4 {
    let o = at(x + [1, -1, 0, 0][k], y + [0, 0, 1, -1][k]);
    if o != "" && (o[0] == d[0] || o[1] == d[1]) { return false; }
  }
  return near;
}

fn place(i: int) {
  if turn >= 10 || picked < 0 || !fits(dice[turn * 2 + picked], i) { return; }
  win[i] = dice[turn * 2 + picked];
  turn += 1;
  picked = -1;
}

fn score() -> int {
  let s = -empty();
  for i in 0..20 {
    if win[i] != "" { s += parse(win[i][1], 0); }
