// Dodgem: tap one of your blue cars, then an arrow (or Up, Down, Right) moves it a square; drive
// them off the right edge. The computer's red cars head up. No move on your own turn, you win.
// icon: loop 3 15 6 8 18 8 21 15 21 18 3 18 dot 8 18 3 dot 16 18 3
state bx = [0, 0, 0];     // my cars, column and row; 9 once off the board
state by = [0, 1, 2];
state rx = [1, 2, 3];     // the computer's
state ry = [3, 3, 3];
state pick = -1;
state result = "";

fn blueat(x: int, y: int) -> int {
  for i in 0..3 {
    if bx[i] == x && by[i] == y { return i; }
  }
  return -1;
}

fn redat(x: int, y: int) -> int {
  for i in 0..3 {
    if rx[i] == x && ry[i] == y { return i; }
  }
  return -1;
}

fn free(x: int, y: int) -> bool {
  return x >= 0 && x < 4 && y >= 0 && y < 4 && blueat(x, y) < 0 && redat(x, y) < 0;
}

// Blue leaves only off the right edge, red only off the top.
fn bluecan(i: int, dx: int, dy: int) -> bool {
  if bx[i] == 9 { return false; }
  if bx[i] + dx == 4 { return true; }
  return free(bx[i] + dx, by[i] + dy);
}

fn redcan(i: int, dx: int, dy: int) -> bool {
  if rx[i] == 9 { return false; }
  if ry[i] + dy == -1 { return true; }
  return free(rx[i] + dx, ry[i] + dy);
}

fn bluemoves() -> bool {
  for i in 0..3 {
    if bluecan(i, 1, 0) || bluecan(i, 0, -1) || bluecan(i, 0, 1) { return true; }
  }
  return false;
}

fn redmoves() -> bool {
  for i in 0..3 {
    if redcan(i, 0, -1) || redcan(i, -1, 0) || redcan(i, 1, 0) { return true; }
  }
  return false;
}

// The computer: its first car in reading order that can go up, else left, else right.
fn computer() {
  for d in 0..3 {
    let dx = [0, -1, 1][d];
    let dy = [-1, 0, 0][d];
    for k in 0..16 {
      let j = redat(k % 4, k / 4);
      if j >= 0 && redcan(j, dx, dy) {
        rx[j] += dx;
        ry[j] += dy;
        if ry[j] < 0 {
          rx[j] = 9;
          ry[j] = 9;
        }
        return;
      }
    }
  }
}

fn go(dx: int, dy: int) {
  if result != "" || pick < 0 || !bluecan(pick, dx, dy) { return; }
  bx[pick] += dx;
  by[pick] += dy;
  if bx[pick] == 4 {
    bx[pick] = 9;
    by[pick] = 9;
    pick = -1;
  }
  if !redmoves() {
    result = "You lose";
    return;
  }
  computer();
  if !bluemoves() { result = "You win"; }
}

fn tap(x: int, y: int) {
  if result == "" && blueat(x, y) >= 0 { pick = blueat(x, y); }
}

fn reset() {
  bx = [0, 0, 0];
  by = [0, 1, 2];
  rx = [1, 2, 3];
  ry = [3, 3, 3];
  pick = -1;
  result = "";
}

fn scene() {
  for k in 0..16 { rect(k % 4 * 20, k / 4 * 20, 19, 19, 7); }
  for i in 0..3 {
    if bx[i] < 9 { rect(bx[i] * 20 + 3, by[i] * 20 + 5, 13, 9, 4); }
    if rx[i] < 9 { rect(rx[i] * 20 + 5, ry[i] * 20 + 3, 9, 13, 1); }
  }
  if pick >= 0 { ring(bx[pick] * 20 + 9, by[pick] * 20 + 9, 9, 1, 11); }
}

