// Dodgem for two: tap one of your cars, then an arrow moves it a square. Blue drives off the right
// side, red off the top; the first to get both cars off wins.
// icon: loop 3 15 6 8 18 8 21 15 21 18 3 18 dot 8 18 3 dot 16 18 3
state xs = [0, 0, 1, 2];     // blue's two cars, then red's; 9 once off
state ys = [0, 1, 2, 2];
state turn = 0;              // 0 blue, 1 red
state pick = -1;
state winner = "";

fn at(x: int, y: int) -> int {
  for i in 0..4 {
    if xs[i] == x && ys[i] == y { return i; }
  }
  return -1;
}

fn go(dx: int, dy: int) {
  if winner != "" || pick < 0 { return; }
  let blue = pick < 2;
  if (blue && dx == -1) || (!blue && dy == 1) { return; }
  let nx = xs[pick] + dx;
  let ny = ys[pick] + dy;
  if (blue && nx == 3) || (!blue && ny == -1) {
    xs[pick] = 9;
    ys[pick] = 9;
  } else if nx >= 0 && nx < 3 && ny >= 0 && ny < 3 && at(nx, ny) < 0 {
    xs[pick] = nx;
    ys[pick] = ny;
  } else {
    return;
  }
  let a = turn * 2;
  if xs[a] == 9 && xs[a + 1] == 9 { winner = turn == 0 ? "Blue wins" : "Red wins"; }
  turn = 1 - turn;
  pick = -1;
}

fn scene() {
