// Zuma: left and right aim the shooter, space (or Shoot) fires its ball into the rolling chain;
// three or more of a color side by side pop. Clear two chains before they reach the end.
// icon: dot 5 6 3 dot 12 5 3 dot 19 6 3 line 12 19 12 11 dot 12 19 3
state chain = [0; 0];           // the chain's colors, from its back (left) to its front
state back = 0;                 // the column of its back ball
state aim = 7;
state order = [1, 3, 4];        // the shooter's balls: red, yellow, blue, over and over
state shots = 0;
state level = 1;
state score = 0;
state steps = 0;
state speed = 0;                // ms a step; 0 while no game runs
state result = "";

fn setup(n: int) {
  if n == 1 {
    chain = [1, 1, 4, 4, 1, 3, 1, 1];
  } else {
    chain = [3, 3, 1, 1, 4, 4, 1, 3, 3];
  }
  back = 0;
  level = n;
}

fn stop(s: string) {
  result = s;
  speed = 0;
}

// The line of one color through ball i pops if it is 3 or more: returns where the gap closed, or -1.
fn pop(i: int) -> int {
  let lo = i;
  let hi = i;
  while lo > 0 && chain[lo - 1] == chain[i] { lo -= 1; }
  while hi < len(chain) - 1 && chain[hi + 1] == chain[i] { hi += 1; }
  if hi - lo < 2 { return -1; }
  repeat hi - lo + 1 { remove(chain, lo); }
  score += 10 * (hi - lo + 1);
  return lo;
}

fn shoot() {
  if speed == 0 { return; }
  let c = order[shots % 3];
  shots += 1;
  let i = aim - back;
  if i < 0 || i >= len(chain) { return; }
  insert(chain, i, c);
  let g = pop(i);
  while g > 0 && g < len(chain) && chain[g - 1] == chain[g] { g = pop(g); }
  if len(chain) == 0 {
    if level == 1 { setup(2); } else { stop("You win"); }
  } else if back + len(chain) > 15 {
    stop("Game over");
  }
}

every speed {
  steps += 1;
  if level == 2 || steps % 2 == 0 {
    back += 1;
    if back + len(chain) > 15 { stop("Game over"); }
  }
}

on key "left" { if speed > 0 { aim = max(0, aim - 1); } }
on key "right" { if speed > 0 { aim = min(15, aim + 1); } }
on key "space" { shoot(); }

fn scene() {
  let cells = [-1; 48];
  for i in 0..len(chain) {
    if back + i < 16 { cells[back + i] = chain[i]; }
  }
  if speed > 0 { cells[32 + aim] = order[shots % 3]; }
  pixels(cells, 0, 0, 16, 10);
  if result != "" { text(result, 80, 15, 9, 11); }
}

