// Zuma: left and right move the shooter, space shoots its ball up into the rolling row; 3 or more
// of a color touching pop. Clear the row before a ball rolls off the right end.
// icon: dot 5 6 3 dot 12 5 3 dot 19 6 3 line 12 19 12 11 dot 12 19 3
state balls = [0; 0];           // colors, left to right
state first = 0;                // the slot of the leftmost ball
state aim = 0;
state shots = 0;
state speed = 0;                // ms a roll; 0 while no game runs
state result = "";

fn over(s: string) {
  result = s;
  speed = 0;
}

// The run of one color through ball i pops if 3 or more: returns where the gap closed, or -1.
fn pop(i: int) -> int {
  let lo = i;
  let hi = i;
  while lo > 0 && balls[lo - 1] == balls[i] { lo -= 1; }
  while hi < len(balls) - 1 && balls[hi + 1] == balls[i] { hi += 1; }
  if hi - lo < 2 { return -1; }
  repeat hi - lo + 1 { remove(balls, lo); }
  return lo;
}

every speed {
  first += 1;
  if first + len(balls) > 12 { over("Game over"); }
}

on key "left" { aim = max(0, aim - 1); }
on key "right" { aim = min(11, aim + 1); }
on key "space" {
  let i = aim - first;
  if speed > 0 && i >= 0 && i < len(balls) {
    insert(balls, i, shots % 2 == 0 ? 4 : 1);
    shots += 1;
    let g = pop(i);
    while g > 0 && g < len(balls) && balls[g - 1] == balls[g] { g = pop(g); }
    if len(balls) == 0 {
      over("You win");
    } else if first + len(balls) > 12 {
      over("Game over");
    }
  } else if speed > 0 {
    shots += 1;
  }
}

fn scene() {
  let cells = [-1; 24];
  for i in 0..len(balls) { cells[first + i] = balls[i]; }
  cells[12 + aim] = shots % 2 == 0 ? 4 : 1;
  pixels(cells, 0, 0, 12, 10);
  if result != "" { text(result, 60, 10, 10, 11); }
}

