// Hanabi for two: on your turn tell your partner a color or a number (a clue), or play or discard
// one of your own unseen cards. Build the red and blue fireworks from 1 to 3 together.
// icon: line 12 22 12 12 line 12 12 5 5 line 12 12 19 5 line 12 12 12 3 dot 5 5 2 dot 19 5 2
state deck = ["R1", "B1", "R2", "B3", "R3", "B2", "B2", "R1", "B1", "R3", "B3", "R2"];
state next = 0;                 // the deck's top
state hands = ["", "", "", "", "", ""];  // Player 1's slots, then Player 2's; "" is empty
state toldc = [false; 6];       // whether a card's color has been told
state toldn = [false; 6];       // whether its number has
state turn = 0;                 // 0: Player 1, 1: Player 2
state red = 0;
state blue = 0;
state clues = 8;
state fuses = 3;
state playing = false;
state result = "";

fn draw(k: int) {
  hands[k] = "";
  if next < len(deck) {
    hands[k] = deck[next];
    next += 1;
  }
  toldc[k] = false;
  toldn[k] = false;
}

fn deal() {
  next = 0;
  for k in 0..6 { draw(k); }
  turn = 0;
  red = 0;
  blue = 0;
  clues = 8;
  fuses = 3;
  result = "";
  playing = true;
}

fn cards(p: int) -> string {
  let s = "";
  for k in p * 3..p * 3 + 3 {
    s = s + " " + (hands[k] == "" ? "--" : hands[k]);
  }
  return s;
}

fn known(p: int) -> string {
  let s = "";
  for k in p * 3..p * 3 + 3 {
    if hands[k] == "" {
      s = s + " --";
    } else {
      s = s + " " + (toldc[k] ? hands[k][0] : "?") + (toldn[k] ? hands[k][1] : "?");
    }
  }
  return s;
}

// A clue to the partner: v is a color's letter or a number.
fn tell(v: string) {
  let q = 1 - turn;
  let hit = false;
  for k in q * 3..q * 3 + 3 {
    if hands[k] != "" && (hands[k][0] == v || hands[k][1] == v) { hit = true; }
  }
  if clues == 0 || !hit { return; }
  for k in q * 3..q * 3 + 3 {
    if hands[k] != "" && hands[k][0] == v { toldc[k] = true; }
    if hands[k] != "" && hands[k][1] == v { toldn[k] = true; }
  }
  clues -= 1;
  turn = q;
}

fn play(s: int) {
  let k = turn * 3 + s;
  if hands[k] == "" { return; }
  let n = parse(hands[k][1], 0);
  if hands[k][0] == "R" && n == red + 1 {
    red += 1;
  } else if hands[k][0] == "B" && n == blue + 1 {
    blue += 1;
  } else {
    fuses -= 1;
  }
  draw(k);
  turn = 1 - turn;
  if red == 3 && blue == 3 {
    result = "You win";
    playing = false;
  } else if fuses == 0 {
    result = "Game over";
    playing = false;
  }
}

fn discard(s: int) {
  let k = turn * 3 + s;
  if hands[k] == "" { return; }
  clues = min(8, clues + 1);
  draw(k);
  turn = 1 - turn;
}

label "Hanabi";
if playing {
  label "Player " + (turn + 1) + " to play";
  label "Partner:" + cards(1 - turn);
  label "You:" + known(turn);
  row {
