    button "Discard 3" { discard(2); }
  }
} else {
  if result != "" { label result; }
  button "Start" { deal(); }
}
label "Score: " + (red + blue) + "   Clues: " + clues + "   Fuses: " + fuses;

// Hanabi for one: hold one unseen card; spend a hint to see its color or its number, then play
// or discard it. Build red and blue from 1 to 3; a wrong play costs a life.
// icon: line 12 22 12 12 line 12 12 5 5 line 12 12 19 5 line 12 12 12 3 dot 5 5 2 dot 19 5 2
state deck = ["R1", "B2", "B1", "R3", "R2", "B2", "B3", "R3"];
state top = 0;                  // the card held
state color = false;            // whether a hint has shown its color
state number = false;           // or its number
state red = 0;
state blue = 0;
state hints = 8;
state lives = 3;
state result = "";

fn card() -> string {
  let c = deck[top];
  return (color ? (c[0] == "R" ? "red" : "blue") : "?") + " " + (number ? c[1] : "?");
}

fn hint(c: bool) {
  if hints == 0 { return; }
  hints -= 1;
  if c { color = true; } else { number = true; }
}

fn next() {
  top += 1;
  color = false;
  number = false;
  if red == 3 && blue == 3 {
    result = "You win";
  } else if lives == 0 {
    result = "Game over";
  } else if top == len(deck) {
    result = "Out of cards";
  }
}

fn play() {
  let c = deck[top];
  let n = parse(c[1], 0);
  if c[0] == "R" && n == red + 1 {
    red += 1;
  } else if c[0] == "B" && n == blue + 1 {
    blue += 1;
  } else {
    lives -= 1;
  }
  next();
}

