// Patchwork for two: the one with less time moves. Tap your quilt to buy the front patch and sew
// it there (its top-left on that square), or Pass for buttons. Each empty square costs 2 at the end.
// icon: loop 3 3 21 3 21 21 3 21 fill 3 3 12 3 12 12 3 12 fill 12 12 21 12 21 21 12 21
state shapes = ["##/##", "###", "##/#.", "####", "#/#", "##/.#"];
state prices = [3, 2, 1, 4, 1, 2];
state times = [2, 3, 2, 3, 1, 2];
state front = 0;                // the front patch of the line
state quilt = [0; 32];          // Red's 16 squares, then Blue's: 0 empty, else its color
state buttons = [5, 5];
state clock = [0, 0];
state playing = false;
state result = "";

fn mover() -> int { return clock[1] < clock[0] ? 1 : 0; }

fn name(who: int) -> string { return who == 0 ? "Red" : "Blue"; }

// Whether the front patch, its top-left at x, y, lies on the quilt over empty squares; with
// sew, it is put there.
fn place(who: int, x: int, y: int, sew: bool) -> bool {
  let s = shapes[front];
  let r = 0;
  let c = 0;
  for i in 0..len(s) {
    if s[i] == "/" {
      r += 1;
      c = 0;
      continue;
    }
    if s[i] == "#" {
      if x + c > 3 || y + r > 3 { return false; }
      let k = who * 16 + (y + r) * 4 + x + c;
      if quilt[k] != 0 { return false; }
      if sew { quilt[k] = who == 0 ? 1 : 4; }
    }
    c += 1;
  }
  return true;
}

fn score(who: int) -> int {
  let n = buttons[who];
  for i in 0..16 {
    if quilt[who * 16 + i] == 0 { n -= 2; }
  }
  return n;
}

fn ended() {
  if clock[0] < 10 || clock[1] < 10 { return; }
  playing = false;
  if score(0) > score(1) {
    result = "Red wins";
  } else if score(1) > score(0) {
    result = "Blue wins";
  } else {
    result = "Tie";
  }
}

fn buy(col: int, y: int) {
  let who = mover();
  let x = who == 0 ? col : col - 5;
  if !playing || front >= len(shapes) || x < 0 || x > 3 { return; }
  if buttons[who] < prices[front] || !place(who, x, y, false) { return; }
  place(who, x, y, true);
  buttons[who] -= prices[front];
  clock[who] = min(10, clock[who] + times[front]);
  front += 1;
  ended();
}

fn pass() {
  let who = mover();
  let t = min(10, clock[1 - who] + 1);
  buttons[who] += t - clock[who];
  clock[who] = t;
  ended();
}

fn scene() {
  let cells = [-1; 36];
  for i in 0..32 {
    let col = (i / 16) * 5 + i % 4;
    cells[(i % 16) / 4 * 9 + col] = quilt[i] == 0 ? 8 : quilt[i];
  }
  pixels(cells, 0, 0, 9, 10);
}

label "Patchwork";
if playing {
  label name(mover()) + " to move";
  if front < len(shapes) {
    label "Front patch: " + shapes[front] + " for " + prices[front] + " buttons and " + times[front] + " time";
  }
}
label "Red buttons: " + buttons[0] + "   Red time: " + clock[0];
label "Blue buttons: " + buttons[1] + "   Blue time: " + clock[1];
