state quilt = [0; 16];          // 0 empty, else a patch's color

// Whether the front patch, its top-left at x, y, lies on the quilt over empty squares; with
// sew, it is put there.
fn place(x: int, y: int, sew: bool) -> bool {
  let s = shapes[front];
  let r = 0;
  let c = 0;
  for i in 0..len(s) {
    if s[i] == "/" {
      r += 1;
      c = 0;
      continue;
    }
    if s[i] == "#" {
      if x + c > 3 || y + r > 3 || quilt[(y + r) * 4 + x + c] != 0 { return false; }
      if sew { quilt[(y + r) * 4 + x + c] = colors[front]; }
    }
    c += 1;
  }
  return true;
}

fn score() -> int {
  let n = 0;
  for i in 0..16 { n += quilt[i] == 0 ? -2 : 1; }
  return n;
}

