// Hue Hop: gates of color fall toward your ball; make it the gate's color (keys 1 2 3 or the
// buttons) to hop through. Six hops for level 2, twelve to win; three wrong ones end it.
// icon: line 3 5 21 5 line 3 11 21 11 dot 12 18 4
state gates = [0; 0];           // the gates' rows, the lowest first
state hues = [0; 0];            // their colors
state order = [1, 4, 2, 4, 1, 2];
state made = 0;                 // gates made this game
state ball = 1;
state level = 1;
state score = 0;
state lives = 3;
state steps = 0;
state moves = 0;
state speed = 0;                // ms a step; 0 while no game runs
state result = "";

fn spawn() {
  push(gates, 0);
  push(hues, order[made % 6]);
  made += 1;
}

fn stop(s: string) {
  result = s;
  speed = 0;
}

fn move() {
  moves += 1;
  for i in 0..len(gates) { gates[i] += 1; }
  if len(gates) > 0 && gates[0] == 9 {
    if hues[0] == ball {
      score += 1;
      if score == 6 { level = 2; }
