    remove(gates, 0);
    remove(hues, 0);
    if score == 12 {
      stop("You win");
      return;
    }
    if lives == 0 {
      stop("Game over");
      return;
    }
  }
  if moves % 4 == 0 { spawn(); }
}

every speed {
