// Coup against the computer: take Income, Tax (claiming the Duke), Steal (claiming the Captain) or
// Coup; Allow or Challenge the computer's claims. Lose both cards and you lose.
// icon: line 4 18 4 7 8 12 12 5 16 12 20 7 20 18 line 4 18 20 18
state coins = [2, 2];           // mine, the computer's
state up = [0, 0];              // cards turned over: mine, the computer's
state claim = "";               // the computer's claim waiting for my answer
state did = "";
state playing = false;
state result = "";

// Whether a player holds the card face down: I hold the Duke, then the Assassin; the computer
// the Captain, then the Contessa.
fn holds(who: int, card: string) -> bool {
  if who == 0 { return (card == "Duke" && up[0] < 1) || (card == "Assassin" && up[0] < 2); }
  return (card == "Captain" && up[1] < 1) || (card == "Contessa" && up[1] < 2);
}

fn shown(card: string) -> bool {
  return (card == "Duke" && up[0] >= 1) || (card == "Captain" && up[1] >= 1);
}

fn lose(who: int) {
  up[who] += 1;
  if up[who] == 2 {
    playing = false;
    result = who == 0 ? "You lose" : "You win";
  }
}

// My claim of a card: whether the action happens.
fn mine(card: string) -> bool {
  if !holds(1, card) && !shown(card) { return true; }
  if holds(0, card) {
    lose(1);
    return true;
  }
  lose(0);
  return false;
}

fn steal(from: int, n: int) {
  let k = min(n, coins[from]);
  coins[from] -= k;
  coins[1 - from] += k;
}

fn computer() {
  if !playing { return; }
  if coins[1] >= 7 {
    coins[1] -= 7;
    did = "The computer coups you";
    lose(0);
  } else if coins[1] >= 3 {
    claim = "Captain";
    did = "The computer claims the Captain to steal 2";
  } else {
    claim = "Duke";
    did = "The computer claims the Duke to take 3";
  }
}

fn answer(challenge: bool) {
  let c = claim;
  claim = "";
  let happens = true;
  if challenge {
    if holds(1, c) {
      lose(0);
    } else {
      lose(1);
      happens = false;
    }
  }
  if happens && playing {
    if c == "Duke" { coins[1] += 3; } else { steal(0, 2); }
  }
}

fn hand(a: string, b: string, n: int) -> string {
  return (n >= 1 ? a + " (turned over)" : a) + ", " + (n >= 2 ? b + " (turned over)" : b);
}

label "Coup";
label "My coins: " + coins[0] + "   My cards: " + (2 - up[0]);
label "Computer coins: " + coins[1] + "   Computer cards: " + (2 - up[1]);
label "My hand: " + hand("Duke", "Assassin", up[0]);
if did != "" { label did; }
if playing && claim != "" {
  row {
    button "Allow" { answer(false); }
    button "Challenge" { answer(true); }
  }
} else if playing {
  row {
    button "Income" {
      coins[0] += 1;
      computer();
    }
    button "Tax" {
      if mine("Duke") { coins[0] += 3; }
      computer();
    }
    button "Steal" {
      if mine("Captain") { steal(1, 2); }
      computer();
    }
    button "Coup" {
      if coins[0] >= 7 {
        coins[0] -= 7;
        lose(1);
        computer();
      }
    }
  }
} else {
  if result != "" { label result; }
  button "Start" {
    coins = [2, 2];
    up = [0, 0];
    claim = "";
    did = "";
    result = "";
    playing = true;
  }
}

// Coup against the computer: take Income, Tax or Coup. The computer taxes (bluffing the Duke) and
// coups at 7 coins; Challenge its tax to take a card from it. Lose both cards and you lose.
// icon: line 4 18 4 7 8 12 12 5 16 12 20 7 20 18 line 4 18 20 18
state coins = [2, 2];           // mine, the computer's
state cards = [2, 2];
state waiting = false;          // its tax waits for a challenge
