// Glider: the arrows change the paper glider's drift; vents on the floor lift it, the floor and
// lamps crash it. Fly out of the third room to win.
// icon: fill 3 10 21 5 11 14 line 11 14 9 20
state vents = [5, 11, -1, 3, 8, 13, 4, 9, 14];   // three a room; -1 none
state room = 1;
state gx = 0;                   // the glider's column
state gy = 2;                   // and row
state drift = 0;
state lives = 3;
state speed = 0;                // ms a step; 0 while no game runs
state result = "";

fn vent(c: int) -> bool {
  for i in 0..3 {
    if vents[(room - 1) * 3 + i] == c { return true; }
  }
  return false;
}

fn lamp(c: int, r: int) -> bool {
  if room == 2 { return c == 8 && r <= 3; }
  if room == 3 { return (c == 6 && r >= 5 && r <= 8) || (c == 11 && r <= 4); }
  return false;
}

fn stop(s: string) {
  result = s;
  speed = 0;
}

every speed {
  gx = max(0, gx + drift);
  if gx > 15 {
    if room == 3 {
      gx = 15;
      stop("You win");
      return;
    }
    room += 1;
    gx = 0;
  }
  if vent(gx) { gy = max(0, gy - 1); } else { gy += 1; }
  if gy >= 9 || lamp(gx, gy) {
    lives -= 1;
    gx = 0;
    gy = 2;
    drift = 0;
    if lives == 0 { stop("Game over"); }
  }
}

on key "right" { if speed > 0 { drift = min(1, drift + 1); } }
on key "left" { if speed > 0 { drift = max(-1, drift - 1); } }

