// Column c's line from row 1 down moves a row; what leaves row 4 is won.
fn shove(c: int) {
  let n = 1;
  while n < 4 && shelf[n * 5 + c] != 0 { n += 1; }
  if n == 4 { hand += shelf[15 + c] == 5 ? 5 : 1; }
  let r = min(n, 3);
  while r > 0 {
    shelf[r * 5 + c] = shelf[(r - 1) * 5 + c];
    r -= 1;
  }
  shelf[c] = 0;
}

