      bx = -1;
      if flat() { stop("You win"); }
    } else if by > 7 {
      bx = -1;
    }
  }
  if speed > 0 && steps % 5 == 0 {
    sx += 1;
    if sx > 9 {
      sx = 0;
      sy += 1;
    }
    if sy >= 8 - towers[sx] { stop("Crash! Game over"); }
  }
}

