  return n;
}

fn over() -> bool { return won(0) == 2 || won(1) == 2; }

fn put(k: int) {
  let s = turn * 3 + k;
  if over() || counts[s] == 3 { return; }
  let c = piles[turn * 9 + drawn[turn]];
  drawn[turn] += 1;
  cards[s] = cards[s] + " " + c;
  sums[s] += c;
  counts[s] += 1;
  if counts[s] == 3 && first[k] < 0 { first[k] = turn; }
  if counts[k] == 3 && counts[3 + k] == 3 {
    if sums[k] > sums[3 + k] {
      owner[k] = 0;
    } else if sums[k] < sums[3 + k] {
      owner[k] = 1;
    } else {
      owner[k] = first[k];
    }
  }
  turn = 1 - turn;
}

fn stone(k: int) -> string {
  let who = owner[k] < 0 ? "" : " - player " + (owner[k] + 1) + "'s";
  return names[k] + ": P1" + cards[k] + " (" + sums[k] + ") | P2" + cards[3 + k] + " (" + sums[3 + k] + ")" + who;
}

label "Schotten-Totten";
for k in 0..3 { label stone(k); }
if over() {
  label "Player " + (won(0) == 2 ? 1 : 2) + " wins!";
} else {
  label "Player " + (turn + 1) + ": place a " + piles[turn * 9 + drawn[turn]];
  row {
    for k in 0..3 { button names[k] { put(k); } }
  }
}

// Hive for two on a 6 x 6 board: choose a bug from your hand and tap where it goes, or tap your
// bug and then where it moves. Surround the other Queen on every side to win.
// icon: loop 12 3 19 7 19 15 12 19 5 15 5 7 dot 12 11 3
state who = [0; 36];          // 0 empty, 1 Blue, 2 Red
state kind = [0; 36];         // 1 Queen, 2 Ant, 3 Grasshopper
state hands = [1, 2, 2, 1, 2, 2];   // player p's bugs of kind k at (p - 1) * 3 + k - 1
state turn = 1;
state chosen = -1;            // a square of the board chosen to move, or -1
state pick = 0;               // a kind chosen from the hand, or 0
state over = "";
state names = ["Queen", "Ant", "Grasshopper"];
state letters = ["", "Q", "A", "G"];

// Square i's neighbor in way d (right, left, down, up), or -1 off the board.
fn step(i: int, d: int) -> int {
  let c = i % 6 + (d == 0 ? 1 : 0) - (d == 1 ? 1 : 0);
  let r = i / 6 + (d == 2 ? 1 : 0) - (d == 3 ? 1 : 0);
  if c < 0 || c > 5 || r < 0 || r > 5 { return -1; }
  return r * 6 + c;
}

// Whether square i touches a piece of player p (0: of anyone) other than the one on square skip.
fn near(i: int, p: int, skip: int) -> bool {
  for d in 0..4 {
    let n = step(i, d);
    if n >= 0 && n != skip && who[n] > 0 && (p == 0 || who[n] == p) { return true; }
  }
  return false;
}

fn pieces() -> int {
  let n = 0;
  for i in 0..36 {
    if who[i] > 0 { n += 1; }
  }
  return n;
}

fn queenout(p: int) -> bool {
  for i in 0..36 {
    if who[i] == p && kind[i] == 1 { return true; }
  }
  return false;
}

// Whether every piece is joined to every other through neighbors.
fn whole() -> bool {
  let seen = [false; 36];
  let todo = [0; 0];
  for i in 0..36 {
    if who[i] > 0 && len(todo) == 0 {
      push(todo, i);
      seen[i] = true;
    }
  }
  let found = len(todo);
  while len(todo) > 0 {
    let i = todo[len(todo) - 1];
    remove(todo, len(todo) - 1);
    for d in 0..4 {
      let n = step(i, d);
      if n >= 0 && who[n] > 0 && !seen[n] {
        seen[n] = true;
        found += 1;
        push(todo, n);
      }
    }
  }
  return found == pieces();
}

fn surrounded(p: int) -> bool {
  for i in 0..36 {
    if who[i] == p && kind[i] == 1 {
      for d in 0..4 {
        let n = step(i, d);
        if n >= 0 && who[n] == 0 { return false; }
      }
      return true;
    }
  }
  return false;
}

fn after() {
  chosen = -1;
  pick = 0;
  let b = surrounded(1);
  let r = surrounded(2);
  if b && r { over = "Draw"; } else if r { over = "Blue wins"; } else if b { over = "Red wins"; }
  turn = 3 - turn;
}

fn place(i: int) {
  let h = (turn - 1) * 3 + pick - 1;
  let n = pieces();
  if hands[h] == 0 || (n == 1 && !near(i, 0, -1)) { return; }
  if n >= 2 && (!near(i, turn, -1) || near(i, 3 - turn, -1)) { return; }
  who[i] = turn;
  kind[i] = pick;
  hands[h] -= 1;
  after();
}

fn legal(a: int, t: int) -> bool {
  if kind[a] == 1 { return abs(a % 6 - t % 6) + abs(a / 6 - t / 6) == 1; }
  if kind[a] == 2 { return near(t, 0, a); }
  let way = 0;
  if a % 6 == t % 6 { way = t > a ? 6 : -6; }
  if a / 6 == t / 6 { way = t > a ? 1 : -1; }
  if way == 0 || a + way == t { return false; }
  let i = a + way;
  while i != t {
    if who[i] == 0 { return false; }
    i += way;
  }
  return true;
}

fn moveto(t: int) {
  let a = chosen;
  if !queenout(turn) || !legal(a, t) { return; }
  who[t] = who[a];
  kind[t] = kind[a];
  who[a] = 0;
  kind[a] = 0;
  if !whole() {
    who[a] = who[t];
    kind[a] = kind[t];
    who[t] = 0;
    kind[t] = 0;
    return;
  }
  after();
}

fn tap(i: int) {
  if over != "" { return; }
  if who[i] == turn {
    chosen = i;
    pick = 0;
  } else if who[i] == 0 && pick > 0 {
    place(i);
  } else if who[i] == 0 && chosen >= 0 {
    moveto(i);
  }
}

fn scene() {
  let cells = [-1; 36];
  for i in 0..36 {
    if who[i] == 1 { cells[i] = 4; }
    if who[i] == 2 { cells[i] = 1; }
  }
  pixels(cells, 0, 0, 6, 20);
  for i in 0..36 {
    if who[i] > 0 { text(letters[kind[i]], i % 6 * 20 + 10, i / 6 * 20 + 10, 12, 0); }
  }
  if chosen >= 0 { ring(chosen % 6 * 20 + 10, chosen / 6 * 20 + 10, 9, 2, 3); }
}

label "Hive";
label over != "" ? over : (turn == 1 ? "Blue to move" : "Red to move");
canvas 120, 120, scene() { tap(y / 20 * 6 + x / 20); }
row {
  for k in 1..4 {
    if over == "" && hands[(turn - 1) * 3 + k - 1] > 0 {
      button names[k - 1] {
        pick = k;
        chosen = -1;
      }
    }
  }
}
button "New game" {
  who = [0; 36];
  kind = [0; 36];
  hands = [1, 2, 2, 1, 2, 2];
  turn = 1;
  chosen = -1;
  pick = 0;
  over = "";
}

// Hive on a 5 x 5 grid: tap an empty square to place your next piece (queen first, then 3 ants),
// or tap your piece and then where it moves. Surround the other queen on all 4 sides to win.
// icon: loop 12 3 19 7 19 15 12 19 5 15 5 7 dot 12 11 3
state who = [0; 25];          // 0 empty, 1 player 1, 2 player 2
state queen = [false; 25];
state placed = [0, 0];
state turn = 1;
state chosen = -1;
state winner = 0;

fn step(i: int, d: int) -> int {
  let c = i % 5 + (d == 0 ? 1 : 0) - (d == 1 ? 1 : 0);
  let r = i / 5 + (d == 2 ? 1 : 0) - (d == 3 ? 1 : 0);
  if c < 0 || c > 4 || r < 0 || r > 4 { return -1; }
  return r * 5 + c;
}

// Whether square i touches a piece of player p (0: anyone's) other than the one on square skip.
fn near(i: int, p: int, skip: int) -> bool {
  for d in 0..4 {
    let n = step(i, d);
    if n >= 0 && n != skip && who[n] > 0 && (p == 0 || who[n] == p) { return true; }
  }
  return false;
}

fn whole() -> bool {
  let seen = [false; 25];
  let todo = [0; 0];
  let all = 0;
  for i in 0..25 {
    if who[i] > 0 {
      all += 1;
      if len(todo) == 0 {
        push(todo, i);
        seen[i] = true;
      }
    }
  }
  let found = len(todo);
  while len(todo) > 0 {
    let i = todo[len(todo) - 1];
    remove(todo, len(todo) - 1);
    for d in 0..4 {
      let n = step(i, d);
      if n >= 0 && who[n] > 0 && !seen[n] {
        seen[n] = true;
        found += 1;
        push(todo, n);
      }
    }
  }
  return found == all;
}

fn trapped(p: int) -> bool {
  for i in 0..25 {
    if who[i] == p && queen[i] {
      for d in 0..4 {
        let n = step(i, d);
        if n < 0 || who[n] == 0 { return false; }
      }
      return true;
    }
  }
  return false;
}

fn done() {
  chosen = -1;
  if trapped(2) { winner = 1; } else if trapped(1) { winner = 2; }
  turn = 3 - turn;
}

fn place(i: int) {
  let n = placed[0] + placed[1];
  if placed[turn - 1] == 4 || (n == 1 && !near(i, 0, -1)) || (n > 1 && !near(i, turn, -1)) { return; }
  who[i] = turn;
  queen[i] = placed[turn - 1] == 0;
  placed[turn - 1] += 1;
  done();
}

fn moveto(t: int) {
  let a = chosen;
  if queen[a] && abs(a % 5 - t % 5) + abs(a / 5 - t / 5) != 1 { return; }
  if !queen[a] && !near(t, 0, a) { return; }
  who[t] = who[a];
  queen[t] = queen[a];
  who[a] = 0;
  queen[a] = false;
  if whole() {
    done();
  } else {
    who[a] = who[t];
    queen[a] = queen[t];
    who[t] = 0;
    queen[t] = false;
  }
}

fn tap(i: int) {
  if winner > 0 { return; }
  if who[i] == turn {
    chosen = i;
  } else if who[i] == 0 && chosen >= 0 {
    moveto(i);
  } else if who[i] == 0 {
    place(i);
  }
}

fn scene() {
  let cells = [-1; 25];
  for i in 0..25 {
    if who[i] > 0 { cells[i] = who[i] == 1 ? 4 : 1; }
  }
  pixels(cells, 0, 0, 5, 20);
  for i in 0..25 {
    if who[i] > 0 { text(queen[i] ? "Q" : "A", i % 5 * 20 + 10, i / 5 * 20 + 10, 12, 0); }
  }
  if chosen >= 0 { ring(chosen % 5 * 20 + 10, chosen / 5 * 20 + 10, 9, 2, 3); }
}

label "Hive";
label winner > 0 ? "Player " + winner + " wins!" : "Player " + turn + "'s turn";
canvas 100, 100, scene() { tap(y / 20 * 5 + x / 20); }

// Rise Up: the balloon rises while rocks fall; move the shield with the arrows to hold them up or
// push them aside. A rock that reaches the balloon pops it; reach height 40 to win.
// icon: ring 12 9 6 line 12 15 12 21 dot 6 4 2 dot 18 4 2
state rocks = [0; 70];          // 1 where a rock is, 7 columns a row
state sx = 3;                   // the shield
state sy = 7;
state height = 0;
state level = 1;
state wave = 0;
state speed = 0;                // ms a step; 0 while no game runs
state result = "";
state waves = [3, 1, 5, 3, 2, 4, 3, 6, 0, 3];

fn at(c: int, r: int) -> int { return r * 7 + c; }

// Each rock falls a row, the lowest first, unless the shield or a resting rock is below it.
fn fall() {
  for k in 0..10 {
    let r = 9 - k;
    for c in 0..7 {
      if rocks[at(c, r)] == 1 {
        if r == 9 {
          rocks[at(c, r)] = 0;
        } else if c == 3 && r == 8 {
          result = "Game over";
          speed = 0;
        } else if !(c == sx && r + 1 == sy) && rocks[at(c, r + 1)] == 0 {
          rocks[at(c, r)] = 0;
          rocks[at(c, r + 1)] = 1;
        }
      }
    }
  }
}

every speed {
  height += 1;
  fall();
  if speed == 0 { return; }
  if height == 40 {
    result = "You win";
    speed = 0;
    return;
  }
  if height % 4 == 0 {
    rocks[at(waves[wave % 10], 0)] = 1;
    wave += 1;
  }
  if height == 20 {
    level = 2;
    speed = 150;
  }
}

// The shield moves a square, pushing a rock in its way one further, or off the board.
fn shove(dx: int, dy: int) {
  let tx = sx + dx;
  let ty = sy + dy;
  if speed == 0 || tx < 0 || tx > 6 || ty < 0 || ty > 8 { return; }
  if rocks[at(tx, ty)] == 1 {
    let px = tx + dx;
    let py = ty + dy;
    if px >= 0 && px <= 6 && py >= 0 {
      if (px == 3 && py == 9) || rocks[at(px, py)] == 1 { return; }
      rocks[at(px, py)] = 1;
    }
    rocks[at(tx, ty)] = 0;
  }
  sx = tx;
  sy = ty;
}

on key "left" { shove(-1, 0); }
on key "right" { shove(1, 0); }
on key "up" { shove(0, -1); }
on key "down" { shove(0, 1); }

fn scene() {
  let cells = [-1; 70];
  for i in 0..70 {
    if rocks[i] == 1 { cells[i] = 3; }
  }
  cells[at(3, 9)] = 1;
  cells[at(sx, sy)] = 4;
  pixels(cells, 0, 0, 7, 12);
  if result != "" { text(result, 42, 50, 10, 11); }
}

label "Rise Up";
label "Height: " + height + "   Level: " + level;
canvas 84, 120, scene();
if speed == 0 {
  button "Start" {
    rocks = [0; 70];
    sx = 3;
    sy = 7;
    height = 0;
    level = 1;
    wave = 0;
    result = "";
    speed = 250;
  }
}

// Rise Up: rocks drop down the middle three columns; move the shield with left and right to break
// them (a point each). A rock that falls on the balloon pops it: game over.
// icon: ring 12 14 6 line 12 20 12 22 fill 8 3 16 3 16 6 8 6
state rx = [2];                 // each rock's column and row
state ry = [0];
state shield = 2;              // the shield's column, in row 6
state points = 0;
state ticks = 0;               // seconds since the start
state speed = 1000;            // 0 once the balloon pops

every speed {
  ticks += 1;
  let i = 0;
  while i < len(rx) {
    ry[i] += 1;
    if ry[i] == 6 && rx[i] == shield {
      points += 1;
      remove(rx, i);
      remove(ry, i);
    } else if ry[i] == 7 && rx[i] == 2 {
      speed = 0;
      return;
    } else if ry[i] == 8 {
      remove(rx, i);
      remove(ry, i);
    } else {
      i += 1;
    }
  }
  if ticks % 3 == 0 {
    push(rx, [2, 1, 3][ticks / 3 % 3]);
    push(ry, 0);
  }
}

on key "left" { if speed > 0 { shield = max(0, shield - 1); } }
on key "right" { if speed > 0 { shield = min(4, shield + 1); } }

fn scene() {
  let cells = [-1; 40];
  for i in 0..len(rx) { cells[ry[i] * 5 + rx[i]] = 8; }
  cells[30 + shield] = 4;
  cells[37] = speed > 0 ? 1 : 3;
  pixels(cells, 0, 0, 5, 12);
  if speed == 0 { text("Game over", 30, 40, 10, 11); }
}

label "Rise Up";
label "Points: " + points;
canvas 60, 96, scene();

// Whodunit: three cases. Choose a suspect, a weapon and a room, then Accuse: it tells how many
// of the three are right. Solve each case within 6 accusations; fewer used scores more.
// icon: ring 10 10 6 line 14 14 20 20 dot 10 10 2
state suspects = ["Plum", "Mustard", "Scarlet", "Green"];
state weapons = ["Rope", "Knife", "Pipe", "Candlestick"];
state rooms = ["Library", "Kitchen", "Hall", "Study"];
state answers = [1, 1, 2, 2, 0, 3, 0, 3, 1];   // case c's suspect, weapon and room at c * 3
state pick = [-1, -1, -1];
state cases = 0;              // the case being solved, from 0; 3 once all are
state tries = 6;
state score = 0;
state right = -1;             // how many the last accusation had right; -1 before one
state lost = false;

fn choose(k: int, i: int) {
  if !lost && cases < 3 { pick[k] = i; }
}

fn accuse() {
  if lost || cases == 3 || pick[0] < 0 || pick[1] < 0 || pick[2] < 0 { return; }
  let n = 0;
  for k in 0..3 {
    if pick[k] == answers[cases * 3 + k] { n += 1; }
  }
  if n == 3 {
    score += tries;
    cases += 1;
    tries = 6;
    right = -1;
    pick = [-1, -1, -1];
  } else {
    right = n;
    tries -= 1;
    if tries == 0 { lost = true; }
  }
}

fn named(k: int, names: [string]) -> string { return pick[k] < 0 ? "?" : names[pick[k]]; }

fn status() -> string {
  if cases == 3 { return "You win"; }
  if lost { return "Game over"; }
  if right < 0 { return "Make an accusation"; }
  return "Right: " + right;
}

label "Whodunit";
label "Case: " + min(cases + 1, 3) + "   Tries: " + tries + "   Score: " + score;
label named(0, suspects) + " with the " + named(1, weapons) + " in the " + named(2, rooms);
label status();
row {
  for i in 0..4 { button suspects[i] { choose(0, i); } }
}
row {
  for i in 0..4 { button weapons[i] { choose(1, i); } }
}
row {
  for i in 0..4 { button rooms[i] { choose(2, i); } }
}
row {
  button "Accuse" { accuse(); }
  button "New game" {
    pick = [-1, -1, -1];
    cases = 0;
    tries = 6;
    score = 0;
    right = -1;
    lost = false;
  }
}

// Whodunit: three cases. Read the clues and tap the suspect you accuse; two accusations a case.
// Solve all three to win; miss twice in a case and the killer gets away.
// icon: ring 10 10 6 line 14 14 20 20 dot 10 10 2
state suspects = ["Butler", "Maid", "Chef", "Gardener"];
