state cases = 0;              // the case being solved; 3 once all are
state left = 2;               // accusations left in this case
state lost = false;
state note = "";

fn accuse(i: int) {
  if lost || cases == 3 { return; }
  if i == killers[cases] {
    cases += 1;
    left = 2;
    note = "Right: the " + suspects[i] + " did it.";
  } else {
    left -= 1;
    note = "Not the " + suspects[i] + ".";
    if left == 0 { lost = true; }
