// Nebula Wars: tap one of your blue planets, then another planet, to send half its ships there.
// Planets build a ship a second; the red computer strikes every 3 seconds. Take every planet.
// icon: ring 12 12 9 dot 12 12 4 dot 20 5 2
state owner = [1, 0, 0, 0, 2];   // 1 mine, 2 the computer's, 0 no one's
state ships = [10, 4, 6, 4, 10];
state chosen = -1;
state secs = 0;
state speed = 0;                 // 1000 while a game runs
state result = "";

fn total(p: int) -> int {
  let n = 0;
  for i in 0..5 {
    if owner[i] == p { n += ships[i]; }
  }
  return n;
}

fn has(p: int) -> bool {
  for i in 0..5 {
    if owner[i] == p { return true; }
  }
  return false;
}

// Half the ships of planet a go to planet b, for player p.
fn send(a: int, b: int, p: int) {
  let n = ships[a] / 2;
  if n == 0 { return; }
  ships[a] -= n;
  if owner[b] == p {
    ships[b] += n;
  } else if n > ships[b] {
    ships[b] = n - ships[b];
    owner[b] = p;
  } else {
    ships[b] -= n;
  }
  if !has(2) { result = "You win"; }
  if !has(1) { result = "You lose"; }
  if result != "" { speed = 0; }
}

// The computer: its biggest planet strikes the weakest planet not its own.
fn computer() {
  let a = -1;
  let b = -1;
  for i in 0..5 {
    if owner[i] == 2 && (a < 0 || ships[i] > ships[a]) { a = i; }
    if owner[i] != 2 && (b < 0 || ships[i] < ships[b]) { b = i; }
  }
  if a >= 0 && b >= 0 { send(a, b, 2); }
}

every speed {
  secs += 1;
  for i in 0..5 {
    if owner[i] > 0 { ships[i] += 1; }
  }
  if secs % 3 == 0 { computer(); }
}

fn tap(i: int) {
  if speed == 0 { return; }
  if owner[i] == 1 && chosen < 0 {
    chosen = i;
  } else if chosen >= 0 && i != chosen {
    send(chosen, i, 1);
    chosen = -1;
  }
}

fn scene() {
  let cells = [8, 8, 8, 8, 8];
  for i in 0..5 {
    if owner[i] == 1 { cells[i] = 4; }
    if owner[i] == 2 { cells[i] = 1; }
  }
  pixels(cells, 0, 0, 5, 20);
  for i in 0..5 { text(ships[i], i * 20 + 10, 10, 10, 9); }
  if chosen >= 0 { ring(chosen * 20 + 10, 10, 9, 1, 3); }
  if result != "" { text(result, 50, 30, 10, 11); }
}

label "Nebula Wars";
label "You: " + total(1) + "   Computer: " + total(2);
canvas 100, 40, scene() { if y < 20 { tap(x / 20); } }
if speed == 0 {
  button "Start" {
    owner = [1, 0, 0, 0, 2];
    ships = [10, 4, 6, 4, 10];
    chosen = -1;
    secs = 0;
    result = "";
    speed = 1000;
  }
}

// Nebula Wars: left and right move your ship between the 5 lanes, space fires up its lane.
// Clear each wave before it reaches the bottom row; every wave has a row more and moves faster.
// icon: fill 12 3 16 12 12 10 8 12 line 5 20 19 20 dot 12 16 2
state ex = [0, 1, 2, 3, 4];     // the enemies' lanes and rows
state ey = [0, 0, 0, 0, 0];
state lane = 2;
state score = 0;
state wave = 1;
state ms = 0;                   // ms since the last row down
state tick = 100;               // 0 once it is over

fn pace() -> int { return max(400, 2000 - (wave - 1) * 400); }

fn next() {
  wave += 1;
  ms = 0;
  for r in 0..wave {
