state maps = ["P.....c", "###.###", "c......", "###s###", ".......", ".#####.", "...e...",
              "P..#c..", ".#.###.", ".#k#...", ".###d##", "......c", "###s###", "...e...",
              "P......", "######.", "c......", ".######", "......c", "######s", "e......"];
state marks = [".", "#", "c", "s", "e", "k", "d"];
state colors = [-1, 8, 3, 5, 2, 6, 1];
state tiles = [0; 49];          // 0 floor, 1 wall, 2 chip, 3 socket, 4 exit, 5 key, 6 door
state px = 0;
state py = 0;
state level = 1;
state keys = 0;
state time = 30;
state speed = 0;                // 1000 while a game runs
state won = false;

fn load() {
  for r in 0..7 {
    let row = maps[(level - 1) * 7 + r];
    for c in 0..7 {
      tiles[r * 7 + c] = 0;
      for k in 1..7 {
        if row[c] == marks[k] { tiles[r * 7 + c] = k; }
      }
      if row[c] == "P" {
        px = c;
        py = r;
      }
    }
  }
  keys = 0;
  time = 30;
