fn go(dx: int, dy: int) {
  let x = px + dx;
  let y = py + dy;
  if speed == 0 || x < 0 || x > 6 || y < 0 || y > 6 { return; }
  let t = tiles[y * 7 + x];
  if t == 1 || (t == 3 && chips() > 0) || (t == 6 && keys == 0) { return; }
  if t == 6 { keys -= 1; }
  if t == 5 { keys += 1; }
  px = x;
  py = y;
  if t != 4 {
    tiles[y * 7 + x] = 0;
  } else if level == 3 {
    won = true;
    speed = 0;
  } else {
    level += 1;
    load();
  }
}

