// Chip's Challenge, one room: the arrows move Chip. Take the chips in the three corners, then the
// exit in the middle opens. Keep clear of the bug walking the row above the bottom.
// icon: loop 4 4 20 4 20 20 4 20 fill 9 9 15 9 15 15 9 15
state cx = 0;
state cy = 0;
state chips = [false, true, true, true];   // the corners' chips: top left, top right, bottom left, bottom right
state bx = 0;                    // the bug, in row 3
state bdx = 1;
state speed = 1000;              // 0 once the game ends
state result = "";

fn corner(x: int, y: int) -> int {
  if (x == 0 || x == 4) && (y == 0 || y == 4) { return x / 4 + y / 4 * 2; }
  return -1;
}

fn left() -> int {
  let n = 0;
  for i in 0..4 {
    if chips[i] { n += 1; }
  }
  return n;
}

fn caught() {
  if cy == 3 && cx == bx {
    result = "Game over";
    speed = 0;
  }
}

fn go(dx: int, dy: int) {
  let x = cx + dx;
  let y = cy + dy;
  if speed == 0 || x < 0 || x > 4 || y < 0 || y > 4 { return; }
  if x == 2 && y == 2 && left() > 0 { return; }
  cx = x;
  cy = y;
  let k = corner(x, y);
  if k >= 0 { chips[k] = false; }
  if x == 2 && y == 2 {
    result = "You win";
    speed = 0;
  }
  caught();
}

every speed {
  if bx + bdx < 0 || bx + bdx > 4 { bdx = -bdx; }
  bx += bdx;
  caught();
}

on key "left" { go(-1, 0); }
on key "right" { go(1, 0); }
on key "up" { go(0, -1); }
on key "down" { go(0, 1); }

