// Trail: Start, then hike the map to the three flags in order (yellow is next) with the arrows
// or a tap beside the scout. Reach the last one in 20 seconds or less for a gold badge.
// icon: line 7 21 7 3 fill 7 3 19 7 7 11
state sc = 0;              // the scout's column and row
state sr = 5;
state fc = [0, 5, 3];      // the flags, in order
state fr = [1, 5, 0];
state next = 0;            // the next flag; 3 once all are reached
state secs = 0;
state steps = 0;
state speed = 0;
state medal = "";

fn tree(c: int, r: int) -> bool {
  return (c == 2 && r >= 1 && r <= 4) || (c == 4 && r != 0 && r != 3);
}

fn go(dc: int, dr: int) {
  let c = sc + dc;
  let r = sr + dr;
  if speed == 0 || c < 0 || c > 5 || r < 0 || r > 5 || tree(c, r) { return; }
  sc = c;
  sr = r;
  steps += 1;
  if c == fc[next] && r == fr[next] {
    next += 1;
    if next == 3 {
      speed = 0;
      medal = secs <= 20 ? "Gold" : "Silver";
    }
  }
}

// A tap on a square beside the scout steps there.
fn toward(c: int, r: int) {
  if abs(c - sc) + abs(r - sr) == 1 { go(c - sc, r - sr); }
}

fn start() {
  sc = 0;
  sr = 5;
  next = 0;
  secs = 0;
  steps = 0;
  medal = "";
  speed = 1000;
}

every speed { secs += 1; }

on key "left" { go(-1, 0); }
on key "right" { go(1, 0); }
on key "up" { go(0, -1); }
on key "down" { go(0, 1); }

fn scene() {
  let b = [-1; 36];
  for i in 0..36 {
    if tree(i % 6, i / 6) { b[i] = 2; }
  }
  for i in next..3 { b[fr[i] * 6 + fc[i]] = i == next ? 3 : 1; }
  b[sr * 6 + sc] = 4;
  pixels(b, 0, 0, 6, 20);
  if medal != "" { text(medal + " badge earned!", 60, 60, 10, 11); }
}

