// Class desk: tap a desk to mark its student absent or present. Call on picks the next one
// present, in turn; Right or Wrong ends the call, and Right gives a point. Top leads.
// icon: loop 3 10 21 10 21 15 3 15 line 6 15 6 21 line 18 15 18 21 dot 12 5 3
state names = ["Ava", "Ben", "Cal", "Dot", "Eve", "Fin", "Gus", "Hal", "Ivy", "Jo"];
state away = [false; 10];
state points = [0; 10];
state last = -1;            // the last student called
state called = -1;          // the one called now; -1 when nobody is

fn count(off: bool) -> int {
  let n = 0;
  for i in 0..10 {
    if away[i] == off { n += 1; }
  }
  return n;
}

fn desks() -> [int] {
  let b = [8; 12];
  for i in 0..10 { b[i] = away[i] ? 1 : 2; }
  if called >= 0 { b[called] = 3; }
  return b;
}

fn seats() -> [string] {
  let s = [""; 12];
  for i in 0..10 { s[i] = names[i]; }
  return s;
}

// The most points, the first in desk order on a tie.
fn top() -> int {
  let best = 0;
  for i in 1..10 {
    if points[i] > points[best] { best = i; }
  }
  return best;
}

fn call() {
  for k in 1..11 {
    let i = (last + k + 10) % 10;
    if !away[i] {
      called = i;
      last = i;
      return;
    }
  }
}

fn answer(good: bool) {
  if called < 0 { return; }
  if good { points[called] += 1; }
  called = -1;
}

