label "Present " + count(false) + "   Absent " + count(true);
grid 4, desks(), seats() {
  if cell < 10 {
    away[cell] = !away[cell];
    if cell == called { called = -1; }
  }
}
label "Called: " + (called >= 0 ? names[called] : "nobody");
