fn total() -> int {
  let s = 0;
  for i in 0..len(scores) { s += scores[i]; }
  return s;
}

fn high() -> int {
  let m = scores[0];
  for i in 0..len(scores) { m = max(m, scores[i]); }
  return m;
}

fn low() -> int {
  let m = scores[0];
  for i in 0..len(scores) { m = min(m, scores[i]); }
  return m;
}

