// Crate quest: push the yellow crates onto the green pads with the arrows to open the red exit,
// then walk out. Two levels; Reset starts a level again.
// icon: loop 3 3 21 3 21 21 3 21 fill 8 8 16 8 16 16 8 16
state level = 1;
state hero = 16;           // a square: row * 7 + column
state crates = [18];
state pads = [32];
state exit = 20;
state moves = 0;
state done = false;

fn load() {
  clear(crates);
  clear(pads);
  moves = 0;
  if level == 1 {
    hero = 16;
    push(crates, 18);
    push(pads, 32);
    exit = 20;
  } else {
    hero = 24;
    push(crates, 16);
    push(crates, 32);
    push(pads, 19);
    push(pads, 29);
    exit = 45;
  }
}

// The crate on square i, or -1.
fn crate(i: int) -> int {
  for k in 0..len(crates) {
    if crates[k] == i { return k; }
  }
  return -1;
}

fn pad(i: int) -> bool {
  for k in 0..len(pads) {
    if pads[k] == i { return true; }
  }
  return false;
}

fn open() -> bool {
  for k in 0..len(pads) {
    if crate(pads[k]) < 0 { return false; }
  }
  return true;
}

fn wall(i: int) -> bool {
  let c = i % 7;
  let r = i / 7;
  return i != exit && (c == 0 || c == 6 || r == 0 || r == 6);
}

// Whether (c, r) is off the board, a wall or the closed exit.
fn blocked(c: int, r: int) -> bool {
  if c < 0 || c > 6 || r < 0 || r > 6 { return true; }
  let i = r * 7 + c;
  return wall(i) || (i == exit && !open());
}

fn go(dc: int, dr: int) {
  if done { return; }
  let c = hero % 7 + dc;
  let r = hero / 7 + dr;
  if blocked(c, r) { return; }
  let k = crate(r * 7 + c);
  if k >= 0 {
    if blocked(c + dc, r + dr) || crate((r + dr) * 7 + c + dc) >= 0 { return; }
    crates[k] = (r + dr) * 7 + c + dc;
  }
  hero = r * 7 + c;
  moves += 1;
  if hero == exit {
    if level == 1 {
      level = 2;
      load();
    } else {
      done = true;
    }
  }
}

fn scene() {
  let b = [-1; 49];
  for i in 0..49 {
    if wall(i) { b[i] = 8; }
  }
  b[exit] = open() ? 6 : 1;
  for k in 0..len(pads) { b[pads[k]] = 2; }
  for k in 0..len(crates) { b[crates[k]] = pad(crates[k]) ? 5 : 3; }
  b[hero] = 4;
  pixels(b, 0, 0, 7, 16);
  if done { text("Quest complete!", 56, 56, 10, 11); }
}

on key "left" { go(-1, 0); }
