// Lights out quest: tap a light to flip it and its neighbours; turn them all off. Level 1 is
// 3 x 3, level 2 is 4 x 4 and level 3 is 5 x 5, each starting all on.
// icon: fill 4 4 11 4 11 11 4 11 loop 13 4 20 4 20 11 13 11 loop 4 13 11 13 11 20 4 20 fill 13 13 20 13 20 20 13 20
state size = 3;
state lights = [3, 3, 3, 3, 3, 3, 3, 3, 3];   // 3 on, 8 off
state moves = 0;
state won = false;

fn flip(c: int, r: int) {
  if c >= 0 && c < size && r >= 0 && r < size {
    let i = r * size + c;
    lights[i] = lights[i] == 3 ? 8 : 3;
  }
}

fn dark() -> bool {
  for i in 0..len(lights) {
    if lights[i] == 3 { return false; }
  }
  return true;
}

fn tap(c: int, r: int) {
  if won { return; }
  flip(c, r);
  flip(c - 1, r);
  flip(c + 1, r);
  flip(c, r - 1);
  flip(c, r + 1);
  moves += 1;
  if dark() {
    if size == 5 {
      won = true;
    } else {
      size += 1;
      lights = [3; size * size];
    }
  }
}

label "Lights out quest";
label "Level " + (size - 2) + " of 3   Moves " + moves;
grid size, lights { tap(cell % size, cell / size); }
if won { label "You won! All three levels are dark."; }

// Dungeon rhythm: Start, then move once between beats with the arrows (a second move is a miss).
// Strike the skeleton, take the gold (worth more on a combo) and reach the green stairs.
// icon: fill 4 20 4 12 12 4 20 12 20 20 dot 9 13 2 dot 15 13 2
state hc = 0;              // the hero's column and row
state hr = 2;
state sr = 0;              // the skeleton's row in column 3; -1 once destroyed
state dir = 1;             // its way: 1 down, -1 up
state gold = true;
state moved = false;       // a move made since the last beat
state combo = 0;
state score = 0;
state hearts = 3;
state speed = 0;
state result = "";

fn wall(c: int, r: int) -> bool {
  return (c == 2 && r != 2) || (c == 4 && r >= 1 && r <= 3);
}

fn go(dc: int, dr: int) {
  if speed == 0 { return; }
  if moved {
    combo = 0;
    return;
  }
  let c = hc + dc;
  let r = hr + dr;
  if c < 0 || c > 6 || r < 0 || r > 4 || wall(c, r) { return; }
  moved = true;
  combo += 1;
  if c == 3 && r == sr {
    sr = -1;
    score += 5;
    return;
  }
  hc = c;
  hr = r;
  if gold && c == 5 && r == 4 {
    gold = false;
    score += 10 + combo;
  }
  if c == 6 && r == 2 {
    result = "Level clear!";
    speed = 0;
  }
}

every speed {
  if !moved { combo = 0; }
  moved = false;
  if sr >= 0 {
    if sr + dir < 0 || sr + dir > 4 { dir = -dir; }
    if hc == 3 && hr == sr + dir {
      hearts -= 1;
      dir = -dir;
    } else {
      sr += dir;
    }
  }
  if hearts == 0 {
    result = "Game over";
    speed = 0;
  }
}

fn start() {
  hc = 0;
  hr = 2;
  sr = 0;
  dir = 1;
  gold = true;
  moved = false;
  combo = 0;
  score = 0;
  hearts = 3;
  result = "";
  speed = 1000;
}

fn scene() {
  let b = [-1; 35];
  for i in 0..35 {
    if wall(i % 7, i / 7) { b[i] = 8; }
  }
  b[20] = 2;
  if gold { b[33] = 3; }
  if sr >= 0 { b[sr * 7 + 3] = 1; }
  b[hr * 7 + hc] = 4;
  pixels(b, 0, 0, 7, 16);
  if result != "" { text(result, 56, 40, 12, 11); }
}

