// once it is green to hand it back and get paid. The line holds 3; the day lasts 30 seconds.
// icon: fill 3 13 6 8 18 8 21 13 21 17 3 17 dot 7 18 2 dot 17 18 2
state jobs = [0, 1, 2, 0, 2, 1, 0, 1, 2, 0];     // the cars in turn: 0 oil, 1 tires, 2 engine
state names = ["Oil", "Tires", "Engine"];
state takes = [2, 3, 5];
state pays = [40, 100, 300];
state shades = [3, 4, 1];
state line = [0; 0];          // the jobs waiting, first in line first
state bay = [-1, -1, -1];     // the job in each bay; -1 when empty
state left = [0, 0, 0];       // seconds of work left in each bay
state arrived = 0;
state secs = 0;
state money = 0;
state served = 0;
state lost = 0;
state speed = 0;
state closed = false;

fn arrive() {
  if len(line) < 3 {
    push(line, jobs[arrived]);
  } else {
    lost += 1;
  }
  arrived += 1;
}

every speed {
  secs += 1;
  for i in 0..3 {
    if left[i] > 0 { left[i] -= 1; }
  }
  if secs % 3 == 0 && secs <= 27 { arrive(); }
  if secs == 30 {
    speed = 0;
    closed = true;
  }
}

fn tap(i: int) {
  if speed == 0 { return; }
  if bay[i] < 0 {
    if len(line) > 0 {
      bay[i] = line[0];
      left[i] = takes[line[0]];
      remove(line, 0);
    }
  } else if left[i] == 0 {
    money += pays[bay[i]];
    served += 1;
    bay[i] = -1;
  }
}

fn start() {
  clear(line);
  bay = [-1, -1, -1];
  left = [0, 0, 0];
  arrived = 0;
  secs = 0;
  money = 0;
  served = 0;
  lost = 0;
  closed = false;
  speed = 1000;
  arrive();
}

fn bays() -> [int] {
  let b = [8, 8, 8];
  for i in 0..3 {
    if bay[i] >= 0 { b[i] = left[i] == 0 ? 2 : shades[bay[i]]; }
  }
  return b;
}

