fn clock() -> string {
  let m = minutes % 60;
  let pad = m < 10 ? "0" : "";
  return (minutes / 60) + ":" + pad + m;
}

fn load(room: int) {
  let tint = [1, 4, 2];
  if left[room] > 0 && loaded < 8 {
    truck[loaded] = tint[room];
    loaded += 1;
    left[room] -= 1;
    minutes += 10;
  }
}

fn drive() {
  if loaded > 0 {
    delivered += loaded;
    loaded = 0;
    truck = [0; 8];
    trips += 1;
    minutes += 60;
  }
}

fn todo() -> int {
  let n = 0;
  for i in 0..3 {
    if !jobs[i] { n += 1; }
  }
  return n;
}

fn mark(on: bool) -> string { return on ? "done" : "to do"; }

