state trash = [0; 80];          // the sea, 10 x 8: 1 where trash floats
state bx = 0;                   // the boat
state by = 0;
state fuel = 20;
state net = 0;
state recycled = 0;
saved state best = 0;
state speed = 0;                // ms between wash-ups; 0 while no game runs
state wave = 0;                 // the next wash-up square
