fn at(c: int, r: int) -> int { return r * 10 + c; }

fn start() {
  let starts = [3, 5, 22, 36, 18, 51, 64, 79];
  trash = [0; 80];
  for i in 0..8 { trash[starts[i]] = 1; }
  bx = 0;
  by = 0;
  fuel = 20;
  net = 0;
  recycled = 0;
  wave = 0;
  over = false;
  speed = 5000;
}

fn move(dx: int, dy: int) {
  let nx = bx + dx;
  let ny = by + dy;
  if speed == 0 || nx < 0 || nx > 9 || ny < 0 || ny > 7 { return; }
  bx = nx;
  by = ny;
  fuel -= 1;
  let i = at(bx, by);
  if trash[i] == 1 && net < 3 {
    trash[i] = 0;
    net += 1;
  }
  if i == 0 {
    recycled += net;
    net = 0;
    fuel = 20;
    best = max(best, recycled);
