// The stamp a parcel needs: 0 Letter, 1 Small, 2 Large.
fn size() -> int {
  if weights[who] <= 100 { return 0; }
  if weights[who] <= 500 { return 1; }
  return 2;
}

fn following() {
  who += 1;
  stamped = false;
  patience = 15;
