// Festival manager: pick an act and tap a slot to book it (a booked one to cancel, half back); Open
// gates sells $3 a fan. A full stage draws 100 more. Three years.
// icon: fill 2 17 22 17 22 21 2 21 line 6 17 6 6 line 18 17 18 6 line 4 6 20 6 dot 12 11 3
state names = ["Rock", "Pop", "Folk", "Jazz"];
state costs = [500, 400, 100, 250];
state draws = [300, 250, 80, 150];
state tints = [1, 5, 2, 4];
state slots = [-1; 12];        // the act booked in each slot, -1 free: 3 stages of 4 times
state act = 0;
state money = 1500;
state year = 1;
state over = false;

fn fans() -> int {
  let n = 0;
  for s in 0..3 {
    let full = true;
    for t in 0..4 {
      let a = slots[s * 4 + t];
      if a < 0 { full = false; } else { n += draws[a]; }
    }
    if full { n += 100; }
  }
  return n;
}

// Whether the picked act already plays at time t on some stage.
fn clash(t: int) -> bool {
  for s in 0..3 {
    if slots[s * 4 + t] == act { return true; }
  }
  return false;
}

fn tap(i: int) {
  if over { return; }
  if slots[i] >= 0 {
    money += costs[slots[i]] / 2;
    slots[i] = -1;
  } else if money >= costs[act] && !clash(i % 4) {
    money -= costs[act];
    slots[i] = act;
  }
}

fn gates() {
  if over { return; }
  money += fans() * 3;
  slots = [-1; 12];
  if year == 3 { over = true; } else { year += 1; }
}

fn lineup() -> [int] {
  let cells = [0; 12];
  for i in 0..12 {
    if slots[i] >= 0 { cells[i] = tints[slots[i]]; }
  }
  return cells;
}

